def _json_dumps(value: Any) -> str:
    def _default(obj: Any) -> Any:
        if is_dataclass(obj):
            return asdict(obj)
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, Enum):
            return obj.value
        raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")

    return json.dumps(value, ensure_ascii=False, default=_default)


_FINAL_DELIVERY_PUBLICATION_CAPABILITY = object()
_COMPANY_WORK_ITEM_GATE_PUBLICATION_CAPABILITY = object()
COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY = (
    "company_work_item_gate_publication_provenance"
)


def _company_work_item_gate_publication_provenance(
    identity: dict[str, Any],
) -> dict[str, Any]:
    provenance = copy.deepcopy(dict(identity or {}))
    provenance["identity_sha256"] = hashlib.sha256(
        json.dumps(
            provenance,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return provenance


def _company_work_item_gate_publication_provenance_matches(
    payload: dict[str, Any],
) -> bool:
    provenance = dict(
        payload.get(COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY, {})
        or {}
    )
    recorded_hash = str(provenance.pop("identity_sha256", "") or "").strip()
    if not recorded_hash:
        return False
    expected = _company_work_item_gate_publication_provenance(provenance)
    try:
        provenance_attempt = int(provenance.get("attempt_seq", 0) or 0)
        payload_attempt = int(payload.get("work_item_attempt_seq", 0) or 0)
        provenance_gate_attempt = int(
            provenance.get("gate_attempt", -1)
        )
        payload_gate_attempt = int(payload.get("gate_attempt", -2))
    except (TypeError, ValueError):
        return False
    return bool(
        expected["identity_sha256"] == recorded_hash
        and str(provenance.get("project_id", "") or "").strip()
        and str(provenance.get("run_id", "") or "").strip()
        == str(payload.get("run_id", "") or "").strip()
        and str(provenance.get("task_id", "") or "").strip()
        == str(payload.get("waiting_task_id", "") or "").strip()
        and str(provenance.get("work_item_id", "") or "").strip()
        == str(payload.get("waiting_work_item_id", "") or "").strip()
        and str(provenance.get("projection_id", "") or "").strip()
        == str(payload.get(WORK_ITEM_PROJECTION_ID_KEY, "") or "").strip()
        and provenance_attempt == payload_attempt
        and provenance_gate_attempt == payload_gate_attempt
        and str(provenance.get("basis_hash", "") or "").strip()
        == str(payload.get("basis_hash", "") or "").strip()
        and str(provenance.get("source_event_id", "") or "").strip()
        == str(payload.get("source_event_id", "") or "").strip()
    )


def _company_work_item_gate_matches_task_metadata(
    task_metadata: dict[str, Any],
    gate: dict[str, Any],
    *,
    pending_harness_override: dict[str, Any] | None = None,
) -> bool:
    """Validate one checkpoint gate against the durable Task policy."""

    checkpoint_gate = canonical_company_work_item_gate_envelope(gate)
    durable_gate = canonical_company_work_item_gate_envelope(
        task_metadata.get("work_item_gate")
    )
    manager_fallback_gate = canonical_company_work_item_gate_envelope(
        company_work_item_gate_human_fallback_payload(
            task_metadata.get("work_item_gate")
        )
    )
    gate_metadata = dict(gate.get("metadata", {}) or {})
    gate_source = str(gate_metadata.get("source", "") or "").strip()
    pending_harness = dict(
        pending_harness_override
        if pending_harness_override is not None
        else task_metadata.get("gate_harness_pending_decision", {}) or {}
    )
    if gate_source == "gate_harness":
        target_ids = [
            str(item).strip()
            for item in list(pending_harness.get("target_projection_ids", []) or [])
            if str(item).strip()
        ]
        target_id = str(
            pending_harness.get("target_projection_id")
            or (target_ids[0] if target_ids else "")
            or ""
        ).strip()
        return bool(
            pending_harness
            and str(gate_metadata.get("recommended_action", "") or "").strip()
            == str(pending_harness.get("action", "") or "").strip()
            and str(gate.get("instructions", "") or "").strip()
            == str(pending_harness.get("summary", "") or "").strip()
            and list(gate_metadata.get("constraints", []) or [])
            == list(pending_harness.get("constraints", []) or [])
            and list(gate_metadata.get("blockers", []) or [])
            == list(pending_harness.get("blockers", []) or [])
            and list(gate_metadata.get("blocker_types", []) or [])
            == list(pending_harness.get("blocker_types", []) or [])
            and str(gate.get("rework_projection_id", "") or "").strip()
            == target_id
            and str(gate.get("on_reject", "") or "").strip()
            == ("rework" if target_id else "halt")
            and int(gate.get("max_retries", 0) or 0) == 1
        )
    durable_gate_present = bool(
        durable_gate.get("type")
        or durable_gate.get("instructions")
        or durable_gate.get("rework_projection_id")
    )
    if not durable_gate_present:
        return False
    manager_fallback_matches = bool(
        gate_metadata.get("manager_gate_fallback") is True
        and checkpoint_gate == manager_fallback_gate
    )
    return checkpoint_gate == durable_gate or manager_fallback_matches


def _reject_reserved_final_publication_patch(
    payload_patch: dict[str, Any] | None,
) -> None:
    reserved_keys = {
        FINAL_DELIVERY_PUBLICATION_PROVENANCE_KEY,
        COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
    }
    if reserved_keys.intersection(dict(payload_patch or {})):
        raise ValueError(
            "publication provenance is Store-owned"
        )


def _require_reserved_final_publication_unchanged(
    before: dict[str, Any],
    after: dict[str, Any],
) -> None:
    for reserved_key in (
        FINAL_DELIVERY_PUBLICATION_PROVENANCE_KEY,
        COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
    ):
        if before.get(reserved_key) != after.get(reserved_key):
            raise ValueError("publication provenance cannot be changed")


def _task_authoritative_preimage_hash(task: Task) -> str:
    payload = {
        "id": task.id,
        "session_id": task.session_id,
        "parent_session_id": task.parent_session_id,
        "title": task.title,
        "description": task.description,
        "assigned_to": task.assigned_to,
        "status": task.status.value,
        "priority": task.priority,
        "dependencies": task.dependencies,
        "execution_lock": bool(task.execution_lock),
        "context_snapshot": task.context_snapshot,
        "assigned_external_agent": task.assigned_external_agent,
        "created_at": task.created_at.isoformat(),
        "deadline": task.deadline.isoformat() if task.deadline else None,
        "result": task.result,
        "parent_id": task.parent_id,
        "project_id": task.project_id,
        "tags": task.tags,
        "comments": task.comments,
        "retry_count": task.retry_count,
        "max_retries": task.max_retries,
        "metadata": task.metadata,
        "org_id": task.org_id,
        "goal_id": task.goal_id,
        "checkout_run_id": task.checkout_run_id,
        "execution_locked_at": (
            task.execution_locked_at.isoformat()
            if task.execution_locked_at
            else None
        ),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
            default=lambda value: (
                value.isoformat()
                if isinstance(value, datetime)
                else value.value
                if isinstance(value, Enum)
                else str(value)
            ),
        ).encode("utf-8")
    ).hexdigest()


def company_controller_task_preimage_hash(task: Task) -> str:
    """Public constructor for authoritative multi-Task CAS preconditions."""

    return _task_authoritative_preimage_hash(task)


@dataclass(frozen=True)
class CompanyControllerWorkItemMutation:
    """One declarative WorkItem mutation in a fenced controller command.

    ``expected_phases`` and ``expected_updated_at`` are domain CAS guards.
    They differ from a controller fence failure: a domain guard mismatch
    returns ``applied=False`` for the whole command, while an expired or
    superseded controller raises :class:`CompanyRunControllerLeaseLost`.
    """

    work_item_id: str
    expected_phases: tuple[Phase, ...] = ()
    expected_updated_at: datetime | None = None
    phase: Phase | None = None
    summary: str | None = None
    deliverable_summary: str | None = None
    blocked_reason: str | None = None
    handoff_status: str | None = None
    claimed_by_role_runtime_session_id: str | None = None
    claimed_by_seat_id: str | None = None
    metadata_updates: dict[str, Any] = field(default_factory=dict)
    metadata_list_appends: dict[str, tuple[Any, ...]] = field(default_factory=dict)
    metadata_list_removes: dict[str, tuple[Any, ...]] = field(default_factory=dict)
    metadata_unset: tuple[str, ...] = ()
    clear_claim: bool = False
    latest_applied_report_work_item_id: str | None = None
    transition_reason: str = ""
    attempt_outcome: str = ""
    allow_via_running: bool = False
    allow_approved_rework: bool = False
    required_pre_delivery_validation_attempt_seq: int | None = None
    required_delivery_package_sha256: str | None = None
    required_pre_delivery_rework_count: int | None = None
    pre_delivery_rework_count_limit: int | None = None


