@dataclass(frozen=True)
class TaskRuntimeToolLedgerSnapshot:
    """One consistent read of the Store-authoritative exact ToolCall ledger."""

    task_id: str
    runtime_session_id: str
    permits: dict[str, dict[str, Any]] = field(default_factory=dict)
    continue_after_tool_result: bool = False
    runtime_resume: dict[str, Any] = field(default_factory=dict)
    runtime_metadata: dict[str, Any] = field(default_factory=dict)
    context_runtime_v2: dict[str, Any] = field(default_factory=dict)

    @property
    def active(self) -> bool:
        return bool(self.permits) or self.continue_after_tool_result

    def apply_to_task(self, task: Task) -> None:
        """Replace only runtime-ledger projections with this canonical snapshot."""

        context_snapshot = dict(getattr(task, "context_snapshot", {}) or {})
        metadata = dict(getattr(task, "metadata", {}) or {})
        context_snapshot["runtime_resume"] = copy.deepcopy(self.runtime_resume)
        context_snapshot["runtime_v2"] = copy.deepcopy(self.context_runtime_v2)
        metadata["runtime_v2"] = copy.deepcopy(self.runtime_metadata)
        task.context_snapshot = context_snapshot
        task.metadata = metadata


def _json_loads(value: str | None, default: Any) -> Any:
    if not value:
        return default
    try:
        return json.loads(value)
    except (json.JSONDecodeError, TypeError):
        # JSON columns can hold corrupt/partial values after a crash or manual edit.
        # Raising here would abort store.initialize() (e.g. via _sweep_stale_claims) and
        # prevent the store from ever opening, so fall back to the default instead.
        return default


