class _SQLiteCursorAdapter:
    def __init__(self, cursor: sqlite3.Cursor) -> None:
        self._cursor = cursor

    async def __aenter__(self) -> "_SQLiteCursorAdapter":
        return self

    async def __aexit__(self, exc_type, exc, tb) -> bool:
        self._cursor.close()
        return False

    async def fetchone(self) -> Any:
        return self._cursor.fetchone()

    async def fetchall(self) -> list[Any]:
        return self._cursor.fetchall()

    @property
    def description(self) -> Any:
        return self._cursor.description

    @property
    def rowcount(self) -> int:
        return self._cursor.rowcount


class _SQLiteExecuteResult:
    def __init__(self, connection: sqlite3.Connection, sql: str, params: tuple[Any, ...] | list[Any] = ()) -> None:
        self._connection = connection
        self._sql = sql
        self._params = tuple(params)
        self._cursor: sqlite3.Cursor | None = None

    def __await__(self):
        async def _run() -> _SQLiteCursorAdapter:
            cursor = self._connection.cursor()
            cursor.execute(self._sql, self._params)
            return _SQLiteCursorAdapter(cursor)

        return _run().__await__()

    async def __aenter__(self) -> _SQLiteCursorAdapter:
        cursor = self._connection.cursor()
        cursor.execute(self._sql, self._params)
        self._cursor = cursor
        return _SQLiteCursorAdapter(cursor)

    async def __aexit__(self, exc_type, exc, tb) -> bool:
        if self._cursor is not None:
            self._cursor.close()
        return False


class _SQLiteConnectionAdapter:
    def __init__(self, db_path: str) -> None:
        self._conn = sqlite3.connect(db_path, check_same_thread=False, timeout=30.0)
        self._conn.execute("PRAGMA foreign_keys=ON")
        self._conn.execute("PRAGMA busy_timeout=30000")

    def execute(self, sql: str, parameters: tuple[Any, ...] | list[Any] = ()) -> _SQLiteExecuteResult:
        return _SQLiteExecuteResult(self._conn, sql, parameters)

    async def executescript(self, script: str) -> None:
        self._conn.executescript(script)

    async def commit(self) -> None:
        self._conn.commit()

    async def rollback(self) -> None:
        self._conn.rollback()

    async def close(self) -> None:
        self._conn.close()


class OPCStore:
    """Async SQLite store for OPC data."""

    _DELEGATE_WORK_RESERVED_METADATA_KEYS = (
        "created_by_delegate_work",
        "delegate_invocation_id",
        "delegate_invocation_index",
        "delegate_sequence_index",
    )
    _DELEGATE_WORK_SEQUENCE_SCOPE_FIELDS = (
        "run_id",
        "batch_id",
        "parent_work_item_id",
        "source_seat_id",
    )

    def __init__(self, db_path: str | Path) -> None:
        self.db_path = str(db_path)
        self.project_id = self._infer_project_id_from_db_path(db_path)
        self._db: _SQLiteConnectionAdapter | None = None
        # Fix 5 PR3 feature flag mirrored onto the store so phase hooks
        # (which receive ``store`` but not the top-level OPCConfig) can
        # consult it cheaply. Engine sets this during init from
        # ``OPCConfig.org.role_serial_queue_enabled``. Tests can flip it
        # directly to exercise both branches.
        self.role_serial_queue_enabled: bool = True

    @staticmethod
    def _infer_project_id_from_db_path(db_path: str | Path) -> str | None:
        path = Path(db_path)
        try:
            if path.name == "tasks.db" and path.parent.parent.name == "projects":
                return path.parent.name or None
        except Exception:
            return None
        return None

    def _assert_project_write_scope(
        self,
        value: str | None,
        *,
        operation: str,
        entity: str,
    ) -> None:
        store_project_id = str(self.project_id or "").strip()
        entity_project_id = str(value or "").strip()
        if not store_project_id or not entity_project_id:
            return
        if entity_project_id != store_project_id:
            raise RuntimeError(
                f"{operation} rejected cross-project {entity} write: "
                f"store_project={store_project_id!r} entity_project={entity_project_id!r} "
                f"db_path={self.db_path!r}"
            )

    @property
    def is_ready(self) -> bool:
        """Whether the SQLite connection has been initialized."""
        return self._db is not None

    def _require_db(self) -> _SQLiteConnectionAdapter:
        """Return the active DB connection or raise a descriptive error."""
        if self._db is None:
            raise RuntimeError(
                f"OPCStore database not initialized (db_path={self.db_path!r}). "
                "Call await store.initialize() before using store methods."
            )
        return self._db

    async def ensure_ready(self) -> None:
        """Initialize the store if not already connected."""
        if self._db is None:
            await self.initialize()

    async def initialize(self, *, run_startup_maintenance: bool = True) -> None:
        """Open the store.

        ``run_startup_maintenance`` is reserved for the owning OpenOPC runtime
        process. Lightweight collaboration clients such as ``opc-collab`` open
        the already-initialized project DB to service one tool call; they must
        not run schema migrations or stale-claim sweeps as a side effect of a
        read-only command.
        """
        if run_startup_maintenance:
            Path(self.db_path).parent.mkdir(parents=True, exist_ok=True)
        elif not Path(self.db_path).exists():
            raise FileNotFoundError(f"OPCStore database does not exist: {self.db_path}")
        self._db = _SQLiteConnectionAdapter(self.db_path)
        if not run_startup_maintenance:
            return
        # Keep the project database safe when the owning UI and short-lived
        # collaboration/CLI processes open it at the same time.  WAL relies on
        # every process observing the same ``-wal``/``-shm`` lifetime.  That is
        # not guaranteed for bind-mounted workspaces and can leave the owning
        # process holding unlinked sidecars, after which controller heartbeats
        # fail with SQLITE_IOERR.  DELETE keeps normal SQLite file locking and
        # the existing busy timeout without a shared-memory sidecar.
        await self._db.execute("PRAGMA journal_mode=DELETE")
        await self._db.execute("PRAGMA foreign_keys=ON")
        await self._create_tables()
        await self._ensure_schema()
        await self._retire_legacy_human_escalation_checkpoints()
        # Claim recovery is run-scoped and happens only after a controller
        # wins the DelegationRun lease.  Store startup alone is not evidence
        # that another process's claims are stale.
        await self._migrate_drop_runtime_topology_version_columns()
        # Fix 5 PR2: merge every (run_id, role_id) group into a single
        # canonical row with PK = ``role-runtime::{run_id}::{role_id}``.
        # Combines inbox, memory_slices, list fields, and picks the most
        # recent state for scalar fields — so historical data survives
        # the collapse. Subsumes the old Fix-2 duplicate-collapse and
        # _no_team-sentinel migrations (the 3-segment canonical form
        # eliminates both problems at the source).
        await self._migrate_role_sessions_merge_by_role()
        await self._migrate_work_item_runtime_metadata()
        await self._migrate_work_item_projection_metadata()
        await self._retire_legacy_company_owner_waits()
        await self._purge_cross_project_runtime_rows()
        await self._validate_work_item_runtime_links()
        await self._ensure_indexes()

    async def _retire_legacy_human_escalation_checkpoints(self) -> None:
        """Fail closed active rows from the retired issue-35 interaction protocol."""

        assert self._db is not None
        active_statuses = ("answered", "consuming", "pending", "resuming")
        placeholders = ", ".join("?" for _ in active_statuses)
        query = (
            "SELECT checkpoint_id, project_id, status FROM execution_checkpoints "
            "WHERE checkpoint_type = 'human_escalation' "
            f"AND status IN ({placeholders})"
        )
        params: list[Any] = list(active_statuses)
        if self.project_id:
            query += " AND project_id = ?"
            params.append(self.project_id)
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()

        reason = "legacy human escalation protocol retired"
        migrated = 0
        for checkpoint_id, project_id, prior_status in rows:
            migrated_at = datetime.now()
            _, applied = await self.patch_execution_checkpoint_payload(
                str(checkpoint_id),
                project_id=str(project_id or "default").strip() or "default",
                checkpoint_type="human_escalation",
                expected_statuses=active_statuses,
                payload_patch={
                    "stale_reason": reason,
                    "stale_at": migrated_at.isoformat(),
                    "legacy_interaction_migration": {
                        "source_checkpoint_type": "human_escalation",
                        "prior_status": str(prior_status or "").strip(),
                        "terminal_status": "stale",
                        "reason": reason,
                        "migrated_at": migrated_at.isoformat(),
                    },
                },
                status="stale",
                updated_at=migrated_at,
            )
            migrated += int(applied)
        if migrated:
            logger.info("Retired {} active legacy human escalation checkpoints", migrated)

    @staticmethod
    def _legacy_metadata_flag(value: Any) -> bool:
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "y", "on"}
        return bool(value)

    @classmethod
    def _legacy_verifier_owner_wait(cls, payload: dict[str, Any]) -> bool:
        """Match only the task_user_input shape emitted by the old verifier gate."""
        pause_request = dict(payload.get("pause_request", {}) or {})
        if cls._legacy_metadata_flag(pause_request.get("requires_user_input", False)):
            return False
        runtime = dict(payload.get("runtime_v2", {}) or {})
        verification = dict(
            payload.get("verification")
            or runtime.get("verification")
            or {}
        )
        evidence = dict(
            payload.get("verification_evidence")
            or verification.get("evidence")
            or runtime.get("verification_evidence")
            or {}
        )
        completed_failure = (
            cls._legacy_metadata_flag(verification.get("completed", False))
            and "passed" in verification
            and not cls._legacy_metadata_flag(verification.get("passed"))
        )
        evidence_verdict = str(evidence.get("verdict", "") or "").strip().lower()
        evidence_failure = evidence_verdict in {
            "fail",
            "failed",
            "issues",
            "partial",
        }
        return completed_failure or evidence_failure

    @classmethod
    def _legacy_final_delivery_metadata(
        cls,
        task_metadata: dict[str, Any],
        work_item_metadata: dict[str, Any],
        *,
        work_item_kind: str,
    ) -> None:
        """Mirror the durable flags that distinguish final owner acceptance."""
        work_item_values = dict(work_item_metadata or {})
        task_values = dict(task_metadata or {})
        combined = {**work_item_values, **task_values}
        if cls._legacy_metadata_flag(combined.get("attention_work_item", False)):
            return False
        final_turn_types = {"deliver", "delivery", "self_evolution"}
        turn_types = {
            str(value or "").strip().lower()
            for value in (
                work_item_kind,
                work_item_values.get(WORK_ITEM_TURN_TYPE_KEY),
                work_item_values.get("work_kind"),
                work_item_values.get("delegation_turn_kind"),
                task_values.get(WORK_ITEM_TURN_TYPE_KEY),
                task_values.get("work_kind"),
                task_values.get("delegation_turn_kind"),
            )
            if str(value or "").strip()
        }
        if turn_types & final_turn_types:
            return True
        if any(
            str(values.get("review_owner_kind", "") or "").strip().lower()
            == "human"
            for values in (work_item_values, task_values)
        ):
            return True
        return (
            any(
                cls._legacy_metadata_flag(values.get("authoritative_output", False))
                for values in (work_item_values, task_values)
            )
            and any(
                cls._legacy_metadata_flag(values.get("user_visible", False))
                for values in (work_item_values, task_values)
            )
            and any(
                str(values.get("feedback_scope", "") or "").strip().lower()
                == "final"
                for values in (work_item_values, task_values)
            )
        )

    @classmethod
    def _legacy_verifier_internal_outcome(
        cls,
        task_metadata: dict[str, Any],
        work_item_metadata: dict[str, Any],
        *,
        work_item_kind: str,
        manager_role_id: str,
    ) -> tuple[Phase, TaskStatus, str]:
        """Project a completed old verifier turn without re-running its tools."""
        combined = {**dict(work_item_metadata or {}), **dict(task_metadata or {})}
        turn_type = canonical_work_item_turn_type_for_kind(
            work_item_turn_type_from_metadata(
                combined,
                fallback=work_item_kind or "",
            ),
            fallback="",
        )
        if cls._legacy_metadata_flag(combined.get("attention_work_item", False)):
            return Phase.APPROVED, TaskStatus.DONE, "attention_completed"
        if turn_type == "aggregate":
            return Phase.APPROVED, TaskStatus.DONE, "aggregate_completed"
        if turn_type in {"dispatch", "intake", "plan"}:
            board_mutated = cls._legacy_metadata_flag(
                combined.get("manager_board_mutation_performed", False)
            )
            normalized_manager = str(
                combined.get("manager_role_id") or manager_role_id or ""
            ).strip()
            if board_mutated or not normalized_manager or normalized_manager == "owner":
                return Phase.APPROVED, TaskStatus.DONE, (
                    "delegation_board_mutated"
                    if board_mutated
                    else "top_seat_self_produced"
                )
            return (
                Phase.AWAITING_MANAGER_REVIEW,
                TaskStatus.AWAITING_MANAGER_REVIEW,
                "delegation_turn_self_produced",
            )
        if turn_type in {"setup", "execute", "followup", "monitor"}:
            normalized_manager = str(
                combined.get("manager_role_id") or manager_role_id or ""
            ).strip()
            if normalized_manager and normalized_manager != "owner":
                return (
                    Phase.AWAITING_MANAGER_REVIEW,
                    TaskStatus.AWAITING_MANAGER_REVIEW,
                    "worker_completion_requires_manager_review",
                )
            return Phase.APPROVED, TaskStatus.DONE, "top_seat_self_produced"
        return Phase.FAILED, TaskStatus.FAILED, "completed_outcome_unknown"

    @staticmethod
    def _legacy_review_resolution_retirement_audit(
        *,
        review_work_item_id: str,
        source_report_work_item_id: str,
        retired_at: str,
    ) -> dict[str, Any]:
        return {
            "kind": "legacy_manager_review_awaiting_human_resolution",
            "review_work_item_id": review_work_item_id,
            "source_report_work_item_id": source_report_work_item_id,
            "original_target_phase": Phase.AWAITING_HUMAN.value,
            "normalized_target_phase": Phase.APPROVED.value,
            "retired_at": retired_at,
        }

    async def legacy_human_review_retirement_is_protected(
        self,
        work_item_id: str,
    ) -> bool:
        """Return whether an old review journal still belongs to the owner.

        Historical manager-review rows used ``AWAITING_HUMAN`` for two very
        different things: the retired manager escalation and legitimate final
        delivery / explicit-input workflows.  Retirement is allowed only
        after this durable classification has ruled out both owner-owned
        shapes.  Keeping the check in the Store gives startup migration and
        live reconciliation one definition backed by the same SQLite state.
        """

        db = self._require_db()
        target_id = str(work_item_id or "").strip()
        if not target_id:
            return True
        async with db.execute(
            """SELECT item.kind, item.metadata, task.id, task.metadata
               FROM delegation_work_items AS item
               LEFT JOIN work_item_runtime_links AS link
                 ON link.work_item_id = item.work_item_id
               LEFT JOIN tasks AS task
                 ON task.id = link.runtime_task_id
               WHERE item.work_item_id = ?""",
            (target_id,),
        ) as cursor:
            target_row = await cursor.fetchone()
        if target_row is None:
            return True
        work_item_kind = str(target_row[0] or "").strip()
        work_item_metadata = _json_loads(target_row[1], {})
        runtime_task_id = str(target_row[2] or "").strip()
        task_metadata = _json_loads(target_row[3], {})
        if self._legacy_final_delivery_metadata(
            task_metadata,
            work_item_metadata,
            work_item_kind=work_item_kind,
        ):
            return True
        if not runtime_task_id:
            return False

        active_statuses = ("pending", "answered", "consuming", "resuming")
        placeholders = ", ".join("?" for _ in active_statuses)
        async with db.execute(
            """SELECT task_id, payload
               FROM execution_checkpoints
               WHERE checkpoint_type = 'task_user_input'
                 AND status IN ("""
            + placeholders
            + ")",
            active_statuses,
        ) as cursor:
            checkpoint_rows = await cursor.fetchall()
        for checkpoint_task_id, payload_json in checkpoint_rows:
            payload = _json_loads(payload_json, {})
            candidate_task_id = str(
                checkpoint_task_id
                or payload.get("task_id")
                or payload.get("waiting_task_id")
                or ""
            ).strip()
            if candidate_task_id != runtime_task_id:
                continue
            pause_request = dict(payload.get("pause_request", {}) or {})
            if self._legacy_metadata_flag(
                pause_request.get("requires_user_input", False)
            ):
                return True
        return False

    async def _retire_legacy_company_owner_waits(self) -> None:
        """Atomically retire the two owner waits removed by issue-35.

        The transaction recognizes only:

        * the old review-rework escalation marker; and
        * a failed verifier checkpoint with no explicit request_user_input.

        Review escalations converge to APPROVED. Failed verifier waits on a
        non-final company WorkItem are projected from the already-completed
        result into the same internal phase that canonical DONE settlement
        uses; the original agent and its tool effects are never replayed. Final
        delivery review and explicit request_user_input checkpoints are
        deliberately untouched.
        The same transaction also retires legacy durable review resolutions
        whose forbidden target was AWAITING_HUMAN, guarded by the exact latest
        applied report generation.
        """
        assert self._db is not None
        active_statuses = ("pending", "answered", "consuming", "resuming")
        now = datetime.now().isoformat()
        retired_checkpoints = 0
        retired_resolutions = 0
        phase_transitions: list[tuple[Phase, Phase, str]] = []
        try:
            await self._db.execute("BEGIN IMMEDIATE")

            # First normalize the durable manager verdict journal. Its source
            # report predicate is intentionally identical to the live review
            # CAS; an older report can never settle a newer generation.
            async with self._db.execute(
                """SELECT work_item_id, run_id, metadata
                   FROM delegation_work_items
                   WHERE kind = 'review'
                     AND phase IN (?, ?, ?)""",
                (
                    Phase.APPROVED.value,
                    Phase.FAILED.value,
                    Phase.CANCELLED.value,
                ),
            ) as cursor:
                review_rows = await cursor.fetchall()
            for review_work_item_id, _run_id, review_metadata_json in review_rows:
                review_id = str(review_work_item_id or "").strip()
                review_metadata = _json_loads(review_metadata_json, {})
                resolution = dict(review_metadata.get("review_resolution", {}) or {})
                if (
                    str(resolution.get("target_phase", "") or "").strip()
                    != Phase.AWAITING_HUMAN.value
                ):
                    continue
                target_id = str(
                    resolution.get("target_work_item_id", "") or ""
                ).strip()
                if not target_id:
                    continue
                source_report_id = str(
                    resolution.get("source_report_work_item_id")
                    or review_metadata.get("review_source_report_work_item_id")
                    or ""
                ).strip()
                async with self._db.execute(
                    """SELECT * FROM delegation_work_items
                       WHERE work_item_id = ?""",
                    (target_id,),
                ) as cursor:
                    target_row = await cursor.fetchone()
                    target_description = cursor.description
                if target_row is None:
                    continue
                target_item = self._row_to_delegation_work_item(
                    target_row,
                    target_description,
                )
                target_phase = target_item.phase.value
                target_metadata = dict(target_item.metadata or {})
                # This check must precede every review-journal mutation.  The
                # checkpoint retirement pass below is too late: old review
                # journals are scanned first in this transaction.
                if await self.legacy_human_review_retirement_is_protected(
                    target_id
                ):
                    continue
                resolution_state = str(
                    review_metadata.get("review_resolution_state", "") or ""
                ).strip()
                if resolution_state == "stale":
                    # A prior process may have committed stale recovery and
                    # crashed before its phase hook projected the linked Task.
                    if target_phase == Phase.AWAITING_MANAGER_REVIEW.value:
                        await self._sync_linked_task_projection_from_exact_work_item_phase(
                            target_id,
                            exact_phase=Phase.AWAITING_MANAGER_REVIEW,
                        )
                    continue
                applied_review_id = str(
                    target_metadata.get("review_resolution_applied_work_item_id", "")
                    or ""
                ).strip()
                if (
                    target_phase == Phase.APPROVED.value
                    and applied_review_id == review_id
                ):
                    # Idempotent crash recovery: the WorkItem CAS is already
                    # durable, but the old post-commit hook may not have run.
                    await self._sync_linked_task_projection_from_exact_work_item_phase(
                        target_id,
                        exact_phase=Phase.APPROVED,
                    )
                    prior_retirement = dict(
                        review_metadata.get("review_resolution_retirement", {})
                        or {}
                    )
                    if (
                        str(
                            review_metadata.get("review_resolution_state", "")
                            or ""
                        ).strip()
                        == "applied"
                        and str(prior_retirement.get("kind", "") or "").strip()
                        == "legacy_manager_review_awaiting_human_resolution"
                        and str(
                            prior_retirement.get("normalized_target_phase", "")
                            or ""
                        ).strip()
                        == Phase.APPROVED.value
                    ):
                        continue
                    target_retirement = dict(
                        target_metadata.get("review_resolution_retirement", {})
                        or {}
                    )
                    audit = (
                        target_retirement
                        if str(target_retirement.get("kind", "") or "").strip()
                        == "legacy_manager_review_awaiting_human_resolution"
                        and str(
                            target_retirement.get("review_work_item_id", "") or ""
                        ).strip()
                        == review_id
                        and str(
                            target_retirement.get(
                                "source_report_work_item_id", ""
                            )
                            or ""
                        ).strip()
                        == source_report_id
                        else self._legacy_review_resolution_retirement_audit(
                            review_work_item_id=review_id,
                            source_report_work_item_id=source_report_id,
                            retired_at=now,
                        )
                    )
                    review_metadata.update(
                        {
                            "review_resolution_state": "applied",
                            "review_work_item_outcome": (
                                "legacy_awaiting_human_resolution_retired_to_approved"
                            ),
                            "review_resolution_retirement": audit,
                        }
                    )
                    await self._db.execute(
                        "UPDATE delegation_work_items SET metadata = ?, updated_at = ? "
                        "WHERE work_item_id = ?",
                        (_json_dumps(review_metadata), now, review_id),
                    )
                    continue
                if target_phase not in {
                    Phase.AWAITING_MANAGER_REVIEW.value,
                    Phase.AWAITING_HUMAN.value,
                }:
                    continue
                async with self._db.execute(
                    """SELECT report.work_item_id
                       FROM delegation_work_items AS report
                       WHERE report.parent_work_item_id = ?
                         AND report.kind = 'report'
                         AND json_extract(
                             report.metadata,
                             '$.report_target_work_item_id'
                         ) = ?
                         AND json_extract(
                             report.metadata,
                             '$.report_card_outcome'
                         ) = 'applied'
                       ORDER BY report.batch_index DESC,
                                report.created_at DESC,
                                report.work_item_id DESC
                       LIMIT 1""",
                    (target_id, target_id),
                ) as cursor:
                    latest_report_row = await cursor.fetchone()
                latest_report_id = str(
                    latest_report_row[0] if latest_report_row else ""
                ).strip()
                if latest_report_id != source_report_id:
                    stale_reason = (
                        "source_report_superseded"
                        if latest_report_id
                        else "source_report_missing"
                    )
                    review_metadata.update(
                        {
                            "review_resolution_state": "stale",
                            "review_resolution_stale_reason": stale_reason,
                            "review_resolution_stale_at": now,
                            "review_work_item_outcome": "superseded_by_newer_report",
                        }
                    )
                    await self._db.execute(
                        "UPDATE delegation_work_items SET metadata = ?, updated_at = ? "
                        "WHERE work_item_id = ?",
                        (_json_dumps(review_metadata), now, review_id),
                    )
                    if target_phase == Phase.AWAITING_HUMAN.value:
                        recovery_audit = {
                            "kind": "legacy_human_review_target_recovered",
                            "stale_review_work_item_id": review_id,
                            "stale_source_report_work_item_id": source_report_id,
                            "latest_source_report_work_item_id": latest_report_id,
                            "reason": stale_reason,
                            "prior_phase": Phase.AWAITING_HUMAN.value,
                            "normalized_phase": Phase.AWAITING_MANAGER_REVIEW.value,
                            "retired_at": now,
                        }
                        target_metadata.update(
                            {
                                "review_resolution_retirement": recovery_audit,
                                "claimed_by_role_session_id": "",
                                "claimed_task_id": "",
                            }
                        )
                        recovered_target = copy.deepcopy(target_item)
                        recovered_target.metadata = target_metadata
                        self._protect_delegate_work_identity(
                            recovered_target,
                            existing=target_item,
                        )
                        target_metadata = recovered_target.metadata
                        await self._db.execute(
                            """UPDATE delegation_work_items
                               SET phase = ?, blocked_reason = '', metadata = ?,
                                   claimed_by_role_runtime_session_id = '',
                                   claimed_by_seat_id = '', updated_at = ?
                               WHERE work_item_id = ? AND phase = ?""",
                            (
                                Phase.AWAITING_MANAGER_REVIEW.value,
                                _json_dumps(target_metadata),
                                now,
                                target_id,
                                Phase.AWAITING_HUMAN.value,
                            ),
                        )
                        await self._sync_linked_task_projection_from_exact_work_item_phase(
                            target_id,
                            exact_phase=Phase.AWAITING_MANAGER_REVIEW,
                        )
                        phase_transitions.append(
                            (
                                Phase.AWAITING_HUMAN,
                                Phase.AWAITING_MANAGER_REVIEW,
                                target_id,
                            )
                        )
                    elif target_phase == Phase.AWAITING_MANAGER_REVIEW.value:
                        await self._sync_linked_task_projection_from_exact_work_item_phase(
                            target_id,
                            exact_phase=Phase.AWAITING_MANAGER_REVIEW,
                        )
                    continue
                audit = self._legacy_review_resolution_retirement_audit(
                    review_work_item_id=review_id,
                    source_report_work_item_id=source_report_id,
                    retired_at=now,
                )
                resolution_updates = resolution.get("metadata_updates", {})
                if isinstance(resolution_updates, dict):
                    target_metadata.update(copy.deepcopy(resolution_updates))
                target_metadata.update(
                    {
                        "review_resolution_applied_work_item_id": review_id,
                        "review_resolution_retirement": audit,
                        "claimed_by_role_session_id": "",
                        "claimed_task_id": "",
                    }
                )
                retired_target = copy.deepcopy(target_item)
                retired_target.metadata = target_metadata
                self._protect_delegate_work_identity(
                    retired_target,
                    existing=target_item,
                )
                target_metadata = retired_target.metadata
                cursor = await self._db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, blocked_reason = '', metadata = ?,
                           claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', updated_at = ?
                       WHERE work_item_id = ?
                         AND phase = ?
                         AND COALESCE((
                             SELECT report.work_item_id
                             FROM delegation_work_items AS report
                             WHERE report.parent_work_item_id = ?
                               AND report.kind = 'report'
                               AND json_extract(
                                   report.metadata,
                                   '$.report_target_work_item_id'
                               ) = ?
                               AND json_extract(
                                   report.metadata,
                                   '$.report_card_outcome'
                               ) = 'applied'
                             ORDER BY report.batch_index DESC,
                                      report.created_at DESC,
                                      report.work_item_id DESC
                             LIMIT 1
                         ), '') = ?""",
                    (
                        Phase.APPROVED.value,
                        _json_dumps(target_metadata),
                        now,
                        target_id,
                        target_phase,
                        target_id,
                        target_id,
                        source_report_id,
                    ),
                )
                if cursor.rowcount != 1:
                    continue
                phase_transitions.append(
                    (Phase(target_phase), Phase.APPROVED, target_id)
                )
                review_metadata.update(
                    {
                        "review_resolution_state": "applied",
                        "review_work_item_outcome": (
                            "legacy_awaiting_human_resolution_retired_to_approved"
                        ),
                        "review_resolution_retirement": audit,
                    }
                )
                await self._db.execute(
                    "UPDATE delegation_work_items SET metadata = ?, updated_at = ? "
                    "WHERE work_item_id = ?",
                    (_json_dumps(review_metadata), now, review_id),
                )
                await self._sync_linked_task_projection_from_exact_work_item_phase(
                    target_id,
                    exact_phase=Phase.APPROVED,
                )
                retired_resolutions += 1

            placeholders = ", ".join("?" for _ in active_statuses)
            params: list[Any] = [*active_statuses]
            checkpoint_query = (
                "SELECT checkpoint_id, project_id, status, task_id, payload "
                "FROM execution_checkpoints "
                "WHERE checkpoint_type = 'task_user_input' "
                f"AND status IN ({placeholders})"
            )
            if self.project_id:
                checkpoint_query += " AND project_id = ?"
                params.append(self.project_id)
            async with self._db.execute(checkpoint_query, params) as cursor:
                checkpoint_rows = await cursor.fetchall()

            for checkpoint_id, project_id, prior_status, row_task_id, payload_json in checkpoint_rows:
                payload = _json_loads(payload_json, {})
                manual_review = str(
                    payload.get("manual_intervention_source", "") or ""
                ).strip() == "review_rework_escalation"
                verifier_failure = self._legacy_verifier_owner_wait(payload)
                if not manual_review and not verifier_failure:
                    continue
                task_id = str(
                    row_task_id
                    or payload.get("task_id")
                    or payload.get("waiting_task_id")
                    or ""
                ).strip()
                if not task_id:
                    continue
                async with self._db.execute(
                    """SELECT status, metadata, result FROM tasks
                       WHERE id = ? AND project_id = ?""",
                    (task_id, str(project_id or "default").strip() or "default"),
                ) as cursor:
                    task_row = await cursor.fetchone()
                if task_row is None:
                    continue
                task_status = str(task_row[0] or "").strip()
                task_metadata = _json_loads(task_row[1], {})
                task_result_json = task_row[2]
                async with self._db.execute(
                    """SELECT item.work_item_id, item.phase, item.kind,
                              item.metadata, item.manager_role_id
                       FROM work_item_runtime_links AS link
                       JOIN delegation_work_items AS item
                         ON item.work_item_id = link.work_item_id
                       WHERE link.runtime_task_id = ?""",
                    (task_id,),
                ) as cursor:
                    work_item_row = await cursor.fetchone()
                if work_item_row is None:
                    continue
                work_item_id = str(work_item_row[0] or "").strip()
                work_item_phase = str(work_item_row[1] or "").strip()
                work_item_kind = str(work_item_row[2] or "").strip()
                work_item_metadata = _json_loads(work_item_row[3], {})
                work_item_manager_role_id = str(work_item_row[4] or "").strip()
                if verifier_failure:
                    if self._legacy_final_delivery_metadata(
                        task_metadata,
                        work_item_metadata,
                        work_item_kind=work_item_kind,
                    ):
                        continue
                    if work_item_phase != Phase.AWAITING_HUMAN.value:
                        continue
                    if task_status != TaskStatus.AWAITING_HUMAN.value:
                        continue
                elif work_item_phase not in {
                    Phase.AWAITING_MANAGER_REVIEW.value,
                    Phase.AWAITING_HUMAN.value,
                    Phase.APPROVED.value,
                }:
                    continue

                migration_kind = (
                    "review_rework_escalation"
                    if manual_review
                    else "failed_verifier_owner_wait"
                )
                if manual_review:
                    recovery_phase = Phase.APPROVED
                    recovery_status = TaskStatus.DONE
                    internal_outcome = "legacy_rework_cap_auto_done"
                else:
                    (
                        recovery_phase,
                        recovery_status,
                        internal_outcome,
                    ) = self._legacy_verifier_internal_outcome(
                        task_metadata,
                        work_item_metadata,
                        work_item_kind=work_item_kind,
                        manager_role_id=work_item_manager_role_id,
                    )
                audit = {
                    "kind": migration_kind,
                    "checkpoint_id": str(checkpoint_id),
                    "prior_checkpoint_status": str(prior_status or "").strip(),
                    "task_id": task_id,
                    "work_item_id": work_item_id,
                    "prior_task_status": task_status,
                    "prior_work_item_phase": work_item_phase,
                    "normalized_task_status": recovery_status.value,
                    "normalized_work_item_phase": recovery_phase.value,
                    "internal_outcome": internal_outcome,
                    "original_execution_replayed": False,
                    "retired_at": now,
                }
                task_result = _json_loads(task_result_json, {})
                result_content = str(
                    task_result.get("content", "")
                    if isinstance(task_result, dict)
                    else ""
                ).strip()
                if verifier_failure and result_content:
                    work_item_metadata.setdefault(
                        "completion_report",
                        result_content,
                    )
                    work_item_metadata.setdefault(
                        "report_source_result_content",
                        result_content,
                    )
                work_item_metadata.update(
                    {
                        "legacy_owner_wait_retirement": audit,
                        "claimed_by_role_session_id": "",
                        "claimed_task_id": "",
                    }
                )
                phase_cursor = await self._db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, blocked_reason = '', metadata = ?,
                           claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', updated_at = ?
                       WHERE work_item_id = ? AND phase = ?""",
                    (
                        recovery_phase.value,
                        _json_dumps(work_item_metadata),
                        now,
                        work_item_id,
                        work_item_phase,
                    ),
                )
                if phase_cursor.rowcount != 1:
                    # Never split the WorkItem, Task, and owner-checkpoint
                    # projections. A missed source-phase CAS leaves the whole
                    # legacy row active for a later deterministic retry.
                    continue
                if work_item_phase != recovery_phase.value:
                    phase_transitions.append(
                        (
                            Phase(work_item_phase),
                            recovery_phase,
                            work_item_id,
                        )
                    )
                task_metadata["legacy_owner_wait_retirement"] = audit
                task_cursor = await self._db.execute(
                    """UPDATE tasks
                       SET metadata = ?
                       WHERE id = ? AND status = ?""",
                    (
                        _json_dumps(task_metadata),
                        task_id,
                        task_status,
                    ),
                )
                if task_cursor.rowcount != 1:
                    raise RuntimeError(
                        "legacy owner-wait Task CAS failed after WorkItem CAS: "
                        f"task_id={task_id} work_item_id={work_item_id}"
                    )
                projected_count = (
                    await self._sync_linked_task_projection_from_exact_work_item_phase(
                        work_item_id,
                        exact_phase=recovery_phase,
                    )
                )
                if projected_count != 1:
                    raise RuntimeError(
                        "legacy owner-wait Task projection failed after WorkItem CAS: "
                        f"task_id={task_id} work_item_id={work_item_id}"
                    )
                payload.update(
                    {
                        "stale_reason": (
                            "legacy company owner wait retired by issue-35 migration"
                        ),
                        "stale_at": now,
                        "legacy_interaction_migration": {
                            **audit,
                            "source_checkpoint_type": "task_user_input",
                            "terminal_status": "stale",
                        },
                    }
                )
                cursor = await self._db.execute(
                    f"""UPDATE execution_checkpoints
                       SET status = 'stale', payload = ?, updated_at = ?
                       WHERE checkpoint_id = ?
                         AND checkpoint_type = 'task_user_input'
                         AND status IN ({placeholders})""",
                    (
                        _json_dumps(payload),
                        now,
                        str(checkpoint_id),
                        *active_statuses,
                    ),
                )
                if cursor.rowcount != 1:
                    raise RuntimeError(
                        "legacy owner-wait checkpoint CAS failed after WorkItem CAS: "
                        f"checkpoint_id={checkpoint_id} work_item_id={work_item_id}"
                    )
                retired_checkpoints += 1

            await self._db.commit()
        except Exception:
            await self._db.rollback()
            raise
        for previous_phase, target_phase, work_item_id in phase_transitions:
            try:
                persisted = await self.get_delegation_work_item(work_item_id)
                if persisted is not None:
                    await on_phase_transition(
                        previous_phase,
                        target_phase,
                        persisted,
                        store=self,
                    )
            except Exception:
                logger.opt(exception=True).debug(
                    "Legacy company owner-wait retirement hook failed for {}",
                    work_item_id,
                )
        if retired_resolutions or retired_checkpoints:
            logger.info(
                "Retired {} legacy company review resolutions and {} owner waits",
                retired_resolutions,
                retired_checkpoints,
            )

    async def _table_columns(self, table: str) -> list[str]:
        assert self._db is not None
        if not await self._table_exists(table):
            return []
        async with self._db.execute(f"PRAGMA table_info({table})") as cursor:
            rows = await cursor.fetchall()
        return [str(row[1]) for row in rows]

    async def _purge_cross_project_runtime_rows(self) -> dict[str, int]:
        """Remove rows that were written into the wrong project-scoped DB.

        Project databases under ``.opc/projects/<project_id>/tasks.db`` are
        single-project stores. A row whose explicit ``project_id`` names a
        different project is corruption from a prior mutable-store race; keeping
        it can break canonical WorkItem validation and project switching.
        """
        if self._db is None:
            return {}
        project_id = str(self.project_id or "").strip()
        if not project_id:
            return {}
        deleted: dict[str, int] = {}
        async def _cross_project_ids(table: str, id_column: str) -> set[str]:
            if not await self._table_exists(table):
                return set()
            async with self._db.execute(
                f"""SELECT {id_column} FROM {table}
                    WHERE project_id IS NOT NULL
                      AND TRIM(project_id) != ''
                      AND project_id != ?""",
                (project_id,),
            ) as cursor:
                rows = await cursor.fetchall()
            return {
                str(row[0] or "").strip()
                for row in rows
                if str(row[0] or "").strip()
            }

        wrong_runtime_session_ids = await _cross_project_ids(
            "runtime_sessions",
            "runtime_session_id",
        )
        wrong_task_ids = await _cross_project_ids("tasks", "id")

        seed_where = [
            "(project_id IS NOT NULL AND TRIM(project_id) != '' AND project_id != ?)"
        ]
        seed_params: list[Any] = [project_id]
        if wrong_runtime_session_ids:
            placeholders = ", ".join("?" for _ in wrong_runtime_session_ids)
            seed_where.append(f"runtime_session_id IN ({placeholders})")
            seed_params.extend(sorted(wrong_runtime_session_ids))
        if wrong_task_ids:
            placeholders = ", ".join("?" for _ in wrong_task_ids)
            seed_where.append(f"task_id IN ({placeholders})")
            seed_params.extend(sorted(wrong_task_ids))
        async with self._db.execute(
            """SELECT seed_key, message_id FROM runtime_user_turn_seeds
               WHERE """ + " OR ".join(seed_where),
            tuple(seed_params),
        ) as cursor:
            corrupt_seed_rows = await cursor.fetchall()
        corrupt_seed_keys = {
            str(row[0] or "").strip()
            for row in corrupt_seed_rows
            if str(row[0] or "").strip()
        }
        corrupt_seed_message_ids = {
            str(row[1] or "").strip()
            for row in corrupt_seed_rows
            if str(row[1] or "").strip()
        }
        await self._delete_where_in(
            "session_parts",
            "message_id",
            corrupt_seed_message_ids,
        )
        await self._delete_where_in(
            "session_messages",
            "message_id",
            corrupt_seed_message_ids,
        )
        await self._delete_where_in(
            "runtime_transcript_entries",
            "message_id",
            corrupt_seed_message_ids,
        )
        await self._delete_where_in(
            "runtime_user_turn_seeds",
            "seed_key",
            corrupt_seed_keys,
        )
        for table in (
            "runtime_events",
            "runtime_transcript_entries",
            "runtime_user_turn_seeds",
            "runtime_tool_calls",
            "runtime_tool_results",
            "runtime_permission_grants",
            "runtime_subagent_runs",
            "runtime_worktree_sessions",
            "runtime_compaction_boundaries",
        ):
            await self._delete_where_in(
                table,
                "runtime_session_id",
                wrong_runtime_session_ids,
            )
        for table in (
            "runtime_transcript_entries",
            "runtime_user_turn_seeds",
            "runtime_tool_calls",
            "runtime_tool_results",
            "runtime_subagent_runs",
            "runtime_worktree_sessions",
            "runtime_compaction_boundaries",
        ):
            await self._delete_where_in(table, "task_id", wrong_task_ids)
        if corrupt_seed_keys:
            deleted["runtime_user_turn_seeds"] = len(corrupt_seed_keys)
        for table in ("external_sessions", "runtime_sessions", "tasks"):
            if not await self._table_exists(table):
                continue
            columns = set(await self._table_columns(table))
            if "project_id" not in columns:
                continue
            cursor = await self._db.execute(
                f"""DELETE FROM {table}
                    WHERE project_id IS NOT NULL
                      AND TRIM(project_id) != ''
                      AND project_id != ?""",
                (project_id,),
            )
            count = int(getattr(cursor, "rowcount", 0) or 0)
            if count:
                deleted[table] = count
        if deleted:
            await self._db.commit()
            logger.warning(
                "Purged cross-project runtime rows from project store: "
                f"project_id={project_id} db_path={self.db_path} deleted={deleted}"
            )
        return deleted

    async def _migrate_drop_runtime_topology_version_columns(self) -> None:
        # runtime_topology_version is no longer tracked: reorg never increments it,
        # snapshots never read it, and gates aren't keyed off it. Drop the
        # vestigial columns from legacy DBs (idempotent).
        assert self._db
        for table, column in (
            ("reorg_proposals", "old_runtime_topology_version"),
            ("reorg_proposals", "new_runtime_topology_version"),
            ("org_snapshots", "runtime_topology_version"),
        ):
            async with self._db.execute(f"PRAGMA table_info({table})") as cursor:
                rows = await cursor.fetchall()
            cols = {row[1] for row in rows}
            if column in cols:
                try:
                    await self._db.execute(f"ALTER TABLE {table} DROP COLUMN {column}")
                except Exception as exc:
                    logger.warning(f"Failed to drop {table}.{column}: {exc}")
        await self._db.commit()

    async def _migrate_work_item_runtime_metadata(self) -> dict[str, int]:
        """Normalize canonical company work-item runtime metadata."""
        if self._db is None:
            return {}

        targets = (
            ("tasks", "id"),
            ("delegation_runs", "run_id"),
            ("delegation_cells", "cell_id"),
            ("delegation_work_items", "work_item_id"),
            ("team_instances", "team_instance_id"),
            ("seat_states", "seat_state_id"),
            ("role_runtime_sessions", "role_session_id"),
            ("delegation_role_sessions", "role_session_id"),
        )
        stats: dict[str, int] = {}
        try:
            # Acquire the writer before the first metadata SELECT.  The whole
            # read/transform/write pass is then ordered with typed ledger
            # commands on every Store connection.
            await self._db.execute("BEGIN IMMEDIATE")
            for table, key_column in targets:
                stats[table] = await self._migrate_work_item_runtime_metadata_table(
                    table=table,
                    key_column=key_column,
                )
            await self._db.commit()
        except BaseException:
            await self._db.rollback()
            raise
        changed = sum(stats.values())
        if changed:
            logger.info(f"work-item runtime metadata migration: updated {changed} rows")
        return stats

    async def _cas_transform_metadata_row(
        self,
        *,
        table: str,
        key_column: str,
        row_id: str,
        transform: Any,
        touch_updated_at: bool = False,
        max_attempts: int = 8,
    ) -> bool:
        """Apply one metadata migration without overwriting a concurrent writer.

        Startup maintenance can run in more than one Engine while typed
        runtime commands update the same JSON blob.  Every failed metadata CAS
        is therefore re-read and re-transformed; using a previously selected
        blob as an unconditional UPDATE could resurrect consumed Tool permits.
        """

        assert self._db is not None
        for _attempt in range(max(1, int(max_attempts))):
            async with self._db.execute(
                f"SELECT metadata FROM {table} WHERE {key_column} = ?",
                (row_id,),
            ) as cursor:
                row = await cursor.fetchone()
            if row is None:
                return False
            original_metadata_json = row[0]
            metadata = _json_loads(original_metadata_json, {})
            if not isinstance(metadata, dict):
                return False
            migrated, changed = transform(dict(metadata))
            if not changed:
                return False
            if touch_updated_at:
                cursor = await self._db.execute(
                    f"""UPDATE {table}
                        SET metadata = ?, updated_at = ?
                        WHERE {key_column} = ? AND metadata IS ?""",
                    (
                        _json_dumps(migrated),
                        datetime.now().isoformat(),
                        row_id,
                        original_metadata_json,
                    ),
                )
            else:
                cursor = await self._db.execute(
                    f"""UPDATE {table} SET metadata = ?
                        WHERE {key_column} = ? AND metadata IS ?""",
                    (_json_dumps(migrated), row_id, original_metadata_json),
                )
            if int(getattr(cursor, "rowcount", 0) or 0) == 1:
                return True
        raise RuntimeError(
            f"metadata migration CAS did not converge for "
            f"{table}.{key_column}={row_id}"
        )

    async def _migrate_work_item_runtime_metadata_table(
        self,
        *,
        table: str,
        key_column: str,
    ) -> int:
        assert self._db is not None
        if not await self._table_exists(table):
            return 0
        async with self._db.execute(f"PRAGMA table_info({table})") as cursor:
            columns = {row[1] for row in await cursor.fetchall()}
        if key_column not in columns or "metadata" not in columns:
            return 0

        async with self._db.execute(
            f"""SELECT {key_column}
                FROM {table}
                WHERE metadata LIKE '%work_item_runtime%'"""
        ) as cursor:
            rows = await cursor.fetchall()

        updated = 0
        for (row_id,) in rows:
            updated += int(await self._cas_transform_metadata_row(
                table=table,
                key_column=key_column,
                row_id=str(row_id),
                transform=migrate_work_item_runtime_metadata,
            ))
        return updated

    async def _migrate_work_item_projection_metadata(self) -> dict[str, int]:
        """Normalize canonical work-item projection identity metadata."""
        if self._db is None:
            return {}
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            stats = {
                "tasks": await self._migrate_task_projection_metadata(),
                "delegation_work_items": await self._migrate_delegation_work_item_projection_metadata(),
            }
            await self._db.commit()
        except BaseException:
            await self._db.rollback()
            raise
        changed = sum(stats.values())
        if changed:
            logger.info(f"work-item projection metadata migration: updated {changed} rows")
        return stats

    async def _migrate_task_projection_metadata(self) -> int:
        assert self._db is not None
        if not await self._table_exists("tasks"):
            return 0
        async with self._db.execute("PRAGMA table_info(tasks)") as cursor:
            columns = {row[1] for row in await cursor.fetchall()}
        if "id" not in columns or "metadata" not in columns:
            return 0
        async with self._db.execute(
            """SELECT id
               FROM tasks
               WHERE metadata LIKE '%work_item_projection_id%'
                  OR metadata LIKE '%work_item_turn_type%'"""
        ) as cursor:
            rows = await cursor.fetchall()
        updated = 0
        for (task_id,) in rows:
            updated += int(await self._cas_transform_metadata_row(
                table="tasks",
                key_column="id",
                row_id=str(task_id),
                transform=migrate_work_item_projection_metadata,
            ))
        return updated

    async def _migrate_delegation_work_item_projection_metadata(self) -> int:
        assert self._db is not None
        if not await self._table_exists("delegation_work_items"):
            return 0
        async with self._db.execute("PRAGMA table_info(delegation_work_items)") as cursor:
            columns = {row[1] for row in await cursor.fetchall()}
        required = {"work_item_id", "projection_id", "kind", "metadata"}
        if not required.issubset(columns):
            return 0
        async with self._db.execute(
            """SELECT work_item_id, projection_id, kind
               FROM delegation_work_items
               WHERE COALESCE(projection_id, '') != ''
                  OR COALESCE(kind, '') != ''
                  OR metadata LIKE '%work_item_projection_id%'
                  OR metadata LIKE '%work_item_turn_type%'"""
        ) as cursor:
            rows = await cursor.fetchall()
        updated = 0
        for work_item_id, projection_id, kind in rows:
            def _transform(
                metadata: dict[str, Any],
                *,
                projection: str = str(projection_id or work_item_id or "").strip(),
                turn_type: str = str(kind or "execute").strip(),
            ) -> tuple[dict[str, Any], bool]:
                return migrate_work_item_projection_metadata(
                    metadata,
                    projection_id_fallback=projection,
                    turn_type_fallback=turn_type,
                )

            updated += int(await self._cas_transform_metadata_row(
                table="delegation_work_items",
                key_column="work_item_id",
                row_id=str(work_item_id),
                transform=_transform,
            ))
        return updated

    async def _task_exists(self, task_id: str) -> bool:
        assert self._db is not None
        tid = str(task_id or "").strip()
        if not tid:
            return False
        async with self._db.execute("SELECT 1 FROM tasks WHERE id=? LIMIT 1", (tid,)) as cursor:
            return await cursor.fetchone() is not None

    async def _work_item_exists(self, work_item_id: str) -> bool:
        assert self._db is not None
        wid = str(work_item_id or "").strip()
        if not wid:
            return False
        async with self._db.execute(
            "SELECT 1 FROM delegation_work_items WHERE work_item_id=? LIMIT 1",
            (wid,),
        ) as cursor:
            return await cursor.fetchone() is not None

    async def _runtime_link_task_id_for_work_item(self, work_item_id: str) -> str:
        assert self._db is not None
        wid = str(work_item_id or "").strip()
        if not wid:
            return ""
        async with self._db.execute(
            "SELECT runtime_task_id FROM work_item_runtime_links WHERE work_item_id=?",
            (wid,),
        ) as cursor:
            row = await cursor.fetchone()
        return str(row[0] or "").strip() if row else ""

    async def _runtime_link_work_item_id_for_task(self, task_id: str) -> str:
        assert self._db is not None
        tid = str(task_id or "").strip()
        if not tid:
            return ""
        async with self._db.execute(
            "SELECT work_item_id FROM work_item_runtime_links WHERE runtime_task_id=?",
            (tid,),
        ) as cursor:
            row = await cursor.fetchone()
        return str(row[0] or "").strip() if row else ""

    async def _sync_linked_task_projection_from_exact_work_item_phase(
        self,
        work_item_id: str,
        *,
        exact_phase: Phase | str,
        db: _SQLiteConnectionAdapter | None = None,
    ) -> int:
        """Project one exact WorkItem phase onto its linked runtime Task.

        This helper intentionally does not commit: callers place it in the
        same SQLite transaction as the WorkItem CAS.  The exact-phase EXISTS
        predicate prevents a stale caller from projecting a phase it did not
        persist.  Only runtime projection fields are changed, so result,
        metadata, context snapshots, and completed tool side-effect evidence
        remain byte-for-byte untouched.
        """

        target_db = db or self._require_db()
        target_id = str(work_item_id or "").strip()
        if not target_id:
            return 0
        target_phase = coerce_phase(exact_phase)
        target_status = task_status_for_phase(target_phase)
        cursor = await target_db.execute(
            """UPDATE tasks
               SET status = ?, execution_lock = 0,
                   execution_locked_at = NULL
               WHERE id = (
                   SELECT runtime_task_id
                   FROM work_item_runtime_links
                   WHERE work_item_id = ?
               )
                 AND EXISTS (
                   SELECT 1
                   FROM delegation_work_items AS item
                   WHERE item.work_item_id = ? AND item.phase = ?
               )""",
            (
                target_status.value,
                target_id,
                target_id,
                target_phase.value,
            ),
        )
        return int(getattr(cursor, "rowcount", 0) or 0)

    async def _get_task_unhydrated(
        self,
        task_id: str,
        *,
        db: _SQLiteConnectionAdapter | None = None,
    ) -> Task | None:
        target_db = db or self._require_db()
        tid = str(task_id or "").strip()
        if not tid:
            return None
        async with target_db.execute(
            "SELECT * FROM tasks WHERE id = ?",
            (tid,),
        ) as cursor:
            row = await cursor.fetchone()
            if not row:
                return None
            return self._row_to_task(row, cursor.description)

    async def _task_status_for_id(self, task_id: str) -> str:
        assert self._db is not None
        tid = str(task_id or "").strip()
        if not tid:
            return ""
        async with self._db.execute(
            "SELECT status FROM tasks WHERE id=? LIMIT 1",
            (tid,),
        ) as cursor:
            row = await cursor.fetchone()
        return str(row[0] or "").strip().lower() if row else ""

    @staticmethod
    def _terminal_task_statuses() -> set[str]:
        return {
            TaskStatus.DONE.value,
            TaskStatus.FAILED.value,
            TaskStatus.CANCELLED.value,
        }

    async def _runtime_task_link_is_replaceable(self, task_id: str) -> bool:
        status = await self._task_status_for_id(task_id)
        return not status or status in self._terminal_task_statuses()

    @staticmethod
    def _runtime_task_matches_work_item(
        task: Task,
        item: DelegationWorkItem,
        *,
        preferred_task_id: str = "",
    ) -> bool:
        metadata = dict(getattr(task, "metadata", {}) or {})
        wid = str(getattr(item, "work_item_id", "") or "").strip()
        if not wid:
            return False

        preferred = str(preferred_task_id or "").strip()
        if not is_work_item_runtime_metadata(metadata) and str(getattr(task, "id", "") or "").strip() != preferred:
            return False

        projection_id = projection_id_for_work_item(item)
        task_projection_id = str(metadata.get(WORK_ITEM_PROJECTION_ID_KEY, "") or "").strip()
        if projection_id and task_projection_id != projection_id:
            return False

        item_run_id = str(getattr(item, "run_id", "") or "").strip()
        task_run_id = str(metadata.get("delegation_run_id", "") or "").strip()
        if item_run_id and task_run_id != item_run_id:
            return False

        item_role_id = str(getattr(item, "role_id", "") or "").strip()
        task_role_id = str(
            metadata.get("work_item_role_id", "")
            or metadata.get("role_id", "")
            or getattr(task, "assigned_to", "")
            or ""
        ).strip()
        if item_role_id and task_role_id and task_role_id != item_role_id:
            return False

        item_seat_id = str(
            getattr(item, "seat_id", "")
            or dict(getattr(item, "metadata", {}) or {}).get("seat_id", "")
            or ""
        ).strip()
        task_seat_id = str(
            metadata.get("delegation_seat_id", "")
            or metadata.get("seat_id", "")
            or ""
        ).strip()
        if item_seat_id and task_seat_id and task_seat_id != item_seat_id:
            return False

        return True

    async def _write_work_item_runtime_link(
        self,
        work_item_id: str,
        runtime_task_id: str,
        *,
        link_kind: str = "primary",
        commit: bool = True,
    ) -> bool:
        assert self._db is not None
        wid = str(work_item_id or "").strip()
        tid = str(runtime_task_id or "").strip()
        if not wid or not tid:
            return False
        now = datetime.now().isoformat()
        # runtime_task_id is UNIQUE. If stale legacy data points this Task at
        # another WorkItem, the explicit WorkItem link wins.
        await self._db.execute(
            "DELETE FROM work_item_runtime_links WHERE runtime_task_id=? AND work_item_id != ?",
            (tid, wid),
        )
        await self._db.execute(
            """INSERT INTO work_item_runtime_links
               (work_item_id, runtime_task_id, link_kind, created_at, updated_at)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(work_item_id) DO UPDATE SET
                   runtime_task_id=excluded.runtime_task_id,
                   link_kind=excluded.link_kind,
                   updated_at=excluded.updated_at""",
            (wid, tid, str(link_kind or "primary").strip() or "primary", now, now),
        )
        if commit:
            await self._db.commit()
        return True

    async def _validate_work_item_runtime_links(self) -> dict[str, int]:
        """Validate canonical WorkItem/Task links.

        WorkItem is the business source of truth; runtime Tasks are connected
        only through ``work_item_runtime_links``.
        """
        if self._db is None:
            return {}
        required_tables = ("tasks", "delegation_work_items", "work_item_runtime_links")
        for table in required_tables:
            if not await self._table_exists(table):
                return {"existing": 0, "missing": 0}

        stats = {"existing": 0, "missing": 0}
        diagnostics: list[str] = []
        linked_task_ids: set[str] = set()

        async with self._db.execute(
            "SELECT work_item_id, runtime_task_id FROM work_item_runtime_links"
        ) as cursor:
            for work_item_id, task_id in await cursor.fetchall():
                wid = str(work_item_id or "").strip()
                tid = str(task_id or "").strip()
                if not wid or not tid:
                    continue
                stats["existing"] += 1
                linked_task_ids.add(tid)
                if not await self._work_item_exists(wid):
                    diagnostics.append(f"runtime link points to missing WorkItem: work_item={wid} task={tid}")
                if not await self._task_exists(tid):
                    diagnostics.append(f"runtime link points to missing Task: work_item={wid} task={tid}")

        async with self._db.execute(
            """SELECT id, metadata
               FROM tasks
               WHERE metadata LIKE '%work_item_runtime%'
                 AND metadata LIKE '%work_item_projection_id%'"""
        ) as cursor:
            projection_rows = await cursor.fetchall()
        for task_id, metadata_json in projection_rows:
            tid = str(task_id or "").strip()
            try:
                metadata = _json_loads(metadata_json, {})
            except Exception as exc:
                diagnostics.append(f"invalid company runtime projection metadata: task={tid} error={exc}")
                continue
            if not isinstance(metadata, dict) or not is_work_item_runtime_metadata(metadata):
                continue
            projection_id = str(metadata.get(WORK_ITEM_PROJECTION_ID_KEY, "") or "").strip()
            if projection_id and tid not in linked_task_ids:
                stats["missing"] += 1
                diagnostics.append(
                    "company runtime projection missing canonical link: "
                    f"task={tid} projection={projection_id}"
                )

        if diagnostics:
            sample = "; ".join(diagnostics[:12])
            suffix = "" if len(diagnostics) <= 12 else f"; ... {len(diagnostics) - 12} more"
            raise RuntimeError(
                "canonical WorkItem runtime link validation failed "
                f"(db_path={self.db_path}): {sample}{suffix}"
            )

        return stats

