    async def _ensure_columns(self, table: str, columns: dict[str, str]) -> None:
        assert self._db
        async with self._db.execute(f"PRAGMA table_info({table})") as cursor:
            rows = await cursor.fetchall()
        existing = {row[1] for row in rows}
        for name, ddl in columns.items():
            if name in existing:
                continue
            await self._db.execute(f"ALTER TABLE {table} ADD COLUMN {name} {ddl}")
        await self._db.commit()

    async def _drop_mismatched_delegation_work_item_indexes(self) -> None:
        assert self._db
        expected = {
            "idx_delegation_work_items_run": ["run_id", "phase", "role_id"],
            "idx_delegation_work_items_team": ["team_instance_id", "team_id", "seat_id", "phase"],
            "idx_delegation_work_items_batch": ["run_id", "batch_id", "batch_index", "phase"],
            "idx_delegation_work_items_manager_board": ["run_id", "manager_seat_id", "parent_work_item_id", "phase"],
        }
        async with self._db.execute("PRAGMA index_list(delegation_work_items)") as cursor:
            rows = await cursor.fetchall()
        existing = {str(row[1]) for row in rows}
        for index_name, expected_columns in expected.items():
            if index_name not in existing:
                continue
            async with self._db.execute(f"PRAGMA index_info({index_name})") as cursor:
                info = await cursor.fetchall()
            columns = [str(row[2]) for row in info]
            if columns != expected_columns:
                await self._db.execute(f"DROP INDEX IF EXISTS {index_name}")
        await self._db.commit()

    async def _ensure_external_session_layout(self) -> None:
        assert self._db
        async with self._db.execute(
            "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'external_sessions'"
        ) as cursor:
            row = await cursor.fetchone()
        create_sql = row[0] if row else ""
        if create_sql and "PRIMARY KEY (agent_type, project_id)" not in create_sql:
            return
        await self._db.executescript(
            """
            CREATE TABLE IF NOT EXISTS external_sessions_v2 (
                session_key TEXT PRIMARY KEY,
                agent_type TEXT NOT NULL,
                project_id TEXT DEFAULT 'default',
                session_id TEXT NOT NULL,
                opc_session_id TEXT,
                task_id TEXT,
                workspace_path TEXT DEFAULT '',
                run_mode TEXT DEFAULT 'batch',
                status TEXT DEFAULT 'unknown',
                metadata TEXT DEFAULT '{}',
                updated_at TEXT NOT NULL
            );
            INSERT OR REPLACE INTO external_sessions_v2
            (session_key, agent_type, project_id, session_id, opc_session_id, task_id, workspace_path, run_mode, status, metadata, updated_at)
            SELECT
                printf('%s|%s|%s|%s|%s', agent_type, project_id, ifnull(opc_session_id, ''), ifnull(task_id, ''), session_id),
                agent_type,
                project_id,
                session_id,
                opc_session_id,
                task_id,
                workspace_path,
                run_mode,
                status,
                metadata,
                updated_at
            FROM external_sessions;
            DROP TABLE external_sessions;
            ALTER TABLE external_sessions_v2 RENAME TO external_sessions;
            CREATE INDEX IF NOT EXISTS idx_external_sessions_agent_project ON external_sessions(agent_type, project_id, updated_at);
            """
        )
        await self._db.commit()

    async def close(self) -> None:
        if self._db:
            await self._db.close()
            self._db = None

    async def _table_exists(self, table: str) -> bool:
        assert self._db
        async with self._db.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",
            (table,),
        ) as cursor:
            return await cursor.fetchone() is not None

    @staticmethod
    def _clean_text_ids(values: Any) -> set[str]:
        return {
            str(value or "").strip()
            for value in values
            if str(value or "").strip()
        }

    @staticmethod
    def _chunked_ids(values: set[str] | list[str], size: int = 400) -> list[list[str]]:
        ids = sorted(OPCStore._clean_text_ids(values))
        return [ids[index : index + size] for index in range(0, len(ids), size)]

    async def _fetch_text_column(
        self,
        query: str,
        params: tuple[Any, ...] | list[Any] = (),
    ) -> set[str]:
        assert self._db
        async with self._db.execute(query, tuple(params)) as cursor:
            rows = await cursor.fetchall()
        return self._clean_text_ids(row[0] for row in rows)

    async def _fetch_text_column_where_in(
        self,
        table: str,
        select_column: str,
        where_column: str,
        values: set[str] | list[str],
        *,
        extra_where: str = "",
    ) -> set[str]:
        assert self._db
        results: set[str] = set()
        for chunk in self._chunked_ids(values):
            placeholders = ", ".join("?" for _ in chunk)
            query = f"SELECT {select_column} FROM {table} WHERE {where_column} IN ({placeholders})"
            if extra_where:
                query += f" AND {extra_where}"
            async with self._db.execute(query, tuple(chunk)) as cursor:
                rows = await cursor.fetchall()
            results.update(self._clean_text_ids(row[0] for row in rows))
        return results

    async def _delete_where_in(
        self,
        table: str,
        column: str,
        values: set[str] | list[str],
    ) -> None:
        assert self._db
        for chunk in self._chunked_ids(values):
            placeholders = ", ".join("?" for _ in chunk)
            await self._db.execute(
                f"DELETE FROM {table} WHERE {column} IN ({placeholders})",
                tuple(chunk),
            )

    async def _delete_events_by_payload_ids(
        self,
        json_path: str,
        values: set[str] | list[str],
    ) -> None:
        assert self._db
        for chunk in self._chunked_ids(values):
            placeholders = ", ".join("?" for _ in chunk)
            await self._db.execute(
                f"""
                DELETE FROM events
                WHERE json_valid(payload)
                  AND json_extract(payload, ?) IN ({placeholders})
                """,
                tuple([json_path, *chunk]),
            )

    async def _fetch_text_column_where_text_contains(
        self,
        table: str,
        select_column: str,
        text_column: str,
        values: set[str] | list[str],
    ) -> set[str]:
        assert self._db
        results: set[str] = set()
        for chunk in self._chunked_ids(values):
            conditions = " OR ".join(f"{text_column} LIKE ?" for _ in chunk)
            async with self._db.execute(
                f"SELECT {select_column} FROM {table} WHERE {conditions}",
                tuple(f"%{value}%" for value in chunk),
            ) as cursor:
                rows = await cursor.fetchall()
            results.update(self._clean_text_ids(row[0] for row in rows))
        return results

    async def _delete_where_text_contains(
        self,
        table: str,
        text_column: str,
        values: set[str] | list[str],
    ) -> None:
        assert self._db
        for chunk in self._chunked_ids(values):
            conditions = " OR ".join(f"{text_column} LIKE ?" for _ in chunk)
            await self._db.execute(
                f"DELETE FROM {table} WHERE {conditions}",
                tuple(f"%{value}%" for value in chunk),
            )

    async def _delete_by_json_path_or_text_ids(
        self,
        table: str,
        json_column: str,
        json_paths: tuple[str, ...],
        values: set[str] | list[str],
    ) -> None:
        assert self._db
        clean_values = self._clean_text_ids(values)
        if not clean_values:
            return
        for path in json_paths:
            for chunk in self._chunked_ids(clean_values):
                placeholders = ", ".join("?" for _ in chunk)
                await self._db.execute(
                    f"""
                    DELETE FROM {table}
                    WHERE json_valid({json_column})
                      AND json_extract({json_column}, ?) IN ({placeholders})
                    """,
                    tuple([path, *chunk]),
                )
        await self._delete_where_text_contains(table, json_column, clean_values)

    async def _delete_company_runtime_artifacts_for_task(
        self,
        task_id: str,
        session_id: str | None,
        *,
        shared_session: bool,
    ) -> None:
        """Delete company-mode and runtime rows tied to one task/session.

        Top-level chat deletion removes the full delegation run for that
        session. Child work-item deletion removes only the linked work item and
        its runtime traces so a sibling/parent run is not destroyed.
        """
        if not self._db:
            return

        clean_task_id = str(task_id or "").strip()
        clean_session_id = str(session_id or "").strip()
        if not clean_task_id and not clean_session_id:
            return

        task_row: dict[str, Any] = {}
        if clean_task_id:
            async with self._db.execute(
                "SELECT id, session_id, parent_session_id, project_id, metadata FROM tasks WHERE id = ?",
                (clean_task_id,),
            ) as cursor:
                row = await cursor.fetchone()
                if row:
                    cols = [description[0] for description in cursor.description]
                    task_row = dict(zip(cols, row))

        parent_session_id = str(task_row.get("parent_session_id") or "").strip()
        if not clean_session_id and task_row:
            clean_session_id = str(task_row.get("session_id") or parent_session_id or "").strip()
        is_primary_session_task = bool(clean_session_id and not shared_session and not parent_session_id)

        task_ids: set[str] = set()
        if clean_task_id:
            task_ids.add(clean_task_id)
        if clean_session_id and not shared_session:
            task_ids.update(
                await self._fetch_text_column(
                    "SELECT id FROM tasks WHERE session_id = ? OR parent_session_id = ?",
                    (clean_session_id, clean_session_id),
                )
            )
        session_ids = {clean_session_id} if clean_session_id and not shared_session else set()
        full_run_ids: set[str] = set()
        work_item_ids: set[str] = set()
        role_runtime_session_ids: set[str] = set()
        runtime_session_ids: set[str] = set()

        if is_primary_session_task:
            full_run_ids.update(
                await self._fetch_text_column(
                    "SELECT run_id FROM delegation_runs WHERE session_id = ?",
                    (clean_session_id,),
                )
            )

        if task_ids:
            work_item_ids.update(
                await self._fetch_text_column_where_in(
                    "work_item_runtime_links",
                    "work_item_id",
                    "runtime_task_id",
                    task_ids,
                )
            )

        metadata_paths = (
            "$.task_id",
            "$.runtime_task_id",
            "$.execution_task_id",
            "$.origin_task_id",
            "$.worker_task_id",
        )
        if task_ids:
            for path in metadata_paths:
                for chunk in self._chunked_ids(task_ids):
                    placeholders = ", ".join("?" for _ in chunk)
                    work_item_ids.update(
                        await self._fetch_text_column(
                            f"""
                            SELECT work_item_id FROM delegation_work_items
                            WHERE json_valid(metadata)
                              AND json_extract(metadata, ?) IN ({placeholders})
                            """,
                            tuple([path, *chunk]),
                        )
                    )

        if session_ids:
            for chunk in self._chunked_ids(session_ids):
                placeholders = ", ".join("?" for _ in chunk)
                work_item_ids.update(
                    await self._fetch_text_column(
                        f"""
                        SELECT work_item_id FROM delegation_work_items
                        WHERE json_valid(metadata)
                          AND (
                            json_extract(metadata, '$.session_id') IN ({placeholders})
                            OR json_extract(metadata, '$.parent_session_id') IN ({placeholders})
                            OR json_extract(metadata, '$.session_scope_id') IN ({placeholders})
                          )
                        """,
                        tuple([*chunk, *chunk, *chunk]),
                    )
                )

        if full_run_ids:
            work_item_ids.update(
                await self._fetch_text_column_where_in(
                    "delegation_work_items",
                    "work_item_id",
                    "run_id",
                    full_run_ids,
                )
            )

        if work_item_ids:
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "delegation_work_items",
                    "role_runtime_session_id",
                    "work_item_id",
                    work_item_ids,
                    extra_where="COALESCE(role_runtime_session_id, '') != ''",
                )
            )
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "delegation_work_items",
                    "claimed_by_role_runtime_session_id",
                    "work_item_id",
                    work_item_ids,
                    extra_where="COALESCE(claimed_by_role_runtime_session_id, '') != ''",
                )
            )

        if full_run_ids:
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "role_runtime_sessions",
                    "role_session_id",
                    "run_id",
                    full_run_ids,
                )
            )
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "delegation_role_sessions",
                    "role_session_id",
                    "run_id",
                    full_run_ids,
                )
            )
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "seat_states",
                    "role_runtime_session_id",
                    "run_id",
                    full_run_ids,
                    extra_where="COALESCE(role_runtime_session_id, '') != ''",
                )
            )
            role_runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "seat_states",
                    "member_session_id",
                    "run_id",
                    full_run_ids,
                    extra_where="COALESCE(member_session_id, '') != ''",
                )
            )

        if task_ids:
            runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "runtime_sessions",
                    "runtime_session_id",
                    "task_id",
                    task_ids,
                )
            )
        if session_ids:
            runtime_session_ids.update(
                await self._fetch_text_column_where_in(
                    "runtime_sessions",
                    "runtime_session_id",
                    "session_id",
                    session_ids,
                )
            )
        if full_run_ids:
            runtime_session_ids.update(role_runtime_session_ids)
            # Some company runtime events are scoped directly to the run id
            # rather than a role/runtime session id.
            runtime_session_ids.update(full_run_ids)
        runtime_lookup_ids = task_ids | session_ids | full_run_ids | work_item_ids
        if full_run_ids:
            runtime_lookup_ids.update(role_runtime_session_ids)
        runtime_session_ids.update(
            await self._fetch_text_column_where_text_contains(
                "runtime_sessions",
                "runtime_session_id",
                "runtime_session_id",
                runtime_lookup_ids,
            )
        )
        runtime_session_ids.update(
            await self._fetch_text_column_where_text_contains(
                "runtime_sessions",
                "runtime_session_id",
                "metadata",
                runtime_lookup_ids,
            )
        )

        task_tables = (
            "runtime_transcript_entries",
            "runtime_user_turn_seeds",
            "runtime_tool_calls",
            "runtime_tool_results",
            "runtime_subagent_runs",
            "runtime_worktree_sessions",
            "runtime_compaction_boundaries",
        )
        for table in task_tables:
            await self._delete_where_in(table, "task_id", task_ids)
            if session_ids and table in {
                "runtime_transcript_entries",
                "runtime_user_turn_seeds",
                "runtime_tool_calls",
                "runtime_tool_results",
            }:
                await self._delete_where_in(table, "session_id", session_ids)

        if runtime_session_ids:
            for table in (
                "runtime_events",
                "runtime_transcript_entries",
                "runtime_user_turn_seeds",
                "runtime_tool_calls",
                "runtime_tool_results",
                "runtime_permission_grants",
                "runtime_subagent_runs",
                "runtime_worktree_sessions",
                "runtime_compaction_boundaries",
                "runtime_sessions",
            ):
                await self._delete_where_in(table, "runtime_session_id", runtime_session_ids)

        await self._delete_where_in("execution_checkpoints", "task_id", task_ids)
        await self._delete_where_in("execution_checkpoints", "session_id", session_ids)
        await self._delete_by_json_path_or_text_ids(
            "execution_checkpoints",
            "payload",
            ("$.task_id", "$.session_id", "$.run_id", "$.work_item_id"),
            task_ids | session_ids | full_run_ids | work_item_ids,
        )
        await self._delete_where_in("external_sessions", "task_id", task_ids)
        await self._delete_where_in("external_sessions", "opc_session_id", session_ids)
        await self._delete_where_in("external_sessions", "session_id", session_ids)
        await self._delete_where_text_contains(
            "external_sessions",
            "metadata",
            task_ids | session_ids | full_run_ids | work_item_ids | runtime_session_ids,
        )
        if await self._table_exists("external_sessions_v2"):
            await self._delete_where_in("external_sessions_v2", "task_id", task_ids)
            await self._delete_where_in("external_sessions_v2", "opc_session_id", session_ids)
            await self._delete_where_in("external_sessions_v2", "session_id", session_ids)
            await self._delete_where_text_contains(
                "external_sessions_v2",
                "metadata",
                task_ids | session_ids | full_run_ids | work_item_ids | runtime_session_ids,
            )

        if clean_task_id:
            await self._db.execute(
                """
                DELETE FROM events
                WHERE json_valid(payload)
                  AND (
                    json_extract(payload, '$.task_id') = ?
                    OR json_extract(payload, '$.runtime_task_id') = ?
                    OR json_extract(payload, '$.execution_task_id') = ?
                    OR json_extract(payload, '$.escalation_id') LIKE ?
                  )
                """,
                (clean_task_id, clean_task_id, clean_task_id, f"esc_{clean_task_id}_%"),
            )
        for path in (
            "$.task_id",
            "$.runtime_task_id",
            "$.execution_task_id",
            "$.origin_task_id",
            "$.worker_task_id",
        ):
            await self._delete_events_by_payload_ids(path, task_ids)
        for path in ("$.session_id", "$.parent_session_id", "$.opc_session_id"):
            await self._delete_events_by_payload_ids(path, session_ids)
        await self._delete_events_by_payload_ids("$.run_id", full_run_ids)
        await self._delete_events_by_payload_ids("$.work_item_id", work_item_ids)
        await self._delete_events_by_payload_ids("$.runtime_session_id", runtime_session_ids)
        role_event_session_ids = set(runtime_session_ids)
        if full_run_ids:
            role_event_session_ids.update(role_runtime_session_ids)
        await self._delete_events_by_payload_ids("$.role_runtime_session_id", role_event_session_ids)
        await self._delete_events_by_payload_ids("$.member_session_id", role_event_session_ids)
        event_scope_ids = task_ids | session_ids | full_run_ids | work_item_ids | runtime_session_ids
        if full_run_ids:
            event_scope_ids.update(role_runtime_session_ids)
        await self._delete_where_text_contains(
            "events",
            "payload",
            event_scope_ids,
        )

        if full_run_ids:
            await self._delete_where_in("work_item_runtime_links", "work_item_id", work_item_ids)
            await self._delete_where_in("delegation_events", "run_id", full_run_ids)
            await self._delete_where_in("delegation_work_items", "run_id", full_run_ids)
            await self._delete_where_in("delegation_cells", "run_id", full_run_ids)
            await self._delete_where_in("delegation_role_sessions", "run_id", full_run_ids)
            await self._delete_where_in("role_runtime_sessions", "run_id", full_run_ids)
            await self._delete_where_in("seat_states", "run_id", full_run_ids)
            await self._delete_where_in("team_instances", "run_id", full_run_ids)
            await self._delete_where_in("delegation_runs", "run_id", full_run_ids)
        elif work_item_ids:
            await self._delete_where_in("work_item_runtime_links", "work_item_id", work_item_ids)
            await self._delete_where_in("delegation_events", "work_item_id", work_item_ids)
            await self._delete_where_in("delegation_work_items", "work_item_id", work_item_ids)
            if await self._table_exists("external_sessions_v2"):
                await self._delete_where_text_contains(
                    "external_sessions_v2",
                    "metadata",
                    task_ids | session_ids | full_run_ids | work_item_ids | runtime_session_ids,
                )
            await self._delete_where_in("work_item_runtime_links", "runtime_task_id", task_ids)
            for chunk in self._chunked_ids(work_item_ids):
                placeholders = ", ".join("?" for _ in chunk)
                await self._db.execute(
                    f"""
                    UPDATE seat_states
                    SET current_work_item_id = '',
                        current_task_id = ''
                    WHERE current_work_item_id IN ({placeholders})
                    """,
                    tuple(chunk),
                )
                await self._db.execute(
                    f"""
                    UPDATE role_runtime_sessions
                    SET focused_work_item_id = ''
                    WHERE focused_work_item_id IN ({placeholders})
                    """,
                    tuple(chunk),
                )

    async def delete_company_runtime_artifacts_for_session(
        self,
        session_id: str,
    ) -> None:
        """Delete company runtime rows tied to a chat session id.

        This is intentionally session-driven rather than task-driven so a hard
        chat delete can clean orphan company runtime rows even if the task row
        was already removed by an earlier or partial delete path.
        """
        if not self._db:
            return
        clean_session_id = str(session_id or "").strip()
        if not clean_session_id:
            return
        await self._delete_company_runtime_artifacts_for_task(
            "",
            clean_session_id,
            shared_session=False,
        )
        await self._db.commit()

    async def _delete_runtime_user_turn_graph_for_session_data(
        self,
        *,
        task_id: str,
        session_id: str | None,
        shared_session: bool,
    ) -> None:
        """Delete the complete runtime/user-turn graph before chat cleanup.

        ``runtime_user_turn_seeds`` asserts that its session message, part, and
        runtime transcript entry were committed atomically.  A soft chat
        deletion must therefore remove the same graph atomically; retaining a
        seed after deleting its message would make every idempotent retry fail
        with an incomplete-record invariant.
        """

        assert self._db is not None
        clean_task_id = str(task_id or "").strip()
        clean_session_id = str(session_id or "").strip()
        conditions = ["task_id = ?"]
        params: list[Any] = [clean_task_id]
        if clean_session_id and not shared_session:
            conditions.append("session_id = ?")
            params.append(clean_session_id)
        predicate = " OR ".join(conditions)

        # Only a runtime_sessions row whose own task/session envelope matches is
        # owned by this cleanup.  A transcript entry may point at a canonical
        # role runtime shared by sibling WorkItems; deriving ownership from that
        # entry would tear down the parent company's live role session.
        runtime_session_ids: set[str] = set()
        seed_message_ids: set[str] = set()
        if await self._table_exists("runtime_sessions"):
            async with self._db.execute(
                f"SELECT runtime_session_id FROM runtime_sessions WHERE {predicate}",
                tuple(params),
            ) as cursor:
                rows = await cursor.fetchall()
            runtime_session_ids.update(
                str(row[0] or "").strip() for row in rows if str(row[0] or "").strip()
            )
        if await self._table_exists("runtime_user_turn_seeds"):
            async with self._db.execute(
                f"SELECT message_id FROM runtime_user_turn_seeds WHERE {predicate}",
                tuple(params),
            ) as cursor:
                rows = await cursor.fetchall()
            seed_message_ids.update(
                str(row[0] or "").strip() for row in rows if str(row[0] or "").strip()
            )

        await self._delete_where_in("session_parts", "message_id", seed_message_ids)
        await self._delete_where_in("session_messages", "message_id", seed_message_ids)
        for table in (
            "runtime_events",
            "runtime_transcript_entries",
            "runtime_user_turn_seeds",
            "runtime_tool_calls",
            "runtime_tool_results",
            "runtime_permission_grants",
            "runtime_subagent_runs",
            "runtime_worktree_sessions",
            "runtime_compaction_boundaries",
            "runtime_sessions",
        ):
            await self._delete_where_in(
                table,
                "runtime_session_id",
                runtime_session_ids,
            )
        for table in (
            "runtime_transcript_entries",
            "runtime_user_turn_seeds",
            "runtime_tool_calls",
            "runtime_tool_results",
        ):
            await self._db.execute(
                f"DELETE FROM {table} WHERE {predicate}",
                tuple(params),
            )
        for table in (
            "runtime_subagent_runs",
            "runtime_worktree_sessions",
            "runtime_compaction_boundaries",
        ):
            await self._db.execute(
                f"DELETE FROM {table} WHERE task_id = ?",
                (clean_task_id,),
            )

    async def delete_session_data(
        self,
        task_id: str,
        session_id: str | None = None,
        *,
        _transaction_open: bool = False,
    ) -> None:
        """Delete all data associated with a session/task.

        Cleans: agent_messages, session_messages, session_parts,
        session_compactions, execution_checkpoints, external_sessions.
        The task row itself is NOT deleted (caller marks it CANCELLED).
        """
        if not self._db:
            return
        try:
            if not _transaction_open:
                await self._db.execute("BEGIN IMMEDIATE")
            await self._db.execute("DELETE FROM agent_messages WHERE task_id = ?", (task_id,))
            shared_session = False
            if session_id:
                async with self._db.execute(
                    "SELECT 1 FROM tasks WHERE session_id = ? AND id != ? LIMIT 1",
                    (session_id, task_id),
                ) as cursor:
                    shared_session = await cursor.fetchone() is not None
            await self._delete_runtime_user_turn_graph_for_session_data(
                task_id=task_id,
                session_id=session_id,
                shared_session=shared_session,
            )
            if session_id:
                if not shared_session:
                    await self._db.execute("DELETE FROM session_parts WHERE session_id = ?", (session_id,))
                    await self._db.execute("DELETE FROM session_compactions WHERE session_id = ?", (session_id,))
                    await self._db.execute("DELETE FROM session_memory_snapshots WHERE session_id = ?", (session_id,))
                    await self._db.execute("DELETE FROM agent_compactions WHERE session_id = ?", (session_id,))
                    await self._db.execute("DELETE FROM agent_memory_snapshots WHERE session_id = ?", (session_id,))
                    await self._db.execute("DELETE FROM session_messages WHERE session_id = ?", (session_id,))
            else:
                await self._db.execute("DELETE FROM session_messages WHERE task_id = ?", (task_id,))
            if session_id and not shared_session:
                await self._db.execute(
                    "DELETE FROM execution_checkpoints WHERE task_id = ? OR session_id = ?",
                    (task_id, session_id),
                )
                await self._db.execute(
                    "DELETE FROM external_sessions WHERE task_id = ? OR opc_session_id = ?",
                    (task_id, session_id),
                )
                if await self._table_exists("external_sessions_v2"):
                    await self._db.execute(
                        "DELETE FROM external_sessions_v2 WHERE task_id = ? OR opc_session_id = ?",
                        (task_id, session_id),
                    )
            else:
                await self._db.execute("DELETE FROM execution_checkpoints WHERE task_id = ?", (task_id,))
                await self._db.execute("DELETE FROM external_sessions WHERE task_id = ?", (task_id,))
                if await self._table_exists("external_sessions_v2"):
                    await self._db.execute("DELETE FROM external_sessions_v2 WHERE task_id = ?", (task_id,))
            if not _transaction_open:
                await self._db.commit()
        except BaseException:
            if not _transaction_open:
                await self._db.rollback()
            raise

    async def hard_delete_task(self, task_id: str, session_id: str | None = None) -> None:
        """Permanently delete a task row and all persisted lifecycle data."""
        if not self._db:
            return
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            shared_session = False
            if session_id:
                async with self._db.execute(
                    "SELECT 1 FROM tasks WHERE session_id = ? AND id != ? LIMIT 1",
                    (session_id, task_id),
                ) as cursor:
                    shared_session = await cursor.fetchone() is not None
            # Capture and remove the seed-owned message/part graph before the
            # broader runtime cleanup deletes the seed rows carrying message_id.
            await self._delete_runtime_user_turn_graph_for_session_data(
                task_id=task_id,
                session_id=session_id,
                shared_session=shared_session,
            )
            await self._delete_company_runtime_artifacts_for_task(
                task_id,
                session_id,
                shared_session=shared_session,
            )
            await self.delete_session_data(
                task_id,
                session_id,
                _transaction_open=True,
            )
            await self._db.execute("DELETE FROM meetings WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM work_item_decisions WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM artifact_records WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM cost_records WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM cost_events WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM approval_records WHERE task_id = ?", (task_id,))
            if session_id and not shared_session:
                await self._db.execute(
                    "DELETE FROM handoff_records WHERE task_id = ? OR session_id = ?",
                    (task_id, session_id),
                )
                await self._db.execute(
                    "DELETE FROM reorg_proposals WHERE task_id = ? OR session_id = ?",
                    (task_id, session_id),
                )
                await self._db.execute(
                    "DELETE FROM session_links WHERE task_id = ? OR session_id = ? OR linked_session_id = ?",
                    (task_id, session_id, session_id),
                )
                await self._db.execute("DELETE FROM sessions WHERE session_id = ?", (session_id,))
            else:
                await self._db.execute("DELETE FROM handoff_records WHERE task_id = ?", (task_id,))
                await self._db.execute("DELETE FROM reorg_proposals WHERE task_id = ?", (task_id,))
                await self._db.execute("DELETE FROM session_links WHERE task_id = ?", (task_id,))
            await self._db.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
            await self._db.commit()
        except BaseException:
            await self._db.rollback()
            raise

    # --- Tasks ---

    @staticmethod
    def _metadata_has_work_item_projection_identity(metadata: dict[str, Any]) -> bool:
        return any(
            str(metadata.get(key, "") or "").strip()
            for key in (
                WORK_ITEM_PROJECTION_ID_KEY,
                WORK_ITEM_TURN_TYPE_KEY,
            )
        )

    _TASK_RUNTIME_TOOL_LEDGER_KEYS = (
        "approved_tool_call",
        "approved_tool_calls",
        "continue_after_tool_result",
    )

    @classmethod
    def _canonicalize_task_runtime_tool_ledger(
        cls,
        context_snapshot: dict[str, Any],
        metadata: dict[str, Any],
    ) -> tuple[
        dict[str, Any],
        dict[str, Any],
        dict[str, dict[str, Any]],
        bool,
        str,
    ]:
        """Read the two authoritative Task ledger views into one exact map.

        ``context_snapshot.runtime_v2`` is deliberately excluded: it is an
        audit mirror historically written by task-ledger persistence, never an
        ownership source.  The two plural maps must agree when both are
        populated.  Legacy singular permits are then merged by their embedded
        fingerprint; ambiguous or conflicting legacy state fails closed.

        A runtime id is an ownership fence only while permits or the explicit
        post-result continuation marker are active.  In that state every
        top-level and permit-carried runtime id must resolve to exactly one
        value.  With no active ledger, old audit ids may be replaced by the
        next Store command and are therefore not forced to agree here.
        """

        runtime_resume = dict(context_snapshot.get("runtime_resume", {}) or {})
        runtime_metadata = dict(metadata.get("runtime_v2", {}) or {})

        def _plural(
            container: dict[str, Any],
            *,
            label: str,
        ) -> dict[str, dict[str, Any]]:
            raw = container.get("approved_tool_calls")
            if raw in (None, {}):
                return {}
            if not isinstance(raw, dict):
                raise RuntimeError(f"{label} approved_tool_calls is not a mapping")
            normalized: dict[str, dict[str, Any]] = {}
            for raw_fingerprint, raw_permit in raw.items():
                fingerprint = str(raw_fingerprint or "").strip()
                if not fingerprint or not isinstance(raw_permit, dict):
                    raise RuntimeError(
                        f"{label} approved_tool_calls contains an invalid permit"
                    )
                permit = copy.deepcopy(dict(raw_permit))
                embedded = str(permit.get("fingerprint", "") or "").strip()
                if embedded and embedded != fingerprint:
                    raise RuntimeError(
                        f"{label} approved_tool_calls fingerprint conflicts with its key"
                    )
                permit["fingerprint"] = fingerprint
                normalized[fingerprint] = permit
            return normalized

        resume_permits = _plural(runtime_resume, label="runtime_resume")
        metadata_permits = _plural(runtime_metadata, label="metadata.runtime_v2")
        if (
            resume_permits
            and metadata_permits
            and resume_permits != metadata_permits
        ):
            raise RuntimeError(
                "Task exact ToolCall permit views conflict"
            )
        permits = copy.deepcopy(resume_permits or metadata_permits)

        singular_permits: list[dict[str, Any]] = []
        for container, label in (
            (runtime_resume, "runtime_resume"),
            (runtime_metadata, "metadata.runtime_v2"),
        ):
            raw_singular = container.get("approved_tool_call")
            if raw_singular in (None, {}):
                continue
            if not isinstance(raw_singular, dict):
                raise RuntimeError(
                    f"{label} approved_tool_call is not a mapping"
                )
            singular = copy.deepcopy(dict(raw_singular))
            fingerprint = str(singular.get("fingerprint", "") or "").strip()
            if not fingerprint:
                raise RuntimeError(
                    f"{label} approved_tool_call has no fingerprint"
                )
            singular["fingerprint"] = fingerprint
            singular_permits.append(singular)

        if len(singular_permits) == 2 and (
            singular_permits[0] != singular_permits[1]
        ):
            raise RuntimeError("Task legacy exact ToolCall permit views conflict")
        singular = singular_permits[0] if singular_permits else None
        if singular is not None:
            fingerprint = str(singular["fingerprint"])
            if permits:
                existing = permits.get(fingerprint)
                if existing is None or existing != singular:
                    raise RuntimeError(
                        "Task legacy exact ToolCall permit conflicts with canonical map"
                    )
            else:
                permits[fingerprint] = singular

        continuation = any(
            container.get("continue_after_tool_result") is True
            for container in (runtime_resume, runtime_metadata)
        )
        top_level_runtime_ids = {
            str(value or "").strip()
            for value in (
                runtime_resume.get("runtime_session_id"),
                runtime_metadata.get("runtime_session_id"),
            )
            if str(value or "").strip()
        }
        active_runtime_ids = set(top_level_runtime_ids)
        for permit in permits.values():
            permit_runtime_id = str(
                permit.get("runtime_session_id", "") or ""
            ).strip()
            if not permit_runtime_id:
                raise RuntimeError(
                    "Task exact ToolCall permit has no runtime session identity"
                )
            active_runtime_ids.add(permit_runtime_id)
        if permits or continuation:
            if len(active_runtime_ids) != 1:
                raise RuntimeError(
                    "active Task exact ToolCall ledger has conflicting runtime "
                    "session identities"
                )
            runtime_session_id = next(iter(active_runtime_ids))
        else:
            runtime_session_id = (
                next(iter(top_level_runtime_ids))
                if len(top_level_runtime_ids) == 1
                else ""
            )
        return (
            runtime_resume,
            runtime_metadata,
            permits,
            continuation,
            runtime_session_id,
        )

    @classmethod
    def _write_canonical_task_runtime_tool_ledger(
        cls,
        context_snapshot: dict[str, Any],
        metadata: dict[str, Any],
        *,
        runtime_resume: dict[str, Any],
        runtime_metadata: dict[str, Any],
        permits: dict[str, dict[str, Any]],
        continuation: bool,
        runtime_session_id: str,
    ) -> None:
        """Write one canonical ledger to both authorities and scrub the mirror."""

        clean_runtime_id = str(runtime_session_id or "").strip()
        canonical_permits = {
            str(fingerprint): copy.deepcopy(dict(permit))
            for fingerprint, permit in permits.items()
        }
        for container in (runtime_resume, runtime_metadata):
            container.pop("approved_tool_call", None)
            if canonical_permits:
                container["approved_tool_calls"] = copy.deepcopy(
                    canonical_permits
                )
            else:
                container.pop("approved_tool_calls", None)
            if continuation:
                container["continue_after_tool_result"] = True
            else:
                container.pop("continue_after_tool_result", None)
            if clean_runtime_id:
                container["runtime_session_id"] = clean_runtime_id
            else:
                container.pop("runtime_session_id", None)
        context_snapshot["runtime_resume"] = runtime_resume
        metadata["runtime_v2"] = runtime_metadata
        cls._scrub_non_authoritative_context_runtime_ledger(
            context_snapshot,
            runtime_session_id=clean_runtime_id,
        )

    @classmethod
    def _scrub_non_authoritative_context_runtime_ledger(
        cls,
        context_snapshot: dict[str, Any],
        *,
        runtime_session_id: str = "",
    ) -> None:
        """Remove exact-permit state from the legacy context runtime mirror."""

        raw_mirror = context_snapshot.get("runtime_v2")
        if not isinstance(raw_mirror, dict):
            return
        mirror = dict(raw_mirror)
        for key in cls._TASK_RUNTIME_TOOL_LEDGER_KEYS:
            mirror.pop(key, None)
        clean_runtime_session_id = str(runtime_session_id or "").strip()
        if clean_runtime_session_id:
            mirror["runtime_session_id"] = clean_runtime_session_id
        else:
            mirror.pop("runtime_session_id", None)
        context_snapshot["runtime_v2"] = mirror

    @classmethod
    def _exact_tool_permit_matches_checkpoint(
        cls,
        permit: dict[str, Any],
        checkpoint: ExecutionCheckpoint,
        *,
        task_id: str,
        project_id: str,
        runtime_session_id: str,
        fingerprint: str,
        tool_call_id: str,
        tool_name: str,
        arguments: dict[str, Any],
        execution_envelope: dict[str, Any] | None = None,
        execution_identity: dict[str, Any] | None = None,
        claim_id: str,
        consumer_id: str,
    ) -> bool:
        """Validate the full immutable owner/effect identity of one permit."""

        checkpoint_payload = dict(checkpoint.payload or {})
        interaction = cls._execution_checkpoint_interaction(checkpoint_payload)
        ownership = dict(interaction.get("ownership", {}) or {})
        recorded_claim = dict(interaction.get("claim", {}) or {})
        checkpoint_call = dict(checkpoint_payload.get("tool_call", {}) or {})
        decision = str(permit.get("decision", "") or "").strip()
        decision_record = dict(interaction.get("decision", {}) or {})
        checkpoint_decision = str(
            decision_record.get("canonical_tool_permission_token", "") or ""
        ).strip()
        if not checkpoint_decision:
            checkpoint_decision = canonical_tool_permission_decision(
                decision_record.get("value")
            )
        approved_decisions = {
            "approve_once",
            "approve_session",
            "always_project",
            "always_global",
        }
        approved = permit.get("approved") is True
        if (
            approved != (decision in approved_decisions)
            or not checkpoint_decision
            or checkpoint_decision != decision
        ):
            return False
        return bool(
            str(checkpoint.checkpoint_type or "").strip() == "tool_permission"
            and str(checkpoint.project_id or "default").strip() == project_id
            and str(checkpoint.task_id or "").strip() == task_id
            and str(ownership.get("waiting_task_id", "") or "").strip()
            == task_id
            and str(ownership.get("tool_runtime_session_id", "") or "").strip()
            == runtime_session_id
            and str(recorded_claim.get("claim_id", "") or "").strip()
            == claim_id
            and str(recorded_claim.get("consumer_id", "") or "").strip()
            == consumer_id
            and str(permit.get("id", "") or "").strip() == tool_call_id
            and str(permit.get("function", "") or "").strip() == tool_name
            and dict(permit.get("arguments", {}) or {}) == arguments
            and dict(permit.get("execution_envelope", {}) or {})
            == dict(execution_envelope or {})
            and dict(permit.get("execution_identity", {}) or {})
            == dict(execution_identity or {})
            and str(permit.get("fingerprint", "") or "").strip()
            == fingerprint
            and str(permit.get("runtime_session_id", "") or "").strip()
            == runtime_session_id
            and str(permit.get("checkpoint_id", "") or "").strip()
            == str(checkpoint.checkpoint_id or "").strip()
            and str(permit.get("checkpoint_type", "") or "").strip()
            == "tool_permission"
            and str(permit.get("checkpoint_project_id", "") or "").strip()
            == project_id
            and str(permit.get("task_id", "") or "").strip() == task_id
            and str(permit.get("claim_id", "") or "").strip() == claim_id
            and str(permit.get("consumer_id", "") or "").strip()
            == consumer_id
            and str(checkpoint_call.get("id", "") or "").strip()
            == tool_call_id
            and str(checkpoint_call.get("name", "") or "").strip()
            == tool_name
            and dict(checkpoint_call.get("arguments", {}) or {}) == arguments
            and dict(checkpoint_call.get("execution_envelope", {}) or {})
            == dict(execution_envelope or {})
            and dict(checkpoint_call.get("execution_identity", {}) or {})
            == dict(execution_identity or {})
            and str(checkpoint_call.get("fingerprint", "") or "").strip()
            == fingerprint
            and str(
                checkpoint_call.get("runtime_session_id", "") or ""
            ).strip()
            == runtime_session_id
        )

    @classmethod
    def _merge_store_owned_task_runtime_ledger(
        cls,
        task: Task,
        *,
        persisted_context_snapshot: dict[str, Any],
        persisted_metadata: dict[str, Any],
    ) -> None:
        """Keep the exact runtime continuation ledger Store-authoritative.

        ``Task`` is intentionally a broad projection object and company-mode
        controllers keep instances alive while a resident runtime is waiting
        for an owner decision.  A decision consumer updates the exact ToolCall
        permit directly in SQLite.  A later ``save_task(stale_task)`` must not
        delete that permit (or resurrect one which the atomic ToolResult commit
        already consumed).

        Only the continuation identity and one-shot ledger are protected here;
        ordinary runtime audit/resume fields may still be refreshed by the
        execution owner.  New Task rows are unaffected because this helper is
        called only when an existing row was read under the same SQLite write
        transaction as the ensuing save.
        """

        incoming_context = dict(getattr(task, "context_snapshot", {}) or {})
        incoming_metadata = dict(getattr(task, "metadata", {}) or {})
        incoming_resume_raw = incoming_context.get("runtime_resume")
        incoming_runtime_raw = incoming_metadata.get("runtime_v2")
        incoming_resume = (
            dict(incoming_resume_raw)
            if isinstance(incoming_resume_raw, dict)
            else {}
        )
        incoming_runtime = (
            dict(incoming_runtime_raw)
            if isinstance(incoming_runtime_raw, dict)
            else {}
        )
        (
            persisted_resume,
            persisted_runtime,
            permits,
            continuation,
            persisted_runtime_id,
        ) = cls._canonicalize_task_runtime_tool_ledger(
            dict(persisted_context_snapshot or {}),
            dict(persisted_metadata or {}),
        )
        persisted_active = bool(permits) or continuation

        persisted_resume_id = str(
            persisted_resume.get("runtime_session_id", "") or ""
        ).strip()
        persisted_metadata_id = str(
            persisted_runtime.get("runtime_session_id", "") or ""
        ).strip()
        incoming_resume_id = str(
            incoming_resume.get("runtime_session_id", "") or ""
        ).strip()
        incoming_metadata_id = str(
            incoming_runtime.get("runtime_session_id", "") or ""
        ).strip()

        if persisted_active:
            # A live exact permit/continuation is the ownership fence.  A broad
            # Task projection may omit the id, but it may never name another
            # runtime while the Store-owned ledger is active.
            incoming_runtime_ids = {
                value
                for value in (incoming_resume_id, incoming_metadata_id)
                if value
            }
            if incoming_runtime_ids - {persisted_runtime_id}:
                raise RuntimeError(
                    "cannot replace a Task runtime while its exact ToolCall "
                    "ledger is active"
                )
            resulting_runtime_id = persisted_runtime_id
        else:
            # With no live ledger, top-level ids are audit/resume state.  Some
            # producers update only one authority, so distinguish the newly
            # changed id from the unchanged old id in the other view.  This also
            # lets a single explicit new id repair legacy persisted views which
            # already disagree with each other.
            changed_ids = {
                incoming_id
                for incoming_id, persisted_id in (
                    (incoming_resume_id, persisted_resume_id),
                    (incoming_metadata_id, persisted_metadata_id),
                )
                if incoming_id and incoming_id != persisted_id
            }
            incoming_ids = {
                value
                for value in (incoming_resume_id, incoming_metadata_id)
                if value
            }
            if len(changed_ids) > 1:
                raise RuntimeError(
                    "incoming Task has ambiguous replacement runtime identities"
                )
            if changed_ids:
                resulting_runtime_id = next(iter(changed_ids))
            elif len(incoming_ids) == 1:
                resulting_runtime_id = next(iter(incoming_ids))
            elif not incoming_ids:
                resulting_runtime_id = ""
            else:
                raise RuntimeError(
                    "incoming Task has conflicting runtime session identities"
                )

        cls._write_canonical_task_runtime_tool_ledger(
            incoming_context,
            incoming_metadata,
            runtime_resume=incoming_resume,
            runtime_metadata=incoming_runtime,
            permits=permits if persisted_active else {},
            continuation=continuation if persisted_active else False,
            runtime_session_id=resulting_runtime_id,
        )
        task.context_snapshot = incoming_context
        task.metadata = incoming_metadata

    async def _merge_store_owned_task_fields_before_save(
        self,
        task: Task,
        *,
        db: _SQLiteConnectionAdapter,
    ) -> None:
        """Merge Store-owned Task fields from the row locked by the caller."""

        async with db.execute(
            "SELECT context_snapshot, metadata FROM tasks WHERE id = ?",
            (str(getattr(task, "id", "") or ""),),
        ) as cursor:
            row = await cursor.fetchone()
        if row is None:
            # Broad Task persistence is not an ingress for exact ToolCall
            # authority.  A newly-created row (or a stale object saved after
            # deletion) may carry old runtime projections, but only the typed
            # checkpoint transaction may create permits/continuation work.
            context_snapshot = dict(getattr(task, "context_snapshot", {}) or {})
            metadata = dict(getattr(task, "metadata", {}) or {})
            runtime_resume = dict(context_snapshot.get("runtime_resume", {}) or {})
            runtime_metadata = dict(metadata.get("runtime_v2", {}) or {})
            top_level_runtime_ids = {
                str(value or "").strip()
                for value in (
                    runtime_resume.get("runtime_session_id"),
                    runtime_metadata.get("runtime_session_id"),
                )
                if str(value or "").strip()
            }
            if len(top_level_runtime_ids) > 1:
                raise RuntimeError(
                    "new Task has conflicting runtime session identities"
                )
            runtime_session_id = next(iter(top_level_runtime_ids), "")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits={},
                continuation=False,
                runtime_session_id=runtime_session_id,
            )
            # Canonicalization must scrub forged exact-ledger fields from a
            # new row, but it must not change an otherwise plain Task's JSON
            # shape by manufacturing empty runtime projections.  Retain any
            # genuine non-ledger runtime fields verbatim.
            for container, key in (
                (context_snapshot, "runtime_resume"),
                (context_snapshot, "runtime_v2"),
                (metadata, "runtime_v2"),
            ):
                if container.get(key) == {}:
                    container.pop(key, None)
            task.context_snapshot = context_snapshot
            task.metadata = metadata
            return
        self._merge_store_owned_task_runtime_ledger(
            task,
            persisted_context_snapshot=_json_loads(row[0], {}),
            persisted_metadata=_json_loads(row[1], {}),
        )

    async def _save_task_row(
        self,
        task: Task,
        *,
        commit: bool = True,
        db: _SQLiteConnectionAdapter | None = None,
    ) -> None:
        target_db = db or self._require_db()
        self._assert_project_write_scope(
            getattr(task, "project_id", None),
            operation="save_task",
            entity=f"task {getattr(task, 'id', '')!r}",
        )
        await self._merge_store_owned_task_fields_before_save(task, db=target_db)
        task.metadata = dict(task.metadata or {})
        if self._metadata_has_work_item_projection_identity(task.metadata):
            task.metadata, _ = migrate_work_item_projection_metadata(
                task.metadata,
                turn_type_fallback="",
            )
        await target_db.execute(
            """INSERT INTO tasks
            (id, session_id, parent_session_id, title, description, assigned_to, status, priority, dependencies,
             execution_lock, context_snapshot, assigned_external_agent, created_at,
             deadline, result, parent_id, project_id, tags, comments,
             retry_count, max_retries, metadata,
             org_id, goal_id, checkout_run_id, execution_locked_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                session_id=excluded.session_id,
                parent_session_id=excluded.parent_session_id,
                title=excluded.title,
                description=excluded.description,
                assigned_to=excluded.assigned_to,
                status=excluded.status,
                priority=excluded.priority,
                dependencies=excluded.dependencies,
                execution_lock=excluded.execution_lock,
                context_snapshot=excluded.context_snapshot,
                assigned_external_agent=excluded.assigned_external_agent,
                created_at=excluded.created_at,
                deadline=excluded.deadline,
                result=excluded.result,
                parent_id=excluded.parent_id,
                project_id=excluded.project_id,
                tags=excluded.tags,
                comments=excluded.comments,
                retry_count=excluded.retry_count,
                max_retries=excluded.max_retries,
                metadata=excluded.metadata,
                org_id=excluded.org_id,
                goal_id=excluded.goal_id,
                checkout_run_id=excluded.checkout_run_id,
                execution_locked_at=excluded.execution_locked_at""",
            (
                task.id,
                task.session_id,
                task.parent_session_id,
                task.title,
                task.description,
                task.assigned_to,
                task.status.value,
                task.priority,
                _json_dumps(task.dependencies),
                int(task.execution_lock),
                _json_dumps(task.context_snapshot),
                task.assigned_external_agent,
                task.created_at.isoformat(),
                task.deadline.isoformat() if task.deadline else None,
                _json_dumps(task.result) if task.result else None,
                task.parent_id,
                task.project_id,
                _json_dumps(task.tags),
                _json_dumps(task.comments),
                task.retry_count,
                task.max_retries,
                _json_dumps(task.metadata),
                task.org_id,
                task.goal_id,
                task.checkout_run_id,
                task.execution_locked_at.isoformat() if task.execution_locked_at else None,
            ),
        )
        if commit:
            await target_db.commit()

    async def save_task(self, task: Task) -> None:
        metadata = dict(getattr(task, "metadata", {}) or {})
        if bool(metadata.get("company_runtime_auxiliary_task", False)):
            await self.save_company_runtime_auxiliary_task(task)
            return
        if (
            str(metadata.get("_comms_endpoint_id", "") or "").strip()
            and str(getattr(task, "parent_id", "") or "").strip()
            and str(metadata.get("delegation_run_id", "") or "").strip()
        ):
            await self.save_company_runtime_subagent_task(task)
            return
        if str(metadata.get("company_run_controller_owner_token", "") or "").strip():
            await self.save_task_for_company_controller(task)
            return
        self._require_db()
        # A separate write transaction makes the current-row merge above and
        # the broad Task projection save indivisible with respect to exact
        # permit writers on this or another Store/Engine instance.
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            async with transaction_db.execute(
                """SELECT 1
                   FROM work_item_runtime_links AS link
                   JOIN delegation_work_items AS work_item
                     ON work_item.work_item_id = link.work_item_id
                   JOIN delegation_runs AS run
                     ON run.run_id = work_item.run_id
                   WHERE link.runtime_task_id = ?
                     AND run.controller_lease_generation > 0
                   LIMIT 1""",
                (str(getattr(task, "id", "") or "").strip(),),
            ) as controller_cursor:
                if await controller_cursor.fetchone() is not None:
                    raise CompanyRunControllerLeaseLost(
                        "live company runtime Task requires an explicit "
                        "run or attempt fence"
                    )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_company_runtime_subagent_task(self, task: Task) -> None:
        """Persist a native child only through its Store-owned parent chain."""

        self._require_db()
        metadata = dict(getattr(task, "metadata", {}) or {})
        run_id, owner_token, generation, attempt_seq = (
            self._company_controller_task_fence(task)
        )
        project_id = str(task.project_id or "default").strip() or "default"
        task_id = str(task.id or "").strip()
        parent_task_id = str(getattr(task, "parent_id", "") or "").strip()
        subagent_run_id = str(
            metadata.get("_comms_endpoint_id", "") or ""
        ).strip()
        if not all(
            (
                run_id,
                owner_token,
                generation > 0,
                attempt_seq > 0,
                task_id,
                parent_task_id,
                subagent_run_id,
            )
        ):
            raise CompanyRunControllerLeaseLost(
                "company native subagent Task lacks an exact parent attempt"
            )
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            async with transaction_db.execute(
                """SELECT 1 FROM runtime_subagent_runs
                   WHERE subagent_run_id = ? AND agent_id = ?
                     AND task_id = ? AND status = 'running'""",
                (subagent_run_id, subagent_run_id, parent_task_id),
            ) as cursor:
                if await cursor.fetchone() is None:
                    raise CompanyRunControllerLeaseLost(
                        "company native subagent has no durable running parent chain"
                    )
            async with transaction_db.execute(
                "SELECT metadata FROM tasks WHERE id = ? AND project_id = ?",
                (parent_task_id, project_id),
            ) as cursor:
                parent_row = await cursor.fetchone()
            if parent_row is None:
                raise CompanyRunControllerLeaseLost(
                    "company native subagent parent Task is unavailable"
                )
            parent_metadata = _json_loads(parent_row[0], {})
            if not (
                str(parent_metadata.get("delegation_run_id", "") or "").strip()
                == run_id
                and str(
                    parent_metadata.get("company_run_controller_owner_token", "")
                    or ""
                ).strip()
                == owner_token
                and int(
                    parent_metadata.get(
                        "company_run_controller_lease_generation",
                        0,
                    )
                    or 0
                )
                == generation
                and int(
                    parent_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                )
                == attempt_seq
            ):
                raise CompanyRunControllerLeaseLost(
                    "company native subagent copied credential is not its parent credential"
                )
            durable_parent = Task(
                id=parent_task_id,
                project_id=project_id,
                metadata=copy.deepcopy(parent_metadata),
            )
            async with transaction_db.execute(
                """SELECT work_item_id FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (parent_task_id,),
            ) as cursor:
                link_row = await cursor.fetchone()
            if link_row is None:
                raise CompanyRunControllerLeaseLost(
                    "company native subagent parent has no durable WorkItem"
                )
            set_linked_work_item_id(durable_parent, str(link_row[0] or ""))
            if not await self._company_controller_task_fence_matches(
                transaction_db,
                durable_parent,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "company native subagent parent attempt is no longer current"
                )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    @staticmethod
    def _company_controller_task_fence(
        task: Task,
    ) -> tuple[str, str, int, int]:
        metadata = dict(getattr(task, "metadata", {}) or {})
        run_id = str(metadata.get("delegation_run_id", "") or "").strip()
        owner_token = str(
            metadata.get("company_run_controller_owner_token", "") or ""
        ).strip()
        try:
            generation = int(
                metadata.get("company_run_controller_lease_generation", 0) or 0
            )
        except (TypeError, ValueError):
            generation = 0
        try:
            attempt_seq = int(
                metadata.get("claimed_work_item_attempt_seq", 0) or 0
            )
        except (TypeError, ValueError):
            attempt_seq = 0
        return run_id, owner_token, generation, attempt_seq

    @staticmethod
    def _task_has_company_attempt_credential(
        task_or_metadata: Task | dict[str, Any],
    ) -> bool:
        metadata = (
            dict(task_or_metadata)
            if isinstance(task_or_metadata, dict)
            else dict(getattr(task_or_metadata, "metadata", {}) or {})
        )
        try:
            generation = int(
                metadata.get(
                    "company_run_controller_lease_generation",
                    0,
                )
                or 0
            )
            attempt_seq = int(
                metadata.get("claimed_work_item_attempt_seq", 0) or 0
            )
        except (TypeError, ValueError):
            return True
        return bool(
            str(
                metadata.get("company_run_controller_owner_token", "") or ""
            ).strip()
            or generation != 0
            or attempt_seq != 0
        )

    async def _company_controller_task_fence_matches(
        self,
        db: _SQLiteConnectionAdapter,
        task: Task,
        *,
        checked_at: datetime,
    ) -> bool:
        """Validate one execution Task against the exact durable attempt.

        The caller must already hold a SQLite write transaction.  Keeping
        this read and the ensuing Task/WorkItem write on the same connection
        is the fence; a takeover cannot commit between validation and effect.
        """

        run_id, owner_token, generation, attempt_seq = (
            self._company_controller_task_fence(task)
        )
        project_id = str(task.project_id or "default").strip() or "default"
        if (
            not run_id
            or not owner_token
            or generation <= 0
            or attempt_seq <= 0
            or not str(task.id or "").strip()
        ):
            return False
        async with db.execute(
            """SELECT 1
               FROM work_item_runtime_links AS link
               JOIN delegation_work_items AS work_item
                 ON work_item.work_item_id = link.work_item_id
               JOIN delegation_runs AS run
                 ON run.run_id = work_item.run_id
                AND run.project_id = ?
               WHERE link.runtime_task_id = ?
                 AND work_item.run_id = ?
                 AND CAST(
                       COALESCE(json_extract(work_item.metadata, '$.attempt_seq'), 0)
                       AS INTEGER
                     ) = ?
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.claimed_task_id'), ''
                     ) IN ('', ?)
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.dispatch_hold'), ''
                     ) = ''
                 AND run.controller_owner_token = ?
                 AND run.controller_lease_generation = ?
                 AND run.controller_lease_expires_at > ?
               LIMIT 1""",
            (
                project_id,
                str(task.id or "").strip(),
                run_id,
                attempt_seq,
                str(task.id or "").strip(),
                owner_token,
                generation,
                checked_at.isoformat(),
            ),
        ) as cursor:
            return await cursor.fetchone() is not None

    async def _company_controller_active_effect_attempt_matches(
        self,
        db: _SQLiteConnectionAdapter,
        task: Task,
        *,
        checked_at: datetime,
    ) -> bool:
        """Require the exact actively claimed company WorkItem attempt.

        The general Task save fence deliberately accepts a few legacy claim
        projections.  An effect is stricter: once an attempt has settled or
        released either durable claim, its old coroutine must not mutate an
        artifact, execute an opaque ToolCall, or append another user turn even
        while the same controller still owns the run.
        """

        run_id, owner_token, generation, attempt_seq = (
            self._company_controller_task_fence(task)
        )
        task_id = str(task.id or "").strip()
        project_id = str(task.project_id or "default").strip() or "default"
        work_item_id = linked_work_item_id_for_task(task)
        task_metadata = dict(getattr(task, "metadata", {}) or {})
        role_session_id = str(
            task_metadata.get("delegation_role_session_id", "") or ""
        ).strip()
        seat_id = str(task_metadata.get("delegation_seat_id", "") or "").strip()
        if (
            not run_id
            or not owner_token
            or generation <= 0
            or attempt_seq <= 0
            or not task_id
            or not work_item_id
            or not role_session_id
            or not seat_id
        ):
            return False
        async with db.execute(
            """SELECT 1
               FROM work_item_runtime_links AS link
               JOIN delegation_work_items AS work_item
                 ON work_item.work_item_id = link.work_item_id
               JOIN delegation_runs AS run
                 ON run.run_id = work_item.run_id
                AND run.project_id = ?
               WHERE link.runtime_task_id = ?
                 AND link.work_item_id = ?
                 AND work_item.run_id = ?
                 AND work_item.phase = 'running'
                 AND CAST(
                       COALESCE(json_extract(work_item.metadata, '$.attempt_seq'), 0)
                       AS INTEGER
                     ) = ?
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.claimed_task_id'), ''
                     ) = ?
                 AND work_item.claimed_by_role_runtime_session_id = ?
                 AND work_item.claimed_by_seat_id = ?
                 AND CAST(
                       COALESCE(
                         json_extract(work_item.metadata, '$.attempt_settled'), 0
                       ) AS INTEGER
                     ) = 0
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.dispatch_hold'), ''
                     ) = ''
                 AND run.controller_owner_token = ?
                 AND run.controller_lease_generation = ?
                 AND run.controller_lease_expires_at > ?
               LIMIT 1""",
            (
                project_id,
                task_id,
                work_item_id,
                run_id,
                attempt_seq,
                task_id,
                role_session_id,
                seat_id,
                owner_token,
                generation,
                checked_at.isoformat(),
            ),
        ) as cursor:
            return await cursor.fetchone() is not None

    async def _company_controller_task_attempt_is_superseded(
        self,
        db: _SQLiteConnectionAdapter,
        task: Task,
        *,
        checked_at: datetime,
    ) -> bool:
        """Classify one exact stale-attempt tail under the caller's transaction.

        A higher durable ``attempt_seq`` is a local supersession only while all
        other authority and integrity fences still match: the exact run lease
        is current, the Task/WorkItem/run link is intact, the current attempt
        still names this Task, and no dispatch hold is installed.  Every other
        mismatch remains a run-controller lease loss and fails closed.
        """

        run_id, owner_token, generation, attempt_seq = (
            self._company_controller_task_fence(task)
        )
        project_id = str(task.project_id or "default").strip() or "default"
        task_id = str(task.id or "").strip()
        work_item_id = linked_work_item_id_for_task(task)
        if (
            not run_id
            or not owner_token
            or generation <= 0
            or attempt_seq <= 0
            or not task_id
            or not work_item_id
        ):
            return False
        async with db.execute(
            """SELECT 1
               FROM work_item_runtime_links AS link
               JOIN delegation_work_items AS work_item
                 ON work_item.work_item_id = link.work_item_id
               JOIN delegation_runs AS run
                 ON run.run_id = work_item.run_id
                AND run.project_id = ?
               WHERE link.runtime_task_id = ?
                 AND link.work_item_id = ?
                 AND work_item.run_id = ?
                 AND CAST(
                       COALESCE(json_extract(work_item.metadata, '$.attempt_seq'), 0)
                       AS INTEGER
                     ) > ?
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.claimed_task_id'), ''
                     ) = ?
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.dispatch_hold'), ''
                     ) = ''
                 AND run.controller_owner_token = ?
                 AND run.controller_lease_generation = ?
                 AND run.controller_lease_expires_at > ?
               LIMIT 1""",
            (
                project_id,
                task_id,
                work_item_id,
                run_id,
                attempt_seq,
                task_id,
                owner_token,
                generation,
                checked_at.isoformat(),
            ),
        ) as cursor:
            return await cursor.fetchone() is not None

    async def save_task_for_company_controller(self, task: Task) -> None:
        """Persist an execution Task only while its exact attempt owns the run.

        A dedicated SQLite transaction is intentional: company WorkItems run
        concurrently on one Store, while each transaction still needs an
        isolated connection.  ``BEGIN IMMEDIATE`` is the only serialization
        mechanism; there is no process-local lock that another Engine could
        bypass.
        """

        self._require_db()
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            if not await self._company_controller_task_fence_matches(
                transaction_db,
                task,
                checked_at=checked_at,
            ):
                if await self._company_controller_task_attempt_is_superseded(
                    transaction_db,
                    task,
                    checked_at=checked_at,
                ):
                    raise CompanyControllerAttemptSuperseded(
                        "older company WorkItem attempt cannot persist Task state"
                    )
                raise CompanyRunControllerLeaseLost(
                    "stale company controller cannot persist Task state"
                )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_unclaimed_runtime_task_projection_for_company_controller(
        self,
        task: Task,
        *,
        project_id: str,
        controller_owner_token: str,
        controller_lease_generation: int,
    ) -> None:
        """Persist a pre-claim Task projection under the live run lease.

        A materialized company Task deliberately has no attempt credential:
        the exact owner/generation/attempt triple is installed only after the
        WorkItem claim CAS wins.  Consequently it cannot use the normal
        attempt-scoped ``save_task_for_company_controller`` path.  This narrow
        command is the run-scheduler boundary for refreshing such a Task.  It
        accepts only the exact linked, unclaimed WorkItem projection and keeps
        lease validation and the broad Task row write in one SQLite write
        transaction.
        """

        self._require_db()
        clean_project_id = str(project_id or "default").strip() or "default"
        owner_token = str(controller_owner_token or "").strip()
        try:
            generation = int(controller_lease_generation or 0)
        except (TypeError, ValueError) as exc:
            raise CompanyRunControllerLeaseLost(
                "unclaimed runtime Task projection has a malformed "
                "run-controller generation"
            ) from exc
        task_id = str(getattr(task, "id", "") or "").strip()
        work_item_id = linked_work_item_id_for_task(task)
        if not owner_token or generation <= 0:
            raise CompanyRunControllerLeaseLost(
                "unclaimed runtime Task projection requires a complete "
                "run-controller lease"
            )
        if not task_id or not work_item_id:
            raise CompanyRunControllerLeaseLost(
                "unclaimed runtime Task projection requires an exact "
                "Task-to-WorkItem link"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            async with transaction_db.execute(
                "SELECT work_item_id FROM work_item_runtime_links "
                "WHERE runtime_task_id = ?",
                (task_id,),
            ) as link_cursor:
                link_rows = await link_cursor.fetchall()
            if [str(row[0] or "").strip() for row in link_rows] != [
                work_item_id
            ]:
                raise CompanyRunControllerLeaseLost(
                    "unclaimed runtime Task projection link is no longer exact"
                )

            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (work_item_id,),
            ) as item_cursor:
                item_row = await item_cursor.fetchone()
                persisted_work_item = (
                    self._row_to_delegation_work_item(
                        item_row,
                        item_cursor.description,
                    )
                    if item_row is not None
                    else None
                )
            durable_task = await self._get_task_unhydrated(
                task_id,
                db=transaction_db,
            )
            if persisted_work_item is None or durable_task is None:
                raise CompanyRunControllerLeaseLost(
                    "unclaimed runtime Task projection source disappeared"
                )

            run_id = str(persisted_work_item.run_id or "").strip()
            checked_at_datetime = datetime.now()
            checked_at = checked_at_datetime.isoformat()
            async with transaction_db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    run_id,
                    clean_project_id,
                    owner_token,
                    generation,
                    checked_at,
                ),
            ) as lease_cursor:
                if await lease_cursor.fetchone() is None:
                    raise CompanyRunControllerLeaseLost(
                        "unclaimed runtime Task projection has no live "
                        "run-controller lease"
                    )

            candidate_metadata = dict(getattr(task, "metadata", {}) or {})
            durable_metadata = dict(durable_task.metadata or {})
            work_item_metadata = dict(persisted_work_item.metadata or {})

            if self._task_has_company_attempt_credential(candidate_metadata):
                raise CompanyRunControllerLeaseLost(
                    "attempt-owned Task cannot use the unclaimed projection "
                    "boundary"
                )
            if self._task_has_company_attempt_credential(durable_metadata):
                # Benign claim race: the scheduler loaded an unclaimed Task
                # projection, then the dispatcher won the WorkItem claim and
                # persisted the exact current attempt before this projection
                # write acquired SQLite's lock.  The durable Task is newer and
                # must win.  Treating this same-controller advancement as a
                # run-lease loss cancels every sibling provider process and
                # leaves their cards RUNNING.  An exact fence check keeps the
                # no-op narrow; partial, foreign, expired, held, or superseded
                # credentials still fail closed below.
                if await self._company_controller_task_fence_matches(
                    transaction_db,
                    durable_task,
                    checked_at=checked_at_datetime,
                ):
                    await transaction_db.rollback()
                    return None
                raise CompanyRunControllerLeaseLost(
                    "durable Task gained an attempt credential before its "
                    "unclaimed projection save"
                )

            try:
                work_item_attempt_seq = int(
                    work_item_metadata.get("attempt_seq", 0) or 0
                )
            except (TypeError, ValueError) as exc:
                raise CompanyRunControllerLeaseLost(
                    "unclaimed WorkItem has an invalid attempt ledger"
                ) from exc
            if (
                str(
                    persisted_work_item.claimed_by_role_runtime_session_id
                    or ""
                ).strip()
                or str(persisted_work_item.claimed_by_seat_id or "").strip()
                or str(
                    work_item_metadata.get("claimed_by_role_session_id", "")
                    or ""
                ).strip()
                or str(
                    work_item_metadata.get("claimed_task_id", "") or ""
                ).strip()
                or str(work_item_metadata.get("dispatch_hold", "") or "").strip()
                or str(candidate_metadata.get("dispatch_hold", "") or "").strip()
                or str(durable_metadata.get("dispatch_hold", "") or "").strip()
                or (
                    work_item_attempt_seq > 0
                    and work_item_metadata.get("attempt_settled") is not True
                )
            ):
                raise CompanyRunControllerLeaseLost(
                    "claimed, held, or active-attempt WorkItem cannot accept "
                    "an unclaimed Task projection"
                )

            expected_projection_id = projection_id_for_work_item(
                persisted_work_item
            )
            candidate_role_id = str(
                candidate_metadata.get("work_item_role_id", "") or ""
            ).strip()
            durable_role_id = str(
                durable_metadata.get("work_item_role_id", "") or ""
            ).strip()
            candidate_seat_id = str(
                candidate_metadata.get("delegation_seat_id", "") or ""
            ).strip()
            durable_seat_id = str(
                durable_metadata.get("delegation_seat_id", "") or ""
            ).strip()
            expected_role_id = str(persisted_work_item.role_id or "").strip()
            expected_seat_id = str(persisted_work_item.seat_id or "").strip()
            expected_turn_type = canonical_work_item_turn_type_for_kind(
                persisted_work_item.kind,
                fallback="",
            )
            candidate_turn_type = work_item_turn_type_from_metadata(
                candidate_metadata,
                fallback="",
            )
            durable_turn_type = work_item_turn_type_from_metadata(
                durable_metadata,
                fallback="",
            )
            expected_status = task_status_for_phase(persisted_work_item.phase)
            derived_projection = candidate_metadata.get(
                "derived_work_item_projection"
            )
            derived = (
                dict(derived_projection)
                if isinstance(derived_projection, dict)
                else {}
            )
            if not (
                run_id
                and expected_projection_id
                and expected_role_id
                and expected_seat_id
                and expected_turn_type
                and (str(task.project_id or "default").strip() or "default")
                == clean_project_id
                and (
                    str(durable_task.project_id or "default").strip()
                    or "default"
                )
                == clean_project_id
                and str(candidate_metadata.get("delegation_run_id", "") or "").strip()
                == run_id
                and str(durable_metadata.get("delegation_run_id", "") or "").strip()
                == run_id
                and projection_id_for_task(task) == expected_projection_id
                and projection_id_for_task(durable_task)
                == expected_projection_id
                and candidate_role_id == expected_role_id
                and durable_role_id == expected_role_id
                and str(task.assigned_to or "").strip() == expected_role_id
                and str(durable_task.assigned_to or "").strip()
                == expected_role_id
                and candidate_seat_id == expected_seat_id
                and durable_seat_id == expected_seat_id
                and candidate_turn_type == expected_turn_type
                and durable_turn_type == expected_turn_type
                and task.status == expected_status
                and str(derived.get("work_item_id", "") or "").strip()
                == work_item_id
                and str(derived.get("projection_id", "") or "").strip()
                == expected_projection_id
                and str(derived.get("phase", "") or "").strip()
                == persisted_work_item.phase.value
                and str(derived.get("kind", "") or "").strip()
                == str(persisted_work_item.kind or "").strip()
            ):
                raise CompanyRunControllerLeaseLost(
                    "unclaimed runtime Task projection identity or phase "
                    "does not match its durable WorkItem"
                )

            await self._save_task_row(
                task,
                commit=False,
                db=transaction_db,
            )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_company_runtime_auxiliary_task(self, task: Task) -> None:
        """Persist one internal runtime Task beneath an owned WorkItem Task.

        Internal native turns such as the CEO pre-delivery assessment need a real
        Task row because NativeRuntimeV2's permission ledger is Store-owned.
        They are not WorkItems themselves, so they cannot use the primary
        WorkItem/Task attempt fence.  This narrower fence binds the auxiliary
        Task to an exact source Task, source attempt, live run controller, and
        the ``<source-task-id>::...`` runtime namespace in one transaction.
        """

        self._require_db()
        metadata = dict(getattr(task, "metadata", {}) or {})
        run_id, owner_token, generation, _ = self._company_controller_task_fence(
            task
        )
        project_id = str(task.project_id or "default").strip() or "default"
        task_id = str(task.id or "").strip()
        source_task_id = str(
            metadata.get("runtime_auxiliary_source_task_id", "") or ""
        ).strip()
        try:
            source_attempt_seq = int(
                metadata.get("runtime_auxiliary_source_attempt_seq", 0) or 0
            )
        except (TypeError, ValueError):
            source_attempt_seq = 0
        if (
            not bool(metadata.get("company_runtime_auxiliary_task", False))
            or not run_id
            or not owner_token
            or generation <= 0
            or not task_id
            or not source_task_id
            or source_attempt_seq <= 0
            or not task_id.startswith(f"{source_task_id}::")
            or str(getattr(task, "parent_id", "") or "").strip()
            != source_task_id
            or str(metadata.get("runtime_auxiliary_kind", "") or "").strip()
            not in {"role_prompt", "meeting_turn"}
        ):
            raise CompanyRunControllerLeaseLost(
                "company runtime auxiliary Task lacks an exact source attempt"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=run_id,
                project_id=project_id,
                owner_token=owner_token,
                generation=generation,
                checked_at=checked_at,
                task_id=task_id,
            )
            async with transaction_db.execute(
                """SELECT 1
                   FROM tasks AS source_task
                   JOIN work_item_runtime_links AS link
                     ON link.runtime_task_id = source_task.id
                   JOIN delegation_work_items AS work_item
                     ON work_item.work_item_id = link.work_item_id
                   WHERE source_task.id = ?
                     AND source_task.project_id = ?
                     AND json_extract(
                           source_task.metadata,
                           '$.delegation_run_id'
                         ) = ?
                     AND json_extract(
                           source_task.metadata,
                           '$.company_run_controller_owner_token'
                         ) = ?
                     AND CAST(
                           COALESCE(
                             json_extract(
                               source_task.metadata,
                               '$.company_run_controller_lease_generation'
                             ), 0
                           ) AS INTEGER
                         ) = ?
                     AND CAST(
                           COALESCE(
                             json_extract(
                               source_task.metadata,
                               '$.claimed_work_item_attempt_seq'
                             ), 0
                           ) AS INTEGER
                         ) = ?
                     AND work_item.run_id = ?
                     AND CAST(
                           COALESCE(
                             json_extract(work_item.metadata, '$.attempt_seq'),
                             0
                           ) AS INTEGER
                         ) = ?
                     AND COALESCE(
                           json_extract(
                             work_item.metadata,
                             '$.claimed_task_id'
                           ), ''
                         ) IN ('', ?)
                     AND COALESCE(
                           json_extract(work_item.metadata, '$.dispatch_hold'),
                           ''
                         ) = ''
                   LIMIT 1""",
                (
                    source_task_id,
                    project_id,
                    run_id,
                    owner_token,
                    generation,
                    source_attempt_seq,
                    run_id,
                    source_attempt_seq,
                    source_task_id,
                ),
            ) as cursor:
                source_is_current = await cursor.fetchone() is not None
            if not source_is_current:
                raise CompanyRunControllerLeaseLost(
                    "company runtime auxiliary Task lost its source WorkItem attempt"
                )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def settle_interrupted_generic_runtime_auxiliary_tasks(
        self,
        *,
        project_id: str,
    ) -> int:
        """Fail non-controller auxiliary runtimes left live across restart.

        Company auxiliary Tasks have a durable source-attempt/controller
        fence and are converged by controller takeover or shutdown.  Generic
        role-prompt and meeting Tasks have no such owner to resume them after
        a process disappears, so startup closes their Task and RuntimeV2
        projections together.  Transcript/event rows are intentionally left
        untouched for audit and this command is idempotent by its live-status
        predicates.
        """

        self._require_db()
        clean_project_id = str(project_id or "default").strip() or "default"
        live_task_statuses = (
            TaskStatus.PENDING.value,
            TaskStatus.RUNNING.value,
            TaskStatus.IDLE.value,
            TaskStatus.BLOCKED.value,
            TaskStatus.AWAITING_PEER.value,
            TaskStatus.AWAITING_MANAGER_REVIEW.value,
            TaskStatus.AWAITING_HUMAN.value,
            TaskStatus.AWAITING_REVIEW.value,
        )
        live_runtime_statuses = (
            "running",
            "starting",
            "working",
            "awaiting_human",
            "awaiting_review",
            "awaiting_peer",
        )
        task_status_placeholders = ", ".join("?" for _ in live_task_statuses)
        runtime_status_placeholders = ", ".join(
            "?" for _ in live_runtime_statuses
        )
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            async with transaction_db.execute(
                f"""SELECT id FROM tasks
                    WHERE project_id = ?
                      AND status IN ({task_status_placeholders})
                      AND json_extract(
                            metadata,
                            '$.runtime_auxiliary_task'
                          ) = 1
                      AND COALESCE(
                            json_extract(
                              metadata,
                              '$.company_runtime_auxiliary_task'
                            ), 0
                          ) != 1
                      AND json_extract(
                            metadata,
                            '$.runtime_auxiliary_kind'
                          ) IN ('role_prompt', 'meeting_turn')""",
                (clean_project_id, *live_task_statuses),
            ) as cursor:
                candidate_task_ids = [
                    str(row[0] or "").strip()
                    for row in await cursor.fetchall()
                    if str(row[0] or "").strip()
                ]
            if not candidate_task_ids:
                await transaction_db.commit()
                return 0

            candidate_placeholders = ", ".join(
                "?" for _ in candidate_task_ids
            )
            terminalized_at = datetime.now().isoformat()
            await transaction_db.execute(
                f"""UPDATE runtime_sessions
                    SET status = 'failed',
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.status', 'failed',
                            '$.runtime_auxiliary_terminal_reason',
                            'startup_interrupted',
                            '$.runtime_auxiliary_terminalized_at', ?
                        ),
                        updated_at = ?
                    WHERE project_id = ?
                      AND task_id IN ({candidate_placeholders})
                      AND lower(COALESCE(status, ''))
                          IN ({runtime_status_placeholders})""",
                (
                    terminalized_at,
                    terminalized_at,
                    clean_project_id,
                    *candidate_task_ids,
                    *live_runtime_statuses,
                ),
            )
            task_update = await transaction_db.execute(
                f"""UPDATE tasks
                    SET status = ?, execution_lock = 0,
                        execution_locked_at = NULL,
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.runtime_v2.status', 'failed',
                            '$.runtime_auxiliary_terminal_reason',
                            'startup_interrupted',
                            '$.runtime_auxiliary_terminalized_at', ?
                        )
                    WHERE project_id = ?
                      AND id IN ({candidate_placeholders})
                      AND status IN ({task_status_placeholders})
                      AND json_extract(
                            metadata,
                            '$.runtime_auxiliary_task'
                          ) = 1
                      AND COALESCE(
                            json_extract(
                              metadata,
                              '$.company_runtime_auxiliary_task'
                            ), 0
                          ) != 1
                      AND json_extract(
                            metadata,
                            '$.runtime_auxiliary_kind'
                          ) IN ('role_prompt', 'meeting_turn')""",
                (
                    TaskStatus.FAILED.value,
                    terminalized_at,
                    clean_project_id,
                    *candidate_task_ids,
                    *live_task_statuses,
                ),
            )
            settled = int(getattr(task_update, "rowcount", 0) or 0)
            await transaction_db.commit()
            return settled
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def _company_controller_attempt_context_matches(
        self,
        db: _SQLiteConnectionAdapter,
        context: CompanyControllerAttemptContext,
        *,
        checked_at: datetime,
    ) -> bool:
        """Validate an immutable attempt context inside a write transaction."""

        if not context.complete:
            return False
        async with db.execute(
            """SELECT 1
               FROM delegation_work_items AS work_item
               JOIN work_item_runtime_links AS link
                 ON link.work_item_id = work_item.work_item_id
                AND link.runtime_task_id = ?
               JOIN tasks AS task
                 ON task.id = link.runtime_task_id
                AND task.project_id = ?
               JOIN delegation_runs AS run
                 ON run.run_id = work_item.run_id
                AND run.project_id = task.project_id
               WHERE work_item.work_item_id = ?
                 AND work_item.run_id = ?
                 AND CAST(
                       COALESCE(json_extract(work_item.metadata, '$.attempt_seq'), 0)
                       AS INTEGER
                     ) = ?
                 AND COALESCE(
                       json_extract(work_item.metadata, '$.dispatch_hold'), ''
                     ) = ''
                 AND run.controller_owner_token = ?
                 AND run.controller_lease_generation = ?
                 AND run.controller_lease_expires_at > ?
               LIMIT 1""",
            (
                context.task_id,
                context.project_id,
                context.work_item_id,
                context.run_id,
                context.attempt_seq,
                context.owner_token,
                context.generation,
                checked_at.isoformat(),
            ),
        ) as cursor:
            return await cursor.fetchone() is not None

    async def _controller_task_snapshot_envelope_matches(
        self,
        db: _SQLiteConnectionAdapter,
        context: CompanyControllerAttemptContext,
        snapshot: Task,
    ) -> bool:
        """Require source replacement to match the exact durable attempt."""

        snapshot_metadata = dict(snapshot.metadata or {})
        try:
            snapshot_generation = int(
                snapshot_metadata.get(
                    "company_run_controller_lease_generation", 0
                )
                or 0
            )
            snapshot_attempt = int(
                snapshot_metadata.get("claimed_work_item_attempt_seq", 0)
                or 0
            )
        except (TypeError, ValueError):
            return False
        return bool(
            str(snapshot.id or "").strip() == context.task_id
            and (str(snapshot.project_id or "default").strip() or "default")
            == context.project_id
            and str(
                snapshot_metadata.get("delegation_run_id", "") or ""
            ).strip()
            == context.run_id
            and str(
                snapshot_metadata.get(
                    "company_run_controller_owner_token", ""
                )
                or ""
            ).strip()
            == context.owner_token
            and snapshot_generation == context.generation
            and snapshot_attempt == context.attempt_seq
            and projection_id_for_task(snapshot)
            and await self._company_controller_task_fence_matches(
                db,
                snapshot,
                checked_at=datetime.now(),
            )
        )

    @staticmethod
    def _delegation_work_item_insert_values(
        item: DelegationWorkItem,
    ) -> tuple[Any, ...]:
        return (
            item.work_item_id,
            item.run_id,
            item.cell_id,
            item.team_instance_id,
            item.team_id,
            item.role_id,
            item.seat_id,
            item.seat_state_id,
            item.role_runtime_session_id,
            item.parent_work_item_id,
            item.source_role_id,
            item.source_seat_id,
            item.title,
            item.summary,
            item.kind,
            item.projection_id,
            item.phase.value,
            item.batch_id,
            int(item.batch_index or 0),
            item.deliverable_summary,
            item.blocked_reason,
            item.handoff_status,
            item.continuation_source,
            item.manager_role_id,
            item.manager_seat_id,
            item.claimed_by_role_runtime_session_id,
            item.claimed_by_seat_id,
            _json_dumps(item.metadata),
            item.created_at.isoformat(),
            item.updated_at.isoformat(),
        )

    @classmethod
    def _protect_delegate_work_identity(
        cls,
        item: DelegationWorkItem,
        *,
        existing: DelegationWorkItem | None,
    ) -> None:
        """Seal delegate-work identity outside the atomic append boundary.

        The marker, invocation identity, and durable sibling sequence are
        assigned only by ``append_delegated_work_items_atomically``.  Generic
        writers may update every other part of a delegated WorkItem, but they
        cannot create these reserved keys, change their sequence scope, or
        erase them with a stale whole-object save.
        """

        metadata = dict(item.metadata or {})
        reserved = cls._DELEGATE_WORK_RESERVED_METADATA_KEYS
        if existing is None:
            supplied = [key for key in reserved if key in metadata]
            if supplied:
                raise ValueError(
                    "delegate_work reserved metadata may only be created by "
                    "the atomic append API: " + ", ".join(supplied)
                )
            item.metadata = metadata
            return

        existing_metadata = dict(existing.metadata or {})
        existing_is_delegate = (
            existing_metadata.get("created_by_delegate_work") is True
        )
        if not existing_is_delegate:
            introduced = [
                key
                for key in reserved
                if key in metadata and key not in existing_metadata
            ]
            changed = [
                key
                for key in reserved
                if key in metadata
                and key in existing_metadata
                and metadata.get(key) != existing_metadata.get(key)
            ]
            if introduced or changed:
                raise ValueError(
                    "generic WorkItem writes cannot add or change "
                    "delegate_work reserved metadata: "
                    + ", ".join([*introduced, *changed])
                )
            item.metadata = metadata
            return

        missing_authority = [
            key for key in reserved if key not in existing_metadata
        ]
        if missing_authority:
            raise RuntimeError(
                "persisted delegate_work item lacks reserved identity: "
                + ", ".join(missing_authority)
            )
        changed_scope = [
            field_name
            for field_name in cls._DELEGATE_WORK_SEQUENCE_SCOPE_FIELDS
            if str(getattr(item, field_name, "") or "").strip()
            != str(getattr(existing, field_name, "") or "").strip()
        ]
        if changed_scope:
            raise ValueError(
                "delegate_work sequence scope is immutable: "
                + ", ".join(changed_scope)
            )
        # A whitespace-only spelling difference is semantically the same
        # scope, but writing that raw value would split later exact SQLite
        # lookups from the sequence allocator.  Preserve the byte-exact
        # persisted scope after validation so stale broad saves cannot drift
        # the allocator namespace.
        for field_name in cls._DELEGATE_WORK_SEQUENCE_SCOPE_FIELDS:
            setattr(
                item,
                field_name,
                copy.deepcopy(getattr(existing, field_name)),
            )
        conflicts = [
            key
            for key in reserved
            if key in metadata
            and metadata.get(key) != existing_metadata.get(key)
        ]
        if conflicts:
            raise ValueError(
                "delegate_work reserved metadata is immutable: "
                + ", ".join(conflicts)
            )
        for key in reserved:
            metadata[key] = copy.deepcopy(existing_metadata[key])
        item.metadata = metadata

    async def _mutate_delegation_run_lifecycle_for_controller(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str | None,
        owner_token: str,
        generation: int,
        mutation: CompanyControllerRunLifecycleMutation,
        checked_at: datetime,
    ) -> CompanyControllerRunLifecycleResult:
        """Apply one run delta using the caller's open write transaction."""

        async with db.execute(
            "SELECT * FROM delegation_runs WHERE run_id = ?",
            (run_id,),
        ) as cursor:
            row = await cursor.fetchone()
            current = (
                self._row_to_delegation_run(row, cursor.description)
                if row is not None
                else None
            )
        expected_root = str(root_session_id or "").strip()
        if (
            current is None
            or str(current.project_id or "default").strip() != project_id
            or (expected_root and str(current.session_id or "").strip() != expected_root)
            or str(current.controller_owner_token or "").strip() != owner_token
            or int(current.controller_lease_generation or 0) != int(generation)
            or current.controller_lease_expires_at is None
            or current.controller_lease_expires_at <= checked_at
        ):
            raise CompanyRunControllerLeaseLost(
                "stale company controller cannot mutate DelegationRun lifecycle"
            )
        async with db.execute(
            """SELECT 1 FROM delegation_work_items
               WHERE run_id = ?
                 AND COALESCE(json_extract(metadata, '$.dispatch_hold'), '') != ''
               LIMIT 1""",
            (run_id,),
        ) as cursor:
            if await cursor.fetchone() is not None:
                raise CompanyRunControllerLeaseLost(
                    "suspended company runtime rejects lifecycle tail writes"
                )
        if mutation.expected_statuses and str(current.status or "") not in set(
            mutation.expected_statuses
        ):
            return CompanyControllerRunLifecycleResult(applied=False, run=current)
        if (
            mutation.expected_lifecycle_statuses
            and str(current.lifecycle_status or "")
            not in set(mutation.expected_lifecycle_statuses)
        ):
            return CompanyControllerRunLifecycleResult(applied=False, run=current)
        if (
            mutation.expected_current_revision is not None
            and int(current.current_revision or 0)
            != int(mutation.expected_current_revision)
        ):
            return CompanyControllerRunLifecycleResult(applied=False, run=current)
        if (
            mutation.expected_updated_at is not None
            and current.updated_at != mutation.expected_updated_at
        ):
            return CompanyControllerRunLifecycleResult(applied=False, run=current)

        updated = copy.deepcopy(current)
        if mutation.status is not None:
            updated.status = str(mutation.status or "").strip()
        if mutation.lifecycle_status is not None:
            updated.lifecycle_status = str(
                mutation.lifecycle_status or ""
            ).strip()
        if mutation.latest_deliverable_summary is not None:
            updated.latest_deliverable_summary = str(
                mutation.latest_deliverable_summary or ""
            ).strip()
        metadata = dict(updated.metadata or {})
        metadata.update(copy.deepcopy(dict(mutation.metadata_updates or {})))
        for key in mutation.metadata_unset:
            metadata.pop(str(key), None)
        updated.metadata = metadata
        updated.updated_at = checked_at
        cursor = await db.execute(
            """UPDATE delegation_runs
               SET status = ?, lifecycle_status = ?,
                   latest_deliverable_summary = ?, metadata = ?, updated_at = ?
               WHERE run_id = ? AND project_id = ? AND session_id = ?
                 AND status = ? AND lifecycle_status = ?
                 AND current_revision = ? AND updated_at = ?
                 AND controller_owner_token = ?
                 AND controller_lease_generation = ?
                 AND controller_lease_expires_at > ?
                 AND NOT EXISTS (
                     SELECT 1 FROM delegation_work_items AS held
                     WHERE held.run_id = delegation_runs.run_id
                       AND COALESCE(
                           json_extract(held.metadata, '$.dispatch_hold'), ''
                       ) != ''
                 )""",
            (
                updated.status,
                updated.lifecycle_status,
                updated.latest_deliverable_summary,
                _json_dumps(updated.metadata),
                updated.updated_at.isoformat(),
                run_id,
                project_id,
                current.session_id,
                current.status,
                current.lifecycle_status,
                int(current.current_revision or 1),
                current.updated_at.isoformat(),
                owner_token,
                int(generation),
                checked_at.isoformat(),
            ),
        )
        if int(getattr(cursor, "rowcount", 0) or 0) != 1:
            raise CompanyRunControllerLeaseLost(
                "company run lifecycle fence changed during mutation"
            )
        return CompanyControllerRunLifecycleResult(applied=True, run=updated)

    async def _load_delivery_origin_authority_from_run(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        context: CompanyControllerAttemptContext,
    ) -> tuple[bool, OriginOwnerInteractionLease | None]:
        """Load the run-authoritative origin for a final owner publication.

        A missing (or explicit null) metadata field is the legacy no-origin
        shape.  Any present value must be one complete typed lease.  Parsing
        happens after ``BEGIN IMMEDIATE`` so a stale Task cannot downgrade an
        origin-backed run into the legacy final-delivery path.
        """

        async with db.execute(
            "SELECT metadata FROM delegation_runs WHERE run_id = ? AND project_id = ?",
            (context.run_id, context.project_id),
        ) as cursor:
            run_row = await cursor.fetchone()
        if run_row is None:
            return False, None

        raw_metadata = run_row[0]
        if raw_metadata in (None, ""):
            metadata: Any = {}
        else:
            try:
                metadata = (
                    json.loads(raw_metadata)
                    if isinstance(raw_metadata, str)
                    else raw_metadata
                )
            except (TypeError, ValueError, json.JSONDecodeError):
                return False, None
        if not isinstance(metadata, dict):
            return False, None
        if "origin_owner_interaction" not in metadata:
            return True, None

        raw_origin = metadata.get("origin_owner_interaction")
        if raw_origin is None:
            return True, None
        try:
            origin = OriginOwnerInteractionLease.from_payload(raw_origin)
        except (TypeError, ValueError):
            return False, None
        if origin is None:
            return False, None
        return True, origin

    async def _resolve_origin_owner_interaction_for_delivery(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        context: CompanyControllerAttemptContext,
        origin: OriginOwnerInteractionLease,
        resolved_at: datetime,
    ) -> bool:
        """Fence the owner decision that admitted this company run.

        The caller already owns ``BEGIN IMMEDIATE``.  A live origin must still
        be the exact executing claim carried by the durable run, WorkItem and
        Task.  It is resolved here, before the next owner card is published in
        that same transaction.  A terminal origin is an accepted recovery
        shape: startup may have conservatively marked an expired executing
        decision ``outcome_unknown`` while a separately suspended company run
        is later resumed by a new controller generation.
        """

        expected_origin = origin.to_payload()

        # The argument is only a request.  Bind it back to every durable
        # execution envelope so a forged or stale Task copy cannot close an
        # unrelated owner decision.
        durable_origins: list[Any] = []
        async with db.execute(
            "SELECT metadata FROM tasks WHERE id = ? AND project_id = ?",
            (context.task_id, context.project_id),
        ) as cursor:
            task_row = await cursor.fetchone()
        if task_row is None:
            return False
        durable_origins.append(
            _json_loads(task_row[0], {}).get("origin_owner_interaction")
        )
        async with db.execute(
            "SELECT metadata FROM delegation_runs WHERE run_id = ? AND project_id = ?",
            (context.run_id, context.project_id),
        ) as cursor:
            run_row = await cursor.fetchone()
        if run_row is None:
            return False
        durable_origins.append(
            _json_loads(run_row[0], {}).get("origin_owner_interaction")
        )
        async with db.execute(
            """SELECT metadata FROM delegation_work_items
               WHERE work_item_id = ? AND run_id = ?""",
            (context.work_item_id, context.run_id),
        ) as cursor:
            work_item_row = await cursor.fetchone()
        if work_item_row is None:
            return False
        durable_origins.append(
            _json_loads(work_item_row[0], {}).get(
                "origin_owner_interaction"
            )
        )
        if any(value != expected_origin for value in durable_origins):
            return False

        checkpoint = await self._select_execution_checkpoint(
            origin.checkpoint_id,
            project_id=origin.project_id,
            checkpoint_type=origin.checkpoint_type,
            db=db,
        )
        if checkpoint is None:
            return False
        payload = dict(checkpoint.payload or {})
        interaction = self._execution_checkpoint_interaction(payload)
        decision = interaction.get("decision")
        immutable_identity_present = bool(
            str(interaction.get("kind", "") or "").strip()
            == origin.checkpoint_type
            and str(interaction.get("domain_key", "") or "").strip()
            and isinstance(decision, dict)
            and str(decision.get("request_id", "") or "").strip()
            and str(decision.get("decision_hash", "") or "").strip()
            and "value" in decision
        )
        if not immutable_identity_present:
            return False

        status = str(checkpoint.status or "").strip()
        nonterminal = {"pending", "answered", "consuming", "resuming"}
        if status != "consuming":
            # Recovery may terminalize the decision independently of the
            # durable company scope.  It is no longer part of the active owner
            # frontier and must not prevent that scope's eventual delivery.
            terminal_statuses = {
                "resolved",
                "outcome_unknown",
                "invalid",
                "failed",
                "cancelled",
                "canceled",
                "stale",
                "superseded",
                "ignored",
                "expired",
                "timeout",
                "timed_out",
            }
            completion = dict(interaction.get("completion", {}) or {})
            return bool(
                status not in nonterminal
                and status in terminal_statuses
                and str(completion.get("claim_id", "") or "")
                == origin.claim_id
                and str(completion.get("consumer_id", "") or "")
                == origin.consumer_id
                and str(completion.get("final_status", "") or "") == status
            )

        claim = dict(interaction.get("claim", {}) or {})
        execution = dict(interaction.get("execution", {}) or {})
        if not (
            str(claim.get("claim_id", "") or "") == origin.claim_id
            and str(claim.get("consumer_id", "") or "")
            == origin.consumer_id
            and str(execution.get("state", "") or "") == "executing"
            and str(execution.get("claim_id", "") or "")
            == origin.claim_id
            and str(execution.get("consumer_id", "") or "")
            == origin.consumer_id
        ):
            return False

        now_text = resolved_at.isoformat()
        interaction["completion"] = {
            "claim_id": origin.claim_id,
            "consumer_id": origin.consumer_id,
            "finished_at": now_text,
            "final_status": "resolved",
        }
        interaction["execution"] = {
            **execution,
            "state": "resolved",
            "finished_at": now_text,
        }
        payload["interaction"] = interaction
        payload["interaction_result"] = {
            "message": "Company execution reached final delivery."
        }
        cursor = await db.execute(
            """UPDATE execution_checkpoints
               SET status = 'resolved', payload = ?, updated_at = ?
               WHERE checkpoint_id = ? AND project_id = ?
                 AND checkpoint_type = ? AND status = 'consuming'
                 AND json_extract(payload, '$.interaction.claim.claim_id') = ?
                 AND json_extract(payload, '$.interaction.claim.consumer_id') = ?
                 AND json_extract(payload, '$.interaction.execution.state') = 'executing'
                 AND json_extract(payload, '$.interaction.execution.claim_id') = ?
                 AND json_extract(payload, '$.interaction.execution.consumer_id') = ?""",
            (
                _json_dumps(payload),
                now_text,
                origin.checkpoint_id,
                origin.project_id,
                origin.checkpoint_type,
                origin.claim_id,
                origin.consumer_id,
                origin.claim_id,
                origin.consumer_id,
            ),
        )
        return int(getattr(cursor, "rowcount", 0) or 0) == 1

    async def _company_work_item_gate_runtime_scope_matches(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        payload: dict[str, Any],
        source_task: Task,
        run_id: str,
        source_projection_id: str,
    ) -> bool:
        """Bind a gate's serialized runtime snapshot to durable run Tasks."""

        payload_plan = payload.get("company_work_item_plan")
        durable_plan = dict(source_task.metadata or {}).get(
            "company_work_item_plan"
        )
        if (
            not isinstance(payload_plan, dict)
            or not payload_plan
            or not isinstance(durable_plan, dict)
            or not durable_plan
            or payload_plan != durable_plan
        ):
            return False
        parsed_plan = deserialize_company_work_item_plan(payload_plan)
        projection_ids = set(parsed_plan.projection_by_id())
        if (
            not projection_ids
            or len(parsed_plan.projections) != len(projection_ids)
            or str(parsed_plan.root_projection_id or "").strip()
            not in projection_ids
            or not source_projection_id
            or source_projection_id not in projection_ids
        ):
            return False
        for projection in parsed_plan.projections:
            clean_projection_id = str(projection.projection_id or "").strip()
            dependency_ids = {
                str(item or "").strip()
                for item in projection.dependency_projection_ids
                if str(item or "").strip()
            }
            if (
                clean_projection_id in dependency_ids
                or not dependency_ids.issubset(projection_ids)
            ):
                return False
        if any(
            not str(dependency.projection_id or "").strip()
            or not str(dependency.dependency_projection_id or "").strip()
            or str(dependency.projection_id or "").strip()
            == str(dependency.dependency_projection_id or "").strip()
            or str(dependency.projection_id or "").strip()
            not in projection_ids
            or str(dependency.dependency_projection_id or "").strip()
            not in projection_ids
            for dependency in parsed_plan.dependencies
        ):
            return False
        gate_policy = WorkItemGatePolicy.from_dict(
            dict(payload.get("gate", {}) or {})
        )
        if gate_policy is None:
            return False
        if gate_policy.on_reject == "rework":
            pending_harness = dict(
                dict(source_task.metadata or {}).get(
                    "gate_harness_pending_decision", {}
                )
                or {}
            )
            target_projection_ids = company_gate_rework_target_projection_ids(
                gate_policy,
                pending_harness_decision=pending_harness,
            )
            raw_harness_targets = list(
                pending_harness.get("target_projection_ids", []) or []
            )
            clean_raw_harness_targets = [
                str(item or "").strip()
                for item in raw_harness_targets
                if str(item or "").strip()
            ]
            if (
                not target_projection_ids
                or any(
                    target not in projection_ids
                    for target in target_projection_ids
                )
                or (
                    raw_harness_targets
                    and len(clean_raw_harness_targets)
                    != len(set(clean_raw_harness_targets))
                )
            ):
                return False
        raw_task_ids = payload.get("task_ids")
        if not isinstance(raw_task_ids, list):
            return False
        task_ids = [str(item or "").strip() for item in raw_task_ids]
        if (
            not task_ids
            or any(not item for item in task_ids)
            or len(set(task_ids)) != len(task_ids)
            or str(source_task.id or "").strip() not in task_ids
        ):
            return False
        scoped_projection_ids: set[str] = set()
        projection_by_id = parsed_plan.projection_by_id()
        for task_id in task_ids:
            scoped_task = await self._get_task_unhydrated(task_id, db=db)
            scoped_task_metadata = dict(
                (scoped_task.metadata if scoped_task else {}) or {}
            )
            scoped_projection_id = work_item_projection_id_from_metadata(
                scoped_task_metadata,
                fallback="",
            )
            if (
                scoped_task is None
                or (str(scoped_task.project_id or "default").strip() or "default")
                != (str(source_task.project_id or "default").strip() or "default")
                or str(
                    dict(scoped_task.metadata or {}).get(
                        "delegation_run_id", ""
                    )
                    or ""
                ).strip()
                != run_id
                or not scoped_projection_id
                or scoped_projection_id in scoped_projection_ids
            ):
                return False
            async with db.execute(
                """SELECT work_item.*
                   FROM work_item_runtime_links AS link
                   JOIN delegation_work_items AS work_item
                     ON work_item.work_item_id = link.work_item_id
                   WHERE link.runtime_task_id = ?""",
                (task_id,),
            ) as cursor:
                scoped_link_rows = await cursor.fetchall()
                scoped_link_description = cursor.description
            scoped_item = (
                self._row_to_delegation_work_item(
                    scoped_link_rows[0], scoped_link_description
                )
                if len(scoped_link_rows) == 1
                else None
            )
            projection_spec = projection_by_id.get(scoped_projection_id)
            expected_dependency_ids = [
                str(item or "").strip()
                for item in list(
                    getattr(
                        projection_spec,
                        "dependency_projection_ids",
                        (),
                    )
                    if projection_spec is not None
                    else ()
                )
                if str(item or "").strip()
            ]
            task_dependency_ids = [
                str(item or "").strip()
                for item in list(scoped_task.dependencies or ())
                if str(item or "").strip()
            ] if scoped_task is not None else []
            task_role_id = str(
                getattr(scoped_task, "assigned_to", "")
                or scoped_task_metadata.get("work_item_role_id", "")
                or ""
            ).strip()
            task_seat_id = str(
                scoped_task_metadata.get("delegation_seat_id")
                or scoped_task_metadata.get("seat_id")
                or ""
            ).strip()
            if (
                scoped_item is None
                or projection_spec is None
                or str(scoped_item.run_id or "").strip() != run_id
                or str(scoped_item.projection_id or "").strip()
                != scoped_projection_id
                or work_item_turn_type_from_metadata(
                    scoped_task_metadata,
                    fallback="",
                )
                != canonical_work_item_turn_type_for_kind(
                    scoped_item.kind,
                    fallback="",
                )
                or canonical_work_item_turn_type_for_kind(
                    projection_spec.turn_type,
                    fallback="",
                )
                != canonical_work_item_turn_type_for_kind(
                    scoped_item.kind,
                    fallback="",
                )
                or (
                    str(projection_spec.role_id or "").strip()
                    and str(projection_spec.role_id or "").strip()
                    != str(scoped_item.role_id or "").strip()
                )
                or (
                    str(projection_spec.seat_id or "").strip()
                    and str(projection_spec.seat_id or "").strip()
                    != str(scoped_item.seat_id or "").strip()
                )
                or not task_role_id
                or task_role_id != str(scoped_item.role_id or "").strip()
                or task_role_id != str(projection_spec.role_id or "").strip()
                or (
                    bool(str(scoped_item.seat_id or "").strip())
                    != bool(task_seat_id)
                )
                or (
                    task_seat_id
                    and task_seat_id
                    != str(scoped_item.seat_id or "").strip()
                )
                or (
                    task_seat_id
                    and task_seat_id
                    != str(projection_spec.seat_id or "").strip()
                )
                or task_dependency_ids != expected_dependency_ids
            ):
                return False
            scoped_projection_ids.add(scoped_projection_id)
        return scoped_projection_ids == projection_ids

    async def validate_company_work_item_gate_runtime_scope(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
    ) -> bool:
        """Validate a persisted gate continuation's complete runtime scope.

        Recovery calls this immediately before admitting a dispatcher so a
        post-commit unlink/relink cannot turn a stale serialized Task set into
        executable authority.
        """

        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        if not clean_checkpoint_id:
            return False
        db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await db.execute("BEGIN")
            checkpoint = await self._select_execution_checkpoint(
                clean_checkpoint_id,
                project_id=clean_project_id,
                checkpoint_type="company_work_item_gate",
                db=db,
            )
            if checkpoint is None or checkpoint.status not in {
                "resolved",
                "invalid",
            }:
                await db.rollback()
                return False
            payload = dict(checkpoint.payload or {})
            completion = dict(
                payload.get(
                    "company_work_item_gate_decision_completion", {}
                )
                or {}
            )
            task_id = str(
                completion.get("task_id")
                or payload.get("waiting_task_id")
                or checkpoint.task_id
                or ""
            ).strip()
            run_id = str(
                completion.get("run_id") or payload.get("run_id") or ""
            ).strip()
            source_task = await self._get_task_unhydrated(task_id, db=db)
            matches = bool(
                source_task is not None
                and source_task.project_id == clean_project_id
                and _company_work_item_gate_publication_provenance_matches(
                    payload
                )
                and str(
                    dict(
                        payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("checkpoint_id", "")
                    or ""
                ).strip()
                == checkpoint.checkpoint_id
                and str(
                    dict(
                        payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("project_id", "")
                    or ""
                ).strip()
                == clean_project_id
                and str(checkpoint.task_id or "").strip() == task_id
                and str(payload.get("waiting_task_id", "") or "").strip()
                == task_id
                and str(completion.get("task_id", "") or "").strip()
                == task_id
                and str(payload.get("run_id", "") or "").strip() == run_id
                and str(completion.get("run_id", "") or "").strip()
                == run_id
                and await self._company_work_item_gate_runtime_scope_matches(
                    db,
                    payload=payload,
                    source_task=source_task,
                    run_id=run_id,
                    source_projection_id=projection_id_for_task(source_task),
                )
            )
            await db.rollback()
            return matches
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

    async def get_company_work_item_gate_publication_provenance(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
    ) -> dict[str, Any] | None:
        """Return only a hash-valid Store-owned gate publication identity."""

        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        if not clean_checkpoint_id:
            return None
        checkpoint = await self.get_execution_checkpoint(
            clean_checkpoint_id,
            project_id=clean_project_id,
            checkpoint_type="company_work_item_gate",
        )
        if checkpoint is None:
            return None
        payload = dict(checkpoint.payload or {})
        provenance = dict(
            payload.get(
                COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                {},
            )
            or {}
        )
        if not (
            _company_work_item_gate_publication_provenance_matches(payload)
            and str(provenance.get("checkpoint_id", "") or "").strip()
            == clean_checkpoint_id
            and str(provenance.get("project_id", "") or "").strip()
            == clean_project_id
        ):
            return None
        return copy.deepcopy(provenance)

    async def reconcile_orphaned_company_work_item_gate_waits_for_controller(
        self,
        run_id: str,
        *,
        project_id: str,
        owner_token: str,
        generation: int,
    ) -> tuple[ExecutionCheckpoint, ...]:
        """Fail exact parked gate waits whose owner decision cannot run.

        This startup-only repair is deliberately narrow: the durable
        Task↔WorkItem link, run, settled attempt, projection, gate provenance,
        and lack of any other active owner card must all agree.  It converts
        only terminal-invalid gates, or ANSWERED gates whose full runtime scope
        is no longer valid, into a controller-fenced FAILED source plus a
        durable failure-settlement continuation.
        """

        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_owner_token = str(owner_token or "").strip()
        try:
            clean_generation = int(generation)
        except (TypeError, ValueError):
            clean_generation = 0
        if not clean_run_id or not clean_owner_token or clean_generation <= 0:
            return ()

        db = _SQLiteConnectionAdapter(self.db_path)
        repaired: list[ExecutionCheckpoint] = []
        transitioned: list[tuple[Phase, DelegationWorkItem]] = []
        try:
            await db.execute("BEGIN IMMEDIATE")
            repaired_at = datetime.now()
            async with db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_owner_token,
                    clean_generation,
                    repaired_at.isoformat(),
                ),
            ) as run_cursor:
                if await run_cursor.fetchone() is None:
                    raise CompanyRunControllerLeaseLost(
                        "stale controller cannot repair orphaned gate waits"
                    )
            async with db.execute(
                """SELECT work_item.work_item_id, link.runtime_task_id
                   FROM delegation_work_items AS work_item
                   JOIN work_item_runtime_links AS link
                     ON link.work_item_id = work_item.work_item_id
                   JOIN tasks AS task
                     ON task.id = link.runtime_task_id
                    AND task.project_id = ?
                   WHERE work_item.run_id = ?
                     AND work_item.phase = ?
                     AND task.status = ?""",
                (
                    clean_project_id,
                    clean_run_id,
                    Phase.AWAITING_HUMAN.value,
                    TaskStatus.AWAITING_HUMAN.value,
                ),
            ) as candidate_cursor:
                source_rows = await candidate_cursor.fetchall()

            for raw_work_item_id, raw_task_id in source_rows:
                work_item_id = str(raw_work_item_id or "").strip()
                task_id = str(raw_task_id or "").strip()
                task = await self._get_task_unhydrated(task_id, db=db)
                async with db.execute(
                    "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                    (work_item_id,),
                ) as item_cursor:
                    item_row = await item_cursor.fetchone()
                    item = (
                        self._row_to_delegation_work_item(
                            item_row, item_cursor.description
                        )
                        if item_row is not None
                        else None
                    )
                if task is None or item is None:
                    continue
                task_metadata = dict(task.metadata or {})
                item_metadata = dict(item.metadata or {})
                try:
                    attempt_seq = int(
                        item_metadata.get("attempt_seq", 0) or 0
                    )
                    item_generation = int(
                        item_metadata.get(
                            "company_run_controller_lease_generation", 0
                        )
                        or 0
                    )
                    task_attempt = int(
                        task_metadata.get("claimed_work_item_attempt_seq", 0)
                        or 0
                    )
                    task_generation = int(
                        task_metadata.get(
                            "company_run_controller_lease_generation", 0
                        )
                        or 0
                    )
                except (TypeError, ValueError):
                    continue
                item_owner = str(
                    item_metadata.get(
                        "company_run_controller_owner_token", ""
                    )
                    or ""
                ).strip()
                task_owner = str(
                    task_metadata.get(
                        "company_run_controller_owner_token", ""
                    )
                    or ""
                ).strip()
                task_parked = bool(
                    (not task_owner and task_generation == 0 and task_attempt == 0)
                    or (
                        task_owner == item_owner
                        and task_generation == item_generation
                        and task_attempt == attempt_seq
                    )
                )
                if not (
                    task.status == TaskStatus.AWAITING_HUMAN
                    and item.phase == Phase.AWAITING_HUMAN
                    and task.project_id == clean_project_id
                    and str(item.run_id or "").strip() == clean_run_id
                    and str(task_metadata.get("delegation_run_id", "") or "").strip()
                    == clean_run_id
                    and attempt_seq > 0
                    and item_metadata.get("attempt_settled") is True
                    and not str(
                        item.claimed_by_role_runtime_session_id or ""
                    ).strip()
                    and not str(item.claimed_by_seat_id or "").strip()
                    and item_owner
                    and item_generation > 0
                    and task_parked
                    and work_item_projection_id_from_metadata(
                        task_metadata,
                        fallback="",
                    )
                    == str(item.projection_id or "").strip()
                    and (
                        isinstance(task_metadata.get("work_item_gate"), dict)
                        or isinstance(
                            task_metadata.get(
                                "gate_harness_pending_decision"
                            ),
                            dict,
                        )
                    )
                    and not dict(
                        task_metadata.get(
                            "company_work_item_gate_continuation", {}
                        )
                        or {}
                    )
                ):
                    continue
                restored_basis_task = copy.deepcopy(task)
                restored_basis_task.metadata = dict(
                    restored_basis_task.metadata or {}
                )
                restored_basis_task.metadata[
                    "claimed_work_item_attempt_seq"
                ] = attempt_seq

                async with db.execute(
                    """SELECT * FROM execution_checkpoints
                       WHERE project_id = ?
                         AND checkpoint_type = 'company_work_item_gate'
                         AND status IN ('answered', 'invalid', 'failed')
                         AND (
                             task_id = ?
                             OR json_extract(payload, '$.waiting_task_id') = ?
                         )
                       ORDER BY updated_at DESC""",
                    (clean_project_id, task_id, task_id),
                ) as checkpoint_cursor:
                    checkpoint_rows = await checkpoint_cursor.fetchall()
                    checkpoint_description = checkpoint_cursor.description
                eligible: list[
                    tuple[ExecutionCheckpoint, int, int, bool]
                ] = []
                for checkpoint_row in checkpoint_rows:
                    candidate = self._execution_checkpoint_from_data(
                        dict(zip(
                            [column[0] for column in checkpoint_description],
                            checkpoint_row,
                        ))
                    )
                    candidate_payload = dict(candidate.payload or {})
                    candidate_provenance = dict(
                        candidate_payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    )
                    candidate_gate = dict(
                        candidate_payload.get("gate", {}) or {}
                    )
                    try:
                        candidate_attempt = int(
                            candidate_payload.get(
                                "work_item_attempt_seq", 0
                            )
                            or 0
                        )
                        candidate_gate_attempt = int(
                            candidate_payload.get("gate_attempt", -1)
                        )
                        provenance_attempt = int(
                            candidate_provenance.get("attempt_seq", 0) or 0
                        )
                        provenance_gate_attempt = int(
                            candidate_provenance.get("gate_attempt", -2)
                        )
                        provenance_generation = int(
                            candidate_provenance.get(
                                "controller_generation", 0
                            )
                            or 0
                        )
                        expected_gate_attempt = company_work_item_gate_attempt(
                            restored_basis_task,
                            dict(candidate_gate.get("metadata", {}) or {}),
                        )
                    except (TypeError, ValueError):
                        continue
                    expected_basis_hash = company_work_item_gate_basis_hash(
                        restored_basis_task,
                        candidate_gate,
                    )
                    if not (
                        _company_work_item_gate_publication_provenance_matches(
                            candidate_payload
                        )
                        and str(candidate.task_id or "").strip() == task_id
                        and str(
                            candidate_provenance.get("checkpoint_id", "") or ""
                        ).strip()
                        == candidate.checkpoint_id
                        and str(
                            candidate_provenance.get("project_id", "") or ""
                        ).strip()
                        == clean_project_id
                        and str(
                            candidate_provenance.get("run_id", "") or ""
                        ).strip()
                        == clean_run_id
                        and str(
                            candidate_provenance.get("task_id", "") or ""
                        ).strip()
                        == task_id
                        and str(
                            candidate_provenance.get("work_item_id", "") or ""
                        ).strip()
                        == work_item_id
                        and str(
                            candidate_provenance.get("projection_id", "") or ""
                        ).strip()
                        == str(item.projection_id or "").strip()
                        and provenance_attempt == candidate_attempt == attempt_seq
                        and provenance_gate_attempt == candidate_gate_attempt
                        and provenance_generation == item_generation
                        and str(
                            candidate_provenance.get("basis_hash", "") or ""
                        ).strip()
                        == str(candidate_payload.get("basis_hash", "") or "").strip()
                        and str(
                            candidate_provenance.get("publication_id", "") or ""
                        ).strip()
                        and str(candidate_payload.get("run_id", "") or "").strip()
                        == clean_run_id
                        and str(
                            candidate_payload.get("waiting_task_id", "")
                            or ""
                        ).strip()
                        == task_id
                        and str(
                            candidate_payload.get("waiting_work_item_id", "")
                            or ""
                        ).strip()
                        == work_item_id
                        and candidate_attempt == attempt_seq
                    ):
                        continue
                    matches_current_task_gate = bool(
                        candidate_gate_attempt == expected_gate_attempt
                        and str(
                            candidate_payload.get("basis_hash", "") or ""
                        ).strip()
                        == expected_basis_hash
                        and _company_work_item_gate_matches_task_metadata(
                            task_metadata,
                            candidate_gate,
                        )
                    )
                    if candidate.status == "answered":
                        interaction = self._execution_checkpoint_interaction(
                            candidate_payload
                        )
                        if not dict(interaction.get("decision", {}) or {}):
                            continue
                        if await self._company_work_item_gate_runtime_scope_matches(
                            db,
                            payload=candidate_payload,
                            source_task=task,
                            run_id=clean_run_id,
                            source_projection_id=projection_id_for_task(task),
                        ):
                            continue
                    eligible.append(
                        (
                            candidate,
                            candidate_attempt,
                            candidate_gate_attempt,
                            matches_current_task_gate,
                        )
                    )
                if not eligible:
                    continue
                newest_identity = max(
                    (entry[1], entry[2]) for entry in eligible
                )
                newest_candidates = [
                    entry
                    for entry in eligible
                    if (entry[1], entry[2]) == newest_identity
                ]
                current_candidates = [
                    entry for entry in newest_candidates if entry[3]
                ]
                if len(current_candidates) == 1:
                    checkpoint = current_candidates[0][0]
                elif len(newest_candidates) == 1:
                    checkpoint = newest_candidates[0][0]
                else:
                    # Two Store-stamped rows claiming the same latest identity
                    # cannot be produced by the typed publisher.  Preserve the
                    # ambiguous audit rows rather than guessing authority.
                    continue

                active_statuses = tuple(
                    sorted(OWNER_INTERACTION_ACTIVE_STATUSES)
                )
                active_placeholders = ", ".join(
                    "?" for _ in active_statuses
                )
                async with db.execute(
                    f"""SELECT * FROM execution_checkpoints
                        WHERE project_id = ?
                          AND checkpoint_type = 'company_work_item_gate'
                          AND status IN ({active_placeholders})
                          AND checkpoint_id != ?
                          AND (
                              task_id = ?
                              OR json_extract(payload, '$.waiting_task_id') = ?
                          )""",
                    (
                        clean_project_id,
                        *active_statuses,
                        checkpoint.checkpoint_id,
                        task_id,
                        task_id,
                    ),
                ) as replacement_cursor:
                    replacement_rows = await replacement_cursor.fetchall()
                    replacement_columns = [
                        column[0] for column in replacement_cursor.description
                    ]
                valid_newer_replacement = False
                for replacement_row in replacement_rows:
                    replacement = self._execution_checkpoint_from_data(
                        dict(zip(replacement_columns, replacement_row))
                    )
                    replacement_payload = dict(replacement.payload or {})
                    replacement_provenance = dict(
                        replacement_payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    )
                    replacement_gate = dict(
                        replacement_payload.get("gate", {}) or {}
                    )
                    try:
                        replacement_attempt = int(
                            replacement_payload.get(
                                "work_item_attempt_seq", 0
                            )
                            or 0
                        )
                        replacement_gate_attempt = int(
                            replacement_payload.get("gate_attempt", -1)
                        )
                        replacement_generation = int(
                            replacement_provenance.get(
                                "controller_generation", 0
                            )
                            or 0
                        )
                    except (TypeError, ValueError):
                        continue
                    if (replacement_attempt, replacement_gate_attempt) <= (
                        newest_identity
                    ):
                        continue
                    expected_replacement_gate_attempt = (
                        company_work_item_gate_attempt(
                            restored_basis_task,
                            dict(replacement_gate.get("metadata", {}) or {}),
                        )
                    )
                    expected_replacement_basis = (
                        company_work_item_gate_basis_hash(
                            restored_basis_task,
                            replacement_gate,
                        )
                    )
                    if (
                        _company_work_item_gate_publication_provenance_matches(
                            replacement_payload
                        )
                        and str(
                            replacement_provenance.get("checkpoint_id", "")
                            or ""
                        ).strip()
                        == replacement.checkpoint_id
                        and str(
                            replacement_provenance.get("project_id", "") or ""
                        ).strip()
                        == clean_project_id
                        and str(
                            replacement_provenance.get("run_id", "") or ""
                        ).strip()
                        == clean_run_id
                        and str(
                            replacement_provenance.get("task_id", "") or ""
                        ).strip()
                        == task_id
                        and str(
                            replacement_provenance.get("work_item_id", "")
                            or ""
                        ).strip()
                        == work_item_id
                        and str(
                            replacement_provenance.get("projection_id", "")
                            or ""
                        ).strip()
                        == str(item.projection_id or "").strip()
                        and int(
                            replacement_provenance.get("attempt_seq", 0) or 0
                        )
                        == replacement_attempt
                        and int(
                            replacement_provenance.get("gate_attempt", -1)
                        )
                        == replacement_gate_attempt
                        == expected_replacement_gate_attempt
                        and replacement_generation == item_generation
                        and str(
                            replacement_provenance.get("basis_hash", "") or ""
                        ).strip()
                        == str(
                            replacement_payload.get("basis_hash", "") or ""
                        ).strip()
                        == expected_replacement_basis
                        and _company_work_item_gate_matches_task_metadata(
                            task_metadata,
                            replacement_gate,
                        )
                        and await self._company_work_item_gate_runtime_scope_matches(
                            db,
                            payload=replacement_payload,
                            source_task=task,
                            run_id=clean_run_id,
                            source_projection_id=projection_id_for_task(task),
                        )
                    ):
                        valid_newer_replacement = True
                        break
                if valid_newer_replacement:
                    continue
                payload = copy.deepcopy(dict(checkpoint.payload or {}))
                interaction = self._execution_checkpoint_interaction(payload)
                decision_record = dict(interaction.get("decision", {}) or {})
                decision_value = decision_record.get("value")
                completion = dict(
                    payload.get(
                        "company_work_item_gate_decision_completion", {}
                    )
                    or {}
                )
                action = (
                    canonical_company_work_item_gate_decision(decision_value)
                    or str(completion.get("action", "") or "").strip()
                    or "invalid"
                )
                completion.update(
                    {
                        "checkpoint_id": checkpoint.checkpoint_id,
                        "final_status": "invalid",
                        "action": action,
                        "run_id": clean_run_id,
                        "task_id": task_id,
                        "work_item_id": work_item_id,
                        "attempt_seq": attempt_seq,
                        "gate_attempt": int(payload.get("gate_attempt", 0) or 0),
                        "basis_hash": str(payload.get("basis_hash", "") or ""),
                        "conflict_reason": "startup_orphan_owner_wait",
                        "target_phase": Phase.FAILED.value,
                        "continuation": "failure_settlement",
                        "finished_at": repaired_at.isoformat(),
                    }
                )
                next_item = copy.deepcopy(item)
                next_task = copy.deepcopy(task)
                failure = {
                    "checkpoint_id": checkpoint.checkpoint_id,
                    "conflict_reason": "startup_orphan_owner_wait",
                    "failed_at": repaired_at.isoformat(),
                    "attempt_seq": attempt_seq,
                    "gate_attempt": completion["gate_attempt"],
                    "basis_hash": completion["basis_hash"],
                }
                next_item.phase = Phase.FAILED
                next_item.metadata = dict(next_item.metadata or {})
                next_item.metadata.update(
                    {
                        "last_transition_reason": (
                            "company_work_item_gate_orphaned"
                        ),
                        "company_work_item_gate_failure": failure,
                        "company_run_controller_owner_token": clean_owner_token,
                        "company_run_controller_lease_generation": clean_generation,
                    }
                )
                next_task.status = task_status_for_phase(next_item.phase)
                next_task.metadata = dict(next_task.metadata or {})
                next_task.metadata.update(
                    {
                        "company_work_item_gate_failure": failure,
                        "company_run_controller_owner_token": clean_owner_token,
                        "company_run_controller_lease_generation": clean_generation,
                        "claimed_work_item_attempt_seq": attempt_seq,
                        "company_work_item_gate_continuation": {
                            **completion,
                            "kind": "failure_settlement",
                            "status": "pending",
                        },
                    }
                )
                item_update = await db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?
                         AND phase = ? AND updated_at = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = delegation_work_items.run_id
                               AND run.project_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        Phase.FAILED.value,
                        _json_dumps(next_item.metadata),
                        repaired_at.isoformat(),
                        work_item_id,
                        clean_run_id,
                        Phase.AWAITING_HUMAN.value,
                        item.updated_at.isoformat(),
                        clean_project_id,
                        clean_owner_token,
                        clean_generation,
                        repaired_at.isoformat(),
                    ),
                )
                if int(getattr(item_update, "rowcount", 0) or 0) != 1:
                    raise CompanyRunControllerLeaseLost(
                        "orphan gate source changed during startup repair"
                    )
                await self._save_task_row(next_task, commit=False, db=db)
                execution = dict(interaction.get("execution", {}) or {})
                interaction["completion"] = copy.deepcopy(completion)
                interaction["execution"] = {
                    **execution,
                    "state": "invalid",
                    "finished_at": repaired_at.isoformat(),
                }
                payload["interaction"] = interaction
                payload[
                    "company_work_item_gate_decision_completion"
                ] = copy.deepcopy(completion)
                checkpoint_update = await db.execute(
                    """UPDATE execution_checkpoints
                       SET status = 'invalid', payload = ?, updated_at = ?
                       WHERE checkpoint_id = ? AND project_id = ?
                         AND checkpoint_type = 'company_work_item_gate'
                         AND status = ? AND updated_at = ?""",
                    (
                        _json_dumps(payload),
                        repaired_at.isoformat(),
                        checkpoint.checkpoint_id,
                        clean_project_id,
                        checkpoint.status,
                        checkpoint.updated_at.isoformat(),
                    ),
                )
                if int(getattr(checkpoint_update, "rowcount", 0) or 0) != 1:
                    raise CompanyRunControllerLeaseLost(
                        "orphan gate checkpoint changed during startup repair"
                    )
                repaired_checkpoint = self._checkpoint_with(
                    checkpoint,
                    status="invalid",
                    payload=payload,
                    updated_at=repaired_at,
                )
                repaired.append(repaired_checkpoint)
                transitioned.append((item.phase, next_item))
            await db.commit()
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

        for previous_phase, item in transitioned:
            try:
                await on_phase_transition(
                    previous_phase,
                    item.phase,
                    item,
                    store=self,
                    notifications_only=True,
                )
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                logger.opt(exception=True).warning(
                    "orphan gate repair committed but phase notification failed "
                    "work_item={}",
                    item.work_item_id,
                )
        return tuple(repaired)

    async def settle_company_work_item_gate_failure_for_controller(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        run_id: str,
        owner_token: str,
        generation: int,
        conflict_reason: str,
    ) -> bool:
        """Fail closed a stamped gate continuation whose runtime scope broke.

        This is the recovery boundary for damage that makes the serialized
        company plan unsafe to execute (including a missing Task or runtime
        link).  Authority comes from the Store-owned publication provenance
        and the still-durable WorkItem attempt, never from the mutable payload
        alone.  The whole unfinished run is settled, its failure review is
        published, and the gate continuation is acknowledged in one SQLite
        transaction so a crash cannot strand a half-closed run.
        """

        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_run_id = str(run_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_reason = str(conflict_reason or "runtime_scope_mismatch").strip()[
            :240
        ]
        try:
            clean_generation = int(generation)
        except (TypeError, ValueError):
            clean_generation = 0
        if not (
            clean_checkpoint_id
            and clean_run_id
            and clean_owner_token
            and clean_generation > 0
        ):
            return False

        db = _SQLiteConnectionAdapter(self.db_path)
        transitioned: list[tuple[Phase, DelegationWorkItem]] = []
        try:
            await db.execute("BEGIN IMMEDIATE")
            settled_at = datetime.now()
            checkpoint = await self._select_execution_checkpoint(
                clean_checkpoint_id,
                project_id=clean_project_id,
                checkpoint_type="company_work_item_gate",
                db=db,
            )
            if checkpoint is None or checkpoint.status not in {
                "resolved",
                "invalid",
                "failed",
            }:
                await db.rollback()
                return False
            payload = copy.deepcopy(dict(checkpoint.payload or {}))
            provenance = dict(
                payload.get(
                    COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                    {},
                )
                or {}
            )
            try:
                stamped_attempt = int(provenance.get("attempt_seq", 0) or 0)
                stamped_gate_attempt = int(
                    provenance.get("gate_attempt", -1)
                )
                stamped_generation = int(
                    provenance.get("controller_generation", 0) or 0
                )
            except (TypeError, ValueError):
                await db.rollback()
                return False
            stamped_task_id = str(provenance.get("task_id", "") or "").strip()
            stamped_work_item_id = str(
                provenance.get("work_item_id", "") or ""
            ).strip()
            stamped_projection_id = str(
                provenance.get("projection_id", "") or ""
            ).strip()
            if not (
                _company_work_item_gate_publication_provenance_matches(payload)
                and str(provenance.get("checkpoint_id", "") or "").strip()
                == clean_checkpoint_id
                and str(provenance.get("project_id", "") or "").strip()
                == clean_project_id
                and str(provenance.get("run_id", "") or "").strip()
                == clean_run_id
                and str(checkpoint.task_id or "").strip() == stamped_task_id
                and stamped_task_id
                and stamped_work_item_id
                and stamped_projection_id
                and stamped_attempt > 0
                and stamped_gate_attempt >= 0
                and stamped_generation > 0
                and str(provenance.get("publication_id", "") or "").strip()
            ):
                await db.rollback()
                return False

            async with db.execute(
                "SELECT * FROM delegation_runs WHERE run_id = ? AND project_id = ?",
                (clean_run_id, clean_project_id),
            ) as run_cursor:
                run_row = await run_cursor.fetchone()
                run = (
                    self._row_to_delegation_run(run_row, run_cursor.description)
                    if run_row is not None
                    else None
                )
            if not (
                run is not None
                and str(run.controller_owner_token or "").strip()
                == clean_owner_token
                and int(run.controller_lease_generation or 0)
                == clean_generation
                and run.controller_lease_expires_at is not None
                and run.controller_lease_expires_at > settled_at
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot settle a broken gate continuation"
                )

            completion = dict(
                payload.get(
                    "company_work_item_gate_decision_completion",
                    {},
                )
                or {}
            )
            if completion and not (
                str(completion.get("run_id", "") or "").strip()
                == clean_run_id
                and str(completion.get("task_id", "") or "").strip()
                == stamped_task_id
                and str(completion.get("work_item_id", "") or "").strip()
                == stamped_work_item_id
                and int(completion.get("attempt_seq", 0) or 0)
                == stamped_attempt
                and int(completion.get("gate_attempt", -1))
                == stamped_gate_attempt
                and str(completion.get("basis_hash", "") or "").strip()
                == str(provenance.get("basis_hash", "") or "").strip()
            ):
                await db.rollback()
                return False
            canonical_reason = str(
                completion.get("conflict_reason")
                or clean_reason
                or "postcommit_company_work_item_gate_scope_mismatch"
            ).strip()[:240]
            settlement_id = hashlib.sha256(
                json.dumps(
                    {
                        "checkpoint_id": clean_checkpoint_id,
                        "publication_identity_sha256": str(
                            provenance.get("identity_sha256", "") or ""
                        ),
                        "run_id": clean_run_id,
                        "work_item_id": stamped_work_item_id,
                        "attempt_seq": stamped_attempt,
                        "gate_attempt": stamped_gate_attempt,
                        "basis_hash": str(
                            provenance.get("basis_hash", "") or ""
                        ),
                        "reason": canonical_reason,
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            failure_source_event_id = f"company-run-failure:{clean_run_id}"
            existing_settlement = dict(
                payload.get("company_work_item_gate_failure_settlement", {})
                or {}
            )
            async with db.execute(
                """SELECT * FROM execution_checkpoints
                   WHERE project_id = ?
                     AND checkpoint_type = 'company_run_failure_review'
                     AND json_extract(payload, '$.run_id') = ?
                     AND json_extract(payload, '$.source_event_id') = ?
                     AND status NOT IN (
                         'invalid', 'stale', 'superseded', 'failed',
                         'cancelled', 'canceled', 'outcome_unknown'
                     )
                   ORDER BY updated_at DESC""",
                (
                    clean_project_id,
                    clean_run_id,
                    failure_source_event_id,
                ),
            ) as existing_review_cursor:
                existing_review_rows = await existing_review_cursor.fetchall()
                existing_review_columns = [
                    item[0] for item in existing_review_cursor.description
                ]
            exact_existing_reviews = []
            for existing_review_row in existing_review_rows:
                existing_review = self._execution_checkpoint_from_data(
                    dict(zip(existing_review_columns, existing_review_row))
                )
                existing_review_payload = dict(existing_review.payload or {})
                if str(
                    existing_review_payload.get(
                        "company_work_item_gate_failure_settlement_id", ""
                    )
                    or ""
                ).strip() == settlement_id:
                    exact_existing_reviews.append(existing_review)
            if existing_settlement:
                exact_duplicate = bool(
                    str(existing_settlement.get("settlement_id", "") or "").strip()
                    == settlement_id
                    and str(existing_settlement.get("checkpoint_id", "") or "").strip()
                    == clean_checkpoint_id
                    and str(existing_settlement.get("run_id", "") or "").strip()
                    == clean_run_id
                    and str(existing_settlement.get("work_item_id", "") or "").strip()
                    == stamped_work_item_id
                    and int(existing_settlement.get("attempt_seq", 0) or 0)
                    == stamped_attempt
                    and str(existing_settlement.get("conflict_reason", "") or "").strip()
                    == canonical_reason
                    and str(run.status or "").strip() == "failed"
                    and str(run.lifecycle_status or "").strip()
                    == "closed_failed"
                    and len(exact_existing_reviews) == 1
                    and str(
                        completion.get("continuation_status", "") or ""
                    ).strip()
                    == "completed"
                )
                await db.rollback()
                return exact_duplicate
            if (
                str(run.lifecycle_status or "").strip() != "active"
                or str(run.status or "").strip() not in {"pending", "running"}
                or existing_review_rows
            ):
                await db.rollback()
                return False

            async with db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (stamped_work_item_id,),
            ) as source_cursor:
                source_row = await source_cursor.fetchone()
                source_item = (
                    self._row_to_delegation_work_item(
                        source_row,
                        source_cursor.description,
                    )
                    if source_row is not None
                    else None
                )
            source_metadata = dict(
                (source_item.metadata if source_item else {}) or {}
            )
            try:
                source_attempt = int(source_metadata.get("attempt_seq", 0) or 0)
            except (TypeError, ValueError):
                source_attempt = 0
            if not (
                source_item is not None
                and str(source_item.run_id or "").strip() == clean_run_id
                and str(source_item.projection_id or "").strip()
                == stamped_projection_id
                and source_attempt == stamped_attempt
                and source_metadata.get("attempt_settled") is True
                and not str(
                    source_item.claimed_by_role_runtime_session_id or ""
                ).strip()
                and not str(source_item.claimed_by_seat_id or "").strip()
            ):
                await db.rollback()
                return False

            # A later gate/attempt is authoritative.  Never let an older stamped
            # continuation fail a source that has already moved on (ABA fence).
            async with db.execute(
                """SELECT * FROM execution_checkpoints
                   WHERE project_id = ?
                     AND checkpoint_type = 'company_work_item_gate'
                     AND checkpoint_id != ?""",
                (clean_project_id, clean_checkpoint_id),
            ) as other_cursor:
                other_rows = await other_cursor.fetchall()
                other_columns = [item[0] for item in other_cursor.description]
            for other_row in other_rows:
                other = self._execution_checkpoint_from_data(
                    dict(zip(other_columns, other_row))
                )
                other_payload = dict(other.payload or {})
                if not _company_work_item_gate_publication_provenance_matches(
                    other_payload
                ):
                    continue
                other_provenance = dict(
                    other_payload.get(
                        COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                        {},
                    )
                    or {}
                )
                if str(
                    other_provenance.get("work_item_id", "") or ""
                ).strip() != stamped_work_item_id:
                    continue
                try:
                    other_attempt = int(
                        other_provenance.get("attempt_seq", 0) or 0
                    )
                    other_gate_attempt = int(
                        other_provenance.get("gate_attempt", -1)
                    )
                except (TypeError, ValueError):
                    await db.rollback()
                    return False
                same_or_newer = bool(
                    other_attempt > stamped_attempt
                    or (
                        other_attempt == stamped_attempt
                        and other_gate_attempt >= stamped_gate_attempt
                    )
                )
                if same_or_newer and (
                    other_attempt > stamped_attempt
                    or other_gate_attempt > stamped_gate_attempt
                    or str(other.status or "").strip()
                    in OWNER_INTERACTION_ACTIVE_STATUSES
                ):
                    await db.rollback()
                    return False

            durable_source_task = await self._get_task_unhydrated(
                stamped_task_id,
                db=db,
            )
            async with db.execute(
                """SELECT work_item_id FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (stamped_task_id,),
            ) as source_link_cursor:
                source_link_rows = await source_link_cursor.fetchall()
            source_marker = dict(
                (
                    (durable_source_task.metadata if durable_source_task else {})
                    or {}
                ).get("company_work_item_gate_continuation", {})
                or {}
            )
            try:
                marker_attempt = int(source_marker.get("attempt_seq", 0) or 0)
                marker_gate_attempt = int(
                    source_marker.get("gate_attempt", -1)
                )
                completion_attempt = int(
                    completion.get("attempt_seq", 0) or 0
                )
                completion_gate_attempt = int(
                    completion.get("gate_attempt", -2)
                )
            except (TypeError, ValueError):
                await db.rollback()
                return False
            exact_source_marker = bool(
                str(source_marker.get("checkpoint_id", "") or "").strip()
                == clean_checkpoint_id
                and str(source_marker.get("kind", "") or "").strip()
                == str(completion.get("continuation", "") or "").strip()
                and str(source_marker.get("action", "") or "").strip()
                == str(completion.get("action", "") or "").strip()
                and marker_attempt == completion_attempt == stamped_attempt
                and marker_gate_attempt
                == completion_gate_attempt
                == stamped_gate_attempt
                and str(source_marker.get("basis_hash", "") or "").strip()
                == str(completion.get("basis_hash", "") or "").strip()
                == str(provenance.get("basis_hash", "") or "").strip()
                and str(source_marker.get("target_phase", "") or "").strip()
                == str(completion.get("target_phase", "") or "").strip()
            )
            exact_pending_source_marker = bool(
                exact_source_marker
                and str(source_marker.get("status", "") or "").strip()
                == "pending"
            )
            exact_completed_source_marker = bool(
                exact_source_marker
                and str(source_marker.get("status", "") or "").strip()
                == "completed"
            )
            full_scope_still_valid = bool(
                durable_source_task is not None
                and [str(row[0] or "").strip() for row in source_link_rows]
                == [stamped_work_item_id]
                and await self._company_work_item_gate_runtime_scope_matches(
                    db,
                    payload=payload,
                    source_task=durable_source_task,
                    run_id=clean_run_id,
                    source_projection_id=stamped_projection_id,
                )
            )
            if checkpoint.status == "resolved" and (
                str(completion.get("continuation_status", "") or "").strip()
                == "completed"
                or exact_completed_source_marker
                or (full_scope_still_valid and exact_pending_source_marker)
            ):
                await db.rollback()
                return False

            async with db.execute(
                "SELECT * FROM delegation_work_items WHERE run_id = ?",
                (clean_run_id,),
            ) as item_cursor:
                item_rows = await item_cursor.fetchall()
                item_description = item_cursor.description
            work_items = [
                self._row_to_delegation_work_item(row, item_description)
                for row in item_rows
            ]
            if not work_items:
                await db.rollback()
                return False
            failed_items: list[dict[str, str]] = []
            task_ids: list[str] = []
            source_task: Task | None = None
            async with db.execute(
                "SELECT * FROM tasks WHERE project_id = ?",
                (clean_project_id,),
            ) as scoped_task_cursor:
                scoped_task_rows = await scoped_task_cursor.fetchall()
                scoped_task_description = scoped_task_cursor.description
            scoped_tasks_by_projection: dict[str, list[Task]] = {}
            for scoped_task_row in scoped_task_rows:
                candidate_task = self._row_to_task(
                    scoped_task_row,
                    scoped_task_description,
                )
                candidate_metadata = dict(candidate_task.metadata or {})
                if str(
                    candidate_metadata.get("delegation_run_id", "") or ""
                ).strip() != clean_run_id:
                    continue
                candidate_projection = work_item_projection_id_from_metadata(
                    candidate_metadata,
                    fallback="",
                )
                if candidate_projection:
                    scoped_tasks_by_projection.setdefault(
                        candidate_projection,
                        [],
                    ).append(candidate_task)
            for item in work_items:
                previous_phase = item.phase
                is_source = item.work_item_id == stamped_work_item_id
                target_phase = (
                    Phase.FAILED
                    if is_source
                    else (
                        item.phase
                        if item.phase in DONE_PHASES
                        else Phase.CANCELLED
                    )
                )
                next_item = copy.deepcopy(item)
                next_item.phase = target_phase
                next_item.claimed_by_role_runtime_session_id = ""
                next_item.claimed_by_seat_id = ""
                next_item.metadata = dict(next_item.metadata or {})
                next_item.metadata.update(
                    build_attempt_settlement_updates(
                        next_item.metadata,
                        outcome=target_phase.value,
                        settled_at=settled_at,
                    )
                )
                for transient_key in (
                    "dispatch_hold",
                    "suspended_at",
                    "suspend_reason",
                    "suspend_checkpoint_type",
                    "suspend_intent_id",
                    "suspended_phase",
                    "suspended_task_status",
                    "suspended_claim",
                    "queued_for_dispatch",
                    "queued_dispatch_at",
                ):
                    next_item.metadata.pop(transient_key, None)
                next_item.metadata["claimed_by_role_session_id"] = ""
                next_item.metadata["claimed_task_id"] = ""
                reason = (
                    "company_work_item_gate_invalidated"
                    if is_source
                    else "company_work_item_gate_failure_cascade"
                )
                next_item.metadata.update(
                    {
                        "last_transition_reason": reason,
                        "company_work_item_gate_failure": {
                            "checkpoint_id": clean_checkpoint_id,
                            "conflict_reason": canonical_reason,
                            "failed_at": settled_at.isoformat(),
                            "attempt_seq": stamped_attempt,
                            "gate_attempt": stamped_gate_attempt,
                            "basis_hash": str(
                                provenance.get("basis_hash", "") or ""
                            ),
                        },
                        "company_run_controller_owner_token": clean_owner_token,
                        "company_run_controller_lease_generation": clean_generation,
                    }
                )
                if is_source or target_phase != previous_phase:
                    next_item.updated_at = settled_at
                    updated = await db.execute(
                        """UPDATE delegation_work_items
                           SET phase = ?, claimed_by_role_runtime_session_id = '',
                               claimed_by_seat_id = '', metadata = ?, updated_at = ?
                           WHERE work_item_id = ? AND run_id = ?
                             AND phase = ? AND updated_at = ?
                             AND EXISTS (
                                 SELECT 1 FROM delegation_runs AS live_run
                                 WHERE live_run.run_id = delegation_work_items.run_id
                                   AND live_run.project_id = ?
                                   AND live_run.controller_owner_token = ?
                                   AND live_run.controller_lease_generation = ?
                                   AND live_run.controller_lease_expires_at > ?
                             )""",
                        (
                            target_phase.value,
                            _json_dumps(next_item.metadata),
                            settled_at.isoformat(),
                            item.work_item_id,
                            clean_run_id,
                            previous_phase.value,
                            item.updated_at.isoformat(),
                            clean_project_id,
                            clean_owner_token,
                            clean_generation,
                            settled_at.isoformat(),
                        ),
                    )
                    if int(getattr(updated, "rowcount", 0) or 0) != 1:
                        raise CompanyRunControllerLeaseLost(
                            "gate failure cascade lost its WorkItem CAS"
                        )
                    if target_phase != previous_phase:
                        transitioned.append((previous_phase, next_item))

                async with db.execute(
                    """SELECT task.* FROM work_item_runtime_links AS link
                       JOIN tasks AS task ON task.id = link.runtime_task_id
                       WHERE link.work_item_id = ?""",
                    (item.work_item_id,),
                ) as task_cursor:
                    linked_task_rows = await task_cursor.fetchall()
                    task_description = task_cursor.description
                if len(linked_task_rows) > 1:
                    await db.rollback()
                    return False
                linked_task = (
                    self._row_to_task(linked_task_rows[0], task_description)
                    if len(linked_task_rows) == 1
                    else None
                )
                if linked_task is not None:
                    linked_metadata = dict(linked_task.metadata or {})
                    if not (
                        linked_task.project_id == clean_project_id
                        and str(
                            linked_metadata.get("delegation_run_id", "") or ""
                        ).strip()
                        == clean_run_id
                        and work_item_projection_id_from_metadata(
                            linked_metadata,
                            fallback="",
                        )
                        == str(item.projection_id or "").strip()
                    ):
                        # A bad link is exactly why this path exists.  Do not
                        # guess-write the unrelated Task; the stamped WorkItem
                        # and run remain sufficient authority for fail-closed.
                        linked_task = None
                if linked_task is None:
                    projection_candidates = scoped_tasks_by_projection.get(
                        str(item.projection_id or "").strip(),
                        [],
                    )
                    if len(projection_candidates) == 1:
                        linked_task = copy.deepcopy(projection_candidates[0])
                if linked_task is not None:
                    linked_metadata = dict(linked_task.metadata or {})
                    if not (
                        linked_task.project_id == clean_project_id
                        and str(
                            linked_metadata.get("delegation_run_id", "") or ""
                        ).strip()
                        == clean_run_id
                        and work_item_projection_id_from_metadata(
                            linked_metadata,
                            fallback="",
                        )
                        == str(item.projection_id or "").strip()
                    ):
                        linked_task = None
                if linked_task is not None:
                    linked_task.status = task_status_for_phase(target_phase)
                    linked_task.execution_lock = False
                    linked_task.execution_locked_at = None
                    linked_task.metadata = linked_metadata
                    for transient_key in (
                        "dispatch_hold",
                        "company_runtime_stop_state",
                        "company_runtime_stop_intent_id",
                        "company_runtime_stop_marked_at",
                        "company_runtime_suspend_checkpoint_type",
                        "company_runtime_suspended_at",
                        "suspended_phase",
                        "suspended_task_status",
                    ):
                        linked_task.metadata.pop(transient_key, None)
                    linked_task.metadata.update(
                        {
                            "company_run_controller_owner_token": (
                                clean_owner_token
                            ),
                            "company_run_controller_lease_generation": (
                                clean_generation
                            ),
                        }
                    )
                    if is_source:
                        linked_task.metadata[
                            "claimed_work_item_attempt_seq"
                        ] = stamped_attempt
                        linked_task.metadata[
                            "company_work_item_gate_continuation"
                        ] = {
                            "checkpoint_id": clean_checkpoint_id,
                            "action": str(
                                completion.get("action", "invalid")
                                or "invalid"
                            ),
                            "attempt_seq": stamped_attempt,
                            "gate_attempt": stamped_gate_attempt,
                            "basis_hash": str(
                                provenance.get("basis_hash", "") or ""
                            ),
                            "target_phase": Phase.FAILED.value,
                            "kind": "failure_settlement",
                            "status": "completed",
                            "completed_at": settled_at.isoformat(),
                        }
                        source_task = linked_task
                    await self._save_task_row(
                        linked_task,
                        commit=False,
                        db=db,
                    )
                    task_ids.append(linked_task.id)
                if target_phase in {Phase.FAILED, Phase.CANCELLED}:
                    failed_items.append(
                        {
                            "work_item_id": item.work_item_id,
                            "kind": str(item.kind or ""),
                            "role_id": str(item.role_id or ""),
                            "phase": target_phase.value,
                            "blocked_reason": str(item.blocked_reason or "")[:300],
                        }
                    )

            closed_at = str(
                dict(dict(run.metadata or {}).get("run_failure", {}) or {}).get(
                    "closed_at", ""
                )
                or settled_at.isoformat()
            ).strip()
            run_failure = {
                "closed_at": closed_at,
                "failed_items": failed_items,
                "source_checkpoint_id": clean_checkpoint_id,
                "conflict_reason": canonical_reason,
                "company_work_item_gate_failure_settlement_id": settlement_id,
            }
            root_session_id = str(run.session_id or "").strip()
            if not existing_review_rows:
                review_basis_hash = hashlib.sha256(
                    json.dumps(
                        {
                            "run_id": clean_run_id,
                            "source_event_id": failure_source_event_id,
                            "company_work_item_gate_failure_settlement_id": (
                                settlement_id
                            ),
                            "failed_items": failed_items,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                interaction_key = hashlib.sha256(
                    (
                        f"company_run_failure_review:{clean_project_id}:"
                        f"{failure_source_event_id}:{review_basis_hash}"
                    ).encode("utf-8")
                ).hexdigest()
                supersession_key = hashlib.sha256(
                    (
                        f"company_run_failure_review:{clean_project_id}:"
                        f"{root_session_id}"
                    ).encode("utf-8")
                ).hexdigest()
                prompt_lines = "\n".join(
                    f"- `{item['kind']}::{item['role_id']}` {item['phase']}"
                    for item in failed_items
                )
                review_checkpoint = ExecutionCheckpoint(
                    checkpoint_id=(
                        "company-run-failure-review-"
                        + hashlib.sha256(
                            f"{clean_project_id}:{clean_run_id}".encode("utf-8")
                        ).hexdigest()[:24]
                    ),
                    project_id=clean_project_id,
                    session_id=root_session_id or None,
                    checkpoint_type="company_run_failure_review",
                    task_id=(source_task.id if source_task is not None else None),
                    payload={
                        "run_id": clean_run_id,
                        "source_event_id": failure_source_event_id,
                        "company_work_item_gate_failure_settlement_id": (
                            settlement_id
                        ),
                        "revision": 1,
                        "basis_hash": review_basis_hash,
                        "waiting_task_id": (
                            source_task.id if source_task is not None else ""
                        ),
                        "session_id": root_session_id,
                        "task_ids": task_ids,
                        "closed_at": closed_at,
                        "failed_items": failed_items,
                        "prompt": (
                            "This company run ended with failed work items and "
                            "has been closed.\n\n"
                            f"{prompt_lines}\n\n"
                            "Reply `dismiss` to acknowledge, or send a new "
                            "request to start a fresh run."
                        ),
                        "interaction": {
                            "kind": "company_run_failure_review",
                            "domain_key": interaction_key,
                            "supersession_key": supersession_key,
                            "supersession_order": [0, 1],
                            "ownership": {
                                "waiting_task_id": (
                                    source_task.id
                                    if source_task is not None
                                    else ""
                                ),
                                "waiting_session_id": root_session_id,
                                "root_session_id": root_session_id,
                                "ui_anchor_session_id": root_session_id,
                            },
                        },
                    },
                )
                await self._publish_owner_interaction_checkpoint(
                    review_checkpoint,
                    interaction_key=interaction_key,
                    supersede_pending_scope=True,
                    supersession_key=supersession_key,
                    supersession_order=(0, 1),
                    transaction_open=True,
                    db=db,
                )

            next_run_metadata = dict(run.metadata or {})
            next_run_metadata.update(
                {
                    "run_failure": run_failure,
                    "failure_review_published_at": settled_at.isoformat(),
                    "failure_review_source_event_id": failure_source_event_id,
                }
            )
            run_update = await db.execute(
                """UPDATE delegation_runs
                   SET status = 'failed', lifecycle_status = 'closed_failed',
                       metadata = ?, updated_at = ?
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?
                     AND status = ? AND lifecycle_status = ?
                     AND updated_at = ?""",
                (
                    _json_dumps(next_run_metadata),
                    settled_at.isoformat(),
                    clean_run_id,
                    clean_project_id,
                    clean_owner_token,
                    clean_generation,
                    settled_at.isoformat(),
                    run.status,
                    run.lifecycle_status,
                    run.updated_at.isoformat(),
                ),
            )
            if int(getattr(run_update, "rowcount", 0) or 0) != 1:
                raise CompanyRunControllerLeaseLost(
                    "gate failure settlement lost its run CAS"
                )

            original_continuation = str(
                completion.get("continuation", "") or ""
            ).strip()
            completion.update(
                {
                    "checkpoint_id": clean_checkpoint_id,
                    "final_status": str(checkpoint.status or "invalid"),
                    "action": str(completion.get("action", "") or "invalid"),
                    "run_id": clean_run_id,
                    "task_id": stamped_task_id,
                    "work_item_id": stamped_work_item_id,
                    "attempt_seq": stamped_attempt,
                    "gate_attempt": stamped_gate_attempt,
                    "basis_hash": str(provenance.get("basis_hash", "") or ""),
                    "target_phase": Phase.FAILED.value,
                    "continuation": "failure_settlement",
                    "continuation_status": "completed",
                    "continuation_completed_at": settled_at.isoformat(),
                    "conflict_reason": canonical_reason,
                    "original_continuation": original_continuation,
                }
            )
            payload[
                "company_work_item_gate_decision_completion"
            ] = copy.deepcopy(completion)
            payload["company_work_item_gate_failure_settlement"] = {
                "settlement_id": settlement_id,
                "checkpoint_id": clean_checkpoint_id,
                "settled_at": settled_at.isoformat(),
                "conflict_reason": canonical_reason,
                "run_id": clean_run_id,
                "work_item_id": stamped_work_item_id,
                "attempt_seq": stamped_attempt,
                "publication_identity_sha256": str(
                    provenance.get("identity_sha256", "") or ""
                ),
            }
            checkpoint_update = await db.execute(
                """UPDATE execution_checkpoints
                   SET payload = ?, updated_at = ?
                   WHERE checkpoint_id = ? AND project_id = ?
                     AND checkpoint_type = 'company_work_item_gate'
                     AND status = ? AND updated_at = ?""",
                (
                    _json_dumps(payload),
                    settled_at.isoformat(),
                    clean_checkpoint_id,
                    clean_project_id,
                    checkpoint.status,
                    checkpoint.updated_at.isoformat(),
                ),
            )
            if int(getattr(checkpoint_update, "rowcount", 0) or 0) != 1:
                raise CompanyRunControllerLeaseLost(
                    "gate failure settlement lost its checkpoint CAS"
                )
            await db.commit()
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

        for previous_phase, item in transitioned:
            try:
                await on_phase_transition(
                    previous_phase,
                    item.phase,
                    item,
                    store=self,
                    notifications_only=True,
                )
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                logger.opt(exception=True).warning(
                    "gate failure settlement committed but notification failed "
                    "work_item={}",
                    item.work_item_id,
                )
        return True

    async def publish_company_work_item_gate_checkpoint_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        publication: PreparedOwnerInteractionPublication,
        *,
        task_snapshot: Task,
        expected_task_preimage_hash: str,
        progress_messages: tuple[str, ...] = (),
    ) -> tuple[ExecutionCheckpoint, bool, Task]:
        """Publish one work-item gate from an exact durable controller attempt.

        The generic owner publisher intentionally cannot establish company
        attempt authority.  This typed ingress validates Task, WorkItem, run,
        controller, attempt, phase, and the full gate basis in the same
        transaction that inserts/supersedes the owner interaction.
        """

        self._require_db()
        checkpoint = copy.deepcopy(publication.checkpoint)
        if not context.complete:
            raise CompanyRunControllerLeaseLost(
                "company gate publication lacks an exact controller attempt"
            )
        if (
            checkpoint.checkpoint_type != "company_work_item_gate"
            or (str(checkpoint.project_id or "default").strip() or "default")
            != context.project_id
            or str(checkpoint.task_id or "").strip() != context.task_id
        ):
            raise ValueError(
                "company gate publication does not belong to the controller context"
            )
        if (
            str(task_snapshot.id or "").strip() != context.task_id
            or (str(task_snapshot.project_id or "default").strip() or "default")
            != context.project_id
            or task_snapshot.status != TaskStatus.AWAITING_HUMAN
            or not str(expected_task_preimage_hash or "").strip()
        ):
            raise ValueError(
                "company gate publication requires an exact awaiting-human Task snapshot"
            )
        submitted_task = copy.deepcopy(task_snapshot)
        expected_preimage = str(expected_task_preimage_hash or "").strip()
        clean_progress_messages = tuple(
            str(message or "").strip()
            for message in tuple(progress_messages or ())
            if str(message or "").strip()
        )
        payload = copy.deepcopy(dict(checkpoint.payload or {}))
        gate = dict(payload.get("gate", {}) or {})
        if not gate:
            raise ValueError("company gate publication requires a gate policy")
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        persisted: ExecutionCheckpoint | None = None
        created = False
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            if not await self._company_controller_attempt_context_matches(
                transaction_db,
                context,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale company controller cannot publish a work-item gate"
                )
            durable_task = await self._get_task_unhydrated(
                context.task_id,
                db=transaction_db,
            )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (context.work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                durable_item = (
                    self._row_to_delegation_work_item(row, cursor.description)
                    if row is not None
                    else None
                )
            if durable_task is None or durable_item is None:
                await transaction_db.rollback()
                raise CompanyControllerAttemptSuperseded(
                    "company gate source Task/WorkItem disappeared"
                )
            async with transaction_db.execute(
                """SELECT work_item_id
                   FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (context.task_id,),
            ) as cursor:
                link_row = await cursor.fetchone()
            durable_linked_work_item_id = (
                str(link_row[0] or "").strip()
                if link_row is not None
                else ""
            )
            if _task_authoritative_preimage_hash(durable_task) != expected_preimage:
                await transaction_db.rollback()
                raise CompanyControllerAttemptSuperseded(
                    "company gate source Task changed before publication"
                )
            task_metadata = dict(durable_task.metadata or {})
            item_metadata = dict(durable_item.metadata or {})
            try:
                task_attempt = int(
                    task_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                )
                item_attempt = int(item_metadata.get("attempt_seq", 0) or 0)
                task_generation = int(
                    task_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                item_generation = int(
                    item_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                payload_attempt = int(payload.get("work_item_attempt_seq", 0) or 0)
                payload_gate_attempt = int(payload.get("gate_attempt", -1))
            except (TypeError, ValueError):
                await transaction_db.rollback()
                raise CompanyControllerAttemptSuperseded(
                    "company gate attempt identity is malformed"
                )
            task_owner = str(
                task_metadata.get("company_run_controller_owner_token", "") or ""
            ).strip()
            item_owner = str(
                item_metadata.get("company_run_controller_owner_token", "") or ""
            ).strip()
            projection_id = projection_id_for_task(durable_task)
            payload_projection_id = str(
                payload.get(WORK_ITEM_PROJECTION_ID_KEY, "") or ""
            ).strip()
            runtime_scope_matches = (
                await self._company_work_item_gate_runtime_scope_matches(
                    transaction_db,
                    payload=payload,
                    source_task=durable_task,
                    run_id=context.run_id,
                    source_projection_id=projection_id,
                )
            )
            expected_gate_attempt = company_work_item_gate_attempt(
                durable_task,
                dict(gate.get("metadata", {}) or {}),
            )
            expected_basis_hash = company_work_item_gate_basis_hash(
                submitted_task,
                gate,
            )
            expected_source_event_id = (
                f"work-item-gate:{context.run_id}:{projection_id}:"
                f"{str(gate.get('type', '') or '').strip()}:{expected_gate_attempt}"
            )
            submitted_metadata = dict(submitted_task.metadata or {})
            submitted_pending_harness = dict(
                submitted_metadata.get(
                    "gate_harness_pending_decision", {}
                )
                or {}
            )
            gate_matches = _company_work_item_gate_matches_task_metadata(
                task_metadata,
                gate,
                pending_harness_override=(
                    submitted_pending_harness or None
                ),
            )
            allowed_task_metadata_keys = {
                "gate_harness_evidence",
                "gate_harness_decision",
                "gate_harness_history",
                "gate_harness_status",
                "gate_harness_pending_decision",
                "gate_harness_review_level",
                "gate_harness_review_target_role_id",
                "gate_harness_review_chain_role_ids",
                "working_memory",
            }
            expected_task = copy.deepcopy(durable_task)
            expected_task.status = TaskStatus.AWAITING_HUMAN
            expected_metadata = dict(expected_task.metadata or {})
            for key in allowed_task_metadata_keys:
                if key in submitted_metadata:
                    expected_metadata[key] = copy.deepcopy(
                        submitted_metadata[key]
                    )
                else:
                    expected_metadata.pop(key, None)
            expected_task.metadata = expected_metadata
            task_snapshot_matches = (
                _task_authoritative_preimage_hash(expected_task)
                == _task_authoritative_preimage_hash(submitted_task)
            )
            already_parked = (
                durable_task.status == TaskStatus.AWAITING_HUMAN
                and durable_item.phase == Phase.AWAITING_HUMAN
                and item_metadata.get("attempt_settled") is True
                and _task_authoritative_preimage_hash(durable_task)
                == _task_authoritative_preimage_hash(submitted_task)
            )
            fresh_open_attempt = (
                durable_task.status == TaskStatus.RUNNING
                and durable_item.phase == Phase.RUNNING
                and item_metadata.get("attempt_settled") is not True
                and bool(
                    str(
                        durable_item.claimed_by_role_runtime_session_id or ""
                    ).strip()
                    or str(durable_item.claimed_by_seat_id or "").strip()
                )
            )
            identity_matches = (
                str(durable_item.run_id or "").strip() == context.run_id
                and str(task_metadata.get("delegation_run_id", "") or "").strip()
                == context.run_id
                and durable_linked_work_item_id == context.work_item_id
                and str(durable_item.projection_id or "").strip() == projection_id
                and payload_projection_id == projection_id
                and str(payload.get("run_id", "") or "").strip()
                == context.run_id
                and str(payload.get("waiting_task_id", "") or "").strip()
                == context.task_id
                and str(payload.get("waiting_work_item_id", "") or "").strip()
                == context.work_item_id
                and task_attempt == item_attempt == payload_attempt
                == context.attempt_seq
                and task_owner == item_owner == context.owner_token
                and task_generation == item_generation == context.generation
                and task_snapshot_matches
                and (fresh_open_attempt or already_parked)
                and payload_gate_attempt == expected_gate_attempt
                and str(payload.get("basis_hash", "") or "").strip()
                == expected_basis_hash
                and str(payload.get("source_event_id", "") or "").strip()
                == expected_source_event_id
                and gate_matches
                and runtime_scope_matches
            )
            if not identity_matches:
                await transaction_db.rollback()
                raise CompanyControllerAttemptSuperseded(
                    "company gate publication lost its durable Task/WorkItem basis"
                )
            payload[
                COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY
            ] = _company_work_item_gate_publication_provenance(
                {
                    "publication_id": hashlib.sha256(
                        (
                            f"{checkpoint.checkpoint_id}:"
                            f"{expected_source_event_id}:"
                            f"{expected_basis_hash}"
                        ).encode("utf-8")
                    ).hexdigest(),
                    "published_at": (
                        durable_item.updated_at
                        if already_parked
                        else checked_at
                    ).isoformat(),
                    "checkpoint_id": checkpoint.checkpoint_id,
                    "project_id": context.project_id,
                    "run_id": context.run_id,
                    "task_id": context.task_id,
                    "work_item_id": context.work_item_id,
                    "projection_id": projection_id,
                    "attempt_seq": context.attempt_seq,
                    "gate_attempt": expected_gate_attempt,
                    "basis_hash": expected_basis_hash,
                    "source_event_id": expected_source_event_id,
                    "controller_owner_token": context.owner_token,
                    "controller_generation": context.generation,
                    "parked_work_item_updated_at": (
                        durable_item.updated_at
                        if already_parked
                        else checked_at
                    ).isoformat(),
                }
            )
            checkpoint.payload = copy.deepcopy(payload)
            previous_phase = durable_item.phase
            if fresh_open_attempt:
                next_item = copy.deepcopy(durable_item)
                next_item.phase = Phase.AWAITING_HUMAN
                next_item.claimed_by_role_runtime_session_id = ""
                next_item.claimed_by_seat_id = ""
                next_item_metadata = dict(next_item.metadata or {})
                next_item_metadata.update(
                    build_attempt_settlement_updates(
                        next_item_metadata,
                        outcome="awaiting_human",
                        settled_at=checked_at,
                    )
                )
                next_item_metadata["claimed_by_role_session_id"] = ""
                next_item_metadata["claimed_task_id"] = ""
                next_item_metadata["last_transition_reason"] = (
                    "company_work_item_gate_awaiting_human"
                )
                for key in allowed_task_metadata_keys - {"working_memory"}:
                    if key in submitted_metadata:
                        next_item_metadata[key] = copy.deepcopy(
                            submitted_metadata[key]
                        )
                    else:
                        next_item_metadata.pop(key, None)
                if clean_progress_messages:
                    current_progress = list(
                        next_item_metadata.get("progress_log", []) or []
                    )
                    next_item_metadata["progress_log"] = list(
                        dict.fromkeys(
                            [*current_progress, *clean_progress_messages]
                        )
                    )
                next_item.metadata = next_item_metadata
                next_item.updated_at = checked_at
                validate_transition(previous_phase, next_item.phase)
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?
                         AND phase = ? AND updated_at = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = delegation_work_items.run_id
                               AND run.project_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        next_item.phase.value,
                        _json_dumps(next_item.metadata),
                        next_item.updated_at.isoformat(),
                        context.work_item_id,
                        context.run_id,
                        previous_phase.value,
                        durable_item.updated_at.isoformat(),
                        context.project_id,
                        context.owner_token,
                        context.generation,
                        checked_at.isoformat(),
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    raise CompanyControllerAttemptSuperseded(
                        "company gate WorkItem pause CAS was lost"
                    )
                await self._save_task_row(
                    submitted_task,
                    commit=False,
                    db=transaction_db,
                )
            persisted, created = await self._publish_owner_interaction_checkpoint(
                checkpoint,
                interaction_key=publication.interaction_key,
                supersede_pending_scope=True,
                supersession_key=publication.supersession_key,
                supersession_order=publication.supersession_order,
                transaction_open=True,
                db=transaction_db,
                reserved_publication_capability=(
                    _COMPANY_WORK_ITEM_GATE_PUBLICATION_CAPABILITY
                ),
            )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()
        if persisted is None:
            raise RuntimeError("company gate publication returned no checkpoint")
        if fresh_open_attempt:
            try:
                await on_phase_transition(
                    previous_phase,
                    Phase.AWAITING_HUMAN,
                    next_item,
                    store=self,
                    notifications_only=True,
                )
            except CompanyRunControllerLeaseLost:
                logger.warning(
                    "Post-commit gate-pause notification observed controller takeover "
                    "work_item={}",
                    context.work_item_id,
                )
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                logger.opt(exception=True).warning(
                    "Post-commit gate-pause notification failed work_item={}",
                    context.work_item_id,
                )
        return persisted, created, copy.deepcopy(submitted_task)

    async def _complete_company_work_item_gate_checkpoint_in_transaction(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        checkpoint: ExecutionCheckpoint,
        command: CompanyWorkItemGateDecisionCommand,
        payload: dict[str, Any],
        completion: dict[str, Any],
        completed_at: datetime,
        final_status: str = "resolved",
    ) -> ExecutionCheckpoint | None:
        """Close the exact ready gate claim while the business tx is open."""

        clean_final_status = str(final_status or "").strip()
        if clean_final_status not in {"resolved", "invalid"}:
            return None
        interaction = self._execution_checkpoint_interaction(payload)
        execution = dict(interaction.get("execution", {}) or {})
        interaction["completion"] = copy.deepcopy(completion)
        interaction["execution"] = {
            **execution,
            "state": clean_final_status,
            "finished_at": completed_at.isoformat(),
        }
        payload["interaction"] = interaction
        payload["company_work_item_gate_decision_completion"] = copy.deepcopy(
            completion
        )
        payload["interaction_result"] = {
            "message": (
                "Company work-item gate approved."
                if command.action == "approve"
                else "Company work-item gate denied."
            )
        }
        cursor = await db.execute(
            """UPDATE execution_checkpoints
               SET status = ?, payload = ?, updated_at = ?
               WHERE checkpoint_id = ? AND project_id = ?
                 AND checkpoint_type = 'company_work_item_gate'
                 AND status = 'consuming'
                 AND json_extract(payload, '$.interaction.claim.claim_id') = ?
                 AND json_extract(payload, '$.interaction.claim.consumer_id') = ?
                 AND json_extract(payload, '$.interaction.execution.state') = 'ready'
                 AND json_extract(payload, '$.interaction.execution.claim_id') = ?
                 AND json_extract(payload, '$.interaction.execution.consumer_id') = ?""",
            (
                clean_final_status,
                _json_dumps(payload),
                completed_at.isoformat(),
                command.checkpoint_id,
                command.project_id,
                command.claim_id,
                command.consumer_id,
                command.claim_id,
                command.consumer_id,
            ),
        )
        if int(getattr(cursor, "rowcount", 0) or 0) != 1:
            return None
        return self._checkpoint_with(
            checkpoint,
            status=clean_final_status,
            payload=payload,
            updated_at=completed_at,
        )

    async def apply_company_work_item_gate_decision_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        command: CompanyWorkItemGateDecisionCommand,
    ) -> CompanyWorkItemGateDecisionResult:
        """Atomically apply one claimed owner gate decision.

        This is a named boundary rather than an extension of the generic
        controller command: a parked gate has a settled WorkItem attempt and
        its Task credential may have been cleared by a graceful generation
        release.  The checkpoint, settled attempt and live run lease together
        are the authority; no caller-supplied mutations are accepted.
        """

        self._require_db()
        if not context.complete or not command.complete:
            return CompanyWorkItemGateDecisionResult(
                applied=False,
                outcome="invalid",
                conflict_reason="incomplete_identity",
            )
        action = str(command.action or "").strip().lower()
        try:
            command_attempt = int(command.attempt_seq)
            command_gate_attempt = int(command.gate_attempt)
        except (TypeError, ValueError):
            return CompanyWorkItemGateDecisionResult(
                applied=False,
                outcome="invalid",
                conflict_reason="malformed_attempt",
            )
        if (
            context.project_id != str(command.project_id or "").strip()
            or context.run_id != str(command.run_id or "").strip()
            or context.task_id != str(command.task_id or "").strip()
            or context.work_item_id != str(command.work_item_id or "").strip()
            or context.attempt_seq != command_attempt
        ):
            return CompanyWorkItemGateDecisionResult(
                applied=False,
                outcome="conflict",
                action=action,
                conflict_reason="controller_command_mismatch",
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        previous_phases: list[tuple[Phase, DelegationWorkItem]] = []
        persisted_checkpoint: ExecutionCheckpoint | None = None
        persisted_task: Task | None = None
        persisted_items: list[DelegationWorkItem] = []
        target_phase: Phase | None = None
        continuation = ""
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            checkpoint = await self._select_execution_checkpoint(
                command.checkpoint_id,
                project_id=command.project_id,
                checkpoint_type="company_work_item_gate",
                db=transaction_db,
            )
            if checkpoint is None:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="not_found",
                    action=action,
                    conflict_reason="checkpoint_missing",
                )
            checkpoint_payload = copy.deepcopy(dict(checkpoint.payload or {}))
            interaction = self._execution_checkpoint_interaction(
                checkpoint_payload
            )
            decision_record = dict(interaction.get("decision", {}) or {})
            decision_value = decision_record.get("value")
            durable_action = canonical_company_work_item_gate_decision(
                decision_value
            )
            durable_feedback = company_work_item_gate_decision_feedback(
                decision_value
            )
            completion = dict(
                checkpoint_payload.get(
                    "company_work_item_gate_decision_completion", {}
                )
                or {}
            )
            expected_tombstone = {
                "checkpoint_id": command.checkpoint_id,
                "claim_id": command.claim_id,
                "consumer_id": command.consumer_id,
                "final_status": "resolved",
                "action": action,
                "run_id": command.run_id,
                "task_id": command.task_id,
                "work_item_id": command.work_item_id,
                "attempt_seq": command_attempt,
                "gate_attempt": command_gate_attempt,
                "basis_hash": command.basis_hash,
            }
            if checkpoint.status == "resolved":
                duplicate_target_phase: Phase | None = None
                if completion.get("target_phase"):
                    try:
                        duplicate_target_phase = Phase(
                            str(completion.get("target_phase", ""))
                        )
                    except ValueError:
                        duplicate_target_phase = None
                duplicate = bool(
                    durable_action == action
                    and all(
                        completion.get(key) == value
                        for key, value in expected_tombstone.items()
                    )
                    and str(durable_feedback or "")
                    == str(command.feedback or "")
                )
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="duplicate" if duplicate else "conflict",
                    action=action,
                    checkpoint=checkpoint,
                    target_phase=(duplicate_target_phase if duplicate else None),
                    continuation=(
                        str(completion.get("continuation", "") or "")
                        if duplicate
                        else ""
                    ),
                    conflict_reason="" if duplicate else "terminal_mismatch",
                )
            if checkpoint.status != "consuming":
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="checkpoint_not_consuming",
                )
            if durable_action != action or str(durable_feedback or "") != str(
                command.feedback or ""
            ):
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="durable_decision_mismatch",
                )
            claim = dict(interaction.get("claim", {}) or {})
            execution = dict(interaction.get("execution", {}) or {})
            try:
                claim_expiry = datetime.fromisoformat(
                    str(claim.get("lease_expires_at", "") or "")
                )
            except (TypeError, ValueError):
                claim_expiry = datetime.fromtimestamp(0)
            if (
                str(interaction.get("kind", "") or "")
                != "company_work_item_gate"
                or str(claim.get("claim_id", "") or "") != command.claim_id
                or str(claim.get("consumer_id", "") or "")
                != command.consumer_id
                or claim_expiry <= checked_at
                or str(execution.get("state", "") or "") != "ready"
                or str(execution.get("claim_id", "") or "")
                != command.claim_id
                or str(execution.get("consumer_id", "") or "")
                != command.consumer_id
            ):
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="interaction_claim_mismatch",
                )
            if not await self._company_controller_attempt_context_matches(
                transaction_db,
                context,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot consume a company work-item gate"
                )

            gate = copy.deepcopy(dict(checkpoint_payload.get("gate", {}) or {}))
            ownership = dict(interaction.get("ownership", {}) or {})
            try:
                payload_attempt = int(
                    checkpoint_payload.get("work_item_attempt_seq", 0) or 0
                )
                payload_gate_attempt = int(
                    checkpoint_payload.get("gate_attempt", -1)
                )
            except (TypeError, ValueError):
                payload_attempt = -1
                payload_gate_attempt = -1
            payload_identity_matches = bool(
                str(checkpoint.task_id or "").strip() == command.task_id
                and str(checkpoint.project_id or "default").strip()
                == command.project_id
                and str(checkpoint_payload.get("run_id", "") or "").strip()
                == command.run_id
                and str(
                    checkpoint_payload.get("waiting_task_id", "") or ""
                ).strip()
                == command.task_id
                and str(
                    checkpoint_payload.get("waiting_work_item_id", "") or ""
                ).strip()
                == command.work_item_id
                and payload_attempt == command_attempt
                and payload_gate_attempt == command_gate_attempt
                and str(checkpoint_payload.get("basis_hash", "") or "").strip()
                == command.basis_hash
                and str(ownership.get("waiting_task_id", "") or "").strip()
                in {"", command.task_id}
                and bool(gate)
                and _company_work_item_gate_publication_provenance_matches(
                    checkpoint_payload
                )
                and str(
                    dict(
                        checkpoint_payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("checkpoint_id", "")
                    or ""
                ).strip()
                == command.checkpoint_id
                and str(
                    dict(
                        checkpoint_payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("project_id", "")
                    or ""
                ).strip()
                == command.project_id
            )
            if not payload_identity_matches:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="checkpoint_domain_mismatch",
                )

            durable_task = await self._get_task_unhydrated(
                command.task_id,
                db=transaction_db,
            )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (command.work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                durable_item = (
                    self._row_to_delegation_work_item(row, cursor.description)
                    if row is not None
                    else None
                )
            async with transaction_db.execute(
                """SELECT work_item_id FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (command.task_id,),
            ) as cursor:
                link_rows = await cursor.fetchall()
            if durable_task is None or durable_item is None:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="source_missing",
                )
            task_metadata = dict(durable_task.metadata or {})
            item_metadata = dict(durable_item.metadata or {})
            try:
                item_attempt = int(item_metadata.get("attempt_seq", 0) or 0)
                item_generation = int(
                    item_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                task_attempt = int(
                    task_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                )
                task_generation = int(
                    task_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
            except (TypeError, ValueError):
                item_attempt = item_generation = task_attempt = task_generation = -1
            item_owner = str(
                item_metadata.get("company_run_controller_owner_token", "") or ""
            ).strip()
            task_owner = str(
                task_metadata.get("company_run_controller_owner_token", "") or ""
            ).strip()
            task_parked_envelope = bool(
                (not task_owner and task_generation == 0 and task_attempt == 0)
                or (
                    task_owner == item_owner
                    and task_generation == item_generation
                    and task_attempt == item_attempt
                )
            )
            restored_basis_task = copy.deepcopy(durable_task)
            restored_basis_task.metadata = dict(restored_basis_task.metadata or {})
            restored_basis_task.metadata[
                "claimed_work_item_attempt_seq"
            ] = command_attempt
            source_projection_id = projection_id_for_task(durable_task)
            runtime_scope_matches = (
                await self._company_work_item_gate_runtime_scope_matches(
                    transaction_db,
                    payload=checkpoint_payload,
                    source_task=durable_task,
                    run_id=command.run_id,
                    source_projection_id=source_projection_id,
                )
            )
            source_identity_matches = bool(
                durable_task.status == TaskStatus.AWAITING_HUMAN
                and durable_item.phase == Phase.AWAITING_HUMAN
                and str(durable_item.run_id or "").strip() == command.run_id
                and str(task_metadata.get("delegation_run_id", "") or "").strip()
                == command.run_id
                and [str(row[0] or "").strip() for row in link_rows]
                == [command.work_item_id]
                and item_attempt == command_attempt
                and item_metadata.get("attempt_settled") is True
                and not str(
                    durable_item.claimed_by_role_runtime_session_id or ""
                ).strip()
                and not str(durable_item.claimed_by_seat_id or "").strip()
                and item_owner
                and item_generation > 0
                and task_parked_envelope
                and source_projection_id
                == str(durable_item.projection_id or "").strip()
                and company_work_item_gate_attempt(
                    restored_basis_task,
                    dict(gate.get("metadata", {}) or {}),
                )
                == command_gate_attempt
                and company_work_item_gate_basis_hash(restored_basis_task, gate)
                == command.basis_hash
                and _company_work_item_gate_matches_task_metadata(
                    task_metadata,
                    gate,
                )
                and runtime_scope_matches
            )
            if not source_identity_matches:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="source_basis_mismatch",
                )

            gate_policy = WorkItemGatePolicy.from_dict(gate)
            if gate_policy is None:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="invalid",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="gate_policy_missing",
                )
            summary = ""
            if isinstance(durable_task.result, dict):
                summary = str(durable_task.result.get("content", "") or "").strip()
            affected: list[tuple[DelegationWorkItem, Task, Phase]] = []
            decision_audit = {
                "checkpoint_id": command.checkpoint_id,
                "action": action,
                "attempt_seq": command_attempt,
                "gate_attempt": command_gate_attempt,
                "basis_hash": command.basis_hash,
                "decided_at": checked_at.isoformat(),
            }

            if action == "approve":
                routing = plan_company_work_item_done_routing(
                    restored_basis_task,
                    durable_item,
                    summary=summary,
                )
                target_phase = routing.target_phase
                next_item = copy.deepcopy(durable_item)
                next_item.phase = target_phase
                if summary:
                    next_item.summary = summary
                next_item.claimed_by_role_runtime_session_id = ""
                next_item.claimed_by_seat_id = ""
                next_item.metadata = {
                    **dict(next_item.metadata or {}),
                    **copy.deepcopy(routing.work_item_metadata_updates),
                    "claimed_by_role_session_id": "",
                    "claimed_task_id": "",
                    "company_run_controller_owner_token": context.owner_token,
                    "company_run_controller_lease_generation": context.generation,
                    "company_work_item_gate_decision": decision_audit,
                    "last_transition_reason": "company_work_item_gate_approved",
                }
                next_task = copy.deepcopy(restored_basis_task)
                next_task.status = task_status_for_phase(target_phase)
                next_task.metadata = copy.deepcopy(routing.task_metadata)
                next_task.metadata.update(
                    {
                        "company_run_controller_owner_token": context.owner_token,
                        "company_run_controller_lease_generation": context.generation,
                        "claimed_work_item_attempt_seq": command_attempt,
                        "company_work_item_gate_decision": decision_audit,
                    }
                )
                gate_source = str(
                    dict(gate.get("metadata", {}) or {}).get("source", "") or ""
                ).strip()
                if gate_source == "gate_harness":
                    gate_metadata = dict(gate.get("metadata", {}) or {})
                    constraints = [
                        str(item).strip()
                        for item in list(gate_metadata.get("constraints", []) or [])
                        if str(item).strip()
                    ]
                    next_task.metadata.pop("gate_harness_pending_decision", None)
                    next_item.metadata.pop("gate_harness_pending_decision", None)
                    if constraints:
                        next_task.metadata["gate_harness_constraints"] = constraints
                        next_task.metadata["gate_harness_status"] = (
                            "passed_with_constraints"
                        )
                        next_task.metadata["risks"] = list(
                            dict.fromkeys(
                                [
                                    *list(next_task.metadata.get("risks", []) or []),
                                    *constraints,
                                ]
                            )
                        )
                    else:
                        next_task.metadata["gate_harness_status"] = "passed"
                continuation = {
                    Phase.AWAITING_HUMAN: "finalize",
                    Phase.AWAITING_MANAGER_REVIEW: "manager_review",
                    Phase.APPROVED: "refresh_dependents",
                }.get(target_phase, "")
                next_task.metadata["company_work_item_gate_continuation"] = {
                    **decision_audit,
                    "kind": continuation,
                    "target_phase": target_phase.value,
                    "status": "pending",
                }
                progress = list(next_item.metadata.get("progress_log", []) or [])
                progress.append("Human approved the work-item gate.")
                next_item.metadata["progress_log"] = progress[-50:]
                affected.append((next_item, next_task, durable_item.phase))
            else:
                try:
                    rework_count = max(
                        0,
                        int(task_metadata.get("gate_rework_count", 0) or 0),
                    )
                    max_retries = max(0, int(gate_policy.max_retries or 0))
                except (TypeError, ValueError):
                    rework_count = max_retries = 0
                pending_harness = dict(
                    task_metadata.get("gate_harness_pending_decision", {}) or {}
                )
                target_projection_ids = company_gate_rework_target_projection_ids(
                    gate_policy,
                    pending_harness_decision=pending_harness,
                )
                runtime_plan = deserialize_company_work_item_plan(
                    dict(checkpoint_payload.get("company_work_item_plan", {}) or {})
                )
                gate_source = str(
                    dict(gate_policy.metadata or {}).get("source", "") or ""
                ).strip()
                harness_entries = (
                    company_gate_harness_rework_entries(
                        gate_policy,
                        pending_harness_decision=pending_harness,
                        plan=runtime_plan,
                    )
                    if gate_source == "gate_harness"
                    else []
                )
                affected_projection_ids = (
                    [entry[0] for entry in harness_entries]
                    if harness_entries
                    else company_gate_rework_affected_projection_ids(
                        gate_policy,
                        pending_harness_decision=pending_harness,
                        plan=runtime_plan,
                    )
                )
                harness_entry_by_projection = {
                    projection_id: (is_primary, upstream_projection_id)
                    for projection_id, is_primary, upstream_projection_id in harness_entries
                }
                policy_requests_rework = bool(
                    gate_policy.on_reject == "rework"
                    and target_projection_ids
                    and affected_projection_ids
                    and rework_count < max_retries
                )
                can_rework = policy_requests_rework
                target_rows: list[tuple[DelegationWorkItem, Task]] = []
                if can_rework:
                    for projection_id in affected_projection_ids:
                        async with transaction_db.execute(
                            """SELECT * FROM delegation_work_items
                               WHERE run_id = ? AND projection_id = ?""",
                            (command.run_id, projection_id),
                        ) as cursor:
                            rows = await cursor.fetchall()
                            description = cursor.description
                        if len(rows) != 1:
                            can_rework = False
                            break
                        target_item = self._row_to_delegation_work_item(
                            rows[0], description
                        )
                        async with transaction_db.execute(
                            """SELECT runtime_task_id
                               FROM work_item_runtime_links
                               WHERE work_item_id = ?""",
                            (target_item.work_item_id,),
                        ) as cursor:
                            target_links = await cursor.fetchall()
                        if len(target_links) != 1:
                            can_rework = False
                            break
                        target_task = await self._get_task_unhydrated(
                            str(target_links[0][0] or "").strip(),
                            db=transaction_db,
                        )
                        if target_task is None:
                            can_rework = False
                            break
                        if target_item.work_item_id == durable_item.work_item_id:
                            if target_task.id != durable_task.id:
                                can_rework = False
                                break
                            target_rows.append(
                                (durable_item, restored_basis_task)
                            )
                            continue

                        target_metadata = dict(target_item.metadata or {})
                        target_task_metadata = dict(target_task.metadata or {})
                        try:
                            target_attempt = int(
                                target_metadata.get("attempt_seq", 0) or 0
                            )
                            target_generation = int(
                                target_metadata.get(
                                    "company_run_controller_lease_generation",
                                    0,
                                )
                                or 0
                            )
                            target_task_attempt = int(
                                target_task_metadata.get(
                                    "claimed_work_item_attempt_seq",
                                    0,
                                )
                                or 0
                            )
                            target_task_generation = int(
                                target_task_metadata.get(
                                    "company_run_controller_lease_generation",
                                    0,
                                )
                                or 0
                            )
                        except (TypeError, ValueError):
                            target_attempt = target_generation = -1
                            target_task_attempt = target_task_generation = -1
                        target_owner = str(
                            target_metadata.get(
                                "company_run_controller_owner_token", ""
                            )
                            or ""
                        ).strip()
                        target_task_owner = str(
                            target_task_metadata.get(
                                "company_run_controller_owner_token", ""
                            )
                            or ""
                        ).strip()
                        target_item_controller_envelope = bool(
                            (
                                not target_owner
                                and target_generation == 0
                            )
                            or (
                                bool(target_owner)
                                and target_generation > 0
                            )
                        )
                        target_task_parked_envelope = bool(
                            (
                                not target_owner
                                and target_generation == 0
                                and not target_task_owner
                                and target_task_generation == 0
                                and target_task_attempt == 0
                            )
                            or (
                                bool(target_owner)
                                and target_generation > 0
                                and (
                                    (
                                        not target_task_owner
                                        and target_task_generation == 0
                                        and target_task_attempt == 0
                                    )
                                    or (
                                        target_task_owner == target_owner
                                        and target_task_generation
                                        == target_generation
                                        and target_task_attempt == target_attempt
                                    )
                                )
                            )
                        )
                        async with transaction_db.execute(
                            """SELECT work_item_id
                               FROM work_item_runtime_links
                               WHERE runtime_task_id = ?""",
                            (target_task.id,),
                        ) as cursor:
                            target_reverse_links = await cursor.fetchall()
                        active_statuses = tuple(
                            sorted(OWNER_INTERACTION_ACTIVE_STATUSES)
                        )
                        active_placeholders = ", ".join(
                            "?" for _ in active_statuses
                        )
                        async with transaction_db.execute(
                            f"""SELECT checkpoint_id
                                FROM execution_checkpoints
                                WHERE project_id = ?
                                  AND status IN ({active_placeholders})
                                  AND (
                                      task_id = ?
                                      OR json_extract(
                                          payload, '$.waiting_task_id'
                                      ) = ?
                                      OR json_extract(
                                          payload,
                                          '$.interaction.ownership.waiting_task_id'
                                      ) = ?
                                  )
                                LIMIT 1""",
                            (
                                command.project_id,
                                *active_statuses,
                                target_task.id,
                                target_task.id,
                                target_task.id,
                            ),
                        ) as cursor:
                            active_target_checkpoint = await cursor.fetchone()
                        done_phase_values = tuple(
                            sorted(phase.value for phase in DONE_PHASES)
                        )
                        done_placeholders = ", ".join(
                            "?" for _ in done_phase_values
                        )
                        async with transaction_db.execute(
                            f"""SELECT work_item_id
                                FROM delegation_work_items
                                WHERE run_id = ?
                                  AND work_item_id != ?
                                  AND phase NOT IN ({done_placeholders})
                                  AND (
                                      json_extract(
                                          metadata,
                                          '$.report_target_work_item_id'
                                      ) = ?
                                      OR json_extract(
                                          metadata,
                                          '$.review_target_work_item_id'
                                      ) = ?
                                  )
                                LIMIT 1""",
                            (
                                command.run_id,
                                target_item.work_item_id,
                                *done_phase_values,
                                target_item.work_item_id,
                                target_item.work_item_id,
                            ),
                        ) as cursor:
                            active_target_auxiliary = await cursor.fetchone()
                        target_identity_matches = bool(
                            target_task.project_id == command.project_id
                            and target_item.phase == Phase.APPROVED
                            and target_task.status
                            == task_status_for_phase(target_item.phase)
                            and str(target_item.run_id or "").strip()
                            == command.run_id
                            and str(
                                target_task_metadata.get(
                                    "delegation_run_id", ""
                                )
                                or ""
                            ).strip()
                            == command.run_id
                            and str(target_item.projection_id or "").strip()
                            == projection_id
                            and projection_id_for_task(target_task)
                            == projection_id
                            and [
                                str(row[0] or "").strip()
                                for row in target_reverse_links
                            ]
                            == [target_item.work_item_id]
                            and target_attempt > 0
                            and target_metadata.get("attempt_settled") is True
                            and not str(
                                target_item.claimed_by_role_runtime_session_id
                                or ""
                            ).strip()
                            and not str(
                                target_item.claimed_by_seat_id or ""
                            ).strip()
                            and target_item_controller_envelope
                            and target_generation <= context.generation
                            and target_task_parked_envelope
                            and not str(
                                target_metadata.get("dispatch_hold", "") or ""
                            ).strip()
                            and not str(
                                target_task_metadata.get("dispatch_hold", "")
                                or ""
                            ).strip()
                            and str(
                                target_task_metadata.get(
                                    "company_runtime_stop_state", ""
                                )
                                or ""
                            ).strip()
                            not in {"suspending", "suspended"}
                            and active_target_checkpoint is None
                            and active_target_auxiliary is None
                        )
                        if not target_identity_matches:
                            can_rework = False
                            target_rows.clear()
                            break
                        target_rows.append((target_item, target_task))
                if policy_requests_rework and not can_rework:
                    await transaction_db.rollback()
                    return CompanyWorkItemGateDecisionResult(
                        applied=False,
                        outcome="conflict",
                        action=action,
                        checkpoint=checkpoint,
                        conflict_reason="rework_target_envelope_mismatch",
                    )
                if can_rework:
                    if all(
                        item.work_item_id != durable_item.work_item_id
                        for item, _task in target_rows
                    ):
                        target_rows.insert(0, (durable_item, restored_basis_task))
                    feedback = str(command.feedback or "").strip()[:12000]
                    if not feedback:
                        feedback = (
                            f"{durable_task.title} was denied at its work-item gate."
                        )
                    rework_round = rework_count + 1
                    rework_request = build_company_gate_rework_record(
                        review_task=restored_basis_task,
                        gate=gate_policy,
                        reviewer_feedback=feedback,
                        rework_round=rework_round,
                        requested_at=checked_at,
                    )
                    seen_work_item_ids: set[str] = set()
                    for current_item, current_task in target_rows:
                        if current_item.work_item_id in seen_work_item_ids:
                            continue
                        seen_work_item_ids.add(current_item.work_item_id)
                        next_item = copy.deepcopy(current_item)
                        next_task = copy.deepcopy(current_task)
                        next_item.phase = Phase.READY_FOR_REWORK
                        next_item.deliverable_summary = ""
                        next_item.blocked_reason = ""
                        next_item.claimed_by_role_runtime_session_id = ""
                        next_item.claimed_by_seat_id = ""
                        next_item.metadata = dict(next_item.metadata or {})
                        next_item.metadata.update(
                            {
                                "claimed_by_role_session_id": "",
                                "claimed_task_id": "",
                                "gate_review_feedback": feedback,
                                "gate_review_feedback_full": str(
                                    command.feedback or ""
                                ).strip(),
                                "gate_instructions": gate_policy.instructions,
                                "gate_rework_round": rework_round,
                                "gate_rework_request": copy.deepcopy(
                                    rework_request
                                ),
                                "company_work_item_gate_decision": decision_audit,
                                "last_transition_reason": (
                                    "company_work_item_gate_denied_rework"
                                ),
                            }
                        )
                        for key in COMPANY_REWORK_OUTPUT_METADATA_KEYS:
                            next_item.metadata.pop(key, None)
                        if current_item.work_item_id == durable_item.work_item_id:
                            next_item.metadata.update(
                                {
                                    "gate_rework_count": rework_round,
                                    "last_gate_review_feedback": feedback,
                                    "last_gate_review_feedback_full": str(
                                        command.feedback or ""
                                    ).strip(),
                                    "last_gate_rework_request": copy.deepcopy(
                                        rework_request
                                    ),
                                }
                            )
                        next_item.metadata.pop(
                            "gate_harness_pending_decision", None
                        )
                        next_task.status = TaskStatus.PENDING
                        next_task.result = None
                        next_task.metadata = dict(next_task.metadata or {})
                        for key in COMPANY_REWORK_OUTPUT_METADATA_KEYS:
                            next_task.metadata.pop(key, None)
                        next_task.metadata.update(
                            {
                                "gate_review_feedback": feedback,
                                "gate_review_feedback_full": str(
                                    command.feedback or ""
                                ).strip(),
                                "gate_instructions": gate_policy.instructions,
                                "gate_rework_round": rework_round,
                                "gate_rework_request": copy.deepcopy(
                                    rework_request
                                ),
                                "company_work_item_gate_decision": decision_audit,
                            }
                        )
                        current_projection_id = str(
                            current_item.projection_id
                            or projection_id_for_task(current_task)
                            or ""
                        ).strip()
                        harness_entry = harness_entry_by_projection.get(
                            current_projection_id
                        )
                        if harness_entry is not None:
                            is_primary, upstream_projection_id = harness_entry
                            if is_primary:
                                try:
                                    harness_round = int(
                                        (current_task.metadata or {}).get(
                                            "gate_harness_rework_count", 0
                                        )
                                        or 0
                                    ) + 1
                                except (TypeError, ValueError):
                                    harness_round = 1
                                harness_request = (
                                    build_company_gate_harness_rework_record(
                                        source_task=restored_basis_task,
                                        target_task=current_task,
                                        decision=pending_harness,
                                        rework_round=harness_round,
                                        requested_at=checked_at,
                                    )
                                )
                                next_task.metadata.update(
                                    {
                                        "gate_harness_rework_count": harness_round,
                                        "gate_harness_rework_feedback": str(
                                            pending_harness.get("summary", "")
                                            or ""
                                        ).strip(),
                                        "gate_harness_rework_request": copy.deepcopy(
                                            harness_request
                                        ),
                                    }
                                )
                                harness_history = list(
                                    next_task.metadata.get(
                                        "gate_harness_rework_requests", []
                                    )
                                    or []
                                )
                                harness_history.append(
                                    copy.deepcopy(harness_request)
                                )
                                next_task.metadata[
                                    "gate_harness_rework_requests"
                                ] = harness_history[-6:]
                                next_task.context_snapshot = dict(
                                    next_task.context_snapshot or {}
                                )
                                next_task.context_snapshot[
                                    "latest_gate_harness_rework"
                                ] = copy.deepcopy(harness_request)
                            else:
                                next_task.metadata[
                                    "upstream_gate_harness_rework_source_projection_id"
                                ] = upstream_projection_id
                                adaptive = dict(
                                    next_task.metadata.get("adaptive", {}) or {}
                                )
                                adaptive["normalized_state"] = "invalidated"
                                next_task.metadata["adaptive"] = adaptive
                                next_task.context_snapshot = dict(
                                    next_task.context_snapshot or {}
                                )
                                next_task.context_snapshot[
                                    "upstream_gate_harness_rework_source_projection_id"
                                ] = upstream_projection_id
                        if current_item.work_item_id == durable_item.work_item_id:
                            next_task.metadata.update(
                                {
                                    "gate_rework_count": rework_round,
                                    "last_gate_review_feedback": feedback,
                                    "last_gate_review_feedback_full": str(
                                        command.feedback or ""
                                    ).strip(),
                                    "last_gate_rework_request": copy.deepcopy(
                                        rework_request
                                    ),
                                }
                            )
                        next_task.metadata.pop(
                            "company_run_controller_owner_token", None
                        )
                        next_task.metadata.pop(
                            "company_run_controller_lease_generation", None
                        )
                        next_task.metadata.pop(
                            "claimed_work_item_attempt_seq", None
                        )
                        if current_item.work_item_id != durable_item.work_item_id:
                            next_task.metadata.pop(
                                "company_work_item_gate_continuation", None
                            )
                        next_task.context_snapshot = dict(
                            next_task.context_snapshot or {}
                        )
                        owned_outputs = dict(
                            next_task.context_snapshot.get(
                                "work_item_owned_outputs", {}
                            )
                            or {}
                        )
                        for key in COMPANY_REWORK_OUTPUT_METADATA_KEYS:
                            owned_outputs.pop(key, None)
                        if owned_outputs:
                            next_task.context_snapshot[
                                "work_item_owned_outputs"
                            ] = owned_outputs
                        else:
                            next_task.context_snapshot.pop(
                                "work_item_owned_outputs", None
                            )
                        next_task.context_snapshot[
                            "latest_gate_rework"
                        ] = copy.deepcopy(rework_request)
                        next_item.updated_at = checked_at
                        affected.append(
                            (next_item, next_task, current_item.phase)
                        )
                    target_phase = Phase.READY_FOR_REWORK
                    continuation = "dispatch_rework"
                else:
                    next_item = copy.deepcopy(durable_item)
                    next_task = copy.deepcopy(restored_basis_task)
                    next_item.phase = Phase.FAILED
                    next_item.claimed_by_role_runtime_session_id = ""
                    next_item.claimed_by_seat_id = ""
                    next_item.metadata = dict(next_item.metadata or {})
                    next_item.metadata.update(
                        {
                            "claimed_by_role_session_id": "",
                            "claimed_task_id": "",
                            "last_gate_review_feedback": str(
                                command.feedback or ""
                            ).strip(),
                            "company_work_item_gate_decision": decision_audit,
                            "last_transition_reason": (
                                "company_work_item_gate_denied_halt"
                            ),
                        }
                    )
                    next_item.metadata.pop("gate_harness_pending_decision", None)
                    next_task.status = task_status_for_phase(next_item.phase)
                    next_task.metadata = dict(next_task.metadata or {})
                    next_task.metadata.update(
                        {
                            "last_gate_review_feedback": str(
                                command.feedback or ""
                            ).strip(),
                            "company_work_item_gate_decision": decision_audit,
                        }
                    )
                    next_task.metadata.pop(
                        "gate_harness_pending_decision", None
                    )
                    next_item.updated_at = checked_at
                    target_phase = Phase.FAILED
                    continuation = "failure_settlement"
                    affected.append((next_item, next_task, durable_item.phase))

            for next_item, next_task, _previous_phase in affected:
                if next_item.work_item_id != durable_item.work_item_id:
                    continue
                next_task.metadata = dict(next_task.metadata or {})
                next_task.metadata["company_work_item_gate_continuation"] = {
                    **decision_audit,
                    "kind": continuation,
                    "target_phase": target_phase.value if target_phase else "",
                    "status": "pending",
                }

            for next_item, next_task, previous_phase in affected:
                next_item.updated_at = checked_at
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, summary = ?, deliverable_summary = ?, blocked_reason = ?,
                           claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?
                         AND phase = ? AND updated_at = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = delegation_work_items.run_id
                               AND run.project_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        next_item.phase.value,
                        next_item.summary,
                        next_item.deliverable_summary,
                        next_item.blocked_reason,
                        _json_dumps(next_item.metadata),
                        checked_at.isoformat(),
                        next_item.work_item_id,
                        command.run_id,
                        previous_phase.value,
                        (
                            durable_item.updated_at.isoformat()
                            if next_item.work_item_id == durable_item.work_item_id
                            else next(
                                current.updated_at.isoformat()
                                for current, _task in target_rows
                                if current.work_item_id == next_item.work_item_id
                            )
                        ),
                        command.project_id,
                        context.owner_token,
                        context.generation,
                        checked_at.isoformat(),
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return CompanyWorkItemGateDecisionResult(
                        applied=False,
                        outcome="conflict",
                        action=action,
                        checkpoint=checkpoint,
                        conflict_reason="work_item_cas_lost",
                    )
                await self._save_task_row(
                    next_task,
                    commit=False,
                    db=transaction_db,
                )
                previous_phases.append((previous_phase, next_item))
                persisted_items.append(copy.deepcopy(next_item))
                if next_item.work_item_id == durable_item.work_item_id:
                    persisted_task = copy.deepcopy(next_task)

            completion_payload = {
                **expected_tombstone,
                "feedback": durable_feedback,
                "target_phase": target_phase.value if target_phase else "",
                "continuation": continuation,
                "finished_at": checked_at.isoformat(),
            }
            persisted_checkpoint = (
                await self._complete_company_work_item_gate_checkpoint_in_transaction(
                    transaction_db,
                    checkpoint=checkpoint,
                    command=command,
                    payload=checkpoint_payload,
                    completion=completion_payload,
                    completed_at=checked_at,
                )
            )
            if persisted_checkpoint is None:
                await transaction_db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="checkpoint_cas_lost",
                )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        for previous_phase, item in previous_phases:
            try:
                await on_phase_transition(
                    previous_phase,
                    item.phase,
                    item,
                    store=self,
                    notifications_only=True,
                )
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                logger.opt(exception=True).warning(
                    "gate decision committed but phase notification failed "
                    "work_item={}",
                    item.work_item_id,
                )
        return CompanyWorkItemGateDecisionResult(
            applied=True,
            outcome="applied",
            action=action,
            task=persisted_task,
            work_items=tuple(persisted_items),
            checkpoint=persisted_checkpoint,
            target_phase=target_phase,
            continuation=continuation,
        )

    async def invalidate_company_work_item_gate_decision_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        command: CompanyWorkItemGateDecisionCommand,
        *,
        conflict_reason: str,
    ) -> CompanyWorkItemGateDecisionResult:
        """Atomically fail closed one permanently invalid gate decision.

        Controller/claim/CAS races never enter this boundary.  When the
        checkpoint can still be bound to its exact parked source attempt, the
        source is failed in the same transaction and receives a durable
        failure-settlement continuation.  If a newer gate is active, or the
        source envelope cannot be proven, only the exact claimed checkpoint is
        invalidated; startup orphan reconciliation remains responsible for an
        otherwise-unowned parked source.
        """

        permanent_reasons = {
            "controller_command_mismatch",
            "durable_decision_mismatch",
            "checkpoint_domain_mismatch",
            "source_missing",
            "source_basis_mismatch",
            "gate_policy_missing",
            "rework_target_envelope_mismatch",
        }
        clean_reason = str(conflict_reason or "").strip()
        if (
            not context.complete
            or not command.complete
            or clean_reason not in permanent_reasons
            or context.project_id != str(command.project_id or "").strip()
            or context.run_id != str(command.run_id or "").strip()
            or context.task_id != str(command.task_id or "").strip()
            or context.work_item_id
            != str(command.work_item_id or "").strip()
            or context.attempt_seq != int(command.attempt_seq)
        ):
            return CompanyWorkItemGateDecisionResult(
                applied=False,
                outcome="conflict",
                action=str(command.action or "").strip().lower(),
                conflict_reason="invalid_invalidation_request",
            )

        action = str(command.action or "").strip().lower()
        db = _SQLiteConnectionAdapter(self.db_path)
        persisted_checkpoint: ExecutionCheckpoint | None = None
        persisted_task: Task | None = None
        persisted_item: DelegationWorkItem | None = None
        previous_phase: Phase | None = None
        continuation = ""
        target_phase: Phase | None = None
        try:
            await db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            checkpoint = await self._select_execution_checkpoint(
                command.checkpoint_id,
                project_id=command.project_id,
                checkpoint_type="company_work_item_gate",
                db=db,
            )
            if checkpoint is None or checkpoint.status != "consuming":
                await db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="checkpoint_not_consuming",
                )
            payload = copy.deepcopy(dict(checkpoint.payload or {}))
            interaction = self._execution_checkpoint_interaction(payload)
            ownership = dict(interaction.get("ownership", {}) or {})
            try:
                payload_attempt = int(
                    payload.get("work_item_attempt_seq", 0) or 0
                )
                payload_gate_attempt = int(payload.get("gate_attempt", -1))
            except (TypeError, ValueError):
                payload_attempt = payload_gate_attempt = -1
            payload_identity_matches = bool(
                str(checkpoint.project_id or "default").strip()
                == command.project_id
                and str(checkpoint.task_id or "").strip() == command.task_id
                and str(payload.get("run_id", "") or "").strip()
                == command.run_id
                and str(payload.get("waiting_task_id", "") or "").strip()
                == command.task_id
                and str(payload.get("waiting_work_item_id", "") or "").strip()
                == command.work_item_id
                and payload_attempt == int(command.attempt_seq)
                and payload_gate_attempt == int(command.gate_attempt)
                and str(payload.get("basis_hash", "") or "").strip()
                == command.basis_hash
                and str(ownership.get("waiting_task_id", "") or "").strip()
                in {"", command.task_id}
                and _company_work_item_gate_publication_provenance_matches(
                    payload
                )
                and str(
                    dict(
                        payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("checkpoint_id", "")
                    or ""
                ).strip()
                == command.checkpoint_id
                and str(
                    dict(
                        payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    ).get("project_id", "")
                    or ""
                ).strip()
                == command.project_id
            )
            if not payload_identity_matches:
                await db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="invalidation_scope_mismatch",
                )
            decision_value = dict(
                dict(interaction.get("decision", {}) or {}).get("value", {})
                or {}
            )
            claim = dict(interaction.get("claim", {}) or {})
            execution = dict(interaction.get("execution", {}) or {})
            try:
                claim_expiry = datetime.fromisoformat(
                    str(claim.get("lease_expires_at", "") or "")
                )
            except (TypeError, ValueError):
                claim_expiry = datetime.fromtimestamp(0)
            if not (
                canonical_company_work_item_gate_decision(decision_value)
                == action
                and company_work_item_gate_decision_feedback(decision_value)
                == str(command.feedback or "")
                and str(claim.get("claim_id", "") or "") == command.claim_id
                and str(claim.get("consumer_id", "") or "")
                == command.consumer_id
                and claim_expiry > checked_at
                and str(execution.get("state", "") or "") == "ready"
                and str(execution.get("claim_id", "") or "")
                == command.claim_id
                and str(execution.get("consumer_id", "") or "")
                == command.consumer_id
            ):
                await db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="interaction_claim_mismatch",
                )
            async with db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    context.run_id,
                    context.project_id,
                    context.owner_token,
                    context.generation,
                    checked_at.isoformat(),
                ),
            ) as run_cursor:
                controller_live = await run_cursor.fetchone() is not None
            if not controller_live:
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot invalidate a company gate"
                )

            durable_task = await self._get_task_unhydrated(
                str(checkpoint.task_id or "").strip(),
                db=db,
            )
            async with db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (command.work_item_id,),
            ) as item_cursor:
                item_row = await item_cursor.fetchone()
                durable_item = (
                    self._row_to_delegation_work_item(
                        item_row, item_cursor.description
                    )
                    if item_row is not None
                    else None
                )
            async with db.execute(
                """SELECT work_item_id FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (str(checkpoint.task_id or "").strip(),),
            ) as link_cursor:
                link_rows = await link_cursor.fetchall()

            source_envelope_matches = False
            if durable_task is not None and durable_item is not None:
                task_metadata = dict(durable_task.metadata or {})
                item_metadata = dict(durable_item.metadata or {})
                try:
                    item_attempt = int(
                        item_metadata.get("attempt_seq", 0) or 0
                    )
                    item_generation = int(
                        item_metadata.get(
                            "company_run_controller_lease_generation", 0
                        )
                        or 0
                    )
                    task_attempt = int(
                        task_metadata.get("claimed_work_item_attempt_seq", 0)
                        or 0
                    )
                    task_generation = int(
                        task_metadata.get(
                            "company_run_controller_lease_generation", 0
                        )
                        or 0
                    )
                except (TypeError, ValueError):
                    item_attempt = item_generation = -1
                    task_attempt = task_generation = -1
                item_owner = str(
                    item_metadata.get(
                        "company_run_controller_owner_token", ""
                    )
                    or ""
                ).strip()
                task_owner = str(
                    task_metadata.get(
                        "company_run_controller_owner_token", ""
                    )
                    or ""
                ).strip()
                task_parked = bool(
                    (not task_owner and task_generation == 0 and task_attempt == 0)
                    or (
                        task_owner == item_owner
                        and task_generation == item_generation
                        and task_attempt == item_attempt
                    )
                )
                has_gate_provenance = bool(
                    isinstance(task_metadata.get("work_item_gate"), dict)
                    or isinstance(
                        task_metadata.get("gate_harness_pending_decision"),
                        dict,
                    )
                )
                source_envelope_matches = bool(
                    str(checkpoint.task_id or "").strip() == command.task_id
                    and durable_task.id == command.task_id
                    and durable_task.project_id == command.project_id
                    and durable_task.status == TaskStatus.AWAITING_HUMAN
                    and durable_item.phase == Phase.AWAITING_HUMAN
                    and str(durable_item.run_id or "").strip()
                    == command.run_id
                    and str(task_metadata.get("delegation_run_id", "") or "").strip()
                    == command.run_id
                    and [str(row[0] or "").strip() for row in link_rows]
                    == [command.work_item_id]
                    and str(durable_item.projection_id or "").strip()
                    == projection_id_for_task(durable_task)
                    and item_attempt == command.attempt_seq
                    and item_metadata.get("attempt_settled") is True
                    and not str(
                        durable_item.claimed_by_role_runtime_session_id or ""
                    ).strip()
                    and not str(durable_item.claimed_by_seat_id or "").strip()
                    and item_owner
                    and item_generation > 0
                    and task_parked
                    and has_gate_provenance
                    and not dict(
                        task_metadata.get(
                            "company_work_item_gate_continuation", {}
                        )
                        or {}
                    )
                )

            active_statuses = tuple(sorted(OWNER_INTERACTION_ACTIVE_STATUSES))
            active_placeholders = ", ".join("?" for _ in active_statuses)
            async with db.execute(
                f"""SELECT checkpoint_id
                    FROM execution_checkpoints
                    WHERE project_id = ?
                      AND checkpoint_type = 'company_work_item_gate'
                      AND checkpoint_id != ?
                      AND status IN ({active_placeholders})
                      AND (
                          task_id = ?
                          OR json_extract(payload, '$.waiting_task_id') = ?
                      )""",
                (
                    command.project_id,
                    command.checkpoint_id,
                    *active_statuses,
                    command.task_id,
                    command.task_id,
                ),
            ) as replacement_cursor:
                replacement_rows = await replacement_cursor.fetchall()
            source_should_fail = bool(
                source_envelope_matches and not replacement_rows
            )

            completion = {
                "checkpoint_id": command.checkpoint_id,
                "claim_id": command.claim_id,
                "consumer_id": command.consumer_id,
                "final_status": "invalid",
                "action": action,
                "run_id": command.run_id,
                "task_id": command.task_id,
                "work_item_id": command.work_item_id,
                "attempt_seq": int(command.attempt_seq),
                "gate_attempt": int(command.gate_attempt),
                "basis_hash": command.basis_hash,
                "conflict_reason": clean_reason,
                "target_phase": Phase.FAILED.value if source_should_fail else "",
                "continuation": (
                    "failure_settlement" if source_should_fail else ""
                ),
                "finished_at": checked_at.isoformat(),
            }
            if source_should_fail:
                assert durable_task is not None and durable_item is not None
                previous_phase = durable_item.phase
                next_item = copy.deepcopy(durable_item)
                next_task = copy.deepcopy(durable_task)
                failure = {
                    "checkpoint_id": command.checkpoint_id,
                    "conflict_reason": clean_reason,
                    "failed_at": checked_at.isoformat(),
                    "attempt_seq": int(command.attempt_seq),
                    "gate_attempt": int(command.gate_attempt),
                    "basis_hash": command.basis_hash,
                }
                next_item.phase = Phase.FAILED
                next_item.claimed_by_role_runtime_session_id = ""
                next_item.claimed_by_seat_id = ""
                next_item.metadata = dict(next_item.metadata or {})
                next_item.metadata.update(
                    {
                        "claimed_by_role_session_id": "",
                        "claimed_task_id": "",
                        "last_transition_reason": (
                            "company_work_item_gate_invalidated"
                        ),
                        "company_work_item_gate_failure": failure,
                        "company_run_controller_owner_token": context.owner_token,
                        "company_run_controller_lease_generation": context.generation,
                    }
                )
                next_task.status = task_status_for_phase(next_item.phase)
                next_task.metadata = dict(next_task.metadata or {})
                next_task.metadata.update(
                    {
                        "company_work_item_gate_failure": failure,
                        "company_run_controller_owner_token": context.owner_token,
                        "company_run_controller_lease_generation": context.generation,
                        "claimed_work_item_attempt_seq": int(command.attempt_seq),
                        "company_work_item_gate_continuation": {
                            **completion,
                            "kind": "failure_settlement",
                            "status": "pending",
                        },
                    }
                )
                cursor = await db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?
                         AND phase = ? AND updated_at = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = delegation_work_items.run_id
                               AND run.project_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        Phase.FAILED.value,
                        _json_dumps(next_item.metadata),
                        checked_at.isoformat(),
                        next_item.work_item_id,
                        command.run_id,
                        Phase.AWAITING_HUMAN.value,
                        durable_item.updated_at.isoformat(),
                        command.project_id,
                        context.owner_token,
                        context.generation,
                        checked_at.isoformat(),
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await db.rollback()
                    return CompanyWorkItemGateDecisionResult(
                        applied=False,
                        outcome="conflict",
                        action=action,
                        checkpoint=checkpoint,
                        conflict_reason="work_item_cas_lost",
                    )
                await self._save_task_row(next_task, commit=False, db=db)
                persisted_task = copy.deepcopy(next_task)
                persisted_item = copy.deepcopy(next_item)
                continuation = "failure_settlement"
                target_phase = Phase.FAILED

            persisted_checkpoint = (
                await self._complete_company_work_item_gate_checkpoint_in_transaction(
                    db,
                    checkpoint=checkpoint,
                    command=command,
                    payload=payload,
                    completion=completion,
                    completed_at=checked_at,
                    final_status="invalid",
                )
            )
            if persisted_checkpoint is None:
                await db.rollback()
                return CompanyWorkItemGateDecisionResult(
                    applied=False,
                    outcome="conflict",
                    action=action,
                    checkpoint=checkpoint,
                    conflict_reason="checkpoint_cas_lost",
                )
            await db.commit()
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

        if persisted_item is not None and previous_phase is not None:
            try:
                await on_phase_transition(
                    previous_phase,
                    persisted_item.phase,
                    persisted_item,
                    store=self,
                    notifications_only=True,
                )
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                logger.opt(exception=True).warning(
                    "gate invalidation committed but phase notification failed "
                    "work_item={}",
                    persisted_item.work_item_id,
                )
        return CompanyWorkItemGateDecisionResult(
            applied=True,
            outcome="invalidated",
            action=action,
            task=persisted_task,
            work_items=((persisted_item,) if persisted_item is not None else ()),
            checkpoint=persisted_checkpoint,
            target_phase=target_phase,
            continuation=continuation,
            conflict_reason=clean_reason,
        )

    async def adopt_company_work_item_gate_continuation_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        *,
        checkpoint_id: str,
        continuation_kind: str = "finalize",
    ) -> Task | None:
        """Adopt one exact resolved gate continuation into the live generation."""

        clean_kind = str(continuation_kind or "").strip()
        expected_phase_by_kind = {
            "finalize": Phase.AWAITING_HUMAN,
            "manager_review": Phase.AWAITING_MANAGER_REVIEW,
            "refresh_dependents": Phase.APPROVED,
            "dispatch_rework": Phase.READY_FOR_REWORK,
            "failure_settlement": Phase.FAILED,
        }
        expected_action_by_kind = {
            "finalize": "approve",
            "manager_review": "approve",
            "refresh_dependents": "approve",
            "dispatch_rework": "deny",
            "failure_settlement": "deny",
        }
        expected_phase = expected_phase_by_kind.get(clean_kind)
        if (
            not context.complete
            or not str(checkpoint_id or "").strip()
            or expected_phase is None
        ):
            return None
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            if not await self._company_controller_attempt_context_matches(
                transaction_db,
                context,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot adopt gate continuation"
                )
            checkpoint = await self._select_execution_checkpoint(
                str(checkpoint_id).strip(),
                project_id=context.project_id,
                checkpoint_type="company_work_item_gate",
                db=transaction_db,
            )
            task = await self._get_task_unhydrated(
                context.task_id,
                db=transaction_db,
            )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (context.work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                item = (
                    self._row_to_delegation_work_item(row, cursor.description)
                    if row is not None
                    else None
                )
            if checkpoint is None or task is None or item is None:
                await transaction_db.rollback()
                return None
            completion = dict(
                dict(checkpoint.payload or {}).get(
                    "company_work_item_gate_decision_completion", {}
                )
                or {}
            )
            marker = dict(
                (task.metadata or {}).get(
                    "company_work_item_gate_continuation", {}
                )
                or {}
            )
            task_metadata = dict(task.metadata or {})
            item_metadata = dict(item.metadata or {})
            try:
                item_attempt = int(item_metadata.get("attempt_seq", 0) or 0)
                item_generation = int(
                    item_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                task_attempt = int(
                    task_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                )
                task_generation = int(
                    task_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                completion_attempt = int(
                    completion.get("attempt_seq", 0) or 0
                )
            except (TypeError, ValueError):
                item_attempt = item_generation = -1
                task_attempt = task_generation = completion_attempt = -1
            item_owner = str(
                item_metadata.get("company_run_controller_owner_token", "")
                or ""
            ).strip()
            task_owner = str(
                task_metadata.get("company_run_controller_owner_token", "")
                or ""
            ).strip()
            parked_envelope = bool(
                (not task_owner and task_generation == 0 and task_attempt == 0)
                or (
                    task_owner == item_owner
                    and task_generation == item_generation
                    and task_attempt == item_attempt
                )
            )
            async with transaction_db.execute(
                """SELECT work_item_id FROM work_item_runtime_links
                   WHERE runtime_task_id = ?""",
                (context.task_id,),
            ) as cursor:
                links = await cursor.fetchall()
            identity_keys = (
                "checkpoint_id",
                "action",
                "attempt_seq",
                "gate_attempt",
                "basis_hash",
                "target_phase",
            )
            checkpoint_continuation_matches = bool(
                (
                    checkpoint.status == "resolved"
                    and completion.get("action")
                    == expected_action_by_kind[clean_kind]
                )
                or (
                    checkpoint.status == "invalid"
                    and clean_kind == "failure_settlement"
                    and str(completion.get("final_status", "") or "").strip()
                    == "invalid"
                    and completion.get("action") in {
                        "approve",
                        "deny",
                        "invalid",
                    }
                )
            )
            if not (
                checkpoint_continuation_matches
                and completion.get("continuation") == clean_kind
                and str(completion.get("checkpoint_id", "") or "")
                == str(checkpoint_id).strip()
                and str(completion.get("run_id", "") or "") == context.run_id
                and str(completion.get("task_id", "") or "") == context.task_id
                and str(completion.get("work_item_id", "") or "")
                == context.work_item_id
                and completion_attempt == context.attempt_seq
                and str(marker.get("kind", "") or "") == clean_kind
                and str(marker.get("status", "") or "") == "pending"
                and all(
                    marker.get(key) == completion.get(key)
                    for key in identity_keys
                )
                and item.phase == expected_phase
                and task.status == task_status_for_phase(expected_phase)
                and str(item.run_id or "").strip() == context.run_id
                and str(task_metadata.get("delegation_run_id", "") or "").strip()
                == context.run_id
                and [str(row[0] or "").strip() for row in links]
                == [context.work_item_id]
                and projection_id_for_task(task)
                == str(item.projection_id or "").strip()
                and item_attempt == context.attempt_seq
                and item_metadata.get("attempt_settled") is True
                and not str(
                    item.claimed_by_role_runtime_session_id or ""
                ).strip()
                and not str(item.claimed_by_seat_id or "").strip()
                and item_owner
                and item_generation > 0
                and parked_envelope
            ):
                await transaction_db.rollback()
                return None
            metadata = dict(task.metadata or {})
            metadata["company_run_controller_owner_token"] = context.owner_token
            metadata[
                "company_run_controller_lease_generation"
            ] = context.generation
            metadata["claimed_work_item_attempt_seq"] = context.attempt_seq
            task.metadata = metadata
            item_metadata[
                "company_run_controller_owner_token"
            ] = context.owner_token
            item_metadata[
                "company_run_controller_lease_generation"
            ] = context.generation
            cursor = await transaction_db.execute(
                """UPDATE delegation_work_items
                   SET metadata = ?, updated_at = ?
                   WHERE work_item_id = ? AND run_id = ?
                     AND phase = ? AND updated_at = ?
                     AND EXISTS (
                         SELECT 1 FROM delegation_runs AS run
                         WHERE run.run_id = delegation_work_items.run_id
                           AND run.project_id = ?
                           AND run.controller_owner_token = ?
                           AND run.controller_lease_generation = ?
                           AND run.controller_lease_expires_at > ?
                     )""",
                (
                    _json_dumps(item_metadata),
                    checked_at.isoformat(),
                    context.work_item_id,
                    context.run_id,
                    expected_phase.value,
                    item.updated_at.isoformat(),
                    context.project_id,
                    context.owner_token,
                    context.generation,
                    checked_at.isoformat(),
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                await transaction_db.rollback()
                return None
            await self._save_task_row(
                task,
                commit=False,
                db=transaction_db,
            )
            await transaction_db.commit()
            return copy.deepcopy(task)
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def complete_company_work_item_gate_continuation_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        *,
        checkpoint_id: str,
        continuation_kind: str = "finalize",
    ) -> bool:
        """CAS-complete one fully matched durable post-gate continuation."""

        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_kind = str(continuation_kind or "").strip()
        if (
            not context.complete
            or not clean_checkpoint_id
            or clean_kind
            not in {
                "finalize",
                "manager_review",
                "refresh_dependents",
                "dispatch_rework",
                "failure_settlement",
            }
        ):
            return False
        db = _SQLiteConnectionAdapter(self.db_path)
        completed_at = datetime.now()
        try:
            await db.execute("BEGIN IMMEDIATE")
            if not await self._company_controller_attempt_context_matches(
                db,
                context,
                checked_at=completed_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot complete gate continuation"
                )
            checkpoint = await self._select_execution_checkpoint(
                clean_checkpoint_id,
                project_id=context.project_id,
                checkpoint_type="company_work_item_gate",
                db=db,
            )
            task = await self._get_task_unhydrated(context.task_id, db=db)
            async with db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (context.work_item_id,),
            ) as item_cursor:
                row = await item_cursor.fetchone()
                item = (
                    self._row_to_delegation_work_item(
                        row, item_cursor.description
                    )
                    if row is not None
                    else None
                )
            if checkpoint is None or task is None or item is None:
                await db.rollback()
                return False
            completion = dict(
                dict(checkpoint.payload or {}).get(
                    "company_work_item_gate_decision_completion", {}
                )
                or {}
            )
            marker = dict(
                (task.metadata or {}).get(
                    "company_work_item_gate_continuation", {}
                )
                or {}
            )
            task_metadata = dict(task.metadata or {})
            item_metadata = dict(item.metadata or {})
            identity_keys = (
                "checkpoint_id",
                "action",
                "attempt_seq",
                "gate_attempt",
                "basis_hash",
                "target_phase",
            )
            identity_matches = bool(
                (
                    checkpoint.status == "resolved"
                    or (
                        checkpoint.status == "invalid"
                        and clean_kind == "failure_settlement"
                        and str(completion.get("final_status", "") or "").strip()
                        == "invalid"
                    )
                )
                and str(completion.get("run_id", "") or "").strip()
                == context.run_id
                and str(completion.get("task_id", "") or "").strip()
                == context.task_id
                and str(completion.get("work_item_id", "") or "").strip()
                == context.work_item_id
                and str(completion.get("continuation", "") or "").strip()
                == clean_kind
                and str(marker.get("kind", "") or "").strip() == clean_kind
                and str(marker.get("status", "") or "").strip() == "pending"
                and all(marker.get(key) == completion.get(key) for key in identity_keys)
                and str(item.run_id or "").strip() == context.run_id
                and str(task_metadata.get("delegation_run_id", "") or "").strip()
                == context.run_id
                and projection_id_for_task(task)
                == str(item.projection_id or "").strip()
            )
            dependency_refresh_ack = dict(
                item_metadata.get(
                    "company_work_item_gate_dependency_refresh", {}
                )
                or {}
            )
            dependency_refresh_ack_matches = bool(
                all(
                    dependency_refresh_ack.get(key) == completion.get(key)
                    for key in identity_keys
                )
                and str(
                    dependency_refresh_ack.get("refreshed_at", "") or ""
                ).strip()
            )
            async with db.execute(
                """SELECT status, lifecycle_status
                   FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?""",
                (context.run_id, context.project_id),
            ) as run_cursor:
                run_row = await run_cursor.fetchone()
            async with db.execute(
                """SELECT 1
                   FROM delegation_work_items
                   WHERE run_id = ? AND kind = 'report'
                     AND phase NOT IN ('approved', 'failed', 'cancelled')
                     AND json_extract(
                           metadata, '$.report_target_work_item_id'
                         ) = ?
                   LIMIT 1""",
                (context.run_id, context.work_item_id),
            ) as report_cursor:
                manager_report_exists = await report_cursor.fetchone() is not None
            async with db.execute(
                """SELECT *
                   FROM execution_checkpoints
                   WHERE project_id = ?
                     AND checkpoint_type = 'company_delivery_feedback'
                     AND status NOT IN (
                         'invalid', 'stale', 'superseded', 'failed',
                         'cancelled', 'canceled', 'outcome_unknown'
                     )
                     AND (
                         task_id = ?
                         OR json_extract(payload, '$.waiting_task_id') = ?
                     )""",
                (context.project_id, context.task_id, context.task_id),
            ) as feedback_cursor:
                feedback_rows = await feedback_cursor.fetchall()
                feedback_columns = [item[0] for item in feedback_cursor.description]
            final_publication_exists = False
            try:
                completion_attempt = int(
                    completion.get("attempt_seq", 0) or 0
                )
            except (TypeError, ValueError):
                completion_attempt = 0
            for feedback_row in feedback_rows:
                feedback_checkpoint = self._execution_checkpoint_from_data(
                    dict(zip(feedback_columns, feedback_row))
                )
                feedback_payload = dict(feedback_checkpoint.payload or {})
                publication_hash = str(
                    feedback_payload.get("delivery_package_sha256", "") or ""
                ).strip()
                if publication_hash and final_delivery_checkpoint_payload_matches(
                    feedback_payload,
                    run_id=context.run_id,
                    task_id=context.task_id,
                    work_item_id=context.work_item_id,
                    attempt_seq=completion_attempt,
                    package_hash=publication_hash,
                ):
                    final_publication_exists = True
                    break
            try:
                current_item_attempt = int(
                    item_metadata.get("attempt_seq", 0) or 0
                )
            except (TypeError, ValueError):
                current_item_attempt = 0
            run_failure_settled = bool(
                run_row is not None
                and str(run_row[0] or "").strip().lower()
                in {"failed", "cancelled", "canceled"}
                and str(run_row[1] or "").strip().lower()
                == "closed_failed"
            )
            async with db.execute(
                """SELECT 1
                   FROM execution_checkpoints
                   WHERE project_id = ?
                     AND checkpoint_type = 'company_run_failure_review'
                     AND json_extract(payload, '$.run_id') = ?
                     AND json_extract(payload, '$.source_event_id') = ?
                     AND status NOT IN (
                         'invalid', 'stale', 'superseded', 'failed',
                         'cancelled', 'canceled', 'outcome_unknown'
                     )
                   LIMIT 1""",
                (
                    context.project_id,
                    context.run_id,
                    f"company-run-failure:{context.run_id}",
                ),
            ) as failure_review_cursor:
                failure_review_exists = (
                    await failure_review_cursor.fetchone() is not None
                )
            finalizer_rework_dispatched = bool(
                current_item_attempt > completion_attempt
                and item.phase
                in {
                    Phase.RUNNING,
                    Phase.WAITING_FOR_PEER,
                    Phase.WAITING_FOR_CHILDREN,
                    Phase.PAUSED,
                    Phase.NEEDS_ATTENTION,
                    Phase.AWAITING_MANAGER_REVIEW,
                    Phase.AWAITING_HUMAN,
                    Phase.APPROVED,
                }
                and task.status == task_status_for_phase(item.phase)
            )
            finalizer_failure_settled = bool(
                item.phase in {Phase.FAILED, Phase.CANCELLED}
                and task.status == task_status_for_phase(item.phase)
                and run_failure_settled
                and failure_review_exists
            )
            phase_postcondition = {
                "finalize": (
                    str(completion.get("action", "") or "") == "approve"
                    and (
                        final_publication_exists
                        or finalizer_rework_dispatched
                        or finalizer_failure_settled
                    )
                ),
                "manager_review": (
                    item.phase == Phase.AWAITING_MANAGER_REVIEW
                    and task.status == TaskStatus.AWAITING_MANAGER_REVIEW
                    and manager_report_exists
                ),
                "refresh_dependents": (
                    item.phase == Phase.APPROVED
                    and task.status == TaskStatus.DONE
                    and dependency_refresh_ack_matches
                ),
                "dispatch_rework": (
                    current_item_attempt > completion_attempt
                    and item.phase != Phase.READY_FOR_REWORK
                    and task.status == task_status_for_phase(item.phase)
                ),
                "failure_settlement": (
                    item.phase == Phase.FAILED
                    and task.status == TaskStatus.FAILED
                    and run_failure_settled
                    and failure_review_exists
                ),
            }[clean_kind]
            if not identity_matches or not phase_postcondition:
                await db.rollback()
                return False
            cursor = await db.execute(
                """UPDATE tasks
                   SET metadata = json_set(
                       metadata,
                       '$.company_work_item_gate_continuation.status',
                       'completed',
                       '$.company_work_item_gate_continuation.completed_at',
                       ?
                   )
                   WHERE id = ? AND project_id = ?
                     AND json_extract(
                         metadata,
                         '$.company_work_item_gate_continuation.checkpoint_id'
                     ) = ?
                     AND json_extract(
                         metadata,
                         '$.company_work_item_gate_continuation.kind'
                     ) = ?
                     AND json_extract(
                         metadata,
                         '$.company_work_item_gate_continuation.status'
                     ) = 'pending'""",
                (
                    completed_at.isoformat(),
                    context.task_id,
                    context.project_id,
                    clean_checkpoint_id,
                    clean_kind,
                ),
            )
            applied = int(getattr(cursor, "rowcount", 0) or 0) == 1
            if applied:
                checkpoint_payload = copy.deepcopy(dict(checkpoint.payload or {}))
                completion["continuation_status"] = "completed"
                completion["continuation_completed_at"] = completed_at.isoformat()
                checkpoint_payload[
                    "company_work_item_gate_decision_completion"
                ] = copy.deepcopy(completion)
                checkpoint_cursor = await db.execute(
                    """UPDATE execution_checkpoints
                       SET payload = ?, updated_at = ?
                       WHERE checkpoint_id = ? AND project_id = ?
                         AND checkpoint_type = 'company_work_item_gate'
                         AND status = ? AND updated_at = ?""",
                    (
                        _json_dumps(checkpoint_payload),
                        completed_at.isoformat(),
                        clean_checkpoint_id,
                        context.project_id,
                        checkpoint.status,
                        checkpoint.updated_at.isoformat(),
                    ),
                )
                if int(getattr(checkpoint_cursor, "rowcount", 0) or 0) != 1:
                    await db.rollback()
                    return False
                await db.commit()
            else:
                await db.rollback()
            return applied
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

    async def ack_company_work_item_gate_dependency_refresh_for_controller(
        self,
        context: CompanyControllerAttemptContext,
        *,
        checkpoint_id: str,
    ) -> bool:
        """Stamp a completed, controller-fenced dependency refresh.

        Approval itself leaves the source APPROVED/DONE, so those phases
        cannot prove that downstream release ran.  This exact marker is
        written only after ``refresh_dependents_for_controller`` completed;
        the continuation CAS below requires it before retiring recovery.
        """

        clean_checkpoint_id = str(checkpoint_id or "").strip()
        if not context.complete or not clean_checkpoint_id:
            return False
        db = _SQLiteConnectionAdapter(self.db_path)
        checked_at = datetime.now()
        try:
            await db.execute("BEGIN IMMEDIATE")
            if not await self._company_controller_attempt_context_matches(
                db,
                context,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale controller cannot acknowledge gate dependency refresh"
                )
            checkpoint = await self._select_execution_checkpoint(
                clean_checkpoint_id,
                project_id=context.project_id,
                checkpoint_type="company_work_item_gate",
                db=db,
            )
            task = await self._get_task_unhydrated(context.task_id, db=db)
            async with db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (context.work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                item = (
                    self._row_to_delegation_work_item(row, cursor.description)
                    if row is not None
                    else None
                )
            if checkpoint is None or task is None or item is None:
                await db.rollback()
                return False
            completion = dict(
                dict(checkpoint.payload or {}).get(
                    "company_work_item_gate_decision_completion", {}
                )
                or {}
            )
            marker = dict(
                dict(task.metadata or {}).get(
                    "company_work_item_gate_continuation", {}
                )
                or {}
            )
            identity_keys = (
                "checkpoint_id",
                "action",
                "attempt_seq",
                "gate_attempt",
                "basis_hash",
                "target_phase",
            )
            try:
                item_attempt = int(
                    dict(item.metadata or {}).get("attempt_seq", 0) or 0
                )
            except (TypeError, ValueError):
                item_attempt = 0
            if not (
                checkpoint.status == "resolved"
                and completion.get("action") == "approve"
                and completion.get("continuation") == "refresh_dependents"
                and str(completion.get("run_id", "") or "") == context.run_id
                and str(completion.get("task_id", "") or "") == context.task_id
                and str(completion.get("work_item_id", "") or "")
                == context.work_item_id
                and str(marker.get("kind", "") or "")
                == "refresh_dependents"
                and str(marker.get("status", "") or "") == "pending"
                and all(marker.get(key) == completion.get(key) for key in identity_keys)
                and item.phase == Phase.APPROVED
                and task.status == TaskStatus.DONE
                and str(item.run_id or "").strip() == context.run_id
                and item_attempt == context.attempt_seq
            ):
                await db.rollback()
                return False
            ack = {
                key: copy.deepcopy(completion.get(key))
                for key in identity_keys
            }
            ack["refreshed_at"] = checked_at.isoformat()
            metadata = dict(item.metadata or {})
            metadata["company_work_item_gate_dependency_refresh"] = ack
            cursor = await db.execute(
                """UPDATE delegation_work_items
                   SET metadata = ?, updated_at = ?
                   WHERE work_item_id = ? AND run_id = ?
                     AND phase = ? AND updated_at = ?
                     AND EXISTS (
                         SELECT 1 FROM delegation_runs AS run
                         WHERE run.run_id = delegation_work_items.run_id
                           AND run.project_id = ?
                           AND run.controller_owner_token = ?
                           AND run.controller_lease_generation = ?
                           AND run.controller_lease_expires_at > ?
                     )""",
                (
                    _json_dumps(metadata),
                    checked_at.isoformat(),
                    context.work_item_id,
                    context.run_id,
                    Phase.APPROVED.value,
                    item.updated_at.isoformat(),
                    context.project_id,
                    context.owner_token,
                    context.generation,
                    checked_at.isoformat(),
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                await db.rollback()
                return False
            await db.commit()
            return True
        except BaseException:
            await db.rollback()
            raise
        finally:
            await db.close()

    async def execute_company_controller_authoritative_command(
        self,
        context: CompanyControllerAttemptContext,
        *,
        operation: str,
        mutations: tuple[CompanyControllerWorkItemMutation, ...] = (),
        insert_work_items: tuple[DelegationWorkItem, ...] = (),
        task_snapshot: Task | None = None,
        task_snapshots: tuple[Task, ...] = (),
        task_preimage_hashes: dict[str, str] | None = None,
        run_mutation: CompanyControllerRunLifecycleMutation | None = None,
        owner_publication: PreparedOwnerInteractionPublication | None = None,
        origin_owner_interaction: OriginOwnerInteractionLease | None = None,
    ) -> CompanyControllerAuthoritativeCommandResult:
        """Execute post-turn business writes under one durable attempt fence.

        The lease, generation, Task/WorkItem link, and ``attempt_seq`` are
        checked after ``BEGIN IMMEDIATE`` on the same connection that performs
        every mutation and insert.  A takeover therefore cannot fit between a
        precheck and an authoritative write.  Related WorkItems may be changed
        only within the same run; optional phase/report predicates are all-or-
        nothing domain CAS guards.

        This command is deliberately separate from the unfenced maintenance
        APIs.  Startup reconciliation, migrations, and explicit admin repair
        continue to use those APIs without manufacturing a live executor
        credential.
        """

        self._require_db()
        if not context.complete:
            raise CompanyRunControllerLeaseLost(
                "company authoritative command lacks an exact controller attempt"
            )
        if task_snapshot is not None and str(task_snapshot.id or "").strip() != context.task_id:
            raise ValueError("task_snapshot does not belong to the controller context")
        additional_task_snapshots = tuple(task_snapshots or ())
        expected_task_preimages = {
            str(task_id or "").strip(): str(value or "").strip()
            for task_id, value in dict(task_preimage_hashes or {}).items()
        }
        additional_task_ids = [
            str(snapshot.id or "").strip()
            for snapshot in additional_task_snapshots
        ]
        if any(not task_id for task_id in additional_task_ids):
            raise ValueError("additional task snapshots must have non-empty ids")
        if len(set(additional_task_ids)) != len(additional_task_ids):
            raise ValueError("authoritative command cannot save a Task twice")
        if task_snapshot is not None and context.task_id in set(additional_task_ids):
            raise ValueError(
                "controller task_snapshot cannot also be an additional snapshot"
            )
        if any(
            (str(snapshot.project_id or "default").strip() or "default")
            != context.project_id
            for snapshot in additional_task_snapshots
        ):
            raise ValueError(
                "additional task snapshots must belong to the controller project"
            )
        all_snapshot_ids = {
            *additional_task_ids,
            *([context.task_id] if task_snapshot is not None else []),
        }
        if all_snapshot_ids and set(expected_task_preimages) != all_snapshot_ids:
            raise ValueError(
                "task preimage hashes must cover every saved Task exactly"
            )
        if expected_task_preimages and not all_snapshot_ids:
            raise ValueError(
                "task preimage hashes cannot be supplied without Task snapshots"
            )
        if owner_publication is not None:
            owner_checkpoint = owner_publication.checkpoint
            if (
                str(owner_checkpoint.project_id or "default").strip()
                != context.project_id
                or str(owner_checkpoint.task_id or "").strip()
                != context.task_id
            ):
                raise ValueError(
                    "owner publication does not belong to the controller context"
                )
            if owner_checkpoint.checkpoint_type != "company_delivery_feedback":
                raise ValueError(
                    "company authoritative command only publishes delivery feedback"
                )
        if origin_owner_interaction is not None:
            if owner_publication is None:
                raise ValueError(
                    "origin owner interaction may only close with owner publication"
                )
            if not origin_owner_interaction.complete:
                raise ValueError("origin owner interaction lease is incomplete")
            if origin_owner_interaction.project_id != context.project_id:
                raise ValueError(
                    "origin owner interaction belongs to another project"
                )
        mutation_ids = [
            str(mutation.work_item_id or "").strip() for mutation in mutations
        ]
        insert_ids = [
            str(item.work_item_id or "").strip() for item in insert_work_items
        ]
        if any(not item_id for item_id in [*mutation_ids, *insert_ids]):
            raise ValueError("authoritative command WorkItem ids must be non-empty")
        if len(set(mutation_ids)) != len(mutation_ids):
            raise ValueError("authoritative command cannot mutate a WorkItem twice")
        if len(set(insert_ids)) != len(insert_ids):
            raise ValueError("authoritative command cannot insert a WorkItem twice")
        if set(mutation_ids) & set(insert_ids):
            raise ValueError("authoritative command cannot mutate and insert the same WorkItem")
        deterministic_rework_operations = {
            "pre_delivery_validation_rework",
            "executive_delivery_rework",
            "company_followup_rework",
        }
        if operation in deterministic_rework_operations and (
            task_snapshot is None
            or context.work_item_id not in set(mutation_ids)
            or not all_snapshot_ids
            or len(mutation_ids) != len(all_snapshot_ids)
        ):
            raise ValueError(
                "deterministic rework requires its controller source and a "
                "non-empty one-to-one WorkItem/Task mutation set"
            )
        if operation == "record_pre_delivery_validation_pass" and (
            task_snapshot is None
            or context.work_item_id not in set(mutation_ids)
            or not all_snapshot_ids
            or len(mutation_ids) != len(all_snapshot_ids)
            or bool(insert_work_items)
            or run_mutation is not None
            or owner_publication is not None
            or origin_owner_interaction is not None
        ):
            raise ValueError(
                "pre-delivery pass cleanup requires its controller source "
                "and a non-empty one-to-one WorkItem/Task mutation set"
            )
        task_snapshot_to_save = (
            copy.deepcopy(task_snapshot) if task_snapshot is not None else None
        )
        additional_task_snapshots_to_save = tuple(
            copy.deepcopy(snapshot) for snapshot in additional_task_snapshots
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        phase_changes: list[tuple[Phase | None, Phase, DelegationWorkItem]] = []
        persisted_mutations: list[DelegationWorkItem] = []
        created_ids: list[str] = []
        persisted_run: DelegationRun | None = None
        persisted_checkpoint: ExecutionCheckpoint | None = None
        checkpoint_created = False
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            if not await self._company_controller_attempt_context_matches(
                transaction_db,
                context,
                checked_at=checked_at,
            ):
                raise CompanyRunControllerLeaseLost(
                    f"stale company controller cannot execute {operation or 'authoritative command'}"
                )
            if task_snapshot_to_save is not None and not (
                await self._controller_task_snapshot_envelope_matches(
                    transaction_db,
                    context,
                    task_snapshot_to_save,
                )
            ):
                await transaction_db.rollback()
                return CompanyControllerAuthoritativeCommandResult(
                    applied=False
                )
            if expected_task_preimages:
                for task_id, expected_hash in expected_task_preimages.items():
                    durable_task = await self._get_task_unhydrated(
                        task_id,
                        db=transaction_db,
                    )
                    if (
                        durable_task is None
                        or not expected_hash
                        or _task_authoritative_preimage_hash(durable_task)
                        != expected_hash
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

            # Every broad Task replacement must be the exact runtime
            # projection of a WorkItem mutated by this command.  The source
            # snapshot is not privileged here: accepting only its id would
            # let a stale/forged credential overwrite the durable envelope.
            mutation_id_set = set(mutation_ids)
            linked_snapshot_work_item_ids: set[str] = set()
            snapshot_by_work_item_id: dict[str, Task] = {}
            linked_metadata_by_work_item_id: dict[str, dict[str, Any]] = {}
            linked_phase_by_work_item_id: dict[str, Phase] = {}
            adopted_work_item_ids: set[str] = set()
            all_task_snapshots = tuple(
                [
                    snapshot
                    for snapshot in (task_snapshot_to_save,)
                    if snapshot is not None
                ]
                + list(additional_task_snapshots_to_save)
            )
            submitted_snapshot_by_id = {
                str(snapshot.id or "").strip(): copy.deepcopy(snapshot)
                for snapshot in all_task_snapshots
            }
            for snapshot in all_task_snapshots:
                async with transaction_db.execute(
                    """SELECT link.work_item_id, work_item.projection_id,
                              work_item.metadata, task.project_id,
                              task.metadata, work_item.phase
                       FROM work_item_runtime_links AS link
                       JOIN delegation_work_items AS work_item
                         ON work_item.work_item_id = link.work_item_id
                       JOIN tasks AS task
                         ON task.id = link.runtime_task_id
                       WHERE link.runtime_task_id = ?
                         AND work_item.run_id = ?
                       LIMIT 1""",
                    (str(snapshot.id or "").strip(), context.run_id),
                ) as cursor:
                    snapshot_link = await cursor.fetchone()
                linked_snapshot_work_item_id = str(
                    snapshot_link[0] if snapshot_link else ""
                ).strip()
                snapshot_projection_id = projection_id_for_task(snapshot)
                linked_projection_id = str(
                    snapshot_link[1] if snapshot_link else ""
                ).strip()
                try:
                    linked_metadata = json.loads(
                        str(snapshot_link[2] if snapshot_link else "{}") or "{}"
                    )
                except (TypeError, ValueError, json.JSONDecodeError):
                    linked_metadata = {}
                durable_project_id = str(
                    snapshot_link[3] if snapshot_link else ""
                ).strip()
                is_source_snapshot = (
                    str(snapshot.id or "").strip() == context.task_id
                )
                try:
                    durable_task_metadata = json.loads(
                        str(snapshot_link[4] if snapshot_link else "{}") or "{}"
                    )
                except (TypeError, ValueError, json.JSONDecodeError):
                    durable_task_metadata = {}
                try:
                    claimed_attempt_seq = int(
                        (snapshot.metadata or {}).get(
                            "claimed_work_item_attempt_seq",
                            0,
                        )
                        or 0
                    )
                    durable_attempt_seq = int(
                        linked_metadata.get("attempt_seq", 0) or 0
                    )
                    durable_claimed_attempt_seq = int(
                        durable_task_metadata.get(
                            "claimed_work_item_attempt_seq",
                            0,
                        )
                        or 0
                    )
                    durable_controller_generation = int(
                        durable_task_metadata.get(
                            "company_run_controller_lease_generation",
                            0,
                        )
                        or 0
                    )
                    snapshot_controller_generation = int(
                        (snapshot.metadata or {}).get(
                            "company_run_controller_lease_generation",
                            0,
                        )
                        or 0
                    )
                except (TypeError, ValueError):
                    claimed_attempt_seq = 0
                    durable_attempt_seq = 0
                    durable_claimed_attempt_seq = 0
                    durable_controller_generation = 0
                    snapshot_controller_generation = 0
                durable_owner_token = str(
                    durable_task_metadata.get(
                        "company_run_controller_owner_token",
                        "",
                    )
                    or ""
                ).strip()
                work_item_owner_token = str(
                    linked_metadata.get(
                        "company_run_controller_owner_token",
                        "",
                    )
                    or ""
                ).strip()
                try:
                    work_item_controller_generation = int(
                        linked_metadata.get(
                            "company_run_controller_lease_generation",
                            0,
                        )
                        or 0
                    )
                except (TypeError, ValueError):
                    work_item_controller_generation = 0
                durable_envelope_matches_work_item = (
                    durable_claimed_attempt_seq == durable_attempt_seq
                    and durable_owner_token == work_item_owner_token
                    and durable_controller_generation
                    == work_item_controller_generation
                )
                durable_envelope_current = (
                    durable_owner_token == context.owner_token
                    and durable_controller_generation == context.generation
                )
                # A new controller may legitimately reopen an APPROVED child
                # whose settled attempt still carries the preceding
                # controller credential.  The old Task and WorkItem must agree
                # exactly before this transaction adopts both below.  The
                # active source attempt may never use this exception.
                settled_rework_adoption = (
                    operation in deterministic_rework_operations
                    and not is_source_snapshot
                    and linked_metadata.get("attempt_settled") is True
                    and durable_attempt_seq > 0
                    and durable_envelope_matches_work_item
                    and bool(durable_owner_token)
                    and 0 < durable_controller_generation < context.generation
                )
                released_task_envelope = (
                    durable_claimed_attempt_seq == 0
                    and not durable_owner_token
                    and durable_controller_generation == 0
                )
                settled_pass_adoption = (
                    operation == "record_pre_delivery_validation_pass"
                    and not is_source_snapshot
                    and linked_metadata.get("attempt_settled") is True
                    and durable_attempt_seq > 0
                    and bool(work_item_owner_token)
                    and (
                        (
                            durable_envelope_matches_work_item
                            and 0
                            < work_item_controller_generation
                            < context.generation
                        )
                        or (
                            released_task_envelope
                            and 0
                            < work_item_controller_generation
                            <= context.generation
                            and (
                                work_item_controller_generation
                                < context.generation
                                or work_item_owner_token
                                == context.owner_token
                            )
                        )
                    )
                )
                snapshot_owner_token = str(
                    (snapshot.metadata or {}).get(
                        "company_run_controller_owner_token",
                        "",
                    )
                    or ""
                ).strip()
                if (
                    linked_snapshot_work_item_id not in mutation_id_set
                    or linked_snapshot_work_item_id
                    in linked_snapshot_work_item_ids
                    or not snapshot_projection_id
                    or snapshot_projection_id != linked_projection_id
                    or (
                        str(snapshot.project_id or "default").strip()
                        or "default"
                    )
                    != context.project_id
                    or str(
                        (snapshot.metadata or {}).get(
                            "delegation_run_id",
                            "",
                        )
                        or ""
                    ).strip()
                    != context.run_id
                    or durable_project_id != context.project_id
                    or str(
                        durable_task_metadata.get(
                            "delegation_run_id",
                            "",
                        )
                        or ""
                    ).strip()
                    != context.run_id
                    or str(
                        durable_task_metadata.get(
                            WORK_ITEM_PROJECTION_ID_KEY,
                            "",
                        )
                        or ""
                    ).strip()
                    != linked_projection_id
                    or (
                        operation in deterministic_rework_operations
                        and linked_metadata.get("attempt_settled") is not True
                    )
                    or not (
                        (
                            claimed_attempt_seq > 0
                            and claimed_attempt_seq == durable_attempt_seq
                            and snapshot_owner_token == durable_owner_token
                            and snapshot_controller_generation
                            == durable_controller_generation
                            and durable_claimed_attempt_seq
                            == durable_attempt_seq
                            and durable_envelope_matches_work_item
                            and durable_envelope_current
                        )
                        or settled_rework_adoption
                        or settled_pass_adoption
                    )
                ):
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(
                        applied=False
                    )
                if settled_rework_adoption or settled_pass_adoption:
                    adopted_work_item_ids.add(linked_snapshot_work_item_id)
                    snapshot.metadata = dict(snapshot.metadata or {})
                    snapshot.metadata[
                        "claimed_work_item_attempt_seq"
                    ] = durable_attempt_seq
                    snapshot.metadata[
                        "company_run_controller_owner_token"
                    ] = context.owner_token
                    snapshot.metadata[
                        "company_run_controller_lease_generation"
                    ] = context.generation
                linked_snapshot_work_item_ids.add(
                    linked_snapshot_work_item_id
                )
                snapshot_by_work_item_id[linked_snapshot_work_item_id] = (
                    snapshot
                )
                linked_metadata_by_work_item_id[
                    linked_snapshot_work_item_id
                ] = linked_metadata
                linked_phase_by_work_item_id[
                    linked_snapshot_work_item_id
                ] = coerce_phase(snapshot_link[5])

            if operation in {
                *deterministic_rework_operations,
                "record_pre_delivery_validation_pass",
            } and (
                linked_snapshot_work_item_ids != mutation_id_set
            ):
                await transaction_db.rollback()
                return CompanyControllerAuthoritativeCommandResult(
                    applied=False
                )
            if operation in deterministic_rework_operations:
                mutation_by_id = {
                    str(mutation.work_item_id or "").strip(): mutation
                    for mutation in mutations
                }
                for linked_work_item_id, snapshot in (
                    snapshot_by_work_item_id.items()
                ):
                    mutation = mutation_by_id[linked_work_item_id]
                    if (
                        mutation.phase is None
                        or snapshot.status
                        != task_status_for_phase(coerce_phase(mutation.phase))
                        or snapshot.result is not None
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
            if operation == "record_pre_delivery_validation_pass":
                mutation_by_id = {
                    str(mutation.work_item_id or "").strip(): mutation
                    for mutation in mutations
                }
                durable_pass_task_by_work_item_id: dict[str, Task] = {}
                for linked_work_item_id, submitted in (
                    snapshot_by_work_item_id.items()
                ):
                    durable_pass_task = await self._get_task_unhydrated(
                        str(submitted.id or "").strip(),
                        db=transaction_db,
                    )
                    if durable_pass_task is None:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    durable_pass_task_by_work_item_id[
                        linked_work_item_id
                    ] = durable_pass_task
                source_submitted = next(
                    (
                        submitted
                        for submitted in snapshot_by_work_item_id.values()
                        if str(submitted.id or "").strip()
                        == context.task_id
                    ),
                    None,
                )
                source_projection_id = projection_id_for_task(
                    source_submitted
                )
                async with transaction_db.execute(
                    """SELECT link.runtime_task_id, work_item.metadata
                       FROM work_item_runtime_links AS link
                       JOIN delegation_work_items AS work_item
                         ON work_item.work_item_id = link.work_item_id
                       WHERE work_item.run_id = ?""",
                    (context.run_id,),
                ) as cursor:
                    run_task_rows = await cursor.fetchall()
                durable_pass_task_by_projection: dict[str, Task] = {}
                durable_pass_task_id_by_projection: dict[str, str] = {}
                durable_pass_work_item_metadata_by_projection: dict[
                    str, dict[str, Any]
                ] = {}
                for run_task_row in run_task_rows:
                    run_task = await self._get_task_unhydrated(
                        str(run_task_row[0] or "").strip(),
                        db=transaction_db,
                    )
                    if run_task is None:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    run_projection_id = projection_id_for_task(run_task)
                    if not run_projection_id:
                        continue
                    if run_projection_id in durable_pass_task_by_projection:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    durable_pass_task_by_projection[
                        run_projection_id
                    ] = run_task
                    durable_pass_task_id_by_projection[
                        run_projection_id
                    ] = str(run_task.id or "").strip()
                    durable_pass_work_item_metadata_by_projection[
                        run_projection_id
                    ] = _json_loads(run_task_row[1], {})
                expected_cleanup_modes: dict[str, str] = {}
                upstream_by_projection: dict[str, str] = {}
                for projection_id, durable in (
                    durable_pass_task_by_projection.items()
                ):
                    durable_metadata = dict(durable.metadata or {})
                    work_item_metadata = dict(
                        durable_pass_work_item_metadata_by_projection.get(
                            projection_id, {}
                        )
                        or {}
                    )
                    active_metadata = (
                        durable_metadata
                        if any(
                            key in durable_metadata
                            for key in (
                                "gate_harness_rework_feedback",
                                "gate_harness_rework_count",
                                "gate_harness_rework_request",
                            )
                        )
                        else work_item_metadata
                    )
                    raw_request = active_metadata.get(
                        "gate_harness_rework_request", {}
                    )
                    request = (
                        dict(raw_request)
                        if isinstance(raw_request, dict)
                        else {}
                    )
                    blocker_types = {
                        str(value or "").strip()
                        for value in list(
                            request.get("blocker_types", []) or []
                        )
                        if str(value or "").strip()
                    }
                    if (
                        projection_id
                        and str(
                            request.get("source_projection_id", "") or ""
                        ).strip()
                        == source_projection_id
                        and "pre_delivery_validation" in blocker_types
                    ):
                        expected_cleanup_modes[projection_id] = (
                            "active_group"
                        )
                    upstream_projection_id = str(
                        durable_metadata.get(
                            "upstream_gate_harness_rework_source_projection_id",
                            "",
                        )
                        or dict(durable.context_snapshot or {}).get(
                            "upstream_gate_harness_rework_source_projection_id",
                            "",
                        )
                        or (
                            work_item_metadata.get(
                                "upstream_gate_harness_rework_source_projection_id",
                                "",
                            )
                            if "upstream_gate_harness_rework_source_projection_id"
                            not in durable_metadata
                            and "upstream_gate_harness_rework_source_projection_id"
                            not in dict(durable.context_snapshot or {})
                            else ""
                        )
                        or ""
                    ).strip()
                    if upstream_projection_id:
                        upstream_by_projection[projection_id] = (
                            upstream_projection_id
                        )
                changed = True
                while changed:
                    changed = False
                    for projection_id, upstream_projection_id in (
                        upstream_by_projection.items()
                    ):
                        if (
                            projection_id in expected_cleanup_modes
                            or upstream_projection_id
                            not in expected_cleanup_modes
                        ):
                            continue
                        durable_metadata = dict(
                            durable_pass_task_by_projection[
                                projection_id
                            ].metadata
                            or {}
                        )
                        work_item_metadata = dict(
                            durable_pass_work_item_metadata_by_projection.get(
                                projection_id, {}
                            )
                            or {}
                        )
                        active_metadata = (
                            durable_metadata
                            if any(
                                key in durable_metadata
                                for key in (
                                    "gate_harness_rework_feedback",
                                    "gate_harness_rework_count",
                                    "gate_harness_rework_request",
                                )
                            )
                            else work_item_metadata
                        )
                        try:
                            active_count = int(
                                active_metadata.get(
                                    "gate_harness_rework_count", 0
                                )
                                or 0
                            )
                        except (TypeError, ValueError):
                            active_count = 0
                        active_group_present = bool(
                            str(
                                active_metadata.get(
                                    "gate_harness_rework_feedback", ""
                                )
                                or ""
                            ).strip()
                            or (
                                isinstance(
                                    active_metadata.get(
                                        "gate_harness_rework_request"
                                    ),
                                    dict,
                                )
                                and bool(
                                    active_metadata.get(
                                        "gate_harness_rework_request"
                                    )
                                )
                            )
                            or active_count > 0
                        )
                        expected_cleanup_modes[projection_id] = (
                            "upstream_marker_only"
                            if active_group_present
                            else "active_group"
                        )
                        changed = True
                required_pass_task_ids = {
                    context.task_id,
                    *(
                        durable_pass_task_id_by_projection[projection_id]
                        for projection_id in expected_cleanup_modes
                    ),
                }
                if {
                    str(snapshot.id or "").strip()
                    for snapshot in snapshot_by_work_item_id.values()
                } != required_pass_task_ids:
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(
                        applied=False
                    )
                active_unset = {
                    "gate_harness_rework_feedback",
                    "gate_harness_rework_count",
                    "gate_harness_rework_request",
                    "upstream_gate_harness_rework_source_projection_id",
                }
                marker_unset = {
                    "upstream_gate_harness_rework_source_projection_id"
                }
                validation_keys = {
                    "pre_delivery_validation",
                    "pre_delivery_validation_evidence",
                    "pre_delivery_validation_history",
                    "delivery_package",
                }
                controller_credential_keys = {
                    "claimed_work_item_attempt_seq",
                    "company_run_controller_owner_token",
                    "company_run_controller_lease_generation",
                }
                for linked_work_item_id, snapshot in (
                    snapshot_by_work_item_id.items()
                ):
                    mutation = mutation_by_id[linked_work_item_id]
                    source_snapshot = (
                        str(snapshot.id or "").strip() == context.task_id
                    )
                    unset_keys = {
                        str(key or "").strip()
                        for key in tuple(mutation.metadata_unset or ())
                        if str(key or "").strip()
                    }
                    raw_unset_keys = tuple(
                        str(key or "").strip()
                        for key in tuple(mutation.metadata_unset or ())
                    )
                    failure_unset = (
                        "pre_delivery_validation_failure_kind"
                        in unset_keys
                    )
                    if failure_unset:
                        unset_keys.remove(
                            "pre_delivery_validation_failure_kind"
                        )
                    cleanup_mode = (
                        "active_group"
                        if unset_keys == active_unset
                        else "upstream_marker_only"
                        if unset_keys == marker_unset
                        else "none"
                        if source_snapshot and not unset_keys
                        else "invalid"
                    )
                    expected_cleanup_mode = expected_cleanup_modes.get(
                        projection_id_for_task(
                            durable_pass_task_by_work_item_id[
                                linked_work_item_id
                            ]
                        ),
                        "none" if source_snapshot else "invalid",
                    )
                    update_keys = set(
                        dict(mutation.metadata_updates or {})
                    )
                    broad_mutation = bool(
                        mutation.phase is not None
                        or mutation.summary is not None
                        or mutation.deliverable_summary is not None
                        or mutation.blocked_reason is not None
                        or mutation.handoff_status is not None
                        or mutation.claimed_by_role_runtime_session_id
                        is not None
                        or mutation.claimed_by_seat_id is not None
                        or mutation.metadata_list_appends
                        or mutation.metadata_list_removes
                        or mutation.clear_claim
                        or mutation.latest_applied_report_work_item_id
                        is not None
                        or str(mutation.transition_reason or "").strip()
                        or str(mutation.attempt_outcome or "").strip()
                        or mutation.allow_via_running
                        or mutation.allow_approved_rework
                        or mutation.required_pre_delivery_validation_attempt_seq
                        is not None
                        or mutation.required_delivery_package_sha256 is not None
                        or mutation.required_pre_delivery_rework_count is not None
                        or mutation.pre_delivery_rework_count_limit is not None
                    )
                    validation_record = dict(
                        dict(mutation.metadata_updates or {}).get(
                            "pre_delivery_validation", {}
                        )
                        or {}
                    )
                    if source_snapshot:
                        source_updates = dict(
                            mutation.metadata_updates or {}
                        )
                        source_package = source_updates.get(
                            "delivery_package"
                        )
                        durable_source_metadata = dict(
                            durable_pass_task_by_work_item_id[
                                linked_work_item_id
                            ].metadata
                            or {}
                        )
                        durable_history = [
                            copy.deepcopy(value)
                            for value in list(
                                durable_source_metadata.get(
                                    "pre_delivery_validation_history", []
                                )
                                or []
                            )
                            if isinstance(value, dict)
                        ]
                        expected_history = list(durable_history)
                        if (
                            not expected_history
                            or expected_history[-1] != validation_record
                        ):
                            expected_history.append(
                                copy.deepcopy(validation_record)
                            )
                        expected_history = expected_history[-12:]
                        validation_record_keys = {
                            "status",
                            "valid",
                            "evidence",
                            "issues",
                            "rework_target_projection_ids",
                            "work_item_attempt_seq",
                            "delivery_package_sha256",
                            "validated_at",
                        }
                        if (
                            update_keys != validation_keys
                            or set(validation_record) != validation_record_keys
                            or not isinstance(source_package, dict)
                            or not failure_unset
                            or "pre_delivery_validation_failure_kind"
                            in dict(
                                submitted_snapshot_by_id[
                                    context.task_id
                                ].metadata
                                or {}
                            )
                            or validation_record.get("issues") != []
                            or validation_record.get(
                                "rework_target_projection_ids"
                            )
                            != []
                            or not isinstance(
                                validation_record.get("evidence"), dict
                            )
                            or not str(
                                validation_record.get("validated_at", "")
                                or ""
                            ).strip()
                            or int(
                                validation_record.get(
                                    "work_item_attempt_seq", 0
                                )
                                or 0
                            )
                            != int(
                                linked_metadata_by_work_item_id[
                                    linked_work_item_id
                                ].get("attempt_seq", 0)
                                or 0
                            )
                            or source_updates.get(
                                "pre_delivery_validation_evidence"
                            )
                            != validation_record.get("evidence")
                            or source_updates.get(
                                "pre_delivery_validation_history"
                            )
                            != expected_history
                            or any(
                                submitted_snapshot_by_id[
                                    context.task_id
                                ].metadata.get(key)
                                != source_updates.get(key)
                                for key in (
                                    "pre_delivery_validation",
                                    "pre_delivery_validation_evidence",
                                    "pre_delivery_validation_history",
                                )
                            )
                            or dict(
                                submitted_snapshot_by_id[
                                    context.task_id
                                ].context_snapshot
                                or {}
                            ).get("delivery_package")
                            != source_package
                            or dict(
                                dict(
                                    submitted_snapshot_by_id[
                                        context.task_id
                                    ].context_snapshot
                                    or {}
                                ).get("work_item_owned_outputs", {})
                                or {}
                            ).get("delivery_package")
                            != source_package
                            or str(
                                validation_record.get(
                                    "delivery_package_sha256", ""
                                )
                                or ""
                            ).strip()
                            != delivery_package_sha256(source_package)
                        ):
                            await transaction_db.rollback()
                            return CompanyControllerAuthoritativeCommandResult(
                                applied=False
                            )
                    if (
                        cleanup_mode == "invalid"
                        or cleanup_mode != expected_cleanup_mode
                        or broad_mutation
                        or len(raw_unset_keys) != len(set(raw_unset_keys))
                        or mutation.expected_phases
                        != (
                            linked_phase_by_work_item_id[
                                linked_work_item_id
                            ],
                        )
                        or mutation.expected_updated_at is None
                        or (failure_unset and not source_snapshot)
                        or (
                            not source_snapshot
                            and linked_metadata_by_work_item_id[
                                linked_work_item_id
                            ].get("attempt_settled")
                            is not True
                        )
                        or (
                            not source_snapshot
                            and (
                                linked_phase_by_work_item_id[
                                    linked_work_item_id
                                ]
                                != Phase.APPROVED
                                or durable_pass_task_by_work_item_id[
                                    linked_work_item_id
                                ].status
                                != TaskStatus.DONE
                            )
                        )
                        or (
                            source_snapshot
                            and (
                                linked_phase_by_work_item_id[
                                    linked_work_item_id
                                ]
                                != Phase.AWAITING_HUMAN
                                or durable_pass_task_by_work_item_id[
                                    linked_work_item_id
                                ].status
                                != TaskStatus.AWAITING_HUMAN
                                or linked_metadata_by_work_item_id[
                                    linked_work_item_id
                                ].get("attempt_settled")
                                is not True
                                or int(
                                    linked_metadata_by_work_item_id[
                                        linked_work_item_id
                                    ].get("attempt_seq", 0)
                                    or 0
                                )
                                <= 0
                            )
                        )
                        or (not source_snapshot and update_keys)
                        or (source_snapshot and not update_keys <= validation_keys)
                        or (
                            source_snapshot
                            and (
                                str(validation_record.get("status", "") or "")
                                != "passed"
                                or validation_record.get("valid") is not True
                                or not str(
                                    validation_record.get(
                                        "delivery_package_sha256", ""
                                    )
                                    or ""
                                ).strip()
                            )
                        )
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

                    task_id = str(snapshot.id or "").strip()
                    durable_snapshot = await self._get_task_unhydrated(
                        task_id,
                        db=transaction_db,
                    )
                    submitted_snapshot = submitted_snapshot_by_id[task_id]
                    if durable_snapshot is None or any(
                        (submitted_snapshot.metadata or {}).get(key)
                        != (durable_snapshot.metadata or {}).get(key)
                        for key in controller_credential_keys
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

                    expected_snapshot = copy.deepcopy(durable_snapshot)
                    expected_metadata = dict(expected_snapshot.metadata or {})
                    submitted_metadata = dict(
                        submitted_snapshot.metadata or {}
                    )
                    allowed_metadata_keys: set[str] = set()
                    allowed_context_keys: set[str] = set()
                    if cleanup_mode == "active_group":
                        allowed_metadata_keys.update(active_unset)
                        allowed_context_keys.update(
                            {
                                "latest_gate_harness_rework",
                                "upstream_gate_harness_rework_source_projection_id",
                            }
                        )
                        if (
                            submitted_metadata.get(
                                "gate_harness_rework_feedback"
                            )
                            != ""
                            or submitted_metadata.get(
                                "gate_harness_rework_count"
                            )
                            != 0
                            or submitted_metadata.get(
                                "gate_harness_rework_request"
                            )
                            != {}
                            or "upstream_gate_harness_rework_source_projection_id"
                            in submitted_metadata
                            or "latest_gate_harness_rework"
                            in dict(
                                submitted_snapshot.context_snapshot or {}
                            )
                            or "upstream_gate_harness_rework_source_projection_id"
                            in dict(
                                submitted_snapshot.context_snapshot or {}
                            )
                        ):
                            await transaction_db.rollback()
                            return CompanyControllerAuthoritativeCommandResult(
                                applied=False
                            )
                    elif cleanup_mode == "upstream_marker_only":
                        allowed_metadata_keys.add(
                            "upstream_gate_harness_rework_source_projection_id"
                        )
                        allowed_context_keys.add(
                            "upstream_gate_harness_rework_source_projection_id"
                        )
                        if (
                            "upstream_gate_harness_rework_source_projection_id"
                            in submitted_metadata
                            or "upstream_gate_harness_rework_source_projection_id"
                            in dict(
                                submitted_snapshot.context_snapshot or {}
                            )
                        ):
                            await transaction_db.rollback()
                            return CompanyControllerAuthoritativeCommandResult(
                                applied=False
                            )
                    if source_snapshot:
                        allowed_metadata_keys.update(validation_keys - {"delivery_package"})
                        allowed_metadata_keys.add(
                            "pre_delivery_validation_failure_kind"
                        )
                        allowed_context_keys.update(
                            {"delivery_package"}
                        )
                    for key in allowed_metadata_keys:
                        if key in submitted_metadata:
                            expected_metadata[key] = copy.deepcopy(
                                submitted_metadata[key]
                            )
                        else:
                            expected_metadata.pop(key, None)
                    expected_snapshot.metadata = expected_metadata
                    if cleanup_mode == "active_group":
                        durable_adaptive = dict(
                            (durable_snapshot.metadata or {}).get(
                                "adaptive", {}
                            )
                            or {}
                        )
                        submitted_adaptive = dict(
                            submitted_metadata.get("adaptive", {}) or {}
                        )
                        if str(
                            durable_adaptive.get("normalized_state", "")
                            or ""
                        ).strip().lower() == "invalidated":
                            expected_normalized_state = {
                                TaskStatus.DONE: "done",
                                TaskStatus.AWAITING_HUMAN: "awaiting_human",
                                TaskStatus.AWAITING_MANAGER_REVIEW: (
                                    "awaiting_manager_review"
                                ),
                                TaskStatus.AWAITING_REVIEW: "awaiting_review",
                            }.get(
                                durable_snapshot.status,
                                durable_snapshot.status.value,
                            )
                            durable_adaptive["normalized_state"] = (
                                expected_normalized_state
                            )
                            durable_adaptive["blocked_reason"] = ""
                        if submitted_adaptive != durable_adaptive:
                            await transaction_db.rollback()
                            return CompanyControllerAuthoritativeCommandResult(
                                applied=False
                            )
                        if "adaptive" in submitted_metadata:
                            expected_metadata["adaptive"] = copy.deepcopy(
                                submitted_adaptive
                            )
                        else:
                            expected_metadata.pop("adaptive", None)
                        expected_snapshot.metadata = expected_metadata
                    expected_context = dict(
                        expected_snapshot.context_snapshot or {}
                    )
                    submitted_context = dict(
                        submitted_snapshot.context_snapshot or {}
                    )
                    for key in allowed_context_keys:
                        if key in submitted_context:
                            expected_context[key] = copy.deepcopy(
                                submitted_context[key]
                            )
                        else:
                            expected_context.pop(key, None)
                    if source_snapshot:
                        durable_owned_outputs = dict(
                            expected_context.get(
                                "work_item_owned_outputs", {}
                            )
                            or {}
                        )
                        submitted_owned_outputs = dict(
                            submitted_context.get(
                                "work_item_owned_outputs", {}
                            )
                            or {}
                        )
                        if "delivery_package" in submitted_owned_outputs:
                            durable_owned_outputs["delivery_package"] = (
                                copy.deepcopy(
                                    submitted_owned_outputs[
                                        "delivery_package"
                                    ]
                                )
                            )
                        else:
                            durable_owned_outputs.pop(
                                "delivery_package", None
                            )
                        if submitted_owned_outputs != durable_owned_outputs:
                            await transaction_db.rollback()
                            return CompanyControllerAuthoritativeCommandResult(
                                applied=False
                            )
                        expected_context["work_item_owned_outputs"] = (
                            durable_owned_outputs
                        )
                    expected_snapshot.context_snapshot = expected_context
                    if (
                        _task_authoritative_preimage_hash(expected_snapshot)
                        != _task_authoritative_preimage_hash(
                            submitted_snapshot
                        )
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

            if owner_publication is not None:
                reserved_publication_capability: object | None = None
                authority_valid, durable_origin = (
                    await self._load_delivery_origin_authority_from_run(
                        transaction_db,
                        context=context,
                    )
                )
                supplied_origin = origin_owner_interaction
                origin_matches = (
                    durable_origin is None
                    and supplied_origin is None
                ) or (
                    durable_origin is not None
                    and supplied_origin is not None
                    and durable_origin.to_payload()
                    == supplied_origin.to_payload()
                )
                if not authority_valid or not origin_matches:
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(
                        applied=False
                    )
                if durable_origin is not None:
                    origin_accepted = (
                        await self._resolve_origin_owner_interaction_for_delivery(
                            transaction_db,
                            context=context,
                            origin=durable_origin,
                            resolved_at=checked_at,
                        )
                    )
                    if not origin_accepted:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

            prepared: list[
                tuple[
                    CompanyControllerWorkItemMutation,
                    DelegationWorkItem,
                    Phase,
                    datetime,
                ]
            ] = []
            for mutation in mutations:
                clean_id = str(mutation.work_item_id or "").strip()
                async with transaction_db.execute(
                    "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                    (clean_id,),
                ) as cursor:
                    row = await cursor.fetchone()
                    current = (
                        self._row_to_delegation_work_item(row, cursor.description)
                        if row is not None
                        else None
                    )
                if current is None or str(current.run_id or "").strip() != context.run_id:
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(applied=False)
                if mutation.expected_phases and current.phase not in set(
                    mutation.expected_phases
                ):
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(applied=False)
                if (
                    mutation.expected_updated_at is not None
                    and current.updated_at != mutation.expected_updated_at
                ):
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(applied=False)
                required_rework_count = (
                    mutation.required_pre_delivery_rework_count
                )
                rework_count_limit = mutation.pre_delivery_rework_count_limit
                if (required_rework_count is None) != (
                    rework_count_limit is None
                ):
                    raise ValueError(
                        "pre-delivery rework counter predicate requires both "
                        "the expected count and its limit"
                    )
                if required_rework_count is not None:
                    if (
                        operation not in deterministic_rework_operations
                        or clean_id != context.work_item_id
                        or int(required_rework_count) < 0
                        or int(rework_count_limit or 0) <= 0
                    ):
                        raise ValueError(
                            "deterministic rework counter predicate is restricted "
                            "to the source mutation of a named rework command"
                        )
                    durable_counter_task = await self._get_task_unhydrated(
                        context.task_id,
                        db=transaction_db,
                    )
                    try:
                        durable_rework_count = int(
                            dict(
                                getattr(
                                    durable_counter_task,
                                    "metadata",
                                    {},
                                )
                                or {}
                            ).get("pre_delivery_rework_count", 0)
                            or 0
                        )
                    except (TypeError, ValueError):
                        durable_rework_count = 0
                    if (
                        durable_counter_task is None
                        or durable_rework_count != int(required_rework_count)
                        or durable_rework_count >= int(rework_count_limit or 0)
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False,
                            conflict_reason=(
                                "pre_delivery_rework_count_mismatch"
                            ),
                        )
                required_validation_attempt = (
                    mutation.required_pre_delivery_validation_attempt_seq
                )
                required_package_hash = str(
                    mutation.required_delivery_package_sha256 or ""
                ).strip()
                if (required_validation_attempt is None) != (
                    not bool(required_package_hash)
                ):
                    raise ValueError(
                        "final-delivery validation predicate requires both "
                        "attempt and package hash"
                    )
                if required_validation_attempt is not None:
                    if operation not in {
                        "publish_final_delivery_owner_handoff",
                        "recover_final_delivery_owner_handoff",
                    }:
                        raise ValueError(
                            "final-delivery validation predicate is restricted "
                            "to owner publication"
                        )
                    durable_task = await self._get_task_unhydrated(
                        context.task_id,
                        db=transaction_db,
                    )
                    durable_package = copy.deepcopy(
                        dict(
                            (
                                (durable_task.context_snapshot or {})
                                .get("work_item_owned_outputs", {})
                                .get("delivery_package", {})
                                if durable_task is not None
                                else {}
                            )
                            or (
                                (durable_task.context_snapshot or {}).get(
                                    "delivery_package", {}
                                )
                                if durable_task is not None
                                else {}
                            )
                            or (current.metadata or {}).get(
                                "delivery_package", {}
                            )
                            or {}
                        )
                    )
                    try:
                        predicate_matches = bool(
                            durable_task is not None
                            and int(required_validation_attempt or 0) > 0
                            and validation_record_matches_current_delivery(
                                durable_task,
                                current,
                                durable_package,
                            )
                            and int(
                                (current.metadata or {}).get(
                                    "attempt_seq", 0
                                )
                                or 0
                            )
                            == int(required_validation_attempt or 0)
                            and str(
                                dict(
                                    (durable_task.metadata or {}).get(
                                        "pre_delivery_validation", {}
                                    )
                                    or {}
                                ).get("delivery_package_sha256", "")
                                or ""
                            ).strip()
                            == required_package_hash
                        )
                    except (TypeError, ValueError):
                        predicate_matches = False
                    if not predicate_matches:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                expected_report_id = mutation.latest_applied_report_work_item_id
                if expected_report_id is not None:
                    async with transaction_db.execute(
                        """SELECT report.work_item_id
                           FROM delegation_work_items AS report
                           WHERE report.run_id = ?
                             AND report.parent_work_item_id = ?
                             AND report.kind = 'report'
                             AND json_extract(
                                   report.metadata,
                                   '$.report_target_work_item_id'
                                 ) = ?
                             AND json_extract(
                                   report.metadata,
                                   '$.report_card_outcome'
                                 ) = 'applied'
                           ORDER BY report.batch_index DESC,
                                    report.created_at DESC,
                                    report.work_item_id DESC
                           LIMIT 1""",
                        (context.run_id, clean_id, clean_id),
                    ) as cursor:
                        report_row = await cursor.fetchone()
                    latest_report_id = str(report_row[0] if report_row else "").strip()
                    if latest_report_id != str(expected_report_id or "").strip():
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(applied=False)

                item = copy.deepcopy(current)
                previous_phase = item.phase
                previous_updated_at = item.updated_at
                if mutation.phase is not None:
                    target_phase = coerce_phase(mutation.phase)
                    if (
                        mutation.allow_approved_rework
                        and previous_phase == Phase.APPROVED
                    ):
                        if (
                            operation not in deterministic_rework_operations
                            or target_phase != Phase.READY_FOR_REWORK
                        ):
                            raise InvalidPhaseTransition(
                                "approved deterministic rework is restricted to "
                                "the named pre-delivery command and "
                                "ready_for_rework target"
                            )
                    elif (
                        mutation.allow_via_running
                        and previous_phase != Phase.RUNNING
                        and target_phase != Phase.RUNNING
                    ):
                        validate_transition(previous_phase, Phase.RUNNING)
                        validate_transition(Phase.RUNNING, target_phase)
                    else:
                        validate_transition(previous_phase, target_phase)
                    item.phase = target_phase
                if mutation.summary is not None:
                    item.summary = str(mutation.summary or "")
                if mutation.deliverable_summary is not None:
                    item.deliverable_summary = str(
                        mutation.deliverable_summary or ""
                    ).strip()
                if mutation.blocked_reason is not None:
                    item.blocked_reason = str(mutation.blocked_reason or "").strip()
                if mutation.handoff_status is not None:
                    item.handoff_status = str(mutation.handoff_status or "").strip()
                if mutation.claimed_by_role_runtime_session_id is not None:
                    item.claimed_by_role_runtime_session_id = str(
                        mutation.claimed_by_role_runtime_session_id or ""
                    ).strip()
                if mutation.claimed_by_seat_id is not None:
                    item.claimed_by_seat_id = str(
                        mutation.claimed_by_seat_id or ""
                    ).strip()
                metadata = dict(item.metadata or {})
                if clean_id in adopted_work_item_ids:
                    metadata["company_run_controller_owner_token"] = (
                        context.owner_token
                    )
                    metadata[
                        "company_run_controller_lease_generation"
                    ] = context.generation
                if mutation.phase is not None and item.phase != Phase.RUNNING:
                    metadata.update(
                        build_attempt_settlement_updates(
                            metadata,
                            outcome=mutation.attempt_outcome or item.phase.value,
                            settled_at=checked_at,
                        )
                    )
                metadata.update(copy.deepcopy(dict(mutation.metadata_updates or {})))
                transition_reason = str(mutation.transition_reason or "").strip()
                if transition_reason:
                    metadata["last_transition_reason"] = transition_reason
                for key, appended_values in dict(
                    mutation.metadata_list_appends or {}
                ).items():
                    current_values = list(metadata.get(key, []) or [])
                    metadata[key] = list(
                        dict.fromkeys([*current_values, *list(appended_values or ())])
                    )
                for key, removed_values in dict(
                    mutation.metadata_list_removes or {}
                ).items():
                    removed = set(removed_values or ())
                    metadata[key] = [
                        value
                        for value in list(metadata.get(key, []) or [])
                        if value not in removed
                    ]
                for key in mutation.metadata_unset:
                    metadata.pop(str(key), None)
                if mutation.clear_claim or item.phase in RUNNABLE_PHASES:
                    item.claimed_by_role_runtime_session_id = ""
                    item.claimed_by_seat_id = ""
                    metadata["claimed_by_role_session_id"] = ""
                    metadata["claimed_task_id"] = ""
                if (
                    self._metadata_has_work_item_projection_identity(metadata)
                    or str(item.projection_id or "").strip()
                    or str(item.kind or "").strip()
                ):
                    metadata, _ = migrate_work_item_projection_metadata(
                        metadata,
                        projection_id_fallback=str(
                            item.projection_id or item.work_item_id or ""
                        ).strip(),
                        turn_type_fallback=str(item.kind or "").strip(),
                    )
                if operation in deterministic_rework_operations:
                    snapshot = snapshot_by_work_item_id.get(clean_id)
                    if snapshot is None:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    snapshot_metadata = dict(snapshot.metadata or {})
                    try:
                        item_attempt = int(
                            metadata.get("attempt_seq", 0) or 0
                        )
                        snapshot_attempt = int(
                            snapshot_metadata.get(
                                "claimed_work_item_attempt_seq", 0
                            )
                            or 0
                        )
                        item_generation = int(
                            metadata.get(
                                "company_run_controller_lease_generation",
                                0,
                            )
                            or 0
                        )
                        snapshot_generation = int(
                            snapshot_metadata.get(
                                "company_run_controller_lease_generation",
                                0,
                            )
                            or 0
                        )
                    except (TypeError, ValueError):
                        item_attempt = snapshot_attempt = 0
                        item_generation = snapshot_generation = 0
                    item_owner = str(
                        metadata.get(
                            "company_run_controller_owner_token", ""
                        )
                        or ""
                    ).strip()
                    snapshot_owner = str(
                        snapshot_metadata.get(
                            "company_run_controller_owner_token", ""
                        )
                        or ""
                    ).strip()
                    if (
                        item_attempt <= 0
                        or item_attempt != snapshot_attempt
                        or metadata.get("attempt_settled") is not True
                        or item_owner != context.owner_token
                        or snapshot_owner != context.owner_token
                        or item_generation != context.generation
                        or snapshot_generation != context.generation
                        or projection_id_for_task(snapshot)
                        != str(item.projection_id or "").strip()
                        or work_item_projection_id_from_metadata(
                            metadata,
                            fallback="",
                        )
                        != str(item.projection_id or "").strip()
                        or work_item_turn_type_from_metadata(
                            metadata,
                            fallback="",
                        )
                        != canonical_work_item_turn_type_for_kind(
                            item.kind,
                            fallback="",
                        )
                        or work_item_turn_type_from_metadata(
                            snapshot_metadata,
                            fallback="",
                        )
                        != canonical_work_item_turn_type_for_kind(
                            item.kind,
                            fallback="",
                        )
                    ):
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                item.metadata = metadata
                self._protect_delegate_work_identity(item, existing=current)
                item.updated_at = checked_at
                prepared.append(
                    (mutation, item, previous_phase, previous_updated_at)
                )

            for item in insert_work_items:
                if str(item.run_id or "").strip() != context.run_id:
                    raise ValueError(
                        "authoritative command cannot insert into another run"
                    )
                item.metadata = dict(item.metadata or {})
                self._protect_delegate_work_identity(item, existing=None)
                if (
                    self._metadata_has_work_item_projection_identity(item.metadata)
                    or str(item.projection_id or "").strip()
                    or str(item.kind or "").strip()
                ):
                    item.metadata, _ = migrate_work_item_projection_metadata(
                        item.metadata,
                        projection_id_fallback=str(
                            item.projection_id or item.work_item_id or ""
                        ).strip(),
                        turn_type_fallback=str(item.kind or "").strip(),
                    )
                validate_transition(None, item.phase)
                cursor = await transaction_db.execute(
                    """INSERT INTO delegation_work_items
                       (work_item_id, run_id, cell_id, team_instance_id, team_id,
                        role_id, seat_id, seat_state_id, role_runtime_session_id,
                        parent_work_item_id, source_role_id, source_seat_id, title,
                        summary, kind, projection_id, phase, batch_id, batch_index,
                        deliverable_summary, blocked_reason, handoff_status,
                        continuation_source, manager_role_id, manager_seat_id,
                        claimed_by_role_runtime_session_id, claimed_by_seat_id,
                        metadata, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                               ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                       ON CONFLICT(work_item_id) DO NOTHING""",
                    self._delegation_work_item_insert_values(item),
                )
                if getattr(cursor, "rowcount", 0) or 0:
                    created_ids.append(str(item.work_item_id or "").strip())
                    phase_changes.append((None, item.phase, copy.deepcopy(item)))
                else:
                    async with transaction_db.execute(
                        "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                        (str(item.work_item_id or "").strip(),),
                    ) as existing_cursor:
                        existing_row = await existing_cursor.fetchone()
                        existing = (
                            self._row_to_delegation_work_item(
                                existing_row,
                                existing_cursor.description,
                            )
                            if existing_row is not None
                            else None
                        )
                    if existing is None:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    expected_metadata = dict(item.metadata or {})
                    existing_metadata = dict(existing.metadata or {})
                    semantic_keys: tuple[str, ...] = (
                        "follow_up_dedupe_key",
                        "report_target_work_item_id",
                        "report_attempt",
                        "review_target_work_item_id",
                        "review_attempt",
                        "intake_work_item_id",
                    )
                    if "intake_work_item_id" in expected_metadata:
                        semantic_keys += (
                            "dependency_work_item_ids",
                            "review_owner_kind",
                            "feedback_scope",
                            "authoritative_output",
                            "user_visible",
                            "requires_user_feedback",
                        )
                    identity_matches = (
                        str(existing.run_id or "").strip() == context.run_id
                        and str(existing.kind or "").strip()
                        == str(item.kind or "").strip()
                        and str(existing.projection_id or "").strip()
                        == str(item.projection_id or "").strip()
                        and str(existing.parent_work_item_id or "").strip()
                        == str(item.parent_work_item_id or "").strip()
                        and str(existing.role_id or "").strip()
                        == str(item.role_id or "").strip()
                        and str(existing.seat_id or "").strip()
                        == str(item.seat_id or "").strip()
                        and all(
                            existing_metadata.get(key) == expected_metadata.get(key)
                            for key in semantic_keys
                            if key in expected_metadata
                        )
                    )
                    if not identity_matches:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )

            for mutation, item, previous_phase, previous_updated_at in prepared:
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, summary = ?, deliverable_summary = ?,
                           blocked_reason = ?, handoff_status = ?,
                           claimed_by_role_runtime_session_id = ?,
                           claimed_by_seat_id = ?, metadata = ?, updated_at = ?
                       WHERE work_item_id = ?
                         AND run_id = ?
                         AND phase = ?
                         AND updated_at = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = delegation_work_items.run_id
                               AND run.project_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        item.phase.value,
                        item.summary,
                        item.deliverable_summary,
                        item.blocked_reason,
                        item.handoff_status,
                        item.claimed_by_role_runtime_session_id,
                        item.claimed_by_seat_id,
                        _json_dumps(item.metadata),
                        item.updated_at.isoformat(),
                        str(item.work_item_id or "").strip(),
                        context.run_id,
                        previous_phase.value,
                        previous_updated_at.isoformat(),
                        context.project_id,
                        context.owner_token,
                        context.generation,
                        checked_at.isoformat(),
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(applied=False)
                persisted_mutations.append(item)
                if item.phase != previous_phase:
                    phase_changes.append((previous_phase, item.phase, item))

            if task_snapshot_to_save is not None:
                await self._save_task_row(
                    task_snapshot_to_save,
                    commit=False,
                    db=transaction_db,
                )
            for additional_snapshot in additional_task_snapshots_to_save:
                await self._save_task_row(
                    additional_snapshot,
                    commit=False,
                    db=transaction_db,
                )
            if run_mutation is not None:
                run_result = (
                    await self._mutate_delegation_run_lifecycle_for_controller(
                        transaction_db,
                        run_id=context.run_id,
                        project_id=context.project_id,
                        root_session_id=None,
                        owner_token=context.owner_token,
                        generation=context.generation,
                        mutation=run_mutation,
                        checked_at=checked_at,
                    )
                )
                if not run_result.applied:
                    await transaction_db.rollback()
                    return CompanyControllerAuthoritativeCommandResult(
                        applied=False,
                        run=run_result.run,
                    )
                persisted_run = run_result.run
            if owner_publication is not None:
                # The proof is stamped here, inside the same transaction that
                # moves Task/WorkItem/run to awaiting-owner and inserts the
                # checkpoint.  A legacy or separately-created feedback row can
                # copy public attempt/hash fields, but cannot acquire this
                # authoritative commit provenance through the generic owner
                # publication API.
                if operation in {
                    "publish_final_delivery_owner_handoff",
                    "recover_final_delivery_owner_handoff",
                }:
                    source_mutation = next(
                        (
                            mutation
                            for mutation in mutations
                            if str(mutation.work_item_id or "").strip()
                            == context.work_item_id
                        ),
                        None,
                    )
                    if source_mutation is None:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    prepared_source = next(
                        (
                            item
                            for mutation, item, _phase, _updated_at in prepared
                            if str(mutation.work_item_id or "").strip()
                            == context.work_item_id
                        ),
                        None,
                    )
                    try:
                        publication_attempt = int(
                            source_mutation.required_pre_delivery_validation_attempt_seq
                            or dict(
                                getattr(prepared_source, "metadata", {}) or {}
                            ).get("attempt_seq", 0)
                            or 0
                        )
                    except (TypeError, ValueError):
                        publication_attempt = 0
                    publication_package = copy.deepcopy(
                        dict(
                            source_mutation.metadata_updates.get(
                                "delivery_package", {}
                            )
                            or dict(
                                getattr(prepared_source, "metadata", {}) or {}
                            ).get("delivery_package", {})
                            or {}
                        )
                    )
                    publication_hash = str(
                        source_mutation.required_delivery_package_sha256 or ""
                    ).strip()
                    if not publication_hash:
                        try:
                            publication_hash = delivery_package_sha256(
                                publication_package
                            )
                        except (TypeError, ValueError):
                            publication_hash = ""
                    if publication_attempt <= 0 or not publication_hash:
                        await transaction_db.rollback()
                        return CompanyControllerAuthoritativeCommandResult(
                            applied=False
                        )
                    owner_publication.checkpoint.payload = dict(
                        owner_publication.checkpoint.payload or {}
                    )
                    owner_publication.checkpoint.payload.update(
                        {
                            "waiting_task_id": context.task_id,
                            "waiting_work_item_id": context.work_item_id,
                            "work_item_attempt_seq": publication_attempt,
                            "delivery_package_sha256": publication_hash,
                        }
                    )
                    owner_publication.checkpoint.payload[
                        FINAL_DELIVERY_PUBLICATION_PROVENANCE_KEY
                    ] = final_delivery_publication_provenance(
                        run_id=context.run_id,
                        task_id=context.task_id,
                        work_item_id=context.work_item_id,
                        attempt_seq=publication_attempt,
                        package_hash=publication_hash,
                    )
                    reserved_publication_capability = (
                        _FINAL_DELIVERY_PUBLICATION_CAPABILITY
                    )
                persisted_checkpoint, checkpoint_created = (
                    await self._publish_owner_interaction_checkpoint(
                        owner_publication.checkpoint,
                        interaction_key=owner_publication.interaction_key,
                        supersede_pending_scope=True,
                        supersession_key=owner_publication.supersession_key,
                        supersession_order=owner_publication.supersession_order,
                        transaction_open=True,
                        db=transaction_db,
                        reserved_publication_capability=(
                            reserved_publication_capability
                        ),
                    )
                )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        for previous_phase, target_phase, item in phase_changes:
            try:
                await on_phase_transition(
                    previous_phase,
                    target_phase,
                    item,
                    store=self,
                    notifications_only=True,
                )
            except CompanyRunControllerLeaseLost:
                logger.warning(
                    "Post-commit phase notification observed controller "
                    "takeover for authoritative command {} work_item={}",
                    operation,
                    str(item.work_item_id or "").strip(),
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "on_phase_transition raised after authoritative command"
                )
        for previous_phase, target_phase, item in phase_changes:
            if previous_phase is None:
                continue
            if target_phase not in DONE_PHASES and target_phase not in {
                Phase.AWAITING_HUMAN,
                Phase.READY_FOR_REWORK,
            }:
                continue
            from opc.layer2_organization.work_item_transition import (
                refresh_dependents_for_controller,
            )

            try:
                await refresh_dependents_for_controller(
                    self,
                    run_id=context.run_id,
                    project_id=context.project_id,
                    controller_owner_token=context.owner_token,
                    controller_lease_generation=context.generation,
                    source_work_item_id=str(item.work_item_id or "").strip(),
                    source_task_id=context.task_id,
                    source_role_id=str(item.role_id or "").strip() or None,
                    source_cell_id=str(item.cell_id or "").strip() or None,
                )
            except CompanyRunControllerLeaseLost:
                logger.warning(
                    "Post-commit dependent refresh observed controller "
                    "takeover for authoritative command {} work_item={}",
                    operation,
                    str(item.work_item_id or "").strip(),
                )
            except Exception:
                # The authoritative transaction is already committed.  A
                # notification/frontier refresh failure must never make the
                # caller reinterpret committed business state as a failed
                # command and issue a contradictory fallback transition.
                logger.opt(exception=True).warning(
                    "Post-commit dependent refresh failed for authoritative "
                    "command {} work_item={}",
                    operation,
                    str(item.work_item_id or "").strip(),
                )
        return CompanyControllerAuthoritativeCommandResult(
            applied=True,
            work_items=tuple(persisted_mutations),
            inserted_work_item_ids=tuple(created_ids),
            run=persisted_run,
            owner_checkpoint=persisted_checkpoint,
            owner_checkpoint_created=checkpoint_created,
        )

    async def requeue_unpublished_delivery_for_controller(
        self,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        task_id: str,
        work_item_id: str,
        expected_task_preimage_hash: str,
        expected_work_item_updated_at: datetime,
    ) -> FinalDeliveryStartupAuditResult:
        """Atomically make a crash-before-publication delivery runnable again.

        A deterministic validator runs before the CEO pre-delivery gate.  A
        passed validator record alone therefore cannot authorize startup to
        manufacture an owner card.  Under the startup controller lease this
        command instead clears the unpublished output projection and reopens
        the exact delivery attempt.  An already-published feedback checkpoint
        blocks the reset in the same transaction.
        """

        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_task_id = str(task_id or "").strip()
        clean_work_item_id = str(work_item_id or "").strip()
        clean_generation = int(generation or 0)
        expected_task_hash = str(expected_task_preimage_hash or "").strip()
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
            or not clean_task_id
            or not clean_work_item_id
            or not expected_task_hash
            or not isinstance(expected_work_item_updated_at, datetime)
        ):
            raise ValueError(
                "delivery recovery requires an exact controller and preimage"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        persisted_item: DelegationWorkItem | None = None
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=clean_run_id,
                project_id=clean_project_id,
                owner_token=clean_owner_token,
                generation=clean_generation,
                checked_at=checked_at,
            )
            durable_task = await self._get_task_unhydrated(
                clean_task_id,
                db=transaction_db,
            )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (clean_work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                current = (
                    self._row_to_delegation_work_item(row, cursor.description)
                    if row is not None
                    else None
                )
            if (
                durable_task is None
                or current is None
                or str(durable_task.project_id or "default").strip()
                != clean_project_id
                or str(current.run_id or "").strip() != clean_run_id
                or current.phase != Phase.AWAITING_HUMAN
                or current.updated_at != expected_work_item_updated_at
                or durable_task.status != TaskStatus.AWAITING_HUMAN
                or _task_authoritative_preimage_hash(durable_task)
                != expected_task_hash
            ):
                await transaction_db.rollback()
                return FinalDeliveryStartupAuditResult(outcome="conflict")
            task_metadata = dict(durable_task.metadata or {})
            item_metadata = dict(current.metadata or {})
            try:
                task_attempt = int(
                    task_metadata.get("claimed_work_item_attempt_seq", 0)
                    or 0
                )
                item_attempt = int(item_metadata.get("attempt_seq", 0) or 0)
                task_generation = int(
                    task_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
                item_generation = int(
                    item_metadata.get(
                        "company_run_controller_lease_generation", 0
                    )
                    or 0
                )
            except (TypeError, ValueError):
                task_attempt = item_attempt = 0
                task_generation = item_generation = 0
            task_owner = str(
                task_metadata.get(
                    "company_run_controller_owner_token", ""
                )
                or ""
            ).strip()
            item_owner = str(
                item_metadata.get(
                    "company_run_controller_owner_token", ""
                )
                or ""
            ).strip()
            task_projection = projection_id_for_task(durable_task)
            item_projection = str(current.projection_id or "").strip()
            current_envelope = (
                task_owner == clean_owner_token
                and task_generation == clean_generation
            )
            settled_previous_envelope = (
                bool(task_owner)
                and task_owner == item_owner
                and 0 < task_generation == item_generation < clean_generation
            )
            if (
                task_attempt <= 0
                or task_attempt != item_attempt
                or item_metadata.get("attempt_settled") is not True
                or not task_projection
                or task_projection != item_projection
                or task_owner != item_owner
                or task_generation != item_generation
                or not (current_envelope or settled_previous_envelope)
                or str(task_metadata.get("delegation_run_id", "") or "").strip()
                != clean_run_id
            ):
                await transaction_db.rollback()
                return FinalDeliveryStartupAuditResult(outcome="conflict")
            async with transaction_db.execute(
                """SELECT 1
                   FROM work_item_runtime_links
                   WHERE work_item_id = ? AND runtime_task_id = ?
                   LIMIT 1""",
                (clean_work_item_id, clean_task_id),
            ) as cursor:
                if await cursor.fetchone() is None:
                    await transaction_db.rollback()
                    return FinalDeliveryStartupAuditResult(outcome="conflict")
            async with transaction_db.execute(
                """SELECT * FROM execution_checkpoints
                   WHERE project_id = ?
                     AND checkpoint_type = 'company_delivery_feedback'
                     AND status IN ('pending', 'answered', 'consuming')
                     AND (
                         task_id = ?
                         OR json_extract(payload, '$.waiting_task_id') = ?
                     )
                   ORDER BY created_at ASC, checkpoint_id ASC""",
                (
                    clean_project_id,
                    clean_task_id,
                    clean_task_id,
                ),
            ) as cursor:
                checkpoint_rows = await cursor.fetchall()
                checkpoint_columns = [item[0] for item in cursor.description]
            validation_hash = str(
                dict(
                    task_metadata.get("pre_delivery_validation", {}) or {}
                ).get("delivery_package_sha256", "")
                or ""
            ).strip()
            durable_package = copy.deepcopy(
                dict(
                    (durable_task.context_snapshot or {})
                    .get("work_item_owned_outputs", {})
                    .get("delivery_package", {})
                    or (durable_task.context_snapshot or {}).get(
                        "delivery_package", {}
                    )
                    or (current.metadata or {}).get("delivery_package", {})
                    or {}
                )
            )
            current_validation_matches = (
                validation_record_matches_current_delivery(
                    durable_task,
                    current,
                    durable_package,
                )
            )
            decoded_checkpoints: list[ExecutionCheckpoint] = [
                self._execution_checkpoint_from_data(
                    dict(zip(checkpoint_columns, checkpoint_row))
                )
                for checkpoint_row in checkpoint_rows
            ]
            exact_checkpoints = [
                checkpoint
                for checkpoint in decoded_checkpoints
                if current_validation_matches
                and final_delivery_checkpoint_payload_matches(
                    checkpoint.payload,
                    run_id=clean_run_id,
                    task_id=clean_task_id,
                    work_item_id=clean_work_item_id,
                    attempt_seq=item_attempt,
                    package_hash=validation_hash,
                )
            ]
            canonical_checkpoint = exact_checkpoints[0] if exact_checkpoints else None
            retired_checkpoint_ids: list[str] = []
            for checkpoint in decoded_checkpoints:
                checkpoint_data = dict(
                    checkpoint.payload or {}
                )
                if (
                    canonical_checkpoint is not None
                    and checkpoint.checkpoint_id
                    == canonical_checkpoint.checkpoint_id
                ):
                    continue
                # A validator-enabled startup may encounter a legacy card or
                # an active row for an older attempt/package.  Retire it in
                # this same transaction before reopening the delivery, so an
                # answer cannot race the requeue and no invalid card remains
                # actionable against the new attempt.
                stale_payload = checkpoint_data
                stale_payload.update(
                    {
                        "stale_reason": (
                            "not_current_atomic_final_delivery_publication"
                        ),
                        "stale_at": checked_at.isoformat(),
                        "administrative_reason": (
                            "pre_delivery_restart_revalidation"
                        ),
                        "administrative_closed_at": checked_at.isoformat(),
                    }
                )
                cursor = await transaction_db.execute(
                    """UPDATE execution_checkpoints
                       SET status = 'invalid', payload = ?, updated_at = ?
                       WHERE checkpoint_id = ? AND project_id = ?
                         AND checkpoint_type = 'company_delivery_feedback'
                         AND status = ?""",
                    (
                        _json_dumps(stale_payload),
                        checked_at.isoformat(),
                        checkpoint.checkpoint_id,
                        clean_project_id,
                        checkpoint.status,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return FinalDeliveryStartupAuditResult(outcome="conflict")
                retired_checkpoint_ids.append(checkpoint.checkpoint_id)

            if canonical_checkpoint is not None:
                await transaction_db.commit()
                return FinalDeliveryStartupAuditResult(
                    outcome="preserved",
                    canonical_checkpoint=canonical_checkpoint,
                    retired_checkpoint_ids=tuple(retired_checkpoint_ids),
                )

            validate_transition(
                Phase.AWAITING_HUMAN,
                Phase.READY_FOR_REWORK,
            )
            item = copy.deepcopy(current)
            item.phase = Phase.READY_FOR_REWORK
            item.deliverable_summary = ""
            item.blocked_reason = ""
            item.claimed_by_role_runtime_session_id = ""
            item.claimed_by_seat_id = ""
            item_metadata = dict(item.metadata or {})
            for key in (
                "pre_delivery_validation",
                "pre_delivery_validation_evidence",
                "pre_delivery_validation_failure_kind",
                "delivery_package",
                "completion_report",
                "work_item_summary",
                "work_item_summary_for_downstream",
                "work_item_artifact_index",
                "verification_status",
                "verification_evidence",
                "verification",
            ):
                item_metadata.pop(key, None)
            item_metadata.update(
                {
                    "claimed_by_role_session_id": "",
                    "claimed_task_id": "",
                    "company_run_controller_owner_token": clean_owner_token,
                    "company_run_controller_lease_generation": clean_generation,
                    "pre_delivery_restart_requeued_at": checked_at.isoformat(),
                    "pre_delivery_restart_requeue_reason": (
                        "atomic_final_publication_not_observed"
                    ),
                    "last_transition_reason": (
                        "pre_delivery_restart_revalidation"
                    ),
                }
            )
            item.metadata = item_metadata
            item.updated_at = checked_at
            cursor = await transaction_db.execute(
                """UPDATE delegation_work_items
                   SET phase = ?, deliverable_summary = '', blocked_reason = '',
                       claimed_by_role_runtime_session_id = '',
                       claimed_by_seat_id = '', metadata = ?, updated_at = ?
                   WHERE work_item_id = ? AND run_id = ?
                     AND phase = ? AND updated_at = ?
                     AND EXISTS (
                         SELECT 1 FROM delegation_runs
                         WHERE run_id = ? AND project_id = ? AND session_id = ?
                           AND controller_owner_token = ?
                           AND controller_lease_generation = ?
                           AND controller_lease_expires_at > ?
                     )""",
                (
                    item.phase.value,
                    _json_dumps(item.metadata),
                    item.updated_at.isoformat(),
                    clean_work_item_id,
                    clean_run_id,
                    current.phase.value,
                    current.updated_at.isoformat(),
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at.isoformat(),
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                await transaction_db.rollback()
                return FinalDeliveryStartupAuditResult(outcome="conflict")

            task_snapshot = copy.deepcopy(durable_task)
            task_snapshot.status = TaskStatus.PENDING
            task_snapshot.result = None
            task_snapshot.execution_lock = False
            task_snapshot.execution_locked_at = None
            task_snapshot.metadata = dict(task_snapshot.metadata or {})
            for key in (
                "pre_delivery_validation",
                "pre_delivery_validation_evidence",
                "pre_delivery_validation_failure_kind",
            ):
                task_snapshot.metadata.pop(key, None)
            task_snapshot.metadata.update(
                {
                    "company_run_controller_owner_token": clean_owner_token,
                    "company_run_controller_lease_generation": clean_generation,
                    "pre_delivery_restart_requeued_at": checked_at.isoformat(),
                    "pre_delivery_restart_requeue_reason": (
                        "atomic_final_publication_not_observed"
                    ),
                }
            )
            task_snapshot.context_snapshot = dict(
                task_snapshot.context_snapshot or {}
            )
            task_snapshot.context_snapshot.pop("delivery_package", None)
            owned_outputs = dict(
                task_snapshot.context_snapshot.get(
                    "work_item_owned_outputs", {}
                )
                or {}
            )
            for key in (
                "delivery_package",
                "work_item_summary",
                "work_item_summary_for_downstream",
                "work_item_artifact_index",
                "verification_status",
                "verification_evidence",
                "verification",
            ):
                owned_outputs.pop(key, None)
            task_snapshot.context_snapshot[
                "work_item_owned_outputs"
            ] = owned_outputs
            await self._save_task_row(
                task_snapshot,
                commit=False,
                db=transaction_db,
            )
            await transaction_db.commit()
            persisted_item = item
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        if persisted_item is not None:
            try:
                await on_phase_transition(
                    Phase.AWAITING_HUMAN,
                    Phase.READY_FOR_REWORK,
                    persisted_item,
                    store=self,
                    notifications_only=True,
                )
            except CompanyRunControllerLeaseLost:
                # The requeue transaction is already committed.  A takeover
                # observed by the best-effort notification cannot be surfaced
                # as if the durable reset failed; startup will reload the new
                # state and the active controller owns subsequent scheduling.
                logger.warning(
                    "delivery restart requeue notification observed "
                    "controller takeover for work_item={}",
                    str(persisted_item.work_item_id or "").strip(),
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "delivery restart requeue notification failed"
                )
        return FinalDeliveryStartupAuditResult(
            outcome="requeued" if persisted_item is not None else "conflict",
            retired_checkpoint_ids=tuple(retired_checkpoint_ids),
        )

    async def sync_runtime_task_status_for_work_item_projection(
        self,
        item: DelegationWorkItem,
        status: TaskStatus,
    ) -> bool:
        """CAS-project a WorkItem phase onto its linked runtime Task.

        This compatibility hook is restricted to runs which have not entered
        the controller protocol.  Live-controller transitions already update
        the Task inside their authoritative transaction, and full unclaimed
        projection refreshes use the explicit run-lease boundary.  A
        credential-free pre-claim Task must never turn this legacy hook into a
        live-controller write bypass.
        """

        db = self._require_db()
        updated_at = getattr(item, "updated_at", None)
        if not isinstance(updated_at, datetime):
            return False
        cursor = await db.execute(
            """UPDATE tasks
               SET status = ?
               WHERE id = (
                   SELECT runtime_task_id
                   FROM work_item_runtime_links
                   WHERE work_item_id = ?
               )
                 AND EXISTS (
                     SELECT 1
                     FROM delegation_work_items AS current_item
                     WHERE current_item.work_item_id = ?
                       AND current_item.phase = ?
                       AND current_item.updated_at = ?
                 )
                 AND NOT EXISTS (
                     SELECT 1
                     FROM delegation_work_items AS owned_item
                     JOIN delegation_runs AS owned_run
                       ON owned_run.run_id = owned_item.run_id
                     WHERE owned_item.work_item_id = ?
                       AND owned_run.controller_lease_generation > 0
                 )""",
            (
                status.value,
                str(item.work_item_id or "").strip(),
                str(item.work_item_id or "").strip(),
                item.phase.value,
                updated_at.isoformat(),
                str(item.work_item_id or "").strip(),
            ),
        )
        await db.commit()
        return bool(getattr(cursor, "rowcount", 0) or 0)

    async def _close_company_delivery_review_task_row(
        self,
        *,
        task_id: str,
        project_id: str,
        resolution: str,
        closed_at: str,
        checkpoint_id: str = "",
        metadata_updates: dict[str, Any] | None = None,
    ) -> tuple[Task | None, dict[str, Any]]:
        """Close one delivery-review Task inside the caller's transaction."""

        task = await self._get_task_unhydrated(task_id)
        if task is None or (
            str(task.project_id or "default").strip() or "default"
        ) != project_id:
            return None, {}
        task.metadata = dict(task.metadata or {})
        task.metadata.update(copy.deepcopy(dict(metadata_updates or {})))
        if checkpoint_id:
            task.metadata["human_review_checkpoint_id"] = checkpoint_id
        progress = list(task.metadata.get("progress_log", []) or [])
        progress.append(f"Delivery human review closed: {resolution}.")
        close_updates = {
            "requires_user_feedback": False,
            "human_review_closed": True,
            "human_review_closed_at": closed_at,
            "human_review_resolution": resolution,
            "feedback_closed": True,
            "feedback_resolved": True,
            "feedback_resolution": resolution,
            "feedback_closed_at": closed_at,
            "progress_log": progress[-50:],
        }
        task.metadata.update(close_updates)
        task.status = TaskStatus.DONE
        task.execution_lock = False
        task.execution_locked_at = None
        await self._save_task_row(task, commit=False)
        return task, close_updates

    async def close_company_delivery_review_task(
        self,
        *,
        task_id: str,
        project_id: str,
        resolution: str,
        closed_at: str,
        checkpoint_id: str = "",
        metadata_updates: dict[str, Any] | None = None,
    ) -> tuple[Task | None, dict[str, Any]]:
        """Persist the canonical delivery-review Task closure."""

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        task_id = str(task_id or "").strip()
        resolution = str(resolution or "").strip()
        closed_at = str(closed_at or "").strip()
        if not task_id or not resolution or not closed_at:
            raise ValueError("task_id, resolution, and closed_at are required")
        self._assert_project_write_scope(
            project_id,
            operation="close_company_delivery_review_task",
            entity=f"task {task_id!r}",
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            result = await self._close_company_delivery_review_task_row(
                task_id=task_id,
                project_id=project_id,
                resolution=resolution,
                closed_at=closed_at,
                checkpoint_id=str(checkpoint_id or "").strip(),
                metadata_updates=metadata_updates,
            )
            await self._db.commit()
            return result
        except Exception:
            await self._db.rollback()
            raise

    async def _find_existing_runtime_task_for_work_item(
        self,
        work_item: DelegationWorkItem,
        candidate_task: Task,
    ) -> Task | None:
        assert self._db is not None
        session_id = str(getattr(candidate_task, "session_id", "") or "").strip()
        project_id = str(getattr(candidate_task, "project_id", "") or "").strip()
        projection_id = projection_id_for_work_item(work_item)
        run_id = str(getattr(work_item, "run_id", "") or "").strip()
        if not session_id or not project_id or not projection_id or not run_id:
            return None
        async with self._db.execute(
            """SELECT * FROM tasks
               WHERE session_id=?
                 AND project_id=?
                 AND metadata LIKE ?
                 AND metadata LIKE ?
               ORDER BY created_at ASC, id ASC""",
            (
                session_id,
                project_id,
                "%work_item_runtime%",
                f"%{projection_id}%",
            ),
        ) as cursor:
            rows = await cursor.fetchall()
            description = cursor.description

        candidates: list[Task] = []
        for row in rows:
            task = self._row_to_task(row, description)
            metadata = dict(task.metadata or {})
            if str(metadata.get("delegation_run_id", "") or "").strip() != run_id:
                continue
            if str(metadata.get(WORK_ITEM_PROJECTION_ID_KEY, "") or "").strip() != projection_id:
                continue
            if not self._runtime_task_matches_work_item(task, work_item):
                continue
            candidates.append(task)
        if not candidates:
            return None

        def _candidate_sort_key(task: Task) -> tuple[int, int, datetime, str]:
            metadata = dict(task.metadata or {})
            status = str(task.status.value if hasattr(task.status, "value") else task.status or "").strip().lower()
            terminal = 1 if status in self._terminal_task_statuses() else 0
            duplicate = 1 if str(metadata.get("duplicate_runtime_task_of", "") or "").strip() else 0
            return (duplicate, terminal, task.created_at, str(task.id or ""))

        candidates.sort(key=_candidate_sort_key)
        if len(candidates) > 1:
            logger.warning(
                "ensure_runtime_task_for_work_item: multiple exact runtime Tasks "
                f"for work_item={work_item.work_item_id}; using task={candidates[0].id} "
                f"candidates={[task.id for task in candidates[:5]]}"
            )
        return candidates[0]

    async def ensure_runtime_task_for_work_item(
        self,
        work_item: DelegationWorkItem,
        task_factory: Any,
        *,
        replace_policy: str = "never_active",
        project_id: str = "",
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> Task:
        """Return the authoritative runtime Task for a WorkItem.

        This is the only hot-path creation/reuse entry point for company-mode
        runtime Tasks. It writes the structured link in the same transaction as
        task creation, and ordinary read paths do not repair or rescore links.
        Once a run has entered the controller protocol, the exact live run
        owner/generation is checked before either a Task or link can be
        observed as the result of this scheduling step.
        """
        if self._db is None:
            raise RuntimeError("store is not initialized")
        wid = str(getattr(work_item, "work_item_id", "") or "").strip()
        if not wid:
            raise ValueError("work_item_id is required")
        policy = str(replace_policy or "never_active").strip() or "never_active"
        if policy != "never_active":
            raise ValueError(f"unsupported runtime link replace_policy: {replace_policy}")

        supplied_run_id = str(getattr(work_item, "run_id", "") or "").strip()
        supplied_project_id = str(project_id or "").strip()
        owner_token = str(controller_owner_token or "").strip()
        generation = int(controller_lease_generation or 0)
        if bool(owner_token) != (generation > 0):
            raise CompanyRunControllerLeaseLost(
                "runtime Task materialization has an incomplete run controller lease"
            )

        await self._db.execute("BEGIN IMMEDIATE")
        try:
            async with self._db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (wid,),
            ) as item_cursor:
                item_row = await item_cursor.fetchone()
                persisted_work_item = (
                    self._row_to_delegation_work_item(
                        item_row,
                        item_cursor.description,
                    )
                    if item_row is not None
                    else None
                )
            if persisted_work_item is None:
                raise ValueError(f"WorkItem does not exist: {wid}")
            persisted_run_id = str(persisted_work_item.run_id or "").strip()
            if not supplied_run_id or supplied_run_id != persisted_run_id:
                raise ValueError(
                    "runtime Task materialization WorkItem scope changed before commit"
                )
            await self._require_company_controller_record_write(
                self._db,
                run_id=persisted_run_id,
                project_id=supplied_project_id or "default",
                owner_token=owner_token,
                generation=generation,
                checked_at=datetime.now(),
                work_item_id=wid,
            )

            persisted_projection_id = projection_id_for_work_item(
                persisted_work_item
            )
            supplied_projection_id = projection_id_for_work_item(work_item)
            persisted_turn_type = canonical_work_item_turn_type_for_kind(
                persisted_work_item.kind,
                fallback="",
            )
            supplied_turn_type = canonical_work_item_turn_type_for_kind(
                work_item.kind,
                fallback="",
            )
            if (
                not persisted_projection_id
                or persisted_projection_id != supplied_projection_id
                or not persisted_turn_type
                or persisted_turn_type != supplied_turn_type
                or str(persisted_work_item.role_id or "").strip()
                != str(work_item.role_id or "").strip()
                or str(persisted_work_item.seat_id or "").strip()
                != str(work_item.seat_id or "").strip()
                or str(
                    persisted_work_item.role_runtime_session_id or ""
                ).strip()
                != str(work_item.role_runtime_session_id or "").strip()
            ):
                raise ValueError(
                    "runtime Task materialization WorkItem identity changed before commit"
                )

            persisted_work_item_metadata = dict(
                persisted_work_item.metadata or {}
            )
            work_item_is_unclaimed = not bool(
                str(
                    persisted_work_item.claimed_by_role_runtime_session_id
                    or ""
                ).strip()
                or str(persisted_work_item.claimed_by_seat_id or "").strip()
                or str(
                    persisted_work_item_metadata.get("claimed_task_id", "")
                    or ""
                ).strip()
            )

            linked_task_id = await self._runtime_link_task_id_for_work_item(wid)
            if linked_task_id:
                linked_task = await self._get_task_unhydrated(linked_task_id)
                if linked_task is not None:
                    set_linked_work_item_id(linked_task, wid)
                    if (
                        owner_token
                        and work_item_is_unclaimed
                        and self._task_has_company_attempt_credential(
                            linked_task
                        )
                    ):
                        raise CompanyRunControllerLeaseLost(
                            "unclaimed materialized Task carries an attempt "
                            "credential"
                        )
                    issues = [
                        issue
                        for issue in validate_work_item_runtime_projection(
                            linked_task,
                            persisted_work_item,
                        )
                        if issue.severity == "error"
                    ]
                    if issues:
                        raise RuntimeError(
                            "work-item runtime invariant failed for linked Task "
                            f"{linked_task.id}: "
                            + "; ".join(f"{issue.code}: {issue.message}" for issue in issues)
                        )
                    await self._db.commit()
                    return linked_task
                await self._db.execute(
                    "DELETE FROM work_item_runtime_links WHERE work_item_id=?",
                    (wid,),
                )

            candidate = task_factory() if callable(task_factory) else task_factory
            if inspect.isawaitable(candidate):
                candidate = await candidate
            if not isinstance(candidate, Task):
                raise TypeError("task_factory must return a Task")
            candidate.metadata = dict(candidate.metadata or {})
            candidate_project_id = (
                str(candidate.project_id or "default").strip() or "default"
            )
            if supplied_project_id and candidate_project_id != supplied_project_id:
                raise ValueError(
                    "runtime Task materialization project does not match controller scope"
                )
            if str(
                candidate.metadata.get("delegation_run_id", "") or ""
            ).strip() != persisted_run_id:
                raise ValueError(
                    "runtime Task materialization candidate has the wrong run scope"
                )
            if owner_token and self._task_has_company_attempt_credential(
                candidate
            ):
                raise CompanyRunControllerLeaseLost(
                    "unclaimed materialization candidate carries an attempt "
                    "credential"
                )
            task = await self._find_existing_runtime_task_for_work_item(
                persisted_work_item,
                candidate,
            )
            if (
                task is not None
                and owner_token
                and work_item_is_unclaimed
                and self._task_has_company_attempt_credential(task)
            ):
                raise CompanyRunControllerLeaseLost(
                    "unclaimed reusable Task carries an attempt credential"
                )
            if task is None:
                task = candidate
                await self._save_task_row(task, commit=False)

            existing_owner_id = await self._runtime_link_work_item_id_for_task(task.id)
            if existing_owner_id and existing_owner_id != wid:
                raise RuntimeError(
                    "runtime Task is already linked to another WorkItem: "
                    f"task={task.id} owner={existing_owner_id} requested={wid}"
                )

            linked = await self._write_work_item_runtime_link(
                wid,
                task.id,
                link_kind="primary",
                commit=False,
            )
            if not linked:
                raise RuntimeError(
                    f"failed to link runtime Task {task.id} for WorkItem {wid}"
                )
            set_linked_work_item_id(task, wid)
            issues = [
                issue
                for issue in validate_work_item_runtime_projection(
                    task,
                    persisted_work_item,
                )
                if issue.severity == "error"
            ]
            if issues:
                raise RuntimeError(
                    "work-item runtime invariant failed for Task "
                    f"{task.id}: "
                    + "; ".join(f"{issue.code}: {issue.message}" for issue in issues)
                )
            await self._db.commit()
            return task
        except BaseException:
            await self._db.rollback()
            raise

    async def link_work_item_runtime_task(
        self,
        work_item_id: str,
        runtime_task_id: str,
        *,
        link_kind: str = "primary",
        allow_replace: bool = False,
    ) -> bool:
        """Persist the authoritative WorkItem -> runtime Task link."""
        if self._db is None:
            return False
        wid = str(work_item_id or "").strip()
        tid = str(runtime_task_id or "").strip()
        if not wid or not tid:
            return False
        if not await self._work_item_exists(wid) or not await self._task_exists(tid):
            return False
        await self._db.execute("BEGIN IMMEDIATE")
        try:
            existing_task_id = await self._runtime_link_task_id_for_work_item(wid)
            existing_owner_id = await self._runtime_link_work_item_id_for_task(tid)
            if existing_task_id and existing_task_id != tid and not allow_replace:
                if not await self._runtime_task_link_is_replaceable(existing_task_id):
                    logger.warning(
                        "work-item runtime link refused to overwrite active link: "
                        f"work_item={wid} existing_task={existing_task_id} requested_task={tid}"
                    )
                    await self._db.rollback()
                    return False
            if existing_owner_id and existing_owner_id != wid and not allow_replace:
                logger.warning(
                    "work-item runtime link refused to steal task from another work item: "
                    f"task={tid} existing_work_item={existing_owner_id} requested_work_item={wid}"
                )
                await self._db.rollback()
                return False
            wrote = await self._write_work_item_runtime_link(
                wid,
                tid,
                link_kind=link_kind,
                commit=False,
            )
            await self._db.commit()
            return wrote
        except Exception:
            await self._db.rollback()
            raise

    async def hydrate_task_work_item_links(self, tasks: list[Task]) -> list[Task]:
        """Attach non-persisted WorkItem link ids from the link table only."""
        if self._db is None or not tasks:
            return tasks
        task_by_id = {
            str(task.id or "").strip(): task
            for task in tasks
            if str(getattr(task, "id", "") or "").strip()
        }
        if not task_by_id:
            return tasks
        placeholders = ", ".join("?" for _ in task_by_id)
        async with self._db.execute(
            f"""SELECT work_item_id, runtime_task_id
                FROM work_item_runtime_links
                WHERE runtime_task_id IN ({placeholders})""",
            list(task_by_id),
        ) as cursor:
            rows = await cursor.fetchall()
        linked_task_ids: set[str] = set()
        for work_item_id, task_id in rows:
            tid = str(task_id or "").strip()
            wid = str(work_item_id or "").strip()
            task = task_by_id.get(tid)
            if task is None or not wid:
                continue
            set_linked_work_item_id(task, wid)
            linked_task_ids.add(tid)

        for tid, task in task_by_id.items():
            if tid not in linked_task_ids:
                set_linked_work_item_id(task, "")
        return tasks

    async def get_runtime_links_for_work_items(self, work_item_ids: list[str]) -> dict[str, str]:
        if self._db is None:
            return {}
        ids = [
            str(work_item_id or "").strip()
            for work_item_id in work_item_ids
            if str(work_item_id or "").strip()
        ]
        if not ids:
            return {}
        placeholders = ", ".join("?" for _ in ids)
        async with self._db.execute(
            f"""SELECT work_item_id, runtime_task_id
                FROM work_item_runtime_links
                WHERE work_item_id IN ({placeholders})""",
            ids,
        ) as cursor:
            rows = await cursor.fetchall()
        return {
            str(work_item_id or "").strip(): str(task_id or "").strip()
            for work_item_id, task_id in rows
            if str(work_item_id or "").strip() and str(task_id or "").strip()
        }

    async def get_runtime_task_for_work_item(self, work_item_id: str) -> Task | None:
        if self._db is None:
            return None
        wid = str(work_item_id or "").strip()
        if not wid:
            return None
        task_id = await self._runtime_link_task_id_for_work_item(wid)
        if not task_id:
            return None
        task = await self._get_task_unhydrated(task_id)
        if task is None:
            return None
        set_linked_work_item_id(task, wid)
        return task

    async def get_work_item_for_runtime_task(self, task_id: str) -> DelegationWorkItem | None:
        if self._db is None:
            return None
        tid = str(task_id or "").strip()
        if not tid:
            return None
        work_item_id = await self._runtime_link_work_item_id_for_task(tid)
        if not work_item_id:
            return None
        return await self.get_delegation_work_item(work_item_id)

    async def get_task(self, task_id: str) -> Task | None:
        assert self._db
        task = await self._get_task_unhydrated(task_id)
        if task is None:
            return None
        await self.hydrate_task_work_item_links([task])
        return task

    async def get_tasks(
        self,
        project_id: str | None = None,
        status: TaskStatus | None = None,
        parent_id: str | None = None,
    ) -> list[Task]:
        assert self._db
        query = "SELECT * FROM tasks WHERE 1=1"
        params: list[Any] = []
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        if status:
            query += " AND status = ?"
            params.append(status.value)
        if parent_id is not None:
            query += " AND parent_id = ?"
            params.append(parent_id)
        query += " ORDER BY priority ASC, created_at ASC"
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            tasks = [self._row_to_task(row, cursor.description) for row in rows]
        await self.hydrate_task_work_item_links(tasks)
        return tasks

    async def get_tasks_by_session_id(
        self,
        session_id: str,
        project_id: str | None = None,
    ) -> list[Task]:
        assert self._db
        query = "SELECT * FROM tasks WHERE session_id = ?"
        params: list[Any] = [session_id]
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        query += " ORDER BY priority ASC, created_at ASC"
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            tasks = [self._row_to_task(row, cursor.description) for row in rows]
        await self.hydrate_task_work_item_links(tasks)
        return tasks

    async def update_task_status(self, task_id: str, status: TaskStatus) -> None:
        assert self._db
        await self._db.execute("UPDATE tasks SET status = ? WHERE id = ?", (status.value, task_id))
        await self._db.commit()

    async def append_task_comment(self, task_id: str, comment: dict[str, Any]) -> None:
        task = await self.get_task(task_id)
        if not task:
            return
        task.comments = list(task.comments)
        task.comments.append(comment)
        await self.save_task(task)

    async def acquire_task_lock(self, task_id: str, *, lease_seconds: int | None = None) -> bool:
        """Atomically acquire the execution lock on a task.

        When ``lease_seconds`` is provided, a stale lock (one whose
        ``execution_locked_at`` timestamp is older than ``now - lease_seconds``)
        can be stolen. This lets a new process claim an execution slot whose
        original holder died without releasing — the common crash-recovery case.

        Always refreshes ``execution_locked_at`` to ``now()`` on successful
        acquire, so the returned lease starts fresh.
        """
        assert self._db
        now_iso = datetime.now().isoformat()
        if lease_seconds is not None and lease_seconds > 0:
            cutoff_iso = (datetime.now() - timedelta(seconds=int(lease_seconds))).isoformat()
            query = (
                "UPDATE tasks SET execution_lock = 1, execution_locked_at = ? "
                "WHERE id = ? AND ("
                "execution_lock = 0 "
                "OR execution_locked_at IS NULL "
                "OR execution_locked_at < ?"
                ")"
            )
            params: tuple[Any, ...] = (now_iso, task_id, cutoff_iso)
        else:
            query = (
                "UPDATE tasks SET execution_lock = 1, execution_locked_at = ? "
                "WHERE id = ? AND execution_lock = 0"
            )
            params = (now_iso, task_id)
        async with self._db.execute(query, params) as cursor:
            await self._db.commit()
            return cursor.rowcount > 0

    async def get_task_runtime_tool_ledger(
        self,
        task_id: str,
        *,
        project_id: str | None = None,
    ) -> TaskRuntimeToolLedgerSnapshot | None:
        """Read both authoritative exact ToolCall views in one SQLite snapshot.

        Callers must not independently inspect ``Task.context_snapshot`` or
        ``Task.metadata`` for ownership decisions.  This API applies the same
        plural/singular migration and fail-closed conflict rules as every
        transactional ledger command without treating the legacy
        ``context_snapshot.runtime_v2`` audit mirror as authority.
        """

        assert self._db
        task_id = str(task_id or "").strip()
        clean_project_id = str(project_id or "").strip()
        if not task_id:
            raise ValueError("task_id is required")
        query = "SELECT context_snapshot, metadata FROM tasks WHERE id = ?"
        params: tuple[Any, ...]
        if clean_project_id:
            query += " AND project_id = ?"
            params = (task_id, clean_project_id)
        else:
            params = (task_id,)
        async with self._db.execute(query, params) as cursor:
            row = await cursor.fetchone()
        if row is None:
            return None
        context_snapshot = _json_loads(row[0], {})
        metadata = _json_loads(row[1], {})
        (
            runtime_resume,
            runtime_metadata,
            permits,
            continuation,
            runtime_session_id,
        ) = self._canonicalize_task_runtime_tool_ledger(
            context_snapshot,
            metadata,
        )
        if not isinstance(context_snapshot.get("runtime_v2"), dict):
            context_snapshot["runtime_v2"] = {}
        self._write_canonical_task_runtime_tool_ledger(
            context_snapshot,
            metadata,
            runtime_resume=runtime_resume,
            runtime_metadata=runtime_metadata,
            permits=permits,
            continuation=continuation,
            runtime_session_id=runtime_session_id,
        )
        return TaskRuntimeToolLedgerSnapshot(
            task_id=task_id,
            runtime_session_id=runtime_session_id,
            permits=copy.deepcopy(permits),
            continue_after_tool_result=continuation,
            runtime_resume=copy.deepcopy(context_snapshot["runtime_resume"]),
            runtime_metadata=copy.deepcopy(metadata["runtime_v2"]),
            context_runtime_v2=copy.deepcopy(context_snapshot["runtime_v2"]),
        )

    async def update_task_runtime_tool_permit(
        self,
        task_id: str,
        *,
        runtime_session_id: str,
        fingerprint: str,
        permit: dict[str, Any] | None,
        expected_permit: dict[str, Any] | None = None,
        prepare_for_resume: bool = False,
    ) -> Task:
        """Atomically merge/remove one exact ToolCall permit in both task views."""

        assert self._db
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        fingerprint = str(fingerprint or "").strip()
        if not task_id or not runtime_session_id or not fingerprint:
            raise ValueError("task_id, runtime_session_id, and fingerprint are required")
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT project_id, context_snapshot, metadata FROM tasks WHERE id = ?",
                (task_id,),
            ) as cursor:
                row = await cursor.fetchone()
            if row is None:
                await self._db.rollback()
                raise ValueError(f"Unknown task `{task_id}`")
            task_project_id = str(row[0] or "default").strip() or "default"
            context_snapshot = _json_loads(row[1], {})
            metadata = _json_loads(row[2], {})
            (
                runtime_resume,
                runtime_metadata,
                approved_calls,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if (approved_calls or continuation) and (
                recorded_runtime_id != runtime_session_id
            ):
                raise RuntimeError(
                    "task runtime session conflicts with exact ToolCall permit"
                )
            if permit is None:
                existing_permit = dict(approved_calls.get(fingerprint, {}) or {})
                if not existing_permit:
                    # An already-removed permit is an exact idempotent no-op.
                    # In particular, a stale cleanup must not rewrite an
                    # inactive Task's newer runtime identity back to its old
                    # caller-supplied id.
                    await self._db.commit()
                    persisted = await self.get_task(task_id)
                    if persisted is None:
                        raise RuntimeError(
                            f"task {task_id} disappeared after permit no-op"
                        )
                    return persisted
                if existing_permit and expected_permit is None:
                    raise RuntimeError(
                        "exact ToolCall permit removal requires expected ownership"
                    )
                if existing_permit:
                    expected = json.loads(_json_dumps(dict(expected_permit or {})))
                    if existing_permit != expected:
                        raise RuntimeError(
                            "exact ToolCall permit removal ownership changed"
                        )
                    approved_calls.pop(fingerprint, None)
            else:
                normalized_permit = json.loads(_json_dumps(dict(permit)))
                if str(
                    normalized_permit.get("runtime_session_id", "") or ""
                ).strip() != runtime_session_id:
                    raise ValueError("permit runtime_session_id does not match")
                embedded_fingerprint = str(
                    normalized_permit.get("fingerprint", "") or ""
                ).strip()
                if embedded_fingerprint and embedded_fingerprint != fingerprint:
                    raise ValueError("permit fingerprint does not match")
                normalized_permit["fingerprint"] = fingerprint
                normalized_permit.setdefault("checkpoint_type", "tool_permission")
                normalized_permit.setdefault(
                    "checkpoint_project_id", task_project_id
                )
                existing_permit = dict(approved_calls.get(fingerprint, {}) or {})
                immutable_keys = (
                    "id",
                    "function",
                    "arguments",
                    "fingerprint",
                    "runtime_session_id",
                    "checkpoint_id",
                    "checkpoint_type",
                    "checkpoint_project_id",
                    "task_id",
                    "decision",
                    "approved",
                )
                if existing_permit:
                    if any(
                        existing_permit.get(key) != normalized_permit.get(key)
                        for key in immutable_keys
                    ):
                        raise RuntimeError(
                            "exact ToolCall permit immutable identity cannot change"
                        )
                    previous_state = str(
                        existing_permit.get("state", "") or ""
                    ).strip()
                    next_state = str(
                        normalized_permit.get("state", "") or ""
                    ).strip()
                    claim_changed = any(
                        str(existing_permit.get(key, "") or "").strip()
                        != str(normalized_permit.get(key, "") or "").strip()
                        for key in ("claim_id", "consumer_id")
                    )
                    if claim_changed and not (
                        previous_state == "ready" and next_state == "ready"
                    ):
                        raise RuntimeError(
                            "exact ToolCall permit claim can rotate only before effect start"
                        )
                    allowed_transitions = {
                        "ready": {"ready", "executing", "denied", "result_persisted"},
                        "executing": {"executing", "result_persisted"},
                        "denied": {"denied", "result_persisted"},
                        "result_persisted": {"result_persisted"},
                    }
                    if (
                        previous_state not in allowed_transitions
                        or next_state
                        not in allowed_transitions.get(previous_state, set())
                    ):
                        raise RuntimeError(
                            "exact ToolCall permit state cannot move backward or "
                            "replace an ambiguous state"
                        )
                permit_task_id = str(
                    normalized_permit.get("task_id", "") or ""
                ).strip()
                checkpoint_id = str(
                    normalized_permit.get("checkpoint_id", "") or ""
                ).strip()
                checkpoint_type = str(
                    normalized_permit.get("checkpoint_type", "") or ""
                ).strip()
                checkpoint_project_id = str(
                    normalized_permit.get("checkpoint_project_id", "") or ""
                ).strip()
                claim_id = str(
                    normalized_permit.get("claim_id", "") or ""
                ).strip()
                consumer_id = str(
                    normalized_permit.get("consumer_id", "") or ""
                ).strip()
                tool_call_id = str(
                    normalized_permit.get("id", "") or ""
                ).strip()
                tool_name = str(
                    normalized_permit.get("function", "") or ""
                ).strip()
                next_state = str(
                    normalized_permit.get("state", "") or ""
                ).strip()
                if (
                    permit_task_id != task_id
                    or checkpoint_type != "tool_permission"
                    or checkpoint_project_id != task_project_id
                    or not checkpoint_id
                    or not claim_id
                    or not consumer_id
                    or not tool_call_id
                    or not tool_name
                    or not isinstance(normalized_permit.get("arguments"), dict)
                    or next_state
                    not in {"ready", "executing", "denied", "result_persisted"}
                ):
                    raise RuntimeError(
                        "exact ToolCall permit has incomplete or mismatched ownership"
                    )
                checkpoint = await self._select_execution_checkpoint(
                    checkpoint_id,
                    project_id=checkpoint_project_id,
                    checkpoint_type=checkpoint_type,
                )
                if checkpoint is None or checkpoint.status != "consuming":
                    raise RuntimeError(
                        "exact ToolCall permit checkpoint is not actively consuming"
                    )
                checkpoint_payload = dict(checkpoint.payload or {})
                interaction = self._execution_checkpoint_interaction(checkpoint_payload)
                if not self._exact_tool_permit_matches_checkpoint(
                    normalized_permit,
                    checkpoint,
                    task_id=task_id,
                    project_id=task_project_id,
                    runtime_session_id=runtime_session_id,
                    fingerprint=fingerprint,
                    tool_call_id=tool_call_id,
                    tool_name=tool_name,
                    arguments=dict(normalized_permit["arguments"]),
                    execution_envelope=dict(
                        normalized_permit.get("execution_envelope", {}) or {}
                    ),
                    execution_identity=dict(
                        normalized_permit.get("execution_identity", {}) or {}
                    ),
                    claim_id=claim_id,
                    consumer_id=consumer_id,
                ):
                    raise RuntimeError(
                        "exact ToolCall permit does not match its checkpoint claim"
                    )
                execution = dict(interaction.get("execution", {}) or {})
                execution_state = str(
                    execution.get("state", "") or ""
                ).strip()
                execution_claim_matches = (
                    str(execution.get("claim_id", "") or "").strip() == claim_id
                    and str(
                        execution.get("consumer_id", "") or ""
                    ).strip()
                    == consumer_id
                )
                if next_state in {"ready", "denied"} and not (
                    execution_state == "ready" and execution_claim_matches
                ):
                    raise RuntimeError(
                        "exact ToolCall permit ready/denied state requires its "
                        "claimed pre-effect checkpoint"
                    )
                if next_state == "executing" and not (
                    execution_state == "executing" and execution_claim_matches
                ):
                    raise RuntimeError(
                        "exact ToolCall permit cannot enter executing before its effect fence"
                    )
                async with self._db.execute(
                    """SELECT 1 FROM runtime_tool_results
                       WHERE runtime_session_id = ? AND tool_call_id = ? LIMIT 1""",
                    (runtime_session_id, tool_call_id),
                ) as result_cursor:
                    result_exists = await result_cursor.fetchone() is not None
                if result_exists and not (
                    existing_permit and next_state == "result_persisted"
                ):
                    raise RuntimeError(
                        "exact ToolCall permit cannot be written after its result"
                    )
                if next_state == "result_persisted" and not result_exists:
                    raise RuntimeError(
                        "exact ToolCall permit cannot record result_persisted without a result"
                    )
                if next_state == "result_persisted" and not (
                    execution_state in {"executing", "result_persisted"}
                    and execution_claim_matches
                ):
                    raise RuntimeError(
                        "exact ToolCall result state requires its exact effect claim"
                    )
                approved_calls[fingerprint] = normalized_permit
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=approved_calls,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                """UPDATE tasks
                SET context_snapshot = ?, metadata = ?,
                    status = CASE WHEN ? THEN ? ELSE status END,
                    result = CASE WHEN ? THEN NULL ELSE result END
                WHERE id = ?""",
                (
                    _json_dumps(context_snapshot),
                    _json_dumps(metadata),
                    int(bool(prepare_for_resume)),
                    TaskStatus.PENDING.value,
                    int(bool(prepare_for_resume)),
                    task_id,
                ),
            )
            await self._db.commit()
        except Exception:
            await self._db.rollback()
            raise
        persisted = await self.get_task(task_id)
        if persisted is None:
            raise RuntimeError(f"task {task_id} disappeared after permit update")
        return persisted

    async def claim_runtime_tool_continuation(
        self,
        *,
        project_id: str,
        task_id: str,
        runtime_session_id: str,
        consumer_id: str,
        lease_seconds: float = 300.0,
    ) -> RuntimeToolContinuationClaimReceipt:
        """Register work and elect one cross-controller runtime continuation.

        Every exact permit is merged into the Task before this method is
        called.  ``request_generation`` is therefore a durable poke: a busy
        caller does not start a second runtime, while the elected runner can
        observe that more permits arrived before releasing its lease.
        """

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        if not task_id or not runtime_session_id or not consumer_id:
            raise ValueError(
                "task_id, runtime_session_id, and consumer_id are required"
            )
        self._assert_project_write_scope(
            project_id,
            operation="claim_runtime_tool_continuation",
            entity=f"task {task_id!r}",
        )
        now = datetime.now()
        expires_at = now + timedelta(seconds=max(0.1, float(lease_seconds)))
        new_claim_id = uuid.uuid4().hex
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT project_id, context_snapshot, metadata FROM tasks WHERE id = ?",
                (task_id,),
            ) as cursor:
                task_row = await cursor.fetchone()
            if task_row is None:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="not_found")
            if str(task_row[0] or "default").strip() != project_id:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            context_snapshot = _json_loads(task_row[1], {})
            metadata = _json_loads(task_row[2], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if not (permits or continuation) or (
                recorded_runtime_id != runtime_session_id
            ):
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
            )

            async with self._db.execute(
                """SELECT consumer_id, claim_id, request_generation,
                          lease_expires_at, state
                   FROM runtime_tool_continuations
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?""",
                (project_id, task_id, runtime_session_id),
            ) as cursor:
                row = await cursor.fetchone()
            if row is None:
                await self._db.execute(
                    """INSERT INTO runtime_tool_continuations
                       (project_id, task_id, runtime_session_id, consumer_id,
                        claim_id, request_generation, state, lease_expires_at,
                        created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, 1, 'ready', ?, ?, ?)""",
                    (
                        project_id,
                        task_id,
                        runtime_session_id,
                        consumer_id,
                        new_claim_id,
                        expires_at.isoformat(),
                        now.isoformat(),
                        now.isoformat(),
                    ),
                )
                await self._db.commit()
                return RuntimeToolContinuationClaimReceipt(
                    outcome="claimed",
                    claim_id=new_claim_id,
                    consumer_id=consumer_id,
                    request_generation=1,
                    lease_expires_at=expires_at.isoformat(),
                )

            current_consumer = str(row[0] or "").strip()
            current_claim_id = str(row[1] or "").strip()
            generation = int(row[2] or 0) + 1
            try:
                current_expiry = datetime.fromisoformat(str(row[3] or ""))
            except (TypeError, ValueError):
                current_expiry = datetime.min
            current_state = str(row[4] or "ready").strip() or "ready"
            if current_consumer == consumer_id and current_claim_id:
                await self._db.execute(
                    """UPDATE runtime_tool_continuations
                       SET request_generation = ?, lease_expires_at = ?, updated_at = ?
                       WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?
                         AND consumer_id = ? AND claim_id = ?""",
                    (
                        generation,
                        expires_at.isoformat(),
                        now.isoformat(),
                        project_id,
                        task_id,
                        runtime_session_id,
                        consumer_id,
                        current_claim_id,
                    ),
                )
                await self._db.commit()
                return RuntimeToolContinuationClaimReceipt(
                    outcome="duplicate",
                    claim_id=current_claim_id,
                    consumer_id=consumer_id,
                    request_generation=generation,
                    lease_expires_at=expires_at.isoformat(),
                )
            if current_expiry > now:
                await self._db.execute(
                    """UPDATE runtime_tool_continuations
                       SET request_generation = ?, updated_at = ?
                       WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?""",
                    (
                        generation,
                        now.isoformat(),
                        project_id,
                        task_id,
                        runtime_session_id,
                    ),
                )
                await self._db.commit()
                return RuntimeToolContinuationClaimReceipt(
                    outcome="busy",
                    claim_id=current_claim_id,
                    consumer_id=current_consumer,
                    request_generation=generation,
                    lease_expires_at=current_expiry.isoformat(),
                )

            if current_state == "executing":
                # Expiry alone is not evidence that the old runtime stopped.
                # Reclaim is safe only after every exact permit's checkpoint
                # has fenced that old runner out *before* its external effect.
                # An executing checkpoint remains fail-closed; its own expiry
                # reconciliation will resolve/result-or-unknown and remove the
                # permit before this scope can be claimed again.
                unsafe_effect = False
                for permit_value in permits.values():
                    permit = (
                        dict(permit_value)
                        if isinstance(permit_value, dict)
                        else {}
                    )
                    if str(
                        permit.get("runtime_session_id", "") or ""
                    ).strip() != runtime_session_id:
                        continue
                    permit_checkpoint_id = str(
                        permit.get("checkpoint_id", "") or ""
                    ).strip()
                    if not permit_checkpoint_id:
                        unsafe_effect = True
                        break
                    async with self._db.execute(
                        """SELECT status, payload FROM execution_checkpoints
                           WHERE checkpoint_id = ? AND project_id = ?""",
                        (permit_checkpoint_id, project_id),
                    ) as checkpoint_cursor:
                        permit_row = await checkpoint_cursor.fetchone()
                    if permit_row is None:
                        unsafe_effect = True
                        break
                    permit_interaction = self._execution_checkpoint_interaction(
                        _json_loads(permit_row[1], {})
                    )
                    permit_execution = dict(
                        permit_interaction.get("execution", {}) or {}
                    )
                    if str(permit_execution.get("state", "") or "") == "executing":
                        unsafe_effect = True
                        break
                if unsafe_effect:
                    await self._db.execute(
                        """UPDATE runtime_tool_continuations
                           SET request_generation = ?, updated_at = ?
                           WHERE project_id = ? AND task_id = ?
                             AND runtime_session_id = ?""",
                        (
                            generation,
                            now.isoformat(),
                            project_id,
                            task_id,
                            runtime_session_id,
                        ),
                    )
                    await self._db.commit()
                    return RuntimeToolContinuationClaimReceipt(
                        outcome="busy",
                        claim_id=current_claim_id,
                        consumer_id=current_consumer,
                        request_generation=generation,
                        lease_expires_at=current_expiry.isoformat(),
                    )

            await self._db.execute(
                """UPDATE runtime_tool_continuations
                   SET consumer_id = ?, claim_id = ?, request_generation = ?, state = 'ready',
                       lease_expires_at = ?, updated_at = ?
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?""",
                (
                    consumer_id,
                    new_claim_id,
                    generation,
                    expires_at.isoformat(),
                    now.isoformat(),
                    project_id,
                    task_id,
                    runtime_session_id,
                ),
            )
            await self._db.commit()
            return RuntimeToolContinuationClaimReceipt(
                outcome="reclaimed",
                claim_id=new_claim_id,
                consumer_id=consumer_id,
                request_generation=generation,
                lease_expires_at=expires_at.isoformat(),
            )
        except Exception:
            await self._db.rollback()
            raise

    async def set_task_runtime_continuation_marker(
        self,
        task_id: str,
        *,
        runtime_session_id: str,
        enabled: bool,
    ) -> Task:
        """Atomically mark a restart that continues after a durable ToolResult."""

        assert self._db
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        if not task_id or not runtime_session_id:
            raise ValueError("task_id and runtime_session_id are required")
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT context_snapshot, metadata FROM tasks WHERE id = ?",
                (task_id,),
            ) as cursor:
                row = await cursor.fetchone()
            if row is None:
                raise ValueError(f"Unknown task `{task_id}`")
            context_snapshot = _json_loads(row[0], {})
            metadata = _json_loads(row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if not enabled and not continuation:
                await self._db.commit()
                persisted = await self.get_task(task_id)
                if persisted is None:
                    raise RuntimeError(
                        f"task {task_id} disappeared after marker no-op"
                    )
                return persisted
            if recorded_runtime_id and recorded_runtime_id != runtime_session_id:
                raise RuntimeError("task runtime session conflicts with continuation")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=bool(enabled),
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
            )
            await self._db.commit()
        except Exception:
            await self._db.rollback()
            raise
        persisted = await self.get_task(task_id)
        if persisted is None:
            raise RuntimeError(f"task {task_id} disappeared after marker update")
        return persisted

    async def renew_runtime_tool_continuation(
        self,
        *,
        project_id: str,
        task_id: str,
        runtime_session_id: str,
        consumer_id: str,
        claim_id: str,
        lease_seconds: float = 300.0,
    ) -> RuntimeToolContinuationClaimReceipt:
        """Renew a continuation lease without registering another request."""

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        claim_id = str(claim_id or "").strip()
        now = datetime.now()
        expires_at = now + timedelta(seconds=max(0.1, float(lease_seconds)))
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT context_snapshot, metadata FROM tasks WHERE id = ? AND project_id = ?",
                (task_id, project_id),
            ) as task_cursor:
                task_row = await task_cursor.fetchone()
            if task_row is None:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            context_snapshot = _json_loads(task_row[0], {})
            metadata = _json_loads(task_row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if recorded_runtime_id != runtime_session_id:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
            )
            cursor = await self._db.execute(
                """UPDATE runtime_tool_continuations
                   SET lease_expires_at = ?, updated_at = ?
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?
                     AND consumer_id = ? AND claim_id = ?""",
                (
                    expires_at.isoformat(),
                    now.isoformat(),
                    project_id,
                    task_id,
                    runtime_session_id,
                    consumer_id,
                    claim_id,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            async with self._db.execute(
                """SELECT request_generation FROM runtime_tool_continuations
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?""",
                (project_id, task_id, runtime_session_id),
            ) as read_cursor:
                row = await read_cursor.fetchone()
            await self._db.commit()
            return RuntimeToolContinuationClaimReceipt(
                outcome="renewed",
                claim_id=claim_id,
                consumer_id=consumer_id,
                request_generation=int(row[0] or 0) if row else 0,
                lease_expires_at=expires_at.isoformat(),
            )
        except Exception:
            await self._db.rollback()
            raise

    async def begin_runtime_tool_continuation(
        self,
        *,
        project_id: str,
        task_id: str,
        runtime_session_id: str,
        consumer_id: str,
        claim_id: str,
    ) -> RuntimeToolContinuationClaimReceipt:
        """Fence the unique runtime runner before it writes transcript/effects."""

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        claim_id = str(claim_id or "").strip()
        now = datetime.now().isoformat()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT context_snapshot, metadata FROM tasks WHERE id = ? AND project_id = ?",
                (task_id, project_id),
            ) as task_cursor:
                task_row = await task_cursor.fetchone()
            if task_row is None:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            context_snapshot = _json_loads(task_row[0], {})
            metadata = _json_loads(task_row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if not (permits or continuation) or (
                recorded_runtime_id != runtime_session_id
            ):
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
            )
            cursor = await self._db.execute(
                """UPDATE runtime_tool_continuations
                   SET state = 'executing', updated_at = ?
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?
                     AND consumer_id = ? AND claim_id = ? AND state = 'ready'""",
                (
                    now,
                    project_id,
                    task_id,
                    runtime_session_id,
                    consumer_id,
                    claim_id,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return RuntimeToolContinuationClaimReceipt(outcome="conflict")
            async with self._db.execute(
                """SELECT request_generation, lease_expires_at
                   FROM runtime_tool_continuations
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?""",
                (project_id, task_id, runtime_session_id),
            ) as read_cursor:
                row = await read_cursor.fetchone()
            await self._db.commit()
            return RuntimeToolContinuationClaimReceipt(
                outcome="claimed",
                claim_id=claim_id,
                consumer_id=consumer_id,
                request_generation=int(row[0] or 0) if row else 0,
                lease_expires_at=str(row[1] or "") if row else "",
            )
        except Exception:
            await self._db.rollback()
            raise

    async def finish_runtime_tool_continuation(
        self,
        *,
        project_id: str,
        task_id: str,
        runtime_session_id: str,
        consumer_id: str,
        claim_id: str,
    ) -> RuntimeToolContinuationFinishReceipt:
        """Release the runner iff its durable permit queue is drained."""

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        claim_id = str(claim_id or "").strip()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                """SELECT request_generation FROM runtime_tool_continuations
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?
                     AND consumer_id = ? AND claim_id = ?""",
                (
                    project_id,
                    task_id,
                    runtime_session_id,
                    consumer_id,
                    claim_id,
                ),
            ) as cursor:
                row = await cursor.fetchone()
            if row is None:
                await self._db.rollback()
                return RuntimeToolContinuationFinishReceipt(outcome="conflict")
            generation = int(row[0] or 0)
            async with self._db.execute(
                "SELECT context_snapshot, metadata FROM tasks WHERE id = ? AND project_id = ?",
                (task_id, project_id),
            ) as cursor:
                task_row = await cursor.fetchone()
            if task_row is None:
                await self._db.rollback()
                return RuntimeToolContinuationFinishReceipt(outcome="not_found")
            context_snapshot = _json_loads(task_row[0], {})
            metadata = _json_loads(task_row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
            )
            if recorded_runtime_id != runtime_session_id:
                await self._db.rollback()
                return RuntimeToolContinuationFinishReceipt(outcome="conflict")
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
            )
            # Every retained permit is live ownership.  Unknown/legacy states
            # must fail closed rather than letting the singleflight runner exit
            # while an exact call is still durable.
            has_work = continuation or bool(permits)
            if has_work:
                await self._db.commit()
                return RuntimeToolContinuationFinishReceipt(
                    outcome="more_work",
                    request_generation=generation,
                )
            cursor = await self._db.execute(
                """DELETE FROM runtime_tool_continuations
                   WHERE project_id = ? AND task_id = ? AND runtime_session_id = ?
                     AND consumer_id = ? AND claim_id = ?""",
                (
                    project_id,
                    task_id,
                    runtime_session_id,
                    consumer_id,
                    claim_id,
                ),
            )
            await self._db.commit()
            return RuntimeToolContinuationFinishReceipt(
                outcome="finished" if cursor.rowcount == 1 else "conflict",
                request_generation=generation,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def release_task_lock(self, task_id: str) -> None:
        assert self._db
        await self._db.execute(
            "UPDATE tasks SET execution_lock = 0, execution_locked_at = NULL WHERE id = ?",
            (task_id,),
        )
        await self._db.commit()

