    async def update_handoff_record(
        self,
        handoff_id: str,
        *,
        status: str | None = None,
        received_at: datetime | None = None,
        acked_at: datetime | None = None,
        accepted_at: datetime | None = None,
        rejected_at: datetime | None = None,
        response_summary: str | None = None,
        ack_message_id: str | None = None,
        response_message_id: str | None = None,
        metadata_updates: dict[str, Any] | None = None,
    ) -> HandoffRecord | None:
        record = await self.get_handoff_record(handoff_id)
        if record is None:
            return None
        if status is not None:
            record.status = str(status).strip() or record.status
        if received_at is not None:
            record.received_at = received_at
        if acked_at is not None:
            record.acked_at = acked_at
        if accepted_at is not None:
            record.accepted_at = accepted_at
        if rejected_at is not None:
            record.rejected_at = rejected_at
        if response_summary is not None:
            record.response_summary = str(response_summary)
        if ack_message_id is not None:
            record.ack_message_id = ack_message_id
        if response_message_id is not None:
            record.response_message_id = response_message_id
        if metadata_updates:
            record.metadata = {**dict(record.metadata or {}), **dict(metadata_updates)}
        await self.save_handoff_record(record)
        return record

    def _row_to_role_runtime_session(self, row: Any, description: Any) -> RoleRuntimeSession:
        cols = [d[0] for d in description]
        data = dict(zip(cols, row))
        focused_work_item_id = data.get("focused_work_item_id") or ""
        status = normalize_role_runtime_status(data.get("status"), focused_work_item_id)
        if status == "idle":
            focused_work_item_id = ""
        return RoleRuntimeSession(
            role_session_id=data["role_session_id"],
            run_id=data["run_id"],
            project_id=data.get("project_id") or "default",
            team_instance_id=data.get("team_instance_id") or "",
            team_id=data.get("team_id") or "",
            role_id=data.get("role_id") or "",
            seat_id=data.get("seat_id") or "",
            seat_state_id=data.get("seat_state_id") or "",
            employee_id=data.get("employee_id") or "",
            focused_work_item_id=focused_work_item_id,
            background_work_item_ids=_json_loads(data.get("background_work_item_ids"), []),
            manager_role_ids=_json_loads(data.get("manager_role_ids"), []),
            manager_seat_ids=_json_loads(data.get("manager_seat_ids"), []),
            seat_ids=_json_loads(data.get("seat_ids"), []),
            adapter_session_state=_json_loads(data.get("adapter_session_state"), {}),
            inbox_state=_json_loads(data.get("inbox_state"), {}),
            memory_slices_by_work_item=_json_loads(data.get("memory_slices_by_work_item"), {}),
            resume_state=_json_loads(data.get("resume_state"), {}),
            current_work_item=_json_loads(data.get("current_work_item"), {}),
            latest_notification=_json_loads(data.get("latest_notification"), {}),
            manager_digest=_json_loads(data.get("manager_digest"), {}),
            status=status,
            pending_work_item_ids=_json_loads(data.get("pending_work_item_ids"), []),
            metadata=_json_loads(data.get("metadata"), {}),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
        )

    @staticmethod
    def _company_controller_credential_from_metadata(
        metadata: dict[str, Any] | None,
        *,
        owner_token: str = "",
        generation: int = 0,
    ) -> tuple[str, int]:
        payload = dict(metadata or {})
        nested = payload.get("metadata")
        nested_payload = dict(nested) if isinstance(nested, dict) else {}
        token = str(
            owner_token
            or payload.get("company_run_controller_owner_token")
            or nested_payload.get("company_run_controller_owner_token")
            or ""
        ).strip()
        raw_generation = (
            generation
            or payload.get("company_run_controller_lease_generation")
            or nested_payload.get("company_run_controller_lease_generation")
            or 0
        )
        try:
            normalized_generation = int(raw_generation or 0)
        except (TypeError, ValueError):
            normalized_generation = 0
        return token, normalized_generation

    async def _require_company_controller_record_write(
        self,
        db: _SQLiteConnectionAdapter,
        *,
        run_id: str,
        project_id: str,
        owner_token: str,
        generation: int,
        checked_at: datetime,
        reject_dispatch_hold: bool = True,
        work_item_id: str = "",
        task_id: str = "",
        role_runtime_session_id: str = "",
        seat_state_id: str = "",
        seat_id: str = "",
    ) -> None:
        """Fence one company-runtime projection inside its write transaction.

        Runs which have never entered the controller protocol (generation 0)
        retain compatibility with bootstrap/migration fixtures.  Once a run
        has a controller generation, every live projection write must present
        that exact, unexpired owner credential -- an omitted token is never a
        production bypass.
        """

        clean_run_id = str(run_id or "").strip()
        if not clean_run_id:
            return
        async with db.execute(
            """SELECT project_id, controller_owner_token,
                      controller_lease_generation, controller_lease_expires_at
               FROM delegation_runs
               WHERE run_id = ?""",
            (clean_run_id,),
        ) as cursor:
            row = await cursor.fetchone()
        if row is None:
            return
        (
            persisted_project_id,
            persisted_owner_token,
            persisted_generation,
            persisted_expires_at,
        ) = row
        persisted_generation = int(persisted_generation or 0)
        if persisted_generation <= 0:
            return
        if (
            str(persisted_project_id or "default").strip()
            != (str(project_id or "default").strip() or "default")
            or not str(owner_token or "").strip()
            or str(persisted_owner_token or "").strip()
            != str(owner_token or "").strip()
            or persisted_generation != int(generation or 0)
            or not str(persisted_expires_at or "").strip()
            or str(persisted_expires_at) <= checked_at.isoformat()
        ):
            raise CompanyRunControllerLeaseLost(
                "stale company controller cannot persist runtime session state "
                f"(run_id={clean_run_id}, generation={int(generation or 0)})"
            )
        if reject_dispatch_hold:
            clean_work_item_id = str(work_item_id or "").strip()
            clean_task_id = str(task_id or "").strip()
            clean_role_session_id = str(
                role_runtime_session_id or ""
            ).strip()
            clean_seat_state_id = str(seat_state_id or "").strip()
            clean_seat_id = str(seat_id or "").strip()
            hold_scope = "1 = 1"
            hold_params: list[Any] = [clean_run_id]
            if clean_work_item_id:
                hold_scope = "work_item.work_item_id = ?"
                hold_params.append(clean_work_item_id)
            elif clean_task_id:
                hold_scope = """EXISTS (
                    SELECT 1 FROM work_item_runtime_links AS link
                    WHERE link.work_item_id = work_item.work_item_id
                      AND (
                          link.runtime_task_id = ?
                          OR substr(
                               ?,
                               1,
                               length(link.runtime_task_id) + 2
                             ) = link.runtime_task_id || '::'
                      )
                )"""
                hold_params.extend([clean_task_id, clean_task_id])
            elif clean_role_session_id:
                hold_scope = """(
                    work_item.role_runtime_session_id = ?
                    OR work_item.claimed_by_role_runtime_session_id = ?
                    OR COALESCE(
                         json_extract(
                           work_item.metadata,
                           '$.claimed_by_role_session_id'
                         ), ''
                       ) = ?
                )"""
                hold_params.extend([clean_role_session_id] * 3)
            elif clean_seat_state_id or clean_seat_id:
                seat_predicates: list[str] = []
                if clean_seat_state_id:
                    seat_predicates.append("work_item.seat_state_id = ?")
                    hold_params.append(clean_seat_state_id)
                if clean_seat_id:
                    seat_predicates.extend(
                        [
                            "work_item.seat_id = ?",
                            "work_item.claimed_by_seat_id = ?",
                        ]
                    )
                    hold_params.extend([clean_seat_id, clean_seat_id])
                hold_scope = f"({' OR '.join(seat_predicates)})"
            async with db.execute(
                f"""SELECT 1
                    FROM delegation_work_items AS work_item
                    WHERE work_item.run_id = ?
                      AND COALESCE(
                            json_extract(
                              work_item.metadata,
                              '$.dispatch_hold'
                            ), ''
                          ) != ''
                      AND {hold_scope}
                    LIMIT 1""",
                hold_params,
            ) as cursor:
                held = await cursor.fetchone()
            if held is not None:
                raise CompanyRunControllerLeaseLost(
                    "suspended company runtime rejects role/session tail writes "
                    f"(run_id={clean_run_id}, generation={int(generation or 0)})"
                )

    async def _save_role_runtime_session_row(
        self,
        session: RoleRuntimeSession,
        *,
        table: str,
        db: _SQLiteConnectionAdapter,
    ) -> None:
        session.focused_work_item_id = str(session.focused_work_item_id or "").strip()
        session.status = normalize_role_runtime_status(
            session.status,
            session.focused_work_item_id,
        )
        if session.status == "idle":
            session.focused_work_item_id = ""
        await db.execute(
            f"""INSERT OR REPLACE INTO {table}
            (role_session_id, run_id, project_id, team_instance_id, team_id, role_id, seat_id, seat_state_id,
             employee_id, focused_work_item_id, background_work_item_ids, manager_role_ids, manager_seat_ids,
             seat_ids, adapter_session_state, inbox_state, memory_slices_by_work_item, resume_state,
             current_work_item, latest_notification, manager_digest, status, pending_work_item_ids,
             metadata, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                session.role_session_id,
                session.run_id,
                session.project_id,
                session.team_instance_id,
                session.team_id,
                session.role_id,
                session.seat_id,
                session.seat_state_id,
                session.employee_id,
                session.focused_work_item_id,
                _json_dumps(session.background_work_item_ids),
                _json_dumps(session.manager_role_ids),
                _json_dumps(session.manager_seat_ids),
                _json_dumps(session.seat_ids),
                _json_dumps(session.adapter_session_state),
                _json_dumps(session.inbox_state),
                _json_dumps(session.memory_slices_by_work_item),
                _json_dumps(session.resume_state),
                _json_dumps(session.current_work_item),
                _json_dumps(session.latest_notification),
                _json_dumps(session.manager_digest),
                session.status,
                _json_dumps(list(getattr(session, "pending_work_item_ids", []) or [])),
                _json_dumps(session.metadata),
                session.created_at.isoformat(),
                session.updated_at.isoformat(),
            ),
        )

    async def save_role_runtime_session(
        self,
        session: RoleRuntimeSession,
        *,
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> None:
        # The credential must come from the caller's controller admission,
        # never from the row being written.  A stale process is allowed to
        # read the winner's projection metadata, so treating that metadata as
        # authority would let a read-after-takeover tail impersonate the new
        # generation.
        token = str(controller_owner_token or "").strip()
        generation = int(controller_lease_generation or 0)
        if token:
            session.metadata = {
                **dict(session.metadata or {}),
                "company_run_controller_owner_token": token,
                "company_run_controller_lease_generation": generation,
            }
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            async with transaction_db.execute(
                """SELECT run_id, project_id
                   FROM role_runtime_sessions
                   WHERE role_session_id = ?""",
                (str(session.role_session_id or "").strip(),),
            ) as cursor:
                existing_scope = await cursor.fetchone()
            scope_run_id = str(session.run_id or "").strip()
            scope_project_id = str(session.project_id or "default").strip() or "default"
            if existing_scope is not None:
                existing_run_id = str(existing_scope[0] or "").strip()
                existing_project_id = (
                    str(existing_scope[1] or "default").strip() or "default"
                )
                if (
                    scope_run_id != existing_run_id
                    or (
                        scope_project_id != existing_project_id
                        and existing_project_id != "default"
                    )
                ):
                    raise CompanyRunControllerLeaseLost(
                        "company role-session identity cannot move between scopes"
                    )
                scope_run_id = existing_run_id
                if existing_project_id != "default":
                    scope_project_id = existing_project_id
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=scope_run_id,
                project_id=scope_project_id,
                owner_token=token,
                generation=generation,
                checked_at=datetime.now(),
                role_runtime_session_id=str(
                    session.role_session_id or ""
                ).strip(),
            )
            await self._save_role_runtime_session_row(
                session,
                table="role_runtime_sessions",
                db=transaction_db,
            )
            await self._save_role_runtime_session_row(
                session,
                table="delegation_role_sessions",
                db=transaction_db,
            )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_delegation_role_session(
        self,
        session: RoleRuntimeSession,
        *,
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> None:
        await self.save_role_runtime_session(
            session,
            controller_owner_token=controller_owner_token,
            controller_lease_generation=controller_lease_generation,
        )

    async def get_role_runtime_session(self, role_session_id: str) -> RoleRuntimeSession | None:
        db = self._require_db()
        for table in ("role_runtime_sessions", "delegation_role_sessions"):
            async with db.execute(
                f"SELECT * FROM {table} WHERE role_session_id = ?",
                (role_session_id,),
            ) as cursor:
                row = await cursor.fetchone()
                if row is not None:
                    return self._row_to_role_runtime_session(row, cursor.description)
        return None

    async def get_delegation_role_session(self, role_session_id: str) -> RoleRuntimeSession | None:
        return await self.get_role_runtime_session(role_session_id)

    async def get_delegation_role_session_for_role(
        self,
        run_id: str,
        role_id: str,
        *,
        team_id: str | None = None,
        seat_id: str | None = None,
    ) -> RoleRuntimeSession | None:
        db = self._require_db()
        query = "SELECT * FROM delegation_role_sessions WHERE run_id = ? AND role_id = ?"
        params: list[Any] = [run_id, role_id]
        if team_id:
            query += " AND team_id = ?"
            params.append(team_id)
        if seat_id:
            query += " AND seat_id = ?"
            params.append(seat_id)
        query += " ORDER BY created_at ASC LIMIT 1"
        async with db.execute(query, params) as cursor:
            row = await cursor.fetchone()
            if row is not None:
                return self._row_to_role_runtime_session(row, cursor.description)
        return None

    async def get_role_runtime_session_for_role(
        self,
        run_id: str,
        role_id: str,
        *,
        team_id: str | None = None,
        seat_id: str | None = None,
    ) -> RoleRuntimeSession | None:
        return await self.get_delegation_role_session_for_role(
            run_id,
            role_id,
            team_id=team_id,
            seat_id=seat_id,
        )

    async def list_role_runtime_sessions(
        self,
        run_id: str,
        *,
        team_id: str | None = None,
        seat_id: str | None = None,
        role_id: str | None = None,
        status: str | None = None,
    ) -> list[RoleRuntimeSession]:
        db = self._require_db()
        query = "SELECT * FROM role_runtime_sessions WHERE run_id = ?"
        params: list[Any] = [run_id]
        if team_id:
            query += " AND team_id = ?"
            params.append(team_id)
        if seat_id:
            query += " AND seat_id = ?"
            params.append(seat_id)
        if role_id:
            query += " AND role_id = ?"
            params.append(role_id)
        if status:
            query += " AND status = ?"
            params.append(status)
        query += " ORDER BY created_at ASC"
        async with db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_role_runtime_session(row, cursor.description) for row in rows]

