    async def update_seat_state(
        self,
        seat_state_id: str,
        *,
        status: str | None = None,
        resident_status: str | None = None,
        current_task_id: str | None = None,
        current_work_item_id: str | None = None,
        role_runtime_session_id: str | None = None,
        inbox_state: dict[str, Any] | None = None,
        resume_state: dict[str, Any] | None = None,
        current_work_item: dict[str, Any] | None = None,
        latest_notification: dict[str, Any] | None = None,
        manager_digest: dict[str, Any] | None = None,
        metadata_updates: dict[str, Any] | None = None,
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> SeatState | None:
        seat = await self.get_seat_state(seat_state_id)
        if seat is None:
            return None
        if status is not None:
            seat.status = normalize_role_runtime_status(
                status,
                seat.current_work_item_id,
            )
        if resident_status is not None:
            seat.resident_status = normalize_role_runtime_status(
                resident_status,
                seat.current_work_item_id,
            )
        if current_task_id is not None:
            seat.current_task_id = str(current_task_id or "").strip()
        if current_work_item_id is not None:
            seat.current_work_item_id = str(current_work_item_id or "").strip()
        seat.status = normalize_role_runtime_status(
            seat.status,
            seat.current_work_item_id,
        )
        if seat.status == "idle":
            seat.current_work_item_id = ""
        seat.resident_status = seat.status
        if role_runtime_session_id is not None:
            seat.role_runtime_session_id = str(role_runtime_session_id or "").strip()
        if inbox_state is not None:
            seat.inbox_state = dict(inbox_state)
        if resume_state is not None:
            seat.resume_state = dict(resume_state)
        if current_work_item is not None:
            seat.current_work_item = dict(current_work_item)
        if latest_notification is not None:
            seat.latest_notification = dict(latest_notification)
        if manager_digest is not None:
            seat.manager_digest = dict(manager_digest)
        if metadata_updates:
            seat.metadata = {**dict(seat.metadata or {}), **dict(metadata_updates)}
        seat.updated_at = datetime.now()
        await self.save_seat_state(
            seat,
            controller_owner_token=controller_owner_token,
            controller_lease_generation=controller_lease_generation,
        )
        return seat

    async def save_delegation_seat_state(
        self,
        seat: SeatState,
        *,
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> None:
        await self.save_seat_state(
            seat,
            controller_owner_token=controller_owner_token,
            controller_lease_generation=controller_lease_generation,
        )

    async def get_delegation_seat_state(self, seat_state_id: str) -> SeatState | None:
        return await self.get_seat_state(seat_state_id)

    async def list_delegation_seat_states(
        self,
        run_id: str,
        *,
        team_id: str | None = None,
        seat_id: str | None = None,
    ) -> list[SeatState]:
        return await self.list_seat_states(
            run_id=run_id,
            team_id=team_id,
            seat_id=seat_id,
        )

    async def update_delegation_seat_state(
        self,
        seat_state_id: str,
        **kwargs: Any,
    ) -> SeatState | None:
        return await self.update_seat_state(seat_state_id, **kwargs)

    def _row_to_delegation_run(self, row: Any, description: Any) -> DelegationRun:
        cols = [d[0] for d in description]
        data = dict(zip(cols, row))

        def _optional_datetime(value: Any) -> datetime | None:
            raw = str(value or "").strip()
            if not raw:
                return None
            try:
                return datetime.fromisoformat(raw)
            except ValueError:
                return None

        return DelegationRun(
            run_id=data["run_id"],
            project_id=data["project_id"],
            session_id=data["session_id"],
            company_profile=data.get("company_profile") or "corporate",
            execution_model=data.get("execution_model") or "recursive_delegation",
            final_decider_role_id=data.get("final_decider_role_id") or "",
            top_level_role_ids=_json_loads(data.get("top_level_role_ids"), []),
            status=data.get("status") or "pending",
            lifecycle_status=data.get("lifecycle_status") or "active",
            current_revision=int(data.get("current_revision") or 1),
            latest_deliverable_summary=data.get("latest_deliverable_summary") or "",
            recovery_pointer=_json_loads(data.get("recovery_pointer"), {}),
            project_dossier=_json_loads(data.get("project_dossier"), {}),
            metadata=_json_loads(data.get("metadata"), {}),
            controller_owner_token=data.get("controller_owner_token") or "",
            controller_lease_generation=int(
                data.get("controller_lease_generation") or 0
            ),
            controller_lease_acquired_at=_optional_datetime(
                data.get("controller_lease_acquired_at")
            ),
            controller_lease_heartbeat_at=_optional_datetime(
                data.get("controller_lease_heartbeat_at")
            ),
            controller_lease_expires_at=_optional_datetime(
                data.get("controller_lease_expires_at")
            ),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
        )

    async def save_delegation_run(self, run: DelegationRun) -> None:
        db = self._require_db()
        await db.execute(
            """INSERT INTO delegation_runs
            (run_id, project_id, session_id, company_profile, execution_model, final_decider_role_id,
             top_level_role_ids, status, lifecycle_status, current_revision, latest_deliverable_summary,
             recovery_pointer, project_dossier, metadata, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(run_id) DO UPDATE SET
                project_id=excluded.project_id,
                session_id=excluded.session_id,
                company_profile=excluded.company_profile,
                execution_model=excluded.execution_model,
                final_decider_role_id=excluded.final_decider_role_id,
                top_level_role_ids=excluded.top_level_role_ids,
                status=excluded.status,
                lifecycle_status=excluded.lifecycle_status,
                current_revision=excluded.current_revision,
                latest_deliverable_summary=excluded.latest_deliverable_summary,
                recovery_pointer=excluded.recovery_pointer,
                project_dossier=excluded.project_dossier,
                metadata=excluded.metadata,
                created_at=excluded.created_at,
                updated_at=excluded.updated_at""",
            (
                run.run_id,
                run.project_id,
                run.session_id,
                run.company_profile,
                run.execution_model,
                run.final_decider_role_id,
                _json_dumps(run.top_level_role_ids),
                run.status,
                run.lifecycle_status,
                int(run.current_revision or 1),
                run.latest_deliverable_summary,
                _json_dumps(run.recovery_pointer),
                _json_dumps(run.project_dossier),
                _json_dumps(run.metadata),
                run.created_at.isoformat(),
                run.updated_at.isoformat(),
            ),
        )
        await db.commit()

    async def get_delegation_run(self, run_id: str) -> DelegationRun | None:
        db = self._require_db()
        async with db.execute(
            "SELECT * FROM delegation_runs WHERE run_id = ?",
            (run_id,),
        ) as cursor:
            row = await cursor.fetchone()
            if row is None:
                return None
            return self._row_to_delegation_run(row, cursor.description)

    async def transition_delegation_run_lifecycle_for_controller(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        mutation: CompanyControllerRunLifecycleMutation,
        operation: str = "run_lifecycle_transition",
    ) -> CompanyControllerRunLifecycleResult:
        """CAS a run lifecycle while the exact durable controller is live.

        This is the run-level counterpart to an attempt command.  It is used
        only after whole-tree convergence, where no individual WorkItem
        attempt remains the semantic owner.  Runtime suspension holds reject
        the write so a same-generation coroutine cannot close a run after its
        shutdown handoff committed.
        """

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
        ):
            raise CompanyRunControllerLeaseLost(
                f"{operation} lacks an exact controller lease"
            )
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            result = await self._mutate_delegation_run_lifecycle_for_controller(
                transaction_db,
                run_id=clean_run_id,
                project_id=clean_project_id,
                root_session_id=clean_root_session_id,
                owner_token=clean_owner_token,
                generation=clean_generation,
                mutation=mutation,
                checked_at=datetime.now(),
            )
            if result.applied:
                await transaction_db.commit()
            else:
                await transaction_db.rollback()
            return result
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def acquire_delegation_run_controller_lease(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        lease_seconds: float,
        acquired_at: datetime | None = None,
    ) -> DelegationRunControllerLeaseReceipt:
        """Atomically acquire one run's durable controller lease.

        ``delegation_runs`` already owns the project/run/root identity, so the
        lease is stored on that row instead of introducing a parallel lock
        registry.  A new owner may replace an existing one only after its
        durable expiry.  The monotonically increasing generation is the fence
        used by claims and effects after a takeover.
        """

        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        if not clean_run_id or not clean_root_session_id or not clean_owner_token:
            raise ValueError("run_id, root_session_id, and owner_token are required")
        duration = max(1.0, float(lease_seconds))
        now = acquired_at or datetime.now()
        expires_at = now + timedelta(seconds=duration)
        db = self._require_db()
        cursor = await db.execute(
            """UPDATE delegation_runs
               SET controller_owner_token = ?,
                   controller_lease_generation = CASE
                       WHEN COALESCE(controller_owner_token, '') = ?
                           THEN COALESCE(controller_lease_generation, 0)
                       ELSE COALESCE(controller_lease_generation, 0) + 1
                   END,
                   controller_lease_acquired_at = CASE
                       WHEN COALESCE(controller_owner_token, '') = ?
                           THEN COALESCE(controller_lease_acquired_at, ?)
                       ELSE ?
                   END,
                   controller_lease_heartbeat_at = ?,
                   controller_lease_expires_at = ?
               WHERE run_id = ?
                 AND project_id = ?
                 AND session_id = ?
                 AND (
                     COALESCE(controller_owner_token, '') = ''
                     OR controller_owner_token = ?
                     OR COALESCE(controller_lease_expires_at, '') = ''
                     OR controller_lease_expires_at <= ?
                 )""",
            (
                clean_owner_token,
                clean_owner_token,
                clean_owner_token,
                now.isoformat(),
                now.isoformat(),
                now.isoformat(),
                expires_at.isoformat(),
                clean_run_id,
                clean_project_id,
                clean_root_session_id,
                clean_owner_token,
                now.isoformat(),
            ),
        )
        await db.commit()
        persisted = await self.get_delegation_run(clean_run_id)
        if not (getattr(cursor, "rowcount", 0) or 0):
            return DelegationRunControllerLeaseReceipt(
                outcome="busy" if persisted is not None else "missing",
                run_id=clean_run_id,
                project_id=clean_project_id,
                root_session_id=clean_root_session_id,
                owner_token=str(
                    getattr(persisted, "controller_owner_token", "") or ""
                ),
                generation=int(
                    getattr(persisted, "controller_lease_generation", 0) or 0
                ),
                expires_at=getattr(persisted, "controller_lease_expires_at", None),
            )
        return DelegationRunControllerLeaseReceipt(
            outcome="acquired",
            run_id=clean_run_id,
            project_id=clean_project_id,
            root_session_id=clean_root_session_id,
            owner_token=clean_owner_token,
            generation=int(
                getattr(persisted, "controller_lease_generation", 0) or 0
            ),
            expires_at=getattr(persisted, "controller_lease_expires_at", None),
        )

    async def renew_delegation_run_controller_lease(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        lease_seconds: float,
        heartbeat_at: datetime | None = None,
    ) -> bool:
        """Renew only an unexpired lease owned by this exact generation."""

        now = heartbeat_at or datetime.now()
        expires_at = now + timedelta(seconds=max(1.0, float(lease_seconds)))
        db = self._require_db()
        cursor = await db.execute(
            """UPDATE delegation_runs
               SET controller_lease_heartbeat_at = ?,
                   controller_lease_expires_at = ?
               WHERE run_id = ?
                 AND project_id = ?
                 AND session_id = ?
                 AND controller_owner_token = ?
                 AND controller_lease_generation = ?
                 AND controller_lease_expires_at > ?""",
            (
                now.isoformat(),
                expires_at.isoformat(),
                str(run_id or "").strip(),
                str(project_id or "default").strip() or "default",
                str(root_session_id or "").strip(),
                str(owner_token or "").strip(),
                int(generation),
                now.isoformat(),
            ),
        )
        await db.commit()
        return bool(getattr(cursor, "rowcount", 0) or 0)

    def renew_delegation_run_controller_lease_sync(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        lease_seconds: float,
        heartbeat_at: datetime | None = None,
    ) -> bool:
        """Thread-safe heartbeat path for event-loop blocking sections.

        It uses a dedicated SQLite connection, never the Store connection that
        belongs to the asyncio controller.  Thus a synchronous provider/tool
        call cannot accidentally let a healthy process's lease expire.
        """

        now = heartbeat_at or datetime.now()
        expires_at = now + timedelta(seconds=max(1.0, float(lease_seconds)))
        connection = sqlite3.connect(self.db_path, timeout=30.0)
        try:
            connection.execute("PRAGMA busy_timeout=30000")
            cursor = connection.execute(
                """UPDATE delegation_runs
                   SET controller_lease_heartbeat_at = ?,
                       controller_lease_expires_at = ?
                   WHERE run_id = ?
                     AND project_id = ?
                     AND session_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    now.isoformat(),
                    expires_at.isoformat(),
                    str(run_id or "").strip(),
                    str(project_id or "default").strip() or "default",
                    str(root_session_id or "").strip(),
                    str(owner_token or "").strip(),
                    int(generation),
                    now.isoformat(),
                ),
            )
            connection.commit()
            return bool(cursor.rowcount or 0)
        finally:
            connection.close()

    async def delegation_run_controller_lease_is_current(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str | None = None,
        owner_token: str | None = None,
        generation: int | None = None,
        checked_at: datetime | None = None,
    ) -> bool:
        """Return whether the requested run has the specified live lease."""

        now = checked_at or datetime.now()
        query = (
            "SELECT 1 FROM delegation_runs "
            "WHERE run_id = ? AND project_id = ? "
            "AND COALESCE(controller_owner_token, '') != '' "
            "AND controller_lease_expires_at > ?"
        )
        params: list[Any] = [
            str(run_id or "").strip(),
            str(project_id or "default").strip() or "default",
            now.isoformat(),
        ]
        if root_session_id is not None:
            query += " AND session_id = ?"
            params.append(str(root_session_id or "").strip())
        if owner_token is not None:
            query += " AND controller_owner_token = ?"
            params.append(str(owner_token or "").strip())
        if generation is not None:
            query += " AND controller_lease_generation = ?"
            params.append(int(generation))
        db = self._require_db()
        async with db.execute(query, params) as cursor:
            return await cursor.fetchone() is not None

    @staticmethod
    def _canonical_company_artifact_path(
        task_metadata: dict[str, Any],
        run_metadata: dict[str, Any],
        raw_path: str,
        *,
        actual_workspace_root: str = "",
        actual_output_root: str = "",
    ) -> tuple[str, str]:
        """Resolve a tool path from Store-owned workspace capabilities.

        The in-memory Task and ToolCall are intentionally not authoritative
        for roots.  Relative paths use the same durable output-root fallback
        as native file tools, while every result remains underneath the
        durable workspace root.
        """

        metadata = dict(task_metadata or {})
        durable_run_metadata = dict(run_metadata or {})
        task_workspace_value = str(
            metadata.get("workspace_root", "")
            or metadata.get("comms_workspace_root", "")
            or ""
        ).strip()
        run_workspace_value = str(
            durable_run_metadata.get("workspace_root", "")
            or durable_run_metadata.get("comms_workspace_root", "")
            or ""
        ).strip()
        if not run_workspace_value:
            raise ValueError("durable company run has no workspace root")
        if not task_workspace_value:
            raise ValueError("durable runtime Task has no workspace root")
        task_output_value = str(
            metadata.get("output_root", "")
            or metadata.get("target_output_dir", "")
            or task_workspace_value
            or run_workspace_value
        ).strip()
        run_output_value = str(
            durable_run_metadata.get("output_root", "")
            or durable_run_metadata.get("target_output_dir", "")
            or ""
        ).strip()

        def _absolute(value: str) -> Path:
            return Path(
                os.path.abspath(
                    os.path.normpath(os.path.expanduser(str(value or "")))
                )
            )

        task_workspace = (
            _absolute(task_workspace_value) if task_workspace_value else None
        )
        run_workspace = (
            _absolute(run_workspace_value) if run_workspace_value else None
        )
        if (
            task_workspace is not None
            and run_workspace is not None
            and task_workspace != run_workspace
        ):
            raise ValueError(
                "durable runtime Task workspace does not match its run workspace"
            )
        workspace = run_workspace or task_workspace
        assert workspace is not None
        task_output = _absolute(task_output_value)
        run_output = _absolute(run_output_value) if run_output_value else None
        if run_output is not None and task_output != run_output:
            raise ValueError(
                "durable runtime Task output root does not match its run output root"
            )
        output = run_output or task_output
        if actual_workspace_root or actual_output_root:
            if not actual_workspace_root or not actual_output_root:
                raise ValueError(
                    "filesystem effect has an incomplete workspace capability"
                )
            actual_workspace = _absolute(actual_workspace_root)
            actual_output = _absolute(actual_output_root)
            if actual_workspace != workspace or actual_output != output:
                raise ValueError(
                    "filesystem effect workspace does not match its durable capability"
                )
        try:
            if Path(os.path.commonpath((str(workspace), str(output)))) != workspace:
                raise ValueError("durable output root is outside the workspace root")
        except (OSError, ValueError) as exc:
            raise ValueError(
                "durable output root is outside the workspace root"
            ) from exc

        candidate_value = str(raw_path or "")
        candidate = Path(os.path.expanduser(candidate_value))
        absolute = _absolute(
            candidate_value if candidate.is_absolute() else str(output / candidate)
        )
        try:
            if Path(os.path.commonpath((str(workspace), str(absolute)))) != workspace:
                raise ValueError("mutation path is outside the durable workspace root")
        except (OSError, ValueError) as exc:
            raise ValueError(
                "mutation path is outside the durable workspace root"
            ) from exc
        if absolute == workspace or absolute == output:
            raise ValueError("mutation path resolves to a workspace directory root")
        relative = os.path.relpath(str(absolute), str(workspace))
        relative_parts = Path(relative).parts
        if any(
            part == ".opc-comms" or part.startswith(".opc-write-")
            for part in relative_parts
        ):
            raise ValueError(
                "mutation path belongs to the runtime-internal workspace namespace"
            )
        path_key = unicodedata.normalize("NFC", Path(relative).as_posix()).casefold()
        if not path_key or path_key == ".":
            raise ValueError("mutation path does not identify a workspace file")
        return path_key, str(absolute)

    async def claim_company_artifact_paths_for_controller(
        self,
        *,
        project_id: str,
        run_id: str,
        work_item_id: str,
        runtime_task_id: str,
        subagent_run_id: str = "",
        subagent_parent_task_id: str = "",
        actual_workspace_root: str,
        actual_output_root: str,
        owner_token: str,
        generation: int,
        attempt_seq: int,
        raw_paths: list[str] | tuple[str, ...],
    ) -> CompanyArtifactOwnershipClaimReceipt:
        """Atomically reserve filesystem paths for one durable WorkItem.

        The claim is committed before the filesystem effect.  This is
        deliberate: if the effect fails, the same WorkItem may retry while a
        sibling can never race in and take over the partially attempted
        output.  The WorkItem, not a replaceable runtime Task, owns the path.
        """

        clean_project_id = str(project_id or "default").strip() or "default"
        clean_run_id = str(run_id or "").strip()
        clean_work_item_id = str(work_item_id or "").strip()
        clean_task_id = str(runtime_task_id or "").strip()
        clean_subagent_run_id = str(subagent_run_id or "").strip()
        clean_subagent_parent_task_id = str(
            subagent_parent_task_id or ""
        ).strip()
        clean_actual_workspace_root = str(actual_workspace_root or "").strip()
        clean_actual_output_root = str(actual_output_root or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        try:
            clean_generation = int(generation or 0)
        except (TypeError, ValueError):
            clean_generation = 0
        try:
            clean_attempt_seq = int(attempt_seq or 0)
        except (TypeError, ValueError):
            clean_attempt_seq = 0
        clean_raw_paths = tuple(
            str(value or "") for value in raw_paths if str(value or "")
        )
        if not (
            clean_run_id
            and clean_task_id
            and (clean_work_item_id or clean_subagent_run_id)
            and (not clean_subagent_run_id or clean_subagent_parent_task_id)
            and clean_actual_workspace_root
            and clean_actual_output_root
            and clean_owner_token
            and clean_generation > 0
            and clean_attempt_seq > 0
            and clean_raw_paths
        ):
            return CompanyArtifactOwnershipClaimReceipt(
                outcome="invalid_identity",
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=clean_work_item_id,
                runtime_task_id=clean_task_id,
                reason="company artifact mutation lacks an exact durable identity",
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            async with transaction_db.execute(
                """SELECT metadata FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at.isoformat(),
                ),
            ) as run_cursor:
                live_run = await run_cursor.fetchone()
            if live_run is None:
                raise CompanyRunControllerLeaseLost(
                    "company artifact ownership claim lost its controller generation"
                )
            run_metadata = _json_loads(live_run[0], {})

            effective_task_id = clean_task_id
            effective_work_item_id = clean_work_item_id
            isolated_worktree_path = ""
            if effective_work_item_id:
                identity_query = (
                    """SELECT task.project_id, task.metadata, item.run_id,
                              item.role_id, link.work_item_id
                       FROM tasks AS task
                       JOIN work_item_runtime_links AS link
                         ON link.runtime_task_id = task.id
                       JOIN delegation_work_items AS item
                         ON item.work_item_id = link.work_item_id
                       WHERE task.id = ? AND link.work_item_id = ?"""
                )
                identity_params: tuple[Any, ...] = (
                    effective_task_id,
                    effective_work_item_id,
                )
            else:
                async with transaction_db.execute(
                    """SELECT task_id, worktree_path, metadata, status
                       FROM runtime_subagent_runs
                       WHERE subagent_run_id = ? AND agent_id = ?""",
                    (clean_subagent_run_id, clean_subagent_run_id),
                ) as subagent_cursor:
                    subagent_rows = await subagent_cursor.fetchall()
                if len(subagent_rows) != 1:
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="invalid_identity",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        runtime_task_id=clean_task_id,
                        reason="native subagent has no durable parent Task chain",
                    )
                parent_task_id, worktree_path, subagent_metadata_json, subagent_status = (
                    subagent_rows[0]
                )
                subagent_metadata = _json_loads(subagent_metadata_json, {})
                if str(subagent_status or "").strip() != "running":
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="invalid_identity",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        runtime_task_id=clean_task_id,
                        reason="native subagent is not in its durable running state",
                    )
                effective_task_id = str(parent_task_id or "").strip()
                if (
                    not effective_task_id
                    or effective_task_id != clean_subagent_parent_task_id
                ):
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="invalid_identity",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        runtime_task_id=clean_task_id,
                        reason=(
                            "native subagent parent hint does not match its "
                            "durable parent Task"
                        ),
                    )
                if (
                    str(subagent_metadata.get("isolation", "") or "").strip()
                    == "worktree"
                ):
                    isolated_worktree_path = str(worktree_path or "").strip()
                    if not isolated_worktree_path:
                        await transaction_db.rollback()
                        return CompanyArtifactOwnershipClaimReceipt(
                            outcome="invalid_identity",
                            run_id=clean_run_id,
                            project_id=clean_project_id,
                            runtime_task_id=clean_task_id,
                            reason="isolated native subagent has no durable worktree",
                        )
                identity_query = (
                    """SELECT task.project_id, task.metadata, item.run_id,
                              item.role_id, link.work_item_id
                       FROM tasks AS task
                       JOIN work_item_runtime_links AS link
                         ON link.runtime_task_id = task.id
                       JOIN delegation_work_items AS item
                         ON item.work_item_id = link.work_item_id
                       WHERE task.id = ?"""
                )
                identity_params = (effective_task_id,)
            async with transaction_db.execute(
                identity_query,
                identity_params,
            ) as identity_cursor:
                identity_rows = await identity_cursor.fetchall()
            if len(identity_rows) != 1:
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="invalid_identity",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    reason="runtime Task is not durably linked to the claimed WorkItem",
                )
            (
                task_project_id,
                task_metadata_json,
                item_run_id,
                owner_role_id,
                durable_work_item_id,
            ) = identity_rows[0]
            effective_work_item_id = str(durable_work_item_id or "").strip()
            task_metadata = _json_loads(task_metadata_json, {})
            if not (
                str(task_project_id or "default").strip() == clean_project_id
                and str(item_run_id or "").strip() == clean_run_id
                and str(task_metadata.get("delegation_run_id", "") or "").strip()
                == clean_run_id
            ):
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="invalid_identity",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    reason="runtime Task, WorkItem, and run scopes do not match",
                )
            durable_task = Task(
                id=effective_task_id,
                project_id=clean_project_id,
                metadata=copy.deepcopy(task_metadata),
            )
            set_linked_work_item_id(durable_task, effective_work_item_id)
            durable_attempt_seq = int(
                task_metadata.get("claimed_work_item_attempt_seq", 0) or 0
            )
            if clean_subagent_run_id:
                async with transaction_db.execute(
                    """SELECT project_id, parent_id, metadata
                       FROM tasks WHERE id = ?""",
                    (clean_task_id,),
                ) as child_cursor:
                    child_row = await child_cursor.fetchone()
                if child_row is None:
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="invalid_identity",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        work_item_id=effective_work_item_id,
                        runtime_task_id=clean_task_id,
                        reason="native subagent has no durable child Task identity",
                    )
                child_project_id, child_parent_id, child_metadata_json = child_row
                child_metadata = _json_loads(child_metadata_json, {})
                try:
                    child_generation = int(
                        child_metadata.get(
                            "company_run_controller_lease_generation", 0
                        )
                        or 0
                    )
                    child_attempt_seq = int(
                        child_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                    )
                except (TypeError, ValueError):
                    child_generation = 0
                    child_attempt_seq = 0
                if not (
                    str(child_project_id or "default").strip()
                    == clean_project_id
                    and str(child_parent_id or "").strip() == effective_task_id
                    and str(
                        child_metadata.get("_comms_endpoint_id", "") or ""
                    ).strip()
                    == clean_subagent_run_id
                    and str(
                        child_metadata.get("delegation_run_id", "") or ""
                    ).strip()
                    == clean_run_id
                    and str(
                        child_metadata.get(
                            "company_run_controller_owner_token", ""
                        )
                        or ""
                    ).strip()
                    == clean_owner_token
                    and child_generation == clean_generation
                    and child_attempt_seq == clean_attempt_seq
                    and child_attempt_seq == durable_attempt_seq
                ):
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="invalid_identity",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        work_item_id=effective_work_item_id,
                        runtime_task_id=clean_task_id,
                        reason=(
                            "native subagent child credential does not match "
                            "its durable parent attempt"
                        ),
                    )
            if not (
                durable_attempt_seq == clean_attempt_seq
                and await self._company_controller_active_effect_attempt_matches(
                    transaction_db,
                    durable_task,
                    checked_at=checked_at,
                )
            ):
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="invalid_identity",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    reason=(
                        "runtime Task does not own the current durable "
                        "WorkItem attempt"
                    ),
                )

            try:
                if isolated_worktree_path:
                    # Isolated subagents cannot mutate the shared company
                    # workspace.  Their Store-owned worktree is a separate
                    # filesystem capability and therefore does not reserve a
                    # shared artifact key.
                    self._canonical_company_artifact_path(
                        task_metadata,
                        run_metadata,
                        "__ownership_scope_probe__",
                    )
                    isolated_metadata = {
                        "workspace_root": isolated_worktree_path,
                        "output_root": isolated_worktree_path,
                    }
                    isolated_by_key: dict[str, str] = {}
                    for raw_path in clean_raw_paths:
                        path_key, absolute_path = (
                            self._canonical_company_artifact_path(
                                isolated_metadata,
                                isolated_metadata,
                                raw_path,
                                actual_workspace_root=clean_actual_workspace_root,
                                actual_output_root=clean_actual_output_root,
                            )
                        )
                        isolated_by_key.setdefault(path_key, absolute_path)
                    isolated_keys = tuple(isolated_by_key)
                    await transaction_db.rollback()
                    return CompanyArtifactOwnershipClaimReceipt(
                        outcome="isolated",
                        run_id=clean_run_id,
                        project_id=clean_project_id,
                        work_item_id=effective_work_item_id,
                        runtime_task_id=effective_task_id,
                        path_keys=isolated_keys,
                        reason="mutation is confined to a durable isolated worktree",
                    )
                canonical_by_key: dict[str, str] = {}
                for raw_path in clean_raw_paths:
                    path_key, absolute_path = (
                        self._canonical_company_artifact_path(
                            task_metadata,
                            run_metadata,
                            raw_path,
                            actual_workspace_root=clean_actual_workspace_root,
                            actual_output_root=clean_actual_output_root,
                        )
                    )
                    canonical_by_key.setdefault(path_key, absolute_path)
                path_keys = tuple(canonical_by_key)
            except (OSError, TypeError, ValueError) as exc:
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="invalid_path",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    reason=str(exc),
                )
            if not path_keys:
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="invalid_path",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    reason="file mutation did not identify a durable workspace path",
                )

            placeholders = ", ".join("?" for _ in path_keys)
            async with transaction_db.execute(
                """SELECT path_key, owner_work_item_id, owner_role_id
                   FROM company_artifact_ownership
                   WHERE project_id = ? AND run_id = ?
                     AND path_key IN ("""
                + placeholders
                + ")",
                (clean_project_id, clean_run_id, *path_keys),
            ) as ownership_cursor:
                ownership_rows = await ownership_cursor.fetchall()
            conflict = next(
                (
                    row
                    for row in ownership_rows
                    if str(row[1] or "").strip() != effective_work_item_id
                ),
                None,
            )
            if conflict is not None:
                await transaction_db.rollback()
                return CompanyArtifactOwnershipClaimReceipt(
                    outcome="conflict",
                    run_id=clean_run_id,
                    project_id=clean_project_id,
                    work_item_id=effective_work_item_id,
                    runtime_task_id=effective_task_id,
                    path_keys=path_keys,
                    conflicting_path=str(conflict[0] or ""),
                    conflicting_work_item_id=str(conflict[1] or ""),
                    conflicting_role_id=str(conflict[2] or ""),
                    reason="artifact path is owned by another durable WorkItem",
                )

            timestamp = checked_at.isoformat()
            for path_key in path_keys:
                await transaction_db.execute(
                    """INSERT INTO company_artifact_ownership
                       (project_id, run_id, path_key, owner_work_item_id,
                        owner_role_id, owner_runtime_task_id, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                       ON CONFLICT(project_id, run_id, path_key) DO UPDATE SET
                           owner_role_id = excluded.owner_role_id,
                           owner_runtime_task_id = excluded.owner_runtime_task_id,
                           updated_at = excluded.updated_at
                       WHERE company_artifact_ownership.owner_work_item_id =
                             excluded.owner_work_item_id""",
                    (
                        clean_project_id,
                        clean_run_id,
                        path_key,
                        effective_work_item_id,
                        str(owner_role_id or "").strip(),
                        effective_task_id,
                        timestamp,
                        timestamp,
                    ),
                )
            await transaction_db.commit()
            return CompanyArtifactOwnershipClaimReceipt(
                outcome="claimed",
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=effective_work_item_id,
                runtime_task_id=effective_task_id,
                path_keys=path_keys,
            )
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def authorize_company_opaque_tool_effect_for_controller(
        self,
        *,
        project_id: str,
        run_id: str,
        work_item_id: str,
        runtime_task_id: str,
        subagent_run_id: str = "",
        subagent_parent_task_id: str = "",
        owner_token: str,
        generation: int,
        attempt_seq: int,
        tool_call_id: str,
        tool_name: str,
        arguments: dict[str, Any],
        execution_envelope: dict[str, Any],
        execution_identity: dict[str, Any],
        permit: dict[str, Any],
    ) -> CompanyOpaqueToolEffectReceipt:
        """Consume one exact human permit at the opaque effect boundary."""

        clean_project_id = str(project_id or "default").strip() or "default"
        clean_run_id = str(run_id or "").strip()
        clean_work_item_id = str(work_item_id or "").strip()
        clean_task_id = str(runtime_task_id or "").strip()
        clean_subagent_id = str(subagent_run_id or "").strip()
        clean_parent_id = str(subagent_parent_task_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_tool_call_id = str(tool_call_id or "").strip()
        clean_tool_name = str(tool_name or "").strip()
        normalized_arguments = json.loads(_json_dumps(dict(arguments or {})))
        normalized_execution_envelope = json.loads(
            _json_dumps(dict(execution_envelope or {}))
        )
        normalized_execution_identity = json.loads(
            _json_dumps(dict(execution_identity or {}))
        )
        normalized_permit = json.loads(_json_dumps(dict(permit or {})))
        try:
            clean_generation = int(generation or 0)
        except (TypeError, ValueError):
            clean_generation = 0
        try:
            clean_attempt_seq = int(attempt_seq or 0)
        except (TypeError, ValueError):
            clean_attempt_seq = 0
        runtime_session_id = str(
            normalized_permit.get("runtime_session_id", "") or ""
        ).strip()
        fingerprint = str(normalized_permit.get("fingerprint", "") or "").strip()
        if not (
            clean_run_id
            and clean_task_id
            and (clean_work_item_id or clean_subagent_id)
            and (not clean_subagent_id or clean_parent_id)
            and clean_owner_token
            and clean_generation > 0
            and clean_attempt_seq > 0
            and clean_tool_call_id
            and clean_tool_name in {"shell_exec", "python_exec"}
            and normalized_execution_envelope
            and normalized_execution_identity
            and runtime_session_id
            and fingerprint
        ):
            return CompanyOpaqueToolEffectReceipt(
                outcome="invalid_identity",
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=clean_work_item_id,
                runtime_task_id=clean_task_id,
                fingerprint=fingerprint,
                reason="opaque company ToolCall lacks an exact durable identity",
            )

        expected_fingerprint = exact_tool_call_fingerprint(
            tool_call_id=clean_tool_call_id,
            tool_name=clean_tool_name,
            arguments=normalized_arguments,
            runtime_session_id=runtime_session_id,
            execution_envelope=normalized_execution_envelope,
            execution_identity=normalized_execution_identity,
        )
        if fingerprint != expected_fingerprint:
            return CompanyOpaqueToolEffectReceipt(
                outcome="invalid_permit",
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=clean_work_item_id,
                runtime_task_id=clean_task_id,
                fingerprint=fingerprint,
                reason="opaque ToolCall fingerprint does not match its effect",
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        effective_work_item_id = clean_work_item_id
        effective_task_id = clean_task_id

        async def _deny(outcome: str, reason: str) -> CompanyOpaqueToolEffectReceipt:
            await transaction_db.rollback()
            return CompanyOpaqueToolEffectReceipt(
                outcome=outcome,
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=effective_work_item_id,
                runtime_task_id=clean_task_id,
                fingerprint=fingerprint,
                reason=reason,
            )

        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            async with transaction_db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at.isoformat(),
                ),
            ) as run_cursor:
                if await run_cursor.fetchone() is None:
                    raise CompanyRunControllerLeaseLost(
                        "opaque company ToolCall lost its controller generation"
                    )

            if clean_subagent_id:
                async with transaction_db.execute(
                    """SELECT task_id, status FROM runtime_subagent_runs
                       WHERE subagent_run_id = ? AND agent_id = ?""",
                    (clean_subagent_id, clean_subagent_id),
                ) as cursor:
                    subagent_rows = await cursor.fetchall()
                if len(subagent_rows) != 1:
                    return await _deny(
                        "invalid_identity",
                        "native subagent has no durable parent Task chain",
                    )
                effective_task_id = str(subagent_rows[0][0] or "").strip()
                if (
                    effective_task_id != clean_parent_id
                    or str(subagent_rows[0][1] or "").strip() != "running"
                ):
                    return await _deny(
                        "invalid_identity",
                        "native subagent parent or running state is not authoritative",
                    )
                identity_where = "task.id = ?"
                identity_params: tuple[Any, ...] = (effective_task_id,)
            else:
                identity_where = "task.id = ? AND link.work_item_id = ?"
                identity_params = (effective_task_id, effective_work_item_id)

            async with transaction_db.execute(
                f"""SELECT task.project_id, task.metadata, item.run_id,
                           link.work_item_id
                    FROM tasks AS task
                    JOIN work_item_runtime_links AS link
                      ON link.runtime_task_id = task.id
                    JOIN delegation_work_items AS item
                      ON item.work_item_id = link.work_item_id
                    WHERE {identity_where}""",
                identity_params,
            ) as cursor:
                identity_rows = await cursor.fetchall()
            if len(identity_rows) != 1:
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall parent Task is not durably linked to one WorkItem",
                )
            task_project_id, parent_metadata_json, item_run_id, durable_work_item_id = (
                identity_rows[0]
            )
            effective_work_item_id = str(durable_work_item_id or "").strip()
            parent_metadata = _json_loads(parent_metadata_json, {})
            if not (
                str(task_project_id or "default").strip() == clean_project_id
                and str(item_run_id or "").strip() == clean_run_id
                and str(parent_metadata.get("delegation_run_id", "") or "").strip()
                == clean_run_id
            ):
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall Task, WorkItem, and run scopes do not match",
                )
            durable_parent = Task(
                id=effective_task_id,
                project_id=clean_project_id,
                metadata=copy.deepcopy(parent_metadata),
            )
            set_linked_work_item_id(durable_parent, effective_work_item_id)
            durable_attempt_seq = int(
                parent_metadata.get("claimed_work_item_attempt_seq", 0) or 0
            )
            if not (
                durable_attempt_seq == clean_attempt_seq
                and await self._company_controller_active_effect_attempt_matches(
                    transaction_db,
                    durable_parent,
                    checked_at=checked_at,
                )
            ):
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall parent does not own the current WorkItem attempt",
                )

            async with transaction_db.execute(
                """SELECT project_id, parent_id, context_snapshot, metadata
                   FROM tasks WHERE id = ?""",
                (clean_task_id,),
            ) as cursor:
                effect_task_row = await cursor.fetchone()
            if effect_task_row is None:
                return await _deny(
                    "invalid_permit",
                    "opaque ToolCall Task has no durable permit ledger",
                )
            (
                effect_project_id,
                effect_parent_id,
                context_snapshot_json,
                effect_metadata_json,
            ) = effect_task_row
            effect_metadata = _json_loads(effect_metadata_json, {})
            if not (
                str(effect_project_id or "default").strip() == clean_project_id
                and str(effect_metadata.get("delegation_run_id", "") or "").strip()
                == clean_run_id
                and str(
                    effect_metadata.get("company_run_controller_owner_token", "")
                    or ""
                ).strip()
                == clean_owner_token
                and int(
                    effect_metadata.get(
                        "company_run_controller_lease_generation",
                        0,
                    )
                    or 0
                )
                == clean_generation
                and int(
                    effect_metadata.get("claimed_work_item_attempt_seq", 0) or 0
                )
                == clean_attempt_seq
            ):
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall Task credential is not durable or current",
                )
            if clean_subagent_id and not (
                str(effect_parent_id or "").strip() == effective_task_id
                and str(effect_metadata.get("_comms_endpoint_id", "") or "").strip()
                == clean_subagent_id
                and str(
                    effect_metadata.get("_company_parent_work_item_id", "")
                    or ""
                ).strip()
                == effective_work_item_id
            ):
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall child does not match its durable subagent chain",
                )
            durable_effect_task = Task(
                id=clean_task_id,
                parent_id=str(effect_parent_id or "").strip() or None,
                project_id=clean_project_id,
                context_snapshot=_json_loads(context_snapshot_json, {}),
                metadata=copy.deepcopy(effect_metadata),
            )
            if not clean_subagent_id:
                set_linked_work_item_id(
                    durable_effect_task,
                    effective_work_item_id,
                )
            durable_execution_identity = company_opaque_execution_identity(
                durable_effect_task
            )
            if durable_execution_identity != normalized_execution_identity:
                return await _deny(
                    "invalid_identity",
                    "opaque ToolCall execution identity differs from its durable Task chain",
                )
            try:
                durable_execution_envelope = (
                    build_company_opaque_execution_plan(
                        durable_effect_task,
                        clean_tool_name,
                        normalized_arguments,
                    ).envelope
                )
            except (OpaqueExecutionEnvelopeError, TypeError, ValueError):
                return await _deny(
                    "invalid_envelope",
                    "opaque ToolCall durable launch envelope cannot be resolved",
                )
            if durable_execution_envelope != normalized_execution_envelope:
                return await _deny(
                    "invalid_envelope",
                    "opaque ToolCall launch envelope differs from durable Task state",
                )

            (
                _,
                _,
                permits,
                _,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                _json_loads(context_snapshot_json, {}),
                effect_metadata,
            )
            current = dict(permits.get(fingerprint, {}) or {})
            checkpoint_id = str(current.get("checkpoint_id", "") or "").strip()
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=clean_project_id,
                checkpoint_type="tool_permission",
                db=transaction_db,
            )
            if checkpoint is None:
                return await _deny(
                    "invalid_permit",
                    "exact ToolCall checkpoint is unavailable",
                )
            claim_id = str(current.get("claim_id", "") or "").strip()
            consumer_id = str(current.get("consumer_id", "") or "").strip()
            interaction = self._execution_checkpoint_interaction(
                dict(checkpoint.payload or {})
            )
            claim = dict(interaction.get("claim", {}) or {})
            execution = dict(interaction.get("execution", {}) or {})
            try:
                claim_expiry = datetime.fromisoformat(
                    str(claim.get("lease_expires_at", "") or "")
                )
                expiry_checked_at = (
                    checked_at
                    if claim_expiry.tzinfo is None
                    else checked_at.astimezone(claim_expiry.tzinfo)
                )
                claim_is_live = claim_expiry > expiry_checked_at
            except (TypeError, ValueError):
                claim_is_live = False
            permit_matches = (
                bool(current)
                and current == normalized_permit
                and current.get("approved") is True
                and str(current.get("decision", "") or "").strip()
                == "approve_once"
                and str(current.get("state", "") or "").strip() == "executing"
                and str(recorded_runtime_id or "").strip() == runtime_session_id
                and str(checkpoint.status or "").strip() == "consuming"
                and claim_is_live
                and str(claim.get("claim_id", "") or "").strip() == claim_id
                and str(claim.get("consumer_id", "") or "").strip()
                == consumer_id
                and str(execution.get("state", "") or "").strip() == "executing"
                and str(execution.get("claim_id", "") or "").strip() == claim_id
                and str(execution.get("consumer_id", "") or "").strip()
                == consumer_id
                and self._exact_tool_permit_matches_checkpoint(
                    current,
                    checkpoint,
                    task_id=clean_task_id,
                    project_id=clean_project_id,
                    runtime_session_id=runtime_session_id,
                    fingerprint=fingerprint,
                    tool_call_id=clean_tool_call_id,
                    tool_name=clean_tool_name,
                    arguments=normalized_arguments,
                    execution_envelope=normalized_execution_envelope,
                    execution_identity=normalized_execution_identity,
                    claim_id=claim_id,
                    consumer_id=consumer_id,
                )
            )
            if not permit_matches:
                return await _deny(
                    "invalid_permit",
                    "opaque ToolCall lacks its exact executing human permit",
                )
            async with transaction_db.execute(
                """SELECT 1 FROM runtime_tool_results
                   WHERE runtime_session_id = ? AND tool_call_id = ? LIMIT 1""",
                (runtime_session_id, clean_tool_call_id),
            ) as cursor:
                if await cursor.fetchone() is not None:
                    return await _deny(
                        "already_consumed",
                        "opaque ToolCall result already exists",
                    )
            insert = await transaction_db.execute(
                """INSERT OR IGNORE INTO company_opaque_tool_effect_fences
                   (project_id, run_id, fingerprint, work_item_id,
                    runtime_task_id, tool_call_id, tool_name, consumed_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    clean_project_id,
                    clean_run_id,
                    fingerprint,
                    effective_work_item_id,
                    clean_task_id,
                    clean_tool_call_id,
                    clean_tool_name,
                    checked_at.isoformat(),
                ),
            )
            if insert.rowcount != 1:
                return await _deny(
                    "already_consumed",
                    "opaque ToolCall effect permit was already consumed",
                )
            await transaction_db.commit()
            return CompanyOpaqueToolEffectReceipt(
                outcome="authorized",
                run_id=clean_run_id,
                project_id=clean_project_id,
                work_item_id=effective_work_item_id,
                runtime_task_id=clean_task_id,
                fingerprint=fingerprint,
            )
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def company_automated_verification_evidence(
        self,
        task: Task,
        required_commands: list[str],
    ) -> dict[str, Any]:
        """Verify current-attempt shell results without executing gate data.

        Gate metadata and environment manifests are untrusted strings.  The
        controller may accept them only when the same current WorkItem attempt
        already executed an exact approved ``shell_exec`` ToolCall and stored
        its successful ToolResult.  Any later opaque or structured mutation
        makes the evidence stale.
        """

        commands = [
            str(command or "").strip()
            for command in list(required_commands or [])
            if str(command or "").strip()
        ]
        if not commands:
            return {"verified": True, "results": [], "reason": "no checks"}

        project_id = str(task.project_id or "default").strip() or "default"
        task_id = str(task.id or "").strip()
        work_item_id = linked_work_item_id_for_task(task)
        metadata = dict(task.metadata or {})
        run_id = str(metadata.get("delegation_run_id", "") or "").strip()
        try:
            attempt_seq = int(
                metadata.get("claimed_work_item_attempt_seq", 0) or 0
            )
        except (TypeError, ValueError):
            attempt_seq = 0
        runtime_state = dict(metadata.get("runtime_v2", {}) or {})
        runtime_session_id = str(
            runtime_state.get("runtime_session_id", "") or ""
        ).strip()
        if not all(
            (
                task_id,
                work_item_id,
                run_id,
                attempt_seq > 0,
                runtime_session_id,
            )
        ):
            return {
                "verified": False,
                "results": [],
                "reason": "verification evidence lacks a current runtime identity",
            }

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        owner_task_ids = {task_id}
        owner_runtime_pairs = {(task_id, runtime_session_id)}

        def _identity_matches(value: Any) -> bool:
            record = dict(value or {}) if isinstance(value, dict) else {}
            try:
                recorded_attempt = int(
                    record.get("claimed_work_item_attempt_seq", 0) or 0
                )
            except (TypeError, ValueError):
                return False
            return bool(
                str(record.get("project_id", "") or "").strip()
                == project_id
                and str(record.get("delegation_run_id", "") or "").strip()
                == run_id
                and str(record.get("work_item_id", "") or "").strip()
                == work_item_id
                and str(record.get("runtime_task_id", "") or "").strip()
                in owner_task_ids
                and recorded_attempt == attempt_seq
            )

        def _result_passed(payload: Any) -> bool:
            outer = dict(payload or {}) if isinstance(payload, dict) else {}
            inner = outer.get("result")
            if outer.get("success") is not True or not isinstance(inner, dict):
                return False
            try:
                exit_code = int(inner.get("exit_code", -1))
            except (TypeError, ValueError):
                return False
            return inner.get("success") is True and exit_code == 0

        def _effect_result_completed(payload: Any) -> bool:
            outer = dict(payload or {}) if isinstance(payload, dict) else {}
            if outer.get("success") is not True:
                return False
            inner = outer.get("result")
            return not isinstance(inner, dict) or inner.get("success") is True

        try:
            await transaction_db.execute("BEGIN")
            async with transaction_db.execute(
                """SELECT task.context_snapshot, task.metadata,
                          link.work_item_id, item.run_id
                   FROM tasks AS task
                   JOIN work_item_runtime_links AS link
                     ON link.runtime_task_id = task.id
                   JOIN delegation_work_items AS item
                     ON item.work_item_id = link.work_item_id
                   WHERE task.id = ? AND task.project_id = ?""",
                (task_id, project_id),
            ) as cursor:
                rows = await cursor.fetchall()
            if len(rows) != 1:
                return {
                    "verified": False,
                    "results": [],
                    "reason": "verification Task has no durable WorkItem link",
                }
            context_json, durable_metadata_json, linked_id, item_run_id = rows[0]
            durable_metadata = _json_loads(durable_metadata_json, {})
            durable_runtime_state = dict(
                durable_metadata.get("runtime_v2", {}) or {}
            )
            if not (
                str(linked_id or "").strip() == work_item_id
                and str(item_run_id or "").strip() == run_id
                and str(
                    durable_metadata.get("delegation_run_id", "") or ""
                ).strip()
                == run_id
                and int(
                    durable_metadata.get("claimed_work_item_attempt_seq", 0)
                    or 0
                )
                == attempt_seq
                and str(
                    durable_runtime_state.get("runtime_session_id", "") or ""
                ).strip()
                == runtime_session_id
            ):
                return {
                    "verified": False,
                    "results": [],
                    "reason": "verification runtime identity is not durable",
                }
            durable_task = Task(
                id=task_id,
                project_id=project_id,
                context_snapshot=_json_loads(context_json, {}),
                metadata=copy.deepcopy(durable_metadata),
            )
            set_linked_work_item_id(durable_task, work_item_id)
            if not await self._company_controller_active_effect_attempt_matches(
                transaction_db,
                durable_task,
                checked_at=datetime.now(),
            ):
                return {
                    "verified": False,
                    "results": [],
                    "reason": "verification WorkItem attempt is no longer active",
                }

            # Include every durably linked native-subagent descendant.  The
            # child metadata alone is never authoritative: its endpoint must
            # match a runtime_subagent_runs row whose parent is already in the
            # verified chain, and its run/WI/attempt must remain exact.
            async with transaction_db.execute(
                """SELECT id, parent_id, metadata
                   FROM tasks WHERE project_id = ? AND parent_id IS NOT NULL""",
                (project_id,),
            ) as cursor:
                child_task_rows = await cursor.fetchall()
            async with transaction_db.execute(
                """SELECT subagent_run_id, task_id
                   FROM runtime_subagent_runs"""
            ) as cursor:
                subagent_rows = await cursor.fetchall()
            durable_subagents = {
                (
                    str(row[1] or "").strip(),
                    str(row[0] or "").strip(),
                )
                for row in subagent_rows
                if str(row[0] or "").strip() and str(row[1] or "").strip()
            }
            pending_children = list(child_task_rows)
            while pending_children:
                advanced = False
                remaining: list[Any] = []
                for child_id_raw, parent_id_raw, child_metadata_json in pending_children:
                    child_id = str(child_id_raw or "").strip()
                    parent_id = str(parent_id_raw or "").strip()
                    child_metadata = _json_loads(child_metadata_json, {})
                    endpoint_id = str(
                        child_metadata.get("_comms_endpoint_id", "") or ""
                    ).strip()
                    try:
                        child_attempt = int(
                            child_metadata.get(
                                "claimed_work_item_attempt_seq", 0
                            )
                            or 0
                        )
                    except (TypeError, ValueError):
                        child_attempt = 0
                    if parent_id not in owner_task_ids:
                        remaining.append(
                            (child_id_raw, parent_id_raw, child_metadata_json)
                        )
                        continue
                    child_runtime = dict(
                        child_metadata.get("runtime_v2", {}) or {}
                    )
                    child_runtime_session_id = str(
                        child_runtime.get("runtime_session_id", "") or ""
                    ).strip()
                    if not (
                        child_id
                        and endpoint_id
                        and (parent_id, endpoint_id) in durable_subagents
                        and str(
                            child_metadata.get("delegation_run_id", "") or ""
                        ).strip()
                        == run_id
                        and str(
                            child_metadata.get(
                                "_company_parent_work_item_id", ""
                            )
                            or ""
                        ).strip()
                        == work_item_id
                        and child_attempt == attempt_seq
                    ):
                        continue
                    owner_task_ids.add(child_id)
                    if child_runtime_session_id:
                        owner_runtime_pairs.add(
                            (child_id, child_runtime_session_id)
                        )
                    advanced = True
                if not advanced:
                    break
                pending_children = remaining

            task_placeholders = ", ".join("?" for _ in owner_task_ids)
            async with transaction_db.execute(
                f"""SELECT runtime_session_id, task_id, tool_call_id,
                           tool_name, arguments, metadata, created_at
                   FROM runtime_tool_calls
                   WHERE task_id IN ({task_placeholders})
                   ORDER BY created_at ASC""",
                tuple(sorted(owner_task_ids)),
            ) as cursor:
                call_rows = await cursor.fetchall()
            calls = [
                {
                    "runtime_session_id": str(row[0] or "").strip(),
                    "task_id": str(row[1] or "").strip(),
                    "tool_call_id": str(row[2] or "").strip(),
                    "tool_name": str(row[3] or "").strip(),
                    "arguments": _json_loads(row[4], {}),
                    "metadata": _json_loads(row[5], {}),
                    "created_at": str(row[6] or "").strip(),
                }
                for row in call_rows
                if (
                    str(row[1] or "").strip(),
                    str(row[0] or "").strip(),
                )
                in owner_runtime_pairs
            ]
            async with transaction_db.execute(
                f"""SELECT runtime_session_id, task_id, tool_call_id,
                           tool_name, payload, metadata, created_at
                   FROM runtime_tool_results
                   WHERE task_id IN ({task_placeholders})
                   ORDER BY created_at ASC""",
                tuple(sorted(owner_task_ids)),
            ) as cursor:
                result_rows = await cursor.fetchall()
            results = [
                {
                    "runtime_session_id": str(row[0] or "").strip(),
                    "task_id": str(row[1] or "").strip(),
                    "tool_call_id": str(row[2] or "").strip(),
                    "tool_name": str(row[3] or "").strip(),
                    "payload": _json_loads(row[4], {}),
                    "metadata": _json_loads(row[5], {}),
                    "created_at": str(row[6] or "").strip(),
                }
                for row in result_rows
                if (
                    str(row[1] or "").strip(),
                    str(row[0] or "").strip(),
                )
                in owner_runtime_pairs
            ]
            async with transaction_db.execute(
                """SELECT tool_call_id, fingerprint, consumed_at
                   FROM company_opaque_tool_effect_fences
                   WHERE project_id = ? AND run_id = ? AND work_item_id = ?""",
                (project_id, run_id, work_item_id),
            ) as cursor:
                fence_rows = await cursor.fetchall()
            fence_records = {
                (
                    str(row[0] or "").strip(),
                    str(row[1] or "").strip(),
                ): str(row[2] or "").strip()
                for row in fence_rows
            }
            evidence_results: list[dict[str, Any]] = []
            evidence_times: list[str] = []
            selected_effects: set[tuple[str, str, str]] = set()
            selected_fences: set[tuple[str, str]] = set()
            for command in commands:
                candidates: list[
                    tuple[str, dict[str, Any], str, str]
                ] = []
                for call in calls:
                    if not (
                        call["task_id"] == task_id
                        and call["runtime_session_id"]
                        == runtime_session_id
                    ):
                        continue
                    try:
                        plan = build_company_opaque_execution_plan(
                            durable_task,
                            "shell_exec",
                            dict(call["arguments"] or {}),
                        )
                        execution_identity = company_opaque_execution_identity(
                            durable_task
                        )
                        expected_fingerprint = exact_tool_call_fingerprint(
                            tool_call_id=call["tool_call_id"],
                            tool_name="shell_exec",
                            arguments=dict(call["arguments"] or {}),
                            runtime_session_id=runtime_session_id,
                            execution_envelope=plan.envelope,
                            execution_identity=execution_identity,
                        )
                        expected_envelope_digest = (
                            opaque_execution_envelope_digest(plan.envelope)
                        )
                    except (
                        OpaqueExecutionEnvelopeError,
                        TypeError,
                        ValueError,
                    ):
                        continue
                    call_metadata = dict(call["metadata"] or {})
                    if not (
                        call["tool_name"] == "shell_exec"
                        and _identity_matches(call["metadata"])
                        and str(
                            call_metadata.get(
                                "company_opaque_fingerprint", ""
                            )
                            or ""
                        ).strip()
                        == expected_fingerprint
                        and str(
                            call_metadata.get(
                                "company_opaque_execution_envelope_digest", ""
                            )
                            or ""
                        ).strip()
                        == expected_envelope_digest
                        and str(
                            dict(call["arguments"] or {}).get("command", "")
                            or ""
                        ).strip()
                        == command
                        and (
                            call["tool_call_id"],
                            expected_fingerprint,
                        )
                        in fence_records
                    ):
                        continue
                    for result in results:
                        result_metadata = dict(result["metadata"] or {})
                        if not (
                            result["tool_call_id"] == call["tool_call_id"]
                            and result["task_id"] == call["task_id"]
                            and result["runtime_session_id"]
                            == call["runtime_session_id"]
                            and result["tool_name"] == "shell_exec"
                            and _identity_matches(result["metadata"])
                            and str(
                                result_metadata.get(
                                    "company_opaque_fingerprint", ""
                                )
                                or ""
                            ).strip()
                            == expected_fingerprint
                            and str(
                                result_metadata.get(
                                    "company_opaque_execution_envelope_digest", ""
                                )
                                or ""
                            ).strip()
                            == expected_envelope_digest
                            and _result_passed(result["payload"])
                        ):
                            continue
                        candidates.append(
                            (
                                result["created_at"],
                                dict(result["payload"].get("result", {}) or {}),
                                call["tool_call_id"],
                                expected_fingerprint,
                            )
                        )
                if not candidates:
                    return {
                        "verified": False,
                        "results": evidence_results,
                        "reason": (
                            "required verification command has no exact successful "
                            f"current-attempt ToolResult: {command}"
                        ),
                    }
                result_time, inner, call_id, selected_fingerprint = max(
                    candidates,
                    key=lambda item: item[0],
                )
                evidence_times.append(result_time)
                selected_effects.add(
                    (runtime_session_id, task_id, call_id)
                )
                selected_fences.add((call_id, selected_fingerprint))
                evidence_results.append(
                    {
                        "command": command,
                        "passed": True,
                        "exit_code": 0,
                        "stdout": str(inner.get("stdout", "") or ""),
                        "stderr": str(inner.get("stderr", "") or ""),
                        "tool_call_id": call_id,
                        "result_created_at": result_time,
                        "outcome": "exact_current_attempt_evidence",
                    }
                )

            earliest_result_at = min(evidence_times)
            latest_result_at = max(evidence_times)
            stale_tools = {
                "shell_exec",
                "python_exec",
                *FILE_MUTATION_TOOL_NAMES,
            }
            for call in calls:
                effect_key = (
                    call["runtime_session_id"],
                    call["task_id"],
                    call["tool_call_id"],
                )
                if (
                    call["tool_name"] not in stale_tools
                    or effect_key in selected_effects
                ):
                    continue
                if not _identity_matches(call["metadata"]):
                    return {
                        "verified": False,
                        "results": evidence_results,
                        "reason": (
                            "verification evidence has an unbound current-runtime "
                            "mutation ToolCall"
                        ),
                    }
                completed = [
                    result
                    for result in results
                    if result["runtime_session_id"]
                    == call["runtime_session_id"]
                    and result["task_id"] == call["task_id"]
                    and result["tool_call_id"] == call["tool_call_id"]
                    and result["tool_name"] == call["tool_name"]
                    and _identity_matches(result["metadata"])
                    and _effect_result_completed(result["payload"])
                ]
                if not completed:
                    return {
                        "verified": False,
                        "results": evidence_results,
                        "reason": (
                            "verification evidence is stale while a mutation "
                            "ToolCall lacks a successful durable ToolResult"
                        ),
                    }
                completed_at = max(
                    result["created_at"] for result in completed
                )
                if (
                    call["created_at"] > earliest_result_at
                    or completed_at > earliest_result_at
                ):
                    return {
                        "verified": False,
                        "results": evidence_results,
                        "reason": (
                            "verification evidence is stale after a mutation "
                            "ToolCall completed"
                        ),
                    }
            if any(
                key not in selected_fences
                and str(consumed_at or "").strip() > earliest_result_at
                for key, consumed_at in fence_records.items()
            ):
                return {
                    "verified": False,
                    "results": evidence_results,
                    "reason": "verification evidence is stale after a later opaque effect",
                }
            async with transaction_db.execute(
                """SELECT MAX(updated_at) FROM company_artifact_ownership
                   WHERE project_id = ? AND run_id = ?
                     AND owner_work_item_id = ?""",
                (project_id, run_id, work_item_id),
            ) as cursor:
                artifact_row = await cursor.fetchone()
            latest_artifact_update = str(
                (artifact_row[0] if artifact_row else "") or ""
            ).strip()
            if latest_artifact_update > earliest_result_at:
                return {
                    "verified": False,
                    "results": evidence_results,
                    "reason": "verification evidence is stale after a later artifact mutation",
                }
            return {
                "verified": True,
                "results": evidence_results,
                "earliest_result_at": earliest_result_at,
                "latest_result_at": latest_result_at,
                "reason": "all exact current-attempt verification evidence passed",
            }
        except (TypeError, ValueError):
            return {
                "verified": False,
                "results": [],
                "reason": "verification evidence contains an invalid durable identity",
            }
        finally:
            await transaction_db.rollback()
            await transaction_db.close()

    async def release_delegation_run_controller_lease(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
    ) -> bool:
        """Gracefully release only the caller's exact fenced lease."""

        db = self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation)
        # Task stamps are attempt credentials, not historical workflow state.
        # Remove only this exact generation while it is still authoritative so
        # later owner/admin transitions never inherit an expired credential.
        await db.execute(
            """UPDATE tasks
               SET metadata = json_remove(
                   metadata,
                   '$.company_run_controller_owner_token',
                   '$.company_run_controller_lease_generation',
                   '$.claimed_work_item_attempt_seq'
               )
               WHERE project_id = ?
                 AND json_extract(metadata, '$.delegation_run_id') = ?
                 AND json_extract(metadata, '$.company_run_controller_owner_token') = ?
                 AND CAST(
                     json_extract(metadata, '$.company_run_controller_lease_generation')
                     AS INTEGER
                 ) = ?
                 AND EXISTS (
                     SELECT 1 FROM delegation_runs
                     WHERE run_id = ? AND project_id = ? AND session_id = ?
                       AND controller_owner_token = ?
                       AND controller_lease_generation = ?
                 )""",
            (
                clean_project_id,
                clean_run_id,
                clean_owner_token,
                clean_generation,
                clean_run_id,
                clean_project_id,
                clean_root_session_id,
                clean_owner_token,
                clean_generation,
            ),
        )
        cursor = await db.execute(
            """UPDATE delegation_runs
               SET controller_owner_token = '',
                   controller_lease_acquired_at = NULL,
                   controller_lease_heartbeat_at = NULL,
                   controller_lease_expires_at = NULL
               WHERE run_id = ?
                 AND project_id = ?
                 AND session_id = ?
                 AND controller_owner_token = ?
                 AND controller_lease_generation = ?""",
            (
                clean_run_id,
                clean_project_id,
                clean_root_session_id,
                clean_owner_token,
                clean_generation,
            ),
        )
        await db.commit()
        return bool(getattr(cursor, "rowcount", 0) or 0)

    async def settle_stale_delegation_run_claims_for_controller(
        self,
        run_id: str,
        *,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        adopt_released_task_ids: set[str] | None = None,
    ) -> int:
        """Settle and release claims left by the preceding controller.

        This runs after the lease CAS but before the new dispatcher starts.
        Every work-item UPDATE is fenced by the winning owner+generation and
        by the exact metadata/claim snapshot, so two takeover contenders can
        neither double-settle an attempt nor clear a newer owner's claim.
        """

        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        released_task_ids = tuple(
            sorted(
                {
                    str(task_id or "").strip()
                    for task_id in set(adopt_released_task_ids or set())
                    if str(task_id or "").strip()
                }
            )
        )
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        settled = 0
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=clean_run_id,
                project_id=clean_project_id,
                owner_token=clean_owner_token,
                generation=clean_generation,
                checked_at=checked_at,
                reject_dispatch_hold=False,
            )
            released_task_clause = ""
            candidate_params: list[Any] = [clean_run_id]
            if released_task_ids:
                placeholders = ", ".join("?" for _ in released_task_ids)
                released_task_clause = f"""
                          OR work_item_id IN (
                              SELECT work_item_id
                              FROM work_item_runtime_links
                              WHERE runtime_task_id IN ({placeholders})
                          )"""
                candidate_params.extend(released_task_ids)
            async with transaction_db.execute(
                f"""SELECT work_item_id, claimed_by_role_runtime_session_id,
                           claimed_by_seat_id, metadata, phase, projection_id
                    FROM delegation_work_items
                    WHERE run_id = ?
                      AND (COALESCE(claimed_by_role_runtime_session_id, '') != ''
                           OR COALESCE(claimed_by_seat_id, '') != ''
                           {released_task_clause})""",
                tuple(candidate_params),
            ) as cursor:
                rows = await cursor.fetchall()
            now = checked_at.isoformat()
            stale_work_item_ids: list[str] = []
            for (
                work_item_id,
                role_claim,
                seat_claim,
                metadata_json,
                work_item_phase,
                work_item_projection_id,
            ) in rows:
                metadata = _json_loads(metadata_json, {})
                prior_metadata = dict(metadata)
                attempt_seq = int(metadata.get("attempt_seq", 0) or 0)
                if attempt_seq > 0 and not bool(metadata.get("attempt_settled", True)):
                    metadata["attempt_settled"] = True
                    metadata["attempt_outcome"] = "interrupted"
                    metadata["attempt_settled_at"] = now
                    metadata["attempt_interrupted_streak"] = int(
                        metadata.get("attempt_interrupted_streak", 0) or 0
                    ) + 1
                metadata["claimed_by_role_session_id"] = ""
                metadata["claimed_task_id"] = ""
                metadata["controller_takeover_released_at"] = now
                metadata["company_run_controller_owner_token"] = clean_owner_token
                metadata["company_run_controller_lease_generation"] = clean_generation
                update = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '',
                           metadata = ?,
                           updated_at = ?
                       WHERE work_item_id = ?
                         AND run_id = ?
                         AND claimed_by_role_runtime_session_id = ?
                         AND claimed_by_seat_id = ?
                         AND metadata = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs
                             WHERE run_id = ? AND project_id = ? AND session_id = ?
                               AND controller_owner_token = ?
                               AND controller_lease_generation = ?
                               AND controller_lease_expires_at > ?
                         )""",
                    (
                        _json_dumps(metadata),
                        now,
                        work_item_id,
                        clean_run_id,
                        str(role_claim or ""),
                        str(seat_claim or ""),
                        str(metadata_json or ""),
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        now,
                    ),
                )
                applied = int(getattr(update, "rowcount", 0) or 0)
                settled += applied
                if applied:
                    clean_work_item_id = str(work_item_id or "").strip()
                    stale_work_item_ids.append(clean_work_item_id)
                    # WorkItem and linked Task form one attempt credential.
                    # A takeover used to stamp only the WorkItem, leaving a
                    # settled delivery/approved child as Task(gen N) versus
                    # WorkItem(gen N+1).  Startup requeue and deterministic
                    # multi-target rework then correctly rejected that mixed
                    # envelope forever.  Verify the old pair exactly and adopt
                    # the Task in this same takeover transaction, preserving
                    # every non-controller Task field.
                    async with transaction_db.execute(
                        """SELECT runtime_task_id, link_kind
                           FROM work_item_runtime_links
                           WHERE work_item_id = ?""",
                        (clean_work_item_id,),
                    ) as cursor:
                        linked_task_links = await cursor.fetchall()
                    if len(linked_task_links) > 1:
                        raise RuntimeError(
                            "controller takeover found multiple linked Tasks "
                            f"for {clean_work_item_id!r}"
                        )
                    if linked_task_links:
                        linked_task_id = str(
                            linked_task_links[0][0] or ""
                        ).strip()
                        linked_task_kind = str(
                            linked_task_links[0][1] or ""
                        ).strip()
                        async with transaction_db.execute(
                            """SELECT work_item_id
                               FROM work_item_runtime_links
                               WHERE runtime_task_id = ?""",
                            (linked_task_id,),
                        ) as cursor:
                            reverse_task_links = await cursor.fetchall()
                        if (
                            len(reverse_task_links) != 1
                            or str(reverse_task_links[0][0] or "").strip()
                            != clean_work_item_id
                        ):
                            raise RuntimeError(
                                "controller takeover found a non-bijective "
                                f"WorkItem/Task link for {clean_work_item_id!r}"
                            )
                        async with transaction_db.execute(
                            """SELECT id, project_id, status, metadata
                               FROM tasks
                               WHERE id = ?""",
                            (linked_task_id,),
                        ) as cursor:
                            linked_task_rows = await cursor.fetchall()
                        if len(linked_task_rows) != 1:
                            raise RuntimeError(
                                "controller takeover found a missing or "
                                f"ambiguous linked Task for {clean_work_item_id!r}"
                            )
                        linked_task_row = linked_task_rows[0]
                        linked_task_project_id = str(
                            linked_task_row[1] or "default"
                        ).strip() or "default"
                        linked_task_status = str(linked_task_row[2] or "").strip()
                        linked_task_metadata_json = str(
                            linked_task_row[3] or "{}"
                        )
                        linked_task_metadata = _json_loads(
                            linked_task_metadata_json,
                            {},
                        )
                        credential_numbers_valid = True
                        try:
                            linked_task_attempt = int(
                                linked_task_metadata.get(
                                    "claimed_work_item_attempt_seq", 0
                                )
                                or 0
                            )
                            prior_work_item_generation = int(
                                prior_metadata.get(
                                    "company_run_controller_lease_generation",
                                    0,
                                )
                                or 0
                            )
                            linked_task_generation = int(
                                linked_task_metadata.get(
                                    "company_run_controller_lease_generation",
                                    0,
                                )
                                or 0
                            )
                        except (TypeError, ValueError):
                            credential_numbers_valid = False
                            linked_task_attempt = 0
                            prior_work_item_generation = 0
                            linked_task_generation = 0
                        prior_work_item_owner = str(
                            prior_metadata.get(
                                "company_run_controller_owner_token", ""
                            )
                            or ""
                        ).strip()
                        linked_task_owner = str(
                            linked_task_metadata.get(
                                "company_run_controller_owner_token", ""
                            )
                            or ""
                        ).strip()
                        claimed_task_id = str(
                            prior_metadata.get("claimed_task_id", "") or ""
                        ).strip()
                        released_target_identity_matches = bool(
                            linked_task_id in released_task_ids
                            and not str(role_claim or "").strip()
                            and not str(seat_claim or "").strip()
                            and claimed_task_id in {"", linked_task_id}
                        )
                        explicit_work_item_projection_id = str(
                            work_item_projection_id or ""
                        ).strip()
                        metadata_work_item_projection_id = (
                            work_item_projection_id_from_metadata(
                                prior_metadata,
                                fallback=explicit_work_item_projection_id,
                            )
                        )
                        linked_task_projection_id = (
                            work_item_projection_id_from_metadata(
                                linked_task_metadata,
                                fallback="",
                            )
                        )
                        try:
                            prior_phase = coerce_phase(work_item_phase)
                        except (TypeError, ValueError):
                            prior_phase = None
                        expected_linked_task_status = (
                            task_status_for_phase(prior_phase).value
                            if prior_phase is not None
                            else ""
                        )
                        legacy_work_item_attempt = bool(
                            (
                                "attempt_seq" not in prior_metadata
                                and attempt_seq == 0
                            )
                            or (
                                attempt_seq > 0
                                and prior_metadata.get("attempt_settled") is True
                            )
                        )
                        # Pre-controller linked rows have no controller
                        # credential on either side and no Task attempt
                        # credential.  Later legacy versions may have a
                        # settled WorkItem-local attempt ledger, but they are
                        # still not a modern mixed envelope: old runtimes
                        # persisted the claim and primary link, then
                        # terminalized the WorkItem/Task without controller
                        # owner/generation fields.
                        # Under the winning run lease it is safe to release
                        # that exact terminal claim, but it is *not* safe to
                        # invent a Task attempt.  A later genuine rework claim
                        # will create the next attempt before the fenced claim
                        # path installs the complete Task credential envelope.
                        fully_legacy_linked_terminal = bool(
                            credential_numbers_valid
                            and legacy_work_item_attempt
                            and "company_run_controller_owner_token"
                            not in prior_metadata
                            and "company_run_controller_lease_generation"
                            not in prior_metadata
                            and "claimed_work_item_attempt_seq"
                            not in linked_task_metadata
                            and "company_run_controller_owner_token"
                            not in linked_task_metadata
                            and "company_run_controller_lease_generation"
                            not in linked_task_metadata
                            and linked_task_attempt == 0
                            and prior_work_item_generation == 0
                            and linked_task_generation == 0
                            and not prior_work_item_owner
                            and not linked_task_owner
                            and is_work_item_runtime_metadata(
                                linked_task_metadata
                            )
                            and linked_task_project_id == clean_project_id
                            and str(
                                linked_task_metadata.get(
                                    "delegation_run_id", ""
                                )
                                or ""
                            ).strip()
                            == clean_run_id
                            and linked_task_kind == "primary"
                            and (
                                claimed_task_id == linked_task_id
                                or released_target_identity_matches
                            )
                            and bool(explicit_work_item_projection_id)
                            and metadata_work_item_projection_id
                            == explicit_work_item_projection_id
                            and linked_task_projection_id
                            == explicit_work_item_projection_id
                            and prior_phase in DONE_PHASES
                            and linked_task_status
                            == expected_linked_task_status
                        )
                        if fully_legacy_linked_terminal:
                            continue
                        # A settled WorkItem may legitimately retain its
                        # completed attempt ledger while controller release
                        # parks the linked Task without an attempt credential.
                        # This includes a terminal card and a deterministic
                        # rework card already moved back to READY.  It is not
                        # a partial credential: all three Task credential keys
                        # must be absent, and either the WorkItem attempt is
                        # settled or it retains a complete in-progress
                        # role+seat+Task claim from graceful cancellation.  The
                        # primary link, projection, phase, status, and claim
                        # identity must all agree.  Under the winning run lease
                        # we can safely adopt that complete projection.
                        fully_released_modern_linked_projection = bool(
                            credential_numbers_valid
                            and attempt_seq > 0
                            and (
                                prior_metadata.get("attempt_settled") is True
                                or (
                                    prior_metadata.get("attempt_settled")
                                    is False
                                    and bool(str(role_claim or "").strip())
                                    and bool(str(seat_claim or "").strip())
                                    and claimed_task_id == linked_task_id
                                    and prior_phase in IN_PROGRESS_PHASES
                                )
                            )
                            and bool(prior_work_item_owner)
                            and prior_work_item_generation > 0
                            and "claimed_work_item_attempt_seq"
                            not in linked_task_metadata
                            and "company_run_controller_owner_token"
                            not in linked_task_metadata
                            and "company_run_controller_lease_generation"
                            not in linked_task_metadata
                            and linked_task_attempt == 0
                            and not linked_task_owner
                            and linked_task_generation == 0
                            and is_work_item_runtime_metadata(
                                linked_task_metadata
                            )
                            and linked_task_project_id == clean_project_id
                            and str(
                                linked_task_metadata.get(
                                    "delegation_run_id", ""
                                )
                                or ""
                            ).strip()
                            == clean_run_id
                            and linked_task_kind == "primary"
                            and (
                                claimed_task_id == linked_task_id
                                or released_target_identity_matches
                            )
                            and bool(explicit_work_item_projection_id)
                            and metadata_work_item_projection_id
                            == explicit_work_item_projection_id
                            and linked_task_projection_id
                            == explicit_work_item_projection_id
                            and prior_phase is not None
                            and linked_task_status
                            == expected_linked_task_status
                        )
                        if (
                            not linked_task_id
                            or linked_task_project_id != clean_project_id
                            or str(
                                linked_task_metadata.get(
                                    "delegation_run_id", ""
                                )
                                or ""
                            ).strip()
                            != clean_run_id
                            or attempt_seq <= 0
                            or linked_task_attempt != attempt_seq
                            or not prior_work_item_owner
                            or linked_task_owner != prior_work_item_owner
                            or prior_work_item_generation <= 0
                            or linked_task_generation
                            != prior_work_item_generation
                        ) and not fully_released_modern_linked_projection:
                            raise RuntimeError(
                                "controller takeover found a mixed linked "
                                f"Task/WorkItem attempt envelope for "
                                f"{clean_work_item_id!r}"
                            )
                        linked_task_metadata[
                            "claimed_work_item_attempt_seq"
                        ] = attempt_seq
                        linked_task_metadata[
                            "company_run_controller_owner_token"
                        ] = clean_owner_token
                        linked_task_metadata[
                            "company_run_controller_lease_generation"
                        ] = clean_generation
                        task_update = await transaction_db.execute(
                            """UPDATE tasks
                               SET metadata = ?
                               WHERE id = ? AND project_id = ?
                                 AND metadata = ?
                                 AND EXISTS (
                                     SELECT 1 FROM delegation_runs
                                     WHERE run_id = ? AND project_id = ?
                                       AND session_id = ?
                                       AND controller_owner_token = ?
                                       AND controller_lease_generation = ?
                                       AND controller_lease_expires_at > ?
                                 )""",
                            (
                                _json_dumps(linked_task_metadata),
                                linked_task_id,
                                clean_project_id,
                                linked_task_metadata_json,
                                clean_run_id,
                                clean_project_id,
                                clean_root_session_id,
                                clean_owner_token,
                                clean_generation,
                                now,
                            ),
                        )
                        if int(
                            getattr(task_update, "rowcount", 0) or 0
                        ) != 1:
                            raise RuntimeError(
                                "controller takeover lost its linked Task CAS"
                            )

            # A controller can disappear while an internal native turn is
            # between its Task RUNNING commit and its terminal commit.  These
            # auxiliary rows are not WorkItems, so claim settlement alone
            # cannot reach them.  The takeover winner terminalizes only prior
            # generations under its live lease; a stale coroutine then fails
            # its typed save fence and cannot resurrect the row.
            live_auxiliary_statuses = (
                TaskStatus.PENDING.value,
                TaskStatus.RUNNING.value,
                TaskStatus.IDLE.value,
                TaskStatus.BLOCKED.value,
                TaskStatus.AWAITING_PEER.value,
                TaskStatus.AWAITING_MANAGER_REVIEW.value,
                TaskStatus.AWAITING_HUMAN.value,
                TaskStatus.AWAITING_REVIEW.value,
            )
            auxiliary_status_placeholders = ", ".join(
                "?" for _ in live_auxiliary_statuses
            )
            takeover_lease_exists = """EXISTS (
                SELECT 1 FROM delegation_runs AS live_run
                WHERE live_run.run_id = ? AND live_run.project_id = ?
                  AND live_run.session_id = ?
                  AND live_run.controller_owner_token = ?
                  AND live_run.controller_lease_generation = ?
                  AND live_run.controller_lease_expires_at > ?
            )"""
            await transaction_db.execute(
                f"""UPDATE runtime_sessions
                    SET status = 'failed',
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.status', 'failed',
                            '$.runtime_auxiliary_terminal_reason',
                            'controller_takeover',
                            '$.runtime_auxiliary_terminalized_at', ?
                        ),
                        updated_at = ?
                    WHERE project_id = ?
                      AND status IN ('running', 'starting', 'working',
                                     'awaiting_human', 'awaiting_review',
                                     'awaiting_peer')
                      AND task_id IN (
                          SELECT id FROM tasks
                          WHERE project_id = ?
                            AND json_extract(
                                  metadata,
                                  '$.delegation_run_id'
                                ) = ?
                            AND json_extract(
                                  metadata,
                                  '$.company_runtime_auxiliary_task'
                                ) = 1
                            AND CAST(
                                  COALESCE(
                                    json_extract(
                                      metadata,
                                      '$.company_run_controller_lease_generation'
                                    ), 0
                                  ) AS INTEGER
                                ) != ?
                      )
                      AND {takeover_lease_exists}""",
                (
                    now,
                    now,
                    clean_project_id,
                    clean_project_id,
                    clean_run_id,
                    clean_generation,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                ),
            )
            await transaction_db.execute(
                f"""UPDATE tasks
                    SET status = ?, execution_lock = 0,
                        execution_locked_at = NULL,
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.runtime_auxiliary_terminal_reason',
                            'controller_takeover',
                            '$.runtime_auxiliary_terminalized_at', ?
                        )
                    WHERE project_id = ?
                      AND json_extract(metadata, '$.delegation_run_id') = ?
                      AND json_extract(
                            metadata,
                            '$.company_runtime_auxiliary_task'
                          ) = 1
                      AND CAST(
                            COALESCE(
                              json_extract(
                                metadata,
                                '$.company_run_controller_lease_generation'
                              ), 0
                            ) AS INTEGER
                          ) != ?
                      AND status IN ({auxiliary_status_placeholders})
                      AND {takeover_lease_exists}""",
                (
                    TaskStatus.CANCELLED.value,
                    now,
                    clean_project_id,
                    clean_run_id,
                    clean_generation,
                    *live_auxiliary_statuses,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                ),
            )

            # Scheduler focus, seat residency, and serialized member runtime
            # are claim projections.  Transfer their fencing credential to
            # the winner in this same transaction, and clear only focus owned
            # by the attempts that were just settled.
            focus_predicate = "status = 'running'"
            focus_params: list[Any] = []
            if stale_work_item_ids:
                placeholders = ", ".join("?" for _ in stale_work_item_ids)
                focus_predicate += f" OR focused_work_item_id IN ({placeholders})"
                focus_params.extend(stale_work_item_ids)
            lease_exists = """EXISTS (
                SELECT 1 FROM delegation_runs
                WHERE run_id = ? AND project_id = ? AND session_id = ?
                  AND controller_owner_token = ?
                  AND controller_lease_generation = ?
                  AND controller_lease_expires_at > ?
            )"""
            for table in ("role_runtime_sessions", "delegation_role_sessions"):
                await transaction_db.execute(
                    f"""UPDATE {table}
                        SET focused_work_item_id = CASE
                                WHEN {focus_predicate} THEN ''
                                ELSE focused_work_item_id END,
                            current_work_item = CASE
                                WHEN {focus_predicate} THEN '{{}}'
                                ELSE current_work_item END,
                            status = CASE
                                WHEN {focus_predicate} THEN 'idle'
                                ELSE status END,
                            metadata = json_set(
                                COALESCE(NULLIF(metadata, ''), '{{}}'),
                                '$.company_run_id', ?,
                                '$.company_run_controller_owner_token', ?,
                                '$.company_run_controller_lease_generation', ?
                            ),
                            updated_at = ?
                        WHERE run_id = ? AND {lease_exists}""",
                    (
                        *focus_params,
                        *focus_params,
                        *focus_params,
                        clean_run_id,
                        clean_owner_token,
                        clean_generation,
                        now,
                        clean_run_id,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        now,
                    ),
                )

            seat_focus_predicate = "status = 'running'"
            seat_focus_params: list[Any] = []
            if stale_work_item_ids:
                placeholders = ", ".join("?" for _ in stale_work_item_ids)
                seat_focus_predicate += f" OR current_work_item_id IN ({placeholders})"
                seat_focus_params.extend(stale_work_item_ids)
            await transaction_db.execute(
                f"""UPDATE seat_states
                    SET status = CASE
                            WHEN {seat_focus_predicate} THEN 'idle' ELSE status END,
                        resident_status = CASE
                            WHEN {seat_focus_predicate} THEN 'idle'
                            ELSE resident_status END,
                        current_task_id = CASE
                            WHEN {seat_focus_predicate} THEN ''
                            ELSE current_task_id END,
                        current_work_item_id = CASE
                            WHEN {seat_focus_predicate} THEN ''
                            ELSE current_work_item_id END,
                        current_work_item = CASE
                            WHEN {seat_focus_predicate} THEN '{{}}'
                            ELSE current_work_item END,
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.company_run_id', ?,
                            '$.company_run_controller_owner_token', ?,
                            '$.company_run_controller_lease_generation', ?
                        ),
                        updated_at = ?
                    WHERE run_id = ? AND {lease_exists}""",
                (
                    *seat_focus_params,
                    *seat_focus_params,
                    *seat_focus_params,
                    *seat_focus_params,
                    *seat_focus_params,
                    clean_run_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                    clean_run_id,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                ),
            )
            await transaction_db.execute(
                f"""UPDATE runtime_sessions
                    SET status = CASE WHEN status = 'running' THEN 'idle' ELSE status END,
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.company_run_id', ?,
                            '$.company_run_controller_owner_token', ?,
                            '$.company_run_controller_lease_generation', ?,
                            '$.status', CASE WHEN status = 'running' THEN 'idle'
                                             ELSE json_extract(metadata, '$.status') END,
                            '$.resident_status', CASE WHEN status = 'running' THEN 'idle'
                                                      ELSE json_extract(metadata, '$.resident_status') END,
                            '$.focused_work_item_id', CASE WHEN status = 'running' THEN ''
                                                           ELSE json_extract(metadata, '$.focused_work_item_id') END,
                            '$.current_task_id', CASE WHEN status = 'running' THEN ''
                                                     ELSE json_extract(metadata, '$.current_task_id') END
                        ),
                        updated_at = ?
                    WHERE project_id = ?
                      AND (
                          json_extract(metadata, '$.company_run_id') = ?
                          OR task_id IN (
                              SELECT id FROM tasks
                              WHERE project_id = ?
                                AND json_extract(metadata, '$.delegation_run_id') = ?
                          )
                      )
                      AND {lease_exists}""",
                (
                    clean_run_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                    clean_project_id,
                    clean_run_id,
                    clean_project_id,
                    clean_run_id,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                ),
            )
            await transaction_db.execute(
                f"""UPDATE external_sessions
                    SET status = CASE
                            WHEN status IN ('starting', 'running', 'working')
                            THEN 'suspended' ELSE status END,
                        metadata = json_set(
                            COALESCE(NULLIF(metadata, ''), '{{}}'),
                            '$.company_run_id', ?,
                            '$.company_run_controller_owner_token', ?,
                            '$.company_run_controller_lease_generation', ?
                        ),
                        updated_at = ?
                    WHERE project_id = ?
                      AND (
                          json_extract(metadata, '$.company_run_id') = ?
                          OR task_id IN (
                              SELECT id FROM tasks
                              WHERE project_id = ?
                                AND json_extract(metadata, '$.delegation_run_id') = ?
                          )
                      )
                      AND {lease_exists}""",
                (
                    clean_run_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                    clean_project_id,
                    clean_run_id,
                    clean_project_id,
                    clean_run_id,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    now,
                ),
            )
            await transaction_db.commit()
            return settled
        except CompanyRunControllerLeaseLost:
            await transaction_db.rollback()
            return 0
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def list_delegation_runs(
        self,
        *,
        project_id: str | None = None,
        status: str | None = None,
        lifecycle_status: str | None = None,
        session_id: str | None = None,
    ) -> list[DelegationRun]:
        db = self._require_db()
        query = "SELECT * FROM delegation_runs WHERE 1=1"
        params: list[Any] = []
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        if status:
            query += " AND status = ?"
            params.append(status)
        if lifecycle_status:
            query += " AND lifecycle_status = ?"
            params.append(lifecycle_status)
        if session_id:
            query += " AND session_id = ?"
            params.append(session_id)
        query += " ORDER BY updated_at DESC"
        async with db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_delegation_run(row, cursor.description) for row in rows]

    async def list_open_delegation_runs(
        self,
        *,
        project_id: str | None = None,
    ) -> list[DelegationRun]:
        db = self._require_db()
        open_states = ("active", "paused", "blocked", "awaiting_owner", "deliverable")
        query = (
            "SELECT * FROM delegation_runs WHERE lifecycle_status IN (?, ?, ?, ?, ?)"
        )
        params: list[Any] = list(open_states)
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        query += " ORDER BY updated_at DESC"
        async with db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_delegation_run(row, cursor.description) for row in rows]

    async def get_latest_delegation_run(
        self,
        project_id: str,
        *,
        include_session_id: str | None = None,
    ) -> DelegationRun | None:
        runs = await self.list_delegation_runs(project_id=project_id)
        for run in runs:
            if include_session_id and run.session_id == include_session_id:
                continue
            return run
        return None

    def _row_to_delegation_cell(self, row: Any, description: Any) -> DelegationCell:
        cols = [d[0] for d in description]
        data = dict(zip(cols, row))
        return DelegationCell(
            cell_id=data["cell_id"],
            run_id=data["run_id"],
            manager_role_id=data.get("manager_role_id") or "",
            member_role_ids=_json_loads(data.get("member_role_ids"), []),
            status=data.get("status") or "idle",
            metadata=_json_loads(data.get("metadata"), {}),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
        )

    async def save_delegation_cell(self, cell: DelegationCell) -> None:
        db = self._require_db()
        await db.execute(
            """INSERT OR REPLACE INTO delegation_cells
            (cell_id, run_id, manager_role_id, member_role_ids, status, metadata, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                cell.cell_id,
                cell.run_id,
                cell.manager_role_id,
                _json_dumps(cell.member_role_ids),
                cell.status,
                _json_dumps(cell.metadata),
                cell.created_at.isoformat(),
                cell.updated_at.isoformat(),
            ),
        )
        await db.commit()

    async def list_delegation_cells(self, run_id: str) -> list[DelegationCell]:
        db = self._require_db()
        async with db.execute(
            "SELECT * FROM delegation_cells WHERE run_id = ? ORDER BY created_at ASC",
            (run_id,),
        ) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_delegation_cell(row, cursor.description) for row in rows]

    def _row_to_delegation_work_item(self, row: Any, description: Any) -> DelegationWorkItem:
        cols = [d[0] for d in description]
        data = dict(zip(cols, row))
        return DelegationWorkItem(
            work_item_id=data["work_item_id"],
            run_id=data["run_id"],
            cell_id=data["cell_id"],
            team_instance_id=data.get("team_instance_id") or "",
            team_id=data.get("team_id") or "",
            role_id=data.get("role_id") or "",
            seat_id=data.get("seat_id") or "",
            seat_state_id=data.get("seat_state_id") or "",
            role_runtime_session_id=data.get("role_runtime_session_id") or "",
            parent_work_item_id=data.get("parent_work_item_id"),
            source_role_id=data.get("source_role_id"),
            source_seat_id=data.get("source_seat_id"),
            title=data.get("title") or "",
            summary=data.get("summary") or "",
            kind=data.get("kind") or "execute",
            projection_id=data.get("projection_id") or "",
            phase=coerce_phase(data.get("phase") or "ready"),
            batch_id=data.get("batch_id") or "",
            batch_index=int(data.get("batch_index") or 0),
            deliverable_summary=data.get("deliverable_summary") or "",
            blocked_reason=data.get("blocked_reason") or "",
            handoff_status=data.get("handoff_status") or "pending",
            continuation_source=data.get("continuation_source") or "",
            manager_role_id=data.get("manager_role_id") or "",
            manager_seat_id=data.get("manager_seat_id") or "",
            claimed_by_role_runtime_session_id=data.get("claimed_by_role_runtime_session_id") or "",
            claimed_by_seat_id=data.get("claimed_by_seat_id") or "",
            metadata=_json_loads(data.get("metadata"), {}),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
        )

    async def _sweep_stale_claims(self) -> int:
        """Crash-recovery sweep for claims without a live run controller.

        Process restart drops every in-memory runtime session, but the
        persistent ``claimed_by_*`` fields on the work items still point to
        those dead session IDs.  A second controller can also open the same
        DB while the first process is healthy, however, so process startup is
        not proof that claims are stale.  The durable run lease is the sole
        liveness fact: its predicate is repeated in each UPDATE so a heartbeat
        that wins after this scan cannot have its claims stolen.

        We only touch in-flight phases (RUNNING / WAITING_FOR_* /
        PAUSED / NEEDS_ATTENTION / AWAITING_*) so we never disturb
        terminal cards. The phase itself is left alone; the sweep only
        clears the claim. Active execution can subsequently be re-picked;
        passive AWAITING_* parents remain non-dispatchable while their
        report/review chain (or human) advances them.
        """
        if self._db is None:
            return 0
        async with self._db.execute(
            """SELECT work_item_id, phase
               FROM delegation_work_items
               WHERE claimed_by_role_runtime_session_id != ''
                  OR claimed_by_seat_id != ''"""
        ) as cursor:
            rows = await cursor.fetchall()
        cleared = 0
        swept_at = datetime.now().isoformat()
        for work_item_id, phase_str in rows:
            try:
                phase = coerce_phase(phase_str)
            except (TypeError, ValueError):
                continue
            # Runnable phases are covered too: the phase-write invariant
            # keeps READY / READY_FOR_REWORK rows unowned, so any claim
            # found on one is corrupt legacy state that would starve the
            # claim CAS forever.
            if not (is_stale_claim_releasable(phase) or is_runnable(phase)):
                continue
            cursor = await self._db.execute(
                """UPDATE delegation_work_items
                   SET claimed_by_role_runtime_session_id='',
                       claimed_by_seat_id='',
                       metadata=json_set(
                           COALESCE(NULLIF(metadata, ''), '{}'),
                           '$.claimed_by_role_session_id', '',
                           '$.claimed_task_id', '',
                           '$.claim_swept_at', ?
                       ),
                       updated_at=?
                   WHERE work_item_id=?
                     AND (COALESCE(claimed_by_role_runtime_session_id, '') != ''
                          OR COALESCE(claimed_by_seat_id, '') != '')
                     AND NOT EXISTS (
                         SELECT 1 FROM delegation_runs
                         WHERE delegation_runs.run_id = delegation_work_items.run_id
                           AND COALESCE(controller_owner_token, '') != ''
                           AND controller_lease_expires_at > ?
                     )""",
                (swept_at, swept_at, work_item_id, swept_at),
            )
            cleared += int(getattr(cursor, "rowcount", 0) or 0)
        if cleared:
            await self._db.commit()
            logger.info(
                f"stale-claim sweep: released {cleared} in-flight work item claims on startup"
            )
        return cleared

    # ── Fix 5 PR2: rich field-level merge by (run_id, role_id) ──────────

    async def _migrate_role_sessions_merge_by_role(self) -> dict[str, int]:
        """Collapse every ``(run_id, role_id)`` group into a single canonical
        row, merging state field-by-field so inbox / memory / adapter
        session tokens survive the collapse.

        Design (see Fix 5 PR2 plan):

        Target PK       ``role-runtime::{run_id}::{role_id}`` (3-segment).
        Groups          every (run_id, role_id) with ≥1 row. A size-1 group
                        whose PK already equals the canonical form is
                        skipped (noop — common case after migration).
        Merge rules     inbox_state, memory_slices_by_work_item, and the
                        list-of-ids columns (background_work_item_ids,
                        manager_role_ids, manager_seat_ids, seat_ids) are
                        UNIONED across all rows. Scalar state columns
                        (focused_work_item_id, status, resume_state,
                        current_work_item, latest_notification,
                        manager_digest, adapter_session_state, team_*,
                        seat_id, seat_state_id) are taken from the
                        "active" row — the one with a populated focus and
                        the highest status priority, tiebroken by
                        updated_at. ``adapter_session_state`` is the
                        externally-observable LLM / codex session token:
                        losing rows' states are retained under
                        ``metadata.adapter_session_state_audit`` so the
                        old codex sessions can be recovered for debugging.
        References      foreign references in delegation_work_items
                        (role_runtime_session_id,
                        claimed_by_role_runtime_session_id), seat_states,
                        and JSON metadata (tasks.metadata.delegation_role_
                        session_id, delegation_work_items.metadata.
                        assigned_role_runtime_id) are all redirected to
                        the canonical PK before losers are deleted.
        Idempotent      re-running the migration is a noop (every row is
                        already canonical).

        Returns counters for observability / tests.
        """
        # Deferred import — the company_runtime module transitively imports
        # layer2 phase machinery, which we also use; importing at module
        # scope would create a cycle during initial bootstrap.
        from opc.layer2_organization.company_runtime import canonical_role_session_id

        if self._db is None:
            return {
                "groups": 0,
                "canonical_written": 0,
                "deleted": 0,
                "refs_updated": 0,
            }

        stats = {
            "groups": 0,
            "canonical_written": 0,
            "deleted": 0,
            "refs_updated": 0,
        }

        # Collect every (run_id, role_id) with any rows — unlike the old
        # "duplicate" migration, this pass also catches single legacy rows
        # whose PK is not the 3-segment canonical form.
        async with self._db.execute(
            """SELECT DISTINCT run_id, role_id
               FROM role_runtime_sessions
               WHERE run_id != '' AND role_id != ''"""
        ) as cursor:
            groups = await cursor.fetchall()

        if not groups:
            return stats

        for run_id, role_id in groups:
            try:
                canonical_id = canonical_role_session_id(
                    run_id=str(run_id), role_id=str(role_id)
                )
            except ValueError:
                logger.warning(
                    f"role-session merge: cannot build canonical ID for "
                    f"run={run_id} role={role_id}; skipping"
                )
                continue

            async with self._db.execute(
                """SELECT * FROM role_runtime_sessions
                   WHERE run_id=? AND role_id=?
                   ORDER BY updated_at DESC""",
                (str(run_id), str(role_id)),
            ) as cursor:
                rows = await cursor.fetchall()
                columns = [desc[0] for desc in cursor.description]

            if not rows:
                continue

            row_dicts = [dict(zip(columns, row)) for row in rows]

            # Fast path: single row already at canonical PK → nothing to do.
            if len(row_dicts) == 1 and row_dicts[0]["role_session_id"] == canonical_id:
                continue

            stats["groups"] += 1

            merged = self._merge_role_session_rows(
                rows=row_dicts, canonical_id=canonical_id
            )

            # Upsert the merged row under the canonical PK in both tables.
            for table in ("role_runtime_sessions", "delegation_role_sessions"):
                await self._upsert_role_session_row(table=table, row=merged)
            stats["canonical_written"] += 1

            # Redirect every foreign reference from any non-canonical PK
            # in the group to the canonical PK. We do this before deleting
            # the rows so a crash mid-migration leaves references resolvable.
            losers = [
                rd["role_session_id"]
                for rd in row_dicts
                if rd["role_session_id"] != canonical_id
            ]
            for loser_id in losers:
                refs = await self._redirect_role_session_references(
                    source_id=loser_id, target_id=canonical_id
                )
                stats["refs_updated"] += refs

            # Delete the orphaned rows from both tables.
            for loser_id in losers:
                for table in ("role_runtime_sessions", "delegation_role_sessions"):
                    await self._db.execute(
                        f"DELETE FROM {table} WHERE role_session_id=?",
                        (loser_id,),
                    )
                stats["deleted"] += 1

        await self._db.commit()
        if stats["groups"]:
            logger.info(
                "role-session merge: "
                f"groups={stats['groups']} "
                f"canonical_written={stats['canonical_written']} "
                f"deleted={stats['deleted']} "
                f"refs_updated={stats['refs_updated']}"
            )
        return stats

    @staticmethod
    def _status_priority(status: str) -> int:
        """Higher priority wins when merging scalar state."""
        return {
            "running": 3,
            "reserved": 2,
            "blocked": 2,
            "idle": 1,
            "cold": 0,
        }.get((status or "").strip().lower(), 1)

    @classmethod
    def _merge_role_session_rows(
        cls, *, rows: list[dict[str, Any]], canonical_id: str
    ) -> dict[str, Any]:
        """Field-level merge of N role_runtime_sessions rows → single canonical
        row. See ``_migrate_role_sessions_merge_by_role`` for the policy.
        Rows must all belong to the same (run_id, role_id)."""
        # Pick the "active" row for scalar fields — the one most likely to
        # reflect the live state of the role. Ordering: has_focus desc,
        # status_priority desc, updated_at desc.
        active = max(
            rows,
            key=lambda r: (
                1 if (r.get("focused_work_item_id") or "").strip() else 0,
                cls._status_priority(r.get("status") or ""),
                str(r.get("updated_at") or ""),
            ),
        )

        # Team instance: prefer any non-empty value across the group. Old
        # short-form rows had it blank; the long-form row carries the truth.
        team_instance_id = str(active.get("team_instance_id") or "").strip()
        if not team_instance_id:
            for r in rows:
                candidate = str(r.get("team_instance_id") or "").strip()
                if candidate:
                    team_instance_id = candidate
                    break

        # Inbox: union + de-dup by message id, then sort by timestamp.
        inbox_messages: list[dict[str, Any]] = []
        seen_msg_ids: set[str] = set()
        for r in rows:
            state = _json_loads(r.get("inbox_state") or "{}", {})
            for msg in list(state.get("messages", []) or []):
                if not isinstance(msg, dict):
                    continue
                mid = str(msg.get("message_id") or msg.get("id") or "").strip()
                # Preserve order for messages that have no ID (rare) — use
                # a synthetic marker so they don't all collide on "".
                key = mid or f"__noid__::{len(inbox_messages)}"
                if key in seen_msg_ids:
                    continue
                seen_msg_ids.add(key)
                inbox_messages.append(dict(msg))
        inbox_messages.sort(key=lambda m: str(m.get("timestamp") or m.get("created_at") or ""))
        # Preserve any non-messages keys from the active row's inbox_state.
        active_inbox = _json_loads(active.get("inbox_state") or "{}", {})
        active_inbox["messages"] = inbox_messages
        merged_inbox_state = active_inbox

        # Memory slices: union dict[work_item_id → list], merging lists per key.
        # Iterate oldest-first so older notes appear before newer ones in the
        # merged list (natural reading order; rows come in DESC so reverse).
        merged_memory: dict[str, list[Any]] = {}
        for r in reversed(rows):
            slices = _json_loads(r.get("memory_slices_by_work_item") or "{}", {})
            if not isinstance(slices, dict):
                continue
            for wid, items in slices.items():
                if not isinstance(items, list):
                    continue
                merged_memory.setdefault(str(wid), []).extend(items)
        # De-dup identical entries per work item (keep order).
        for wid, items in list(merged_memory.items()):
            seen: set[str] = set()
            deduped: list[Any] = []
            for entry in items:
                sig = _json_dumps(entry) if not isinstance(entry, str) else entry
                if sig in seen:
                    continue
                seen.add(sig)
                deduped.append(entry)
            merged_memory[wid] = deduped

        # List unions (order: active row's entries first, others appended).
        def _union_list(field: str) -> list[str]:
            merged: list[str] = []
            seen: set[str] = set()
            for r in [active] + [r for r in rows if r is not active]:
                raw = _json_loads(r.get(field) or "[]", [])
                for item in raw if isinstance(raw, list) else []:
                    normalized = str(item)
                    if normalized in seen:
                        continue
                    seen.add(normalized)
                    merged.append(normalized)
            return merged

        background_ids = _union_list("background_work_item_ids")
        manager_role_ids = _union_list("manager_role_ids")
        manager_seat_ids = _union_list("manager_seat_ids")
        seat_ids = _union_list("seat_ids")
        # Pending queue: preserve FIFO — active row's queue first (these
        # are the ones already committed to this role's runtime), then any
        # extras from siblings. De-dup but keep earliest occurrence.
        pending_ids = _union_list("pending_work_item_ids")

        # Adapter session state (codex / LLM resume token): active row
        # wins; every other row's state is retained as audit breadcrumbs.
        active_adapter = _json_loads(active.get("adapter_session_state") or "{}", {})
        adapter_audit: list[dict[str, Any]] = []
        for r in rows:
            if r is active:
                continue
            raw_state = r.get("adapter_session_state") or ""
            if not raw_state or raw_state in ("{}", "null"):
                continue
            adapter_audit.append(
                {
                    "source_role_session_id": str(r.get("role_session_id") or ""),
                    "updated_at": str(r.get("updated_at") or ""),
                    "adapter_session_state": _json_loads(raw_state, {}),
                }
            )

        # Base metadata: start from active row's metadata, then append the
        # adapter audit list (append, don't overwrite — a role that has
        # been merged multiple times retains its full trail).
        merged_metadata = _json_loads(active.get("metadata") or "{}", {})
        if not isinstance(merged_metadata, dict):
            merged_metadata = {}
        if adapter_audit:
            existing_audit = list(merged_metadata.get("adapter_session_state_audit", []) or [])
            existing_audit.extend(adapter_audit)
            merged_metadata["adapter_session_state_audit"] = existing_audit

        # team_instance_id history — diagnostic trail of which team contexts
        # this role has been seen in. Useful when debugging cross-team flows.
        prior_team_instances = [
            str(r.get("team_instance_id") or "").strip()
            for r in rows
            if str(r.get("team_instance_id") or "").strip()
        ]
        if prior_team_instances:
            existing_history = list(merged_metadata.get("team_instance_history", []) or [])
            existing_history.extend(prior_team_instances)
            # De-dup preserving order.
            dedup_history: list[str] = []
            seen_tid: set[str] = set()
            for tid in existing_history:
                if tid in seen_tid:
                    continue
                seen_tid.add(tid)
                dedup_history.append(tid)
            merged_metadata["team_instance_history"] = dedup_history

        # Preserve the oldest created_at across the group (role has been
        # around since the earliest row was written), use the most recent
        # updated_at (merged row reflects the latest activity).
        created_at = min(str(r.get("created_at") or "") for r in rows if r.get("created_at"))
        updated_at = max(str(r.get("updated_at") or "") for r in rows if r.get("updated_at"))
        if not updated_at:
            updated_at = datetime.now().isoformat()

        return {
            "role_session_id": canonical_id,
            "run_id": str(active.get("run_id") or ""),
            "project_id": str(active.get("project_id") or "default"),
            "team_instance_id": team_instance_id,
            "team_id": str(active.get("team_id") or ""),
            "role_id": str(active.get("role_id") or ""),
            "seat_id": str(active.get("seat_id") or ""),
            "seat_state_id": str(active.get("seat_state_id") or ""),
            "employee_id": str(active.get("employee_id") or ""),
            "focused_work_item_id": str(active.get("focused_work_item_id") or ""),
            "background_work_item_ids": _json_dumps(background_ids),
            "manager_role_ids": _json_dumps(manager_role_ids),
            "manager_seat_ids": _json_dumps(manager_seat_ids),
            "seat_ids": _json_dumps(seat_ids),
            "adapter_session_state": _json_dumps(active_adapter),
            "inbox_state": _json_dumps(merged_inbox_state),
            "memory_slices_by_work_item": _json_dumps(merged_memory),
            "resume_state": active.get("resume_state") or "{}",
            "current_work_item": active.get("current_work_item") or "{}",
            "latest_notification": active.get("latest_notification") or "{}",
            "manager_digest": active.get("manager_digest") or "{}",
            "status": normalize_role_runtime_status(
                active.get("status"),
                active.get("focused_work_item_id"),
            ),
            "pending_work_item_ids": _json_dumps(pending_ids),
            "metadata": _json_dumps(merged_metadata),
            "created_at": created_at or updated_at,
            "updated_at": updated_at,
        }

    async def _upsert_role_session_row(self, *, table: str, row: dict[str, Any]) -> None:
        """Write the merged row under its canonical PK. ``INSERT OR REPLACE``
        so an earlier migration pass (or a pre-existing canonical row) is
        overwritten with the merged state."""
        assert self._db is not None
        columns = [
            "role_session_id", "run_id", "project_id", "team_instance_id",
            "team_id", "role_id", "seat_id", "seat_state_id", "employee_id",
            "focused_work_item_id", "background_work_item_ids",
            "manager_role_ids", "manager_seat_ids", "seat_ids",
            "adapter_session_state", "inbox_state", "memory_slices_by_work_item",
            "resume_state", "current_work_item", "latest_notification",
            "manager_digest", "status", "pending_work_item_ids",
            "metadata", "created_at", "updated_at",
        ]
        placeholders = ", ".join("?" for _ in columns)
        await self._db.execute(
            f"INSERT OR REPLACE INTO {table} ({', '.join(columns)}) "
            f"VALUES ({placeholders})",
            tuple(row.get(c) for c in columns),
        )

    async def _redirect_role_session_references(
        self,
        *,
        source_id: str,
        target_id: str,
    ) -> int:
        """Rewrite every table/column that references ``source_id`` to
        ``target_id``. Returns the number of rows modified (for observability).

        Scope is intentionally explicit: we know which columns hold
        role_session_id references and update exactly those. JSON metadata
        columns (tasks.metadata, delegation_work_items.metadata) are
        rewritten with a targeted JSON-level replace that only touches the
        specific keys we control — we never blindly string-replace the
        JSON blob.
        """
        assert self._db is not None
        total = 0

        # delegation_work_items: two direct columns.
        cursor = await self._db.execute(
            """UPDATE delegation_work_items
               SET role_runtime_session_id=?,
                   updated_at=?
               WHERE role_runtime_session_id=?""",
            (target_id, datetime.now().isoformat(), source_id),
        )
        total += getattr(cursor, "rowcount", 0) or 0
        cursor = await self._db.execute(
            """UPDATE delegation_work_items
               SET claimed_by_role_runtime_session_id=?,
                   updated_at=?
               WHERE claimed_by_role_runtime_session_id=?""",
            (target_id, datetime.now().isoformat(), source_id),
        )
        total += getattr(cursor, "rowcount", 0) or 0

        # seat_states: single column.
        cursor = await self._db.execute(
            """UPDATE seat_states
               SET role_runtime_session_id=?,
                   updated_at=?
               WHERE role_runtime_session_id=?""",
            (target_id, datetime.now().isoformat(), source_id),
        )
        total += getattr(cursor, "rowcount", 0) or 0

        # JSON metadata references: load, rewrite keys, store.
        # delegation_work_items.metadata.assigned_role_runtime_id
        async with self._db.execute(
            """SELECT work_item_id, metadata FROM delegation_work_items
               WHERE metadata LIKE ?""",
            (f'%"{source_id}"%',),
        ) as cursor:
            wi_rows = await cursor.fetchall()
        for work_item_id, _metadata_json in wi_rows:
            def _redirect_work_item(
                meta: dict[str, Any],
            ) -> tuple[dict[str, Any], bool]:
                if str(meta.get("assigned_role_runtime_id", "")) != source_id:
                    return meta, False
                meta["assigned_role_runtime_id"] = target_id
                return meta, True

            total += int(await self._cas_transform_metadata_row(
                table="delegation_work_items",
                key_column="work_item_id",
                row_id=str(work_item_id),
                transform=_redirect_work_item,
                touch_updated_at=True,
            ))

        # tasks.metadata.delegation_role_session_id
        async with self._db.execute(
            """SELECT id, metadata FROM tasks
               WHERE metadata LIKE ?""",
            (f'%"{source_id}"%',),
        ) as cursor:
            task_rows = await cursor.fetchall()
        for task_id, _metadata_json in task_rows:
            def _redirect_task(meta: dict[str, Any]) -> tuple[dict[str, Any], bool]:
                if str(meta.get("delegation_role_session_id", "")) != source_id:
                    return meta, False
                meta["delegation_role_session_id"] = target_id
                return meta, True

            total += int(await self._cas_transform_metadata_row(
                table="tasks",
                key_column="id",
                row_id=str(task_id),
                transform=_redirect_task,
            ))

        return total

    async def save_delegation_work_item(
        self,
        item: DelegationWorkItem,
    ) -> None:
        await self._write_delegation_work_item(item, if_absent=False)

    async def upsert_company_attention_work_item_for_controller(
        self,
        candidate: DelegationWorkItem,
        *,
        project_id: str,
        controller_owner_token: str,
        controller_lease_generation: int,
        expected_role_session_focus: str,
    ) -> DelegationWorkItem | None:
        """Atomically create/revive one manager-attention wake under the run lease.

        Attention cards are a controller wake primitive, not ordinary work
        queued behind the manager's currently blocked parent.  The WorkItem,
        both durable role-session mirrors, and an existing linked Task are
        therefore updated in one ``BEGIN IMMEDIATE`` transaction.  Generic
        phase hooks run in notification-only mode after commit and can never
        infer controller authority from an untrusted candidate row.

        ``None`` is a same-generation focus/version conflict.  A stale or
        expired controller raises :class:`CompanyRunControllerLeaseLost` and
        leaves every row untouched.
        """

        self._require_db()
        item = copy.deepcopy(candidate)
        run_id = str(item.run_id or "").strip()
        role_session_id = str(item.role_runtime_session_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        owner_token = str(controller_owner_token or "").strip()
        generation = int(controller_lease_generation or 0)
        expected_focus = str(expected_role_session_focus or "").strip()
        item_metadata = dict(item.metadata or {})
        attention_key = str(item_metadata.get("attention_key", "") or "").strip()
        projection_id = str(item.projection_id or "").strip()
        turn_type = canonical_work_item_turn_type_for_kind(
            item.kind,
            fallback="",
        )
        if not (
            run_id
            and role_session_id
            and owner_token
            and generation > 0
            and attention_key
            and item_metadata.get("attention_work_item") is True
            and projection_id
            and turn_type
        ):
            raise CompanyRunControllerLeaseLost(
                "company attention upsert lacks an exact controller capability"
            )
        if item.phase not in {Phase.READY, Phase.RUNNING}:
            raise ValueError(
                "company attention candidate must request a runnable wake phase"
            )
        if str(item.parent_work_item_id or "").strip() != expected_focus:
            raise ValueError(
                "company attention parent must match the expected role-session focus"
            )
        item.metadata, _ = migrate_work_item_projection_metadata(
            item_metadata,
            projection_id_fallback=projection_id,
            turn_type_fallback=turn_type,
        )
        if (
            work_item_projection_id_from_metadata(
                item.metadata,
                fallback="",
            )
            != projection_id
            or work_item_turn_type_from_metadata(
                item.metadata,
                fallback="",
            )
            != turn_type
        ):
            raise ValueError(
                "company attention projection identity does not match its WorkItem"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        previous_phase: Phase | None = None
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now()
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=run_id,
                project_id=clean_project_id,
                owner_token=owner_token,
                generation=generation,
                checked_at=checked_at,
                role_runtime_session_id=role_session_id,
            )

            role_rows: dict[str, tuple[Any, ...]] = {}
            role_descriptions: dict[str, Any] = {}
            for table in ("role_runtime_sessions", "delegation_role_sessions"):
                async with transaction_db.execute(
                    f"""SELECT * FROM {table}
                        WHERE role_session_id = ?""",
                    (role_session_id,),
                ) as cursor:
                    row = await cursor.fetchone()
                    if row is not None:
                        role_rows[table] = row
                        role_descriptions[table] = cursor.description
            required_role_tables = {
                "role_runtime_sessions",
                "delegation_role_sessions",
            }
            if set(role_rows) != required_role_tables:
                raise RuntimeError(
                    "company attention wake requires both durable role-session mirrors"
                )
            for table, row in role_rows.items():
                role_session = self._row_to_role_runtime_session(
                    row,
                    role_descriptions[table],
                )
                durable_focus = str(
                    role_session.focused_work_item_id or ""
                ).strip()
                if (
                    str(role_session.run_id or "").strip() != run_id
                    or (str(role_session.project_id or "default").strip() or "default")
                    != clean_project_id
                    or durable_focus != expected_focus
                    or str(role_session.status or "").strip().lower()
                    not in {"blocked", "idle"}
                    or (
                        str(role_session.role_id or "").strip()
                        and str(item.role_id or "").strip()
                        and str(role_session.role_id or "").strip()
                        != str(item.role_id or "").strip()
                    )
                    or (
                        str(role_session.seat_id or "").strip()
                        and str(item.seat_id or "").strip()
                        and str(role_session.seat_id or "").strip()
                        != str(item.seat_id or "").strip()
                    )
                ):
                    await transaction_db.rollback()
                    return None

            async with transaction_db.execute(
                """SELECT * FROM delegation_work_items
                   WHERE run_id = ?
                     AND role_runtime_session_id = ?
                     AND json_extract(metadata, '$.attention_work_item') = 1
                     AND json_extract(metadata, '$.attention_key') = ?
                     AND phase NOT IN ('approved', 'failed', 'cancelled')
                   ORDER BY created_at ASC""",
                (run_id, role_session_id, attention_key),
            ) as cursor:
                attention_rows = await cursor.fetchall()
                attention_description = cursor.description
            if len(attention_rows) > 1:
                raise RuntimeError(
                    "multiple live attention WorkItems share one durable attention key"
                )

            if attention_rows:
                existing = self._row_to_delegation_work_item(
                    attention_rows[0],
                    attention_description,
                )
                previous_phase = existing.phase
                item = copy.deepcopy(existing)
                if existing.phase == Phase.PAUSED:
                    item.phase = Phase.RUNNING
                elif existing.phase in TODO_PHASES and existing.phase != Phase.READY:
                    item.phase = (
                        Phase.RUNNING
                        if existing.phase == Phase.READY_FOR_REWORK
                        else Phase.READY
                    )
                validate_transition(previous_phase, item.phase)
                item.summary = str(candidate.summary or existing.summary or "")
                item.metadata = {
                    **dict(existing.metadata or {}),
                    **dict(candidate.metadata or {}),
                }
                item.updated_at = checked_at
                self._protect_delegate_work_identity(item, existing=existing)
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, summary = ?, metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?
                         AND phase = ? AND updated_at = ?""",
                    (
                        item.phase.value,
                        item.summary,
                        _json_dumps(item.metadata),
                        checked_at.isoformat(),
                        item.work_item_id,
                        run_id,
                        previous_phase.value,
                        existing.updated_at.isoformat(),
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return None
            else:
                previous_phase = None
                if item.phase != Phase.READY:
                    raise ValueError(
                        "new company attention WorkItems must start READY"
                    )
                validate_transition(None, item.phase)
                self._protect_delegate_work_identity(item, existing=None)

            item.metadata = dict(item.metadata or {})
            item.metadata.update(
                {
                    "company_run_id": run_id,
                    "company_run_controller_owner_token": owner_token,
                    "company_run_controller_lease_generation": generation,
                }
            )
            item.metadata.pop("queued_behind_session", None)
            item.metadata, _ = migrate_work_item_projection_metadata(
                item.metadata,
                projection_id_fallback=str(
                    item.projection_id or item.work_item_id or ""
                ).strip(),
                turn_type_fallback=str(item.kind or "").strip(),
            )
            if (
                work_item_projection_id_from_metadata(
                    item.metadata,
                    fallback="",
                )
                != str(item.projection_id or "").strip()
                or work_item_turn_type_from_metadata(
                    item.metadata,
                    fallback="",
                )
                != canonical_work_item_turn_type_for_kind(
                    item.kind,
                    fallback="",
                )
            ):
                raise ValueError(
                    "persisted company attention projection identity is invalid"
                )
            item.updated_at = checked_at
            if previous_phase is None:
                cursor = await transaction_db.execute(
                    """INSERT INTO delegation_work_items
                       (work_item_id, run_id, cell_id, team_instance_id, team_id,
                        role_id, seat_id, seat_state_id, role_runtime_session_id,
                        parent_work_item_id, source_role_id, source_seat_id, title,
                        summary, kind, projection_id, phase, batch_id, batch_index,
                        deliverable_summary, blocked_reason, handoff_status,
                        continuation_source, manager_role_id, manager_seat_id,
                        claimed_by_role_runtime_session_id, claimed_by_seat_id,
                        metadata, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                               ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                       ON CONFLICT(work_item_id) DO NOTHING""",
                    self._delegation_work_item_insert_values(item),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return None
            else:
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET metadata = ?, updated_at = ?
                       WHERE work_item_id = ? AND run_id = ?""",
                    (
                        _json_dumps(item.metadata),
                        checked_at.isoformat(),
                        item.work_item_id,
                        run_id,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return None

            for table, row in role_rows.items():
                role_session = self._row_to_role_runtime_session(
                    row,
                    role_descriptions[table],
                )
                pending = [
                    str(value or "").strip()
                    for value in list(role_session.pending_work_item_ids or [])
                    if str(value or "").strip()
                    and str(value or "").strip() != item.work_item_id
                ]
                role_metadata = dict(role_session.metadata or {})
                role_metadata.update(
                    {
                        "company_run_id": run_id,
                        "company_run_controller_owner_token": owner_token,
                        "company_run_controller_lease_generation": generation,
                    }
                )
                cursor = await transaction_db.execute(
                    f"""UPDATE {table}
                        SET focused_work_item_id = '', status = 'idle',
                            current_work_item = '{{}}',
                            pending_work_item_ids = ?, metadata = ?, updated_at = ?
                        WHERE role_session_id = ? AND run_id = ?
                          AND project_id = ?""",
                    (
                        _json_dumps(pending),
                        _json_dumps(role_metadata),
                        checked_at.isoformat(),
                        role_session_id,
                        run_id,
                        clean_project_id,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    await transaction_db.rollback()
                    return None

            async with transaction_db.execute(
                """SELECT runtime_task_id
                   FROM work_item_runtime_links
                   WHERE work_item_id = ?""",
                (item.work_item_id,),
            ) as link_cursor:
                link_row = await link_cursor.fetchone()
            linked_task_id = str(link_row[0] if link_row else "").strip()
            if linked_task_id:
                linked_task = await self._get_task_unhydrated(
                    linked_task_id,
                    db=transaction_db,
                )
                if (
                    linked_task is None
                    or (str(linked_task.project_id or "default").strip() or "default")
                    != clean_project_id
                    or not self._runtime_task_matches_work_item(
                        linked_task,
                        item,
                    )
                ):
                    raise RuntimeError(
                        "company attention runtime Task link violates its durable scope"
                    )
                linked_task.status = task_status_for_phase(item.phase)
                linked_task.metadata = dict(linked_task.metadata or {})
                linked_task.metadata["message_priority"] = "seat_attention"
                # A pre-claim wake is owned by the run-level scheduler, not a
                # retained Task attempt.  Keeping a settled attempt token here
                # would let a later broad save impersonate that old attempt.
                for key in (
                    "company_run_controller_owner_token",
                    "company_run_controller_lease_generation",
                    "claimed_work_item_attempt_seq",
                ):
                    linked_task.metadata.pop(key, None)
                await self._save_task_row(
                    linked_task,
                    commit=False,
                    db=transaction_db,
                )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        try:
            await on_phase_transition(
                previous_phase,
                item.phase,
                item,
                store=self,
                notifications_only=True,
            )
        except CompanyRunControllerLeaseLost:
            logger.warning(
                "company attention notification observed controller takeover "
                "after commit for work_item={}",
                str(item.work_item_id or "").strip(),
            )
        except Exception:
            logger.opt(exception=True).debug(
                "company attention post-commit notification failed"
            )
        return item

    async def append_delegated_work_items_atomically(
        self,
        items: list[DelegationWorkItem] | tuple[DelegationWorkItem, ...],
    ) -> list[DelegationWorkItem]:
        """Create one validated ``delegate_work`` batch atomically.

        ``batch_index`` predates the manager-board delegation tool and is also
        used by intake, delivery, review, and report cards.  It is therefore
        deliberately left unchanged.  New business children instead receive a
        monotonic ``delegate_sequence_index`` inside their exact durable
        manager-board scope.  ``BEGIN IMMEDIATE`` serializes the read of the
        prior maximum with every insert, including callers using another
        :class:`OPCStore` instance for the same SQLite database.

        The collaboration layer must finish shape, dependency, and DAG
        validation before calling this method.  This boundary still validates
        the durable identity fields defensively and never overwrites an
        existing WorkItem.  Any insert conflict or other exception rolls back
        the complete input set; phase hooks run only after commit.
        """

        self._require_db()
        pending = [copy.deepcopy(item) for item in list(items or [])]
        if not pending:
            return []

        grouped: dict[tuple[str, str, str, str], list[DelegationWorkItem]] = {}
        invocation_indexes: dict[str, list[int]] = {}
        for item in pending:
            item_id = str(item.work_item_id or "").strip()
            run_id = str(item.run_id or "").strip()
            batch_id = str(item.batch_id or "").strip()
            parent_work_item_id = str(item.parent_work_item_id or "").strip()
            source_seat_id = str(item.source_seat_id or "").strip()
            metadata = dict(item.metadata or {})
            if not all(
                (
                    item_id,
                    run_id,
                    batch_id,
                    parent_work_item_id,
                    source_seat_id,
                )
            ):
                raise ValueError(
                    "atomic delegate_work append requires non-empty item, run, "
                    "batch, parent, and source-seat identities"
                )
            # The stripped values are the allocator's exact durable scope,
            # not merely validation temporaries.  Persist that same canonical
            # identity so the next append queries the row it just inserted.
            item.work_item_id = item_id
            item.run_id = run_id
            item.batch_id = batch_id
            item.parent_work_item_id = parent_work_item_id
            item.source_seat_id = source_seat_id
            if metadata.get("created_by_delegate_work") is not True:
                raise ValueError(
                    "atomic delegate_work append requires "
                    "created_by_delegate_work=true"
                )
            if "delegate_sequence_index" in metadata:
                raise ValueError(
                    "delegate_sequence_index is Store-assigned and must not "
                    "be supplied to atomic delegate_work append"
                )
            invocation_id = str(
                metadata.get("delegate_invocation_id", "") or ""
            ).strip()
            invocation_index = metadata.get("delegate_invocation_index")
            if (
                not invocation_id
                or isinstance(invocation_index, bool)
                or not isinstance(invocation_index, int)
                or invocation_index < 0
            ):
                raise ValueError(
                    "atomic delegate_work append requires a durable invocation "
                    "id and non-negative invocation index"
                )
            metadata["delegate_invocation_id"] = invocation_id
            validate_transition(None, item.phase)
            if (
                self._metadata_has_work_item_projection_identity(metadata)
                or str(item.projection_id or "").strip()
                or str(item.kind or "").strip()
            ):
                metadata, _ = migrate_work_item_projection_metadata(
                    metadata,
                    projection_id_fallback=str(
                        item.projection_id or item.work_item_id or ""
                    ).strip(),
                    turn_type_fallback=str(item.kind or "").strip(),
                )
            item.metadata = metadata
            invocation_indexes.setdefault(invocation_id, []).append(
                invocation_index
            )
            grouped.setdefault(
                (run_id, batch_id, parent_work_item_id, source_seat_id),
                [],
            ).append(item)

        if len(invocation_indexes) != 1:
            raise ValueError(
                "one atomic delegate_work append must carry one invocation id"
            )
        actual_indexes = next(iter(invocation_indexes.values()))
        if sorted(actual_indexes) != list(range(len(pending))):
            raise ValueError(
                "delegate_work invocation indexes must be unique and contiguous "
                "from zero"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            for scope, scoped_items in grouped.items():
                run_id, batch_id, parent_work_item_id, source_seat_id = scope
                async with transaction_db.execute(
                    """SELECT
                               COUNT(*),
                               MAX(
                                   CASE
                                       WHEN json_type(
                                           metadata,
                                           '$.delegate_sequence_index'
                                       ) = 'integer'
                                       THEN CAST(
                                           json_extract(
                                               metadata,
                                               '$.delegate_sequence_index'
                                           ) AS INTEGER
                                       )
                                       ELSE NULL
                                   END
                               )
                       FROM delegation_work_items
                       WHERE run_id = ?
                         AND batch_id = ?
                         AND parent_work_item_id = ?
                         AND source_seat_id = ?
                         AND (
                             json_extract(
                                 metadata,
                                 '$.created_by_delegate_work'
                             ) = 1
                             OR (
                                 json_type(
                                     metadata,
                                     '$.created_by_delegate_work'
                                 ) IS NULL
                                 AND json_extract(
                                     metadata,
                                     '$.created_by_seat_id'
                                 ) = ?
                                 AND json_extract(
                                     metadata,
                                     '$.manager_board_parent_work_item_id'
                                 ) = ?
                             )
                         )""",
                    (
                        run_id,
                        batch_id,
                        parent_work_item_id,
                        source_seat_id,
                        source_seat_id,
                        parent_work_item_id,
                    ),
                ) as cursor:
                    row = await cursor.fetchone()
                existing_count = int(row[0] or 0) if row else 0
                existing_max = (
                    int(row[1])
                    if row is not None and row[1] is not None
                    else -1
                )
                next_index = max(existing_count, existing_max + 1)
                for offset, item in enumerate(scoped_items):
                    item.metadata = {
                        **dict(item.metadata or {}),
                        "delegate_sequence_index": next_index + offset,
                    }

            for item in pending:
                await transaction_db.execute(
                    """INSERT INTO delegation_work_items
                       (work_item_id, run_id, cell_id, team_instance_id, team_id,
                        role_id, seat_id, seat_state_id, role_runtime_session_id,
                        parent_work_item_id, source_role_id, source_seat_id, title,
                        summary, kind, projection_id, phase, batch_id, batch_index,
                        deliverable_summary, blocked_reason, handoff_status,
                        continuation_source, manager_role_id, manager_seat_id,
                        claimed_by_role_runtime_session_id, claimed_by_seat_id,
                        metadata, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                               ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    self._delegation_work_item_insert_values(item),
                )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        for item in pending:
            try:
                await on_phase_transition(None, item.phase, item, store=self)
            except Exception:
                logger.opt(exception=True).debug(
                    "on_phase_transition raised after atomic delegate_work append"
                )
        return pending

    async def _write_delegation_work_item(
        self,
        item: DelegationWorkItem,
        *,
        if_absent: bool,
    ) -> bool:
        # Single-source-of-truth gate: every write — whether it goes through
        # update_delegation_work_item or directly mutates `item.phase` and
        # then calls save — passes through validate_transition. Skipping the
        # validation requires a separate code path; there is no way to write
        # an invalid phase by accident.
        item.metadata = dict(item.metadata or {})
        if (
            self._metadata_has_work_item_projection_identity(item.metadata)
            or str(item.projection_id or "").strip()
            or str(item.kind or "").strip()
        ):
            item.metadata, _ = migrate_work_item_projection_metadata(
                item.metadata,
                projection_id_fallback=str(item.projection_id or item.work_item_id or "").strip(),
                turn_type_fallback=str(item.kind or "").strip(),
            )
        target_phase = item.phase
        self._require_db()
        conflict_action = (
            "DO NOTHING"
            if if_absent
            else """DO UPDATE SET
                run_id=excluded.run_id,
                cell_id=excluded.cell_id,
                team_instance_id=excluded.team_instance_id,
                team_id=excluded.team_id,
                role_id=excluded.role_id,
                seat_id=excluded.seat_id,
                seat_state_id=excluded.seat_state_id,
                role_runtime_session_id=excluded.role_runtime_session_id,
                parent_work_item_id=excluded.parent_work_item_id,
                source_role_id=excluded.source_role_id,
                source_seat_id=excluded.source_seat_id,
                title=excluded.title,
                summary=excluded.summary,
                kind=excluded.kind,
                projection_id=excluded.projection_id,
                phase=excluded.phase,
                batch_id=excluded.batch_id,
                batch_index=excluded.batch_index,
                deliverable_summary=excluded.deliverable_summary,
                blocked_reason=excluded.blocked_reason,
                handoff_status=excluded.handoff_status,
                continuation_source=excluded.continuation_source,
                manager_role_id=excluded.manager_role_id,
                manager_seat_id=excluded.manager_seat_id,
                claimed_by_role_runtime_session_id=excluded.claimed_by_role_runtime_session_id,
                claimed_by_seat_id=excluded.claimed_by_seat_id,
                metadata=excluded.metadata,
                created_at=excluded.created_at,
                updated_at=excluded.updated_at"""
        )
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        existing: DelegationWorkItem | None = None
        previous_phase: Phase | None = None
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (item.work_item_id,),
            ) as existing_cursor:
                row = await existing_cursor.fetchone()
                if row is not None:
                    existing = self._row_to_delegation_work_item(
                        row,
                        existing_cursor.description,
                    )
            if if_absent and existing is not None:
                await transaction_db.rollback()
                return False
            previous_phase = existing.phase if existing is not None else None
            validate_transition(previous_phase, item.phase)
            self._protect_delegate_work_identity(item, existing=existing)
            await transaction_db.execute(
                f"""INSERT INTO delegation_work_items
                (work_item_id, run_id, cell_id, team_instance_id, team_id, role_id, seat_id, seat_state_id,
                 role_runtime_session_id, parent_work_item_id, source_role_id, source_seat_id, title, summary,
                 kind, projection_id, phase, batch_id, batch_index,
                 deliverable_summary, blocked_reason, handoff_status, continuation_source, manager_role_id,
                 manager_seat_id, claimed_by_role_runtime_session_id, claimed_by_seat_id, metadata,
                 created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(work_item_id) {conflict_action}""",
                self._delegation_work_item_insert_values(item),
            )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()
        # D2 hook fire — propagate phase change to dependent layers
        # (task.status, role_session.status, dispatcher wake, etc.). All
        # writes to delegation_work_items pass through here, so this is
        # the single chokepoint where hooks fire.
        try:
            await on_phase_transition(previous_phase, target_phase, item, store=self)
        except Exception:  # never let hook failures break the write
            logger.opt(exception=True).debug("on_phase_transition raised at top level")
        return True

    async def insert_delegation_work_item_if_absent(
        self,
        item: DelegationWorkItem,
    ) -> bool:
        """Atomically create a WorkItem without overwriting a concurrent claim.

        Auxiliary report/review IDs are deterministic.  A read-before-write
        check is insufficient because another dispatcher can create and claim
        the same card between those operations; the conflict decision must be
        made by SQLite in the insert statement itself.
        """
        return await self._write_delegation_work_item(item, if_absent=True)

    async def list_delegation_work_items(
        self,
        run_id: str,
        *,
        team_instance_id: str | None = None,
        team_id: str | None = None,
        seat_id: str | None = None,
        role_runtime_session_id: str | None = None,
        role_id: str | None = None,
        batch_id: str | None = None,
    ) -> list[DelegationWorkItem]:
        db = self._require_db()
        query = "SELECT * FROM delegation_work_items WHERE run_id = ?"
        params: list[Any] = [run_id]
        if team_instance_id:
            query += " AND team_instance_id = ?"
            params.append(team_instance_id)
        if team_id:
            query += " AND team_id = ?"
            params.append(team_id)
        if seat_id:
            query += " AND seat_id = ?"
            params.append(seat_id)
        if role_runtime_session_id:
            query += " AND role_runtime_session_id = ?"
            params.append(role_runtime_session_id)
        if role_id:
            query += " AND role_id = ?"
            params.append(role_id)
        if batch_id:
            query += " AND batch_id = ?"
            params.append(batch_id)
        query += " ORDER BY created_at ASC"
        async with db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_delegation_work_item(row, cursor.description) for row in rows]

    async def list_manager_board(
        self,
        run_id: str,
        *,
        manager_seat_id: str,
        parent_work_item_id: str | None = None,
    ) -> list[DelegationWorkItem]:
        db = self._require_db()
        query = "SELECT * FROM delegation_work_items WHERE run_id = ? AND manager_seat_id = ?"
        params: list[Any] = [run_id, str(manager_seat_id or "").strip()]
        normalized_parent = str(parent_work_item_id or "").strip()
        if normalized_parent:
            query += " AND parent_work_item_id = ?"
            params.append(normalized_parent)
        query += " ORDER BY batch_index ASC, created_at ASC"
        async with db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_delegation_work_item(row, cursor.description) for row in rows]

    async def summarize_parent_status(
        self,
        run_id: str,
        *,
        manager_seat_id: str,
        parent_work_item_id: str,
    ) -> dict[str, Any]:
        parent_id = str(parent_work_item_id or "").strip()
        manager_id = str(manager_seat_id or "").strip()
        if not run_id or not parent_id or not manager_id:
            return {
                "run_id": str(run_id or "").strip(),
                "manager_seat_id": manager_id,
                "parent_work_item_id": parent_id,
                "total_children": 0,
                "phase_counts": {},
                "column_counts": {},
                "releasable_work_item_ids": [],
                "blocked_reasons": [],
                "blocker_count": 0,
                "rework_count": 0,
                "upstream_summary": [],
                "derived_parent_column": "todo",
            }
        children = await self.list_manager_board(
            run_id,
            manager_seat_id=manager_id,
            parent_work_item_id=parent_id,
        )
        phase_counts: dict[str, int] = {}
        column_counts: dict[str, int] = {}
        blocked_reasons: list[str] = []
        releasable_work_item_ids: list[str] = []
        upstream_summary: list[dict[str, Any]] = []
        blocker_count = 0
        rework_count = 0
        done_children = 0
        active_children = 0
        review_children = 0
        todo_children = 0
        visible_children = 0
        for item in children:
            phase = item.phase
            metadata = dict(item.metadata or {})
            column_value = kanban_column(phase)
            phase_counts[phase.value] = phase_counts.get(phase.value, 0) + 1
            column_counts[column_value] = column_counts.get(column_value, 0) + 1
            if item.blocked_reason:
                blocked_reasons.append(str(item.blocked_reason).strip())
            if item.blocked_reason or phase in {
                Phase.WAITING_FOR_PEER,
                Phase.WAITING_FOR_CHILDREN,
                Phase.NEEDS_ATTENTION,
                Phase.WAITING_DEPENDENCIES,
            }:
                blocker_count += 1
            if str(metadata.get("rework_feedback", "") or "").strip():
                rework_count += 1
            if phase == Phase.QUEUED:
                releasable_work_item_ids.append(str(item.work_item_id))
            if metadata.get("hidden_from_company_kanban"):
                continue
            visible_children += 1
            if phase in DONE_PHASES:
                done_children += 1
            elif phase in IN_PROGRESS_PHASES:
                active_children += 1
            elif phase in IN_REVIEW_PHASES:
                review_children += 1
            else:
                todo_children += 1
            visibility = str(metadata.get("upstream_visibility", "summary_only") or "summary_only").strip().lower()
            if visibility != "hidden":
                payload = {
                    "work_item_id": str(item.work_item_id),
                    "title": str(item.title or "").strip(),
                    "role_id": str(item.role_id or "").strip(),
                    "phase": phase.value,
                    "kanban_column": column_value,
                    "deliverable_summary": str(item.deliverable_summary or "").strip(),
                    "blocked_reason": str(item.blocked_reason or "").strip(),
                    "completion_report": str(metadata.get("completion_report", "") or "").strip(),
                    "review_owner_role_id": str(
                        metadata.get("review_owner_role_id")
                        or item.manager_role_id
                        or ""
                    ).strip(),
                    "review_owner_seat_id": str(
                        metadata.get("review_owner_seat_id")
                        or item.manager_seat_id
                        or ""
                    ).strip(),
                    "review_evidence": dict(metadata.get("review_evidence", {}) or {}),
                }
                if visibility == "debug":
                    payload["summary"] = str(item.summary or "").strip()
                    payload["dependency_work_item_ids"] = [
                        str(dep).strip()
                        for dep in list(metadata.get("dependency_work_item_ids", []) or [])
                        if str(dep).strip()
                    ]
                upstream_summary.append(payload)
        derived_parent_column = "todo"
        if visible_children and done_children == visible_children:
            derived_parent_column = "done"
        elif review_children:
            derived_parent_column = "in_review"
        elif active_children:
            derived_parent_column = "in_progress"
        return {
            "run_id": str(run_id or "").strip(),
            "manager_seat_id": manager_id,
            "parent_work_item_id": parent_id,
            "total_children": visible_children,
            "phase_counts": phase_counts,
            "column_counts": column_counts,
            "releasable_work_item_ids": releasable_work_item_ids,
            "blocked_reasons": list(dict.fromkeys(item for item in blocked_reasons if item)),
            "blocker_count": blocker_count,
            "rework_count": rework_count,
            "upstream_summary": upstream_summary[:12],
            "derived_parent_column": derived_parent_column,
        }

    async def get_delegation_work_item(self, work_item_id: str) -> DelegationWorkItem | None:
        db = self._require_db()
        async with db.execute(
            "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
            (work_item_id,),
        ) as cursor:
            row = await cursor.fetchone()
            if row is None:
                return None
            return self._row_to_delegation_work_item(row, cursor.description)

    async def update_delegation_work_item_dependency_frontier_for_controller(
        self,
        expected_item: DelegationWorkItem,
        *,
        project_id: str,
        controller_owner_token: str,
        controller_lease_generation: int,
        phase: Phase | str | None = None,
        summary: str | None = None,
        blocked_reason: str | None = None,
        metadata_updates: dict[str, Any] | None = None,
        claimed_by_role_runtime_session_id: str | None = None,
        claimed_by_seat_id: str | None = None,
        wake_role_runtime_session_id: str = "",
        expected_role_session_focus: str = "",
        linked_task_metadata_updates: dict[str, Any] | None = None,
        allow_approved_dependency_invalidation: bool = False,
    ) -> DelegationWorkItem | None:
        """CAS one dependency-frontier projection under the live run lease.

        Dependency propagation runs after the source child transition commits,
        so a read/check followed by ``update_delegation_work_item`` would leave
        a takeover window.  This API keeps the exact lease generation, the
        parent's phase/version, the WorkItem mutation, and its linked Task
        status projection in one SQLite write transaction.

        ``None`` means the parent snapshot lost an ordinary same-generation
        CAS race.  Losing the run lease is different: it raises the typed
        controller exception, ensuring the stale dispatcher stops instead of
        continuing with a partially authoritative frontier walk.
        """

        self._require_db()
        run_id = str(getattr(expected_item, "run_id", "") or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        owner_token = str(controller_owner_token or "").strip()
        generation = int(controller_lease_generation or 0)
        wake_role_session_id = str(
            wake_role_runtime_session_id or ""
        ).strip()
        expected_focus = str(expected_role_session_focus or "").strip()
        expected_updated_at = getattr(expected_item, "updated_at", None)
        if (
            not run_id
            or not owner_token
            or generation <= 0
            or not isinstance(expected_updated_at, datetime)
        ):
            raise CompanyRunControllerLeaseLost(
                "dependency frontier mutation lacks an exact controller lease"
            )

        item = copy.deepcopy(expected_item)
        previous_phase = item.phase
        if phase is not None:
            target_phase = coerce_phase(phase)
            approved_dependency_invalidation = bool(
                allow_approved_dependency_invalidation
                and previous_phase == Phase.APPROVED
                and target_phase
                in {Phase.WAITING_DEPENDENCIES, Phase.READY_FOR_REWORK}
            )
            if not approved_dependency_invalidation:
                validate_transition(previous_phase, target_phase)
            item.phase = target_phase
        if summary is not None:
            item.summary = str(summary or "")
        if blocked_reason is not None:
            item.blocked_reason = str(blocked_reason or "").strip()
        if claimed_by_role_runtime_session_id is not None:
            item.claimed_by_role_runtime_session_id = str(
                claimed_by_role_runtime_session_id or ""
            ).strip()
        if claimed_by_seat_id is not None:
            item.claimed_by_seat_id = str(claimed_by_seat_id or "").strip()
        metadata = dict(item.metadata or {})
        metadata.update(dict(metadata_updates or {}))
        if wake_role_session_id:
            metadata.update(
                {
                    "company_run_id": run_id,
                    "company_run_controller_owner_token": owner_token,
                    "company_run_controller_lease_generation": generation,
                }
            )
        if phase is not None and item.phase in RUNNABLE_PHASES:
            item.claimed_by_role_runtime_session_id = ""
            item.claimed_by_seat_id = ""
            metadata["claimed_by_role_session_id"] = ""
            metadata["claimed_task_id"] = ""
        item.metadata = metadata
        item.updated_at = datetime.now()

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        wake_role_rows: dict[str, tuple[Any, ...]] = {}
        wake_role_descriptions: dict[str, Any] = {}
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at_datetime = datetime.now()
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=run_id,
                project_id=clean_project_id,
                owner_token=owner_token,
                generation=generation,
                checked_at=checked_at_datetime,
                work_item_id=str(item.work_item_id or "").strip(),
            )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (str(item.work_item_id or "").strip(),),
            ) as identity_cursor:
                identity_row = await identity_cursor.fetchone()
                persisted_identity = (
                    self._row_to_delegation_work_item(
                        identity_row,
                        identity_cursor.description,
                    )
                    if identity_row is not None
                    else None
                )
            if persisted_identity is None:
                await transaction_db.rollback()
                return None
            if wake_role_session_id:
                for table in (
                    "role_runtime_sessions",
                    "delegation_role_sessions",
                ):
                    async with transaction_db.execute(
                        f"""SELECT * FROM {table}
                            WHERE role_session_id = ?""",
                        (wake_role_session_id,),
                    ) as role_cursor:
                        role_row = await role_cursor.fetchone()
                        if role_row is not None:
                            wake_role_rows[table] = role_row
                            wake_role_descriptions[table] = (
                                role_cursor.description
                            )
                if set(wake_role_rows) != {
                    "role_runtime_sessions",
                    "delegation_role_sessions",
                }:
                    raise RuntimeError(
                        "controller attention resume requires both durable "
                        "role-session mirrors"
                    )
                for table, role_row in wake_role_rows.items():
                    role_session = self._row_to_role_runtime_session(
                        role_row,
                        wake_role_descriptions[table],
                    )
                    if (
                        str(role_session.run_id or "").strip() != run_id
                        or (
                            str(role_session.project_id or "default").strip()
                            or "default"
                        )
                        != clean_project_id
                        or str(
                            role_session.focused_work_item_id or ""
                        ).strip()
                        != expected_focus
                        or str(role_session.status or "").strip().lower()
                        not in {"blocked", "idle"}
                        or (
                            str(role_session.role_id or "").strip()
                            and str(item.role_id or "").strip()
                            and str(role_session.role_id or "").strip()
                            != str(item.role_id or "").strip()
                        )
                        or (
                            str(role_session.seat_id or "").strip()
                            and str(item.seat_id or "").strip()
                            and str(role_session.seat_id or "").strip()
                            != str(item.seat_id or "").strip()
                        )
                    ):
                        await transaction_db.rollback()
                        return None
            self._protect_delegate_work_identity(
                item,
                existing=persisted_identity,
            )
            checked_at = checked_at_datetime.isoformat()
            cursor = await transaction_db.execute(
                """UPDATE delegation_work_items
                   SET phase = ?, summary = ?, blocked_reason = ?,
                       claimed_by_role_runtime_session_id = ?,
                       claimed_by_seat_id = ?, metadata = ?, updated_at = ?
                   WHERE work_item_id = ?
                     AND run_id = ?
                     AND phase = ?
                     AND updated_at = ?
                     AND EXISTS (
                         SELECT 1 FROM delegation_runs AS run
                         WHERE run.run_id = delegation_work_items.run_id
                           AND run.project_id = ?
                           AND run.controller_owner_token = ?
                           AND run.controller_lease_generation = ?
                           AND run.controller_lease_expires_at > ?
                     )""",
                (
                    item.phase.value,
                    item.summary,
                    item.blocked_reason,
                    item.claimed_by_role_runtime_session_id,
                    item.claimed_by_seat_id,
                    _json_dumps(item.metadata),
                    item.updated_at.isoformat(),
                    str(item.work_item_id or "").strip(),
                    run_id,
                    previous_phase.value,
                    expected_updated_at.isoformat(),
                    clean_project_id,
                    owner_token,
                    generation,
                    checked_at,
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                async with transaction_db.execute(
                    """SELECT 1 FROM delegation_runs
                       WHERE run_id = ?
                         AND project_id = ?
                         AND controller_owner_token = ?
                         AND controller_lease_generation = ?
                         AND controller_lease_expires_at > ?""",
                    (
                        run_id,
                        clean_project_id,
                        owner_token,
                        generation,
                        checked_at,
                    ),
                ) as lease_cursor:
                    lease_is_current = await lease_cursor.fetchone() is not None
                await transaction_db.rollback()
                if not lease_is_current:
                    raise CompanyRunControllerLeaseLost(
                        "stale company controller cannot refresh dependency frontier"
                    )
                return None

            # The WorkItem phase remains the source of truth, but its linked
            # Task must enter the same projected state before the transaction
            # releases the write lock.  A takeover therefore sees either both
            # rows before this frontier step or both rows after it.
            async with transaction_db.execute(
                """SELECT runtime_task_id
                   FROM work_item_runtime_links
                   WHERE work_item_id = ?""",
                (str(item.work_item_id or "").strip(),),
            ) as link_cursor:
                link_row = await link_cursor.fetchone()
            linked_task_id = str(link_row[0] if link_row else "").strip()
            if linked_task_id and not (
                wake_role_session_id or linked_task_metadata_updates
            ):
                await transaction_db.execute(
                    """UPDATE tasks SET status = ?
                       WHERE id = ? AND project_id = ?""",
                    (
                        task_status_for_phase(item.phase).value,
                        linked_task_id,
                        clean_project_id,
                    ),
                )
            elif linked_task_id:
                linked_task = await self._get_task_unhydrated(
                    linked_task_id,
                    db=transaction_db,
                )
                if (
                    linked_task is None
                    or (str(linked_task.project_id or "default").strip() or "default")
                    != clean_project_id
                    or not self._runtime_task_matches_work_item(
                        linked_task,
                        item,
                    )
                ):
                    raise RuntimeError(
                        "dependency frontier runtime Task link violates its "
                        "durable scope"
                    )
                linked_task.status = task_status_for_phase(item.phase)
                linked_task.metadata = dict(linked_task.metadata or {})
                linked_task.metadata.update(
                    copy.deepcopy(dict(linked_task_metadata_updates or {}))
                )
                await self._save_task_row(
                    linked_task,
                    commit=False,
                    db=transaction_db,
                )
            elif linked_task_metadata_updates:
                raise RuntimeError(
                    "controller attention resume requires a linked runtime Task"
                )

            for table, role_row in wake_role_rows.items():
                role_session = self._row_to_role_runtime_session(
                    role_row,
                    wake_role_descriptions[table],
                )
                pending = [
                    str(value or "").strip()
                    for value in list(role_session.pending_work_item_ids or [])
                    if str(value or "").strip()
                    and str(value or "").strip()
                    != str(item.work_item_id or "").strip()
                ]
                role_metadata = dict(role_session.metadata or {})
                role_metadata.update(
                    {
                        "company_run_id": run_id,
                        "company_run_controller_owner_token": owner_token,
                        "company_run_controller_lease_generation": generation,
                    }
                )
                role_cursor = await transaction_db.execute(
                    f"""UPDATE {table}
                        SET focused_work_item_id = '', status = 'idle',
                            current_work_item = '{{}}',
                            pending_work_item_ids = ?, metadata = ?,
                            updated_at = ?
                        WHERE role_session_id = ? AND run_id = ?
                          AND project_id = ?""",
                    (
                        _json_dumps(pending),
                        _json_dumps(role_metadata),
                        item.updated_at.isoformat(),
                        wake_role_session_id,
                        run_id,
                        clean_project_id,
                    ),
                )
                if int(getattr(role_cursor, "rowcount", 0) or 0) != 1:
                    raise RuntimeError(
                        "controller attention resume lost a role-session mirror"
                    )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        # Durable convergence hooks are intentionally excluded here: every
        # durable effect of this controller-owned step already committed
        # above under the exact generation.  Only dispatcher notifications
        # may run after the transaction without another fence.
        try:
            await on_phase_transition(
                previous_phase,
                item.phase,
                item,
                store=self,
                notifications_only=True,
            )
        except CompanyRunControllerLeaseLost:
            logger.warning(
                "dependency frontier notification observed controller takeover "
                "after commit for work_item={}",
                str(item.work_item_id or "").strip(),
            )
        except Exception:
            logger.opt(exception=True).debug(
                "dependency frontier post-commit notification failed"
            )
        return item

    async def transition_claimed_work_item_and_task_for_controller(
        self,
        work_item_id: str,
        *,
        task: Task,
        target_phase: Phase | str,
        reason: str,
        summary: str | None = None,
        metadata_updates: dict[str, Any] | None = None,
        release_claim: bool = False,
        attempt_outcome: str | None = None,
        blocked_reason: str | None = None,
        handoff_status: str | None = None,
        release_role_session_id: str = "",
        release_role_session_metadata_updates: dict[str, Any] | None = None,
    ) -> DelegationWorkItem:
        """Atomically commit one controller-owned WorkItem/Task transition.

        The controller lease, exact runtime-task link, exact attempt sequence,
        phase transition, attempt settlement, WorkItem update, and complete
        Task snapshot are one SQLite transaction.  Consequently a lease
        takeover cannot fit between a validation query and either business
        write, and an old attempt cannot overwrite a later attempt owned by
        the same controller generation.
        """

        self._require_db()
        clean_work_item_id = str(work_item_id or "").strip()
        if not clean_work_item_id:
            raise ValueError("work_item_id is required")
        target = coerce_phase(target_phase)
        clean_release_role_session_id = str(
            release_role_session_id or ""
        ).strip()
        run_id, owner_token, generation, attempt_seq = (
            self._company_controller_task_fence(task)
        )
        if not run_id or not owner_token or generation <= 0 or attempt_seq <= 0:
            raise CompanyRunControllerLeaseLost(
                "company execution transition lacks an exact controller attempt"
            )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        item: DelegationWorkItem | None = None
        previous_phase: Phase | None = None
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            now = datetime.now()
            if not await self._company_controller_task_fence_matches(
                transaction_db,
                task,
                checked_at=now,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale company controller cannot transition WorkItem/Task"
                )
            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                (clean_work_item_id,),
            ) as cursor:
                row = await cursor.fetchone()
                if row is not None:
                    item = self._row_to_delegation_work_item(
                        row,
                        cursor.description,
                    )
            if item is None or str(item.run_id or "").strip() != run_id:
                raise CompanyRunControllerLeaseLost(
                    "controller Task is not linked to the requested WorkItem"
                )
            role_projection_tables: list[str] = []
            if clean_release_role_session_id:
                if (
                    str(item.claimed_by_role_runtime_session_id or "").strip()
                    != clean_release_role_session_id
                ):
                    raise CompanyRunControllerLeaseLost(
                        "controller quota park does not own the requested role session"
                    )
                task_project_id = (
                    str(task.project_id or "default").strip() or "default"
                )
                for table in (
                    "role_runtime_sessions",
                    "delegation_role_sessions",
                ):
                    async with transaction_db.execute(
                        f"""SELECT run_id, project_id FROM {table}
                            WHERE role_session_id = ?""",
                        (clean_release_role_session_id,),
                    ) as role_cursor:
                        role_row = await role_cursor.fetchone()
                    if role_row is None:
                        continue
                    role_run_id = str(role_row[0] or "").strip()
                    role_project_id = (
                        str(role_row[1] or "default").strip() or "default"
                    )
                    if role_run_id != run_id or role_project_id not in {
                        task_project_id,
                        "default",
                    }:
                        raise CompanyRunControllerLeaseLost(
                            "controller quota park role session belongs to another scope"
                        )
                    role_projection_tables.append(table)
                if not role_projection_tables:
                    raise CompanyRunControllerLeaseLost(
                        "controller quota park role session is missing"
                    )
            async with transaction_db.execute(
                """SELECT 1 FROM work_item_runtime_links
                   WHERE work_item_id = ? AND runtime_task_id = ?""",
                (clean_work_item_id, str(task.id or "").strip()),
            ) as cursor:
                if await cursor.fetchone() is None:
                    raise CompanyRunControllerLeaseLost(
                        "controller Task/WorkItem link changed before transition"
                    )

            previous_phase = item.phase
            persisted_identity = copy.deepcopy(item)
            validate_transition(previous_phase, target)
            previous_updated_at = item.updated_at.isoformat()
            item.phase = target
            if summary is not None:
                item.summary = str(summary or "")
            if blocked_reason is not None:
                item.blocked_reason = str(blocked_reason or "").strip()
            if handoff_status is not None:
                item.handoff_status = str(handoff_status or "").strip()
            metadata = dict(item.metadata or {})
            if target != Phase.RUNNING:
                metadata.update(
                    build_attempt_settlement_updates(
                        metadata,
                        outcome=attempt_outcome or target.value,
                        settled_at=now,
                    )
                )
            metadata.update(dict(metadata_updates or {}))
            reason_clean = str(reason or "").strip()
            if reason_clean:
                metadata["last_transition_reason"] = reason_clean
            release_ownership = release_claim or target in RUNNABLE_PHASES
            if release_ownership:
                item.claimed_by_role_runtime_session_id = ""
                item.claimed_by_seat_id = ""
                metadata["claimed_by_role_session_id"] = ""
                metadata["claimed_task_id"] = ""
            item.metadata = metadata
            self._protect_delegate_work_identity(
                item,
                existing=persisted_identity,
            )
            item.updated_at = now

            cursor = await transaction_db.execute(
                """UPDATE delegation_work_items
                   SET phase = ?, summary = ?, blocked_reason = ?,
                       handoff_status = ?,
                       claimed_by_role_runtime_session_id = ?,
                       claimed_by_seat_id = ?, metadata = ?, updated_at = ?
                   WHERE work_item_id = ?
                     AND run_id = ?
                     AND phase = ?
                     AND updated_at = ?
                     AND CAST(
                           COALESCE(json_extract(metadata, '$.attempt_seq'), 0)
                           AS INTEGER
                         ) = ?
                     AND COALESCE(
                           json_extract(metadata, '$.claimed_task_id'), ''
                         ) IN ('', ?)
                     AND EXISTS (
                         SELECT 1 FROM work_item_runtime_links AS link
                         WHERE link.work_item_id = delegation_work_items.work_item_id
                           AND link.runtime_task_id = ?
                     )
                     AND EXISTS (
                         SELECT 1 FROM delegation_runs AS run
                         WHERE run.run_id = delegation_work_items.run_id
                           AND run.project_id = ?
                           AND run.controller_owner_token = ?
                           AND run.controller_lease_generation = ?
                           AND run.controller_lease_expires_at > ?
                     )""",
                (
                    target.value,
                    item.summary,
                    item.blocked_reason,
                    item.handoff_status,
                    item.claimed_by_role_runtime_session_id,
                    item.claimed_by_seat_id,
                    _json_dumps(item.metadata),
                    item.updated_at.isoformat(),
                    clean_work_item_id,
                    run_id,
                    previous_phase.value,
                    previous_updated_at,
                    attempt_seq,
                    str(task.id or "").strip(),
                    str(task.id or "").strip(),
                    str(task.project_id or "default").strip() or "default",
                    owner_token,
                    generation,
                    now.isoformat(),
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                raise CompanyRunControllerLeaseLost(
                    "controller WorkItem transition lost its atomic fence"
                )

            if clean_release_role_session_id:
                role_metadata_updates = {
                    **dict(release_role_session_metadata_updates or {}),
                    "company_run_controller_owner_token": owner_token,
                    "company_run_controller_lease_generation": generation,
                }
                role_updated_at = datetime.now().isoformat()
                for table in role_projection_tables:
                    role_cursor = await transaction_db.execute(
                        f"""UPDATE {table}
                            SET focused_work_item_id = '',
                                current_work_item = '{{}}',
                                status = 'idle',
                                metadata = json_patch(
                                    COALESCE(NULLIF(metadata, ''), '{{}}'), ?
                                ),
                                updated_at = ?
                            WHERE role_session_id = ? AND run_id = ?""",
                        (
                            _json_dumps(role_metadata_updates),
                            role_updated_at,
                            clean_release_role_session_id,
                            run_id,
                        ),
                    )
                    if int(getattr(role_cursor, "rowcount", 0) or 0) != 1:
                        raise CompanyRunControllerLeaseLost(
                            "controller quota park lost its role-session projection"
                        )

            # Task is the runtime projection, but its result and resumable
            # metadata are still execution effects.  Persist the complete
            # snapshot before releasing the transaction's write lock.
            task.status = task_status_for_phase(target)
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

        assert item is not None and previous_phase is not None
        try:
            await on_phase_transition(
                previous_phase,
                target,
                item,
                store=self,
                notifications_only=True,
            )
        except Exception:
            logger.opt(exception=True).debug(
                "on_phase_transition raised after fenced controller transition"
            )
        if target in DONE_PHASES or target in {
            Phase.AWAITING_HUMAN,
            Phase.READY_FOR_REWORK,
        }:
            # Mutating phase hooks cannot safely run after the source commit:
            # an old generation could lose its lease between commit and hook.
            # Dependency convergence therefore has an explicit controller
            # entry point whose every parent/Task write carries this exact
            # owner token and generation in the SQL predicate.
            from opc.layer2_organization.work_item_transition import (
                refresh_dependents_for_controller,
            )

            await refresh_dependents_for_controller(
                self,
                run_id=run_id,
                project_id=str(task.project_id or "default").strip() or "default",
                controller_owner_token=owner_token,
                controller_lease_generation=generation,
                source_work_item_id=clean_work_item_id,
                source_task_id=str(task.id or "").strip() or None,
                source_role_id=str(item.role_id or "").strip() or None,
                source_cell_id=str(item.cell_id or "").strip() or None,
            )
        return item

    async def update_delegation_work_item(
        self,
        work_item_id: str,
        *,
        team_instance_id: str | None = None,
        team_id: str | None = None,
        seat_id: str | None = None,
        seat_state_id: str | None = None,
        role_runtime_session_id: str | None = None,
        phase: Phase | str | None = None,
        summary: str | None = None,
        batch_id: str | None = None,
        batch_index: int | None = None,
        deliverable_summary: str | None = None,
        blocked_reason: str | None = None,
        handoff_status: str | None = None,
        continuation_source: str | None = None,
        metadata_updates: dict[str, Any] | None = None,
        metadata_unset: list[str] | tuple[str, ...] | None = None,
        manager_role_id: str | None = None,
        manager_seat_id: str | None = None,
        claimed_by_role_runtime_session_id: str | None = None,
        claimed_by_seat_id: str | None = None,
    ) -> DelegationWorkItem | None:
        item = await self.get_delegation_work_item(work_item_id)
        if item is None:
            return None
        previous_phase = item.phase
        if team_instance_id is not None:
            item.team_instance_id = str(team_instance_id or "").strip()
        if team_id is not None:
            item.team_id = str(team_id or "").strip()
        if seat_id is not None:
            item.seat_id = str(seat_id or "").strip()
        if seat_state_id is not None:
            item.seat_state_id = str(seat_state_id or "").strip()
        if role_runtime_session_id is not None:
            item.role_runtime_session_id = str(role_runtime_session_id or "").strip()
        if phase is not None:
            target_phase = coerce_phase(phase)
            validate_transition(previous_phase, target_phase)
            item.phase = target_phase
        if summary is not None:
            item.summary = summary
        if batch_id is not None:
            item.batch_id = str(batch_id or "").strip()
        if batch_index is not None:
            item.batch_index = int(batch_index)
        if deliverable_summary is not None:
            item.deliverable_summary = str(deliverable_summary or "").strip()
        if blocked_reason is not None:
            item.blocked_reason = str(blocked_reason or "").strip()
        if handoff_status is not None:
            item.handoff_status = str(handoff_status or "").strip()
        if continuation_source is not None:
            item.continuation_source = str(continuation_source or "").strip()
        if manager_role_id is not None:
            item.manager_role_id = str(manager_role_id or "").strip()
        if manager_seat_id is not None:
            item.manager_seat_id = str(manager_seat_id or "").strip()
        if claimed_by_role_runtime_session_id is not None:
            item.claimed_by_role_runtime_session_id = str(claimed_by_role_runtime_session_id or "").strip()
        if claimed_by_seat_id is not None:
            item.claimed_by_seat_id = str(claimed_by_seat_id or "").strip()
        if metadata_unset or metadata_updates:
            metadata = dict(item.metadata or {})
            for key in list(metadata_unset or []):
                metadata.pop(str(key), None)
            if metadata_updates:
                metadata.update(dict(metadata_updates))
            item.metadata = metadata
        if phase is not None and item.phase in RUNNABLE_PHASES:
            # Invariant: a fresh-runnable card is unowned. The claim CAS
            # refuses cards with any leftover claim, so entering READY /
            # READY_FOR_REWORK must release ownership in the same write —
            # otherwise the card is permanently unclaimable and the
            # dispatcher livelocks (project-0011 wedge).
            item.claimed_by_role_runtime_session_id = ""
            item.claimed_by_seat_id = ""
            metadata = dict(item.metadata or {})
            metadata["claimed_by_role_session_id"] = ""
            metadata["claimed_task_id"] = ""
            item.metadata = metadata
        item.updated_at = datetime.now()
        await self.save_delegation_work_item(item)
        return item

    async def claim_delegation_work_item_if_dispatchable(
        self,
        work_item_id: str,
        *,
        expected_phase: Phase | str,
        role_runtime_session_id: str,
        seat_id: str,
        task_id: str,
        work_item_revision: int = 0,
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> DelegationWorkItem | None:
        """Atomically claim an unheld, unowned dispatchable WorkItem.

        The dispatcher may be operating on a snapshot loaded before a Stop or
        shutdown transition.  Keeping the phase, claim, queue, and durable
        hold predicates in the same UPDATE prevents that stale snapshot from
        resurrecting a suspended WorkItem.

        Ownership truth is the two claim columns. The metadata mirror keys
        (``claimed_by_role_session_id`` / ``claimed_task_id``) are written for
        observability but must never gate the claim: a mirror key that a
        release path forgot to blank would make a runnable card permanently
        unclaimable (the project-0011 dispatcher livelock).
        """

        phase = coerce_phase(expected_phase)
        dispatchable_phases = {
            Phase.READY,
            Phase.READY_FOR_REWORK,
            *IN_PROGRESS_PHASES,
        }
        if phase not in dispatchable_phases:
            return None
        if phase != Phase.RUNNING:
            validate_transition(phase, Phase.RUNNING)
        role_session_id = str(role_runtime_session_id or "").strip()
        claimed_task_id = str(task_id or "").strip()
        controller_token = str(controller_owner_token or "").strip()
        controller_generation = int(controller_lease_generation or 0)
        if not work_item_id or not role_session_id or not claimed_task_id:
            return None

        updated_at = datetime.now()
        db = self._require_db()
        cursor = await db.execute(
            """UPDATE delegation_work_items
               SET phase = ?,
                   role_runtime_session_id = ?,
                   claimed_by_role_runtime_session_id = ?,
                   claimed_by_seat_id = ?,
                   metadata = json_set(
                       COALESCE(NULLIF(metadata, ''), '{}'),
                       '$.claimed_by_role_session_id', ?,
                       '$.claimed_task_id', ?,
                       '$.claimed_work_item_revision', ?,
                       '$.attempt_seq', COALESCE(
                           CAST(json_extract(metadata, '$.attempt_seq') AS INTEGER),
                           0
                       ) + 1,
                       '$.attempt_settled', json('false'),
                       '$.attempt_outcome', '',
                       '$.company_run_controller_owner_token', ?,
                       '$.company_run_controller_lease_generation', ?,
                       '$.attempt_started_at', ?
                   ),
                   updated_at = ?
               WHERE work_item_id = ?
                 AND phase = ?
                 AND COALESCE(claimed_by_role_runtime_session_id, '') = ''
                 AND COALESCE(claimed_by_seat_id, '') = ''
                 AND COALESCE(json_extract(metadata, '$.dispatch_hold'), '') = ''
                 AND COALESCE(json_extract(metadata, '$.queued_behind_session'), '') = ''
                 AND COALESCE(
                       CAST(json_extract(metadata, '$.manager_mutation_revision') AS INTEGER),
                       0
                     ) = ?
                 AND (
                     NOT EXISTS (
                         SELECT 1 FROM delegation_runs
                         WHERE delegation_runs.run_id = delegation_work_items.run_id
                     )
                     OR (
                         ? != ''
                         AND EXISTS (
                         SELECT 1 FROM delegation_runs
                         WHERE delegation_runs.run_id = delegation_work_items.run_id
                           AND controller_owner_token = ?
                           AND controller_lease_generation = ?
                           AND controller_lease_expires_at > ?
                         )
                     )
                 )""",
            (
                Phase.RUNNING.value,
                role_session_id,
                role_session_id,
                str(seat_id or "").strip(),
                role_session_id,
                claimed_task_id,
                int(work_item_revision or 0),
                controller_token,
                controller_generation,
                updated_at.isoformat(),
                updated_at.isoformat(),
                str(work_item_id or "").strip(),
                phase.value,
                int(work_item_revision or 0),
                controller_token,
                controller_token,
                controller_generation,
                datetime.now().isoformat(),
            ),
        )
        await db.commit()
        if not (getattr(cursor, "rowcount", 0) or 0):
            return None
        persisted = await self.get_delegation_work_item(work_item_id)
        if persisted is None:
            return None
        persisted_metadata = dict(persisted.metadata or {})
        if (
            persisted.phase != Phase.RUNNING
            or str(persisted.claimed_by_role_runtime_session_id or "").strip()
            != role_session_id
            or str(persisted_metadata.get("claimed_by_role_session_id", "") or "").strip()
            != role_session_id
            or str(persisted_metadata.get("claimed_task_id", "") or "").strip()
            != claimed_task_id
            or str(persisted_metadata.get("dispatch_hold", "") or "").strip()
            or str(persisted_metadata.get("queued_behind_session", "") or "").strip()
        ):
            # Stop/shutdown may have won immediately after the CAS commit and
            # cleared this claim while adding a durable hold.  The committed
            # UPDATE is not permission to spawn once that newer state exists.
            return None
        # Do not fire the generic phase hooks here.  The executor's first
        # idempotent RUNNING transition performs projection.  Deferring it
        # avoids a post-commit hook racing after Stop and projecting the Task
        # back to RUNNING from an already-held WorkItem.
        return persisted

    async def apply_delegation_review_resolution(
        self,
        work_item_id: str,
        *,
        source_report_work_item_id: str,
        target_phase: Phase | str,
        blocked_reason: str,
        metadata_updates: dict[str, Any],
    ) -> DelegationWorkItem | None:
        """Atomically apply a manager verdict to its exact report generation.

        The phase predicate and latest-applied-report predicate live in the
        same SQLite UPDATE as the child phase + applied-stamp write. This
        prevents a late manager turn from mutating a child after it leaves
        AWAITING_MANAGER_REVIEW or approving an older report after a newer
        report landed. The manager-review state machine has only two normal
        outcomes: APPROVED and READY_FOR_REWORK; in particular it never creates
        an AWAITING_HUMAN owner gate. ``updated_at`` provides optimistic
        metadata concurrency; a few retries preserve unrelated same-phase
        updates without weakening either guard.
        """
        target = coerce_phase(target_phase)
        validate_transition(Phase.AWAITING_MANAGER_REVIEW, target)
        return await self._apply_delegation_review_resolution_cas(
            work_item_id,
            source_report_work_item_id=source_report_work_item_id,
            source_phases=frozenset({Phase.AWAITING_MANAGER_REVIEW}),
            target_phase=target,
            blocked_reason=blocked_reason,
            metadata_updates=metadata_updates,
        )

    async def retire_legacy_human_review_resolution(
        self,
        work_item_id: str,
        *,
        source_report_work_item_id: str,
        metadata_updates: dict[str, Any],
    ) -> DelegationWorkItem | None:
        """Retire one pre-state-machine manager-to-human review verdict.

        Older databases can contain a durable ``review_resolution`` whose
        target phase is AWAITING_HUMAN. That edge is not part of the current
        manager-review state machine. Recovery deterministically normalizes
        the old verdict to APPROVED, whether the interrupted process left the
        child in AWAITING_MANAGER_REVIEW or already wrote AWAITING_HUMAN.

        This is deliberately a separate, target-less compatibility API: it
        cannot create an owner gate or choose any phase other than APPROVED.
        It retains the same exact latest-report and optimistic metadata CAS as
        normal review resolution application.
        """
        if await self.legacy_human_review_retirement_is_protected(work_item_id):
            return None
        return await self._apply_delegation_review_resolution_cas(
            work_item_id,
            source_report_work_item_id=source_report_work_item_id,
            source_phases=frozenset(
                {Phase.AWAITING_MANAGER_REVIEW, Phase.AWAITING_HUMAN}
            ),
            target_phase=Phase.APPROVED,
            blocked_reason="",
            metadata_updates=metadata_updates,
        )

    async def recover_legacy_human_review_target_from_stale_resolution(
        self,
        work_item_id: str,
        *,
        stale_source_report_work_item_id: str,
        metadata_updates: dict[str, Any],
    ) -> DelegationWorkItem | None:
        """Return one legacy human target to manager review after stale CAS.

        This compatibility write is intentionally narrower than a phase API:
        the source must be AWAITING_HUMAN and the latest applied report must no
        longer equal the stale resolution's report. The only destination is
        AWAITING_MANAGER_REVIEW, allowing reconciliation to consume the newest
        existing report without replaying the worker's completed tool effects.
        """
        if await self.legacy_human_review_retirement_is_protected(work_item_id):
            return None
        expected_source = str(stale_source_report_work_item_id or "").strip()
        self._require_db()
        for _attempt in range(3):
            transaction_db = _SQLiteConnectionAdapter(self.db_path)
            persisted: DelegationWorkItem | None = None
            applied = False
            try:
                await transaction_db.execute("BEGIN IMMEDIATE")
                async with transaction_db.execute(
                    "SELECT * FROM delegation_work_items WHERE work_item_id = ?",
                    (str(work_item_id or "").strip(),),
                ) as current_cursor:
                    current_row = await current_cursor.fetchone()
                    item = (
                        self._row_to_delegation_work_item(
                            current_row,
                            current_cursor.description,
                        )
                        if current_row is not None
                        else None
                    )
                if item is None or item.phase != Phase.AWAITING_HUMAN:
                    await transaction_db.rollback()
                    return None
                persisted_identity = copy.deepcopy(item)
                metadata = dict(item.metadata or {})
                metadata.update(copy.deepcopy(dict(metadata_updates or {})))
                metadata["claimed_by_role_session_id"] = ""
                metadata["claimed_task_id"] = ""
                item.metadata = metadata
                self._protect_delegate_work_identity(
                    item,
                    existing=persisted_identity,
                )
                previous_updated_at = item.updated_at.isoformat()
                updated_at = datetime.now()
                cursor = await transaction_db.execute(
                    """UPDATE delegation_work_items
                       SET phase = ?, blocked_reason = '', metadata = ?,
                           claimed_by_role_runtime_session_id = '',
                           claimed_by_seat_id = '', updated_at = ?
                       WHERE work_item_id = ?
                         AND phase = ?
                         AND updated_at = ?
                         AND COALESCE((
                             SELECT report.work_item_id
                             FROM delegation_work_items AS report
                             WHERE report.parent_work_item_id = ?
                               AND report.kind = 'report'
                               AND json_extract(
                                   report.metadata,
                                   '$.report_target_work_item_id'
                               ) = ?
                               AND json_extract(
                                   report.metadata,
                                   '$.report_card_outcome'
                               ) = 'applied'
                             ORDER BY report.batch_index DESC,
                                      report.created_at DESC,
                                      report.work_item_id DESC
                             LIMIT 1
                         ), '') != ?""",
                    (
                        Phase.AWAITING_MANAGER_REVIEW.value,
                        _json_dumps(item.metadata),
                        updated_at.isoformat(),
                        work_item_id,
                        Phase.AWAITING_HUMAN.value,
                        previous_updated_at,
                        work_item_id,
                        work_item_id,
                        expected_source,
                    ),
                )
                applied = bool(getattr(cursor, "rowcount", 0) or 0)
                if not applied:
                    await transaction_db.rollback()
                    continue
                await self._sync_linked_task_projection_from_exact_work_item_phase(
                    work_item_id,
                    exact_phase=Phase.AWAITING_MANAGER_REVIEW,
                    db=transaction_db,
                )
                await transaction_db.commit()
                item.phase = Phase.AWAITING_MANAGER_REVIEW
                item.blocked_reason = ""
                item.claimed_by_role_runtime_session_id = ""
                item.claimed_by_seat_id = ""
                item.updated_at = updated_at
                persisted = item
            except BaseException:
                await transaction_db.rollback()
                raise
            finally:
                await transaction_db.close()
            if not applied or persisted is None:
                continue
            if persisted is None:
                return None
            try:
                await on_phase_transition(
                    Phase.AWAITING_HUMAN,
                    Phase.AWAITING_MANAGER_REVIEW,
                    persisted,
                    store=self,
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "on_phase_transition raised after legacy review recovery CAS"
                )
            return persisted
        return None

    async def _apply_delegation_review_resolution_cas(
        self,
        work_item_id: str,
        *,
        source_report_work_item_id: str,
        source_phases: frozenset[Phase],
        target_phase: Phase,
        blocked_reason: str,
        metadata_updates: dict[str, Any],
    ) -> DelegationWorkItem | None:
        """Shared exact-report CAS for normal application and legacy retirement."""
        if not source_phases:
            raise ValueError("source_phases must not be empty")
        for source_phase in source_phases:
            validate_transition(source_phase, target_phase)
        expected_source = str(source_report_work_item_id or "").strip()
        db = self._require_db()

        # A rework verdict sends the card back to the dispatch queue; the
        # claim CAS refuses owned cards, so ownership must be released in
        # the same UPDATE that writes the runnable phase (project-0011
        # wedge: REJECT kept the worker's claim and the card became
        # permanently unclaimable).
        release_ownership = target_phase in RUNNABLE_PHASES

        for _attempt in range(3):
            item = await self.get_delegation_work_item(work_item_id)
            if item is None or item.phase not in source_phases:
                return None
            metadata = dict(item.metadata or {})
            persisted_identity = copy.deepcopy(item)
            metadata.update(dict(metadata_updates or {}))
            if release_ownership:
                metadata["claimed_by_role_session_id"] = ""
                metadata["claimed_task_id"] = ""
            if (
                self._metadata_has_work_item_projection_identity(metadata)
                or str(item.projection_id or "").strip()
                or str(item.kind or "").strip()
            ):
                metadata, _ = migrate_work_item_projection_metadata(
                    metadata,
                    projection_id_fallback=str(
                        item.projection_id or item.work_item_id or ""
                    ).strip(),
                    turn_type_fallback=str(item.kind or "").strip(),
                )
            item.metadata = metadata
            self._protect_delegate_work_identity(
                item,
                existing=persisted_identity,
            )
            metadata = item.metadata
            previous_updated_at = item.updated_at.isoformat()
            updated_at = datetime.now()
            claimed_session = (
                "" if release_ownership
                else str(item.claimed_by_role_runtime_session_id or "")
            )
            claimed_seat = (
                "" if release_ownership else str(item.claimed_by_seat_id or "")
            )
            cursor = await db.execute(
                """UPDATE delegation_work_items
                   SET phase = ?, blocked_reason = ?, metadata = ?, updated_at = ?,
                       claimed_by_role_runtime_session_id = ?,
                       claimed_by_seat_id = ?
                   WHERE work_item_id = ?
                     AND phase = ?
                     AND updated_at = ?
                     AND COALESCE((
                         SELECT report.work_item_id
                         FROM delegation_work_items AS report
                         WHERE report.parent_work_item_id = ?
                           AND report.kind = 'report'
                           AND json_extract(
                               report.metadata,
                               '$.report_target_work_item_id'
                           ) = ?
                           AND json_extract(
                               report.metadata,
                               '$.report_card_outcome'
                           ) = 'applied'
                         ORDER BY report.batch_index DESC,
                                  report.created_at DESC,
                                  report.work_item_id DESC
                         LIMIT 1
                     ), '') = ?""",
                (
                    target_phase.value,
                    str(blocked_reason or ""),
                    _json_dumps(metadata),
                    updated_at.isoformat(),
                    claimed_session,
                    claimed_seat,
                    work_item_id,
                    item.phase.value,
                    previous_updated_at,
                    work_item_id,
                    work_item_id,
                    expected_source,
                ),
            )
            if getattr(cursor, "rowcount", 0) or 0:
                await self._sync_linked_task_projection_from_exact_work_item_phase(
                    work_item_id,
                    exact_phase=target_phase,
                )
            await db.commit()
            if not (getattr(cursor, "rowcount", 0) or 0):
                continue
            persisted = await self.get_delegation_work_item(work_item_id)
            if persisted is None:
                return None
            try:
                await on_phase_transition(
                    item.phase,
                    target_phase,
                    persisted,
                    store=self,
                )
            except Exception:
                logger.opt(exception=True).debug(
                    "on_phase_transition raised after review-resolution CAS"
                )
            return persisted
        return None

    async def reopen_approved_delegation_work_item_for_rework(
        self,
        work_item_id: str,
        *,
        target_phase: Phase | str = Phase.READY_FOR_REWORK,
        summary: str | None = None,
        deliverable_summary: str | None = "",
        blocked_reason: str | None = "",
        metadata_updates: dict[str, Any] | None = None,
        metadata_unset: list[str] | tuple[str, ...] | None = None,
        release_claim: bool = True,
    ) -> DelegationWorkItem | None:
        """Named bypass for invalidating approved work after manager/user feedback."""
        item = await self.get_delegation_work_item(work_item_id)
        if item is None:
            return None
        previous_phase = item.phase
        persisted_identity = copy.deepcopy(item)
        target = coerce_phase(target_phase)
        if previous_phase != Phase.APPROVED:
            raise InvalidPhaseTransition(
                f"executive rework can only reopen approved work items, got {previous_phase.value}"
            )
        if target not in {
            Phase.READY_FOR_REWORK,
            Phase.READY,
            Phase.WAITING_DEPENDENCIES,
        }:
            raise InvalidPhaseTransition(
                "executive rework target must be ready_for_rework, ready, "
                f"or waiting_dependencies, got {target.value}"
            )

        item.phase = target
        if summary is not None:
            item.summary = str(summary or "").strip()
        if deliverable_summary is not None:
            item.deliverable_summary = str(deliverable_summary or "").strip()
        if blocked_reason is not None:
            item.blocked_reason = str(blocked_reason or "").strip()
        if release_claim:
            item.claimed_by_role_runtime_session_id = ""
            item.claimed_by_seat_id = ""

        metadata = dict(item.metadata or {})
        for key in list(metadata_unset or []):
            metadata.pop(str(key), None)
        if metadata_updates:
            metadata.update(dict(metadata_updates))
        if (
            self._metadata_has_work_item_projection_identity(metadata)
            or str(item.projection_id or "").strip()
            or str(item.kind or "").strip()
        ):
            metadata, _ = migrate_work_item_projection_metadata(
                metadata,
                projection_id_fallback=str(item.projection_id or item.work_item_id or "").strip(),
                turn_type_fallback=str(item.kind or "").strip(),
            )
        item.metadata = metadata
        self._protect_delegate_work_identity(
            item,
            existing=persisted_identity,
        )
        item.updated_at = datetime.now()

        db = self._require_db()
        await db.execute(
            """UPDATE delegation_work_items
               SET phase=?,
                   summary=?,
                   deliverable_summary=?,
                   blocked_reason=?,
                   claimed_by_role_runtime_session_id=?,
                   claimed_by_seat_id=?,
                   metadata=?,
                   updated_at=?
               WHERE work_item_id=?""",
            (
                item.phase.value,
                item.summary,
                item.deliverable_summary,
                item.blocked_reason,
                item.claimed_by_role_runtime_session_id,
                item.claimed_by_seat_id,
                _json_dumps(item.metadata),
                item.updated_at.isoformat(),
                item.work_item_id,
            ),
        )
        await db.commit()
        try:
            await on_phase_transition(previous_phase, target, item, store=self)
        except Exception:
            logger.opt(exception=True).debug("on_phase_transition raised during approved work-item reopen")
        return item

    async def amend_delegation_work_item(
        self,
        work_item_id: str,
        *,
        title: str | None = None,
        summary: str | None = None,
        kind: str | None = None,
        role_id: str | None = None,
        seat_id: str | None = None,
        team_instance_id: str | None = None,
        team_id: str | None = None,
        role_runtime_session_id: str | None = None,
        claimed_by_role_runtime_session_id: str | None = None,
        claimed_by_seat_id: str | None = None,
        dependency_work_item_ids: list[str] | None = None,
        phase: Phase | str | None = None,
        metadata_set: dict[str, Any] | None = None,
        metadata_unset: list[str] | None = None,
    ) -> DelegationWorkItem | None:
        item = await self.get_delegation_work_item(work_item_id)
        if item is None:
            return None
        previous_phase = item.phase
        if title is not None:
            item.title = str(title or "").strip()
        if summary is not None:
            item.summary = str(summary or "").strip()
        if kind is not None:
            item.kind = str(kind or "").strip() or item.kind
        if role_id is not None:
            item.role_id = str(role_id or "").strip()
        if seat_id is not None:
            item.seat_id = str(seat_id or "").strip()
        if team_instance_id is not None:
            item.team_instance_id = str(team_instance_id or "").strip()
        if team_id is not None:
            item.team_id = str(team_id or "").strip()
        if role_runtime_session_id is not None:
            item.role_runtime_session_id = str(role_runtime_session_id or "").strip()
        if claimed_by_role_runtime_session_id is not None:
            item.claimed_by_role_runtime_session_id = str(claimed_by_role_runtime_session_id or "").strip()
        if claimed_by_seat_id is not None:
            item.claimed_by_seat_id = str(claimed_by_seat_id or "").strip()
        if phase is not None:
            target_phase = coerce_phase(phase)
            validate_transition(previous_phase, target_phase)
            item.phase = target_phase

        metadata = dict(item.metadata or {})
        if dependency_work_item_ids is not None:
            raw_dependencies = (
                [dependency_work_item_ids]
                if isinstance(dependency_work_item_ids, str)
                else list(dependency_work_item_ids or [])
            )
            metadata["dependency_work_item_ids"] = [
                str(dep).strip()
                for dep in raw_dependencies
                if str(dep).strip()
            ]
        if metadata_set:
            metadata.update(dict(metadata_set))
        for key in list(metadata_unset or []):
            metadata.pop(str(key), None)
        item.metadata = metadata
        item.updated_at = datetime.now()
        await self.save_delegation_work_item(item)
        return item

    async def replace_work_item_dependency(
        self,
        run_id: str,
        old_work_item_id: str,
        new_work_item_ids: list[str],
    ) -> list[DelegationWorkItem]:
        rid = str(run_id or "").strip()
        old_id = str(old_work_item_id or "").strip()
        raw_replacements = (
            [new_work_item_ids]
            if isinstance(new_work_item_ids, str)
            else list(new_work_item_ids or [])
        )
        replacements = [
            str(item).strip()
            for item in raw_replacements
            if str(item).strip()
        ]
        if not rid or not old_id:
            return []
        updated: list[DelegationWorkItem] = []
        for item in await self.list_delegation_work_items(rid):
            metadata = dict(item.metadata or {})
            dependency_ids = [
                str(dep).strip()
                for dep in list(metadata.get("dependency_work_item_ids", []) or [])
                if str(dep).strip()
            ]
            waiting_ids = [
                str(dep).strip()
                for dep in list(metadata.get("waiting_on_work_item_ids", []) or [])
                if str(dep).strip()
            ]
            if old_id not in dependency_ids and old_id not in waiting_ids:
                continue
            rewritten: list[str] = []
            for dep in dependency_ids:
                if dep == old_id:
                    rewritten.extend(replacements)
                else:
                    rewritten.append(dep)
            deduped = list(dict.fromkeys(dep for dep in rewritten if dep))
            rewritten_waiting: list[str] = []
            for dep in waiting_ids:
                if dep == old_id:
                    rewritten_waiting.extend(replacements)
                else:
                    rewritten_waiting.append(dep)
            item.metadata = {
                **metadata,
                "dependency_work_item_ids": deduped,
                "waiting_on_work_item_ids": list(
                    dict.fromkeys(dep for dep in rewritten_waiting if dep)
                ),
                "dependency_rewritten_from_work_item_id": old_id,
                "dependency_rewritten_at": datetime.now().isoformat(),
            }
            item.updated_at = datetime.now()
            await self.save_delegation_work_item(item)
            updated.append(item)
        return updated

    async def release_manager_work_items(
        self,
        run_id: str,
        *,
        manager_seat_id: str,
        work_item_ids: list[str] | None = None,
        parent_work_item_id: str | None = None,
        release_note: str = "",
        released_by_message_id: str = "",
        action_hint: str = "",
    ) -> list[DelegationWorkItem]:
        target_ids = {
            str(item).strip()
            for item in list(work_item_ids or [])
            if str(item).strip()
        }
        candidates = await self.list_manager_board(
            run_id,
            manager_seat_id=manager_seat_id,
            parent_work_item_id=parent_work_item_id,
        )
        released: list[DelegationWorkItem] = []
        for item in candidates:
            if target_ids and item.work_item_id not in target_ids:
                continue
            metadata_updates = {
                "last_release_note": str(release_note or "").strip(),
                "last_released_by_message_id": str(released_by_message_id or "").strip(),
                "last_release_action_hint": str(action_hint or "").strip(),
                "released_at": datetime.now().isoformat(),
            }
            target_phase = Phase.READY if item.phase == Phase.QUEUED else item.phase
            updated = await self.update_delegation_work_item(
                item.work_item_id,
                phase=target_phase,
                metadata_updates=metadata_updates,
            )
            if updated is not None:
                released.append(updated)
        return released

    async def rollup_manager_board(
        self,
        run_id: str,
        *,
        manager_seat_id: str,
        parent_work_item_id: str,
        summary: str = "",
        phase: Phase | str | None = None,
        blocked_reason: str | None = None,
        metadata_updates: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        rollup = await self.summarize_parent_status(
            run_id,
            manager_seat_id=manager_seat_id,
            parent_work_item_id=parent_work_item_id,
        )
        parent = await self.get_delegation_work_item(parent_work_item_id)
        if parent is not None:
            merged_updates = {
                "manager_board_rollup": dict(rollup),
                "manager_board_rollup_updated_at": datetime.now().isoformat(),
            }
            if summary:
                merged_updates["manager_board_rollup_summary"] = str(summary).strip()
            if metadata_updates:
                merged_updates.update(dict(metadata_updates))
            await self.update_delegation_work_item(
                parent_work_item_id,
                phase=phase,
                deliverable_summary=summary or None,
                blocked_reason=blocked_reason,
                metadata_updates=merged_updates,
            )
            refreshed_parent = await self.get_delegation_work_item(parent_work_item_id)
            if refreshed_parent is not None:
                rollup["parent_phase"] = refreshed_parent.phase.value
                rollup["parent_column"] = kanban_column(refreshed_parent.phase)
                rollup["parent_deliverable_summary"] = str(getattr(refreshed_parent, "deliverable_summary", "") or "").strip()
                rollup["parent_blocked_reason"] = str(getattr(refreshed_parent, "blocked_reason", "") or "").strip()
        return rollup

    async def save_delegation_event(self, event: DelegationEvent) -> None:
        db = self._require_db()
        await db.execute(
            """INSERT OR REPLACE INTO delegation_events
            (event_id, run_id, work_item_id, cell_id, role_id, event_type, payload, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                event.event_id,
                event.run_id,
                event.work_item_id,
                event.cell_id,
                event.role_id,
                event.event_type,
                _json_dumps(event.payload),
                event.created_at.isoformat(),
            ),
        )
        await db.commit()

    async def list_delegation_events(self, run_id: str) -> list[DelegationEvent]:
        db = self._require_db()
        async with db.execute(
            "SELECT * FROM delegation_events WHERE run_id = ? ORDER BY created_at ASC",
            (run_id,),
        ) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        return [
            DelegationEvent(
                event_id=data["event_id"],
                run_id=data["run_id"],
                work_item_id=data.get("work_item_id"),
                cell_id=data.get("cell_id"),
                role_id=data.get("role_id"),
                event_type=data["event_type"],
                payload=_json_loads(data.get("payload"), {}),
                created_at=datetime.fromisoformat(data["created_at"]),
            )
            for data in (dict(zip(cols, row)) for row in rows)
        ]

    # --- Dynamic reorg persistence ---

    @staticmethod
    def _reorg_proposal_create_identity(proposal: ReorgProposal) -> dict[str, Any]:
        """Immutable source identity used to make proposal creation idempotent."""

        return {
            "proposal_id": proposal.proposal_id,
            "project_id": proposal.project_id,
            "session_id": proposal.session_id,
            "task_id": proposal.task_id,
            "initiated_by": proposal.initiated_by,
            "source_role_id": proposal.source_role_id,
            "scope": proposal.scope.value,
            "risk_level": proposal.risk_level.value,
            "title": proposal.title,
            "summary": proposal.summary,
            "rationale": proposal.rationale,
            "user_confirmation_required": proposal.user_confirmation_required,
            "old_org_version": proposal.old_org_version,
            "new_org_version": proposal.new_org_version,
            "changeset": proposal.changeset.__dict__,
        }

    async def create_reorg_proposal_with_interaction(
        self,
        proposal: ReorgProposal,
        *,
        owner_checkpoint: ExecutionCheckpoint,
    ) -> tuple[ReorgProposal, bool, ExecutionCheckpoint | None, bool]:
        """Atomically create a proposal and its required owner confirmation.

        A pre-existing identical proposal is an idempotent retry.  For legacy
        crash states where the proposal committed before its card, retrying
        this method creates the missing card in the same serialized domain
        transaction.  No existing proposal status is ever overwritten.
        """

        if owner_checkpoint is None:
            raise ValueError(
                "public reorg proposal creation requires an owner checkpoint"
            )
        return await self._create_reorg_proposal(
            proposal,
            owner_checkpoint=owner_checkpoint,
            system_decision_authorized=False,
        )

    async def _create_system_task_adjustment_proposal(
        self,
        proposal: ReorgProposal,
    ) -> tuple[ReorgProposal, bool, None, bool]:
        """Persist the manager's fixed low-risk system adjustment path."""

        persisted, created, checkpoint, checkpoint_created = (
            await self._create_reorg_proposal(
                proposal,
                owner_checkpoint=None,
                system_decision_authorized=True,
            )
        )
        if checkpoint is not None or checkpoint_created:
            raise RuntimeError("system task adjustment unexpectedly created a card")
        return persisted, created, None, False

    async def _create_reorg_proposal(
        self,
        proposal: ReorgProposal,
        *,
        owner_checkpoint: ExecutionCheckpoint | None,
        system_decision_authorized: bool,
    ) -> tuple[ReorgProposal, bool, ExecutionCheckpoint | None, bool]:
        """Shared create-only transaction for the two fixed authority modes."""

        assert self._db
        if proposal.status != ReorgProposalStatus.PROPOSED:
            raise ValueError("new reorg proposal must start proposed")
        if proposal.user_confirmation_required != (owner_checkpoint is not None):
            raise ValueError(
                "confirmation-required proposal and owner checkpoint must be paired"
            )
        persisted_system_authority = (
            dict(proposal.metadata or {}).get("system_decision_authorized") is True
        )
        if not proposal.user_confirmation_required:
            if not system_decision_authorized or (
                proposal.scope != ReorgScope.TASK_ADJUSTMENT
                or proposal.risk_level != ReorgRiskLevel.LOW
                or not persisted_system_authority
            ):
                raise ValueError(
                    "owner-free reorg proposals require the fixed low-risk system path"
                )
        elif system_decision_authorized or persisted_system_authority:
            raise ValueError(
                "owner-confirmed reorg proposals cannot carry system authority"
            )
        checkpoint_payload: dict[str, Any] | None = None
        interaction_key = ""
        if owner_checkpoint is not None:
            if (
                owner_checkpoint.checkpoint_type != "company_reorg_pending"
                or owner_checkpoint.project_id != proposal.project_id
                or str(owner_checkpoint.session_id or "")
                != str(proposal.session_id or "")
                or str(owner_checkpoint.task_id or "") != str(proposal.task_id or "")
                or str(owner_checkpoint.status or "pending") != "pending"
            ):
                raise ValueError("reorg owner checkpoint identity does not match proposal")
            checkpoint_payload = json.loads(
                _json_dumps(dict(owner_checkpoint.payload or {}))
            )
            interaction = self._execution_checkpoint_interaction(checkpoint_payload)
            interaction_key = str(interaction.get("domain_key", "") or "").strip()
            if not interaction_key:
                raise ValueError("reorg owner checkpoint requires interaction.domain_key")
            if str(checkpoint_payload.get("proposal_id", "") or "") != str(
                proposal.proposal_id
            ):
                raise ValueError("reorg owner checkpoint proposal_id mismatch")
            if any(
                key in interaction
                for key in ("decision", "claim", "completion", "execution")
            ):
                raise ValueError("new reorg owner checkpoint must have a clean envelope")

        self._assert_project_write_scope(
            proposal.project_id,
            operation="create_reorg_proposal_with_interaction",
            entity=f"reorg proposal {proposal.proposal_id!r}",
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
                (proposal.proposal_id,),
            ) as cursor:
                existing_row = await cursor.fetchone()
                existing_description = cursor.description
            created = existing_row is None
            if existing_row is not None:
                persisted = self._row_to_reorg_proposal(
                    existing_row,
                    existing_description,
                )
                if self._reorg_proposal_create_identity(
                    persisted
                ) != self._reorg_proposal_create_identity(proposal):
                    raise RuntimeError("reorg proposal id has conflicting source identity")
            else:
                await self._db.execute(
                    """INSERT INTO reorg_proposals
            (proposal_id, project_id, session_id, task_id, initiated_by, source_role_id, scope, risk_level,
             status, title, summary, rationale, user_confirmation_required, old_org_version, new_org_version,
             changeset, migration_plan, impact_summary,
             approval_notes, metadata, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        proposal.proposal_id,
                        proposal.project_id,
                        proposal.session_id,
                        proposal.task_id,
                        proposal.initiated_by,
                        proposal.source_role_id,
                        proposal.scope.value,
                        proposal.risk_level.value,
                        proposal.status.value,
                        proposal.title,
                        proposal.summary,
                        proposal.rationale,
                        int(proposal.user_confirmation_required),
                        proposal.old_org_version,
                        proposal.new_org_version,
                        _json_dumps(proposal.changeset.__dict__),
                        _json_dumps(proposal.migration_plan.__dict__),
                        _json_dumps(proposal.impact_summary),
                        proposal.approval_notes,
                        _json_dumps(proposal.metadata),
                        proposal.created_at.isoformat(),
                        proposal.updated_at.isoformat(),
                    ),
                )
                persisted = proposal

            persisted_checkpoint: ExecutionCheckpoint | None = None
            checkpoint_created = False
            if owner_checkpoint is not None and checkpoint_payload is not None:
                persisted_checkpoint, checkpoint_created = (
                    await self._publish_owner_interaction_checkpoint(
                        owner_checkpoint,
                        interaction_key=interaction_key,
                        supersede_pending_scope=True,
                        supersession_key=str(
                            interaction.get("supersession_key", "") or ""
                        ).strip()
                        or None,
                        supersession_order=list(
                            interaction.get("supersession_order", []) or []
                        ),
                        transaction_open=True,
                        db=self._db,
                    )
                )
                if str(
                    dict(persisted_checkpoint.payload or {}).get("proposal_id", "")
                    or ""
                ) != proposal.proposal_id:
                    raise RuntimeError(
                        "reorg interaction domain key has conflicting proposal identity"
                    )
                if (
                    proposal.task_id
                    and persisted.status == ReorgProposalStatus.PROPOSED
                    and persisted_checkpoint.status
                    in {"pending", "answered", "consuming"}
                ):
                    # Publish the owner card and its Task-side wait marker as
                    # one fact.  UI notification happens only after commit, so
                    # an immediate answer can never observe a card whose Task
                    # still lacks the matching proposal identity.
                    waiting_task = await self._get_task_unhydrated(proposal.task_id)
                    if waiting_task is not None:
                        waiting_project_id = (
                            str(waiting_task.project_id or "default").strip()
                            or "default"
                        )
                        if waiting_project_id != proposal.project_id:
                            raise RuntimeError(
                                "reorg waiting task belongs to another project"
                            )
                        waiting_task.metadata = dict(waiting_task.metadata or {})
                        waiting_task.metadata["pending_reorg_proposal_id"] = (
                            proposal.proposal_id
                        )
                        waiting_task.metadata["pending_reorg_scope"] = (
                            proposal.scope.value
                        )
                        await self._save_task_row(waiting_task, commit=False)
            await self._db.commit()
            return persisted, created, persisted_checkpoint, checkpoint_created
        except Exception:
            await self._db.rollback()
            raise

    async def get_reorg_proposal(self, proposal_id: str) -> ReorgProposal | None:
        assert self._db
        async with self._db.execute(
            "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
            (proposal_id,),
        ) as cursor:
            row = await cursor.fetchone()
            if not row:
                return None
            return self._row_to_reorg_proposal(row, cursor.description)

    async def decide_reorg_proposal(
        self,
        proposal_id: str,
        *,
        approved: bool,
        notes: str = "",
        checkpoint_id: str = "",
        checkpoint_claim_id: str = "",
        checkpoint_consumer_id: str = "",
    ) -> ReorgDecisionReceipt:
        """Atomically make the immutable owner decision for a proposal."""

        return await self._decide_reorg_proposal(
            proposal_id,
            approved=approved,
            notes=notes,
            checkpoint_id=checkpoint_id,
            checkpoint_claim_id=checkpoint_claim_id,
            checkpoint_consumer_id=checkpoint_consumer_id,
            system_decision=False,
        )

    async def _decide_system_task_adjustment_proposal(
        self,
        proposal_id: str,
        *,
        approved: bool,
        notes: str = "",
    ) -> ReorgDecisionReceipt:
        """Decide the manager's persisted low-risk system adjustment."""

        return await self._decide_reorg_proposal(
            proposal_id,
            approved=approved,
            notes=notes,
            system_decision=True,
        )

    async def _decide_reorg_proposal(
        self,
        proposal_id: str,
        *,
        approved: bool,
        notes: str = "",
        checkpoint_id: str = "",
        checkpoint_claim_id: str = "",
        checkpoint_consumer_id: str = "",
        system_decision: bool,
    ) -> ReorgDecisionReceipt:
        """Shared immutable decision transaction for fixed authority modes."""

        assert self._db
        target = (
            ReorgProposalStatus.APPROVED
            if approved
            else ReorgProposalStatus.DENIED
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
                (proposal_id,),
            ) as cursor:
                row = await cursor.fetchone()
                description = cursor.description
            if row is None:
                await self._db.rollback()
                return ReorgDecisionReceipt(outcome="not_found")
            proposal = self._row_to_reorg_proposal(row, description)
            if proposal.user_confirmation_required:
                if not all(
                    (
                        checkpoint_id,
                        checkpoint_claim_id,
                        checkpoint_consumer_id,
                    )
                ):
                    await self._db.commit()
                    return ReorgDecisionReceipt(outcome="conflict", proposal=proposal)
                checkpoint = await self._select_execution_checkpoint(
                    checkpoint_id,
                    project_id=proposal.project_id,
                    checkpoint_type="company_reorg_pending",
                )
                if checkpoint is None:
                    await self._db.commit()
                    return ReorgDecisionReceipt(outcome="conflict", proposal=proposal)
                checkpoint_payload = dict(checkpoint.payload or {})
                checkpoint_interaction = self._execution_checkpoint_interaction(
                    checkpoint_payload
                )
                checkpoint_claim = dict(
                    checkpoint_interaction.get("claim", {}) or {}
                )
                completion = dict(
                    checkpoint_interaction.get("completion", {}) or {}
                )
                claim_matches = (
                    str(checkpoint_claim.get("claim_id", "") or "")
                    == checkpoint_claim_id
                    and str(checkpoint_claim.get("consumer_id", "") or "")
                    == checkpoint_consumer_id
                ) or (
                    str(completion.get("claim_id", "") or "")
                    == checkpoint_claim_id
                    and str(completion.get("consumer_id", "") or "")
                    == checkpoint_consumer_id
                )
                decision_record = dict(
                    checkpoint_interaction.get("decision", {}) or {}
                )
                decision_value = dict(decision_record.get("value", {}) or {})
                decision_token = str(
                    decision_value.get("option_id")
                    or decision_value.get("checkpoint_reply_kind")
                    or decision_value.get("text")
                    or ""
                ).strip().lower()
                approved_tokens = {
                    "y", "yes", "ok", "okay", "approve", "approved",
                    "confirm", "continue", "proceed", "go",
                }
                denied_tokens = {
                    "n", "no", "deny", "denied", "reject", "rejected",
                    "stop", "cancel", "abort",
                }
                decision_matches = decision_token in (
                    approved_tokens if approved else denied_tokens
                )
                if (
                    checkpoint_payload.get("proposal_id") != proposal_id
                    or checkpoint.status not in {"consuming", "resolved"}
                    or not claim_matches
                    or not decision_matches
                ):
                    await self._db.commit()
                    return ReorgDecisionReceipt(outcome="conflict", proposal=proposal)
            elif (
                not system_decision
                or proposal.scope != ReorgScope.TASK_ADJUSTMENT
                or proposal.risk_level != ReorgRiskLevel.LOW
                or dict(proposal.metadata or {}).get(
                    "system_decision_authorized"
                )
                is not True
            ):
                await self._db.commit()
                return ReorgDecisionReceipt(outcome="conflict", proposal=proposal)
            if proposal.status == target:
                await self._db.commit()
                return ReorgDecisionReceipt(outcome="duplicate", proposal=proposal)
            if proposal.status != ReorgProposalStatus.PROPOSED:
                await self._db.commit()
                return ReorgDecisionReceipt(outcome="conflict", proposal=proposal)
            updated_at = datetime.now()
            cursor = await self._db.execute(
                """UPDATE reorg_proposals
                SET status = ?, approval_notes = ?, updated_at = ?
                WHERE proposal_id = ? AND status = ?""",
                (
                    target.value,
                    notes or proposal.approval_notes,
                    updated_at.isoformat(),
                    proposal_id,
                    ReorgProposalStatus.PROPOSED.value,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ReorgDecisionReceipt(outcome="conflict")
            await self._db.commit()
            proposal.status = target
            proposal.approval_notes = notes or proposal.approval_notes
            proposal.updated_at = updated_at
            return ReorgDecisionReceipt(outcome="applied", proposal=proposal)
        except Exception:
            await self._db.rollback()
            raise

    async def claim_reorg_application(
        self,
        proposal_id: str,
        *,
        operation_token: str,
    ) -> ReorgApplicationClaimReceipt:
        """Elect exactly one controller to apply an approved reorganization.

        ``APPLYING`` is intentionally fail-closed.  A controller crash leaves
        the proposal in that state for explicit operator reconciliation; a
        second controller must never infer that the external mutation is safe
        to replay.
        """

        assert self._db
        token = str(operation_token or "").strip()
        if not token:
            raise ValueError("operation_token is required")
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
                (proposal_id,),
            ) as cursor:
                row = await cursor.fetchone()
                description = cursor.description
            if row is None:
                await self._db.rollback()
                return ReorgApplicationClaimReceipt(
                    outcome="not_found",
                    operation_token=token,
                )
            proposal = self._row_to_reorg_proposal(row, description)
            if proposal.status == ReorgProposalStatus.APPLIED:
                await self._db.commit()
                return ReorgApplicationClaimReceipt(
                    outcome="applied",
                    operation_token=token,
                    proposal=proposal,
                )
            application = dict(proposal.metadata or {}).get("application_claim")
            application = dict(application or {}) if isinstance(application, dict) else {}
            if proposal.status == ReorgProposalStatus.APPLYING:
                outcome = (
                    "duplicate"
                    if str(application.get("operation_token", "") or "") == token
                    else "busy"
                )
                await self._db.commit()
                return ReorgApplicationClaimReceipt(
                    outcome=outcome,
                    operation_token=token,
                    proposal=proposal,
                )
            if proposal.status != ReorgProposalStatus.APPROVED:
                await self._db.commit()
                return ReorgApplicationClaimReceipt(
                    outcome="invalid_state",
                    operation_token=token,
                    proposal=proposal,
                )

            started_at = datetime.now()
            proposal.metadata = dict(proposal.metadata or {})
            proposal.metadata["application_claim"] = {
                "operation_token": token,
                "state": "applying",
                "started_at": started_at.isoformat(),
            }
            cursor = await self._db.execute(
                """UPDATE reorg_proposals
                SET status = ?, metadata = ?, updated_at = ?
                WHERE proposal_id = ? AND status = ?""",
                (
                    ReorgProposalStatus.APPLYING.value,
                    _json_dumps(proposal.metadata),
                    started_at.isoformat(),
                    proposal_id,
                    ReorgProposalStatus.APPROVED.value,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ReorgApplicationClaimReceipt(
                    outcome="busy",
                    operation_token=token,
                )
            await self._db.commit()
            proposal.status = ReorgProposalStatus.APPLYING
            proposal.updated_at = started_at
            return ReorgApplicationClaimReceipt(
                outcome="acquired",
                operation_token=token,
                proposal=proposal,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def finish_reorg_application(
        self,
        proposal: ReorgProposal,
        *,
        operation_token: str,
    ) -> ReorgApplicationFinishReceipt:
        """Persist an application result only for the elected controller."""

        assert self._db
        token = str(operation_token or "").strip()
        if not token:
            raise ValueError("operation_token is required")
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
                (proposal.proposal_id,),
            ) as cursor:
                row = await cursor.fetchone()
                description = cursor.description
            if row is None:
                await self._db.rollback()
                return ReorgApplicationFinishReceipt("not_found", token)
            current = self._row_to_reorg_proposal(row, description)
            if current.status == ReorgProposalStatus.APPLIED:
                await self._db.commit()
                return ReorgApplicationFinishReceipt(
                    "duplicate", token, current
                )
            application = dict(current.metadata or {}).get("application_claim")
            application = dict(application or {}) if isinstance(application, dict) else {}
            if (
                current.status != ReorgProposalStatus.APPLYING
                or str(application.get("operation_token", "") or "") != token
            ):
                await self._db.commit()
                return ReorgApplicationFinishReceipt("ownership_lost", token, current)
            if proposal.status != ReorgProposalStatus.APPLIED:
                raise ValueError("finished reorg proposal must have APPLIED status")

            completed_at = datetime.now()
            proposal.metadata = dict(proposal.metadata or {})
            proposal.metadata["application_claim"] = {
                **application,
                "state": "applied",
                "completed_at": completed_at.isoformat(),
            }
            proposal.updated_at = completed_at
            cursor = await self._db.execute(
                """UPDATE reorg_proposals
                SET status = ?, old_org_version = ?, new_org_version = ?,
                    changeset = ?, migration_plan = ?, impact_summary = ?,
                    approval_notes = ?, metadata = ?, updated_at = ?
                WHERE proposal_id = ? AND status = ?""",
                (
                    proposal.status.value,
                    proposal.old_org_version,
                    proposal.new_org_version,
                    _json_dumps(proposal.changeset.__dict__),
                    _json_dumps(proposal.migration_plan.__dict__),
                    _json_dumps(proposal.impact_summary),
                    proposal.approval_notes,
                    _json_dumps(proposal.metadata),
                    proposal.updated_at.isoformat(),
                    proposal.proposal_id,
                    ReorgProposalStatus.APPLYING.value,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ReorgApplicationFinishReceipt("ownership_lost", token)
            await self._db.commit()
            return ReorgApplicationFinishReceipt("applied", token, proposal)
        except Exception:
            await self._db.rollback()
            raise

    async def fail_reorg_application(
        self,
        proposal_id: str,
        *,
        operation_token: str,
        effect_started: bool,
        error: str,
    ) -> ReorgApplicationFinishReceipt:
        """Settle a claimed application without ever replaying uncertain work."""

        assert self._db
        token = str(operation_token or "").strip()
        if not token:
            raise ValueError("operation_token is required")
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT * FROM reorg_proposals WHERE proposal_id = ?",
                (proposal_id,),
            ) as cursor:
                row = await cursor.fetchone()
                description = cursor.description
            if row is None:
                await self._db.rollback()
                return ReorgApplicationFinishReceipt("not_found", token)
            proposal = self._row_to_reorg_proposal(row, description)
            application = dict(proposal.metadata or {}).get("application_claim")
            application = dict(application or {}) if isinstance(application, dict) else {}
            if (
                proposal.status != ReorgProposalStatus.APPLYING
                or str(application.get("operation_token", "") or "") != token
            ):
                await self._db.commit()
                return ReorgApplicationFinishReceipt(
                    "ownership_lost", token, proposal
                )
            terminal = (
                ReorgProposalStatus.EXECUTION_UNKNOWN
                if effect_started
                else ReorgProposalStatus.FAILED
            )
            completed_at = datetime.now()
            proposal.metadata = dict(proposal.metadata or {})
            proposal.metadata["application_claim"] = {
                **application,
                "state": terminal.value,
                "completed_at": completed_at.isoformat(),
                "error": str(error or "")[:2000],
            }
            cursor = await self._db.execute(
                """UPDATE reorg_proposals
                SET status = ?, metadata = ?, updated_at = ?
                WHERE proposal_id = ? AND status = ?""",
                (
                    terminal.value,
                    _json_dumps(proposal.metadata),
                    completed_at.isoformat(),
                    proposal_id,
                    ReorgProposalStatus.APPLYING.value,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ReorgApplicationFinishReceipt("ownership_lost", token)
            await self._db.commit()
            proposal.status = terminal
            proposal.updated_at = completed_at
            return ReorgApplicationFinishReceipt("applied", token, proposal)
        except Exception:
            await self._db.rollback()
            raise

    async def list_reorg_proposals(
        self,
        project_id: str,
        status: ReorgProposalStatus | None = None,
        limit: int = 20,
    ) -> list[ReorgProposal]:
        assert self._db
        query = "SELECT * FROM reorg_proposals WHERE project_id = ?"
        params: list[Any] = [project_id]
        if status:
            query += " AND status = ?"
            params.append(status.value)
        query += " ORDER BY updated_at DESC LIMIT ?"
        params.append(limit)
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            return [self._row_to_reorg_proposal(row, cursor.description) for row in rows]

    def _row_to_reorg_proposal(self, row: Any, description: Any) -> ReorgProposal:
        from dataclasses import fields as _dc_fields

        from opc.core.models import (
            ReorgChangeSet,
            ReorgMigrationPlan,
            ReorgRoleChange,
            ReorgTaskAdjustment,
        )

        cols = [d[0] for d in description]
        data = dict(zip(cols, row))
        changeset_data = _json_loads(data.get("changeset"), {})
        migration_plan_data = _json_loads(data.get("migration_plan"), {})
        migration_plan_data = {
            k: v
            for k, v in migration_plan_data.items()
            if k in {f.name for f in _dc_fields(ReorgMigrationPlan)}
        }
        return ReorgProposal(
            proposal_id=data["proposal_id"],
            project_id=data["project_id"],
            session_id=data.get("session_id"),
            task_id=data.get("task_id"),
            initiated_by=data.get("initiated_by") or "owner",
            source_role_id=data.get("source_role_id") or "",
            scope=ReorgScope(data["scope"]),
            risk_level=ReorgRiskLevel(data["risk_level"]),
            status=ReorgProposalStatus(data["status"]),
            title=data.get("title") or "",
            summary=data.get("summary") or "",
            rationale=data.get("rationale") or "",
            user_confirmation_required=bool(data.get("user_confirmation_required", 1)),
            old_org_version=int(data.get("old_org_version") or 1),
            new_org_version=int(data.get("new_org_version") or 1),
            old_runtime_topology_version=int(data.get("old_runtime_topology_version") or 1),
            new_runtime_topology_version=int(data.get("new_runtime_topology_version") or 1),
            changeset=ReorgChangeSet(
                role_changes=[ReorgRoleChange(**item) for item in changeset_data.get("role_changes", [])],
                task_adjustments=[ReorgTaskAdjustment(**item) for item in changeset_data.get("task_adjustments", [])],
                metadata=dict(changeset_data.get("metadata", {})),
            ),
            migration_plan=ReorgMigrationPlan(**migration_plan_data),
            impact_summary=_json_loads(data.get("impact_summary"), {}),
            approval_notes=data.get("approval_notes") or "",
            metadata=_json_loads(data.get("metadata"), {}),
            created_at=datetime.fromisoformat(data["created_at"]),
            updated_at=datetime.fromisoformat(data["updated_at"]),
        )

