    async def get_autonomy_stats(self, project_id: str | None = None) -> dict[str, Any]:
        assert self._db
        query = "SELECT decision_action, COUNT(*) FROM approval_records"
        params: list[Any] = []
        if project_id:
            query += " WHERE project_id = ?"
            params.append(project_id)
        query += " GROUP BY decision_action"
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
        counts = {row[0]: row[1] for row in rows}
        total = sum(counts.values())
        auto = counts.get("auto_approve", 0)
        escalate = counts.get("escalate", 0)
        reject = counts.get("reject", 0)
        return {
            "total": total,
            "auto_approved": auto,
            "escalated": escalate,
            "rejected": reject,
            "auto_approval_rate": (auto / total) if total else 0.0,
        }

    # --- External sessions ---

    async def save_external_session(self, session: ExternalSession) -> None:
        assert self._db
        self._assert_project_write_scope(
            getattr(session, "project_id", None),
            operation="save_external_session",
            entity=f"external session task={getattr(session, 'task_id', '')!r}",
        )
        session_key = self._external_session_key(session)
        payload = dict(session.metadata or {})
        run_id = str(
            payload.get("company_run_id")
            or payload.get("delegation_run_id")
            or ""
        ).strip()
        token, generation = self._company_controller_credential_from_metadata(
            payload
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            if not run_id:
                async with self._db.execute(
                    """SELECT metadata FROM external_sessions
                       WHERE session_key = ?""",
                    (session_key,),
                ) as cursor:
                    existing_row = await cursor.fetchone()
                if existing_row is not None:
                    existing_metadata = _json_loads(existing_row[0], {})
                    run_id = str(
                        existing_metadata.get("company_run_id")
                        or existing_metadata.get("delegation_run_id")
                        or ""
                    ).strip()
            if not run_id and str(session.task_id or "").strip():
                async with self._db.execute(
                    """SELECT json_extract(metadata, '$.delegation_run_id')
                       FROM tasks WHERE id = ? AND project_id = ?""",
                    (str(session.task_id or "").strip(), session.project_id),
                ) as cursor:
                    task_scope = await cursor.fetchone()
                if task_scope is not None:
                    run_id = str(task_scope[0] or "").strip()
            if run_id:
                payload["company_run_id"] = run_id
            await self._require_company_controller_record_write(
                self._db,
                run_id=run_id,
                project_id=session.project_id,
                owner_token=token,
                generation=generation,
                checked_at=datetime.now(),
                task_id=str(session.task_id or "").strip(),
            )
            await self._db.execute(
                """INSERT OR REPLACE INTO external_sessions
                (session_key, agent_type, project_id, session_id, opc_session_id, task_id, workspace_path, run_mode, status, metadata, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    session_key,
                    session.agent_type,
                    session.project_id,
                    session.session_id,
                    session.opc_session_id,
                    session.task_id,
                    session.workspace_path,
                    session.run_mode,
                    session.status,
                    _json_dumps(payload),
                    session.updated_at.isoformat(),
                ),
            )
            await self._close_replaced_external_session_rows(
                session,
                session_key=session_key,
            )
            await self._db.commit()
        except BaseException:
            await self._db.rollback()
            raise

    async def _close_replaced_external_session_rows(
        self,
        session: ExternalSession,
        *,
        session_key: str,
    ) -> None:
        """Close stale placeholder rows once the real provider session finishes."""
        assert self._db
        status = str(session.status or "").strip().lower()
        if status not in {
            "done",
            "completed",
            "complete",
            "finished",
            "failed",
            "cancelled",
            "canceled",
            "suspended",
            "hard_timeout",
            "idle_timeout",
            "startup_timeout",
            "denied",
            "rejected",
        }:
            return
        task_id = str(session.task_id or "").strip()
        if not task_id:
            return
        await self._db.execute(
            """
            UPDATE external_sessions
            SET status = ?, updated_at = ?
            WHERE project_id = ?
              AND agent_type = ?
              AND task_id = ?
              AND COALESCE(opc_session_id, '') = ?
              AND session_key != ?
              AND status IN ('starting', 'running', 'working')
            """,
            (
                session.status,
                session.updated_at.isoformat(),
                session.project_id,
                session.agent_type,
                task_id,
                str(session.opc_session_id or "").strip(),
                session_key,
            ),
        )

    async def get_external_session(
        self,
        agent_type: str,
        project_id: str = "default",
        *,
        opc_session_id: str | None = None,
        task_id: str | None = None,
    ) -> ExternalSession | None:
        assert self._db
        query = "SELECT * FROM external_sessions WHERE agent_type = ? AND project_id = ?"
        params: list[Any] = [agent_type, project_id]
        if opc_session_id:
            query += " AND opc_session_id = ?"
            params.append(opc_session_id)
        if task_id:
            query += " AND task_id = ?"
            params.append(task_id)
        query += " ORDER BY updated_at DESC LIMIT 1"
        async with self._db.execute(query, params) as cursor:
            row = await cursor.fetchone()
            if not row:
                return None
            cols = [d[0] for d in cursor.description]
            data = dict(zip(cols, row))
            return ExternalSession(
                agent_type=data["agent_type"],
                project_id=data["project_id"],
                session_id=data["session_id"],
                opc_session_id=data.get("opc_session_id"),
                task_id=data["task_id"],
                workspace_path=data["workspace_path"],
                run_mode=data["run_mode"],
                status=data["status"],
                metadata=_json_loads(data["metadata"], {}),
                updated_at=datetime.fromisoformat(data["updated_at"]),
            )

    async def get_latest_external_session_for_task(
        self,
        project_id: str,
        task_id: str,
    ) -> ExternalSession | None:
        assert self._db
        async with self._db.execute(
            """
            SELECT * FROM external_sessions
            WHERE project_id = ? AND task_id = ?
            ORDER BY updated_at DESC
            LIMIT 1
            """,
            (project_id, task_id),
        ) as cursor:
            row = await cursor.fetchone()
            if not row:
                return None
            cols = [d[0] for d in cursor.description]
            data = dict(zip(cols, row))
            return ExternalSession(
                agent_type=data["agent_type"],
                project_id=data["project_id"],
                session_id=data["session_id"],
                opc_session_id=data.get("opc_session_id"),
                task_id=data["task_id"],
                workspace_path=data["workspace_path"],
                run_mode=data["run_mode"],
                status=data["status"],
                metadata=_json_loads(data["metadata"], {}),
                updated_at=datetime.fromisoformat(data["updated_at"]),
            )

    async def list_external_sessions(
        self,
        *,
        project_id: str | None = None,
        status: str | None = None,
        task_id: str | None = None,
        opc_session_id: str | None = None,
        limit: int = 50,
    ) -> list[ExternalSession]:
        assert self._db
        query = "SELECT * FROM external_sessions WHERE 1=1"
        params: list[Any] = []
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        if status:
            query += " AND status = ?"
            params.append(status)
        if task_id:
            query += " AND task_id = ?"
            params.append(task_id)
        if opc_session_id:
            query += " AND opc_session_id = ?"
            params.append(opc_session_id)
        query += " ORDER BY updated_at DESC LIMIT ?"
        params.append(max(1, int(limit or 50)))
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        return [
            ExternalSession(
                agent_type=data["agent_type"],
                project_id=data["project_id"],
                session_id=data["session_id"],
                opc_session_id=data.get("opc_session_id"),
                task_id=data["task_id"],
                workspace_path=data["workspace_path"],
                run_mode=data["run_mode"],
                status=data["status"],
                metadata=_json_loads(data["metadata"], {}),
                updated_at=datetime.fromisoformat(data["updated_at"]),
            )
            for data in (dict(zip(cols, row)) for row in rows)
        ]

    def _external_session_key(self, session: ExternalSession) -> str:
        return "|".join(
            [
                session.agent_type,
                session.project_id or "default",
                session.opc_session_id or "",
                session.task_id or "",
                session.session_id,
            ]
        )

    # --- Execution checkpoints ---

    @staticmethod
    def _execution_checkpoint_from_data(data: dict[str, Any]) -> ExecutionCheckpoint:
        return ExecutionCheckpoint(
            checkpoint_id=str(data["checkpoint_id"]),
            project_id=str(data["project_id"]),
            session_id=data.get("session_id"),
            checkpoint_type=str(data["checkpoint_type"]),
            status=str(data["status"]),
            task_id=data.get("task_id"),
            payload=_json_loads(data.get("payload"), {})
            if not isinstance(data.get("payload"), dict)
            else dict(data.get("payload") or {}),
            created_at=datetime.fromisoformat(str(data["created_at"])),
            updated_at=datetime.fromisoformat(str(data["updated_at"])),
        )

    @staticmethod
    def _checkpoint_with(
        checkpoint: ExecutionCheckpoint,
        *,
        status: str,
        payload: dict[str, Any],
        updated_at: datetime,
    ) -> ExecutionCheckpoint:
        return ExecutionCheckpoint(
            checkpoint_id=checkpoint.checkpoint_id,
            project_id=checkpoint.project_id,
            session_id=checkpoint.session_id,
            checkpoint_type=checkpoint.checkpoint_type,
            status=status,
            task_id=checkpoint.task_id,
            payload=payload,
            created_at=checkpoint.created_at,
            updated_at=updated_at,
        )

    @staticmethod
    def _require_owner_interaction_type(
        checkpoint_type: str,
        *,
        operation: str,
    ) -> None:
        """Keep the answered/claimed state machine exclusive to owner cards."""

        if str(checkpoint_type or "").strip() not in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise ValueError(
                f"{operation} only accepts owner interaction checkpoint types"
            )

    @classmethod
    def _merge_execution_checkpoint_payload(
        cls,
        current: dict[str, Any],
        patch: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Recursively merge a patch into the payload read in this transaction."""

        merged = dict(current or {})
        for key, value in dict(patch or {}).items():
            existing = merged.get(key)
            if isinstance(existing, dict) and isinstance(value, dict):
                merged[key] = cls._merge_execution_checkpoint_payload(existing, value)
            else:
                merged[key] = value
        return merged

    @staticmethod
    def _execution_checkpoint_interaction(
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        value = payload.get("interaction")
        return dict(value) if isinstance(value, dict) else {}

    async def _remove_task_runtime_tool_permit_in_transaction(
        self,
        *,
        task_id: str,
        runtime_session_id: str,
        fingerprint: str,
        continue_after_result: bool = False,
    ) -> bool:
        """Remove one exact permit while the caller owns the SQLite tx."""

        assert self._db
        task_id = str(task_id or "").strip()
        runtime_session_id = str(runtime_session_id or "").strip()
        fingerprint = str(fingerprint or "").strip()
        if not task_id or not runtime_session_id or not fingerprint:
            return False
        async with self._db.execute(
            "SELECT context_snapshot, metadata FROM tasks WHERE id = ?",
            (task_id,),
        ) as cursor:
            row = await cursor.fetchone()
        if row is None:
            return False
        context_snapshot = _json_loads(row[0], {})
        metadata = _json_loads(row[1], {})
        (
            runtime_resume,
            runtime_metadata,
            permits,
            continuation,
            recorded_runtime_id,
        ) = self._canonicalize_task_runtime_tool_ledger(
            context_snapshot,
            metadata,
        )
        existed = fingerprint in permits
        if not existed and not continue_after_result:
            # A delayed cleanup after the exact permit was already consumed is
            # a true no-op.  In particular, it must not let the old runtime
            # overwrite an inactive Task that has since moved to a new one.
            return False
        if (
            (existed or permits or continuation or continue_after_result)
            and recorded_runtime_id
            and recorded_runtime_id != runtime_session_id
        ):
            raise RuntimeError(
                "task runtime session conflicts with exact ToolCall permit removal"
            )
        if not existed and continuation:
            # The requested continuation is already durable and canonical.
            return False
        permits.pop(fingerprint, None)
        self._write_canonical_task_runtime_tool_ledger(
            context_snapshot,
            metadata,
            runtime_resume=runtime_resume,
            runtime_metadata=runtime_metadata,
            permits=permits,
            continuation=continuation or bool(continue_after_result),
            runtime_session_id=runtime_session_id,
        )
        await self._db.execute(
            "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
            (_json_dumps(context_snapshot), _json_dumps(metadata), task_id),
        )
        return existed

    @staticmethod
    def _owner_interaction_supersession_order(
        interaction: dict[str, Any],
    ) -> tuple[int, ...]:
        """Return the producer-defined durable order for one interaction flow."""

        raw = interaction.get("supersession_order", [])
        if not isinstance(raw, (list, tuple)):
            return (0,)
        normalized: list[int] = []
        for component in raw:
            try:
                normalized.append(max(0, int(component)))
            except (TypeError, ValueError):
                normalized.append(0)
        return tuple(normalized or [0])

    async def allocate_owner_interaction_source_sequence(
        self,
        *,
        project_id: str,
        scope_id: str,
        source_event_id: str,
    ) -> int:
        """Allocate one durable, idempotent order number at turn ingress.

        A retry carrying the same source event receives the same sequence;
        distinct turns are serialized by SQLite, so later producers cannot
        make an older, slower turn look newer by choosing a timestamp or UUID.
        """

        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        scope_id = str(scope_id or "").strip()
        source_event_id = str(source_event_id or "").strip()
        if not scope_id or not source_event_id:
            raise ValueError("scope_id and source_event_id are required")
        self._assert_project_write_scope(
            project_id,
            operation="allocate_owner_interaction_source_sequence",
            entity=f"owner interaction source {source_event_id!r}",
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                """SELECT source_sequence FROM owner_interaction_source_events
                WHERE project_id = ? AND scope_id = ? AND source_event_id = ?""",
                (project_id, scope_id, source_event_id),
            ) as cursor:
                row = await cursor.fetchone()
            if row is not None:
                await self._db.commit()
                return int(row[0])
            async with self._db.execute(
                """SELECT COALESCE(MAX(source_sequence), 0) + 1
                FROM owner_interaction_source_events
                WHERE project_id = ? AND scope_id = ?""",
                (project_id, scope_id),
            ) as cursor:
                next_row = await cursor.fetchone()
            sequence = int(next_row[0] if next_row else 1)
            await self._db.execute(
                """INSERT INTO owner_interaction_source_events
                (project_id, scope_id, source_event_id, source_sequence, created_at)
                VALUES (?, ?, ?, ?, ?)""",
                (
                    project_id,
                    scope_id,
                    source_event_id,
                    sequence,
                    datetime.now().isoformat(),
                ),
            )
            await self._db.commit()
            return sequence
        except Exception:
            await self._db.rollback()
            raise

    async def _select_execution_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str | None = None,
        db: _SQLiteConnectionAdapter | None = None,
    ) -> ExecutionCheckpoint | None:
        target_db = db or self._require_db()
        query = (
            "SELECT * FROM execution_checkpoints "
            "WHERE checkpoint_id = ? AND project_id = ?"
        )
        params: list[Any] = [checkpoint_id, project_id]
        if checkpoint_type is not None:
            query += " AND checkpoint_type = ?"
            params.append(checkpoint_type)
        async with target_db.execute(query, params) as cursor:
            row = await cursor.fetchone()
            if row is None:
                return None
            cols = [description[0] for description in cursor.description]
        return self._execution_checkpoint_from_data(dict(zip(cols, row)))

    async def create_execution_checkpoint(
        self,
        checkpoint: ExecutionCheckpoint,
    ) -> tuple[ExecutionCheckpoint, bool]:
        """Atomically create a checkpoint without replacing an existing row.

        The returned boolean is true only for the controller whose INSERT won.
        Every loser reads the already-persisted row in the same transaction,
        so callers can validate its immutable domain identity before waiting.
        """

        assert self._db
        checkpoint_id = str(checkpoint.checkpoint_id or "").strip()
        project_id = str(checkpoint.project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint.checkpoint_type or "").strip()
        status = str(checkpoint.status or "pending").strip() or "pending"
        if not checkpoint_id or not checkpoint_type:
            raise ValueError("checkpoint_id and checkpoint_type are required")
        if checkpoint_type in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise RuntimeError(
                "owner interactions must use publish_owner_interaction_checkpoint"
            )
        self._assert_project_write_scope(
            project_id,
            operation="create_execution_checkpoint",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        payload = json.loads(_json_dumps(dict(checkpoint.payload or {})))
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            cursor = await self._db.execute(
                """INSERT INTO execution_checkpoints
                (checkpoint_id, project_id, session_id, checkpoint_type, status,
                 task_id, payload, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(checkpoint_id) DO NOTHING""",
                (
                    checkpoint_id,
                    project_id,
                    checkpoint.session_id,
                    checkpoint_type,
                    status,
                    checkpoint.task_id,
                    _json_dumps(payload),
                    checkpoint.created_at.isoformat(),
                    checkpoint.updated_at.isoformat(),
                ),
            )
            created = cursor.rowcount == 1
            persisted = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if persisted is None:
                raise RuntimeError(
                    f"checkpoint_id {checkpoint_id!r} already exists outside "
                    f"project/type scope {project_id!r}/{checkpoint_type!r}"
                )
            await self._db.commit()
            return persisted, created
        except Exception:
            await self._db.rollback()
            raise

    async def create_owner_interaction_checkpoint(
        self,
        checkpoint: ExecutionCheckpoint,
        *,
        interaction_key: str,
    ) -> tuple[ExecutionCheckpoint, bool]:
        """Atomically create-or-get one active owner interaction domain.

        This is the non-superseding form used by permission calls: distinct
        tool-call fingerprints may legitimately be pending at the same time.
        Domain producers that replace an older card must use
        :meth:`publish_owner_interaction_checkpoint`, which performs creation
        and supersession in the same transaction.
        """

        return await self.publish_owner_interaction_checkpoint(
            checkpoint,
            interaction_key=interaction_key,
            supersede_pending_scope=False,
        )

    async def _publish_owner_interaction_checkpoint(
        self,
        checkpoint: ExecutionCheckpoint,
        *,
        interaction_key: str,
        supersede_pending_scope: bool = True,
        supersession_key: str | None = None,
        supersession_order: list[int] | tuple[int, ...] | None = None,
        transaction_open: bool,
        db: _SQLiteConnectionAdapter | None = None,
        reserved_publication_capability: object | None = None,
    ) -> tuple[ExecutionCheckpoint, bool]:
        """Atomically publish one owner interaction and retire older cards.

        Checkpoint ids identify individual rows, while ``interaction_key``
        identifies the domain event that produced the card.  Serializing the
        lookup and insert prevents two controller/process retries from
        publishing duplicate pending cards.  When supersession is enabled,
        the transaction also chooses the producer-ordered latest pending row
        for the same supersession flow and marks every older pending row superseded.  Thus
        concurrent distinct domain revisions cannot supersede each other in
        two separate transactions and leave no active card.

        Permission producers disable scope supersession because independent
        ToolCalls for one task are allowed to wait concurrently.  A terminal
        row is an idempotency tombstone for its exact domain event; a genuinely
        new lifecycle must carry a new source event/domain key.  Answered or
        consuming rows keep their accepted lease while a next-revision pending
        handoff may coexist; the invariant is one *answerable pending* row per
        supersession key, not one row across all active statuses.
        """

        if transaction_open != (db is not None):
            raise ValueError(
                "owner publication transaction_open must match an injected db"
            )
        target_db = db or self._require_db()
        checkpoint_id = str(checkpoint.checkpoint_id or "").strip()
        project_id = str(checkpoint.project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint.checkpoint_type or "").strip()
        interaction_key = str(interaction_key or "").strip()
        supersession_key = str(supersession_key or "").strip()
        normalized_order = tuple(
            max(0, int(component)) for component in (supersession_order or (0,))
        )
        if not checkpoint_id or not checkpoint_type or not interaction_key:
            raise ValueError(
                "checkpoint_id, checkpoint_type, and interaction_key are required"
            )
        if checkpoint_type not in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise ValueError("owner publication requires an owner checkpoint type")
        if str(checkpoint.status or "pending").strip() != "pending":
            raise ValueError("new owner interaction must start pending")
        self._assert_project_write_scope(
            project_id,
            operation="publish_owner_interaction_checkpoint",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        payload = json.loads(_json_dumps(dict(checkpoint.payload or {})))
        has_reserved_provenance = (
            FINAL_DELIVERY_PUBLICATION_PROVENANCE_KEY in payload
        )
        has_gate_provenance = (
            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY in payload
        )
        final_capability_valid = (
            reserved_publication_capability
            is _FINAL_DELIVERY_PUBLICATION_CAPABILITY
        )
        gate_capability_valid = (
            reserved_publication_capability
            is _COMPANY_WORK_ITEM_GATE_PUBLICATION_CAPABILITY
        )
        if has_reserved_provenance and not final_capability_valid:
            raise ValueError(
                "final-delivery publication provenance is reserved for the "
                "controller authoritative transaction"
            )
        if has_gate_provenance and not gate_capability_valid:
            raise ValueError(
                "work-item gate publication provenance is reserved for the "
                "controller authoritative transaction"
            )
        if final_capability_valid and (
            not transaction_open
            or checkpoint_type != "company_delivery_feedback"
            or not has_reserved_provenance
        ):
            raise ValueError(
                "final-delivery publication capability is valid only for an "
                "authoritative feedback publication"
            )
        if gate_capability_valid and (
            not transaction_open
            or checkpoint_type != "company_work_item_gate"
            or not has_gate_provenance
        ):
            raise ValueError(
                "work-item gate publication capability is valid only for an "
                "authoritative gate publication"
            )
        interaction = self._execution_checkpoint_interaction(payload)
        if any(
            key in interaction
            for key in ("decision", "claim", "completion", "execution")
        ):
            raise ValueError(
                "new owner interaction cannot prefill decision/claim/execution state"
            )
        recorded_key = str(interaction.get("domain_key", "") or "").strip()
        if recorded_key and recorded_key != interaction_key:
            raise ValueError("payload interaction.domain_key does not match interaction_key")
        interaction["domain_key"] = interaction_key
        if supersession_key:
            recorded_supersession_key = str(
                interaction.get("supersession_key", "") or ""
            ).strip()
            if (
                recorded_supersession_key
                and recorded_supersession_key != supersession_key
            ):
                raise ValueError(
                    "payload interaction.supersession_key does not match supersession_key"
                )
            interaction["supersession_key"] = supersession_key
        recorded_order = interaction.get("supersession_order")
        if recorded_order not in (None, [], ()):
            if self._owner_interaction_supersession_order(interaction) != normalized_order:
                raise ValueError(
                    "payload interaction.supersession_order does not match supersession_order"
                )
        interaction["supersession_order"] = list(normalized_order)
        payload["interaction"] = interaction
        try:
            if not transaction_open:
                await target_db.execute("BEGIN IMMEDIATE")
            async with target_db.execute(
                """SELECT * FROM execution_checkpoints
                WHERE project_id = ? AND checkpoint_type = ?
                ORDER BY created_at ASC, checkpoint_id ASC""",
                (project_id, checkpoint_type),
            ) as cursor:
                rows = await cursor.fetchall()
                columns = [description[0] for description in cursor.description]
            for row in rows:
                existing = self._execution_checkpoint_from_data(
                    dict(zip(columns, row))
                )
                existing_interaction = self._execution_checkpoint_interaction(
                    dict(existing.payload or {})
                )
                if (
                    str(existing_interaction.get("domain_key", "") or "").strip()
                    != interaction_key
                ):
                    continue
                if (
                    str(existing.task_id or "") != str(checkpoint.task_id or "")
                    or str(existing.session_id or "")
                    != str(checkpoint.session_id or "")
                ):
                    raise RuntimeError(
                        "active owner interaction domain key has conflicting ownership"
                    )
                if final_capability_valid:
                    incoming_provenance = payload.get(
                        FINAL_DELIVERY_PUBLICATION_PROVENANCE_KEY
                    )
                    if not isinstance(incoming_provenance, dict):
                        raise RuntimeError(
                            "authoritative final publication lacks valid provenance"
                        )
                    try:
                        publication_identity = {
                            "run_id": str(
                                incoming_provenance.get("run_id", "") or ""
                            ).strip(),
                            "task_id": str(
                                incoming_provenance.get("task_id", "") or ""
                            ).strip(),
                            "work_item_id": str(
                                incoming_provenance.get("work_item_id", "") or ""
                            ).strip(),
                            "attempt_seq": int(
                                incoming_provenance.get(
                                    "work_item_attempt_seq", 0
                                )
                                or 0
                            ),
                            "package_hash": str(
                                incoming_provenance.get(
                                    "delivery_package_sha256", ""
                                )
                                or ""
                            ).strip(),
                        }
                    except (TypeError, ValueError) as exc:
                        raise RuntimeError(
                            "authoritative final publication has malformed provenance"
                        ) from exc
                    existing_payload = dict(existing.payload or {})
                    if (
                        not final_delivery_checkpoint_payload_matches(
                            payload,
                            **publication_identity,
                        )
                        or not final_delivery_checkpoint_payload_matches(
                            existing_payload,
                            **publication_identity,
                        )
                    ):
                        raise RuntimeError(
                            "active final-delivery interaction conflicts with "
                            "the authoritative publication basis"
                        )
                if gate_capability_valid:
                    existing_payload = dict(existing.payload or {})
                    incoming_provenance = dict(
                        payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    )
                    existing_provenance = dict(
                        existing_payload.get(
                            COMPANY_WORK_ITEM_GATE_PUBLICATION_PROVENANCE_KEY,
                            {},
                        )
                        or {}
                    )
                    if not (
                        _company_work_item_gate_publication_provenance_matches(
                            payload
                        )
                        and _company_work_item_gate_publication_provenance_matches(
                            existing_payload
                        )
                        and incoming_provenance == existing_provenance
                        and dict(payload.get("gate", {}) or {})
                        == dict(existing_payload.get("gate", {}) or {})
                        and str(payload.get("basis_hash", "") or "").strip()
                        == str(
                            existing_payload.get("basis_hash", "") or ""
                        ).strip()
                    ):
                        raise RuntimeError(
                            "active work-item gate interaction conflicts with "
                            "the authoritative publication basis"
                        )
                if not transaction_open:
                    await target_db.commit()
                return existing, False

            await target_db.execute(
                """INSERT INTO execution_checkpoints
                (checkpoint_id, project_id, session_id, checkpoint_type, status,
                 task_id, payload, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    checkpoint_id,
                    project_id,
                    checkpoint.session_id,
                    checkpoint_type,
                    str(checkpoint.status or "pending").strip() or "pending",
                    checkpoint.task_id,
                    _json_dumps(payload),
                    checkpoint.created_at.isoformat(),
                    checkpoint.updated_at.isoformat(),
                ),
            )

            if supersede_pending_scope and supersession_key:
                async with target_db.execute(
                    """SELECT * FROM execution_checkpoints
                    WHERE project_id = ? AND checkpoint_type = ?
                      AND status = 'pending'
                    ORDER BY checkpoint_id ASC""",
                    (project_id, checkpoint_type),
                ) as cursor:
                    raw_pending_rows = await cursor.fetchall()
                    pending_columns = [
                        description[0] for description in cursor.description
                    ]
                pending_rows: list[tuple[Any, tuple[int, ...], str]] = []
                for pending_row in raw_pending_rows:
                    pending_data = dict(zip(pending_columns, pending_row))
                    pending_payload = _json_loads(
                        pending_data.get("payload"),
                        {},
                    )
                    pending_interaction = self._execution_checkpoint_interaction(
                        pending_payload
                    )
                    if str(
                        pending_interaction.get("supersession_key", "") or ""
                    ).strip() == supersession_key:
                        pending_rows.append(
                            (
                                pending_row,
                                self._owner_interaction_supersession_order(
                                    pending_interaction
                                ),
                                str(
                                    pending_interaction.get("domain_key", "") or ""
                                ).strip(),
                            )
                        )
                if pending_rows:
                    pending_rows.sort(
                        key=lambda item: (
                            item[1],
                            item[2],
                            str(
                                dict(zip(pending_columns, item[0])).get(
                                    "checkpoint_id", ""
                                )
                                or ""
                            ),
                        ),
                        reverse=True,
                    )
                    winner_data = dict(zip(pending_columns, pending_rows[0][0]))
                    winner_id = str(
                        winner_data.get("checkpoint_id", "") or ""
                    ).strip()
                    now = datetime.now().isoformat()
                    for row, _, _ in pending_rows[1:]:
                        row_data = dict(zip(pending_columns, row))
                        loser_id = str(
                            row_data.get("checkpoint_id", "") or ""
                        ).strip()
                        if not loser_id:
                            continue
                        loser_payload = _json_loads(row_data.get("payload"), {})
                        loser_payload["superseded_at"] = now
                        loser_payload["superseded_by_checkpoint_id"] = winner_id
                        await target_db.execute(
                            """UPDATE execution_checkpoints
                            SET status = 'superseded', payload = ?, updated_at = ?
                            WHERE checkpoint_id = ? AND project_id = ?
                              AND checkpoint_type = ? AND status = 'pending'""",
                            (
                                _json_dumps(loser_payload),
                                now,
                                loser_id,
                                project_id,
                                checkpoint_type,
                            ),
                        )

            persisted = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
                db=target_db,
            )
            if persisted is None:
                raise RuntimeError(
                    f"owner interaction {checkpoint_id!r} disappeared during publication"
                )
            if not transaction_open:
                await target_db.commit()
            return persisted, True
        except Exception:
            if not transaction_open:
                await target_db.rollback()
            raise

    async def publish_owner_interaction_checkpoint(
        self,
        checkpoint: ExecutionCheckpoint,
        *,
        interaction_key: str,
        supersede_pending_scope: bool = True,
        supersession_key: str | None = None,
        supersession_order: list[int] | tuple[int, ...] | None = None,
    ) -> tuple[ExecutionCheckpoint, bool]:
        """Publish through the canonical owner transaction implementation."""

        return await self._publish_owner_interaction_checkpoint(
            checkpoint,
            interaction_key=interaction_key,
            supersede_pending_scope=supersede_pending_scope,
            supersession_key=supersession_key,
            supersession_order=supersession_order,
            transaction_open=False,
        )

    async def get_execution_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str = "default",
        checkpoint_type: str | None = None,
    ) -> ExecutionCheckpoint | None:
        """Return exactly one checkpoint inside its project/type scope."""

        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        clean_type = (
            str(checkpoint_type or "").strip() if checkpoint_type is not None else None
        )
        if not checkpoint_id:
            return None
        if checkpoint_type is not None and not clean_type:
            return None
        return await self._select_execution_checkpoint(
            checkpoint_id,
            project_id=project_id,
            checkpoint_type=clean_type,
        )

    async def patch_execution_checkpoint_payload(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        expected_statuses: list[str] | tuple[str, ...] | set[str],
        payload_patch: dict[str, Any] | None = None,
        status: str | None = None,
        updated_at: datetime | None = None,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """Merge a non-owner checkpoint patch with a scoped status CAS."""

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        expected = {
            str(item or "").strip()
            for item in expected_statuses
            if str(item or "").strip()
        }
        patch = dict(payload_patch or {})
        if not checkpoint_id or not checkpoint_type or not expected:
            raise ValueError(
                "checkpoint_id, checkpoint_type, and expected_statuses are required"
            )
        if "interaction" in patch:
            raise ValueError("payload_patch cannot modify Store-owned interaction metadata")
        if checkpoint_type in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise RuntimeError(
                "owner interactions require typed coordinator enrichment/closure"
            )
        target_status = str(status or "").strip()
        self._assert_project_write_scope(
            project_id,
            operation="patch_execution_checkpoint_payload",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = updated_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return None, False
            if checkpoint.status not in expected:
                await self._db.commit()
                return checkpoint, False
            next_payload = self._merge_execution_checkpoint_payload(
                dict(checkpoint.payload or {}),
                patch,
            )
            next_status = target_status or checkpoint.status
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = ?, payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = ?""",
                (
                    next_status,
                    _json_dumps(next_payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                    checkpoint.status,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                current = await self._select_execution_checkpoint(
                    checkpoint_id,
                    project_id=project_id,
                    checkpoint_type=checkpoint_type,
                )
                return current, False
            await self._db.commit()
            return self._checkpoint_with(
                checkpoint,
                status=next_status,
                payload=next_payload,
                updated_at=now,
            ), True
        except Exception:
            await self._db.rollback()
            raise

    async def enrich_owner_interaction_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        expected_statuses: list[str] | tuple[str, ...] | set[str],
        payload_patch: dict[str, Any],
        updated_at: datetime | None = None,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """CAS a narrow set of execution/migration projections onto an owner row."""

        allowed = {
            "runtime_v2",
            "runtime_session_id",
            "resume_cursor",
            "active_subagents",
            "permission_requests",
            "compaction_boundaries",
            "worktree_path",
            "migrated_to_runtime_v2",
            "org_version",
            "runtime_topology_version",
            "reorg_proposal_id",
        }
        patch = dict(payload_patch or {})
        unknown = set(patch) - allowed
        if unknown:
            raise ValueError(
                "owner enrichment contains unsupported fields: "
                + ", ".join(sorted(unknown))
            )
        return await self._patch_owner_interaction_checkpoint(
            checkpoint_id,
            project_id=project_id,
            checkpoint_type=checkpoint_type,
            expected_statuses=expected_statuses,
            payload_patch=patch,
            status=None,
            updated_at=updated_at,
        )

    async def backfill_owner_interaction_ownership(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        expected_statuses: list[str] | tuple[str, ...] | set[str],
        ownership: dict[str, Any],
        updated_at: datetime | None = None,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """CAS canonical actor fields onto a legacy owner row once.

        This upgrade path is intentionally narrower than generic enrichment:
        it only fills an interaction whose durable actor is absent.  A
        non-empty recorded actor is never rewritten, even when invalid, so a
        historical child-as-owner row remains fail-closed for explicit repair.
        """

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        expected = {
            str(item or "").strip()
            for item in expected_statuses
            if str(item or "").strip()
        }
        self._require_owner_interaction_type(
            checkpoint_type,
            operation="backfill_owner_interaction_ownership",
        )
        if not checkpoint_id or not expected:
            raise ValueError("checkpoint_id and expected_statuses are required")
        allowed_fields = {
            "ui_anchor_task_id",
            "ui_anchor_session_id",
            "waiting_task_id",
            "waiting_session_id",
            "execution_parent_task_id",
            "execution_parent_session_id",
            "root_session_id",
            "company_runtime_session_id",
        }
        normalized = {
            str(key): str(value or "").strip()
            for key, value in dict(ownership or {}).items()
            if str(key) in allowed_fields
        }
        unknown = set(dict(ownership or {})) - allowed_fields
        if unknown:
            raise ValueError(
                "owner ownership backfill contains unsupported fields: "
                + ", ".join(sorted(str(item) for item in unknown))
            )
        if not normalized.get("ui_anchor_session_id") and not normalized.get(
            "root_session_id"
        ):
            raise ValueError("owner ownership backfill requires a durable session actor")
        now = updated_at or datetime.now()
        actor_fields = {
            "ui_anchor_task_id",
            "ui_anchor_session_id",
            "root_session_id",
            "company_runtime_session_id",
        }
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return None, False
            if checkpoint.status not in expected:
                await self._db.commit()
                return checkpoint, False
            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            current_ownership = dict(interaction.get("ownership", {}) or {})
            if any(
                str(current_ownership.get(field, "") or "").strip()
                for field in actor_fields
            ):
                await self._db.commit()
                return checkpoint, False
            interaction["ownership"] = {
                **current_ownership,
                **normalized,
            }
            payload["interaction"] = interaction
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = ?""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                    checkpoint.status,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return checkpoint, False
            await self._db.commit()
            return self._checkpoint_with(
                checkpoint,
                status=checkpoint.status,
                payload=payload,
                updated_at=now,
            ), True
        except Exception:
            await self._db.rollback()
            raise

    async def close_pending_owner_interaction_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        status: str,
        payload_patch: dict[str, Any] | None = None,
        updated_at: datetime | None = None,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """Administratively close an unanswered owner row; never consume a decision."""

        terminal = str(status or "").strip()
        allowed_statuses = {
            "stale",
            "superseded",
            "cancelled",
            "canceled",
            "invalid",
            "ignored",
            "failed",
            "expired",
            "timeout",
            "timed_out",
        }
        if terminal not in allowed_statuses:
            raise ValueError("unsupported owner administrative terminal status")
        allowed_fields = {
            "feedback_superseded",
            "feedback_superseded_at",
            "feedback_resolution",
            "checkpoint_resolution_reason",
            "superseded_by_company_turn",
            "stale_reason",
            "stale_at",
            "administrative_reason",
            "administrative_closed_at",
        }
        patch = dict(payload_patch or {})
        unknown = set(patch) - allowed_fields
        if unknown:
            raise ValueError(
                "owner administrative closure contains unsupported fields: "
                + ", ".join(sorted(unknown))
            )
        return await self._patch_owner_interaction_checkpoint(
            checkpoint_id,
            project_id=project_id,
            checkpoint_type=checkpoint_type,
            expected_statuses={"pending"},
            payload_patch=patch,
            status=terminal,
            updated_at=updated_at,
        )

    async def supersede_pending_delivery_review_for_company_turn(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        root_session_id: str,
        conversation_turn_id: str,
        superseded_at: datetime | None = None,
    ) -> DeliveryReviewSupersessionReceipt:
        """Atomically supersede a delivery card and close its waiting Task.

        The persisted conversation turn is the idempotency key.  A competing
        owner answer can win the checkpoint CAS instead; in that case this
        transition leaves the Task untouched.
        """

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        root_session_id = str(root_session_id or "").strip()
        conversation_turn_id = str(conversation_turn_id or "").strip()
        if not checkpoint_id or not root_session_id or not conversation_turn_id:
            raise ValueError(
                "checkpoint_id, root_session_id, and conversation_turn_id are required"
            )
        self._assert_project_write_scope(
            project_id,
            operation="supersede_pending_delivery_review_for_company_turn",
            entity=f"delivery checkpoint {checkpoint_id!r}",
        )
        now = superseded_at or datetime.now()
        now_text = now.isoformat()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type="company_delivery_feedback",
            )
            if checkpoint is None:
                await self._db.commit()
                return DeliveryReviewSupersessionReceipt(outcome="not_found")

            payload = dict(checkpoint.payload or {})
            interaction = dict(payload.get("interaction", {}) or {})
            ownership = dict(interaction.get("ownership", {}) or {})
            prior_transition = dict(
                payload.get("superseded_by_company_turn", {}) or {}
            )
            if checkpoint.status != "pending":
                outcome = (
                    "duplicate"
                    if checkpoint.status == "superseded"
                    and str(
                        prior_transition.get("conversation_turn_id", "") or ""
                    ).strip()
                    == conversation_turn_id
                    else "invalid_state"
                )
                durable_task_id = str(
                    payload.get("waiting_task_id")
                    or payload.get("task_id")
                    or checkpoint.task_id
                    or ""
                ).strip()
                task = (
                    await self._get_task_unhydrated(durable_task_id)
                    if durable_task_id
                    else None
                )
                await self._db.commit()
                return DeliveryReviewSupersessionReceipt(
                    outcome=outcome,
                    checkpoint=checkpoint,
                    task=task,
                )

            durable_task_ids = {
                str(value or "").strip()
                for value in (
                    checkpoint.task_id,
                    payload.get("waiting_task_id"),
                    payload.get("task_id"),
                    ownership.get("waiting_task_id"),
                )
                if str(value or "").strip()
            }
            if len(durable_task_ids) != 1:
                await self._db.commit()
                return DeliveryReviewSupersessionReceipt(
                    outcome="invalid_task_scope",
                    checkpoint=checkpoint,
                )
            waiting_task_id = next(iter(durable_task_ids))
            waiting_task = await self._get_task_unhydrated(waiting_task_id)
            if waiting_task is None or (
                str(waiting_task.project_id or "default").strip() or "default"
            ) != project_id:
                await self._db.commit()
                return DeliveryReviewSupersessionReceipt(
                    outcome="task_not_found",
                    checkpoint=checkpoint,
                )

            durable_root_session_id = str(
                ownership.get("root_session_id")
                or ownership.get("company_runtime_session_id")
                or payload.get("parent_session_id")
                or waiting_task.parent_session_id
                or waiting_task.metadata.get("parent_session_id")
                or checkpoint.session_id
                or ""
            ).strip()
            if durable_root_session_id != root_session_id:
                await self._db.commit()
                return DeliveryReviewSupersessionReceipt(
                    outcome="scope_mismatch",
                    checkpoint=checkpoint,
                    task=waiting_task,
                )

            next_payload = self._merge_execution_checkpoint_payload(
                payload,
                {
                    "feedback_superseded": True,
                    "feedback_superseded_at": now_text,
                    "feedback_resolution": "new_company_turn_started",
                    "checkpoint_resolution_reason": "new_company_turn_started",
                    "superseded_by_company_turn": {
                        "conversation_turn_id": conversation_turn_id,
                        "root_session_id": root_session_id,
                        "prior_delivery_revision": payload.get(
                            "delivery_revision"
                        ),
                        "prior_basis_hash": str(
                            payload.get("basis_hash", "") or ""
                        ),
                    },
                },
            )
            closed_task, close_updates = (
                await self._close_company_delivery_review_task_row(
                    task_id=waiting_task_id,
                    project_id=project_id,
                    resolution="new_company_turn_started",
                    closed_at=now_text,
                    checkpoint_id=checkpoint.checkpoint_id,
                    metadata_updates={
                        "feedback_superseded": True,
                        "feedback_superseded_at": now_text,
                        "feedback_superseded_by_turn_id": conversation_turn_id,
                    },
                )
            )
            if closed_task is None:
                raise RuntimeError("delivery review task disappeared during transition")
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = 'superseded', payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = 'company_delivery_feedback'
                  AND status = 'pending'""",
                (
                    _json_dumps(next_payload),
                    now_text,
                    checkpoint.checkpoint_id,
                    project_id,
                ),
            )
            if cursor.rowcount != 1:
                raise RuntimeError("delivery review checkpoint CAS was lost")
            await self._db.commit()
            return DeliveryReviewSupersessionReceipt(
                outcome="applied",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="superseded",
                    payload=next_payload,
                    updated_at=now,
                ),
                task=closed_task,
                task_close_updates=close_updates,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def _patch_owner_interaction_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        expected_statuses: list[str] | tuple[str, ...] | set[str],
        payload_patch: dict[str, Any],
        status: str | None,
        updated_at: datetime | None,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """Store primitive used only by the typed owner coordinator facade."""

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        expected = {
            str(item or "").strip()
            for item in expected_statuses
            if str(item or "").strip()
        }
        if checkpoint_type not in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise ValueError("typed owner mutation requires an owner checkpoint type")
        if not checkpoint_id or not expected:
            raise ValueError("checkpoint_id and expected_statuses are required")
        _reject_reserved_final_publication_patch(payload_patch)
        now = updated_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return None, False
            if checkpoint.status not in expected:
                await self._db.commit()
                return checkpoint, False
            next_payload = self._merge_execution_checkpoint_payload(
                dict(checkpoint.payload or {}),
                dict(payload_patch or {}),
            )
            _require_reserved_final_publication_unchanged(
                dict(checkpoint.payload or {}),
                next_payload,
            )
            next_status = str(status or checkpoint.status).strip()
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = ?, payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = ?""",
                (
                    next_status,
                    _json_dumps(next_payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                    checkpoint.status,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return checkpoint, False
            await self._db.commit()
            return self._checkpoint_with(
                checkpoint,
                status=next_status,
                payload=next_payload,
                updated_at=now,
            ), True
        except Exception:
            await self._db.rollback()
            raise

    async def accept_execution_checkpoint_decision(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        request_id: str,
        decision_hash: str,
        decision: Any,
        submitted_at: datetime | None = None,
    ) -> ExecutionCheckpointDecisionReceipt:
        """Durably accept one immutable answer for a pending checkpoint.

        The decision hash + value is idempotent across controllers.  A
        ``request_id`` correlates an individual transport ACK, so a reconnect
        may safely retry the same decision with a new id.  Any different answer
        conflicts instead of replacing the first accepted decision.  The
        domain payload is merged from the row read under ``BEGIN IMMEDIATE`` so
        unrelated metadata is never lost.
        """

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        request_id = str(request_id or "").strip()
        decision_hash = str(decision_hash or "").strip()
        if (
            not checkpoint_id
            or not checkpoint_type
            or not request_id
            or not decision_hash
        ):
            raise ValueError(
                "checkpoint_id, checkpoint_type, request_id, and decision_hash are required"
            )
        self._require_owner_interaction_type(
            checkpoint_type,
            operation="accept_execution_checkpoint_decision",
        )
        self._assert_project_write_scope(
            project_id,
            operation="accept_execution_checkpoint_decision",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        # Normalize the value to the representation that SQLite will return.
        decision_value = json.loads(_json_dumps(decision))
        now = submitted_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointDecisionReceipt(outcome="not_found")

            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            existing = interaction.get("decision")
            if isinstance(existing, dict):
                same_decision = (
                    str(existing.get("decision_hash", "") or "") == decision_hash
                    and existing.get("value") == decision_value
                )
                await self._db.commit()
                return ExecutionCheckpointDecisionReceipt(
                    outcome="duplicate" if same_decision else "conflict",
                    checkpoint=checkpoint,
                )
            if checkpoint.status != "pending":
                await self._db.commit()
                return ExecutionCheckpointDecisionReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )

            if checkpoint_type == "task_user_input":
                waiting_task_id = str(
                    checkpoint.task_id
                    or payload.get("task_id")
                    or payload.get("waiting_task_id")
                    or ""
                ).strip()
                if waiting_task_id:
                    waiting_task = await self._get_task_unhydrated(waiting_task_id)
                    waiting_status = (
                        str(waiting_task.status.value).strip().lower()
                        if waiting_task is not None
                        else ""
                    )
                    waiting_project = (
                        str(waiting_task.project_id or "default").strip()
                        if waiting_task is not None
                        else ""
                    )
                    if waiting_task is None or waiting_project != project_id or (
                        waiting_status in self._terminal_task_statuses()
                    ):
                        stale_reason = (
                            f"task {waiting_task_id} settled as {waiting_status}"
                            if waiting_task is not None
                            and waiting_project == project_id
                            else f"task {waiting_task_id} no longer exists"
                        )
                        stale_payload = self._merge_execution_checkpoint_payload(
                            payload,
                            {
                                "stale_reason": stale_reason,
                                "stale_at": now.isoformat(),
                            },
                        )
                        cursor = await self._db.execute(
                            """UPDATE execution_checkpoints
                            SET status = 'stale', payload = ?, updated_at = ?
                            WHERE checkpoint_id = ? AND project_id = ?
                              AND checkpoint_type = 'task_user_input'
                              AND status = 'pending'""",
                            (
                                _json_dumps(stale_payload),
                                now.isoformat(),
                                checkpoint_id,
                                project_id,
                            ),
                        )
                        if cursor.rowcount != 1:
                            await self._db.rollback()
                            return ExecutionCheckpointDecisionReceipt(
                                outcome="conflict",
                                checkpoint=checkpoint,
                            )
                        await self._db.commit()
                        return ExecutionCheckpointDecisionReceipt(
                            outcome="invalid_state",
                            checkpoint=self._checkpoint_with(
                                checkpoint,
                                status="stale",
                                payload=stale_payload,
                                updated_at=now,
                            ),
                        )

            interaction["decision"] = {
                "request_id": request_id,
                "decision_hash": decision_hash,
                "value": decision_value,
                "submitted_at": now.isoformat(),
            }
            if checkpoint_type == "tool_permission":
                interaction["decision"][
                    "canonical_tool_permission_token"
                ] = canonical_tool_permission_decision(decision_value)
            payload["interaction"] = interaction
            _require_reserved_final_publication_unchanged(
                dict(checkpoint.payload or {}),
                payload,
            )
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = 'answered', payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = 'pending'""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointDecisionReceipt(
                    outcome="conflict",
                    checkpoint=checkpoint,
                )
            await self._db.commit()
            return ExecutionCheckpointDecisionReceipt(
                outcome="accepted",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="answered",
                    payload=payload,
                    updated_at=now,
                ),
            )
        except Exception:
            await self._db.rollback()
            raise

    async def _execution_checkpoint_company_run_scope(
        self,
        checkpoint: ExecutionCheckpoint,
        *,
        payload: dict[str, Any],
        project_id: str,
    ) -> tuple[str, bool]:
        """Resolve one checkpoint's canonical company run inside a transaction.

        Owner interactions predate the controller lease and consequently do
        not have a dedicated run-id column.  Newer rows carry it directly or
        in interaction ownership; older rows are resolved through their
        durable waiting Task and canonical WorkItem link.  Conflicting
        identities fail closed instead of choosing whichever copy happened to
        be read first.
        """

        assert self._db
        run_ids: set[str] = set()

        def add_run_id(value: Any) -> None:
            clean = str(value or "").strip()
            if clean:
                run_ids.add(clean)

        interaction = self._execution_checkpoint_interaction(payload)
        ownership = dict(interaction.get("ownership", {}) or {})
        for source in (payload, ownership):
            add_run_id(source.get("delegation_run_id"))
            add_run_id(source.get("company_run_id"))
            add_run_id(source.get("run_id"))

        task_ids: set[str] = set()

        def add_task_id(value: Any) -> None:
            clean = str(value or "").strip()
            if clean:
                task_ids.add(clean)

        add_task_id(checkpoint.task_id)
        for source in (payload, ownership):
            add_task_id(source.get("waiting_task_id"))
            add_task_id(source.get("task_id"))
            add_task_id(source.get("origin_task_id"))
        for raw_task_id in list(payload.get("task_ids", []) or []):
            add_task_id(raw_task_id)

        for task_id in sorted(task_ids):
            async with self._db.execute(
                "SELECT project_id, metadata FROM tasks WHERE id = ?",
                (task_id,),
            ) as task_cursor:
                task_row = await task_cursor.fetchone()
            if task_row is not None:
                task_project_id = str(task_row[0] or "default").strip() or "default"
                if task_project_id != project_id:
                    return "", True
                task_metadata = _json_loads(task_row[1], {})
                if isinstance(task_metadata, dict):
                    add_run_id(task_metadata.get("delegation_run_id"))
                    add_run_id(task_metadata.get("company_run_id"))

            async with self._db.execute(
                """SELECT item.run_id
                   FROM work_item_runtime_links AS link
                   JOIN delegation_work_items AS item
                     ON item.work_item_id = link.work_item_id
                   JOIN delegation_runs AS run
                     ON run.run_id = item.run_id
                   WHERE link.runtime_task_id = ?
                     AND run.project_id = ?""",
                (task_id, project_id),
            ) as link_cursor:
                linked_rows = await link_cursor.fetchall()
            for linked_row in linked_rows:
                add_run_id(linked_row[0])

        if len(run_ids) > 1:
            return "", True
        return (next(iter(run_ids)) if run_ids else ""), False

    async def claim_answered_execution_checkpoint(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        consumer_id: str,
        claim_id: str | None = None,
        lease_seconds: float = 60.0,
        claimed_at: datetime | None = None,
        enforce_company_controller_eligibility: bool = False,
        controller_run_id: str | None = None,
        controller_root_session_id: str | None = None,
        controller_owner_token: str | None = None,
        controller_lease_generation: int | None = None,
    ) -> ExecutionCheckpointClaimReceipt:
        """Acquire or recover the consumption lease for an accepted answer.

        Recovery consumers use ``enforce_company_controller_eligibility``.
        For a checkpoint attached to a company run, the run-lease lookup and
        the answered -> consuming claim then happen under this same
        ``BEGIN IMMEDIATE``.  A live remote controller wins without any
        checkpoint mutation; a matching local generation, or the absence of
        a live controller, may continue.  The ordinary live waiter path does
        not use this recovery fence because it already owns the interaction
        future that produced the answer.
        """

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        consumer_id = str(consumer_id or "").strip()
        requested_claim_id = str(claim_id or uuid.uuid4()).strip()
        if (
            not checkpoint_id
            or not checkpoint_type
            or not consumer_id
            or not requested_claim_id
        ):
            raise ValueError(
                "checkpoint_id, checkpoint_type, consumer_id, and claim_id are required"
            )
        self._require_owner_interaction_type(
            checkpoint_type,
            operation="claim_answered_execution_checkpoint",
        )
        if float(lease_seconds) <= 0:
            raise ValueError("lease_seconds must be positive")
        self._assert_project_write_scope(
            project_id,
            operation="claim_answered_execution_checkpoint",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = claimed_at or datetime.now()
        lease_expires_at = now + timedelta(seconds=float(lease_seconds))
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(outcome="not_found")

            payload = dict(checkpoint.payload or {})
            if enforce_company_controller_eligibility:
                (
                    associated_run_id,
                    run_scope_conflict,
                ) = await self._execution_checkpoint_company_run_scope(
                    checkpoint,
                    payload=payload,
                    project_id=project_id,
                )
                if run_scope_conflict:
                    await self._db.commit()
                    return ExecutionCheckpointClaimReceipt(
                        outcome="invalid_state",
                        checkpoint=checkpoint,
                    )
                if associated_run_id:
                    async with self._db.execute(
                        """SELECT session_id, controller_owner_token,
                                  controller_lease_generation
                           FROM delegation_runs
                           WHERE run_id = ? AND project_id = ?
                             AND COALESCE(controller_owner_token, '') != ''
                             AND COALESCE(controller_lease_expires_at, '') > ?""",
                        (
                            associated_run_id,
                            project_id,
                            now.isoformat(),
                        ),
                    ) as controller_cursor:
                        live_controller = await controller_cursor.fetchone()
                    if live_controller is not None:
                        live_root_session_id = str(
                            live_controller[0] or ""
                        ).strip()
                        live_owner_token = str(
                            live_controller[1] or ""
                        ).strip()
                        live_generation = int(live_controller[2] or 0)
                        local_matches = (
                            str(controller_run_id or "").strip()
                            == associated_run_id
                            and str(controller_root_session_id or "").strip()
                            == live_root_session_id
                            and str(controller_owner_token or "").strip()
                            == live_owner_token
                            and int(controller_lease_generation or 0)
                            == live_generation
                        )
                        if not local_matches:
                            await self._db.commit()
                            return ExecutionCheckpointClaimReceipt(
                                outcome="controller_busy",
                                checkpoint=checkpoint,
                            )
            interaction = self._execution_checkpoint_interaction(payload)
            if not isinstance(interaction.get("decision"), dict):
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )

            prior_claim = interaction.get("claim")
            outcome = "claimed"
            expected_statuses = ["answered"]
            if checkpoint.status == "consuming":
                if not isinstance(prior_claim, dict):
                    prior_claim = {}
                prior_claim_id = str(prior_claim.get("claim_id", "") or "")
                prior_consumer_id = str(prior_claim.get("consumer_id", "") or "")
                raw_expiry = str(prior_claim.get("lease_expires_at", "") or "")
                try:
                    prior_expiry = datetime.fromisoformat(raw_expiry)
                    lease_expired = prior_expiry.timestamp() <= now.timestamp()
                except (TypeError, ValueError, OSError):
                    lease_expired = True
                if (
                    not lease_expired
                    and prior_claim_id == requested_claim_id
                    and prior_consumer_id == consumer_id
                ):
                    await self._db.commit()
                    return ExecutionCheckpointClaimReceipt(
                        outcome="duplicate",
                        checkpoint=checkpoint,
                        claim_id=requested_claim_id,
                    )
                if not lease_expired:
                    await self._db.commit()
                    return ExecutionCheckpointClaimReceipt(
                        outcome="busy",
                        checkpoint=checkpoint,
                        claim_id=prior_claim_id,
                    )
                prior_execution = interaction.get("execution")
                tool_call = dict(payload.get("tool_call", {}) or {})
                tool_runtime_session_id = str(
                    tool_call.get("runtime_session_id", "") or ""
                ).strip()
                tool_call_id = str(tool_call.get("id", "") or "").strip()
                tool_fingerprint = str(
                    tool_call.get("fingerprint", "") or ""
                ).strip()
                tool_task_id = str(
                    checkpoint.task_id
                    or dict(interaction.get("ownership", {}) or {}).get(
                        "waiting_task_id"
                    )
                    or ""
                ).strip()
                result_persisted = False
                if (
                    checkpoint_type == "tool_permission"
                    and tool_runtime_session_id
                    and tool_call_id
                ):
                    async with self._db.execute(
                        """SELECT 1 FROM runtime_tool_results
                           WHERE runtime_session_id = ? AND tool_call_id = ? LIMIT 1""",
                        (tool_runtime_session_id, tool_call_id),
                    ) as result_cursor:
                        result_persisted = await result_cursor.fetchone() is not None
                if result_persisted:
                    # The exact result ledger is authoritative.  Reconcile the
                    # old three-transaction crash shape instead of reporting
                    # an unknown outcome or replaying the external call.
                    await self._remove_task_runtime_tool_permit_in_transaction(
                        task_id=tool_task_id,
                        runtime_session_id=tool_runtime_session_id,
                        fingerprint=tool_fingerprint,
                        continue_after_result=True,
                    )
                    await self._db.execute(
                        """DELETE FROM runtime_tool_continuations
                           WHERE project_id = ? AND task_id = ?
                             AND runtime_session_id = ?
                             AND lease_expires_at <= ?""",
                        (
                            project_id,
                            tool_task_id,
                            tool_runtime_session_id,
                            now.isoformat(),
                        ),
                    )
                    next_claim = {
                        "claim_id": requested_claim_id,
                        "consumer_id": consumer_id,
                        "claimed_at": now.isoformat(),
                        "lease_expires_at": lease_expires_at.isoformat(),
                        "attempt": int(dict(prior_claim or {}).get("attempt", 0) or 0)
                        + 1,
                        "reclaimed_from_claim_id": prior_claim_id,
                    }
                    interaction["claim"] = next_claim
                    interaction["execution"] = {
                        **dict(prior_execution or {}),
                        "state": "result_persisted",
                        "claim_id": requested_claim_id,
                        "consumer_id": consumer_id,
                        "reconciled_at": now.isoformat(),
                    }
                    interaction.pop("completion", None)
                    approval_result = dict(payload.get("approval_result", {}) or {})
                    approval_result.update(
                        {
                            "tool_call_id": tool_call_id,
                            "tool_call_fingerprint": tool_fingerprint,
                            "tool_result_persisted": True,
                            "reconciled_after_restart": True,
                        }
                    )
                    payload["approval_result"] = approval_result
                    payload["interaction"] = interaction
                    _require_reserved_final_publication_unchanged(
                        dict(checkpoint.payload or {}),
                        payload,
                    )
                    cursor = await self._db.execute(
                        """UPDATE execution_checkpoints
                           SET status = 'consuming', payload = ?, updated_at = ?
                           WHERE checkpoint_id = ? AND project_id = ?
                             AND checkpoint_type = ? AND status = 'consuming'""",
                        (
                            _json_dumps(payload),
                            now.isoformat(),
                            checkpoint_id,
                            project_id,
                            checkpoint_type,
                        ),
                    )
                    if cursor.rowcount != 1:
                        await self._db.rollback()
                        return ExecutionCheckpointClaimReceipt(
                            outcome="busy",
                            checkpoint=checkpoint,
                            claim_id=prior_claim_id,
                        )
                    await self._db.commit()
                    return ExecutionCheckpointClaimReceipt(
                        outcome="reclaimed",
                        checkpoint=self._checkpoint_with(
                            checkpoint,
                            status="consuming",
                            payload=payload,
                            updated_at=now,
                        ),
                        claim_id=requested_claim_id,
                    )
                if (
                    isinstance(prior_execution, dict)
                    and str(prior_execution.get("state", "") or "")
                    == "executing"
                    and str(prior_execution.get("claim_id", "") or "")
                    == prior_claim_id
                ):
                    # The prior consumer crossed the non-idempotent effect
                    # boundary.  Expiry proves only that its lease was not
                    # renewed; it does not prove the effect did not happen.
                    # Terminalize conservatively instead of replaying it.
                    prior_execution = {
                        **prior_execution,
                        "state": "outcome_unknown",
                        "detected_at": now.isoformat(),
                        "reason": "execution_lease_expired",
                    }
                    interaction["execution"] = prior_execution
                    interaction["completion"] = {
                        "claim_id": prior_claim_id,
                        "consumer_id": prior_consumer_id,
                        "finished_at": now.isoformat(),
                        "final_status": "outcome_unknown",
                    }
                    if checkpoint_type == "tool_permission":
                        await self._remove_task_runtime_tool_permit_in_transaction(
                            task_id=tool_task_id,
                            runtime_session_id=tool_runtime_session_id,
                            fingerprint=tool_fingerprint,
                        )
                        await self._db.execute(
                            """DELETE FROM runtime_tool_continuations
                               WHERE project_id = ? AND task_id = ?
                                 AND runtime_session_id = ?
                                 AND lease_expires_at <= ?""",
                            (
                                project_id,
                                tool_task_id,
                                tool_runtime_session_id,
                                now.isoformat(),
                            ),
                        )
                    payload["interaction"] = interaction
                    _require_reserved_final_publication_unchanged(
                        dict(checkpoint.payload or {}),
                        payload,
                    )
                    cursor = await self._db.execute(
                        """UPDATE execution_checkpoints
                        SET status = 'outcome_unknown', payload = ?, updated_at = ?
                        WHERE checkpoint_id = ? AND project_id = ?
                          AND checkpoint_type = ? AND status = 'consuming'""",
                        (
                            _json_dumps(payload),
                            now.isoformat(),
                            checkpoint_id,
                            project_id,
                            checkpoint_type,
                        ),
                    )
                    if cursor.rowcount != 1:
                        await self._db.rollback()
                        return ExecutionCheckpointClaimReceipt(
                            outcome="busy",
                            checkpoint=checkpoint,
                            claim_id=prior_claim_id,
                        )
                    await self._db.commit()
                    return ExecutionCheckpointClaimReceipt(
                        outcome="invalid_state",
                        checkpoint=self._checkpoint_with(
                            checkpoint,
                            status="outcome_unknown",
                            payload=payload,
                            updated_at=now,
                        ),
                        claim_id=prior_claim_id,
                    )
                outcome = "reclaimed"
                expected_statuses = ["consuming"]
            elif checkpoint.status != "answered":
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )

            try:
                attempt = int(dict(prior_claim or {}).get("attempt", 0) or 0) + 1
            except (TypeError, ValueError):
                attempt = 1
            next_claim = {
                "claim_id": requested_claim_id,
                "consumer_id": consumer_id,
                "claimed_at": now.isoformat(),
                "lease_expires_at": lease_expires_at.isoformat(),
                "attempt": attempt,
            }
            if outcome == "reclaimed" and isinstance(prior_claim, dict):
                next_claim["reclaimed_from_claim_id"] = str(
                    prior_claim.get("claim_id", "") or ""
                )
            interaction["claim"] = next_claim
            interaction["execution"] = {
                "state": "ready",
                "claim_id": requested_claim_id,
                "consumer_id": consumer_id,
            }
            payload["interaction"] = interaction
            _require_reserved_final_publication_unchanged(
                dict(checkpoint.payload or {}),
                payload,
            )
            placeholders = ", ".join("?" for _ in expected_statuses)
            cursor = await self._db.execute(
                f"""UPDATE execution_checkpoints
                SET status = 'consuming', payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status IN ({placeholders})""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                    *expected_statuses,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                )
            await self._db.commit()
            return ExecutionCheckpointClaimReceipt(
                outcome=outcome,
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="consuming",
                    payload=payload,
                    updated_at=now,
                ),
                claim_id=requested_claim_id,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def begin_execution_checkpoint_effect(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        started_at: datetime | None = None,
    ) -> ExecutionCheckpointClaimReceipt:
        """Fence a claimed owner decision immediately before domain effects."""

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        claim_id = str(claim_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        if not checkpoint_id or not checkpoint_type or not claim_id or not consumer_id:
            raise ValueError(
                "checkpoint_id, checkpoint_type, claim_id, and consumer_id are required"
            )
        self._require_owner_interaction_type(
            checkpoint_type,
            operation="begin_execution_checkpoint_effect",
        )
        self._assert_project_write_scope(
            project_id,
            operation="begin_execution_checkpoint_effect",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = started_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(outcome="not_found")
            if checkpoint.status != "consuming":
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )
            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            claim = interaction.get("claim")
            if not isinstance(claim, dict) or (
                str(claim.get("claim_id", "") or "") != claim_id
                or str(claim.get("consumer_id", "") or "") != consumer_id
            ):
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                    claim_id=str(dict(claim or {}).get("claim_id", "") or ""),
                )
            execution = interaction.get("execution")
            if isinstance(execution, dict) and (
                str(execution.get("state", "") or "") == "executing"
                and str(execution.get("claim_id", "") or "") == claim_id
                and str(execution.get("consumer_id", "") or "") == consumer_id
            ):
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="duplicate",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )
            interaction["execution"] = {
                "state": "executing",
                "claim_id": claim_id,
                "consumer_id": consumer_id,
                "started_at": now.isoformat(),
            }
            payload["interaction"] = interaction
            _require_reserved_final_publication_unchanged(
                dict(checkpoint.payload or {}),
                payload,
            )
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = 'consuming'""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )
            await self._db.commit()
            return ExecutionCheckpointClaimReceipt(
                outcome="started",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="consuming",
                    payload=payload,
                    updated_at=now,
                ),
                claim_id=claim_id,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def begin_exact_tool_permission_effect(
        self,
        permit: dict[str, Any],
        *,
        started_at: datetime | None = None,
    ) -> ExecutionCheckpointClaimReceipt:
        """Atomically fence both halves of an exact ToolCall effect.

        The checkpoint execution marker and Task permit state form one
        at-most-once boundary.  Advancing them in separate transactions leaves
        a crash/TOCTOU window where recovery can observe contradictory facts.
        """

        assert self._db
        normalized = json.loads(_json_dumps(dict(permit or {})))
        checkpoint_id = str(normalized.get("checkpoint_id", "") or "").strip()
        checkpoint_type = str(
            normalized.get("checkpoint_type", "") or ""
        ).strip()
        project_id = str(
            normalized.get("checkpoint_project_id", "") or "default"
        ).strip() or "default"
        task_id = str(normalized.get("task_id", "") or "").strip()
        runtime_session_id = str(
            normalized.get("runtime_session_id", "") or ""
        ).strip()
        fingerprint = str(normalized.get("fingerprint", "") or "").strip()
        tool_call_id = str(normalized.get("id", "") or "").strip()
        tool_name = str(normalized.get("function", "") or "").strip()
        claim_id = str(normalized.get("claim_id", "") or "").strip()
        consumer_id = str(normalized.get("consumer_id", "") or "").strip()
        if (
            checkpoint_type != "tool_permission"
            or not all(
                (
                    checkpoint_id,
                    task_id,
                    runtime_session_id,
                    fingerprint,
                    tool_call_id,
                    tool_name,
                    claim_id,
                    consumer_id,
                )
            )
            or not isinstance(normalized.get("arguments"), dict)
        ):
            raise ValueError("exact ToolCall effect identity is incomplete")
        self._assert_project_write_scope(
            project_id,
            operation="begin_exact_tool_permission_effect",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = started_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(outcome="not_found")
            if checkpoint.status != "consuming":
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )
            async with self._db.execute(
                """SELECT context_snapshot, metadata FROM tasks
                   WHERE id = ? AND project_id = ?""",
                (task_id, project_id),
            ) as cursor:
                task_row = await cursor.fetchone()
            if task_row is None:
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )
            context_snapshot = _json_loads(task_row[0], {})
            task_metadata = _json_loads(task_row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                task_metadata,
            )
            current = dict(permits.get(fingerprint, {}) or {})
            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            execution = dict(interaction.get("execution", {}) or {})
            execution_ready = (
                str(execution.get("state", "") or "").strip() == "ready"
                and str(execution.get("claim_id", "") or "").strip()
                == claim_id
                and str(execution.get("consumer_id", "") or "").strip()
                == consumer_id
            )
            identity_matches = bool(current) and current == normalized and (
                recorded_runtime_id == runtime_session_id
            ) and self._exact_tool_permit_matches_checkpoint(
                current,
                checkpoint,
                task_id=task_id,
                project_id=project_id,
                runtime_session_id=runtime_session_id,
                fingerprint=fingerprint,
                tool_call_id=tool_call_id,
                tool_name=tool_name,
                arguments=dict(normalized["arguments"]),
                execution_envelope=dict(
                    normalized.get("execution_envelope", {}) or {}
                ),
                execution_identity=dict(
                    normalized.get("execution_identity", {}) or {}
                ),
                claim_id=claim_id,
                consumer_id=consumer_id,
            )
            async with self._db.execute(
                """SELECT 1 FROM runtime_tool_results
                   WHERE runtime_session_id = ? AND tool_call_id = ? LIMIT 1""",
                (runtime_session_id, tool_call_id),
            ) as result_cursor:
                result_exists = await result_cursor.fetchone() is not None
            if (
                not identity_matches
                or current.get("approved") is not True
                or str(current.get("decision", "") or "").strip()
                not in {
                    "approve_once",
                    "approve_session",
                    "always_project",
                    "always_global",
                }
                or str(current.get("state", "") or "").strip() != "ready"
                or not execution_ready
                or result_exists
            ):
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )

            permits[fingerprint] = {**current, "state": "executing"}
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                task_metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (
                    _json_dumps(context_snapshot),
                    _json_dumps(task_metadata),
                    task_id,
                ),
            )
            interaction["execution"] = {
                "state": "executing",
                "claim_id": claim_id,
                "consumer_id": consumer_id,
                "started_at": now.isoformat(),
            }
            payload["interaction"] = interaction
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                   SET payload = ?, updated_at = ?
                   WHERE checkpoint_id = ? AND project_id = ?
                     AND checkpoint_type = 'tool_permission'
                     AND status = 'consuming'""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )
            await self._db.commit()
            return ExecutionCheckpointClaimReceipt(
                outcome="started",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="consuming",
                    payload=payload,
                    updated_at=now,
                ),
                claim_id=claim_id,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def finish_execution_checkpoint_consumption(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        final_status: str = "resolved",
        payload_patch: dict[str, Any] | None = None,
        finished_at: datetime | None = None,
    ) -> ExecutionCheckpointConsumptionReceipt:
        """Finish a claimed decision exactly once."""

        final_status = str(final_status or "").strip()
        if not final_status or final_status in {
            "pending",
            "answered",
            "consuming",
            "resuming",
        }:
            raise ValueError("final_status must be terminal")
        return await self._settle_execution_checkpoint_consumption(
            checkpoint_id,
            project_id=project_id,
            checkpoint_type=checkpoint_type,
            claim_id=claim_id,
            consumer_id=consumer_id,
            action="finish",
            final_status=final_status,
            payload_patch=payload_patch,
            reason="",
            transitioned_at=finished_at,
        )

    async def renew_execution_checkpoint_claim(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        lease_seconds: float = 60.0,
        renewed_at: datetime | None = None,
    ) -> ExecutionCheckpointClaimReceipt:
        """Extend one live consumption lease using its exact owner tuple."""

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        claim_id = str(claim_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        if not checkpoint_id or not checkpoint_type or not claim_id or not consumer_id:
            raise ValueError(
                "checkpoint_id, checkpoint_type, claim_id, and consumer_id are required"
            )
        self._require_owner_interaction_type(
            checkpoint_type,
            operation="renew_execution_checkpoint_claim",
        )
        if float(lease_seconds) <= 0:
            raise ValueError("lease_seconds must be positive")
        self._assert_project_write_scope(
            project_id,
            operation="renew_execution_checkpoint_claim",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = renewed_at or datetime.now()
        lease_expires_at = now + timedelta(seconds=float(lease_seconds))
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(outcome="not_found")
            if checkpoint.status != "consuming":
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )
            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            claim = interaction.get("claim")
            if not isinstance(claim, dict) or (
                str(claim.get("claim_id", "") or "") != claim_id
                or str(claim.get("consumer_id", "") or "") != consumer_id
            ):
                await self._db.commit()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                    claim_id=str(dict(claim or {}).get("claim_id", "") or ""),
                )
            next_claim = dict(claim)
            next_claim["lease_expires_at"] = lease_expires_at.isoformat()
            next_claim["heartbeat_at"] = now.isoformat()
            interaction["claim"] = next_claim
            payload["interaction"] = interaction
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = 'consuming'""",
                (
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointClaimReceipt(
                    outcome="busy",
                    checkpoint=checkpoint,
                    claim_id=claim_id,
                )
            await self._db.commit()
            return ExecutionCheckpointClaimReceipt(
                outcome="renewed",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status=checkpoint.status,
                    payload=payload,
                    updated_at=now,
                ),
                claim_id=claim_id,
            )
        except Exception:
            await self._db.rollback()
            raise

    async def release_execution_checkpoint_claim(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        reason: str = "",
        payload_patch: dict[str, Any] | None = None,
        released_at: datetime | None = None,
    ) -> ExecutionCheckpointConsumptionReceipt:
        """Release a failed consumer lease so the durable answer can retry."""

        return await self._settle_execution_checkpoint_consumption(
            checkpoint_id,
            project_id=project_id,
            checkpoint_type=checkpoint_type,
            claim_id=claim_id,
            consumer_id=consumer_id,
            action="release",
            final_status="answered",
            payload_patch=payload_patch,
            reason=str(reason or ""),
            transitioned_at=released_at,
        )

    async def _settle_execution_checkpoint_consumption(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        action: str,
        final_status: str,
        payload_patch: dict[str, Any] | None,
        reason: str,
        transitioned_at: datetime | None,
    ) -> ExecutionCheckpointConsumptionReceipt:
        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        claim_id = str(claim_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        if not checkpoint_id or not checkpoint_type or not claim_id or not consumer_id:
            raise ValueError(
                "checkpoint_id, checkpoint_type, claim_id, and consumer_id are required"
            )
        self._require_owner_interaction_type(
            checkpoint_type,
            operation=f"{action}_execution_checkpoint_consumption",
        )
        if action not in {"finish", "release"}:
            raise ValueError("action must be finish or release")
        if "interaction" in dict(payload_patch or {}):
            raise ValueError(
                "payload_patch cannot modify Store-owned interaction metadata"
            )
        _reject_reserved_final_publication_patch(payload_patch)
        self._assert_project_write_scope(
            project_id,
            operation=f"{action}_execution_checkpoint_consumption",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = transitioned_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(outcome="not_found")

            payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(payload)
            completion = interaction.get("completion")
            last_release = interaction.get("last_release")
            if action == "finish" and isinstance(completion, dict):
                same = (
                    str(completion.get("claim_id", "") or "") == claim_id
                    and str(completion.get("consumer_id", "") or "") == consumer_id
                    and str(completion.get("final_status", "") or "") == final_status
                )
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="duplicate" if same else "conflict",
                    checkpoint=checkpoint,
                )
            if action == "release" and isinstance(last_release, dict):
                same = (
                    str(last_release.get("claim_id", "") or "") == claim_id
                    and str(last_release.get("consumer_id", "") or "") == consumer_id
                )
                if checkpoint.status == "answered" and same:
                    await self._db.commit()
                    return ExecutionCheckpointConsumptionReceipt(
                        outcome="duplicate",
                        checkpoint=checkpoint,
                    )
            if checkpoint.status != "consuming":
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="invalid_state",
                    checkpoint=checkpoint,
                )

            claim = interaction.get("claim")
            if not isinstance(claim, dict) or (
                str(claim.get("claim_id", "") or "") != claim_id
                or str(claim.get("consumer_id", "") or "") != consumer_id
            ):
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict",
                    checkpoint=checkpoint,
                )

            execution = interaction.get("execution")
            if (
                action == "release"
                and isinstance(execution, dict)
                and str(execution.get("state", "") or "") == "executing"
            ):
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict",
                    checkpoint=checkpoint,
                )

            payload = self._merge_execution_checkpoint_payload(payload, payload_patch)
            _require_reserved_final_publication_unchanged(
                dict(checkpoint.payload or {}),
                payload,
            )
            interaction = self._execution_checkpoint_interaction(payload)
            if action == "finish":
                interaction["completion"] = {
                    "claim_id": claim_id,
                    "consumer_id": consumer_id,
                    "finished_at": now.isoformat(),
                    "final_status": final_status,
                }
                interaction["execution"] = {
                    **dict(interaction.get("execution", {}) or {}),
                    "state": final_status,
                    "finished_at": now.isoformat(),
                }
                outcome = "finished"
            else:
                interaction["last_release"] = {
                    "claim_id": claim_id,
                    "consumer_id": consumer_id,
                    "released_at": now.isoformat(),
                    "reason": reason,
                }
                interaction.pop("claim", None)
                interaction["execution"] = {
                    "state": "ready",
                    "released_at": now.isoformat(),
                }
                outcome = "released"
            payload["interaction"] = interaction
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = ?, payload = ?, updated_at = ?
                WHERE checkpoint_id = ? AND project_id = ?
                  AND checkpoint_type = ? AND status = 'consuming'""",
                (
                    final_status,
                    _json_dumps(payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    checkpoint_type,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict",
                    checkpoint=checkpoint,
                )
            await self._db.commit()
            return ExecutionCheckpointConsumptionReceipt(
                outcome=outcome,
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status=final_status,
                    payload=payload,
                    updated_at=now,
                ),
            )
        except Exception:
            await self._db.rollback()
            raise

    async def save_execution_checkpoint(self, checkpoint: ExecutionCheckpoint) -> None:
        assert self._db
        checkpoint_id = str(checkpoint.checkpoint_id or "").strip()
        project_id = str(checkpoint.project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint.checkpoint_type or "").strip()
        if not checkpoint_id or not checkpoint_type:
            raise ValueError("checkpoint_id and checkpoint_type are required")
        if checkpoint_type in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise RuntimeError(
                "owner interactions must use publish/decision/claim/finish APIs"
            )
        self._assert_project_write_scope(
            project_id,
            operation="save_execution_checkpoint",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                "SELECT project_id, checkpoint_type FROM execution_checkpoints WHERE checkpoint_id = ?",
                (checkpoint_id,),
            ) as cursor:
                existing = await cursor.fetchone()
            if existing is not None:
                existing_project = str(existing[0] or "default").strip() or "default"
                existing_type = str(existing[1] or "").strip()
                if existing_type in OWNER_INTERACTION_CHECKPOINT_TYPES:
                    raise RuntimeError(
                        "generic checkpoint save cannot overwrite an owner interaction"
                    )
                if existing_project != project_id or existing_type != checkpoint_type:
                    raise RuntimeError(
                        "checkpoint_id already belongs to a different project/type scope"
                    )
                await self._db.execute(
                    """UPDATE execution_checkpoints
                    SET session_id = ?, status = ?, task_id = ?, payload = ?,
                        created_at = ?, updated_at = ?
                    WHERE checkpoint_id = ? AND project_id = ?
                      AND checkpoint_type = ?""",
                    (
                        checkpoint.session_id,
                        checkpoint.status,
                        checkpoint.task_id,
                        _json_dumps(checkpoint.payload),
                        checkpoint.created_at.isoformat(),
                        checkpoint.updated_at.isoformat(),
                        checkpoint_id,
                        project_id,
                        checkpoint_type,
                    ),
                )
            else:
                await self._db.execute(
                    """INSERT INTO execution_checkpoints
                    (checkpoint_id, project_id, session_id, checkpoint_type,
                     status, task_id, payload, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        checkpoint_id,
                        project_id,
                        checkpoint.session_id,
                        checkpoint_type,
                        checkpoint.status,
                        checkpoint.task_id,
                        _json_dumps(checkpoint.payload),
                        checkpoint.created_at.isoformat(),
                        checkpoint.updated_at.isoformat(),
                    ),
                )
            await self._db.commit()
        except Exception:
            await self._db.rollback()
            raise

    async def resume_company_runtime_scope_for_controller(
        self,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        checkpoint_id: str,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
        expected_checkpoint_statuses: list[str] | tuple[str, ...] | set[str],
        task_ids: list[str] | tuple[str, ...] | set[str],
        checkpoint_payload_updates: dict[str, Any] | None = None,
    ) -> CompanyRuntimeControllerResumeReceipt:
        """Atomically claim a suspend card and reopen selected runtime Tasks.

        Acquiring a run lease does not inherit the preceding generation's
        WorkItem attempt.  This command consequently clears every old Task
        controller/attempt credential while it releases the durable holds;
        the dispatcher may stamp the new generation only after its normal
        claim CAS creates a new ``attempt_seq``.
        """

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_types = sorted(
            {str(value or "").strip() for value in checkpoint_types if str(value or "").strip()}
        )
        clean_statuses = sorted(
            {
                str(value or "").strip().lower()
                for value in expected_checkpoint_statuses
                if str(value or "").strip()
            }
        )
        clean_task_ids = tuple(
            dict.fromkeys(
                str(value or "").strip()
                for value in task_ids
                if str(value or "").strip()
            )
        )
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
            or not clean_checkpoint_id
            or not clean_types
            or not clean_statuses
        ):
            raise ValueError("company runtime resume requires an exact controller/checkpoint scope")
        if any(value in OWNER_INTERACTION_CHECKPOINT_TYPES for value in clean_types):
            raise ValueError("company runtime resume cannot consume owner interactions")
        if any(value not in {"pending", "resuming"} for value in clean_statuses):
            raise ValueError("company runtime resume accepts only pending/resuming checkpoints")
        self._assert_project_write_scope(
            clean_project_id,
            operation="resume_company_runtime_scope_for_controller",
            entity=f"delegation run {clean_run_id!r}",
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            now = datetime.now()
            checked_at = now.isoformat()
            async with transaction_db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ? AND session_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            ) as cursor:
                lease_is_current = await cursor.fetchone() is not None
            if not lease_is_current:
                await transaction_db.rollback()
                return CompanyRuntimeControllerResumeReceipt(outcome="stale")

            type_placeholders = ", ".join("?" for _ in clean_types)
            status_placeholders = ", ".join("?" for _ in clean_statuses)
            async with transaction_db.execute(
                f"""SELECT * FROM execution_checkpoints
                    WHERE checkpoint_id = ? AND project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({type_placeholders})
                      AND status IN ({status_placeholders})""",
                (
                    clean_checkpoint_id,
                    clean_project_id,
                    clean_root_session_id,
                    *clean_types,
                    *clean_statuses,
                ),
            ) as cursor:
                checkpoint_row = await cursor.fetchone()
                checkpoint_description = cursor.description
            if checkpoint_row is None:
                await transaction_db.rollback()
                return CompanyRuntimeControllerResumeReceipt(
                    outcome="not_claimable"
                )
            selected_checkpoint = self._execution_checkpoint_from_data(
                dict(
                    zip(
                        [item[0] for item in checkpoint_description],
                        checkpoint_row,
                    )
                )
            )

            async with transaction_db.execute(
                "SELECT * FROM delegation_work_items WHERE run_id = ?",
                (clean_run_id,),
            ) as cursor:
                work_item_rows = await cursor.fetchall()
                work_item_description = cursor.description
            work_items = {
                item.work_item_id: item
                for item in (
                    self._row_to_delegation_work_item(
                        row,
                        work_item_description,
                    )
                    for row in work_item_rows
                )
            }

            def dependencies_satisfied(item: DelegationWorkItem) -> bool:
                metadata = dict(item.metadata or {})
                dependency_ids = [
                    str(value or "").strip()
                    for value in list(
                        metadata.get("dependency_work_item_ids", []) or []
                    )
                    if str(value or "").strip()
                ]
                dependency_classes = dict(metadata.get("dependency_classes", {}) or {})
                settlement = dict(metadata.get("dependency_settlement", {}) or {})
                settled_failure_ids = {
                    str(value or "").strip()
                    for key in ("failed", "cancelled", "stuck")
                    for value in list(settlement.get(key, []) or [])
                    if str(value or "").strip()
                }
                for dependency_id in dependency_ids:
                    dependency = work_items.get(dependency_id)
                    if dependency is None:
                        continue
                    dependency_class = str(
                        dependency_classes.get(dependency_id, "hard") or "hard"
                    ).strip().lower()
                    if dependency_class == "info":
                        continue
                    if dependency_class == "soft":
                        if (
                            dependency.phase not in DONE_PHASES
                            and dependency.phase not in IN_PROGRESS_PHASES
                            and dependency_id not in settled_failure_ids
                        ):
                            return False
                        continue
                    if (
                        dependency.phase != Phase.APPROVED
                        and dependency_id not in settled_failure_ids
                    ):
                        return False
                return True

            def resume_target_phase(item: DelegationWorkItem) -> Phase:
                metadata = dict(item.metadata or {})
                try:
                    original_phase = Phase(
                        str(metadata.get("suspended_phase", "") or item.phase.value)
                    )
                except ValueError:
                    original_phase = item.phase
                if item.phase in DONE_PHASES or original_phase in DONE_PHASES:
                    return item.phase
                if original_phase in IN_REVIEW_PHASES:
                    return original_phase
                if original_phase == Phase.WAITING_DEPENDENCIES:
                    return original_phase
                if not dependencies_satisfied(item):
                    if original_phase == Phase.RUNNING:
                        return Phase.WAITING_FOR_CHILDREN
                    if original_phase in {
                        Phase.READY,
                        Phase.READY_FOR_REWORK,
                        Phase.QUEUED,
                    }:
                        return Phase.WAITING_DEPENDENCIES
                    return original_phase
                if original_phase == Phase.QUEUED:
                    return Phase.READY
                return original_phase

            affected_task_ids: list[str] = []
            for task_id in clean_task_ids:
                async with transaction_db.execute(
                    "SELECT * FROM tasks WHERE id = ? AND project_id = ?",
                    (task_id, clean_project_id),
                ) as cursor:
                    task_row = await cursor.fetchone()
                    task_description = cursor.description
                if task_row is None:
                    raise RuntimeError(
                        f"company runtime resume Task {task_id!r} no longer exists"
                    )
                persisted_task = self._row_to_task(task_row, task_description)
                task_metadata = dict(persisted_task.metadata or {})
                if (
                    str(task_metadata.get("delegation_run_id", "") or "").strip()
                    != clean_run_id
                ):
                    raise CompanyRunControllerLeaseLost(
                        "company runtime resume Task left the controller run scope"
                    )

                async with transaction_db.execute(
                    """SELECT work_item_id FROM work_item_runtime_links
                       WHERE runtime_task_id = ?""",
                    (task_id,),
                ) as cursor:
                    link_row = await cursor.fetchone()
                work_item = (
                    work_items.get(str(link_row[0] or "").strip())
                    if link_row is not None
                    else None
                )
                if link_row is not None and work_item is None:
                    raise CompanyRunControllerLeaseLost(
                        "company runtime resume Task/WorkItem link left the run scope"
                    )
                if (
                    persisted_task.status
                    in {TaskStatus.DONE, TaskStatus.FAILED, TaskStatus.CANCELLED}
                    and (work_item is None or work_item.phase in DONE_PHASES)
                ):
                    continue

                work_item_is_held = bool(
                    work_item is not None
                    and str(
                        dict(work_item.metadata or {}).get("dispatch_hold", "")
                        or ""
                    ).strip()
                    == "company_runtime_suspended"
                )
                task_is_held = bool(
                    str(task_metadata.get("dispatch_hold", "") or "").strip()
                    == "company_runtime_suspended"
                    or str(
                        task_metadata.get("company_runtime_stop_state", "") or ""
                    ).strip()
                    in {"suspending", "suspended"}
                )
                if not task_is_held and not work_item_is_held:
                    continue
                affected_task_ids.append(task_id)

                target_status = persisted_task.status
                if work_item is not None and work_item.phase not in DONE_PHASES:
                    target_phase = resume_target_phase(work_item)
                    validate_transition(work_item.phase, target_phase)
                    work_item_metadata = dict(work_item.metadata or {})
                    for key in (
                        "dispatch_hold",
                        "suspended_at",
                        "suspend_reason",
                        "suspend_checkpoint_type",
                        "suspend_intent_id",
                        "suspended_phase",
                        "suspended_task_status",
                        "suspended_claim",
                    ):
                        work_item_metadata.pop(key, None)
                    work_item_metadata.update(
                        {
                            "resume_requested_at": checked_at,
                            "resume_source_checkpoint_id": clean_checkpoint_id,
                            "resume_source_checkpoint_type": selected_checkpoint.checkpoint_type,
                            "claimed_by_role_session_id": "",
                            "claimed_task_id": "",
                        }
                    )
                    cursor = await transaction_db.execute(
                        """UPDATE delegation_work_items
                           SET phase = ?, claimed_by_role_runtime_session_id = '',
                               claimed_by_seat_id = '', metadata = ?, updated_at = ?
                           WHERE work_item_id = ? AND run_id = ?
                             AND phase = ? AND updated_at = ?
                             AND EXISTS (
                                 SELECT 1 FROM delegation_runs AS run
                                 WHERE run.run_id = delegation_work_items.run_id
                                   AND run.project_id = ? AND run.session_id = ?
                                   AND run.controller_owner_token = ?
                                   AND run.controller_lease_generation = ?
                                   AND run.controller_lease_expires_at > ?
                             )""",
                        (
                            target_phase.value,
                            _json_dumps(work_item_metadata),
                            checked_at,
                            work_item.work_item_id,
                            clean_run_id,
                            work_item.phase.value,
                            work_item.updated_at.isoformat(),
                            clean_project_id,
                            clean_root_session_id,
                            clean_owner_token,
                            clean_generation,
                            checked_at,
                        ),
                    )
                    if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                        raise CompanyRunControllerLeaseLost(
                            "company runtime resume lost its WorkItem fence"
                        )
                    target_status = task_status_for_phase(target_phase)
                    work_item.phase = target_phase
                    work_item.metadata = work_item_metadata
                    work_item.claimed_by_role_runtime_session_id = ""
                    work_item.claimed_by_seat_id = ""
                    work_item.updated_at = now
                else:
                    suspended_status = str(
                        task_metadata.get("suspended_task_status", "") or ""
                    ).strip()
                    if suspended_status:
                        try:
                            target_status = TaskStatus(suspended_status)
                        except ValueError:
                            target_status = TaskStatus.PENDING

                for key in (
                    "dispatch_hold",
                    "company_runtime_stop_state",
                    "company_runtime_stop_intent_id",
                    "company_runtime_stop_marked_at",
                    "company_runtime_suspend_checkpoint_type",
                    "company_runtime_suspended_at",
                    "suspended_phase",
                    "suspended_task_status",
                    "company_run_controller_owner_token",
                    "company_run_controller_lease_generation",
                    "claimed_work_item_attempt_seq",
                ):
                    task_metadata.pop(key, None)
                task_metadata["company_runtime_resume_checkpoint_id"] = (
                    clean_checkpoint_id
                )
                task_metadata["company_runtime_resume_requested_at"] = checked_at
                progress = list(task_metadata.get("progress_log", []) or [])
                progress.append("Resumed from company runtime suspend checkpoint.")
                task_metadata["progress_log"] = progress[-20:]
                cursor = await transaction_db.execute(
                    """UPDATE tasks
                       SET status = ?, execution_lock = 0,
                           execution_locked_at = NULL, result = NULL, metadata = ?
                       WHERE id = ? AND project_id = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = ? AND run.project_id = ?
                               AND run.session_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        target_status.value,
                        _json_dumps(task_metadata),
                        task_id,
                        clean_project_id,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    raise CompanyRunControllerLeaseLost(
                        "company runtime resume lost its Task fence"
                    )

                role_session_id = str(
                    task_metadata.get("delegation_role_session_id", "") or ""
                ).strip()
                if role_session_id:
                    for role_table in (
                        "role_runtime_sessions",
                        "delegation_role_sessions",
                    ):
                        async with transaction_db.execute(
                            f"""SELECT metadata FROM {role_table}
                                WHERE role_session_id = ? AND run_id = ?
                                  AND project_id = ?""",
                            (
                                role_session_id,
                                clean_run_id,
                                clean_project_id,
                            ),
                        ) as cursor:
                            role_row = await cursor.fetchone()
                        if role_row is None:
                            continue
                        role_metadata = _json_loads(role_row[0], {})
                        role_metadata.update(
                            {
                                "last_resume_checkpoint_type": selected_checkpoint.checkpoint_type,
                                "last_resume_requested_at": checked_at,
                            }
                        )
                        await transaction_db.execute(
                            f"""UPDATE {role_table}
                                SET focused_work_item_id = '', status = 'idle',
                                    metadata = ?, updated_at = ?
                                WHERE role_session_id = ? AND run_id = ?
                                  AND project_id = ?
                                  AND EXISTS (
                                      SELECT 1 FROM delegation_runs AS run
                                      WHERE run.run_id = ? AND run.project_id = ?
                                        AND run.session_id = ?
                                        AND run.controller_owner_token = ?
                                        AND run.controller_lease_generation = ?
                                        AND run.controller_lease_expires_at > ?
                                  )""",
                            (
                                _json_dumps(role_metadata),
                                checked_at,
                                role_session_id,
                                clean_run_id,
                                clean_project_id,
                                clean_run_id,
                                clean_project_id,
                                clean_root_session_id,
                                clean_owner_token,
                                clean_generation,
                                checked_at,
                            ),
                        )

            merged_payload = self._merge_execution_checkpoint_payload(
                dict(selected_checkpoint.payload or {}),
                checkpoint_payload_updates,
            )
            merged_payload.setdefault("resume_state", "resuming")
            merged_payload.setdefault("resume_started_at", checked_at)
            merged_payload["resume_controller_owner_token"] = clean_owner_token
            merged_payload["resume_controller_lease_generation"] = clean_generation
            cursor = await transaction_db.execute(
                f"""UPDATE execution_checkpoints
                    SET status = 'resuming', payload = ?, updated_at = ?
                    WHERE checkpoint_id = ? AND project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({type_placeholders})
                      AND status IN ({status_placeholders})
                      AND EXISTS (
                          SELECT 1 FROM delegation_runs AS run
                          WHERE run.run_id = ? AND run.project_id = ?
                            AND run.session_id = ?
                            AND run.controller_owner_token = ?
                            AND run.controller_lease_generation = ?
                            AND run.controller_lease_expires_at > ?
                      )""",
                (
                    _json_dumps(merged_payload),
                    checked_at,
                    clean_checkpoint_id,
                    clean_project_id,
                    clean_root_session_id,
                    *clean_types,
                    *clean_statuses,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                raise CompanyRunControllerLeaseLost(
                    "company runtime resume lost its checkpoint fence"
                )
            await transaction_db.commit()
            return CompanyRuntimeControllerResumeReceipt(
                outcome="applied",
                checkpoint=self._checkpoint_with(
                    selected_checkpoint,
                    status="resuming",
                    payload=merged_payload,
                    updated_at=now,
                ),
                affected_task_ids=tuple(affected_task_ids),
            )
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_company_runtime_resume_projection_for_controller(
        self,
        task: Task,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        checkpoint_id: str,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
    ) -> CompanyRuntimeControllerProjectionReceipt:
        """Persist a prepared runtime Task without fabricating a new attempt.

        Resume clears the preceding generation's attempt credentials before
        any scheduler claim.  Such a Task cannot use the ordinary attempt
        fence, so this narrow projection command instead fences the write by
        the live run lease, the still-resuming checkpoint, and an unclaimed,
        unheld linked WorkItem in one SQLite transaction.
        """

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_types = sorted(
            {
                str(value or "").strip()
                for value in checkpoint_types
                if str(value or "").strip()
            }
        )
        task_id = str(getattr(task, "id", "") or "").strip()
        task_project_id = (
            str(getattr(task, "project_id", "default") or "default").strip()
            or "default"
        )
        task_metadata = dict(getattr(task, "metadata", {}) or {})
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
            or not clean_checkpoint_id
            or not clean_types
            or not task_id
            or task_project_id != clean_project_id
            or str(task_metadata.get("delegation_run_id", "") or "").strip()
            != clean_run_id
        ):
            raise ValueError("company runtime projection requires an exact run scope")
        if any(value in OWNER_INTERACTION_CHECKPOINT_TYPES for value in clean_types):
            raise ValueError("company runtime projection cannot target owner interactions")
        if any(
            str(task_metadata.get(key, "") or "").strip()
            for key in (
                "company_run_controller_owner_token",
                "company_run_controller_lease_generation",
                "claimed_work_item_attempt_seq",
            )
        ):
            raise ValueError(
                "resume projection cannot fabricate controller attempt credentials"
            )
        self._assert_project_write_scope(
            clean_project_id,
            operation="save_company_runtime_resume_projection_for_controller",
            entity=f"task {task_id!r}",
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now().isoformat()
            async with transaction_db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ? AND session_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            ) as cursor:
                if await cursor.fetchone() is None:
                    await transaction_db.rollback()
                    return CompanyRuntimeControllerProjectionReceipt(outcome="stale")

            type_placeholders = ", ".join("?" for _ in clean_types)
            async with transaction_db.execute(
                f"""SELECT 1 FROM execution_checkpoints
                    WHERE checkpoint_id = ? AND project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({type_placeholders})
                      AND status = 'resuming'""",
                (
                    clean_checkpoint_id,
                    clean_project_id,
                    clean_root_session_id,
                    *clean_types,
                ),
            ) as cursor:
                if await cursor.fetchone() is None:
                    await transaction_db.rollback()
                    return CompanyRuntimeControllerProjectionReceipt(
                        outcome="not_claimable"
                    )

            async with transaction_db.execute(
                """SELECT task.metadata, work_item.metadata,
                          work_item.claimed_by_role_runtime_session_id,
                          work_item.claimed_by_seat_id
                   FROM tasks AS task
                   JOIN work_item_runtime_links AS link
                     ON link.runtime_task_id = task.id
                   JOIN delegation_work_items AS work_item
                     ON work_item.work_item_id = link.work_item_id
                   WHERE task.id = ? AND task.project_id = ?
                     AND work_item.run_id = ?""",
                (task_id, clean_project_id, clean_run_id),
            ) as cursor:
                projection_row = await cursor.fetchone()
            if projection_row is None:
                await transaction_db.rollback()
                return CompanyRuntimeControllerProjectionReceipt(
                    outcome="not_claimable"
                )
            persisted_task_metadata = _json_loads(projection_row[0], {})
            work_item_metadata = _json_loads(projection_row[1], {})
            if (
                str(
                    persisted_task_metadata.get(
                        "company_run_controller_owner_token", ""
                    )
                    or ""
                ).strip()
                or str(work_item_metadata.get("dispatch_hold", "") or "").strip()
                or str(work_item_metadata.get("claimed_task_id", "") or "").strip()
                or str(projection_row[2] or "").strip()
                or str(projection_row[3] or "").strip()
            ):
                await transaction_db.rollback()
                return CompanyRuntimeControllerProjectionReceipt(
                    outcome="not_claimable"
                )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
            return CompanyRuntimeControllerProjectionReceipt(outcome="applied")
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def save_company_runtime_ui_anchor_for_controller(
        self,
        task: Task,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        checkpoint_id: str,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
    ) -> CompanyRuntimeControllerProjectionReceipt:
        """Fence the resume-side UI-anchor projection by lease and checkpoint."""

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_types = sorted(
            {
                str(value or "").strip()
                for value in checkpoint_types
                if str(value or "").strip()
            }
        )
        task_id = str(getattr(task, "id", "") or "").strip()
        task_project_id = (
            str(getattr(task, "project_id", "default") or "default").strip()
            or "default"
        )
        task_session_id = str(getattr(task, "session_id", "") or "").strip()
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
            or not clean_checkpoint_id
            or not clean_types
            or not task_id
            or task_project_id != clean_project_id
            or task_session_id != clean_root_session_id
        ):
            raise ValueError("company runtime UI projection requires an exact scope")
        if any(value in OWNER_INTERACTION_CHECKPOINT_TYPES for value in clean_types):
            raise ValueError("company runtime UI projection cannot target owner interactions")
        self._assert_project_write_scope(
            clean_project_id,
            operation="save_company_runtime_ui_anchor_for_controller",
            entity=f"task {task_id!r}",
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            checked_at = datetime.now().isoformat()
            type_placeholders = ", ".join("?" for _ in clean_types)
            async with transaction_db.execute(
                f"""SELECT 1 FROM delegation_runs AS run
                    JOIN execution_checkpoints AS checkpoint
                      ON checkpoint.checkpoint_id = ?
                     AND checkpoint.project_id = run.project_id
                     AND checkpoint.session_id = run.session_id
                     AND checkpoint.checkpoint_type IN ({type_placeholders})
                     AND checkpoint.status = 'resuming'
                    JOIN tasks AS anchor
                      ON anchor.id = ? AND anchor.project_id = run.project_id
                     AND anchor.session_id = run.session_id
                    WHERE run.run_id = ? AND run.project_id = ?
                      AND run.session_id = ?
                      AND run.controller_owner_token = ?
                      AND run.controller_lease_generation = ?
                      AND run.controller_lease_expires_at > ?
                      AND NOT EXISTS (
                          SELECT 1 FROM work_item_runtime_links AS link
                          WHERE link.runtime_task_id = anchor.id
                      )""",
                (
                    clean_checkpoint_id,
                    *clean_types,
                    task_id,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            ) as cursor:
                projection_is_current = await cursor.fetchone() is not None
            if not projection_is_current:
                async with transaction_db.execute(
                    """SELECT 1 FROM delegation_runs
                       WHERE run_id = ? AND project_id = ? AND session_id = ?
                         AND controller_owner_token = ?
                         AND controller_lease_generation = ?
                         AND controller_lease_expires_at > ?""",
                    (
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                ) as cursor:
                    lease_is_current = await cursor.fetchone() is not None
                await transaction_db.rollback()
                return CompanyRuntimeControllerProjectionReceipt(
                    outcome="not_claimable" if lease_is_current else "stale"
                )
            await self._save_task_row(task, commit=False, db=transaction_db)
            await transaction_db.commit()
            return CompanyRuntimeControllerProjectionReceipt(outcome="applied")
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def complete_company_runtime_resume_for_controller(
        self,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        checkpoint_id: str,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
        payload: dict[str, Any],
        ui_anchor_task_id: str = "",
        completed_at: datetime | None = None,
    ) -> CompanyRuntimeControllerCompletionReceipt:
        """Resolve a resumed run and reopen its UI anchor under one lease fence."""

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        clean_checkpoint_id = str(checkpoint_id or "").strip()
        clean_ui_anchor_task_id = str(ui_anchor_task_id or "").strip()
        clean_types = sorted(
            {
                str(value or "").strip()
                for value in checkpoint_types
                if str(value or "").strip()
            }
        )
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
            or not clean_checkpoint_id
            or not clean_types
        ):
            raise ValueError("company runtime completion requires an exact scope")
        if any(value in OWNER_INTERACTION_CHECKPOINT_TYPES for value in clean_types):
            raise ValueError("company runtime completion cannot target owner interactions")
        self._assert_project_write_scope(
            clean_project_id,
            operation="complete_company_runtime_resume_for_controller",
            entity=f"delegation run {clean_run_id!r}",
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            now = completed_at or datetime.now()
            checked_at = now.isoformat()
            async with transaction_db.execute(
                """SELECT 1 FROM delegation_runs
                   WHERE run_id = ? AND project_id = ? AND session_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            ) as cursor:
                if await cursor.fetchone() is None:
                    await transaction_db.rollback()
                    return CompanyRuntimeControllerCompletionReceipt(outcome="stale")

            type_placeholders = ", ".join("?" for _ in clean_types)
            async with transaction_db.execute(
                f"""SELECT * FROM execution_checkpoints
                    WHERE checkpoint_id = ? AND project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({type_placeholders})
                      AND status = 'resuming'""",
                (
                    clean_checkpoint_id,
                    clean_project_id,
                    clean_root_session_id,
                    *clean_types,
                ),
            ) as cursor:
                checkpoint_row = await cursor.fetchone()
                checkpoint_description = cursor.description
            if checkpoint_row is None:
                await transaction_db.rollback()
                return CompanyRuntimeControllerCompletionReceipt(
                    outcome="not_claimable"
                )
            checkpoint = self._execution_checkpoint_from_data(
                dict(
                    zip(
                        [item[0] for item in checkpoint_description],
                        checkpoint_row,
                    )
                )
            )
            cursor = await transaction_db.execute(
                f"""UPDATE execution_checkpoints
                    SET status = 'resolved', payload = ?, updated_at = ?
                    WHERE checkpoint_id = ? AND project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({type_placeholders})
                      AND status = 'resuming'
                      AND EXISTS (
                          SELECT 1 FROM delegation_runs AS run
                          WHERE run.run_id = ? AND run.project_id = ?
                            AND run.session_id = ?
                            AND run.controller_owner_token = ?
                            AND run.controller_lease_generation = ?
                            AND run.controller_lease_expires_at > ?
                      )""",
                (
                    _json_dumps(dict(payload or {})),
                    checked_at,
                    clean_checkpoint_id,
                    clean_project_id,
                    clean_root_session_id,
                    *clean_types,
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            )
            if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                raise CompanyRunControllerLeaseLost(
                    "company runtime completion lost its checkpoint fence"
                )
            if clean_ui_anchor_task_id:
                await transaction_db.execute(
                    """UPDATE tasks
                       SET status = ?, execution_lock = 0,
                           execution_locked_at = NULL
                       WHERE id = ? AND project_id = ? AND session_id = ?
                         AND status = ?
                         AND NOT EXISTS (
                             SELECT 1 FROM work_item_runtime_links AS link
                             WHERE link.runtime_task_id = tasks.id
                         )
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = ? AND run.project_id = ?
                               AND run.session_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        TaskStatus.IDLE.value,
                        clean_ui_anchor_task_id,
                        clean_project_id,
                        clean_root_session_id,
                        TaskStatus.CANCELLED.value,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )
            await transaction_db.commit()
            return CompanyRuntimeControllerCompletionReceipt(
                outcome="applied",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="resolved",
                    payload=dict(payload or {}),
                    updated_at=now,
                ),
            )
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def suspend_company_runtime_scope_for_controller(
        self,
        *,
        run_id: str,
        project_id: str,
        root_session_id: str,
        owner_token: str,
        generation: int,
        checkpoint: ExecutionCheckpoint,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
        task_ids: list[str] | tuple[str, ...] | set[str],
        checkpoint_payload_updates: dict[str, Any] | None = None,
    ) -> CompanyRuntimeControllerSuspendReceipt:
        """Atomically suspend one company run under its exact controller lease.

        The run lease, authoritative WorkItem holds, Task projections, runtime
        session projections, and the single resumable checkpoint are one
        SQLite transaction.  A controller takeover can therefore observe the
        scope entirely before or entirely after shutdown preparation, never a
        hold without a card (or a card without its holds).

        ``outcome`` values ``stale``, ``already_awaiting_owner``, and
        ``terminal`` are deliberately non-mutating.  The exact run row and
        final owner publication are read immediately after ``BEGIN IMMEDIATE``;
        a final authoritative commit which wins the transaction race therefore
        cannot be followed by a shutdown hold or interrupted checkpoint.
        """

        self._require_db()
        clean_run_id = str(run_id or "").strip()
        clean_project_id = str(project_id or "default").strip() or "default"
        clean_root_session_id = str(root_session_id or "").strip()
        clean_owner_token = str(owner_token or "").strip()
        clean_generation = int(generation or 0)
        clean_types = sorted(
            {str(value or "").strip() for value in checkpoint_types if str(value or "").strip()}
        )
        clean_task_ids = tuple(
            dict.fromkeys(
                str(value or "").strip()
                for value in task_ids
                if str(value or "").strip()
            )
        )
        checkpoint_type = str(checkpoint.checkpoint_type or "").strip()
        checkpoint_project_id = (
            str(checkpoint.project_id or "default").strip() or "default"
        )
        checkpoint_session_id = str(checkpoint.session_id or "").strip()
        if (
            not clean_run_id
            or not clean_root_session_id
            or not clean_owner_token
            or clean_generation <= 0
        ):
            raise ValueError("company runtime suspension requires an exact controller lease")
        if (
            checkpoint_project_id != clean_project_id
            or checkpoint_session_id != clean_root_session_id
            or checkpoint_type not in clean_types
            or not str(checkpoint.checkpoint_id or "").strip()
        ):
            raise ValueError("company runtime suspension checkpoint scope is invalid")
        if any(value in OWNER_INTERACTION_CHECKPOINT_TYPES for value in clean_types):
            raise ValueError("company runtime suspension cannot publish owner interactions")
        self._assert_project_write_scope(
            clean_project_id,
            operation="suspend_company_runtime_scope_for_controller",
            entity=f"delegation run {clean_run_id!r}",
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            now = datetime.now()
            checked_at = now.isoformat()
            async with transaction_db.execute(
                """SELECT status, lifecycle_status FROM delegation_runs
                   WHERE run_id = ? AND project_id = ? AND session_id = ?
                     AND controller_owner_token = ?
                     AND controller_lease_generation = ?
                     AND controller_lease_expires_at > ?""",
                (
                    clean_run_id,
                    clean_project_id,
                    clean_root_session_id,
                    clean_owner_token,
                    clean_generation,
                    checked_at,
                ),
            ) as cursor:
                run_row = await cursor.fetchone()
            if run_row is None:
                await transaction_db.rollback()
                return CompanyRuntimeControllerSuspendReceipt(outcome="stale")

            run_status = str(run_row[0] or "").strip().lower()
            lifecycle_status = str(run_row[1] or "").strip().lower()
            async with transaction_db.execute(
                """SELECT 1
                   FROM execution_checkpoints AS checkpoint
                   JOIN tasks AS task
                     ON task.id = checkpoint.task_id
                    AND task.project_id = checkpoint.project_id
                   WHERE checkpoint.project_id = ?
                     AND checkpoint.checkpoint_type = 'company_delivery_feedback'
                     AND checkpoint.status IN (?, ?, ?)
                     AND COALESCE(
                           json_extract(task.metadata, '$.delegation_run_id'), ''
                         ) = ?
                     AND (
                           COALESCE(
                             json_extract(
                               checkpoint.payload,
                               '$.interaction.ownership.root_session_id'
                             ), ''
                           ) = ?
                           OR task.parent_session_id = ?
                         )
                   LIMIT 1""",
                (
                    clean_project_id,
                    *sorted(OWNER_INTERACTION_ACTIVE_STATUSES),
                    clean_run_id,
                    clean_root_session_id,
                    clean_root_session_id,
                ),
            ) as cursor:
                final_owner_publication_exists = await cursor.fetchone() is not None

            if (
                run_status == "awaiting_owner"
                or lifecycle_status == "awaiting_owner"
                or final_owner_publication_exists
            ):
                await transaction_db.rollback()
                return CompanyRuntimeControllerSuspendReceipt(
                    outcome="already_awaiting_owner"
                )

            terminal_run_statuses = {
                "cancelled",
                "canceled",
                "closed",
                "completed",
                "done",
                "failed",
                "terminal",
            }
            terminal_lifecycle_statuses = {
                "cancelled",
                "canceled",
                "closed",
                "closed_failed",
                "completed",
                "delivered",
                "done",
                "failed",
                "terminal",
            }
            if (
                run_status in terminal_run_statuses
                or lifecycle_status in terminal_lifecycle_statuses
            ):
                await transaction_db.rollback()
                return CompanyRuntimeControllerSuspendReceipt(outcome="terminal")

            placeholders = ", ".join("?" for _ in clean_types)
            async with transaction_db.execute(
                f"""SELECT * FROM execution_checkpoints
                    WHERE project_id = ? AND session_id = ?
                      AND checkpoint_type IN ({placeholders})
                      AND status IN ('pending', 'resuming')
                    ORDER BY updated_at DESC, created_at DESC, checkpoint_id DESC""",
                (clean_project_id, clean_root_session_id, *clean_types),
            ) as cursor:
                checkpoint_rows = await cursor.fetchall()
                checkpoint_columns = [item[0] for item in cursor.description]

            checkpoint_created = not bool(checkpoint_rows)
            if checkpoint_rows:
                decoded_rows = [
                    dict(zip(checkpoint_columns, row)) for row in checkpoint_rows
                ]
                winner_data = decoded_rows[0]
                selected_checkpoint = self._execution_checkpoint_from_data(winner_data)
                for duplicate_data in decoded_rows[1:]:
                    duplicate_id = str(
                        duplicate_data.get("checkpoint_id", "") or ""
                    ).strip()
                    duplicate_payload = _json_loads(
                        duplicate_data.get("payload"), {}
                    )
                    duplicate_payload["superseded_at"] = checked_at
                    duplicate_payload["superseded_by_checkpoint_id"] = (
                        selected_checkpoint.checkpoint_id
                    )
                    await transaction_db.execute(
                        """UPDATE execution_checkpoints
                           SET status = 'superseded', payload = ?, updated_at = ?
                           WHERE checkpoint_id = ? AND project_id = ?
                             AND status IN ('pending', 'resuming')""",
                        (
                            _json_dumps(duplicate_payload),
                            checked_at,
                            duplicate_id,
                            clean_project_id,
                        ),
                    )
                selected_payload = self._merge_execution_checkpoint_payload(
                    dict(selected_checkpoint.payload or {}),
                    checkpoint_payload_updates,
                )
                if selected_checkpoint.status == "resuming":
                    requested_resume_state = str(
                        dict(checkpoint_payload_updates or {}).get(
                            "resume_state", ""
                        )
                        or ""
                    ).strip()
                    selected_payload.update(
                        {
                            "resume_state": requested_resume_state or "interrupted",
                            "resume_interrupted_at": checked_at,
                            "resume_interruption_reason": str(
                                dict(checkpoint.payload or {}).get("reason", "")
                                or "service_shutdown"
                            ),
                        }
                    )
                if (
                    selected_checkpoint.status == "resuming"
                    or selected_payload != dict(selected_checkpoint.payload or {})
                ):
                    prior_status = selected_checkpoint.status
                    cursor = await transaction_db.execute(
                        """UPDATE execution_checkpoints
                           SET status = 'pending', payload = ?, updated_at = ?
                           WHERE checkpoint_id = ? AND project_id = ?
                             AND status = ?""",
                        (
                            _json_dumps(selected_payload),
                            checked_at,
                            selected_checkpoint.checkpoint_id,
                            clean_project_id,
                            prior_status,
                        ),
                    )
                    if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                        raise CompanyRunControllerLeaseLost(
                            "company runtime shutdown lost its active checkpoint"
                        )
                    selected_checkpoint = self._checkpoint_with(
                        selected_checkpoint,
                        status="pending",
                        payload=selected_payload,
                        updated_at=now,
                    )
            else:
                candidate_payload = self._merge_execution_checkpoint_payload(
                    dict(checkpoint.payload or {}),
                    checkpoint_payload_updates,
                )
                selected_checkpoint = ExecutionCheckpoint(
                    checkpoint_id=checkpoint.checkpoint_id,
                    project_id=checkpoint_project_id,
                    session_id=checkpoint.session_id,
                    checkpoint_type=checkpoint_type,
                    status="pending",
                    task_id=checkpoint.task_id,
                    payload=json.loads(_json_dumps(candidate_payload)),
                    created_at=checkpoint.created_at,
                    updated_at=checkpoint.updated_at,
                )

            selected_payload = dict(selected_checkpoint.payload or {})
            effective_reason = str(
                selected_payload.get("reason", "")
                or dict(checkpoint.payload or {}).get("reason", "")
                or "service_shutdown"
            )
            effective_checkpoint_type = str(
                selected_checkpoint.checkpoint_type or checkpoint_type
            )
            effective_stop_intent_id = str(
                selected_payload.get("stop_intent_id", "")
                or dict(checkpoint.payload or {}).get("stop_intent_id", "")
                or ""
            )

            affected_task_ids: list[str] = []
            terminal_task_statuses = {
                TaskStatus.DONE,
                TaskStatus.FAILED,
                TaskStatus.CANCELLED,
            }
            terminal_work_item_phases = {
                Phase.APPROVED,
                Phase.FAILED,
                Phase.CANCELLED,
            }
            for task_id in clean_task_ids:
                async with transaction_db.execute(
                    "SELECT * FROM tasks WHERE id = ? AND project_id = ?",
                    (task_id, clean_project_id),
                ) as cursor:
                    task_row = await cursor.fetchone()
                    task_description = cursor.description
                if task_row is None:
                    raise RuntimeError(
                        f"company runtime shutdown Task {task_id!r} no longer exists"
                    )
                persisted_task = self._row_to_task(task_row, task_description)
                task_metadata = dict(persisted_task.metadata or {})
                if (
                    str(task_metadata.get("delegation_run_id", "") or "").strip()
                    != clean_run_id
                ):
                    raise CompanyRunControllerLeaseLost(
                        "company runtime shutdown Task left the controller run scope"
                    )

                work_item: DelegationWorkItem | None = None
                async with transaction_db.execute(
                    """SELECT work_item.* FROM work_item_runtime_links AS link
                       JOIN delegation_work_items AS work_item
                         ON work_item.work_item_id = link.work_item_id
                       WHERE link.runtime_task_id = ?""",
                    (task_id,),
                ) as cursor:
                    work_item_row = await cursor.fetchone()
                    work_item_description = cursor.description
                if work_item_row is not None:
                    work_item = self._row_to_delegation_work_item(
                        work_item_row,
                        work_item_description,
                    )
                    if str(work_item.run_id or "").strip() != clean_run_id:
                        raise CompanyRunControllerLeaseLost(
                            "company runtime shutdown WorkItem left the controller run scope"
                        )

                task_is_terminal = persisted_task.status in terminal_task_statuses
                work_item_is_active = bool(
                    work_item is not None
                    and work_item.phase not in terminal_work_item_phases
                )
                if task_is_terminal and not work_item_is_active:
                    continue

                core_is_suspended = bool(
                    str(task_metadata.get("company_runtime_stop_state", "") or "").strip()
                    == "suspended"
                    and str(
                        task_metadata.get(
                            "company_runtime_suspend_checkpoint_type", ""
                        )
                        or ""
                    ).strip()
                    == effective_checkpoint_type
                    and str(
                        task_metadata.get("company_runtime_suspended_at", "") or ""
                    ).strip()
                    and not persisted_task.execution_lock
                    and persisted_task.execution_locked_at is None
                )
                if work_item_is_active and work_item is not None:
                    work_item_metadata = dict(work_item.metadata or {})
                    core_is_suspended = bool(
                        core_is_suspended
                        and str(task_metadata.get("dispatch_hold", "") or "").strip()
                        == "company_runtime_suspended"
                        and str(work_item_metadata.get("dispatch_hold", "") or "").strip()
                        == "company_runtime_suspended"
                        and str(
                            work_item_metadata.get("suspend_checkpoint_type", "")
                            or ""
                        ).strip()
                        == effective_checkpoint_type
                        and not str(
                            work_item.claimed_by_role_runtime_session_id or ""
                        ).strip()
                        and not str(work_item.claimed_by_seat_id or "").strip()
                        and not str(
                            work_item_metadata.get(
                                "claimed_by_role_session_id", ""
                            )
                            or ""
                        ).strip()
                        and not str(
                            work_item_metadata.get("claimed_task_id", "") or ""
                        ).strip()
                    )

                role_session_id = str(
                    task_metadata.get("delegation_role_session_id", "") or ""
                ).strip()
                role_projection_is_suspended = True
                if role_session_id:
                    for role_table in (
                        "role_runtime_sessions",
                        "delegation_role_sessions",
                    ):
                        async with transaction_db.execute(
                            f"""SELECT focused_work_item_id, status FROM {role_table}
                                WHERE role_session_id = ? AND run_id = ?
                                  AND project_id = ?""",
                            (
                                role_session_id,
                                clean_run_id,
                                clean_project_id,
                            ),
                        ) as cursor:
                            role_row = await cursor.fetchone()
                        if role_row is not None and (
                            str(role_row[0] or "").strip()
                            or str(role_row[1] or "").strip().lower() != "idle"
                        ):
                            role_projection_is_suspended = False

                async with transaction_db.execute(
                    """SELECT 1 FROM external_sessions
                       WHERE project_id = ? AND task_id = ?
                         AND lower(COALESCE(status, '')) NOT IN
                             ('suspended', 'failed', 'cancelled', 'denied', 'rejected')
                       LIMIT 1""",
                    (clean_project_id, task_id),
                ) as cursor:
                    external_projection_is_suspended = await cursor.fetchone() is None

                if (
                    core_is_suspended
                    and role_projection_is_suspended
                    and external_projection_is_suspended
                ):
                    continue

                affected_task_ids.append(task_id)
                original_task_status = (
                    persisted_task.status.value
                    if isinstance(persisted_task.status, TaskStatus)
                    else str(persisted_task.status or "")
                )
                task_metadata["last_stop_reason"] = effective_reason
                task_metadata["company_runtime_suspend_checkpoint_type"] = (
                    effective_checkpoint_type
                )
                task_metadata["company_runtime_suspended_at"] = str(
                    task_metadata.get("company_runtime_suspended_at", "") or checked_at
                )
                task_metadata["company_runtime_stop_state"] = "suspended"
                task_metadata["company_runtime_stop_intent_id"] = (
                    effective_stop_intent_id
                    or str(
                        task_metadata.get("company_runtime_stop_intent_id", "") or ""
                    )
                )
                task_metadata["company_runtime_stop_marked_at"] = str(
                    task_metadata.get("company_runtime_stop_marked_at", "")
                    or checked_at
                )
                task_metadata.setdefault("suspended_task_status", original_task_status)

                suspended_phase: Phase | None = None
                if work_item_is_active and work_item is not None:
                    suspended_phase = work_item.phase
                    work_item_metadata = dict(work_item.metadata or {})
                    original_claim = dict(
                        work_item_metadata.get("suspended_claim", {}) or {}
                    ) or {
                        "claimed_by_role_runtime_session_id": str(
                            work_item.claimed_by_role_runtime_session_id or ""
                        ),
                        "claimed_by_seat_id": str(
                            work_item.claimed_by_seat_id or ""
                        ),
                        "claimed_by_role_session_id": str(
                            work_item_metadata.get(
                                "claimed_by_role_session_id", ""
                            )
                            or ""
                        ),
                        "claimed_task_id": str(
                            work_item_metadata.get("claimed_task_id", "")
                            or task_id
                        ),
                    }
                    work_item_metadata.update(
                        {
                            "dispatch_hold": "company_runtime_suspended",
                            "suspended_at": str(
                                work_item_metadata.get("suspended_at", "")
                                or checked_at
                            ),
                            "suspend_reason": effective_reason,
                            "suspend_checkpoint_type": effective_checkpoint_type,
                            "suspend_intent_id": effective_stop_intent_id,
                            "suspended_phase": suspended_phase.value,
                            "suspended_task_status": original_task_status,
                            "suspended_claim": original_claim,
                            "claimed_by_role_session_id": "",
                            "claimed_task_id": "",
                        }
                    )
                    cursor = await transaction_db.execute(
                        """UPDATE delegation_work_items
                           SET claimed_by_role_runtime_session_id = '',
                               claimed_by_seat_id = '', metadata = ?, updated_at = ?
                           WHERE work_item_id = ? AND run_id = ?
                             AND phase = ? AND updated_at = ?
                             AND EXISTS (
                                 SELECT 1 FROM delegation_runs AS run
                                 WHERE run.run_id = delegation_work_items.run_id
                                   AND run.project_id = ? AND run.session_id = ?
                                   AND run.controller_owner_token = ?
                                   AND run.controller_lease_generation = ?
                                   AND run.controller_lease_expires_at > ?
                             )""",
                        (
                            _json_dumps(work_item_metadata),
                            checked_at,
                            work_item.work_item_id,
                            clean_run_id,
                            work_item.phase.value,
                            work_item.updated_at.isoformat(),
                            clean_project_id,
                            clean_root_session_id,
                            clean_owner_token,
                            clean_generation,
                            checked_at,
                        ),
                    )
                    if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                        raise CompanyRunControllerLeaseLost(
                            "company runtime shutdown lost its WorkItem fence"
                        )
                    task_metadata["dispatch_hold"] = "company_runtime_suspended"
                    task_metadata["suspended_phase"] = suspended_phase.value

                target_task_status = persisted_task.status
                if not task_is_terminal and suspended_phase is not None:
                    target_task_status = task_status_for_phase(suspended_phase)
                cursor = await transaction_db.execute(
                    """UPDATE tasks
                       SET status = ?, execution_lock = 0,
                           execution_locked_at = NULL, metadata = ?
                       WHERE id = ? AND project_id = ?
                         AND EXISTS (
                             SELECT 1 FROM delegation_runs AS run
                             WHERE run.run_id = ? AND run.project_id = ?
                               AND run.session_id = ?
                               AND run.controller_owner_token = ?
                               AND run.controller_lease_generation = ?
                               AND run.controller_lease_expires_at > ?
                         )""",
                    (
                        target_task_status.value,
                        _json_dumps(task_metadata),
                        task_id,
                        clean_project_id,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    raise CompanyRunControllerLeaseLost(
                        "company runtime shutdown lost its Task fence"
                    )

                if role_session_id:
                    for role_table in (
                        "role_runtime_sessions",
                        "delegation_role_sessions",
                    ):
                        async with transaction_db.execute(
                            f"""SELECT metadata FROM {role_table}
                                WHERE role_session_id = ? AND run_id = ?
                                  AND project_id = ?""",
                            (
                                role_session_id,
                                clean_run_id,
                                clean_project_id,
                            ),
                        ) as cursor:
                            role_row = await cursor.fetchone()
                        if role_row is None:
                            continue
                        role_metadata = _json_loads(role_row[0], {})
                        role_metadata.update(
                            {
                                "last_suspend_reason": effective_reason,
                                "last_suspend_checkpoint_type": effective_checkpoint_type,
                                "last_suspended_at": checked_at,
                                "last_suspend_intent_id": effective_stop_intent_id,
                            }
                        )
                        await transaction_db.execute(
                            f"""UPDATE {role_table}
                                SET focused_work_item_id = '', status = 'idle',
                                    metadata = ?, updated_at = ?
                                WHERE role_session_id = ? AND run_id = ?
                                  AND project_id = ?
                                  AND EXISTS (
                                      SELECT 1 FROM delegation_runs AS run
                                      WHERE run.run_id = ? AND run.project_id = ?
                                        AND run.session_id = ?
                                        AND run.controller_owner_token = ?
                                        AND run.controller_lease_generation = ?
                                        AND run.controller_lease_expires_at > ?
                                  )""",
                            (
                                _json_dumps(role_metadata),
                                checked_at,
                                role_session_id,
                                clean_run_id,
                                clean_project_id,
                                clean_run_id,
                                clean_project_id,
                                clean_root_session_id,
                                clean_owner_token,
                                clean_generation,
                                checked_at,
                            ),
                        )

                async with transaction_db.execute(
                    """SELECT session_key, metadata FROM external_sessions
                       WHERE project_id = ? AND task_id = ?
                         AND lower(COALESCE(status, '')) NOT IN
                             ('suspended', 'failed', 'cancelled', 'denied', 'rejected')""",
                    (clean_project_id, task_id),
                ) as cursor:
                    external_rows = await cursor.fetchall()
                for session_key, raw_metadata in external_rows:
                    external_metadata = _json_loads(raw_metadata, {})
                    external_metadata.update(
                        {
                            "company_runtime_suspended_at": checked_at,
                            "company_runtime_suspend_checkpoint_type": effective_checkpoint_type,
                            "company_runtime_stop_intent_id": effective_stop_intent_id,
                        }
                    )
                    await transaction_db.execute(
                        """UPDATE external_sessions
                           SET status = 'suspended', metadata = ?, updated_at = ?
                           WHERE session_key = ? AND project_id = ?
                             AND EXISTS (
                                 SELECT 1 FROM delegation_runs AS run
                                 WHERE run.run_id = ? AND run.project_id = ?
                                   AND run.session_id = ?
                                   AND run.controller_owner_token = ?
                                   AND run.controller_lease_generation = ?
                                   AND run.controller_lease_expires_at > ?
                             )""",
                        (
                            _json_dumps(external_metadata),
                            checked_at,
                            session_key,
                            clean_project_id,
                            clean_run_id,
                            clean_project_id,
                            clean_root_session_id,
                            clean_owner_token,
                            clean_generation,
                            checked_at,
                        ),
                    )

            # Role/member/seat rows are scheduler projections of this exact
            # controller scope.  They are not recovery checkpoints in their
            # own right, so leaving one of them ``running`` after the
            # WorkItem hold is committed advertises a process which no longer
            # exists.  Converge every run-scoped projection in the same
            # transaction as the authoritative hold.  Rich resume/memory
            # payloads stay intact; only live ownership/focus fields and their
            # embedded display status are changed.
            def _suspended_current_work_item(value: Any) -> dict[str, Any]:
                current = dict(value) if isinstance(value, dict) else {}
                if current:
                    current["status"] = "suspended"
                return current

            def _idle_manager_digest(value: Any) -> dict[str, Any]:
                digest = dict(value) if isinstance(value, dict) else {}
                if digest:
                    digest["resident_status"] = "idle"
                    nested_current = digest.get("current_work_item")
                    if isinstance(nested_current, dict) and nested_current:
                        digest["current_work_item"] = _suspended_current_work_item(
                            nested_current
                        )
                return digest

            projection_suspend_metadata = {
                "last_suspend_reason": effective_reason,
                "last_suspend_checkpoint_type": effective_checkpoint_type,
                "last_suspended_at": checked_at,
                "last_suspend_intent_id": effective_stop_intent_id,
                "company_run_id": clean_run_id,
                "company_run_controller_owner_token": clean_owner_token,
                "company_run_controller_lease_generation": clean_generation,
            }
            lease_exists = """EXISTS (
                SELECT 1 FROM delegation_runs AS run
                WHERE run.run_id = ? AND run.project_id = ?
                  AND run.session_id = ?
                  AND run.controller_owner_token = ?
                  AND run.controller_lease_generation = ?
                  AND run.controller_lease_expires_at > ?
            )"""

            # A serialized CompanyMemberSession is also copied into Task
            # metadata.  Normalizing only the dedicated projection tables
            # would allow bootstrap to rehydrate a stale ``running`` member
            # before the canonical role row corrects it. Internal role-prompt
            # Tasks are one-shot auxiliary attempts: shutdown cancels their
            # Task projection while the corresponding RuntimeV2 row below is
            # suspended, so neither durable table advertises live execution.
            async with transaction_db.execute(
                """SELECT id, status, metadata FROM tasks
                   WHERE project_id = ?
                     AND json_extract(metadata, '$.delegation_run_id') = ?""",
                (clean_project_id, clean_run_id),
            ) as cursor:
                run_task_projection_rows = await cursor.fetchall()
            for (
                projection_task_id,
                projection_task_status,
                raw_task_metadata,
            ) in run_task_projection_rows:
                task_projection_metadata = _json_loads(raw_task_metadata, {})
                projection_changed = False
                target_projection_task_status = str(
                    projection_task_status or TaskStatus.PENDING.value
                ).strip()
                auxiliary_is_live = bool(
                    task_projection_metadata.get(
                        "company_runtime_auxiliary_task", False
                    )
                    and target_projection_task_status
                    not in {
                        TaskStatus.DONE.value,
                        TaskStatus.FAILED.value,
                        TaskStatus.CANCELLED.value,
                    }
                )
                if auxiliary_is_live:
                    target_projection_task_status = TaskStatus.CANCELLED.value
                    task_projection_metadata.update(
                        {
                            "last_stop_reason": effective_reason,
                            "company_runtime_stop_state": "suspended",
                            "company_runtime_suspend_checkpoint_type": effective_checkpoint_type,
                            "company_runtime_suspended_at": checked_at,
                            "company_runtime_stop_intent_id": effective_stop_intent_id,
                            "runtime_auxiliary_terminal_reason": "controller_shutdown",
                        }
                    )
                    projection_changed = True
                member_state = task_projection_metadata.get("member_session_state")
                if isinstance(member_state, dict) and (
                    str(member_state.get("status", "") or "").strip().lower()
                    != "idle"
                    or str(
                        member_state.get("resident_status", "") or ""
                    ).strip().lower()
                    != "idle"
                    or str(member_state.get("current_task_id", "") or "").strip()
                    or str(
                        member_state.get("focused_work_item_id", "") or ""
                    ).strip()
                ):
                    normalized_member_state = dict(member_state)
                    normalized_member_state.update(
                        {
                            "status": "idle",
                            "resident_status": "idle",
                            "current_task_id": "",
                            "focused_work_item_id": "",
                            "current_work_item": _suspended_current_work_item(
                                normalized_member_state.get("current_work_item")
                            ),
                            "manager_digest": _idle_manager_digest(
                                normalized_member_state.get("manager_digest")
                            ),
                        }
                    )
                    nested_member_metadata = dict(
                        normalized_member_state.get("metadata", {}) or {}
                    )
                    nested_member_metadata.update(projection_suspend_metadata)
                    normalized_member_state["metadata"] = nested_member_metadata
                    task_projection_metadata["member_session_state"] = (
                        normalized_member_state
                    )
                    projection_changed = True
                runtime_v2_state = task_projection_metadata.get("runtime_v2")
                if (
                    isinstance(runtime_v2_state, dict)
                    and str(runtime_v2_state.get("status", "") or "")
                    .strip()
                    .lower()
                    in {"running", "starting", "working"}
                ):
                    normalized_runtime_v2 = dict(runtime_v2_state)
                    normalized_runtime_v2.update(
                        {
                            "status": "suspended",
                            "company_runtime_suspend_checkpoint_type": effective_checkpoint_type,
                            "company_runtime_suspended_at": checked_at,
                            "company_runtime_stop_intent_id": effective_stop_intent_id,
                        }
                    )
                    task_projection_metadata["runtime_v2"] = normalized_runtime_v2
                    projection_changed = True
                if not projection_changed:
                    continue
                await transaction_db.execute(
                    f"""UPDATE tasks
                        SET status = ?, execution_lock = 0,
                            execution_locked_at = NULL, metadata = ?
                        WHERE id = ? AND project_id = ?
                          AND json_extract(metadata, '$.delegation_run_id') = ?
                          AND {lease_exists}""",
                    (
                        target_projection_task_status,
                        _json_dumps(task_projection_metadata),
                        projection_task_id,
                        clean_project_id,
                        clean_run_id,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )

            for role_table in (
                "role_runtime_sessions",
                "delegation_role_sessions",
            ):
                async with transaction_db.execute(
                    f"""SELECT role_session_id, focused_work_item_id, status,
                               current_work_item, manager_digest, metadata
                        FROM {role_table}
                        WHERE run_id = ? AND project_id = ?""",
                    (clean_run_id, clean_project_id),
                ) as cursor:
                    role_projection_rows = await cursor.fetchall()
                for (
                    role_session_id,
                    focused_work_item_id,
                    role_status,
                    raw_current_work_item,
                    raw_manager_digest,
                    raw_role_metadata,
                ) in role_projection_rows:
                    role_current_work_item = _json_loads(
                        raw_current_work_item, {}
                    )
                    role_manager_digest = _json_loads(raw_manager_digest, {})
                    if (
                        str(role_status or "").strip().lower() == "idle"
                        and not str(focused_work_item_id or "").strip()
                        and str(
                            role_current_work_item.get("status", "") or ""
                        ).strip().lower()
                        not in {"running", "starting", "working"}
                        and str(
                            role_manager_digest.get("resident_status", "") or ""
                        ).strip().lower()
                        not in {"running", "starting", "working"}
                    ):
                        continue
                    role_metadata = _json_loads(raw_role_metadata, {})
                    role_metadata.update(projection_suspend_metadata)
                    await transaction_db.execute(
                        f"""UPDATE {role_table}
                            SET focused_work_item_id = '', status = 'idle',
                                current_work_item = ?, manager_digest = ?,
                                metadata = ?, updated_at = ?
                            WHERE role_session_id = ? AND run_id = ?
                              AND project_id = ? AND {lease_exists}""",
                        (
                            _json_dumps(
                                _suspended_current_work_item(
                                    role_current_work_item
                                )
                            ),
                            _json_dumps(
                                _idle_manager_digest(role_manager_digest)
                            ),
                            _json_dumps(role_metadata),
                            checked_at,
                            role_session_id,
                            clean_run_id,
                            clean_project_id,
                            clean_run_id,
                            clean_project_id,
                            clean_root_session_id,
                            clean_owner_token,
                            clean_generation,
                            checked_at,
                        ),
                    )

            async with transaction_db.execute(
                """SELECT seat_state_id, status, resident_status,
                          current_task_id, current_work_item_id,
                          current_work_item, manager_digest, metadata
                   FROM seat_states
                   WHERE run_id = ? AND project_id = ?""",
                (clean_run_id, clean_project_id),
            ) as cursor:
                seat_projection_rows = await cursor.fetchall()
            for (
                seat_state_id,
                seat_status,
                resident_status,
                current_task_id,
                current_work_item_id,
                raw_current_work_item,
                raw_manager_digest,
                raw_seat_metadata,
            ) in seat_projection_rows:
                seat_current_work_item = _json_loads(raw_current_work_item, {})
                seat_manager_digest = _json_loads(raw_manager_digest, {})
                if (
                    str(seat_status or "").strip().lower() == "idle"
                    and str(resident_status or "").strip().lower() == "idle"
                    and not str(current_task_id or "").strip()
                    and not str(current_work_item_id or "").strip()
                    and str(
                        seat_current_work_item.get("status", "") or ""
                    ).strip().lower()
                    not in {"running", "starting", "working"}
                    and str(
                        seat_manager_digest.get("resident_status", "") or ""
                    ).strip().lower()
                    not in {"running", "starting", "working"}
                ):
                    continue
                seat_metadata = _json_loads(raw_seat_metadata, {})
                seat_metadata.update(projection_suspend_metadata)
                await transaction_db.execute(
                    f"""UPDATE seat_states
                        SET status = 'idle', resident_status = 'idle',
                            current_task_id = '', current_work_item_id = '',
                            current_work_item = ?, manager_digest = ?,
                            metadata = ?, updated_at = ?
                        WHERE seat_state_id = ? AND run_id = ?
                          AND project_id = ? AND {lease_exists}""",
                    (
                        _json_dumps(
                            _suspended_current_work_item(seat_current_work_item)
                        ),
                        _json_dumps(
                            _idle_manager_digest(seat_manager_digest)
                        ),
                        _json_dumps(seat_metadata),
                        checked_at,
                        seat_state_id,
                        clean_run_id,
                        clean_project_id,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )

            # ``runtime_sessions`` contains two intentionally different
            # projections: serialized CompanyMemberSession rows and native
            # execution attempts.  Member rows become idle; native attempts
            # become suspended. Generated role-prompt Tasks (for example CEO
            # pre-delivery assessment) are persisted and namespaced beneath
            # their durable source Task, so both exact and legacy descendant
            # identities remain inside the same shutdown scope.
            async with transaction_db.execute(
                """SELECT runtime.runtime_session_id, runtime.status,
                          runtime.metadata
                   FROM runtime_sessions AS runtime
                   WHERE runtime.project_id = ?
                     AND lower(COALESCE(runtime.status, ''))
                         IN ('running', 'starting', 'working')
                     AND (
                         json_extract(runtime.metadata, '$.company_run_id') = ?
                         OR json_extract(
                                runtime.metadata,
                                '$.delegation_run_id'
                            ) = ?
                         OR json_extract(
                                runtime.metadata,
                                '$.metadata.company_run_id'
                            ) = ?
                         OR EXISTS (
                             SELECT 1 FROM tasks AS run_task
                             WHERE run_task.project_id = ?
                               AND json_extract(
                                     run_task.metadata,
                                     '$.delegation_run_id'
                                   ) = ?
                               AND (
                                   runtime.task_id = run_task.id
                                   OR substr(
                                        runtime.task_id,
                                        1,
                                        length(run_task.id) + 2
                                      ) = run_task.id || '::'
                               )
                         )
                     )""",
                (
                    clean_project_id,
                    clean_run_id,
                    clean_run_id,
                    clean_run_id,
                    clean_project_id,
                    clean_run_id,
                ),
            ) as cursor:
                live_runtime_projection_rows = await cursor.fetchall()
            for (
                runtime_session_id,
                prior_runtime_status,
                raw_runtime_metadata,
            ) in live_runtime_projection_rows:
                runtime_metadata = _json_loads(raw_runtime_metadata, {})
                is_member_projection = bool(
                    str(runtime_metadata.get("member_session_id", "") or "").strip()
                )
                target_runtime_status = (
                    "idle" if is_member_projection else "suspended"
                )
                runtime_metadata.update(
                    {
                        "status": target_runtime_status,
                        "company_run_id": clean_run_id,
                        "company_run_controller_owner_token": clean_owner_token,
                        "company_run_controller_lease_generation": clean_generation,
                        "company_runtime_suspend_checkpoint_type": effective_checkpoint_type,
                        "company_runtime_suspended_at": checked_at,
                        "company_runtime_stop_intent_id": effective_stop_intent_id,
                    }
                )
                if is_member_projection:
                    runtime_metadata.update(
                        {
                            "resident_status": "idle",
                            "current_task_id": "",
                            "focused_work_item_id": "",
                            "current_work_item": _suspended_current_work_item(
                                runtime_metadata.get("current_work_item")
                            ),
                            "manager_digest": _idle_manager_digest(
                                runtime_metadata.get("manager_digest")
                            ),
                        }
                    )
                    nested_runtime_metadata = dict(
                        runtime_metadata.get("metadata", {}) or {}
                    )
                    nested_runtime_metadata.update(projection_suspend_metadata)
                    runtime_metadata["metadata"] = nested_runtime_metadata
                await transaction_db.execute(
                    f"""UPDATE runtime_sessions
                        SET status = ?, metadata = ?, updated_at = ?
                        WHERE runtime_session_id = ? AND project_id = ?
                          AND status = ? AND {lease_exists}""",
                    (
                        target_runtime_status,
                        _json_dumps(runtime_metadata),
                        checked_at,
                        runtime_session_id,
                        clean_project_id,
                        prior_runtime_status,
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )

            if checkpoint_created:
                cursor = await transaction_db.execute(
                    """INSERT INTO execution_checkpoints
                       (checkpoint_id, project_id, session_id, checkpoint_type,
                        status, task_id, payload, created_at, updated_at)
                       SELECT ?, ?, ?, ?, 'pending', ?, ?, ?, ?
                       WHERE EXISTS (
                           SELECT 1 FROM delegation_runs AS run
                           WHERE run.run_id = ? AND run.project_id = ?
                             AND run.session_id = ?
                             AND run.controller_owner_token = ?
                             AND run.controller_lease_generation = ?
                             AND run.controller_lease_expires_at > ?
                       )""",
                    (
                        selected_checkpoint.checkpoint_id,
                        clean_project_id,
                        clean_root_session_id,
                        selected_checkpoint.checkpoint_type,
                        selected_checkpoint.task_id,
                        _json_dumps(selected_checkpoint.payload),
                        selected_checkpoint.created_at.isoformat(),
                        selected_checkpoint.updated_at.isoformat(),
                        clean_run_id,
                        clean_project_id,
                        clean_root_session_id,
                        clean_owner_token,
                        clean_generation,
                        checked_at,
                    ),
                )
                if int(getattr(cursor, "rowcount", 0) or 0) != 1:
                    raise CompanyRunControllerLeaseLost(
                        "company runtime shutdown lost its checkpoint fence"
                    )

            await transaction_db.commit()
            return CompanyRuntimeControllerSuspendReceipt(
                outcome="applied",
                checkpoint=selected_checkpoint,
                checkpoint_created=checkpoint_created,
                affected_task_ids=tuple(affected_task_ids),
            )
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def get_or_create_active_execution_checkpoint(
        self,
        checkpoint: ExecutionCheckpoint,
        *,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
        create_if_missing: bool = True,
    ) -> tuple[ExecutionCheckpoint | None, bool]:
        """Atomically reuse or create one active checkpoint for a session scope.

        ``BEGIN IMMEDIATE`` serializes checkpoint creation across independent
        controller/store connections.  It also repairs historical duplicate
        active rows in the same transaction, so concurrent startup/shutdown
        reconcilers can never supersede each other's newly-created checkpoint
        and leave the scope without a durable recovery point.
        """

        assert self._db
        clean_types = sorted(
            {
                str(item).strip()
                for item in checkpoint_types
                if str(item).strip()
            }
        )
        project_id = str(checkpoint.project_id or "default").strip() or "default"
        session_id = str(checkpoint.session_id or "").strip()
        checkpoint_type = str(checkpoint.checkpoint_type or "").strip()
        if not session_id:
            raise ValueError("active execution checkpoint requires session_id")
        if checkpoint_type not in clean_types:
            raise ValueError(
                "checkpoint_type must be included in the active checkpoint scope"
            )
        if any(item in OWNER_INTERACTION_CHECKPOINT_TYPES for item in clean_types):
            raise RuntimeError(
                "owner interactions cannot use generic active-checkpoint mutation"
            )

        placeholders = ", ".join("?" for _ in clean_types)
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                f"""SELECT * FROM execution_checkpoints
                WHERE project_id = ?
                  AND session_id = ?
                  AND checkpoint_type IN ({placeholders})
                  AND status IN ('pending', 'resuming')
                ORDER BY updated_at DESC, created_at DESC, checkpoint_id DESC""",
                (project_id, session_id, *clean_types),
            ) as cursor:
                rows = await cursor.fetchall()
                cols = [description[0] for description in cursor.description]

            if rows:
                decoded = [dict(zip(cols, row)) for row in rows]
                winner_data = decoded[0]
                winner_id = str(winner_data["checkpoint_id"])
                now = datetime.now().isoformat()
                for duplicate in decoded[1:]:
                    duplicate_id = str(duplicate.get("checkpoint_id", "") or "").strip()
                    if not duplicate_id:
                        continue
                    payload = _json_loads(duplicate.get("payload"), {})
                    payload["superseded_at"] = now
                    payload["superseded_by_checkpoint_id"] = winner_id
                    await self._db.execute(
                        """UPDATE execution_checkpoints
                        SET status = 'superseded', payload = ?, updated_at = ?
                        WHERE checkpoint_id = ? AND status IN ('pending', 'resuming')""",
                        (_json_dumps(payload), now, duplicate_id),
                    )
                await self._db.commit()
                return (
                    ExecutionCheckpoint(
                        checkpoint_id=winner_id,
                        project_id=str(winner_data["project_id"]),
                        session_id=winner_data.get("session_id"),
                        checkpoint_type=str(winner_data["checkpoint_type"]),
                        status=str(winner_data["status"]),
                        task_id=winner_data.get("task_id"),
                        payload=_json_loads(winner_data.get("payload"), {}),
                        created_at=datetime.fromisoformat(str(winner_data["created_at"])),
                        updated_at=datetime.fromisoformat(str(winner_data["updated_at"])),
                    ),
                    False,
                )

            if not create_if_missing:
                await self._db.commit()
                return None, False

            await self._db.execute(
                """INSERT INTO execution_checkpoints
                (checkpoint_id, project_id, session_id, checkpoint_type, status,
                 task_id, payload, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    checkpoint.checkpoint_id,
                    project_id,
                    session_id,
                    checkpoint_type,
                    checkpoint.status,
                    checkpoint.task_id,
                    _json_dumps(checkpoint.payload),
                    checkpoint.created_at.isoformat(),
                    checkpoint.updated_at.isoformat(),
                ),
            )
            await self._db.commit()
            return checkpoint, True
        except Exception:
            await self._db.rollback()
            raise

    async def normalize_active_execution_checkpoints(
        self,
        *,
        project_id: str,
        session_id: str,
        checkpoint_types: list[str] | tuple[str, ...] | set[str],
    ) -> ExecutionCheckpoint | None:
        """Return one active scope owner while superseding duplicate rows.

        Unlike creation, startup reconciliation must not manufacture a
        checkpoint merely because none exists.  This wrapper reuses the same
        serialized transaction and duplicate winner rule with insertion
        explicitly disabled.
        """

        clean_types = sorted(
            {
                str(item).strip()
                for item in checkpoint_types
                if str(item).strip()
            }
        )
        if not clean_types or not str(session_id or "").strip():
            return None
        candidate = ExecutionCheckpoint(
            project_id=str(project_id or "default").strip() or "default",
            session_id=str(session_id or "").strip(),
            checkpoint_type=clean_types[0],
        )
        checkpoint, _created = await self.get_or_create_active_execution_checkpoint(
            candidate,
            checkpoint_types=clean_types,
            create_if_missing=False,
        )
        return checkpoint

    async def compare_and_set_execution_checkpoint(
        self,
        checkpoint_id: str,
        *,
        expected_statuses: list[str] | tuple[str, ...] | set[str],
        status: str,
        payload: dict[str, Any],
        updated_at: datetime | None = None,
    ) -> bool:
        """Atomically transition a checkpoint only from an expected state.

        The conditional UPDATE is the cross-controller guard for checkpoint
        consumption.  In-memory scope locks serialize one Office controller;
        this CAS prevents a standalone CLI/controller from claiming the same
        pending runtime concurrently.
        """

        assert self._db
        expected = [
            str(item).strip()
            for item in expected_statuses
            if str(item).strip()
        ]
        if not checkpoint_id or not expected:
            return False
        async with self._db.execute(
            "SELECT checkpoint_type FROM execution_checkpoints WHERE checkpoint_id = ?",
            (checkpoint_id,),
        ) as type_cursor:
            type_row = await type_cursor.fetchone()
        if (
            type_row is not None
            and str(type_row[0] or "").strip()
            in OWNER_INTERACTION_CHECKPOINT_TYPES
        ):
            raise RuntimeError(
                "owner interactions require scoped decision/claim/finish CAS"
            )
        placeholders = ", ".join("?" for _ in expected)
        cursor = await self._db.execute(
            f"""UPDATE execution_checkpoints
            SET status = ?, payload = ?, updated_at = ?
            WHERE checkpoint_id = ? AND status IN ({placeholders})""",
            (
                str(status or "").strip(),
                _json_dumps(dict(payload or {})),
                (updated_at or datetime.now()).isoformat(),
                checkpoint_id,
                *expected,
            ),
        )
        await self._db.commit()
        return cursor.rowcount == 1

    async def complete_execution_checkpoint_and_reopen_ui_anchor(
        self,
        checkpoint_id: str,
        *,
        project_id: str,
        session_id: str,
        expected_status: str,
        status: str,
        payload: dict[str, Any],
        ui_anchor_task_id: str = "",
        updated_at: datetime | None = None,
    ) -> bool:
        """Atomically complete a runtime handoff and reopen its UI anchor.

        The anchor must never become chat-runnable if a concurrent Stop already
        took checkpoint ownership back.  Keeping both writes in one SQLite
        transaction makes the checkpoint CAS the gate for the UI projection.
        """

        assert self._db
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        session_id = str(session_id or "").strip()
        expected_status = str(expected_status or "").strip()
        status = str(status or "").strip()
        ui_anchor_task_id = str(ui_anchor_task_id or "").strip()
        if not checkpoint_id or not session_id or not expected_status or not status:
            return False
        now = updated_at or datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(
                """SELECT checkpoint_type FROM execution_checkpoints
                   WHERE checkpoint_id = ? AND project_id = ?""",
                (checkpoint_id, project_id),
            ) as type_cursor:
                type_row = await type_cursor.fetchone()
            if (
                type_row is not None
                and str(type_row[0] or "").strip()
                in OWNER_INTERACTION_CHECKPOINT_TYPES
            ):
                raise RuntimeError(
                    "owner interactions cannot use runtime checkpoint completion"
                )
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                SET status = ?, payload = ?, updated_at = ?
                WHERE checkpoint_id = ?
                  AND project_id = ?
                  AND session_id = ?
                  AND status = ?""",
                (
                    status,
                    _json_dumps(dict(payload or {})),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                    session_id,
                    expected_status,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return False
            if ui_anchor_task_id:
                await self._db.execute(
                    """UPDATE tasks
                    SET status = ?, execution_lock = 0, execution_locked_at = NULL
                    WHERE id = ? AND project_id = ? AND status = ?""",
                    (
                        TaskStatus.IDLE.value,
                        ui_anchor_task_id,
                        project_id,
                        TaskStatus.CANCELLED.value,
                    ),
                )
            await self._db.commit()
            return True
        except Exception:
            await self._db.rollback()
            raise

    async def get_execution_checkpoints(
        self,
        project_id: str = "default",
        session_id: str | None = None,
        checkpoint_types: list[str] | None = None,
        statuses: list[str] | None = None,
    ) -> list[ExecutionCheckpoint]:
        assert self._db
        query = "SELECT * FROM execution_checkpoints WHERE project_id = ?"
        params: list[Any] = [project_id]
        clean_statuses = [str(status).strip() for status in list(statuses or []) if str(status).strip()]
        if clean_statuses:
            placeholders = ", ".join("?" for _ in clean_statuses)
            query += f" AND status IN ({placeholders})"
            params.extend(clean_statuses)
        if session_id:
            query += " AND session_id = ?"
            params.append(session_id)
        if checkpoint_types:
            placeholders = ", ".join("?" for _ in checkpoint_types)
            query += f" AND checkpoint_type IN ({placeholders})"
            params.extend(checkpoint_types)
        query += " ORDER BY updated_at DESC"
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
            return [
                ExecutionCheckpoint(
                    checkpoint_id=data["checkpoint_id"],
                    project_id=data["project_id"],
                    session_id=data.get("session_id"),
                    checkpoint_type=data["checkpoint_type"],
                    status=data["status"],
                    task_id=data["task_id"],
                    payload=_json_loads(data["payload"], {}),
                    created_at=datetime.fromisoformat(data["created_at"]),
                    updated_at=datetime.fromisoformat(data["updated_at"]),
                )
                for data in (dict(zip(cols, row)) for row in rows)
            ]

    async def get_pending_checkpoints(
        self,
        project_id: str = "default",
        session_id: str | None = None,
        checkpoint_types: list[str] | None = None,
    ) -> list[ExecutionCheckpoint]:
        return await self.get_execution_checkpoints(
            project_id=project_id,
            session_id=session_id,
            checkpoint_types=checkpoint_types,
            statuses=["pending"],
        )

    async def get_latest_pending_checkpoint(
        self,
        project_id: str = "default",
        session_id: str | None = None,
    ) -> ExecutionCheckpoint | None:
        checkpoints = await self.get_pending_checkpoints(project_id=project_id, session_id=session_id)
        return checkpoints[0] if checkpoints else None

    async def resolve_execution_checkpoint(self, checkpoint_id: str, status: str = "resolved") -> None:
        assert self._db
        async with self._db.execute(
            "SELECT checkpoint_type FROM execution_checkpoints WHERE checkpoint_id = ?",
            (checkpoint_id,),
        ) as cursor:
            row = await cursor.fetchone()
        if row is not None and str(row[0] or "").strip() in OWNER_INTERACTION_CHECKPOINT_TYPES:
            raise RuntimeError(
                "owner interaction checkpoints require scoped decision/claim/finish CAS"
            )
        await self._db.execute(
            "UPDATE execution_checkpoints SET status = ?, updated_at = ? WHERE checkpoint_id = ?",
            (status, datetime.now().isoformat(), checkpoint_id),
        )
        await self._db.commit()

    async def supersede_pending_checkpoints(
        self,
        *,
        project_id: str = "default",
        task_id: str | None = None,
        session_id: str | None = None,
        checkpoint_types: list[str] | None = None,
        basis_hash: str | None = None,
        exclude_checkpoint_id: str | None = None,
    ) -> list[str]:
        assert self._db
        project_id = str(project_id or "default").strip() or "default"
        self._assert_project_write_scope(
            project_id,
            operation="supersede_pending_checkpoints",
            entity="execution checkpoints",
        )
        query = "SELECT * FROM execution_checkpoints WHERE project_id = ? AND status = 'pending'"
        params: list[Any] = [project_id]
        if task_id:
            query += " AND task_id = ?"
            params.append(task_id)
        if session_id:
            query += " AND session_id = ?"
            params.append(session_id)
        if checkpoint_types:
            if any(
                str(item or "").strip() in OWNER_INTERACTION_CHECKPOINT_TYPES
                for item in checkpoint_types
            ):
                raise ValueError(
                    "owner interactions use atomic owner publication supersession"
                )
            placeholders = ", ".join("?" for _ in checkpoint_types)
            query += f" AND checkpoint_type IN ({placeholders})"
            params.extend(checkpoint_types)
        else:
            owner_types = sorted(OWNER_INTERACTION_CHECKPOINT_TYPES)
            owner_placeholders = ", ".join("?" for _ in owner_types)
            query += f" AND checkpoint_type NOT IN ({owner_placeholders})"
            params.extend(owner_types)
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            async with self._db.execute(query, params) as cursor:
                rows = await cursor.fetchall()
                cols = [d[0] for d in cursor.description]

            superseded_ids: list[str] = []
            now = datetime.now().isoformat()
            for data in (dict(zip(cols, row)) for row in rows):
                checkpoint_id = str(data.get("checkpoint_id", "") or "").strip()
                if not checkpoint_id or checkpoint_id == str(exclude_checkpoint_id or "").strip():
                    continue
                payload = _json_loads(data.get("payload"), {})
                existing_basis_hash = str(payload.get("basis_hash", "") or "").strip()
                if basis_hash and existing_basis_hash and existing_basis_hash == basis_hash:
                    continue
                payload["superseded_at"] = now
                if exclude_checkpoint_id:
                    payload["superseded_by_checkpoint_id"] = str(exclude_checkpoint_id)
                cursor = await self._db.execute(
                    """UPDATE execution_checkpoints
                    SET status = 'superseded', payload = ?, updated_at = ?
                    WHERE checkpoint_id = ? AND status = 'pending'""",
                    (_json_dumps(payload), now, checkpoint_id),
                )
                if cursor.rowcount == 1:
                    superseded_ids.append(checkpoint_id)
            await self._db.commit()
            return superseded_ids
        except Exception:
            await self._db.rollback()
            raise

    # --- Runtime V2 persistence ---

    async def save_runtime_session(
        self,
        *,
        runtime_session_id: str,
        project_id: str = "default",
        session_id: str | None = None,
        task_id: str | None = None,
        status: str = "running",
        metadata: dict[str, Any] | None = None,
        controller_run_id: str = "",
        controller_owner_token: str = "",
        controller_lease_generation: int = 0,
    ) -> None:
        assert self._db
        self._assert_project_write_scope(
            project_id,
            operation="save_runtime_session",
            entity=f"runtime session {runtime_session_id!r}",
        )
        payload = dict(metadata or {})
        run_id = str(
            controller_run_id
            or payload.get("company_run_id")
            or payload.get("delegation_run_id")
            or ""
        ).strip()
        # Runtime metadata can be reloaded by any process.  Require the live
        # caller to supply its admission credential explicitly so an old
        # executor cannot adopt the takeover winner's stamped generation.
        token = str(controller_owner_token or "").strip()
        generation = int(controller_lease_generation or 0)
        if token:
            payload.update(
                {
                    "company_run_id": run_id,
                    "company_run_controller_owner_token": token,
                    "company_run_controller_lease_generation": generation,
                }
            )
        now = datetime.now()
        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            effective_run_id = run_id
            if not effective_run_id:
                async with transaction_db.execute(
                    """SELECT metadata FROM runtime_sessions
                       WHERE runtime_session_id = ?""",
                    (str(runtime_session_id or "").strip(),),
                ) as cursor:
                    existing_row = await cursor.fetchone()
                if existing_row is not None:
                    existing_metadata = _json_loads(existing_row[0], {})
                    effective_run_id = str(
                        existing_metadata.get("company_run_id")
                        or existing_metadata.get("delegation_run_id")
                        or ""
                    ).strip()
            if not effective_run_id and str(task_id or "").strip():
                async with transaction_db.execute(
                    """SELECT json_extract(metadata, '$.delegation_run_id')
                       FROM tasks WHERE id = ? AND project_id = ?""",
                    (str(task_id or "").strip(), project_id),
                ) as cursor:
                    task_scope = await cursor.fetchone()
                if task_scope is not None:
                    effective_run_id = str(task_scope[0] or "").strip()
            if effective_run_id:
                payload["company_run_id"] = effective_run_id
            await self._require_company_controller_record_write(
                transaction_db,
                run_id=effective_run_id,
                project_id=project_id,
                owner_token=token,
                generation=generation,
                checked_at=now,
                task_id=str(task_id or "").strip(),
            )
            now_iso = now.isoformat()
            await transaction_db.execute(
                """INSERT OR REPLACE INTO runtime_sessions
                (runtime_session_id, project_id, session_id, task_id, status, metadata, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, COALESCE((SELECT created_at FROM runtime_sessions WHERE runtime_session_id = ?), ?), ?)""",
                (
                    runtime_session_id,
                    project_id,
                    session_id,
                    task_id,
                    status,
                    _json_dumps(payload),
                    runtime_session_id,
                    now_iso,
                    now_iso,
                ),
            )
            await transaction_db.commit()
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

    async def get_runtime_session(self, runtime_session_id: str) -> dict[str, Any] | None:
        assert self._db
        async with self._db.execute(
            "SELECT * FROM runtime_sessions WHERE runtime_session_id = ?",
            (runtime_session_id,),
        ) as cursor:
            row = await cursor.fetchone()
            if row is None:
                return None
            cols = [d[0] for d in cursor.description]
        data = dict(zip(cols, row))
        data["metadata"] = _json_loads(data.get("metadata"), {})
        return data

    async def list_runtime_sessions(
        self,
        *,
        project_id: str | None = None,
        status: str | None = None,
        task_id: str | None = None,
        session_id: str | None = None,
        limit: int = 50,
    ) -> list[dict[str, Any]]:
        assert self._db
        query = "SELECT * FROM runtime_sessions WHERE 1=1"
        params: list[Any] = []
        if project_id:
            query += " AND project_id = ?"
            params.append(project_id)
        if status:
            query += " AND status = ?"
            params.append(status)
        if task_id:
            query += " AND task_id = ?"
            params.append(task_id)
        if session_id:
            query += " AND session_id = ?"
            params.append(session_id)
        query += " ORDER BY updated_at DESC LIMIT ?"
        params.append(max(1, int(limit or 50)))
        async with self._db.execute(query, params) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        sessions: list[dict[str, Any]] = []
        for row in rows:
            data = dict(zip(cols, row))
            data["metadata"] = _json_loads(data.get("metadata"), {})
            sessions.append(data)
        return sessions

    async def save_runtime_event(
        self,
        runtime_session_id: str,
        event_type: str,
        payload: dict[str, Any] | None = None,
    ) -> None:
        assert self._db
        await self._db.execute(
            """INSERT INTO runtime_events
            (event_id, runtime_session_id, event_type, payload, created_at)
            VALUES (?, ?, ?, ?, ?)""",
            (
                str(uuid.uuid4()),
                runtime_session_id,
                event_type,
                _json_dumps(payload or {}),
                datetime.now().isoformat(),
            ),
        )
        await self._db.commit()

    async def list_runtime_events(
        self,
        runtime_session_id: str,
        limit: int = 100,
    ) -> list[dict[str, Any]]:
        assert self._db
        async with self._db.execute(
            """
            SELECT * FROM (
                SELECT * FROM runtime_events
                WHERE runtime_session_id = ?
                ORDER BY created_at DESC
                LIMIT ?
            )
            ORDER BY created_at ASC
            """,
            (runtime_session_id, max(1, int(limit or 100))),
        ) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        results: list[dict[str, Any]] = []
        for row in rows:
            data = dict(zip(cols, row))
            data["payload"] = _json_loads(data.get("payload"), {})
            results.append(data)
        return results

    async def ensure_runtime_user_turn_seed(
        self,
        *,
        task: Task,
        runtime_session_id: str,
        seed_key: str,
        prompt_revision: str,
        content: str,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Atomically persist one idempotent user turn for a business attempt.

        A resumed Native runtime may execute several WorkItem attempts in the
        same session.  This transaction makes the attempt boundary visible to
        both the recoverable runtime transcript and the owner-facing session
        transcript without a crash gap.  Stable ids plus the seed row make a
        retry after commit a no-op; a different payload for the same seed is
        an invariant violation.

        Company-mode writers are fenced by the exact live controller and
        claimed WorkItem attempt in the same ``BEGIN IMMEDIATE`` transaction,
        so a stale generation cannot inject a correction into a successor's
        conversation.
        """

        self._require_db()
        clean_runtime_session_id = str(runtime_session_id or "").strip()
        clean_seed_key = str(seed_key or "").strip()
        clean_revision = str(prompt_revision or "").strip()
        clean_content = str(content or "").strip()
        task_id = str(getattr(task, "id", "") or "").strip()
        session_id = str(getattr(task, "session_id", "") or "").strip()
        project_id = str(getattr(task, "project_id", "") or "default").strip() or "default"
        if not all(
            (
                clean_runtime_session_id,
                clean_seed_key,
                clean_revision,
                clean_content,
                task_id,
                session_id,
            )
        ):
            raise ValueError("runtime user-turn seed requires complete identity and content")

        content_hash = hashlib.sha256(clean_content.encode("utf-8")).hexdigest()
        stable_digest = hashlib.sha256(clean_seed_key.encode("utf-8")).hexdigest()
        message_id = f"runtime-v2-user-{stable_digest}"
        part_id = f"runtime-v2-user-part-{stable_digest}"
        entry_id = f"runtime-v2-user-entry-{stable_digest}"
        ui_message_id = f"runtime-v2-attempt-user:{stable_digest}"
        message_metadata = {
            "project_id": project_id,
            "session_id": session_id,
            "task_id": task_id,
            "kind": "runtime_v2_user_turn",
            "runtime_session_id": clean_runtime_session_id,
            "runtime_user_turn_seed_key": clean_seed_key,
            "runtime_user_turn_prompt_revision": clean_revision,
            "runtime_user_turn_content_hash": content_hash,
            "ui_message_id": ui_message_id,
            **dict(metadata or {}),
        }
        # Reserved identity is authoritative even if a caller supplied stale
        # values in its descriptive metadata.
        message_metadata.update(
            {
                "project_id": project_id,
                "session_id": session_id,
                "task_id": task_id,
                "kind": "runtime_v2_user_turn",
                "runtime_session_id": clean_runtime_session_id,
                "runtime_user_turn_seed_key": clean_seed_key,
                "runtime_user_turn_prompt_revision": clean_revision,
                "runtime_user_turn_content_hash": content_hash,
                "ui_message_id": ui_message_id,
            }
        )

        transaction_db = _SQLiteConnectionAdapter(self.db_path)
        try:
            await transaction_db.execute("BEGIN IMMEDIATE")
            now = datetime.now()
            task_metadata = dict(getattr(task, "metadata", {}) or {})
            async with transaction_db.execute(
                """SELECT 1
                     FROM work_item_runtime_links AS link
                     JOIN delegation_work_items AS work_item
                       ON work_item.work_item_id = link.work_item_id
                     JOIN delegation_runs AS run
                       ON run.run_id = work_item.run_id
                     WHERE link.runtime_task_id = ?
                     LIMIT 1""",
                (task_id,),
            ) as cursor:
                durable_company_link = await cursor.fetchone() is not None
            company_scoped = durable_company_link or bool(
                str(task_metadata.get("delegation_run_id", "") or "").strip()
                or str(task_metadata.get("execution_mode", "") or "").strip()
                == "company_mode"
                or str(task_metadata.get("runtime_model", "") or "").strip()
                == "multi_team_org"
            )
            if company_scoped and not await self._company_controller_active_effect_attempt_matches(
                transaction_db,
                task,
                checked_at=now,
            ):
                raise CompanyRunControllerLeaseLost(
                    "stale company controller cannot seed a runtime user turn"
                )

            async with transaction_db.execute(
                """SELECT project_id, session_id, task_id
                     FROM runtime_sessions WHERE runtime_session_id = ?""",
                (clean_runtime_session_id,),
            ) as cursor:
                runtime_row = await cursor.fetchone()
            if runtime_row is None:
                runtime_metadata = {
                    "runtime_user_turn_seed_bootstrapped": True,
                }
                if company_scoped:
                    run_id, owner_token, generation, _attempt_seq = (
                        self._company_controller_task_fence(task)
                    )
                    runtime_metadata.update(
                        {
                            "company_run_id": run_id,
                            "company_run_controller_owner_token": owner_token,
                            "company_run_controller_lease_generation": generation,
                        }
                    )
                await transaction_db.execute(
                    """INSERT INTO runtime_sessions
                       (runtime_session_id, project_id, session_id, task_id,
                        status, metadata, created_at, updated_at)
                       VALUES (?, ?, ?, ?, 'running', ?, ?, ?)""",
                    (
                        clean_runtime_session_id,
                        project_id,
                        session_id,
                        task_id,
                        _json_dumps(runtime_metadata),
                        now.isoformat(),
                        now.isoformat(),
                    ),
                )
                runtime_row = (project_id, session_id, task_id)
            if tuple(runtime_row) != (project_id, session_id, task_id):
                raise RuntimeError(
                    "runtime user-turn seed requires its existing exact runtime session"
                )

            async with transaction_db.execute(
                """SELECT runtime_session_id, task_id, session_id, project_id,
                          prompt_revision, content_hash, message_id
                     FROM runtime_user_turn_seeds WHERE seed_key = ?""",
                (clean_seed_key,),
            ) as cursor:
                existing = await cursor.fetchone()
            if existing is not None:
                expected_identity = (
                    clean_runtime_session_id,
                    task_id,
                    session_id,
                    project_id,
                    message_id,
                )
                existing_identity = (
                    existing[0],
                    existing[1],
                    existing[2],
                    existing[3],
                    existing[6],
                )
                if tuple(existing_identity) != expected_identity:
                    raise RuntimeError(
                        "runtime user-turn seed identity invariant violated"
                    )
                existing_revision = str(existing[4] or "").strip()
                existing_content_hash = str(existing[5] or "").strip()
                async with transaction_db.execute(
                    """SELECT session_id, task_id, role, metadata
                         FROM session_messages WHERE message_id = ?""",
                    (message_id,),
                ) as cursor:
                    message_row = await cursor.fetchone()
                async with transaction_db.execute(
                    """SELECT message_id, session_id, part_type, payload
                         FROM session_parts WHERE part_id = ?""",
                    (part_id,),
                ) as cursor:
                    part_row = await cursor.fetchone()
                async with transaction_db.execute(
                    """SELECT runtime_session_id, task_id, session_id,
                              message_id, role, entry_type, content, metadata
                         FROM runtime_transcript_entries WHERE entry_id = ?""",
                    (entry_id,),
                ) as cursor:
                    transcript_row = await cursor.fetchone()
                if message_row is None or part_row is None or transcript_row is None:
                    raise RuntimeError(
                        "runtime user-turn seed has an incomplete atomic record"
                    )
                canonical_content = str(transcript_row[6] or "")
                part_payload = _json_loads(part_row[3], {})
                stored_message_metadata = _json_loads(message_row[3], {})
                stored_transcript_metadata = _json_loads(transcript_row[7], {})
                graph_matches = (
                    tuple(message_row[:3]) == (session_id, task_id, "user")
                    and tuple(part_row[:3]) == (message_id, session_id, "text")
                    and tuple(transcript_row[:6])
                    == (
                        clean_runtime_session_id,
                        task_id,
                        session_id,
                        message_id,
                        "user",
                        "message",
                    )
                    and str(part_payload.get("text", "") or "")
                    == canonical_content
                    and hashlib.sha256(canonical_content.encode("utf-8")).hexdigest()
                    == existing_content_hash
                    and str(
                        stored_message_metadata.get(
                            "runtime_user_turn_seed_key", ""
                        )
                        or ""
                    ).strip()
                    == clean_seed_key
                    and str(
                        stored_message_metadata.get(
                            "runtime_user_turn_prompt_revision", ""
                        )
                        or ""
                    ).strip()
                    == existing_revision
                    and str(
                        stored_message_metadata.get(
                            "runtime_user_turn_content_hash", ""
                        )
                        or ""
                    ).strip()
                    == existing_content_hash
                    and str(
                        stored_transcript_metadata.get(
                            "runtime_user_turn_seed_key", ""
                        )
                        or ""
                    ).strip()
                    == clean_seed_key
                )
                if not graph_matches:
                    raise RuntimeError(
                        "runtime user-turn seed atomic graph invariant violated"
                    )
                if (
                    existing_revision != clean_revision
                    or existing_content_hash != content_hash
                ):
                    raise RuntimeError(
                        "runtime user-turn seed identity/content invariant violated"
                    )
                await transaction_db.commit()
                return {
                    "created": False,
                    "seed_key": clean_seed_key,
                    "message_id": message_id,
                    "ui_message_id": ui_message_id,
                    "prompt_revision": existing_revision,
                    "content": canonical_content,
                    "canonical_reused": False,
                }

            async with transaction_db.execute(
                "SELECT project_id FROM sessions WHERE session_id = ?",
                (session_id,),
            ) as cursor:
                session_row = await cursor.fetchone()
            if session_row is None or (
                str(session_row[0] or "default").strip() or "default"
            ) != project_id:
                raise RuntimeError(
                    "runtime user-turn seed requires its existing exact session"
                )

            await transaction_db.execute(
                """INSERT INTO runtime_user_turn_seeds
                   (seed_key, runtime_session_id, task_id, session_id,
                    project_id, prompt_revision, content_hash, message_id,
                    created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    clean_seed_key,
                    clean_runtime_session_id,
                    task_id,
                    session_id,
                    project_id,
                    clean_revision,
                    content_hash,
                    message_id,
                    now.isoformat(),
                ),
            )
            await transaction_db.execute(
                """INSERT INTO session_messages
                   (message_id, session_id, role, task_id, agent_id,
                    parent_message_id, summary_flag, metadata, created_at)
                   VALUES (?, ?, 'user', ?, NULL, NULL, 0, ?, ?)""",
                (
                    message_id,
                    session_id,
                    task_id,
                    _json_dumps(message_metadata),
                    now.isoformat(),
                ),
            )
            await transaction_db.execute(
                """INSERT INTO session_parts
                   (part_id, message_id, session_id, part_type, payload, created_at)
                   VALUES (?, ?, ?, 'text', ?, ?)""",
                (
                    part_id,
                    message_id,
                    session_id,
                    _json_dumps({"text": clean_content}),
                    now.isoformat(),
                ),
            )
            await transaction_db.execute(
                """INSERT INTO runtime_transcript_entries
                   (entry_id, runtime_session_id, task_id, session_id,
                    message_id, role, entry_type, content, metadata, created_at)
                   VALUES (?, ?, ?, ?, ?, 'user', 'message', ?, ?, ?)""",
                (
                    entry_id,
                    clean_runtime_session_id,
                    task_id,
                    session_id,
                    message_id,
                    clean_content,
                    _json_dumps(message_metadata),
                    now.isoformat(),
                ),
            )
            await transaction_db.execute(
                "UPDATE sessions SET updated_at = ? WHERE session_id = ?",
                (now.isoformat(), session_id),
            )
            await transaction_db.commit()
            return {
                "created": True,
                "seed_key": clean_seed_key,
                "message_id": message_id,
                "ui_message_id": ui_message_id,
                "prompt_revision": clean_revision,
                "content": clean_content,
                "canonical_reused": False,
            }
        except BaseException:
            await transaction_db.rollback()
            raise
        finally:
            await transaction_db.close()

