    async def persist_runtime_tool_result_and_finish_permission(
        self,
        *,
        runtime_session_id: str,
        tool_name: str,
        payload: dict[str, Any],
        tool_call_id: str,
        task_id: str,
        session_id: str | None,
        message_id: str,
        metadata: dict[str, Any] | None,
        fingerprint: str,
        checkpoint_id: str,
        project_id: str,
        checkpoint_type: str,
        claim_id: str,
        consumer_id: str,
        checkpoint_payload_patch: dict[str, Any] | None = None,
    ) -> ExecutionCheckpointConsumptionReceipt:
        """Commit an exact ToolResult and its one-shot permit atomically.

        The ToolResult ledger is the durable fact that the external call
        completed.  Storing it in the same transaction that removes the Task
        permit and finishes the interaction eliminates the crash window where
        recovery could misclassify a committed result as ``outcome_unknown``.
        """

        assert self._db
        runtime_session_id = str(runtime_session_id or "").strip()
        tool_call_id = str(tool_call_id or "").strip()
        task_id = str(task_id or "").strip()
        fingerprint = str(fingerprint or "").strip()
        checkpoint_id = str(checkpoint_id or "").strip()
        project_id = str(project_id or "default").strip() or "default"
        checkpoint_type = str(checkpoint_type or "").strip()
        claim_id = str(claim_id or "").strip()
        consumer_id = str(consumer_id or "").strip()
        if not all(
            (
                runtime_session_id,
                tool_call_id,
                task_id,
                fingerprint,
                checkpoint_id,
                checkpoint_type,
                claim_id,
                consumer_id,
            )
        ):
            raise ValueError("durable ToolResult completion identity is incomplete")
        if checkpoint_type != "tool_permission":
            raise ValueError("atomic ToolResult completion requires tool_permission")
        self._assert_project_write_scope(
            project_id,
            operation="persist_runtime_tool_result_and_finish_permission",
            entity=f"execution checkpoint {checkpoint_id!r}",
        )
        now = datetime.now()
        try:
            await self._db.execute("BEGIN IMMEDIATE")
            checkpoint = await self._select_execution_checkpoint(
                checkpoint_id,
                project_id=project_id,
                checkpoint_type=checkpoint_type,
            )
            if checkpoint is None:
                await self._db.commit()
                return ExecutionCheckpointConsumptionReceipt(outcome="not_found")
            checkpoint_payload = dict(checkpoint.payload or {})
            interaction = self._execution_checkpoint_interaction(checkpoint_payload)
            async with self._db.execute(
                "SELECT context_snapshot, metadata FROM tasks WHERE id = ? AND project_id = ?",
                (task_id, project_id),
            ) as cursor:
                task_row = await cursor.fetchone()
            if task_row is None:
                await self._db.rollback()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict", checkpoint=checkpoint
                )
            context_snapshot = _json_loads(task_row[0], {})
            task_metadata = _json_loads(task_row[1], {})
            (
                runtime_resume,
                runtime_metadata,
                permits,
                continuation,
                _recorded_runtime_id,
            ) = self._canonicalize_task_runtime_tool_ledger(
                context_snapshot,
                task_metadata,
            )
            permit = dict(permits.get(fingerprint, {}) or {})
            permit_matches = bool(permit) and self._exact_tool_permit_matches_checkpoint(
                permit,
                checkpoint,
                task_id=task_id,
                project_id=project_id,
                runtime_session_id=runtime_session_id,
                fingerprint=fingerprint,
                tool_call_id=tool_call_id,
                tool_name=str(tool_name or "").strip(),
                arguments=dict(permit.get("arguments", {}) or {}),
                execution_envelope=dict(
                    permit.get("execution_envelope", {}) or {}
                ),
                execution_identity=dict(
                    permit.get("execution_identity", {}) or {}
                ),
                claim_id=claim_id,
                consumer_id=consumer_id,
            )
            execution = dict(interaction.get("execution", {}) or {})
            execution_state = str(execution.get("state", "") or "").strip()
            execution_claim_matches = (
                str(execution.get("claim_id", "") or "").strip() == claim_id
                and str(execution.get("consumer_id", "") or "").strip()
                == consumer_id
            )
            permit_state = str(permit.get("state", "") or "").strip()
            approved_permit = permit.get("approved") is True
            effect_state_matches = (
                permit_state == "executing"
                and execution_state == "executing"
                and execution_claim_matches
                if approved_permit
                else permit_state in {"ready", "denied"}
                and execution_state == "ready"
                and execution_claim_matches
            )
            result_exists = False
            async with self._db.execute(
                """SELECT 1 FROM runtime_tool_results
                   WHERE runtime_session_id = ? AND tool_call_id = ? LIMIT 1""",
                (runtime_session_id, tool_call_id),
            ) as cursor:
                result_exists = await cursor.fetchone() is not None
            if (
                checkpoint.status != "consuming"
                or not permit_matches
                or not effect_state_matches
            ):
                if (
                    checkpoint.status == "resolved"
                    and result_exists
                    and (not permit or permit_matches)
                ):
                    if not permit and not permits and not continuation:
                        # The result and permission were already committed.
                        # Do not rewrite an inactive Task with this stale
                        # completion caller's runtime_session_id.
                        await self._db.commit()
                        return ExecutionCheckpointConsumptionReceipt(
                            outcome="duplicate", checkpoint=checkpoint
                        )
                    if (permits or continuation) and (
                        _recorded_runtime_id != runtime_session_id
                    ):
                        await self._db.rollback()
                        return ExecutionCheckpointConsumptionReceipt(
                            outcome="conflict", checkpoint=checkpoint
                        )
                    permits.pop(fingerprint, None)
                    self._write_canonical_task_runtime_tool_ledger(
                        context_snapshot,
                        task_metadata,
                        runtime_resume=runtime_resume,
                        runtime_metadata=runtime_metadata,
                        permits=permits,
                        continuation=continuation,
                        runtime_session_id=runtime_session_id,
                    )
                    await self._db.execute(
                        "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                        (
                            _json_dumps(context_snapshot),
                            _json_dumps(task_metadata),
                            task_id,
                        ),
                    )
                    await self._db.commit()
                    return ExecutionCheckpointConsumptionReceipt(
                        outcome="duplicate", checkpoint=checkpoint
                    )
                await self._db.rollback()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict", checkpoint=checkpoint
                )

            await self._db.execute(
                """INSERT OR REPLACE INTO runtime_tool_results
                   (result_record_id, runtime_session_id, task_id, session_id,
                    message_id, tool_call_id, tool_name, payload, metadata, created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    f"{runtime_session_id}|{tool_call_id}|durable",
                    runtime_session_id,
                    task_id,
                    session_id,
                    message_id,
                    tool_call_id,
                    tool_name,
                    _json_dumps(payload or {}),
                    _json_dumps(metadata or {}),
                    now.isoformat(),
                ),
            )
            permits.pop(fingerprint, None)
            self._write_canonical_task_runtime_tool_ledger(
                context_snapshot,
                task_metadata,
                runtime_resume=runtime_resume,
                runtime_metadata=runtime_metadata,
                permits=permits,
                continuation=continuation,
                runtime_session_id=runtime_session_id,
            )
            await self._db.execute(
                "UPDATE tasks SET context_snapshot = ?, metadata = ? WHERE id = ?",
                (
                    _json_dumps(context_snapshot),
                    _json_dumps(task_metadata),
                    task_id,
                ),
            )
            for key, value in dict(checkpoint_payload_patch or {}).items():
                if key != "interaction":
                    checkpoint_payload[key] = json.loads(_json_dumps(value))
            interaction["execution"] = {
                **dict(interaction.get("execution", {}) or {}),
                "state": "result_persisted",
                "claim_id": claim_id,
                "consumer_id": consumer_id,
                "finished_at": now.isoformat(),
            }
            interaction["completion"] = {
                "claim_id": claim_id,
                "consumer_id": consumer_id,
                "finished_at": now.isoformat(),
                "final_status": "resolved",
            }
            checkpoint_payload["interaction"] = interaction
            cursor = await self._db.execute(
                """UPDATE execution_checkpoints
                   SET status = 'resolved', payload = ?, updated_at = ?
                   WHERE checkpoint_id = ? AND project_id = ?
                     AND checkpoint_type = 'tool_permission' AND status = 'consuming'""",
                (
                    _json_dumps(checkpoint_payload),
                    now.isoformat(),
                    checkpoint_id,
                    project_id,
                ),
            )
            if cursor.rowcount != 1:
                await self._db.rollback()
                return ExecutionCheckpointConsumptionReceipt(
                    outcome="conflict", checkpoint=checkpoint
                )
            await self._db.commit()
            return ExecutionCheckpointConsumptionReceipt(
                outcome="finished",
                checkpoint=self._checkpoint_with(
                    checkpoint,
                    status="resolved",
                    payload=checkpoint_payload,
                    updated_at=now,
                ),
            )
        except Exception:
            await self._db.rollback()
            raise

    async def list_runtime_transcript_entries(
        self,
        runtime_session_id: str,
    ) -> list[dict[str, Any]]:
        assert self._db
        async with self._db.execute(
            "SELECT * FROM runtime_transcript_entries WHERE runtime_session_id = ? ORDER BY created_at ASC",
            (runtime_session_id,),
        ) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        return [
            {**dict(zip(cols, row)), "metadata": _json_loads(dict(zip(cols, row)).get("metadata"), {})}
            for row in rows
        ]

    async def list_runtime_tool_calls(
        self,
        runtime_session_id: str,
    ) -> list[dict[str, Any]]:
        assert self._db
        async with self._db.execute(
            "SELECT * FROM runtime_tool_calls WHERE runtime_session_id = ? ORDER BY created_at ASC",
            (runtime_session_id,),
        ) as cursor:
            rows = await cursor.fetchall()
            cols = [d[0] for d in cursor.description]
        results: list[dict[str, Any]] = []
        for row in rows:
            data = dict(zip(cols, row))
            data["arguments"] = _json_loads(data.get("arguments"), {})
            data["metadata"] = _json_loads(data.get("metadata"), {})
            results.append(data)
        return results

